-- [MTL Install] generated by tools/make_installer.py. Do not edit by hand.
local function svc(path)
 local cur = game
 for name in string.gmatch(path, "[^/]+") do
  local nxt = cur:FindFirstChild(name)
  if not nxt then
   if cur == game then nxt = game:GetService(name) else nxt = Instance.new("Folder"); nxt.Name = name; nxt.Parent = cur end
  end
  cur = nxt
 end
 return cur
end
local function put(dir, name, class, src)
 local parent = svc(dir)
 local old = parent:FindFirstChild(name)
 if old and old.ClassName ~= class then old:Destroy(); old = nil end
 local s = old or Instance.new(class)
 s.Name = name
 s.Source = src
 s.Parent = parent
end
put("ReplicatedStorage/MTL", "Format", "ModuleScript", [======[--!strict
local Format = {}

-- 1234567 -> "$1,234,567"
function Format.cash(n: number): string
	n = math.floor(n + 0.5)
	local s = tostring(math.abs(n))
	local out = s:reverse():gsub("(%d%d%d)", "%1,"):reverse()
	if out:sub(1, 1) == "," then
		out = out:sub(2)
	end
	return (if n < 0 then "-$" else "$") .. out
end

-- 1500 -> "1.5K", 2300000 -> "2.3M"
function Format.short(n: number): string
	local a = math.abs(n)
	local s
	if a >= 1e9 then
		s = string.format("%.1fB", n / 1e9)
	elseif a >= 1e6 then
		s = string.format("%.1fM", n / 1e6)
	elseif a >= 1e4 then
		s = string.format("%.1fK", n / 1e3)
	else
		return tostring(math.floor(n + 0.5))
	end
	return (s:gsub("%.0([BMK])$", "%1"))
end

-- studs -> "120 m", rounded to 5 (shown 1 stud = 1 m, like most RP games; real scale reads too small)
function Format.distance(studs: number): string
	if studs >= 1000 then
		return string.format("%.1f km", studs / 1000)
	end
	return string.format("%d m", math.floor(studs / 5 + 0.5) * 5)
end

return Format
]======])
put("ReplicatedStorage/MTL", "Net", "ModuleScript", [======[--!strict
-- Every remote in the game. The server creates them once (Net.init); both sides get them by name (Net.get).
-- To add a remote: add it here AND to the table in "00 Master Plan" §3.3.
local RunService = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local FOLDER = "MTL_Net"

local Net = {}

Net.Definitions = {
	-- S -> C
	ProfileUpdated = "RemoteEvent", -- public snapshot of the save
	Notify = "RemoteEvent", -- {kind="toast"|"line"|"banner", text, color?}
	PhoneEvent = "RemoteEvent", -- {type="text"|"call"|"unlockApp"|"open", ...}
	Waypoint = "RemoteEvent", -- {id, position, label, radius} | {id, clear=true}
	PlayCutscene = "RemoteEvent", -- {id, token, anchor = CFrame?}
	JobState = "RemoteEvent",
	MissionState = "RemoteEvent", -- {type="state"|"clear"|"bark"|"progress"|"meet"|"meetClear"|"payout", ...} (MissionService)
	GunFx = "RemoteEvent", -- {type="shot", shooter, gun, origin, ends} | {type="hit", pos, head, kill, damage} | {type="hurt", from, damage}
	GunState = "RemoteEvent", -- {equipped?, mode?, guns={{id, mode, temp, mag, reserve}}, reloading?} (owner only)
	LevelUp = "RemoteEvent", -- {level, unlocks = {string}}
	Reward = "RemoteEvent", -- {cash, xp, at = Vector3?} (for "+$8 +20 XP" pops)
	PropertyState = "RemoteEvent", -- Piece 4: {type="home"|"listing"|"fade"|"arrived"|"phone"|"bed"|"exit"|"power", ...} (PropertyService)
	-- C -> S
	ClientReady = "RemoteEvent", -- client controllers are listening (server re-sends waypoints etc.)
	PhoneAction = "RemoteEvent",
	CutsceneDone = "RemoteEvent", -- {id, token, skipped}
	JobAction = "RemoteEvent",
	MissionAction = "RemoteEvent", -- {type="begin"|"step", step} | {type="closeOffer"} | {type="buy", item}
	GunFire = "RemoteEvent", -- {gun, origin, dir, t, rays={{pos, part?}}} (one ray per pellet)
	GunReload = "RemoteEvent", -- {gun}
	GunAction = "RemoteEvent", -- {type="equip", gun} | {type="holster", reason?} | {type="sync"}
	GunAim = "UnreliableRemoteEvent", -- {aiming, raised, pitch, target?} at Guns.Tuning.AimSendHz while a gun is out
	PropertyAction = "RemoteEvent", -- Piece 4: {type="buy", home} | {type="closeListing"}
	WaypointArrived = "RemoteEvent", -- {id} (hint only; the server checks the distance itself)
	RequestSnapshot = "RemoteFunction",
}

function Net.init(): Folder
	assert(RunService:IsServer(), "[MTL Net] only the server creates remotes")
	local folder = ReplicatedStorage:FindFirstChild(FOLDER) :: Folder?
	if not folder then
		local f = Instance.new("Folder")
		f.Name = FOLDER
		f.Parent = ReplicatedStorage
		folder = f
	end
	assert(folder)
	for name, className in Net.Definitions do
		local existing = folder:FindFirstChild(name)
		if existing then
			assert(existing.ClassName == className, "[MTL Net] wrong class for remote " .. name)
		else
			local remote = Instance.new(className)
			remote.Name = name
			remote.Parent = folder
		end
	end
	return folder
end

function Net.get(name: string): any
	assert(Net.Definitions[name], "[MTL Net] unknown remote: " .. tostring(name))
	local folder = ReplicatedStorage:WaitForChild(FOLDER, 30)
	assert(folder, "[MTL Net] remotes folder never appeared")
	return folder:WaitForChild(name, 30)
end

return Net
]======])
put("ReplicatedStorage/MTL", "Rig", "ModuleScript", [======[--!strict
-- Procedural poses for humanoid rigs (R15 and R6), shared by client cutscene actors and server NPCs (the clerk).
-- Placeholder for real animations: Config/Missions.Animations[gesture] ~= 0 makes actors play that animation instead.
--
-- Poses are rotations in the PARENT part's space (X right, Y up, -Z forward), as Euler degrees {x, y, z}
-- applied z first, then x, then y (CFrame.fromEulerAnglesYXZ):
--   z = raise sideways (right arm out = +z, left arm out = -z), x = swing forward (arm/leg forward = +x),
--   y = twist around the vertical. Neck x < 0 looks down; Waist x < 0 leans forward.
-- Converting to a joint: Transform = C0rot^-1 * R * C0rot, so the same numbers work on any rig's joint frames.
--   local joints = Rig.joints(model)
--   Rig.apply(joints, Rig.compose(state, now), "Transform")   -- client, every frame (Transform isn't replicated)
--   Rig.apply(joints, Rig.compose(state, now), "C0")          -- server (C0 replicates), e.g. the clerk's hands up
local Rig = {}

export type Joint = { motor: Motor6D, rot0: CFrame, c0: CFrame }
export type Joints = { [string]: Joint }

local NAMES: { [string]: string } = {
	Neck = "Neck",
	Waist = "Waist",
	RightShoulder = "RShoulder",
	["Right Shoulder"] = "RShoulder",
	LeftShoulder = "LShoulder",
	["Left Shoulder"] = "LShoulder",
	RightElbow = "RElbow",
	LeftElbow = "LElbow",
	RightHip = "RHip",
	["Right Hip"] = "RHip",
	LeftHip = "LHip",
	["Left Hip"] = "LHip",
	RightKnee = "RKnee",
	LeftKnee = "LKnee",
}

type Pose = { [string]: { number } }

-- Held poses (base layer). `_drop` = studs the root sits lower (sitting).
Rig.Poses = {
	None = {},
	Cross = { RShoulder = { 25, 0, -10 }, RElbow = { 100, 55, 0 }, LShoulder = { 25, 0, 10 }, LElbow = { 100, -55, 0 } },
	Lean = {
		RShoulder = { 25, 0, -10 },
		RElbow = { 100, 55, 0 },
		LShoulder = { 25, 0, 10 },
		LElbow = { 100, -55, 0 },
		Waist = { 7, 0, -3 },
		LHip = { 10, 0, -8 },
		Neck = { -4, 10, 0 },
	},
	Phone = { RShoulder = { 40, 0, -8 }, RElbow = { 85, 20, 0 }, LShoulder = { 30, 0, 8 }, LElbow = { 70, -30, 0 }, Neck = { -22, 0, 0 } },
	HandsUp = { RShoulder = { 0, 0, 85 }, RElbow = { 0, 0, 90 }, LShoulder = { 0, 0, -85 }, LElbow = { 0, 0, -90 }, Neck = { 8, 0, 0 }, Waist = { 4, 0, 0 } },
	Sit = { RHip = { 90, 0, 0 }, LHip = { 90, 0, 0 }, RKnee = { -90, 0, 0 }, LKnee = { -90, 0, 0 }, _drop = { 1.7 } },
	Point = { RShoulder = { 85, 0, -5 }, RElbow = { 5, 0, 0 } },
	Aim = { RShoulder = { 88, 0, -4 }, RElbow = { 4, 0, 0 }, LShoulder = { 80, 30, 0 }, LElbow = { 20, 0, 0 } },
	-- Piece 4 (the flat): seated variants. Same legs and drop as Sit.
	SitType = { RHip = { 90, 0, 0 }, LHip = { 90, 0, 0 }, RKnee = { -90, 0, 0 }, LKnee = { -90, 0, 0 }, RShoulder = { 62, 0, -4 }, RElbow = { 38, 0, 0 }, LShoulder = { 62, 0, 4 }, LElbow = { 38, 0, 0 }, Waist = { -6, 0, 0 }, Neck = { -8, 0, 0 }, _drop = { 1.7 } },
	SitSlump = { RHip = { 84, 0, 0 }, LHip = { 84, 0, 0 }, RKnee = { -80, 0, 0 }, LKnee = { -80, 0, 0 }, RShoulder = { 8, 0, -14 }, LShoulder = { 8, 0, 14 }, Waist = { 9, 0, 0 }, Neck = { -10, 0, 0 }, _drop = { 1.7 } },
	SitPhone = { RHip = { 90, 0, 0 }, LHip = { 90, 0, 0 }, RKnee = { -90, 0, 0 }, LKnee = { -90, 0, 0 }, RShoulder = { 40, 0, -8 }, RElbow = { 85, 20, 0 }, LShoulder = { 30, 0, 8 }, LElbow = { 70, -30, 0 }, Waist = { -4, 0, 0 }, Neck = { -24, 0, 0 }, _drop = { 1.7 } },
}

local S = math.sin

-- Gestures (top layer, play once). fn(localTime, duration) -> pose. Envelope in/out is added by compose().
Rig.Gestures = {
	Wave = function(lt: number): Pose
		return { RShoulder = { 0, 0, 145 }, RElbow = { 0, 0, 25 + 25 * S(lt * 9) } }
	end,
	Point = function(): Pose
		return Rig.Poses.Point
	end,
	Shrug = function(): Pose
		return { RShoulder = { 10, 0, 25 }, LShoulder = { 10, 0, -25 }, RElbow = { 80, -35, 0 }, LElbow = { 80, 35, 0 }, Neck = { 0, 0, 12 } }
	end,
	Nod = function(lt: number): Pose
		return { Neck = { -16 * math.abs(S(lt * 7)), 0, 0 } }
	end,
	Open = function(lt: number): Pose
		local w = 6 * S(lt * 5)
		return { RShoulder = { 35 + w, 0, 20 }, RElbow = { 60, -30, 0 }, LShoulder = { 35 - w, 0, -20 }, LElbow = { 60, 30, 0 } }
	end,
	Laugh = function(lt: number): Pose
		return { Waist = { -10 + 4 * S(lt * 14), 0, 0 }, Neck = { 12, 0, 0 }, RShoulder = { 15, 0, -6 }, LShoulder = { 15, 0, 6 } }
	end,
	Smash = function(lt: number): Pose
		local a = 30 * S(lt * 16)
		return { RShoulder = { 60 + a, 0, -6 }, LShoulder = { 60 - a, 0, 6 }, RElbow = { 40, 0, 0 }, LElbow = { 40, 0, 0 }, Neck = { -15, 0, 0 } }
	end,
	Flop = function(): Pose
		return { Waist = { 22, 0, 0 }, RShoulder = { -10, 0, 30 }, LShoulder = { -10, 0, -30 } }
	end,
	-- Piece 4: poke the PC's power button; stretch after waking up
	Press = function(lt: number): Pose
		local jab = 10 * math.max(0, S(lt * 9))
		return { RShoulder = { 70 + jab, 0, -4 }, RElbow = { 18 - jab, 0, 0 }, Neck = { -6, 0, 0 } }
	end,
	Stretch = function(lt: number): Pose
		local w = 8 * S(lt * 3)
		return { RShoulder = { 0, 0, 155 + w }, LShoulder = { 0, 0, -155 - w }, RElbow = { 0, 0, 10 }, LElbow = { 0, 0, -10 }, Waist = { 8, 0, 0 }, Neck = { 14, 0, 0 } }
	end,
	HandsUp = function(lt: number): Pose
		local p = table.clone(Rig.Poses.HandsUp) :: any
		p.Neck = { 8 + 3 * S(lt * 20), 0, 0 } -- shaking
		return p
	end,
}

local function rad(v: { number }?): CFrame
	if not v then
		return CFrame.identity
	end
	return CFrame.fromEulerAnglesYXZ(math.rad(v[1] or 0), math.rad(v[2] or 0), math.rad(v[3] or 0))
end

local KEYS = { "Neck", "Waist", "RShoulder", "LShoulder", "RElbow", "LElbow", "RHip", "LHip", "RKnee", "LKnee" }

function Rig.joints(model: Instance): Joints
	local out: Joints = {}
	for _, d in model:GetDescendants() do
		if d:IsA("Motor6D") then
			local key = NAMES[d.Name]
			if key and not out[key] then
				local c0 = d.C0
				out[key] = { motor = d, rot0 = c0.Rotation, c0 = c0 }
			end
		end
	end
	return out
end

function Rig.isR6(model: Instance): boolean
	local h = model:FindFirstChildOfClass("Humanoid")
	return h ~= nil and h.RigType == Enum.HumanoidRigType.R6
end

-- Height of the root part's centre above the ground (feet on the floor).
function Rig.rootHeight(model: Model): number
	local h = model:FindFirstChildOfClass("Humanoid")
	local root = model:FindFirstChild("HumanoidRootPart") :: BasePart?
	if not h or not root then
		return 3
	end
	if h.RigType == Enum.HumanoidRigType.R6 then
		return 3 * (root.Size.Y / 2)
	end
	return h.HipHeight + root.Size.Y / 2
end

local function blend(a: CFrame, b: CFrame, w: number): CFrame
	if w <= 0 then
		return a
	elseif w >= 1 then
		return b
	end
	return a:Lerp(b, w)
end

local function smooth(x: number): number
	x = math.clamp(x, 0, 1)
	return x * x * (3 - 2 * x)
end

export type State = {
	pose: string?, -- held pose name (Rig.Poses)
	prevPose: string?,
	poseT0: number?, -- when `pose` started (blends in over 0.35 s)
	gesture: string?, -- Rig.Gestures name
	gestureT0: number?,
	gestureDur: number?,
	walk: number?, -- 0..1 how much the walk cycle shows
	walkPhase: number?, -- radians, advanced by distance walked
	lookYaw: number?, -- head turn in radians (+ = left), clamped by compose
	breath: boolean?, -- idle breathing (default on)
}

-- Rotations for every joint at time `now` (parent space). Missing joints are simply not driven.
function Rig.compose(s: State, now: number): { [string]: CFrame }
	local base: Pose = Rig.Poses[s.pose or "None"] or {}
	local prev: Pose = Rig.Poses[s.prevPose or "None"] or {}
	local wPose = smooth((now - (s.poseT0 or -10)) / 0.35)
	local g: Pose? = nil
	local wG = 0
	if s.gesture and Rig.Gestures[s.gesture] and s.gestureT0 then
		local lt = now - s.gestureT0
		local dur = s.gestureDur or 1.2
		if lt >= 0 and lt <= dur then
			g = Rig.Gestures[s.gesture](lt, dur)
			wG = math.min(smooth(lt / 0.25), smooth((dur - lt) / 0.3))
		end
	end
	local walk = s.walk or 0
	local ph = s.walkPhase or 0
	local out: { [string]: CFrame } = {}
	for _, k in KEYS do
		local cf = blend(rad(prev[k]), rad(base[k]), wPose)
		if g and g[k] then
			cf = blend(cf, rad(g[k]), wG)
		end
		if walk > 0 then
			local swing = math.sin(ph)
			local add: { number }? = nil
			if k == "RHip" then
				add = { 28 * swing, 0, 0 }
			elseif k == "LHip" then
				add = { -28 * swing, 0, 0 }
			elseif k == "RKnee" then
				add = { -25 * math.max(0, -swing), 0, 0 }
			elseif k == "LKnee" then
				add = { -25 * math.max(0, swing), 0, 0 }
			elseif k == "RShoulder" and not (g and g.RShoulder) and not base.RShoulder then
				add = { -18 * swing, 0, 0 }
			elseif k == "LShoulder" and not (g and g.LShoulder) and not base.LShoulder then
				add = { 18 * swing, 0, 0 }
			end
			if add then
				cf = rad({ add[1] * walk, 0, 0 }) * cf
			end
		end
		if k == "Waist" and s.breath ~= false then
			cf = cf * CFrame.fromEulerAnglesYXZ(math.rad(1.2 * math.sin(now * 1.7)), 0, 0)
		end
		if k == "Neck" and s.lookYaw then
			cf = CFrame.fromEulerAnglesYXZ(0, math.clamp(s.lookYaw, -0.8, 0.8), 0) * cf
		end
		out[k] = cf
	end
	return out
end

-- How far the root drops for the current held pose (sitting).
function Rig.drop(s: State): number
	local p = Rig.Poses[s.pose or "None"] :: any
	return if p and p._drop then p._drop[1] else 0
end

-- Writes rotations into the joints. mode "Transform" (client, per frame) or "C0" (server, replicates).
function Rig.apply(joints: Joints, rots: { [string]: CFrame }, mode: string?)
	for k, j in joints do
		local r = rots[k]
		if r then
			local t = j.rot0:Inverse() * r * j.rot0
			if mode == "C0" then
				j.motor.C0 = j.c0 * t
			else
				j.motor.Transform = t
			end
		end
	end
end

-- Back to the rest pose.
function Rig.reset(joints: Joints, mode: string?)
	for _, j in joints do
		if mode == "C0" then
			j.motor.C0 = j.c0
		else
			j.motor.Transform = CFrame.identity
		end
	end
end

return Rig
]======])
put("ReplicatedStorage/MTL", "Signal", "ModuleScript", [======[--!strict
-- Tiny signal: Connect / Once / Fire / Wait. Handlers run in their own thread so one error can't stop the rest.
local Signal = {}
Signal.__index = Signal

export type Connection = { Connected: boolean, Disconnect: (self: Connection) -> () }

function Signal.new()
	return setmetatable({ _handlers = {} :: { [any]: (...any) -> () } }, Signal)
end

function Signal:Connect(fn: (...any) -> ())
	local key = {}
	self._handlers[key] = fn
	local conn = { Connected = true }
	function conn.Disconnect(c)
		c.Connected = false
		self._handlers[key] = nil
	end
	return conn
end

function Signal:Once(fn: (...any) -> ())
	local conn
	conn = self:Connect(function(...)
		conn:Disconnect()
		fn(...)
	end)
	return conn
end

function Signal:Fire(...: any)
	for _, fn in self._handlers do
		task.spawn(fn, ...)
	end
end

function Signal:Wait(): ...any
	local thread = coroutine.running()
	self:Once(function(...)
		task.spawn(thread, ...)
	end)
	return coroutine.yield()
end

function Signal:DisconnectAll()
	table.clear(self._handlers)
end

return Signal
]======])
put("ReplicatedStorage/MTL/Config", "DayNight", "ModuleScript", [======[--!strict
-- The day-night cycle and the look of every time of day (Master Plan §4 "Lighting and time of day").
-- Target look: Alex's hood references (vault: Vice Bay/References/Larp + Quality Target):
--   day     warm, slightly hazy blue sky, strong crisp shadows, a little desaturated
--   evening low gold sun, long shadows, orange-to-magenta sky, then a purple dusk
--   night   purple-blue fog, dark asphalt, warm sodium street lights and lit signs
-- The server only owns the clock (TimeService); every client draws the look itself (LightingController), so the
-- sun moves smoothly and a cutscene can show one player a different time (NextDay's morning) without touching
-- anyone else. Lighting.Technology must be Future (Studio only: Lighting > Technology).
local DayNight = {}

-- One full day in real minutes, split by phase. The clock runs at a different speed in each phase so the day gets
-- most of the real time and the night is long enough to feel, but never drags. Phases follow the clock order.
DayNight.Phases = {
	{ id = "Morning", from = 5.6, to = 9.5, minutes = 4 },
	{ id = "Day", from = 9.5, to = 16.6, minutes = 11 },
	{ id = "Evening", from = 16.6, to = 19.6, minutes = 5 },
	{ id = "Night", from = 19.6, to = 29.6, minutes = 8 }, -- to = 5.6 next day (+24)
}
DayNight.Latitude = 41 -- tilts the noon sun (Miami's real 26 puts it straight overhead: flat, shadowless streets)
DayNight.HideMapSky = true -- in game, use Roblox's soft default sky (hazy, real sunsets) instead of the place's Sky
DayNight.StartClock = 8.2 -- a fresh server starts in the morning (the first thing players see is a nice light)

-- Clock hours used by the story (local holds, see LightingController.hold)
DayNight.Story = {
	MoveIn = 21.4, -- PowerOut: you move in at night
	Sleep = 23.3, -- NextDay: the window at night before the card
	Wake = 7.0, -- NextDay: "6:58 AM", low morning sun through the boards
}

local RGB = Color3.fromRGB

-- Keyframes by clock hour (0-24). The look between two keys is blended (smoothstep). Every key lists every field.
--   Lighting: Brightness, Exposure, Ambient (indoors), Outdoor (outdoor ambient = shadow colour), Top/Bottom
--             (colour shift), EnvDiffuse, EnvSpecular, Softness (shadow softness)
--   Atmosphere: Density, Offset, AtmoColor, Decay, Glare, Haze
--   Grade (ColorCorrection): GBright, Contrast, Saturation, Tint
--   Bloom: Bloom, BloomSize, Threshold · SunRays: Rays, Spread · Clouds: Cover, CloudDensity, CloudColor
--   Lamps: 0..1, street lights and night-only neon (1 = fully on)
DayNight.Keys = {
	{
		at = 0, -- midnight
		Brightness = 2.4, Exposure = 0.7, Ambient = RGB(72, 72, 84), Outdoor = RGB(116, 116, 136),
		Top = RGB(176, 180, 208), Bottom = RGB(72, 72, 92), EnvDiffuse = 0.45, EnvSpecular = 0.7, Softness = 0.4,
		Density = 0.264, Offset = 0.18, AtmoColor = RGB(122, 120, 142), Decay = RGB(92, 90, 112), Glare = 0, Haze = 1.32,
		GBright = 0.02, Contrast = 0.1, Saturation = -0.25, Tint = RGB(236, 236, 248),
		Bloom = 0.9, BloomSize = 30, Threshold = 0.95, Rays = 0, Spread = 0.3,
		Cover = 0.72, CloudDensity = 0.4, CloudColor = RGB(84, 82, 96), Lamps = 1,
	},
	{
		at = 5.0, -- before dawn: still night, the sky starts to lift
		Brightness = 2.4, Exposure = 0.7, Ambient = RGB(74, 74, 86), Outdoor = RGB(118, 118, 140),
		Top = RGB(176, 180, 208), Bottom = RGB(74, 74, 96), EnvDiffuse = 0.4, EnvSpecular = 0.8, Softness = 0.35,
		Density = 0.264, Offset = 0.18, AtmoColor = RGB(128, 126, 148), Decay = RGB(96, 94, 116), Glare = 0, Haze = 1.32,
		GBright = 0.02, Contrast = 0.1, Saturation = -0.25, Tint = RGB(236, 236, 248),
		Bloom = 0.9, BloomSize = 30, Threshold = 0.95, Rays = 0, Spread = 0.3,
		Cover = 0.72, CloudDensity = 0.4, CloudColor = RGB(90, 88, 102), Lamps = 1,
	},
	{
		at = 6.1, -- sunrise: pink-orange sky, soft long light, lamps going off
		Brightness = 1.7, Exposure = 0.1, Ambient = RGB(84, 66, 78), Outdoor = RGB(126, 98, 112),
		Top = RGB(255, 168, 118), Bottom = RGB(96, 96, 150), EnvDiffuse = 0.7, EnvSpecular = 0.85, Softness = 0.45,
		Density = 0.252, Offset = 0.22, AtmoColor = RGB(255, 196, 172), Decay = RGB(196, 120, 146), Glare = 0.6, Haze = 1.32,
