	for _, t in def.tasks or {} do
		Jobs.TaskJob[t] = jobId
	end
end

-- Shift-done / first-task texts from the boss (light flavour, makes the job feel like a place).
Jobs.BossLines = {
	Patel = {
		FirstTask = "Good, good. Boxes go on the shelves, not in your pocket.",
