put("ReplicatedStorage/MTL/Config", "Movement", "ModuleScript", [======[--!strict
-- Moment-to-moment movement feel (client, Controllers/MovementController.lua). Why these numbers:
-- Research/Movement and Game Feel.md. Tune by feel; nothing here is saved or checked by the server.
local Movement = {}

-- speed (studs/s). MovementController is the only client script that writes Humanoid.WalkSpeed.
Movement.WalkSpeed = 16 -- Roblox default: every map, door and prompt distance was built around it
Movement.SprintSpeed = 24 -- x1.5: clearly faster, still lands inside the job sites' prompt ranges
Movement.EaseUpSeconds = 0.25 -- walk -> sprint reaches ~95% in this long (no snap)
Movement.EaseDownSeconds = 0.15 -- sprint -> walk (stopping should feel quicker than starting)

-- input
Movement.SprintKeys = { Enum.KeyCode.LeftShift } -- PC: hold. StarterPlayer.EnableMouseLockOption is off so Shift is free
Movement.SprintToggleKeys = { Enum.KeyCode.ButtonL3 } -- gamepad: click the left stick to toggle
Movement.ToggleOffIdleSeconds = 0.35 -- a toggled sprint (L3 / touch) switches off after standing still this long
Movement.TouchButton = { title = "RUN", position = UDim2.new(1, -150, 1, -100) } -- left of the jump button

-- camera (all off in first person, cutscenes, non-Custom cameras and with Settings.ReducedMotion)
Movement.SprintFov = 7 -- FOV added while sprinting (degrees), on top of whatever FOV the game set
Movement.FovEaseSeconds = 0.3
Movement.BobPitch = 0.35 -- sprint head bob (degrees, at full sprint)
Movement.BobRoll = 0.25 -- sprint sway (degrees)
Movement.BobStepsPerStud = 0.18 -- bob frequency follows ground speed (steps per stud travelled)
Movement.StrafeRoll = 1.25 -- camera roll at full speed sideways (degrees)
Movement.LandDipMax = 2.5 -- landing dip (degrees of pitch down) at LandDipFallSpeed
Movement.LandDipDrop = 0.35 -- and this many studs down
Movement.LandDipMinFallSpeed = 18 -- falls slower than this (a curb, a normal jump ~50 down) do nothing much
Movement.LandDipFallSpeed = 90

-- character lean (R15 LowerTorso.Root / R6 RootJoint C0, local only; pivots at the feet)
Movement.SprintLean = 5 -- forward lean at full sprint (degrees)
Movement.TurnLean = 6 -- side lean into a fast turn (degrees, max)
Movement.TurnLeanRate = 7 -- yaw rate (rad/s) that gives the full side lean
Movement.LeanStiffness = 90 -- spring (higher = snappier)
Movement.LeanDamping = 0.85 -- share of critical damping

-- jumping
Movement.JumpCooldown = 0.3 -- seconds after landing before the next jump (no bunny-hop spam)

-- Footsteps: the default Roblox character sounds (PlayerScripts.RbxCharacterSounds) already play steps and
-- landings in this place, so nothing extra here. TODO(Alex sfx): custom surface footsteps would go in Theme.Sfx.

return Movement
]======])
put("ReplicatedStorage/MTL/Config", "Phone", "ModuleScript", [======[--!strict
-- The phone: apps, tuning, scripted calls, GPS places. Tune here; no phone system hard-codes these.
-- Contacts (names/subtitles) live in Config/Story.Contacts so the story owns who people are.
local Phone = {}

-- Home-screen apps, in order. `id` is what the server/save uses (Phone.Apps[id] = true means installed).
-- `module` = the client app module in StarterPlayerScripts/MTL/Apps. `default` = installed on a new save.
-- `glyph` is the placeholder icon letter until Alex's icons arrive (Theme.Phone.Icons[id]).
Phone.Apps = {
	{ id = "Messages", title = "Messages", glyph = "M", default = true },
	{ id = "Calls", title = "Phone", glyph = "P", default = true },
	{ id = "Jobs", title = "Jobs", glyph = "J", default = true },
	{ id = "Map", title = "GPS", glyph = "G", default = true },
	{ id = "Camera", title = "Camera", glyph = "C", default = true }, -- photos (CaptureService) + selfie mode
	{ id = "Settings", title = "Settings", glyph = "S", default = true },
	{ id = "Plug", title = "Plug", glyph = "$", default = false }, -- Guns piece: guns + ammo, criminal path only
	{ id = "Goals", title = "Goals", glyph = "*", default = false }, -- Piece 4: the FreePlay goals list (unlocks at FreePlay)
}

Phone.Tuning = {
	DesignSize = Vector2.new(300, 620), -- phone in design pixels (everything inside is laid out for this)
	HeightOfScreen = 0.6, -- open phone height as a share of the screen height
	MinScale = 0.5,
	MaxScale = 1.25,
	Margin = 24, -- px from the right screen edge
	OpenBottom = 14, -- px from the bottom of the screen when open (low on screen)
	PeekShare = 0.07, -- share of the phone that sticks out when closed: just the top edge + time
	HoverShare = 0.11, -- on mouse hover
	PingShare = 0.22, -- when something arrives while closed; shows the banner
	PingSeconds = 3.5,
	TiltDegrees = 0, -- closed tilt (0 keeps the glass clipping clean)
	SpringOpenHz = 3.4, -- the phone moves on a spring: how fast it rises
	SpringOpenDamping = 0.72, -- < 1 = a small bounce at the top
	SpringCloseHz = 3.8, -- how fast it drops (no bounce)
	ToggleKeys = { Enum.KeyCode.M, Enum.KeyCode.DPadUp },
	SwipeClosePixels = 70, -- drag down this far on the top/bottom bar to close
	NotificationSeconds = 4,
	RingSeconds = 25, -- server: an unanswered call becomes "missed" after this
	MaxTextsPerThread = 60,
	MaxRecents = 30,
}

-- Scripted calls. The server rings with PhoneService.call(player, id); the client plays `lines` as captions
-- on the in-call screen (tap to advance, Skip), then shows `choices`. The server validates the choice id and
-- fires PhoneService.CallResolved(player, callId, choiceId). No choices -> resolves as "answered".
-- `callBack = true`: a missed/declined/hung-up call stays in Recents with a call-back button
-- (and after a choice with keepCallBack = true).
Phone.Calls = {
	Recruit = {
		contact = "Unknown",
		callBack = true,
		lines = {
			{ who = "Unknown", text = "You the one stacking shelves at Liberty?" },
			{ who = "Unknown", text = "Don't matter how I got the number. Eight bucks a box, that's what they pay you." },
			{ who = "Unknown", text = "I got people who make that in a minute. Real money." },
			{ who = "Unknown", text = "Come meet us. I'll send you the spot. Come alone." },
		},
		choices = {
			{ id = "accept", text = "I'm in" },
			{ id = "decline", text = "Not right now", keepCallBack = true }, -- stays in Recents to call back
		},
	},
}

-- Messages: canned replies the player can send in any thread (server checks the index), and what each contact
-- answers back (once a minute at most, after a short "typing" pause). Keep it short and in character.
Phone.QuickReplies = { "On my way", "Bet", "Who's this?", "Busy rn", "Say less", "Thanks" }
Phone.ReplyCooldown = 2.5 -- seconds between the player's replies
Phone.AutoReplyCooldown = 60 -- per contact
Phone.AutoReplies = {
	Patel = { "Less texting, more stacking.", "Shelves won't fill themselves!", "See you at the store." },
	Dre = { "Bet.", "Keep your head down.", "We'll hit you up." },
	Smoke = { "aight", "say less" },
	Nina = { "Don't text this number for dumb stuff.", "k." },
	Unknown = { "..." },
	default = { "👍" },
}

-- Contacts that never pick up when the player calls them (no scripted call): what the screen says.
Phone.NoAnswer = {
	default = "No answer",
	Patel = "Mr. Patel is busy. Text him instead.",
}

-- GPS places. `location` = a key in Config/Locations (the server resolves positions; the client never sends one).
-- `field` = which position inside that entry (Door by default). `requires` = story stage the player must have
-- reached before the place shows. `ownedHome = true` = only once the player owns a home.
Phone.Places = {
	{ id = "FoodMart", label = "Liberty Food Mart", location = "FoodMart", category = "Work" },
	{ id = "BurgerShack", label = "Burger Shack", location = "BurgerShack", category = "Work" },
	{ id = "WestsideAuto", label = "Westside Auto Repair", location = "WestsideAuto", category = "Work" },
	-- Level 8+ / 15+ job sites (Jobs piece). Shown once the player can pick their own job.
	{ id = "CarWash", label = "Bay Suds Car Wash", location = "CarWash", category = "Work", requires = "ChooseJob" },
	{ id = "Valet", label = "Coral Hotel", location = "Valet", category = "Work", requires = "ChooseJob" },
	{ id = "Security", label = "Bayside Mall", location = "Security", category = "Work", requires = "ChooseJob" },
	{ id = "TruckDepot", label = "Vice Bay Freight", location = "TruckDepot", category = "Work", requires = "ChooseJob" },
	{ id = "Docks", label = "Port of Vice Bay", location = "Docks", category = "Work", requires = "ChooseJob" },
	{ id = "Home", label = "Your place", location = "EndsFlat", category = "Home", requires = "FindAPlace" },
}

Phone.GPSWaypointId = "GPS" -- the GPS uses its own waypoint id so it never replaces the story waypoint

-- Jobs app shell: shown until the Jobs piece adds Config/Jobs.lua (then the app reads that instead).
Phone.JobsFallback = {
	{ id = "Supermarket", title = "Liberty Food Mart", role = "Stocker", pay = "$8 / task", level = 1, place = "FoodMart" },
	{ id = "Mechanic", title = "Westside Auto Repair", role = "Mechanic", pay = "$10 / task", level = 1, place = "WestsideAuto" },
	{ id = "Restaurant", title = "Burger Shack", role = "Cook", pay = "$9 / task", level = 1, place = "BurgerShack" },
}

-- Lifestyle switch (Settings). Opens from this stage on (StoryRules.freePlayOpen). Cooldown stops spam-flipping.
Phone.PathSwitchCooldown = 30
Phone.Paths = {
	Civilian = { title = "Civilian", blurb = "Work, earn, stay safe. No guns out, no PvP." },
	Criminal = { title = "Criminal", blurb = "Crew missions, guns out, PvP on. Watch your back." },
}

-- Settings the client may change (whitelist + type). Keys live in the save under Settings.
Phone.SettingKeys = {
	Music = "boolean",
	Sound = "boolean",
	ReducedMotion = "boolean",
	Tutorial = "number", -- TutorialController: how many tutorial steps are done (Config/Tutorial; 99 = skipped)
}

return Phone
]======])
put("ReplicatedStorage/MTL/Config", "Property", "ModuleScript", [======[--!strict
-- Story Piece 4: homes (the flat in the Ends), interiors, the power bill, sleeping. Tune here only.
-- Master Plan §1 stages 8-12. PropertyService (server) + PropertyController (client) read this.
--
-- HOW THE FLAT WORKS
--   Outside: an invisible door part at Locations.EndsFlat.Door (or a map part tagged MTL_FlatDoor with attribute
--   Id = "EndsFlat") carries the door prompt. Not owned -> the FOR SALE card. Owned -> go inside.
--   Inside: every owner gets their OWN copy of the interior (an instanced room), built far away from the map at
--   a slot position, so two players never share one dirty room. Walking in/out is a fade + teleport.
--   The room: ServerStorage.MTL_FlatInterior (Alex's model) wins over the part-built placeholder. A model needs a
--   PrimaryPart at floor level in the middle of the room (front = -Z = the back wall, the door in the +Z wall) and
--   parts with the names in `Points` (anywhere inside the model). Missing ones fall back to the numbers below.
local Economy = require(script.Parent.Economy)

local V = Vector3.new

local Property = {}

Property.Homes = {
	EndsFlat = {
		title = "Flat 3B", -- placeholder name until Alex names the building
		area = "The Ends",
		price = Economy.EndsFlatPrice,
		location = "EndsFlat", -- Config/Locations key (Door = outside door, Out = where you appear when you leave)
		place = "Home", -- Config/Phone.Places id (GPS)
		-- the FOR SALE card (honest about how bad it is; that's the joke and the goal)
		blurb = "One room. One window. Lights not included (the power bill is your problem).",
		facts = {
			{ "Bedroom", "Yes (it's also the kitchen)" },
			{ "Power", "Off. Bill not paid" },
			{ "Landlord", "Doesn't ask questions" },
		},
		photo = "rbxassetid://0", -- TODO(Alex art): a photo of the room for the card
	},
}
Property.StarterHome = "EndsFlat" -- the story's flat (stage FindAPlace)

-- Instanced interiors: slot i sits at Origin + (i-1) * Spacing along X (far from the map, above the sea).
Property.Slots = {
	Origin = V(6000, 400, 6000),
	Spacing = 160,
	Max = 60, -- more than a full server
}

-- The placeholder room and the named points (local to the room's PrimaryPart; y = 0 is the floor).
-- "Spot" points are floor points (actors stand/sit there); the rest are objects (camera targets).
Property.Interior = {
	Size = V(26, 12, 22), -- inside size of the placeholder room (X wide, Y high, Z deep)
	Points = {
		Entry = V(6, 0, 7.5), -- where you appear when you walk in (facing -Z)
		Exit = V(6, 0, 10.6), -- the inside of the front door (the "Leave" prompt)
		ChairSpot = V(-6, 0, -6.4), -- sitting at the PC (pelvis above this floor point)
		Screen = V(-6, 3.55, -8.56), -- the dead monitor (its front face)
		Keyboard = V(-6, 2.3, -8.1),
		PowerLed = V(-8.2, 1.7, -8.25),
		BedSpot = V(7.6, 0, -4.5), -- sitting on the edge of the mattress (facing -X, into the room)
		BedStand = V(5.6, 0, -2.4), -- where you stand after getting up
		BedSeat = V(7.8, 1.05, -4.5), -- the real Seat on the mattress
		Breaker = V(11.6, 4.5, 10.75), -- breaker box by the door (power bill prompt)
		Window = V(6, 6, -10.9),
		Bulb = V(0, 9.6, 0),
	},
	PromptDistance = 7,
}

-- The power bill (Master Plan §1 FreePlay goals). One payment turns the power on (no real-time bills yet).
Property.Power = {
	Bill = Economy.PowerBill,
	-- No power = the bulb is dead (it flickers once when you walk in, then dies); the room is lit only by the
	-- cold street light through the boards. Paying turns the bulb on for good and boots the PC (client visuals).
}

-- Door and buy rules (server checks).
Property.Door = {
	Radius = 12, -- studs from the door where buying / entering is accepted
	FadeOut = 0.3, -- seconds of fade before the teleport
	Hold = 0.35, -- seconds black while the room streams in
	EnterCooldown = 1.5,
}

-- What the story says in stages 8-13 (Config/Story.Contacts ids). Rename freely.
Property.Texts = {
	-- stage 8 FindAPlace: Dre texts right after the offer card closes
	FindAPlace = {
		{ who = "Dre", text = "You got paid. Now get off the street before somebody sees you counting it." },
		{ who = "Dre", text = "There's a flat going in the Ends. Cheap. Landlord don't ask questions.", link = true },
	},
	-- stage 13 FreePlay: one welcome text
	FreePlay = { who = "Dre", text = "Heard you got a real job. Smart, keeps you clean. When you want more, you know where we are." },
	-- stage 12 CommuteToWork: the boss of the job you picked texts when you wake up (Config/Jobs.Defs[job].boss)
	Wake = {
		Patel = "Morning! Somebody robbed us the other night, can you believe it? I need all the help I can get. Come in!",
		Rico = "Morning, rookie. Bays open at 7. Come find me at Westside Auto.",
		Tasha = "Morning! Grill's heating up. Burger Shack, don't be late on day one.",
		default = "Morning. Your first shift starts when you get here.",
	},
}

-- One line under each starter job card on the ChooseJob screen (story flavour, keyed by job id).
Property.JobHooks = {
	Supermarket = "Mr. Patel's hiring again. He has no idea it was you.",
	Mechanic = "Rico pays fair, and you learn your way around cars.",
	Restaurant = "Tasha runs a tight kitchen. Busy, but the time flies.",
}

-- The PC once the power is on. Honest: nothing to do on it yet.
Property.PC = {
	OffText = "No power. Pay the power bill first.",
	OnText = "Nothing to do on the PC yet. It gets apps in a later update.",
}

return Property
]======])
put("ReplicatedStorage/MTL/Config", "Story", "ModuleScript", [======[--!strict
-- The story stages in order (Master Plan §1). Index = onboarding funnel step number. Never reorder; only append.
local Story = {}

