put("ReplicatedStorage/MTL/Config", "Tutorial", "ModuleScript", [======[--!strict
-- The new-player tutorial (TutorialController; Research: Cinematic Cutscenes §9). One small coach card at a time,
-- a pulsing ring around the real thing it talks about, and the step ends when the player actually does it.
-- Steps run in order, only while the story is at one of their `stages`; a step whose stages are already behind the
-- player counts as done (a returning player never sees "open your phone" at Level 9).
-- Progress is saved in Settings.Tutorial (= number of steps done, Skipped = skipped). Order matters: append only.
--
-- Step fields:
--   id, stages = { story stage ids }, title, body = text | { kb, touch, pad } (per input device; kb is the default)
--   keys = { kb = {...}, touch = {...}, pad = {...} }   key chips under the text
--   target = a Targets id (what the ring goes around; nil = no ring) · whileOpen / whileOpenTarget = text + ring while
--   the phone is up (phone steps)
--   done = "phone" (opened, then put away) | "stage" (the story left these stages) | "task" (first job task done)
--        | "menu" (menu opened) | "seen"   and/or  seconds = auto-advance after this long on screen
--   ok = "Got it" button text (shown for "seen" steps)
local Tutorial = {}

Tutorial.Skipped = 99

-- PlayerGui paths tried in order (the HUD and phone get redesigned; names are the contract, see UI/Build/*).
Tutorial.Targets = {
	Phone = { { "MTL_Phone", "Phone", "Body" }, { "MTL_Phone", "Phone" } },
	Messages = { { "MTL_Phone", "**App_Messages" } }, -- "**Name" = anywhere below (the phone's layout changes)
	Objective = { { "MTL_HUD", "Objective" } },
	Job = { { "MTL_Job", "Panel" } },
	Cash = { { "MTL_HUD", "Top", "Cash" } },
	Level = { { "MTL_HUD", "Top", "Status", "Level" }, { "MTL_HUD", "Top", "Status" } },
	Menu = { { "MTL_HUD", "Menu", "Toggle" } },
}

Tutorial.Steps = {
	{
		id = "Phone",
		stages = { "Arrive" },
		title = "Your phone just buzzed",
		body = { kb = "Press M to check it.", touch = "Tap your phone in the bottom right to check it.", pad = "Press up on the D-pad to check it." },
		keys = { kb = { "M" }, pad = { "D-pad up" } },
		target = "Phone",
		done = "phone",
		whileOpen = { kb = "Tap Messages to read Mr. Patel's text. Press M to put the phone away.", touch = "Tap Messages to read Mr. Patel's text, then swipe the phone down.", pad = "Open Messages to read Mr. Patel's text, then press up on the D-pad." },
		whileOpenTarget = "Messages", -- the ring moves to the Messages app while the phone is up
	},
	{
		id = "Walk",
		stages = { "Arrive" },
		title = "Head to Liberty Food Mart",
		body = "Follow the glowing arrows. Your next goal always sits at the top of the screen.",
		keys = { kb = { "W", "A", "S", "D" }, touch = { "Left thumb to walk" }, pad = { "Left stick" } },
		target = "Objective",
		done = "stage",
	},
	{
		id = "Job",
		stages = { "FirstShift" },
		title = "Clock in, get paid",
		body = { kb = "Your task is on the job panel. Walk to the glowing spot and hold E.", touch = "Your task is on the job panel. Walk to the glowing spot and hold the button.", pad = "Your task is on the job panel. Walk to the glowing spot and hold X." },
		keys = { kb = { "Hold E" }, pad = { "Hold X" } },
		-- the card names the live task from the job panel: "Now: Stock the empty shelf. Follow the glow ..."
		liveTask = { kb = "Follow the glow, then hold E.", touch = "Follow the glow, then hold the button.", pad = "Follow the glow, then hold X." },
		target = "Job",
		done = "task",
	},
	{
		id = "Paid",
		stages = { "FirstShift" },
		title = "Payday",
		body = "Every task pays. Watch your cash stack up right here.",
		target = "Cash",
		done = "seen",
		seconds = 7,
		ok = "Got it",
	},
	{
		id = "Level",
		stages = { "FirstShift" },
		title = "Level up",
		body = "Tasks fill this ring with XP. Hit Level 4 and someone comes calling...",
		target = "Level",
		done = "seen",
		seconds = 8,
		ok = "Got it",
	},
	{
		id = "Menu",
		stages = { "FirstShift" },
		title = "Your menu",
		body = { kb = "Press G for the store, emotes and settings.", touch = "Tap this button for the store, emotes and settings.", pad = "Press left on the D-pad for the store, emotes and settings." },
		keys = { kb = { "G" }, pad = { "D-pad left" } },
		target = "Menu",
		done = "menu",
		seconds = 12,
	},
}

Tutorial.Tuning = {
	FirstDelay = 1.2, -- seconds after a cutscene / join before the first card shows
	BetweenSteps = 0.9, -- pause after a step is done (the tick shows) before the next card
	PhoneReadSeconds = 10, -- "phone" steps also finish if the phone stays open this long
	DoneToast = "That's the basics. The city's yours.",
}

return Tutorial
]======])
put("ReplicatedStorage/MTL/Cutscenes", "FirstDay", "ModuleScript", [======[--!strict
-- Stage 2 (FirstShift), first time only: Mr. Patel meets you inside Liberty Food Mart (~16.4 s, skippable).
-- Data only: CutsceneController plays it. Research: Cinematic Cutscenes. Shot plan:
--   A  0.0  high corner wide as you walk in; the door bell rings on the cut     (where: inside the store)
--   B  3.4  two-shot, you and Patel on the shop floor                              (who)
--   C  7.4  over your shoulder on Patel; he points to the back                   (the job)
--   D 11.4  close-up on Patel, the joke                                           (who he is)
--   E 13.8  you walk into the aisle, the camera glides into a close gameplay camera, "FIRST SHIFT" (hand-off)
-- Anchor = StoryWelcome.storeAnchor(): at Locations.FoodMart.Door, local -Z = into the store, local +X = world -X.
-- Layout (measured in Studio after the job-interiors rebuild, 2026-11-02): front door centred at local x 0 in the
-- glass line (local z -6.3), checkout counter on the east side at local x -17 (world x -1425), Patel's spot behind
-- it at local (-23, -12), shelf rows from local z -18 back, free aisle at local x -4, coolers at the back.
local V = Vector3.new

local MEET = V(-12.5, 0, -11) -- you stop at the counter, across from Patel
local AISLE = V(-4, 0, -21) -- then walk into the aisle (the real character waits here, hidden); camera stays inside
local BACK = V(-4, 0, -40) -- the coolers at the back

return {
	id = "FirstDay",
	length = 16.4,
	skippable = true,
	fadeIn = 0.7,
	grade = { TintColor = Color3.fromRGB(240, 248, 232), Saturation = -0.04, Contrast = 0.06, Brightness = 0.02 }, -- shop strip lights
	dof = true,
	stream = { V(0, 0, -20) },
	placePlayer = { at = AISLE, face = BACK },
	actors = {
		Patel = { rig = "Patel", at = V(-23, 0, -12), face = MEET },
		Player = { rig = "@player", at = V(0, 0, 1), face = MEET },
	},
	shots = {
		-- A: high wide from inside the store, looking back at the door as you come in (the bell rings on the cut)
		{ t = 0, from = { pos = V(-6, 9.5, -19), look = V(-1, 4, -5) }, to = { pos = V(-6.5, 9, -18), look = V(-4, 4, -7) }, dur = 3.4, fov = 58, blur = 0.15 },
		-- B: two-shot from the shop floor: you screen-left, Patel behind the counter screen-right
		{ t = 3.4, from = { pos = V(-7, 5.6, -17), look = V(-17.8, 4.6, -11.5) }, to = { pos = V(-7.8, 5.5, -16.2), look = V(-17.8, 4.6, -11.5) }, dur = 4, fov = 50, blur = 0.3 },
		-- C: over your shoulder on Patel while he points to the back
		{ t = 7.4, from = { ots = { "Player", "Patel" }, dist = 4.4, side = 2.2 }, to = { ots = { "Player", "Patel" }, dist = 3.8, side = 2.2 }, dur = 3.8, fov = 48, blur = 0.4 },
		-- D: medium close on Patel, the joke
		{ t = 11.4, from = { pos = V(-15.5, 5.5, -14), look = "Patel" }, to = { pos = V(-16.2, 5.4, -13.4), look = "Patel" }, dur = 2.4, fov = 44, ease = "Quad", blur = 0.5 },
		-- E: you walk into the aisle; the camera follows and settles into a close gameplay camera (we're indoors)
		{ t = 13.8, from = { pos = V(-7, 6.4, -12), look = V(-4, 4, -34) }, to = { gameplay = true, dist = 7.5, height = 2.4 }, dur = 2.6, fov = 56, fovTo = 70, ease = "Cubic", blur = 0.1 },
	},
	lines = {
		{ t = 3.8, who = "Patel", text = "Ah, the new kid! Right on time. I like that.", dur = 3.0 },
		{ t = 7.6, who = "Patel", text = "Boxes in the back, shelves out front. Eight bucks a box.", dur = 3.8 },
		{ t = 11.5, who = "Patel", text = "Break nothing. And smile, customers love a smile.", dur = 3.2 },
	},
	actions = {
