	id = "PowerOut",
	length = 16.2,
	skippable = true,
	holdBlack = false, -- ends on gameplay: the real you is already sitting on the bed, phone coming up
	fadeIn = 0.5,
	grade = { TintColor = Color3.fromRGB(236, 240, 214), Saturation = -0.28, Contrast = 0.1, Brightness = -0.04 }, -- grimy
	dof = true,
	ambience = "RoomTone",
