put("ReplicatedStorage/MTL/Cutscenes", "Welcome", "ModuleScript", [======[--!strict
-- Stage 1 (Arrive), first join only: the welcome (~26.6 s, skippable). Data only: CutsceneController plays it.
-- Built against Research: Cinematic Cutscenes. Shot plan (wide -> medium -> close -> hand-off):
--   A  0.0  aerial crane over the Ends down to Liberty Food Mart, game title       (establishing, high = "small, new")
--   B  6.4  street level by the curb, slow dolly, store sign in the distance          (where we are)
--   C 10.8  low tracking shot: the player walks in from the boulevard                  (who)
--   D 15.4  CUT ON THE BUZZ: close-up, phone out, Mr. Patel's text                     (the hook: you have a job)
--   E 19.6  over the shoulder toward the store door, dolly in                          (the goal)
--   F 23.4  the camera glides into the gameplay camera behind the real player, "CHAPTER 1" (hand-off, no snap)
-- Coordinates are LOCAL to the anchor: StoryWelcome sends CFrame.new(Locations.Spawn) (no rotation), so local =
-- world minus the spawn (-1432, 3, -368). The Food Mart door is at local (-10, 0, 38); north = -Z.
local V = Vector3.new

local DOOR = V(-10, 0, 38)
local STAND = V(-3, 0, 12) -- where the player ends up (and the real character waits, hidden)
local FROM = V(24, 0, -4) -- walks in from the boulevard side

return {
	id = "Welcome",
	length = 26.6,
	skippable = true,
	fadeIn = 1.2,
	hour = 7.6, -- early morning: low warm sun, long shadows (LightingController holds it, then blends back)
	grade = { TintColor = Color3.fromRGB(255, 241, 224), Saturation = 0.08, Contrast = 0.08, Brightness = 0.01 }, -- warm, hopeful
	dof = true,
	music = "WelcomeMusic", -- Theme.Cutscene.Sounds ("" = silent until Alex sends a track)
	musicVolume = 0.4,
	ambience = "City",
	stream = { DOOR, V(60, 0, -120), V(-40, 0, 80) },
	placePlayer = { at = STAND, face = DOOR },
	actors = {
		Player = { rig = "@player", at = FROM, face = STAND },
	},
	shots = {
		-- A: aerial crane down along a spline (no corners), looking at the store front
		{
			t = 0,
			from = { path = { V(170, 165, -250), V(110, 110, -170), V(55, 62, -100), V(22, 30, -52) }, lookPath = { V(-14, 0, 26), V(-13, 2, 29), V(-12, 4, 31), V(-11, 6, 33) } }, -- the lot in front of the door (never inside a building)
			dur = 6.4,
			fov = 55,
			fovTo = 50,
			blur = 0.08,
			safe = false, -- high above the roofs: no wall check (it would pull the camera into the store)
		},
		-- B: street level, low by the curb, slow sideways dolly; the store sign far away
		{ t = 6.4, from = { pos = V(16, 2.4, -24), look = V(-12, 9, 34) }, to = { pos = V(3, 2.9, -15), look = V(-12, 8, 34) }, dur = 4.4, fov = 58, blur = 0.15 },
		-- C: low tracking shot while the player walks in (camera leads the walk)
		{ t = 10.8, from = { pos = V(12, 2.2, 14), look = "Player" }, to = { pos = V(3, 2.6, 22), look = "Player" }, dur = 4.6, fov = 46, blur = 0.3 },
		-- D: close-up on the buzz (cut on action), slow push
		{ t = 15.4, from = { close = "Player", dist = 5.4, side = 1 }, to = { close = "Player", dist = 4.4, side = 1 }, dur = 4.2, fov = 38, ease = "Quad", blur = 0.5 },
		-- E: over the shoulder toward the store door, dolly in
		{ t = 19.6, from = { pos = V(-4.0, 5.7, 7.0), look = V(-12, 7, 34) }, to = { pos = V(-3.9, 5.5, 8.4), look = V(-12, 7, 34) }, dur = 3.8, fov = 50, focus = V(-11, 6, 38), blur = 0.25 },
		-- F: glide into the gameplay camera behind the real player (Research §5: hand-off)
		{ t = 23.4, from = { pos = V(-3.9, 5.5, 8.4), look = V(-12, 7, 34) }, to = { gameplay = true }, dur = 3.2, fov = 50, fovTo = 70, ease = "Cubic", blur = 0.1 },
	},
	lines = {
		{ t = 7.0, who = "You", text = "Fifty bucks and a phone. That's the whole plan.", dur = 3.4 },
		{ t = 11.6, who = "You", text = "No job. No crib. Nobody knows my name.", dur = 3.2 },
		{ t = 16.2, who = "Patel", text = "Morning! Your first shift starts now. Come on in.", dur = 3.2 },
		{ t = 20.0, who = "You", text = "Stocking shelves. Everybody starts somewhere.", dur = 3.2 },
	},
	actions = {
		{ t = 1.2, title = "MIAMI TRAP LIFE", sub = "Vice Bay, Florida", dur = 4.2 },
		{ t = 10.8, actor = "Player", walk = STAND, dur = 4.8 },
		{ t = 15.4, sound = "PhoneVibrate" },
		{ t = 15.6, actor = "Player", turn = DOOR, dur = 0.5 },
		{ t = 15.7, actor = "Player", pose = "Phone" },
		{ t = 16.0, sound = "PhoneMessage", volume = 0.4 },
		{ t = 19.4, actor = "Player", pose = "None" },
		{ t = 20.4, actor = "Player", gesture = "Nod", dur = 1.0 },
		{ t = 23.6, title = "CHAPTER 1", sub = "New in Town", dur = 2.8 },
	},
}
]======])
put("ReplicatedStorage/MTL/Rules", "CutsceneRules", "ModuleScript", [======[--!strict
-- Pure timeline maths for cutscenes (no Instances, unit-tested in tools/tests/test_story_rules.py).
-- A cutscene is data (ReplicatedStorage/MTL/Cutscenes/<Id>.lua); everything on screen is a function of the clock t,
-- so skipping or tap-advancing is just moving t. See CutsceneController for the data format.
local CutsceneRules = {}

CutsceneRules.MaxLength = 45 -- story scenes stay short (Research: Cutscenes)
CutsceneRules.CharsPerSecond = 40 -- typewriter speed
CutsceneRules.SkipGrace = 1 -- seconds before a skip is accepted (stops accidental skips)
CutsceneRules.SkipHold = 0.6 -- hold this long to skip; a tap only finishes / advances the line

local function clamp01(a: number): number
	if a < 0 then
		return 0
	elseif a > 1 then
		return 1
	end
	return a
end

-- Ease curves. Camera never uses Linear (robotic); it's here for props.
function CutsceneRules.ease(name: string?, a: number): number
	a = clamp01(a)
	if name == "Linear" then
		return a
	elseif name == "Quad" then
		if a < 0.5 then
			return 2 * a * a
		end
		local b = -2 * a + 2
		return 1 - b * b / 2
	elseif name == "QuadIn" then
		return a * a
	elseif name == "QuadOut" then
		return 1 - (1 - a) * (1 - a)
	elseif name == "Cubic" then
		if a < 0.5 then
			return 4 * a * a * a
		end
		local b = -2 * a + 2
		return 1 - b * b * b / 2
	elseif name == "Snap" then
		if a >= 1 then
			return 1
		end
		return 0
	end
	-- "Sine" (default): smooth in and out
	return -(math.cos(math.pi * a) - 1) / 2
end

-- Index of the item whose start time is the latest one <= t (items sorted by .t). 0 = none yet.
function CutsceneRules.indexAt(items: { any }, t: number): number
	local found = 0
	for i, it in items do
		if (it.t or 0) <= t then
			found = i
		else
			break
		end
	end
	return found
end

-- Eased progress (0..1) through a shot's move. Shots without dur hold still (1 = at `to`, or at `from`).
function CutsceneRules.shotAlpha(shot: any, t: number): number
	local dur = shot.dur
	if not dur or dur <= 0 then
		return 1
	end
	return CutsceneRules.ease(shot.ease, (t - (shot.t or 0)) / dur)
end

-- How long a subtitle line stays up: its own dur, or long enough to read.
function CutsceneRules.lineDuration(line: any): number
	if line.dur then
		return line.dur
	end
	return 1.2 + #(line.text or "") / 16
end

-- The line on screen at t (or nil), and its index.
function CutsceneRules.lineAt(lines: { any }, t: number): (any?, number)
	local i = CutsceneRules.indexAt(lines, t)
	local line = lines[i]
	if line and t < line.t + CutsceneRules.lineDuration(line) then
		return line, i
	end
	return nil, i
end

-- Characters of `text` shown at time t for a line that started at t0.
function CutsceneRules.typed(text: string, t0: number, t: number, cps: number?): number
	local n = math.floor((t - t0) * (cps or CutsceneRules.CharsPerSecond))
	return math.clamp(n, 0, #text)
end

-- Tap: if the current line is still typing, finish it (returns t unchanged + true); otherwise jump to the start
-- of the next line (or nil when there is none: let the scene play on).
function CutsceneRules.tapTarget(lines: { any }, t: number, cps: number?): (number?, boolean)
	local line = CutsceneRules.lineAt(lines, t)
	if line and CutsceneRules.typed(line.text, line.t, t, cps) < #line.text then
		return t, true
	end
	for _, l in lines do
		if l.t > t + 0.05 then
			return l.t, false
		end
	end
	return nil, false
end

-- Total length: scene.length, or the end of the last thing in it.
function CutsceneRules.length(scene: any): number
	if scene.length then
		return scene.length
	end
	local last = 0
	for _, s in scene.shots or {} do
		last = math.max(last, (s.t or 0) + (s.dur or 0))
	end
	for _, l in scene.lines or {} do
		last = math.max(last, l.t + CutsceneRules.lineDuration(l))
	end
	for _, a in scene.actions or {} do
		last = math.max(last, (a.t or 0) + (a.dur or 0))
	end
	return last
end

-- Actions that start in (from, to] (fired once while the clock passes them).
function CutsceneRules.crossed(actions: { any }, from: number, to: number): { any }
	local out = {}
	for _, a in actions do
		local at = a.t or 0
		if at > from and at <= to then
			table.insert(out, a)
		end
	end
	return out
end

local function sorted(items: { any }?): boolean
	local last = -math.huge
	for _, it in items or {} do
		if (it.t or 0) < last then
			return false
		end
		last = it.t or 0
	end
	return true
end

-- Checks a scene for mistakes. Returns a list of problems (empty = fine). Used by the tests and by the controller
-- (warns in Output, still plays).
function CutsceneRules.validate(scene: any, speakers: { [string]: any }?): { string }
	local problems = {}
	local function bad(msg: string)
		table.insert(problems, msg)
	end
	if type(scene) ~= "table" then
		return { "not a table" }
	end
	if type(scene.shots) ~= "table" or #scene.shots == 0 then
		bad("no shots")
	end
	if not sorted(scene.shots) then
		bad("shots out of order")
	end
	if not sorted(scene.lines) then
		bad("lines out of order")
	end
	if not sorted(scene.actions) then
		bad("actions out of order")
	end
	local length = CutsceneRules.length(scene)
	if length > CutsceneRules.MaxLength then
		bad("too long: " .. length .. "s")
	end
	if (scene.shots and scene.shots[1] and (scene.shots[1].t or 0) ~= 0) then
		bad("first shot must start at t = 0")
	end
	for _, s in scene.shots or {} do
		if s.fov and (s.fov < 20 or s.fov > 80) then
			bad("fov out of range at t=" .. tostring(s.t))
		end
		if s.ease == "Linear" then
			bad("linear camera ease at t=" .. tostring(s.t))
		end
	end
	local lines = scene.lines or {}
	for i, l in lines do
		if type(l.text) ~= "string" or l.text == "" then
			bad("empty line at t=" .. tostring(l.t))
		end
		if speakers and l.who and not speakers[l.who] then
			bad("unknown speaker " .. tostring(l.who))
		end
		local nextLine = lines[i + 1]
		if nextLine and l.t + CutsceneRules.lineDuration(l) > nextLine.t + 0.01 then
			bad("line at t=" .. l.t .. " overlaps the next one")
		end
		if l.t + CutsceneRules.lineDuration(l) > length + 0.01 then
			bad("line at t=" .. l.t .. " runs past the end")
		end
		-- readable: at least 1 s per 15 characters once fully typed
		local typing = #l.text / CutsceneRules.CharsPerSecond
		if CutsceneRules.lineDuration(l) - typing < #l.text / 25 then
			bad("line at t=" .. l.t .. " is too short to read")
		end
	end
	local actors = scene.actors or {}
	for _, a in scene.actions or {} do
		if a.actor and not actors[a.actor] and not (scene.props and scene.props[a.actor]) then
			bad("action for unknown actor " .. tostring(a.actor))
		end
	end
	return problems
end

return CutsceneRules
]======])
put("ReplicatedStorage/MTL/Rules", "DayNightRules", "ModuleScript", [======[--!strict
-- Pure maths for the day-night cycle (no Instances; unit-tested in tools/tests/test_daynight_rules.py).
-- "Position" = real seconds into the cycle, 0 = the start of the first phase (Morning). The clock runs at a
-- different speed in each phase (Config/DayNight.Phases), so position <-> clock is piecewise linear.
local DayNight = require(script.Parent.Parent.Config.DayNight)

local DayNightRules = {}

local function wrap24(h: number): number
	return h % 24
end

function DayNightRules.cycleSeconds(phases: any?): number
	local total = 0
	for _, p in phases or DayNight.Phases do
		total += p.minutes * 60
	end
	return total
end

-- clock hour (0-24) at `pos` real seconds into the cycle
function DayNightRules.clockAt(pos: number, phases: any?): number
	local list = phases or DayNight.Phases
	local total = DayNightRules.cycleSeconds(list)
	local t = pos % total
	for _, p in list do
		local len = p.minutes * 60
		if t < len then
			return wrap24(p.from + (p.to - p.from) * (t / len))
		end
		t -= len
	end
	return wrap24(list[1].from)
end

-- inverse: real seconds into the cycle for a clock hour (used to jump the clock: debug, server start)
function DayNightRules.positionFor(clock: number, phases: any?): number
	local list = phases or DayNight.Phases
	local h = wrap24(clock)
	local start = 0
	for _, p in list do
		local len = p.minutes * 60
		-- the phase's range, unwrapped so it can cross midnight (Night: 19.6 -> 29.6)
		local hh = h
		if hh < p.from then
			hh += 24
		end
		if hh >= p.from and hh < p.to then
			return start + len * (hh - p.from) / (p.to - p.from)
		end
		start += len
	end
	return 0
end

function DayNightRules.phaseOf(clock: number, phases: any?): string
	local list = phases or DayNight.Phases
	local h = wrap24(clock)
	for _, p in list do
		local hh = h
		if hh < p.from then
			hh += 24
		end
		if hh >= p.from and hh < p.to then
			return p.id
		end
	end
	return list[1].id
end

local function smooth(x: number): number
	return x * x * (3 - 2 * x)
end

-- the two keys around `clock` and the eased blend between them: (keyA, keyB, alpha 0..1)
function DayNightRules.sample(clock: number, keys: any?): (any, any, number)
	local list = keys or DayNight.Keys
	local h = wrap24(clock)
	local n = #list
	for i = 1, n do
		local a = list[i]
		local b = list[i + 1]
		local bAt = if b then b.at else list[1].at + 24
		if not b then
			b = list[1]
		end
		if h >= a.at and h < bAt then
			return a, b, smooth((h - a.at) / (bAt - a.at))
		end
	end
	-- before the first key (only if the first key isn't at 0): blend from the last key across midnight
	local last = list[n]
	local first = list[1]
	local span = first.at + 24 - last.at
	return last, first, smooth((h + 24 - last.at) / span)
end

-- shortest way round the clock from `from` to `to` (hours, -12..12) for blending a held clock back
function DayNightRules.clockDelta(from: number, to: number): number
	local d = (to - from) % 24
	if d > 12 then
		d -= 24
	end
	return d
end

return DayNightRules
]======])
put("ReplicatedStorage/MTL/Rules", "GoalRules", "ModuleScript", [======[--!strict
-- Pure FreePlay goal evaluation (no Instances; unit-tested in tools/tests/test_flat_rules.py).
-- Input: a save snapshot (data). Output: one entry per visible goal, in Config/Goals order:
--   { id, title, sub, done, claimed, soon, progress (0..1), progressText, action, reward }
-- `claimed` = the reward was already given (data.Goals.Done[id]); a claimed goal stays done even if the number
-- drops again later (spending cash never "un-does" Save5k).
local Goals = require(script.Parent.Parent.Config.Goals)

local GoalRules = {}

local function money(n: number): string
	local s = tostring(math.floor(n))
	local out = s:reverse():gsub("(%d%d%d)", "%1,"):reverse()
	if out:sub(1, 1) == "," then
		out = out:sub(2)
	end
	return "$" .. out
end
GoalRules.money = money

local function count(t: any): number
	local n = 0
	if type(t) == "table" then
		for _, v in t do
			if v then
				n += 1
			end
		end
	end
	return n
end

-- (done, progress 0..1, progressText) for one goal definition.
function GoalRules.check(g: any, d: any): (boolean, number, string)
	local kind = g.kind
	if kind == "power" then
		local on = d.Home ~= nil and d.Home.PowerOn == true
		if on then
			return true, 1, "Power on"
		end
		local cash = d.Cash or 0
		local need = g.amount or 1
		return false, math.clamp(cash / math.max(need, 1), 0, 1), money(math.min(cash, need)) .. " / " .. money(need)
	elseif kind == "shifts" then
		local job = d.Job and d.Job.Current or ""
		local n = (job ~= "" and d.Job.Shifts and d.Job.Shifts[job]) or 0
		local need = g.count or 1
		return n >= need, math.clamp(n / need, 0, 1), string.format("%d / %d", math.min(n, need), need)
	elseif kind == "level" then
		local lv = d.Level or 1
		return lv >= g.level, math.clamp(lv / g.level, 0, 1), string.format("Level %d / %d", math.min(lv, g.level), g.level)
	elseif kind == "cash" then
		local cash = d.Cash or 0
		return cash >= g.amount, math.clamp(cash / g.amount, 0, 1), money(math.min(cash, g.amount)) .. " / " .. money(g.amount)
	elseif kind == "guns" then
		local n = count(d.Inventory and d.Inventory.Guns)
		local need = g.count or 1
		return n >= need, math.clamp(n / need, 0, 1), string.format("%d / %d", math.min(n, need), need)
	end
	return false, 0, "Coming soon"
end

function GoalRules.visible(g: any, d: any): boolean
	return g.path == nil or g.path == d.Path
end

function GoalRules.evaluate(d: any, list: { any }?): { any }
	local out = {}
	local claimedSet = (d.Goals and d.Goals.Done) or {}
	for _, g in list or Goals.List do
		if GoalRules.visible(g, d) then
			local soon = g.kind == "soon"
			local done, progress, text = GoalRules.check(g, d)
			local claimed = claimedSet[g.id] ~= nil
			table.insert(out, {
				id = g.id,
				title = g.title,
				sub = g.sub,
				done = (done or claimed) and not soon,
				claimed = claimed,
				soon = soon,
				progress = if claimed then 1 else progress,
				progressText = if claimed and not done then "Done" else text,
				action = g.action,
				reward = g.reward or 0,
			})
		end
	end
	return out
end

-- The first goal that is not done and not "soon" (or nil when everything playable is done).
function GoalRules.top(d: any, list: { any }?): any?
	for _, e in GoalRules.evaluate(d, list) do
		if not e.done and not e.soon then
			return e
		end
	end
	return nil
end

-- Goals that are done but not yet rewarded (the server pays these once and records them).
function GoalRules.newlyDone(d: any, list: { any }?): { any }
	local out = {}
	for _, e in GoalRules.evaluate(d, list) do
		if e.done and not e.claimed then
			table.insert(out, e)
		end
	end
	return out
end

-- The HUD objective line for free play.
function GoalRules.objective(d: any, prefix: string?, list: { any }?): string
	local top = GoalRules.top(d, list)
	if not top then
		return ""
	end
	return (prefix or Goals.ObjectivePrefix) .. top.title .. "  (" .. top.progressText .. ")"
end

return GoalRules
]======])
put("ReplicatedStorage/MTL/Rules", "GunRules", "ModuleScript", [======[--!strict
-- Pure gun maths and rules (no Instances, no Vector3), shared by GunService and GunController and unit-tested
-- by tools/tests/test_gun_rules.py. Angles in degrees unless a name says Rad.
local GunRules = {}

---------------------------------------------------------------- who may do what

-- Can this player take this gun out? mode = "Live" | "Intimidate".
function GunRules.canEquip(path: string, mode: string, onShift: boolean, inSafe: boolean, alive: boolean): (boolean, string?)
	if not alive then
		return false, "You're down"
	end
	if mode == "Intimidate" then
		return true, nil -- story guns: any path, safe zones too (the robbery happens inside the store)
	end
	if path ~= "Criminal" then
		return false, "Guns are for the Criminal lifestyle (phone: Settings)"
	end
	if onShift then
		return false, "Not while you're on shift"
	end
	if inSafe then
		return false, "Safe zone: guns stay holstered here"
	end
	return true, nil
end

-- Can a shot from attacker hurt this target?
--   target = { isPlayer, path, safe, damageable (NPC attribute MTL_Damageable), self }
function GunRules.canDamage(mode: string, attackerPath: string, attackerSafe: boolean, target: any): (boolean, string?)
	if mode ~= "Live" then
		return false, "no-damage gun"
	end
	if target.self then
		return false, "self"
	end
	if not target.isPlayer then
		return target.damageable == true, if target.damageable then nil else "protected NPC"
	end
	if attackerPath ~= "Criminal" then
		return false, "attacker not criminal"
	end
	if target.path ~= "Criminal" then
		return false, "target is a civilian"
	end
	if attackerSafe or target.safe then
		return false, "safe zone"
	end
	return true, nil
end

---------------------------------------------------------------- damage

-- Linear falloff: 100% up to FalloffStart, FalloffMin from FalloffEnd on.
function GunRules.falloff(def: any, distance: number): number
	local s, e = def.FalloffStart or 0, def.FalloffEnd or def.Range or 1
	if distance <= s then
		return 1
	end
	if distance >= e or e <= s then
		return def.FalloffMin or 1
	end
	local a = (distance - s) / (e - s)
	return 1 + ((def.FalloffMin or 1) - 1) * a
end

function GunRules.damage(def: any, distance: number, head: boolean): number
	if distance > (def.Range or 0) then
		return 0
	end
	local d = def.Damage * GunRules.falloff(def, distance) * (if head then def.HeadMult or 1 else 1)
	return math.floor(d * 10 + 0.5) / 10
end

-- Shots to kill `health` at a distance with body shots (balance tests + the shop card).
function GunRules.shotsToKill(def: any, health: number, distance: number, head: boolean?): number
	local per = GunRules.damage(def, distance, head == true) * (def.Pellets or 1)
	if per <= 0 then
		return math.huge
	end
	return math.ceil(health / per - 1e-9)
end

function GunRules.timeToKill(def: any, health: number, distance: number): number
	local n = GunRules.shotsToKill(def, health, distance)
	return (n - 1) * GunRules.fireInterval(def)
end

---------------------------------------------------------------- fire rate

function GunRules.fireInterval(def: any): number
	return 60 / def.RPM
end

-- Server-side token bucket. tokens refill at RPM/60 / tolerance per second, at most `burst`.
function GunRules.newBucket(burst: number, now: number)
	return { tokens = burst, t = now }
end

function GunRules.rateAllow(bucket: any, def: any, now: number, tolerance: number, burst: number): boolean
	local rate = (def.RPM / 60) / tolerance
	bucket.tokens = math.min(burst, bucket.tokens + math.max(0, now - bucket.t) * rate)
	bucket.t = now
	if bucket.tokens >= 1 then
		bucket.tokens -= 1
		return true
	end
	return false
end

---------------------------------------------------------------- spread

-- state = { aiming, moving, airborne, bloom }
function GunRules.spread(def: any, state: any): number
	local s = def.Spread
	local base = if state.aiming then s.Aim else s.Hip
	if state.moving then
		base += s.Move * (if state.aiming then 0.5 else 1)
	end
	if state.airborne then
		base += s.Air
	end
	return base + math.clamp(state.bloom or 0, 0, s.MaxBloom or 0)
end

-- The widest cone this gun can ever have (server angle check).
function GunRules.maxSpread(def: any): number
	local s = def.Spread
	return math.max(s.Hip, s.Aim) + s.Move + s.Air + (s.MaxBloom or 0) + (def.PelletSpread or 0)
end

function GunRules.bloomAfterShot(def: any, bloom: number): number
	return math.min((def.Spread.MaxBloom or 0), bloom + (def.Spread.Bloom or 0))
end

function GunRules.bloomRecover(def: any, bloom: number, dt: number): number
	return math.max(0, bloom - (def.Spread.Recover or 0) * dt)
end

-- A random direction inside a cone, uniform over the disc. u1, u2 in [0, 1).
-- Returns (pitchRad, yawRad) to apply as CFrame.Angles(pitch, yaw, 0) on the aim CFrame.
function GunRules.coneOffset(maxDeg: number, u1: number, u2: number): (number, number)
	local r = math.rad(maxDeg) * math.sqrt(u1)
	local a = 2 * math.pi * u2
	return r * math.cos(a), r * math.sin(a)
end

-- Angle between two direction vectors given as numbers.
function GunRules.angle(ax: number, ay: number, az: number, bx: number, by: number, bz: number): number
	local la = math.sqrt(ax * ax + ay * ay + az * az)
	local lb = math.sqrt(bx * bx + by * by + bz * bz)
	if la < 1e-6 or lb < 1e-6 then
		return 180
	end
	local c = math.clamp((ax * bx + ay * by + az * bz) / (la * lb), -1, 1)
	return math.deg(math.acos(c))
end

---------------------------------------------------------------- recoil

-- Camera kick for one shot: (up, side) degrees. sideRand in [-1, 1].
function GunRules.recoilKick(def: any, sideRand: number, scale: number?): (number, number)
	local r = def.Recoil
	local k = scale or 1
	return r.Up * k, r.Side * sideRand * k
end

-- Split a kick: `stay` part moves the camera for good (full-auto climbs), `bounce` part springs back.
function GunRules.recoilSplit(def: any, up: number): (number, number)
	local ret = math.clamp(def.Recoil.Return or 0.7, 0, 1)
	return up * (1 - ret), up * ret
end

-- Damped spring toward 0. s = { x, v }. stiffness k, damping ratio z (1 = critical). Sub-stepped for stability.
function GunRules.springStep(s: any, k: number, z: number, dt: number)
	local steps = math.max(1, math.ceil(dt / (1 / 240)))
	local h = dt / steps
	local c = 2 * math.sqrt(k) * z
	for _ = 1, steps do
		local a = -k * s.x - c * s.v
		s.v += a * h
		s.x += s.v * h
	end
	return s
end

-- Launch speed so the spring's peak is about `peak` (critically damped peak = v0 / (w * e)).
function GunRules.kickVelocity(peak: number, k: number): number
	return peak * math.sqrt(k) * math.exp(1)
end

---------------------------------------------------------------- ammo

-- Reload: fill the mag from the reserve. Returns newMag, newReserve.
function GunRules.reload(mag: number, magSize: number, reserve: number): (number, number)
	local need = math.max(0, magSize - mag)
	local take = math.min(need, math.max(0, reserve))
	return mag + take, reserve - take
end

function GunRules.canReload(mag: number, magSize: number, reserve: number): boolean
	return mag < magSize and reserve > 0
end

---------------------------------------------------------------- hit checks

-- Distance from a point (in the box's local space) to a box of half-size (hx, hy, hz). 0 = inside.
function GunRules.boxDistance(lx: number, ly: number, lz: number, hx: number, hy: number, hz: number): number
	local dx = math.max(math.abs(lx) - hx, 0)
	local dy = math.max(math.abs(ly) - hy, 0)
	local dz = math.max(math.abs(lz) - hz, 0)
	return math.sqrt(dx * dx + dy * dy + dz * dz)
end

-- Lag-comp history: indices of the samples to test for a shot at time t (server clock) given "now".
-- times = ascending list. Returns the list of indices whose time is inside [max(now-maxRewind, t-window), now].
function GunRules.rewindSamples(times: { number }, t: number, now: number, maxRewind: number, window: number): { number }
	local from = math.max(now - maxRewind, math.min(t, now) - window)
	local out = {}
	for i, ti in times do
		if ti >= from and ti <= now + 1e-6 then
			table.insert(out, i)
		end
	end
	return out
end

-- In a fight = shot at or got hit by a player within FightSeconds.
function GunRules.inFight(lastCombat: number?, now: number, seconds: number): boolean
	return lastCombat ~= nil and now - lastCombat < seconds
end

-- Is a point inside a round config zone? (x, z distance, y within height)
function GunRules.inZone(px: number, py: number, pz: number, cx: number, cy: number, cz: number, radius: number, height: number): boolean
	local dx, dz = px - cx, pz - cz
	return dx * dx + dz * dz <= radius * radius and math.abs(py - cy) <= height
end

-- Shop: can the player buy this gun? owned = already have it.
function GunRules.canBuyGun(def: any, level: number, cash: number, path: string, owned: boolean): (boolean, string?)
	if path ~= "Criminal" then
		return false, "Criminal lifestyle only"
	end
	if owned then
		return false, "Already yours"
	end
	if level < (def.Level or 1) then
		return false, "Level " .. tostring(def.Level)
	end
	if cash < def.Price then
		return false, "Not enough cash"
	end
	return true, nil
end

function GunRules.canBuyAmmo(pack: any, reserve: number, cash: number, path: string, ownsUser: boolean): (boolean, string?)
	if path ~= "Criminal" then
		return false, "Criminal lifestyle only"
	end
	if not ownsUser then
		return false, "You don't have a gun for this"
	end
	if reserve >= pack.Max then
		return false, "Full"
	end
	if cash < pack.Price then
		return false, "Not enough cash"
	end
	return true, nil
end

-- Crosshair gap in pixels for a cone of `deg` on a screen `height` px tall with vertical fov `fov`.
function GunRules.crosshairGap(deg: number, fov: number, height: number): number
	return math.tan(math.rad(deg)) / math.tan(math.rad(fov / 2)) * height / 2
end

return GunRules
]======])
put("ReplicatedStorage/MTL/Rules", "JobRules", "ModuleScript", [======[--!strict
-- Pure job maths and rules (no Instances): which jobs a player sees and may work, which task comes next,
-- how a minigame score turns into pay and XP, shift bonuses, and the minimum time a step may take
-- (the server's anti-exploit check). Shared by JobService, JobController, the Jobs app and the unit tests.
local Jobs = require(script.Parent.Parent.Config.Jobs)
local StoryRules = require(script.Parent.StoryRules)

local JobRules = {}

function JobRules.def(jobId: any): any?
	return if type(jobId) == "string" then Jobs.Defs[jobId] else nil
end

function JobRules.task(taskId: any): any?
	return if type(taskId) == "string" then Jobs.Tasks[taskId] else nil
end

---------------------------------------------------------------- who can see / pick / work a job

-- Jobs listed in the phone at this story stage.
--   before ChooseJob : only the story job (Mr. Patel is expecting you)
--   ChooseJob        : the 3 starter jobs (the story beat)
--   after            : every job (locked ones show their level)
function JobRules.visibleJobs(stage: string): { string }
	if stage == Jobs.ChooseFromStage then
		return table.clone(Jobs.StarterJobs)
	end
	if not StoryRules.reached(stage, Jobs.ChooseFromStage) then
		return { Jobs.StoryJob }
	end
	return table.clone(Jobs.Order)
end

function JobRules.isVisible(jobId: string, stage: string): boolean
	return table.find(JobRules.visibleJobs(stage), jobId) ~= nil
end

-- May this player pick `jobId` as their job right now?
function JobRules.canChoose(jobId: any, level: number, stage: string): (boolean, string?)
	local def = JobRules.def(jobId)
	if not def then
		return false, "Unknown job"
	end
	if not StoryRules.reached(stage, Jobs.ChooseFromStage) then
		return false, "Finish your shifts at the Food Mart first"
	end
	if not JobRules.isVisible(jobId, stage) then
		return false, "Not hiring right now"
	end
	if level < def.level then
		return false, "Reach Level " .. def.level
	end
	return true, nil
end

-- May this player clock in to `jobId` right now?
function JobRules.canWork(jobId: any, level: number, stage: string): (boolean, string?)
	local def = JobRules.def(jobId)
	if not def then
		return false, "Pick a job in the Jobs app"
	end
	if Jobs.BlockedStages[stage] then
		return false, "Not now"
	end
	if level < def.level then
		return false, "Reach Level " .. def.level
	end
	return true, nil
end

-- Job ids that unlock exactly at `level` (for the level-up phone ping).
function JobRules.unlockedAt(level: number): { string }
	local out = {}
	for _, id in Jobs.Order do
		if Jobs.Defs[id].level == level and level > 1 then
			table.insert(out, id)
		end
	end
	return out
end

---------------------------------------------------------------- tasks

-- Tasks of this job the player can get at this level.
function JobRules.availableTasks(jobId: string, level: number): { string }
	local def = JobRules.def(jobId)
	local out = {}
	if not def or not def.tasks then
		return out
	end
	for _, id in def.tasks do
		local t = Jobs.Tasks[id]
		if t and (t.level or 1) <= level then
			table.insert(out, id)
		end
	end
	return out
end

-- Weighted pick of the next task. `history` = recent task ids, newest last. A task never comes up a
-- third time in a row (variety inside a shift). `rand()` returns [0, 1).
function JobRules.pickTask(jobId: string, level: number, history: { string }, rand: () -> number): string?
	local pool = JobRules.availableTasks(jobId, level)
	if #pool == 0 then
		return nil
	end
	local n = #history
	local banned: string? = nil
	if n >= 2 and history[n] == history[n - 1] and #pool > 1 then
		banned = history[n]
	end
	local total = 0
	for _, id in pool do
		if id ~= banned then
			total += Jobs.Tasks[id].weight or 1
		end
	end
	local r = rand() * total
	for _, id in pool do
		if id ~= banned then
			r -= Jobs.Tasks[id].weight or 1
			if r < 0 then
				return id
			end
		end
	end
	for i = #pool, 1, -1 do
		if pool[i] ~= banned then
			return pool[i]
		end
	end
	return pool[1]
end

-- Picks a station id from a step's `at` list, avoiding `last` when there's a choice.
function JobRules.pickStation(at: { string }, last: string?, rand: () -> number): string
	if #at == 1 then
		return at[1]
	end
	local options = {}
	for _, s in at do
		if s ~= last then
			table.insert(options, s)
		end
	end
	if #options == 0 then
		options = at
	end
	return options[math.clamp(math.floor(rand() * #options) + 1, 1, #options)]
end

-- The ordered items for a sequence step. keepOrder = the pool IS the order (oil change);
-- otherwise `count` random items from the pool, in random order (burger ticket).
function JobRules.sequenceItems(step: any, rand: () -> number): { string }
	local pool = table.clone(step.pool or {})
	if step.keepOrder then
		return pool
	end
	local out = {}
	local count = math.min(step.count or #pool, #pool)
	for _ = 1, count do
		local i = math.clamp(math.floor(rand() * #pool) + 1, 1, #pool)
		table.insert(out, table.remove(pool, i) :: string)
	end
	return out
end

-- Seconds a hold minigame takes at this level (Quick hands perk).
function JobRules.holdSeconds(step: any, level: number): number
	local s = step.seconds or 3
	if level >= Jobs.QuickHandsLevel then
		s *= Jobs.QuickHandsScale
	end
	return s
end

-- The fastest an honest player can finish this step after it began (server check).
function JobRules.minStepSeconds(step: any, level: number): number
	local V = Jobs.Validation
	if step.kind == "hold" then
		return JobRules.holdSeconds(step, level) * V.HoldTolerance
	elseif step.kind == "timing" then
		return (step.hits or 3) * V.TimingMinPerHit
	elseif step.kind == "sequence" then
		return (step.count or 4) * V.SequenceMinPerItem
	end
	return V.MinPromptSeconds
end

function JobRules.isMinigame(kind: string): boolean
	return kind == "hold" or kind == "timing" or kind == "sequence"
end

---------------------------------------------------------------- scores (0..1, computed on the client, clamped on the server)

function JobRules.scoreHold(releases: number): number
	return math.clamp(1 - 0.15 * releases, 0.4, 1)
end

function JobRules.scoreTiming(hits: number, misses: number): number
	if hits <= 0 then
		return 0.4
	end
	return math.clamp(hits / (hits + misses), 0.4, 1)
end

function JobRules.scoreSequence(mistakes: number): number
	return math.clamp(1 - 0.2 * mistakes, 0.4, 1)
end

---------------------------------------------------------------- pay and XP

-- Multiplier from level pay raises (Level 6: +10%, Level 9: +20%).
function JobRules.payRaise(level: number): number
	local m = 1
	for _, r in Jobs.PayRaises do
		if level >= r.level then
			m += r.share
		end
	end
	return m
end

-- score -> multiplier, label ("PERFECT" | "" | "SLOPPY"). The PERFECT bonus (tips) starts at Quality.PerfectBonusLevel.
function JobRules.quality(score: number?, level: number?): (number, string)
	local Q = Jobs.Quality
	if score == nil then
		return 1, ""
	end
	if score >= Q.Perfect then
		local bonus = if (level or 1) >= Q.PerfectBonusLevel then Q.PerfectBonus else 0
		return 1 + bonus, "PERFECT"
	elseif score < Q.Good then
		return 1 - Q.SloppyPenalty, "SLOPPY"
	end
	return 1, ""
end

-- Base pay and XP for finishing a task (before the 2x passes/boosts, which EconomyService applies).
-- `score` = the minigame score (nil if the task had no minigame), `distance` = studs (route jobs).
function JobRules.taskReward(taskId: string, level: number, score: number?, distance: number?): (number, number, string)
	local t = Jobs.Tasks[taskId]
	if not t then
		return 0, 0, ""
	end
	local q, label = JobRules.quality(score, level)
	local pay = t.pay * JobRules.payRaise(level) * q
	if t.distancePay and distance then
		pay += t.distancePay * math.max(0, distance)
	end
	local xp = t.xp * q
	return math.floor(pay + 0.5), math.floor(xp + 0.5), label
end

-- Post jobs: pay and XP per pay tick.
function JobRules.postTick(jobId: string, level: number): (number, number)
	local def = Jobs.Defs[jobId]
	if not def or def.kind ~= "post" then
		return 0, 0
	end
	local share = Jobs.Post.PayEvery / 60
	return math.floor(def.perMinute * share * JobRules.payRaise(level) + 0.5), math.floor((def.xpPerMinute or 0) * share + 0.5)
end

function JobRules.shiftBonusShare(level: number): number
	local S = Jobs.Shift
	if level >= S.BigBonusLevel then
		return S.BigBonusShare
	elseif level >= S.BonusLevel then
		return S.BonusShare
	end
	return 0
end

function JobRules.shiftLength(jobId: string): number
	local def = Jobs.Defs[jobId]
	return if def and def.kind == "post" then Jobs.Shift.PostTicks else Jobs.Shift.Tasks
end

-- Rough $/min and XP/min for the app ("about $24/min"). Uses each task's `est` seconds + the job's gap.
function JobRules.perMinute(jobId: string, level: number): (number, number)
	local def = Jobs.Defs[jobId]
	if not def then
		return 0, 0
	end
	if def.kind == "post" then
		return math.floor(def.perMinute * JobRules.payRaise(level) + 0.5), def.xpPerMinute or 0
	end
	local pool = JobRules.availableTasks(jobId, math.max(level, def.level))
	local wsum, cash, xp, secs = 0, 0, 0, 0
	local gap = if def.gap then (def.gap[1] + def.gap[2]) / 2 else 0
	for _, id in pool do
		local t = Jobs.Tasks[id]
		local w = t.weight or 1
		wsum += w
		cash += w * (t.pay + (t.distancePay or 0) * (t.estDistance or 0))
		xp += w * t.xp
		secs += w * ((t.est or 20) + gap)
	end
	if wsum == 0 or secs == 0 then
		return 0, 0
	end
	local perSec = 60 / secs
	return math.floor(cash * perSec * JobRules.payRaise(level) + 0.5), math.floor(xp * perSec + 0.5)
end

-- "Chill" label for the app.
function JobRules.tierLabel(tier: number): string
	if tier >= 3 then
		return "AFK-friendly"
	elseif tier == 2 then
		return "Laid back"
	end
	return "Hands-on"
end

return JobRules
]======])
put("ReplicatedStorage/MTL/Rules", "LevelRules", "ModuleScript", [======[--!strict
-- Pure level maths (no Instances), shared by EconomyService, the HUD and the tests.
local Levels = require(script.Parent.Parent.Config.Levels)

local LevelRules = {}

-- XP needed to go from `level` to `level + 1`.
function LevelRules.need(level: number): number
	if level >= Levels.MaxLevel then
		return math.huge
	end
	return math.floor(Levels.Base + Levels.Scale * (math.max(level, 1) - 1) ^ Levels.Power + 0.5)
end

-- Total XP from Level 1 to reach `level`.
function LevelRules.totalTo(level: number): number
	local total = 0
	for l = 1, level - 1 do
		total += LevelRules.need(l)
	end
	return total
end

-- Adds XP. Returns newLevel, newXP (XP inside the level), and the list of levels gained (in order).
function LevelRules.add(level: number, xp: number, amount: number): (number, number, { number })
	local gained = {}
	xp += math.max(0, amount)
	while level < Levels.MaxLevel and xp >= LevelRules.need(level) do
		xp -= LevelRules.need(level)
		level += 1
		table.insert(gained, level)
	end
	if level >= Levels.MaxLevel then
		xp = 0
	end
	return level, xp, gained
end

-- 0..1 progress through the current level (for the HUD bar).
function LevelRules.progress(level: number, xp: number): number
	local need = LevelRules.need(level)
	if need == math.huge then
		return 1
	end
	return math.clamp(xp / need, 0, 1)
end

function LevelRules.unlocks(level: number): { string }
	return Levels.Unlocks[level] or {}
end

return LevelRules
]======])
put("ReplicatedStorage/MTL/Rules", "MissionRules", "ModuleScript", [======[--!strict
-- Pure helpers for missions and the meet (no Instances, unit-tested in tools/tests/test_story_rules.py).
local MissionRules = {}

-- Picks one meet spot. `roll` is a random number in [0, 1) (the server rolls it once and saves the result).
function MissionRules.pickSpot(spots: { any }, roll: number): any?
	if #spots == 0 then
		return nil
	end
	local i = math.clamp(math.floor(roll * #spots) + 1, 1, #spots)
	return spots[i]
end

function MissionRules.findSpot(spots: { any }, id: any): any?
	for _, s in spots do
		if s.Id == id then
			return s
		end
	end
	return nil
end

function MissionRules.stepIndex(def: any, stepId: any): number?
	for i, s in def.Steps do
		if s.id == stepId then
			return i
		end
	end
	return nil
end

function MissionRules.step(def: any, index: number): any?
	return def.Steps[index]
end

function MissionRules.isLast(def: any, index: number): boolean
	return index >= #def.Steps
end

-- A held step is long enough (server side; `share` forgives lag, e.g. 0.75).
function MissionRules.holdOk(needSeconds: number, elapsed: number, share: number): boolean
	return elapsed >= needSeconds * share
end

-- Flat (x/z) facing check: is the target in front of `look` within `minDot` (cosine) and within `range`?
function MissionRules.facingOk(fromX: number, fromZ: number, lookX: number, lookZ: number, toX: number, toZ: number, minDot: number, range: number): boolean
	local dx, dz = toX - fromX, toZ - fromZ
	local dist = math.sqrt(dx * dx + dz * dz)
	if dist > range then
		return false
	end
	if dist < 0.5 then
		return true
	end
	local ll = math.sqrt(lookX * lookX + lookZ * lookZ)
	if ll < 1e-6 then
		return false
	end
	local dot = (dx / dist) * (lookX / ll) + (dz / dist) * (lookZ / ll)
	return dot >= minDot
end

-- What the job pays before multipliers. escapeSeconds = alarm -> car (nil = not measured, no bonus).
function MissionRules.payout(def: any, escapeSeconds: number?): (number, number, boolean)
	local take = def.Pay or 0
	local clean = escapeSeconds ~= nil and def.CleanGetaway ~= nil and escapeSeconds <= def.CleanGetaway.Seconds
	local bonus = if clean then def.CleanGetaway.Bonus else 0
	return take, bonus, clean
end

-- The checklist the client shows: { {id, text, done, current} }.
function MissionRules.checklist(def: any, index: number): { any }
	local out = {}
	for i, s in def.Steps do
		table.insert(out, { id = s.id, text = s.text, done = i < index, current = i == index })
	end
	return out
end

-- "0:25"
function MissionRules.clock(seconds: number): string
	local s = math.max(0, math.floor(seconds + 0.5))
	return string.format("%d:%02d", math.floor(s / 60), s % 60)
end

return MissionRules
]======])
put("ReplicatedStorage/MTL/Rules", "PhoneRules", "ModuleScript", [======[--!strict
-- Pure phone helpers (no Instances), shared by PhoneService, the phone apps and the tests.
-- Save shapes (Master Plan §3.4, Phone):
--   Texts[contactId]  = { { me = bool, text = string, t = os.time(), link = {kind, place}? }, ... } oldest first
--   Unread[contactId] = number
--   Recents           = { { call = callId?, contact = id, kind = "missed"|"declined"|"answered"|"outgoing",
--                           t = os.time(), callBack = bool, seen = bool }, ... } newest first
--   Contacts[contactId] = true
local Phone = require(script.Parent.Parent.Config.Phone)
local StoryRules = require(script.Parent.StoryRules)

local PhoneRules = {}

-- Adds a message to a thread, keeping only the newest `max`. Returns the thread.
function PhoneRules.appendText(thread: { any }, msg: any, max: number?): { any }
	table.insert(thread, msg)
	local limit = max or Phone.Tuning.MaxTextsPerThread
	while #thread > limit do
		table.remove(thread, 1)
	end
	return thread
end

-- Adds a call to the front of Recents, keeping only the newest `max`. Returns the list.
function PhoneRules.addRecent(recents: { any }, entry: any, max: number?): { any }
	table.insert(recents, 1, entry)
	local limit = max or Phone.Tuning.MaxRecents
	while #recents > limit do
		table.remove(recents)
	end
	return recents
end

-- A later call-back for the same call replaces the old "call back" button (only the newest one can be called back).
function PhoneRules.clearCallBack(recents: { any }, callId: string)
	for _, r in recents do
		if r.call == callId then
			r.callBack = false
		end
	end
end

-- The newest Recents entry for `callId` that can still be called back, or nil.
function PhoneRules.findCallBack(recents: { any }, callId: string): any?
	for _, r in recents do
		if r.call == callId and r.callBack then
			return r
		end
	end
	return nil
end

function PhoneRules.unreadTotal(phone: any): number
	local n = 0
	for _, c in (phone and phone.Unread) or {} do
		if type(c) == "number" then
			n += c
		end
	end
	return n
end

function PhoneRules.missedCount(phone: any): number
	local n = 0
	for _, r in (phone and phone.Recents) or {} do
		if r.kind == "missed" and not r.seen then
			n += 1
		end
	end
	return n
end

-- Badge numbers per app id for the home screen.
function PhoneRules.badges(phone: any): { [string]: number }
	return { Messages = PhoneRules.unreadTotal(phone), Calls = PhoneRules.missedCount(phone) }
end

-- Thread list for Messages: { {contact, last, t, unread} } newest first.
function PhoneRules.threads(phone: any): { any }
	local out = {}
	for contact, list in (phone and phone.Texts) or {} do
		local last = list[#list]
		if last then
			table.insert(out, {
				contact = contact,
				last = last,
				t = last.t or 0,
				unread = (phone.Unread and phone.Unread[contact]) or 0,
			})
		end
	end
	table.sort(out, function(a, b)
		if a.t ~= b.t then
			return a.t > b.t
		end
		return a.contact < b.contact
	end)
	return out
end

-- "now", "4m", "2h", "3d"
function PhoneRules.ago(seconds: number): string
	if seconds < 60 then
		return "now"
	elseif seconds < 3600 then
		return math.floor(seconds / 60) .. "m"
	elseif seconds < 86400 then
		return math.floor(seconds / 3600) .. "h"
	end
	return math.floor(seconds / 86400) .. "d"
end

-- Minutes after midnight -> "9:05 PM"
function PhoneRules.clock(minutes: number): string
	local m = math.floor(minutes) % 1440
	local h24 = m // 60
	local h12 = h24 % 12
	if h12 == 0 then
		h12 = 12
	end
	return string.format("%d:%02d %s", h12, m % 60, if h24 < 12 then "AM" else "PM")
end

function PhoneRules.place(id: any): any?
	for _, p in Phone.Places do
		if p.id == id then
			return p
		end
	end
	return nil
end

-- Is this GPS place listed for a player at `stage` (ownsHome = player owns any home)?
function PhoneRules.placeVisible(place: any, stage: string, ownsHome: boolean): boolean
	if place.requires and not StoryRules.reached(stage, place.requires) then
		return false
	end
	if place.ownedHome and not ownsHome then
		return false
	end
	return true
end

-- World position of a GPS place, read from Config/Locations (passed in so this stays pure). Returns pos, radius.
function PhoneRules.placePosition(place: any, locations: any): (Vector3?, number)
	local loc = locations[place.location]
	if typeof(loc) == "Vector3" then
		return loc, 14
	elseif type(loc) == "table" then
		local v = loc[place.field or "Door"] or loc.Inside
		if typeof(v) == "Vector3" then
			return v, loc.Radius or 14
		end
	end
	return nil, 14
end

function PhoneRules.validChoice(callId: any, choiceId: any): boolean
	local cfg = type(callId) == "string" and Phone.Calls[callId] or nil
	if not cfg then
		return false
	end
	if not cfg.choices then
		return choiceId == "answered"
	end
	for _, c in cfg.choices do
		if c.id == choiceId then
			return true
		end
	end
	return false
end

-- Can the player switch Lifestyle now? Returns ok, reason (shown in Settings when not ok).
function PhoneRules.canSwitchPath(stage: string, current: string, wanted: any, lastSwitch: number, now: number): (boolean, string?)
	if wanted ~= "Civilian" and wanted ~= "Criminal" then
		return false, "Unknown lifestyle"
	end
	if wanted == current then
		return false, "Already " .. wanted
	end
	if not StoryRules.freePlayOpen(stage) then
		return false, "Unlocks after your first mission"
	end
	local wait = Phone.PathSwitchCooldown - (now - lastSwitch)
	if wait > 0 then
		return false, string.format("Wait %ds to switch again", math.ceil(wait))
	end
	return true, nil
end

function PhoneRules.validSetting(key: any, value: any): boolean
	return type(key) == "string" and Phone.SettingKeys[key] ~= nil and type(value) == Phone.SettingKeys[key]
end

function PhoneRules.appInfo(id: any): (any?, number?)
	for i, a in Phone.Apps do
		if a.id == id then
			return a, i
		end
	end
	return nil
end

return PhoneRules
]======])
put("ReplicatedStorage/MTL/Rules", "PropertyRules", "ModuleScript", [======[--!strict
-- Pure helpers for homes (no Instances; unit-tested in tools/tests/test_flat_rules.py).
local Property = require(script.Parent.Parent.Config.Property)
local StoryRules = require(script.Parent.StoryRules)

local PropertyRules = {}

function PropertyRules.home(id: any): any?
	return if type(id) == "string" then (Property.Homes :: any)[id] else nil
end

function PropertyRules.owns(d: any, id: string): boolean
	return d.Home ~= nil and type(d.Home.Owned) == "table" and d.Home.Owned[id] ~= nil
end

function PropertyRules.ownsAny(d: any): boolean
	return d.Home ~= nil and type(d.Home.Owned) == "table" and next(d.Home.Owned) ~= nil
end

-- May this player buy home `id` now? -> ok, reason?, shortfall (cash still needed, 0 when enough)
function PropertyRules.canBuy(d: any, id: string): (boolean, string?, number)
	local h = PropertyRules.home(id)
	if not h then
		return false, "Not for sale", 0
	end
	if PropertyRules.owns(d, id) then
		return false, "You already own this place", 0
	end
	if not StoryRules.reached(d.Story.Stage, "FindAPlace") then
		return false, "Not for sale yet", 0
	end
	local short = math.max(0, h.price - (d.Cash or 0))
	if short > 0 then
		return false, "Not enough cash", short
	end
	return true, nil, 0
end

-- Slot i (1-based) -> the room's world origin (Vector3; the room faces -Z).
function PropertyRules.slotOrigin(i: number): Vector3
	local s = Property.Slots
	return s.Origin + Vector3.new((i - 1) * s.Spacing, 0, 0)
end

-- The lowest free slot index (taken[i] = true), or nil when every slot is used.
function PropertyRules.freeSlot(taken: { [number]: boolean }): number?
	for i = 1, Property.Slots.Max do
		if not taken[i] then
			return i
		end
	end
	return nil
end

-- Is a world point inside a room whose origin is `origin`? (generous box around the room)
function PropertyRules.insideRoom(origin: Vector3, p: Vector3): boolean
	local size = Property.Interior.Size
	local d = p - origin
	return math.abs(d.X) <= size.X / 2 + 6 and math.abs(d.Z) <= size.Z / 2 + 6 and d.Y > -8 and d.Y < size.Y + 8
end

-- Story stages where a returning player wakes up inside their home (first spawn of the session).
PropertyRules.HomeSpawnFrom = "MoveIn"
function PropertyRules.spawnsAtHome(d: any): boolean
	return PropertyRules.ownsAny(d) and StoryRules.reached(d.Story.Stage, PropertyRules.HomeSpawnFrom)
end

-- What the outside door prompt says for this player.
function PropertyRules.doorText(d: any, id: string): string
	local h = PropertyRules.home(id)
	if not h then
		return "Door"
	end
	if PropertyRules.owns(d, id) then
		return "Go inside"
	end
	return "For sale · $" .. tostring(h.price)
end

return PropertyRules
]======])
put("ReplicatedStorage/MTL/Rules", "StoryRules", "ModuleScript", [======[--!strict
-- Pure helpers over the stage list in Config/Story.
local Story = require(script.Parent.Parent.Config.Story)

local StoryRules = {}

local indexOf: { [string]: number } = {}
for i, id in Story.Stages do
	indexOf[id] = i
end

function StoryRules.index(stage: string): number?
	return indexOf[stage]
end

function StoryRules.isValid(stage: any): boolean
	return type(stage) == "string" and indexOf[stage] ~= nil
end

function StoryRules.first(): string
	return Story.Stages[1]
end

function StoryRules.nextOf(stage: string): string?
	local i = indexOf[stage]
	return if i then Story.Stages[i + 1] else nil
end

-- true when `stage` is `target` or later
function StoryRules.reached(stage: string, target: string): boolean
	local a, b = indexOf[stage], indexOf[target]
	return a ~= nil and b ~= nil and a >= b
end

-- Free play (switching path, all apps) is open from MissionDone on.
function StoryRules.freePlayOpen(stage: string): boolean
	return StoryRules.reached(stage, "MissionDone")
end

return StoryRules
]======])
put("ReplicatedStorage/MTL/Rules", "TutorialRules", "ModuleScript", [======[--!strict
-- Pure tutorial logic (no Instances; tested in tools/tests/test_tutorial_rules.py). Config: Config/Tutorial.lua.
local TutorialRules = {}

local function indexOf(list: { string }, v: string): number?
	for i, s in list do
		if s == v then
			return i
		end
	end
	return nil
end

-- The step to show now: (index, step) or nil.
--   steps = Config/Tutorial.Steps, doneCount = Settings.Tutorial (0..#steps or Skipped), stage = the story stage,
--   order = Config/Story.Stages. Steps whose stages are all behind the player are passed over (count as done);
--   a step whose stages are still ahead waits (nil).
function TutorialRules.current(steps: { any }, doneCount: number?, stage: string?, order: { string }): (number?, any?)
	local done = doneCount or 0
	if done >= #steps or stage == nil then
		return nil, nil
	end
	local here = indexOf(order, stage)
	if not here then
		return nil, nil
	end
	for i = done + 1, #steps do
		local step = steps[i]
		local last = 0
		local first = math.huge
		for _, s in step.stages or {} do
			local k = indexOf(order, s)
			if k then
				last = math.max(last, k)
				first = math.min(first, k)
			end
		end
		if indexOf(step.stages or {}, stage) then
			return i, step
		elseif here < first then
			return nil, nil -- not there yet: wait
		end
		-- here > last: this step's moment has passed, look at the next one
	end
	return nil, nil
end

-- How many steps count as done once the story is at `stage` (used to save progress when steps are passed over).
function TutorialRules.passed(steps: { any }, doneCount: number?, stage: string?, order: { string }): number
	local done = doneCount or 0
	if done >= #steps then
		return done
	end
	local i = TutorialRules.current(steps, done, stage, order)
	if i then
		return i - 1
	end
	-- nothing to show: either waiting for a later stage, or everything has passed
	local here = stage and indexOf(order, stage) or 0
	local n = done
	for k = done + 1, #steps do
		local first = math.huge
		for _, s in steps[k].stages or {} do
			first = math.min(first, indexOf(order, s) or math.huge)
		end
		if (here :: number) < first then
			break
		end
		n = k
	end
	return n
end

-- The text for the player's device: body may be a string or { kb, touch, pad }.
function TutorialRules.text(value: any, device: string): string
	if type(value) == "string" then
		return value
	elseif type(value) == "table" then
		return value[device] or value.kb or ""
	end
	return ""
end

-- Key chips for the device (touch shows none unless the step lists some).
function TutorialRules.keys(step: any, device: string): { string }
	local keys = step.keys
	if type(keys) ~= "table" then
		return {}
	end
	return keys[device] or {}
end

function TutorialRules.finished(steps: { any }, doneCount: number?): boolean
	return (doneCount or 0) >= #steps
end

return TutorialRules
]======])
put("ReplicatedStorage/MTL/UI", "LowPoly", "ModuleScript", [======[--!strict
-- The shared low-poly UI look (tokens in Theme.LowPoly). Flat colour bands at an angle instead of smooth
-- gradients, a bold dark outline, small hard corners. Works on any GuiObject with a background.
--   LowPoly.style(frame, color, { outline = 3?, corner = UDim?, rim = true? })   -- all of the below in one go
--   LowPoly.facets(color) -> UIGradient   (set the frame's BackgroundColor3 to white; the gradient carries the colour)
--   LowPoly.outline(thickness?, color?) -> UIStroke
local Theme = require(script.Parent.Theme)

local L = (Theme :: any).LowPoly

local LowPoly = {}

local WHITE = Color3.new(1, 1, 1)
local BLACK = Color3.new(0, 0, 0)

-- three flat bands: light / base / dark, hard edges between them
function LowPoly.facets(color: Color3, angle: number?): UIGradient
	local a, b = L.FacetSplits[1], L.FacetSplits[2]
	local light = color:Lerp(WHITE, L.FacetLight)
	local dark = color:Lerp(BLACK, L.FacetDark)
	local g = Instance.new("UIGradient")
	g.Name = "Facets"
	g.Rotation = angle or L.FacetAngle
	g.Color = ColorSequence.new({
		ColorSequenceKeypoint.new(0, light),
		ColorSequenceKeypoint.new(a, light),
		ColorSequenceKeypoint.new(a + 0.001, color),
		ColorSequenceKeypoint.new(b, color),
		ColorSequenceKeypoint.new(b + 0.001, dark),
		ColorSequenceKeypoint.new(1, dark),
	})
	return g
end

function LowPoly.outline(thickness: number?, color: Color3?): UIStroke
	local s = Instance.new("UIStroke")
	s.Name = "Stroke"
	s.Color = color or L.Outline
	s.Thickness = thickness or L.OutlineThickness
	s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	s.LineJoinMode = Enum.LineJoinMode.Miter -- square joins read as cut edges
	return s
end

-- thin light line along the top edge (the "lit" bevel)
function LowPoly.rim(parent: GuiObject)
	local r = Instance.new("Frame")
	r.Name = "Rim"
	r.AnchorPoint = Vector2.new(0.5, 0)
	r.Position = UDim2.new(0.5, 0, 0, 2)
	r.Size = UDim2.new(1, -10, 0, 2)
	r.BorderSizePixel = 0
	r.BackgroundColor3 = L.Rim
	r.BackgroundTransparency = L.RimTransparency
	r.ZIndex = parent.ZIndex
	r.Parent = parent
end

function LowPoly.style(frame: GuiObject, color: Color3, opts: { outline: number?, corner: UDim?, rim: boolean?, angle: number? }?)
	local o = opts or {}
	-- a UIGradient tints a button's own text too, so move the text into a child label first
	if (frame:IsA("TextButton") or frame:IsA("TextLabel")) and (frame :: any).Text ~= "" then
		local src = frame :: any
		local label = Instance.new("TextLabel")
		label.Name = "Text"
		label.Size = UDim2.fromScale(1, 1)
		label.BackgroundTransparency = 1
		label.FontFace = src.FontFace
		label.Text = src.Text
		label.TextColor3 = src.TextColor3
		label.TextSize = src.TextSize
		label.TextScaled = src.TextScaled
		label.ZIndex = src.ZIndex + 1
		for _, c in frame:GetChildren() do
			if c:IsA("UIStroke") and c.ApplyStrokeMode == Enum.ApplyStrokeMode.Contextual then
				c.Parent = label -- the text outline goes with the text
			end
		end
		src.Text = ""
		label.Parent = frame
	end
	for _, c in frame:GetChildren() do
		if c:IsA("UIGradient") or c:IsA("UIStroke") or c:IsA("UICorner") then
			c:Destroy()
		end
	end
	frame.BackgroundColor3 = WHITE
	LowPoly.facets(color, o.angle).Parent = frame
	if (o.outline or 1) > 0 then
		LowPoly.outline(o.outline).Parent = frame
	end
	local corner = Instance.new("UICorner")
	corner.CornerRadius = o.corner or L.Corner
	corner.Parent = frame
	if o.rim ~= false then
		LowPoly.rim(frame)
	end
end

return LowPoly
]======])
put("ReplicatedStorage/MTL/UI", "Motion", "ModuleScript", [======[--!strict
-- One place for UI timing so every panel moves the same way.
local TweenService = game:GetService("TweenService")

local Motion = {}

Motion.Fast = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
Motion.Normal = TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
Motion.Slow = TweenInfo.new(0.45, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
Motion.Spring = TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out) -- phone rise, pops
Motion.Bar = TweenInfo.new(0.5, Enum.EasingStyle.Quart, Enum.EasingDirection.Out) -- XP bar fill
Motion.AppIn = TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out) -- phone apps opening

function Motion.tween(inst: Instance, info: TweenInfo, props: { [string]: any }): Tween
	local t = TweenService:Create(inst, info, props)
	t:Play()
	return t
end

-- Counts a TextLabel from one number to another (cash ticking up). `format` turns a number into text.
function Motion.count(label: TextLabel, from: number, to: number, duration: number, format: (number) -> string)
	local start = os.clock()
	local token = {}
	label:SetAttribute("MTL_CountToken", tostring(token))
	task.spawn(function()
		while true do
			if label:GetAttribute("MTL_CountToken") ~= tostring(token) then
				return -- a newer count took over
			end
			local a = math.clamp((os.clock() - start) / duration, 0, 1)
			local eased = 1 - (1 - a) ^ 3
			label.Text = format(from + (to - from) * eased)
			if a >= 1 then
				return
			end
			task.wait()
		end
	end)
end

return Motion
]======])
put("ReplicatedStorage/MTL/UI", "Sfx", "ModuleScript", [======[--!strict
-- UI sound player for the whole game (phone, HUD, menus). Sounds are named; ids live in Theme.Sfx so a reskin
-- swaps them in one place. Client only.
--   Sfx.play("Tap")                         one-shot (small random pitch so repeats don't sound copy-pasted)
--   Sfx.play("Type", { volume = 0.3 })      per-call overrides: volume, pitch, jitter
--   local h = Sfx.loop("Ring")  h:Stop()    looping sound (ringtone)
--   Sfx.setMuted(true)                      Settings > Sound effects
-- Theme.Sfx[name] = { id = "rbxassetid://...", volume = 0.5, pitch = 1, jitter = 0.04 }  ("" id = silent)
local ContentProvider = game:GetService("ContentProvider")
local SoundService = game:GetService("SoundService")

local Theme = require(script.Parent.Theme)

local Sfx = {}

local library: { [string]: any } = (Theme :: any).Sfx or {}
local muted = false
local folder: Folder? = nil
local pool: { [string]: { Sound } } = {}
local POOL_SIZE = 4

local function getFolder(): Folder
	if folder and folder.Parent then
		return folder
	end
	local f = SoundService:FindFirstChild("MTL_Sfx") :: Folder?
	if not f then
		local nf = Instance.new("Folder")
		nf.Name = "MTL_Sfx"
		nf.Parent = SoundService
		f = nf
	end
	folder = f
	return f :: Folder
end

local function spec(name: string): any?
	local s = library[name]
	if type(s) == "string" then
		s = { id = s }
	end
	if type(s) ~= "table" or type(s.id) ~= "string" or s.id == "" or s.id == "rbxassetid://0" then
		return nil
	end
	return s
end

-- a free Sound for `name` (reuses a small pool, so rapid taps overlap without making new instances)
local function take(name: string, s: any): Sound
	local list = pool[name]
	if not list then
		list = {}
		pool[name] = list
	end
	for _, snd in list do
		if not snd.IsPlaying then
			return snd
		end
	end
	if #list >= POOL_SIZE then
		local oldest = table.remove(list, 1) :: Sound
		oldest:Stop()
		table.insert(list, oldest)
		return oldest
	end
	local snd = Instance.new("Sound")
	snd.Name = name
	snd.SoundId = s.id
	snd.Parent = getFolder()
	table.insert(list, snd)
	return snd
end

function Sfx.has(name: string): boolean
	return spec(name) ~= nil
end

function Sfx.play(name: string, opts: { volume: number?, pitch: number?, jitter: number? }?): Sound?
	if muted then
		return nil
	end
	local s = spec(name)
	if not s then
		return nil
	end
	local o = opts or {}
	local snd = take(name, s)
	local jitter = o.jitter or s.jitter or 0.03
	snd.Volume = o.volume or s.volume or 0.5
	snd.PlaybackSpeed = (o.pitch or s.pitch or 1) * (1 + (math.random() * 2 - 1) * jitter)
	snd.TimePosition = s.start or 0
	snd:Play()
	return snd
end

export type LoopHandle = { Stop: (LoopHandle) -> () }

-- Looping sound. Returns a handle with :Stop() (safe to call when muted: it just does nothing).
function Sfx.loop(name: string, opts: { volume: number? }?): LoopHandle
	local s = spec(name)
	if muted or not s then
		return { Stop = function() end }
	end
	local snd = Instance.new("Sound")
	snd.Name = name .. "_Loop"
	snd.SoundId = s.id
	snd.Looped = true
	snd.Volume = (opts and opts.volume) or s.volume or 0.5
	snd.PlaybackSpeed = s.pitch or 1
	snd.Parent = getFolder()
	snd:Play()
	return {
		Stop = function()
			snd:Stop()
			snd:Destroy()
		end,
	}
end

function Sfx.setMuted(m: boolean)
	muted = m
	if m then
		for _, list in pool do
			for _, snd in list do
				snd:Stop()
			end
		end
	end
end

-- Loads every sound up front so the first tap isn't silent. Call once from a client controller.
function Sfx.preload()
	task.spawn(function()
		local list = {}
		for name in library do
			local s = spec(name)
			if s then
				local snd = take(name, s)
				table.insert(list, snd)
			end
		end
		pcall(function()
			ContentProvider:PreloadAsync(list)
		end)
	end)
end

return Sfx
]======])
