put("ReplicatedStorage/MTL/UI", "UIKit", "ModuleScript", [======[--!strict
-- Themeable widgets for code-built screens (phone apps first; any menu can use them).
-- Everything reads colours/fonts from Theme, so a reskin of Theme reskins every app.
-- Widgets are named (Header, Row, Button, Toggle...) so controllers and Alex can find them.
local Theme = require(script.Parent.Theme)
local Motion = require(script.Parent.Motion)

local C = Theme.Colors
local P = Theme.Phone

local UIKit = {}

function UIKit.new(className: string, props: { [string]: any }?, children: { Instance }?): any
	local inst = Instance.new(className)
	for k, v in props or {} do
		if k ~= "Parent" then
			(inst :: any)[k] = v
		end
	end
	for _, child in children or {} do
		child.Parent = inst
	end
	if props and props.Parent then
		inst.Parent = props.Parent
	end
	return inst
end
local new = UIKit.new

function UIKit.corner(r: UDim?): UICorner
	return new("UICorner", { CornerRadius = r or Theme.Corner })
end

function UIKit.stroke(transparency: number?, color: Color3?): UIStroke
	return new("UIStroke", {
		Color = color or C.Stroke,
		Transparency = transparency or C.StrokeTransparency,
		Thickness = 1,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
	})
end

function UIKit.padding(all: number, top: number?, bottom: number?): UIPadding
	return new("UIPadding", {
		PaddingLeft = UDim.new(0, all),
		PaddingRight = UDim.new(0, all),
		PaddingTop = UDim.new(0, top or all),
		PaddingBottom = UDim.new(0, bottom or top or all),
	})
end

function UIKit.list(gap: number?, horizontal: boolean?): UIListLayout
	return new("UIListLayout", {
		FillDirection = if horizontal then Enum.FillDirection.Horizontal else Enum.FillDirection.Vertical,
		Padding = UDim.new(0, gap or 6),
		SortOrder = Enum.SortOrder.LayoutOrder,
	})
end

-- Small press feedback for any button: darken on hover, shrink a touch on press.
function UIKit.feedback(button: GuiButton, base: Color3, hover: Color3?)
	local scale = button:FindFirstChildOfClass("UIScale") or new("UIScale", { Parent = button })
	button.MouseEnter:Connect(function()
		Motion.tween(button, Motion.Fast, { BackgroundColor3 = hover or base:Lerp(Color3.new(1, 1, 1), 0.08) })
	end)
	button.MouseLeave:Connect(function()
		Motion.tween(button, Motion.Fast, { BackgroundColor3 = base })
		Motion.tween(scale, Motion.Fast, { Scale = 1 })
	end)
	button.MouseButton1Down:Connect(function()
		Motion.tween(scale, Motion.Fast, { Scale = 0.97 })
	end)
	button.MouseButton1Up:Connect(function()
		Motion.tween(scale, Motion.Fast, { Scale = 1 })
	end)
end

export type LabelOpts = { size: number?, dim: boolean?, bold: boolean?, wrap: boolean?, color: Color3?, align: Enum.TextXAlignment?, order: number?, name: string? }

function UIKit.label(parent: Instance, text: string, o: LabelOpts?): TextLabel
	local opts: LabelOpts = o or {}
	local size = opts.size or 14
	return new("TextLabel", {
		Name = opts.name or "Label",
		LayoutOrder = opts.order or 0,
		Size = UDim2.new(1, 0, 0, size + 6),
		AutomaticSize = if opts.wrap then Enum.AutomaticSize.Y else Enum.AutomaticSize.None,
		BackgroundTransparency = 1,
		FontFace = if opts.bold then Theme.Fonts.Bold else Theme.Fonts.Body,
		Text = text,
		TextColor3 = opts.color or (if opts.dim then C.TextDim else C.Text),
		TextSize = size,
		TextWrapped = opts.wrap == true,
		TextTruncate = if opts.wrap then Enum.TextTruncate.None else Enum.TextTruncate.AtEnd,
		TextXAlignment = opts.align or Enum.TextXAlignment.Left,
		Parent = parent,
	})
end

-- App header: [< Back]  Title  [right slot]. onBack nil = no back button.
function UIKit.header(parent: Instance, title: string, onBack: (() -> ())?): Frame
	local header = new("Frame", {
		Name = "Header",
		Size = UDim2.new(1, 0, 0, 44),
		BackgroundTransparency = 1,
		Parent = parent,
	})
	new("TextLabel", {
		Name = "Title",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.new(1, -120, 1, 0),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Bold,
		Text = title,
		TextColor3 = C.Text,
		TextSize = 18,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = header,
	})
	if onBack then
		local back = new("TextButton", {
			Name = "Back",
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, 4, 0.5, 0),
			Size = UDim2.fromOffset(64, 32),
			BackgroundTransparency = 1,
			FontFace = Theme.Fonts.Bold,
			Text = "‹ Back",
			TextColor3 = C.Accent,
			TextSize = 15,
			TextXAlignment = Enum.TextXAlignment.Left,
			Parent = header,
		})
		back.Activated:Connect(onBack)
	end
	new("Frame", {
		Name = "Right",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -4, 0.5, 0),
		Size = UDim2.fromOffset(64, 32),
		BackgroundTransparency = 1,
		Parent = header,
	})
	return header
end

-- Vertical scroll list that fills `parent` below an optional header (top px).
function UIKit.scroll(parent: Instance, top: number?, name: string?): ScrollingFrame
	local sf = new("ScrollingFrame", {
		Name = name or "List",
		Position = UDim2.fromOffset(0, top or 0),
		Size = UDim2.new(1, 0, 1, -(top or 0)),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		ScrollBarThickness = 3,
		ScrollBarImageColor3 = C.TextDim,
		Parent = parent,
	}, { UIKit.list(6), UIKit.padding(10, 4, 16) })
	return sf
end

export type RowOpts = {
	title: string,
	sub: string?,
	right: string?,
	rightColor: Color3?,
	dot: Color3?, -- small dot on the left (unread, missed)
	glyph: string?, -- avatar letter
	glyphColor: Color3?,
	order: number?,
	onClick: (() -> ())?,
	name: string?,
}

-- A tappable list row: (avatar) Title / sub ............ right
function UIKit.row(parent: Instance, o: RowOpts): TextButton
	local row = new("TextButton", {
		Name = o.name or "Row",
		LayoutOrder = o.order or 0,
		Size = UDim2.new(1, 0, 0, if o.sub then 56 else 44),
		BackgroundColor3 = P.Card,
		AutoButtonColor = false,
		Text = "",
		Parent = parent,
	}, { UIKit.corner(Theme.CornerSmall) })
	local left = 12
	if o.dot then
		new("Frame", {
			Name = "Dot",
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, 6, 0.5, 0),
			Size = UDim2.fromOffset(7, 7),
			BackgroundColor3 = o.dot,
			Parent = row,
		}, { UIKit.corner(UDim.new(1, 0)) })
		left = 18
	end
	if o.glyph then
		local av = new("TextLabel", {
			Name = "Avatar",
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, left, 0.5, 0),
			Size = UDim2.fromOffset(34, 34),
			BackgroundColor3 = o.glyphColor or C.AccentAlt,
			FontFace = Theme.Fonts.Bold,
			Text = o.glyph,
			TextColor3 = C.Text,
			TextSize = 16,
			Parent = row,
		}, { UIKit.corner(UDim.new(1, 0)) })
		left += av.Size.X.Offset + 10
	end
	local rightW = if o.right then 70 else 0
	new("TextLabel", {
		Name = "Title",
		Position = UDim2.fromOffset(left, if o.sub then 9 else 0),
		Size = UDim2.new(1, -(left + rightW + 10), 0, if o.sub then 20 else 44),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Bold,
		Text = o.title,
		TextColor3 = C.Text,
		TextSize = 15,
		TextTruncate = Enum.TextTruncate.AtEnd,
		TextXAlignment = Enum.TextXAlignment.Left,
		Parent = row,
	})
	if o.sub then
		new("TextLabel", {
			Name = "Sub",
			Position = UDim2.fromOffset(left, 29),
			Size = UDim2.new(1, -(left + rightW + 10), 0, 18),
			BackgroundTransparency = 1,
			FontFace = Theme.Fonts.Body,
			Text = o.sub,
			TextColor3 = C.TextDim,
			TextSize = 13,
			TextTruncate = Enum.TextTruncate.AtEnd,
			TextXAlignment = Enum.TextXAlignment.Left,
			Parent = row,
		})
	end
	if o.right then
		new("TextLabel", {
			Name = "Right",
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -10, 0.5, 0),
			Size = UDim2.fromOffset(rightW, 20),
			BackgroundTransparency = 1,
			FontFace = Theme.Fonts.Body,
			Text = o.right,
			TextColor3 = o.rightColor or C.TextDim,
			TextSize = 13,
			TextXAlignment = Enum.TextXAlignment.Right,
			Parent = row,
		})
	end
	UIKit.feedback(row, P.Card, P.CardHover)
	if o.onClick then
		row.Activated:Connect(o.onClick)
	end
	return row
end

export type ButtonOpts = { style: string?, order: number?, height: number?, onClick: (() -> ())?, name: string?, disabled: boolean? }

-- Full-width button. style: "primary" (accent), "secondary" (card), "danger".
function UIKit.button(parent: Instance, text: string, o: ButtonOpts?): TextButton
	local opts: ButtonOpts = o or {}
	local style = opts.style or "primary"
	local bg = if style == "primary" then C.Accent elseif style == "danger" then C.Danger else P.Card
	local fg = if style == "primary" then C.Glass else C.Text
	local btn = new("TextButton", {
		Name = opts.name or "Button",
		LayoutOrder = opts.order or 0,
		Size = UDim2.new(1, 0, 0, opts.height or 42),
		BackgroundColor3 = bg,
		AutoButtonColor = false,
		FontFace = Theme.Fonts.Bold,
		Text = text,
		TextColor3 = fg,
		TextSize = 15,
		Parent = parent,
	}, { UIKit.corner(Theme.CornerSmall) })
	if opts.disabled then
		btn.BackgroundTransparency = 0.6
		btn.TextTransparency = 0.4
		btn.Active = false
		btn.AutoButtonColor = false
	else
		UIKit.feedback(btn, bg)
		if opts.onClick then
			btn.Activated:Connect(opts.onClick)
		end
	end
	return btn
end

-- Label + switch. onChange(newValue) is called on tap; call `set(value)` on the returned table to update it.
function UIKit.toggle(parent: Instance, text: string, value: boolean, onChange: (boolean) -> (), order: number?)
	local row = new("TextButton", {
		Name = "Toggle",
		LayoutOrder = order or 0,
		Size = UDim2.new(1, 0, 0, 44),
		BackgroundColor3 = P.Card,
		AutoButtonColor = false,
		Text = "",
		Parent = parent,
	}, { UIKit.corner(Theme.CornerSmall) })
	new("TextLabel", {
		Name = "Title",
		Position = UDim2.fromOffset(12, 0),
		Size = UDim2.new(1, -80, 1, 0),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Bold,
		Text = text,
		TextColor3 = C.Text,
		TextSize = 15,
		TextXAlignment = Enum.TextXAlignment.Left,
		Parent = row,
	})
	local track = new("Frame", {
		Name = "Track",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -12, 0.5, 0),
		Size = UDim2.fromOffset(44, 24),
		BackgroundColor3 = C.TextDim,
		Parent = row,
	}, { UIKit.corner(UDim.new(1, 0)) })
	local knob = new("Frame", {
		Name = "Knob",
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 2, 0.5, 0),
		Size = UDim2.fromOffset(20, 20),
		BackgroundColor3 = C.Text,
		Parent = track,
	}, { UIKit.corner(UDim.new(1, 0)) })
	local state = value
	local api = {}
	function api.set(v: boolean)
		state = v
		Motion.tween(track, Motion.Fast, { BackgroundColor3 = if v then C.Accent else C.TextDim })
		Motion.tween(knob, Motion.Fast, { Position = if v then UDim2.new(1, -22, 0.5, 0) else UDim2.new(0, 2, 0.5, 0) })
	end
	api.instance = row
	api.set(value)
	row.Activated:Connect(function()
		api.set(not state)
		onChange(state)
	end)
	return api
end

function UIKit.section(parent: Instance, text: string, order: number?): TextLabel
	local l = UIKit.label(parent, string.upper(text), { size = 12, dim = true, bold = true, order = order, name = "Section" })
	l.Size = UDim2.new(1, 0, 0, 26)
	l.TextYAlignment = Enum.TextYAlignment.Bottom
	return l
end

-- Centered grey text for empty lists.
function UIKit.empty(parent: Instance, text: string, order: number?): TextLabel
	local l = UIKit.label(parent, text, { dim = true, wrap = true, align = Enum.TextXAlignment.Center, order = order, name = "Empty" })
	l.Size = UDim2.new(1, 0, 0, 60)
	l.TextYAlignment = Enum.TextYAlignment.Center
	return l
end

-- A card frame with padding and a vertical list inside (for job cards, info blocks).
function UIKit.card(parent: Instance, order: number?, name: string?): Frame
	return new("Frame", {
		Name = name or "Card",
		LayoutOrder = order or 0,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = P.Card,
		Parent = parent,
	}, { UIKit.corner(Theme.Corner), UIKit.padding(12), UIKit.list(4) })
end

-- Red count bubble at the top-right of `parent`. n <= 0 hides it. Returns the label.
function UIKit.badge(parent: Instance, n: number): TextLabel
	local b = parent:FindFirstChild("Badge") :: TextLabel?
	if not b then
		b = new("TextLabel", {
			Name = "Badge",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(1, -4, 0, 4),
			Size = UDim2.fromOffset(20, 20),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundColor3 = P.Badge,
			FontFace = Theme.Fonts.Bold,
			TextColor3 = C.Text,
			TextSize = 12,
			ZIndex = 5,
			Parent = parent,
		}, { UIKit.corner(UDim.new(1, 0)), new("UIPadding", { PaddingLeft = UDim.new(0, 5), PaddingRight = UDim.new(0, 5) }) })
	end
	assert(b)
	b.Visible = n > 0
	b.Text = if n > 99 then "99+" else tostring(n)
	return b
end

return UIKit
]======])
put("ReplicatedStorage/MTL/UI/Build", "Cutscene", "ModuleScript", [======[--!strict
-- Builds the MTL_Cutscene ScreenGui (Piece 3): letterbox bars, subtitles, title card, fade, skip hint.
-- Used two ways, same as HUD/Phone/Job:
--   1. Edit time: tools/Install.lua saves it into StarterGui as real instances (Alex reskins it there)
--   2. Runtime fallback: CutsceneController builds it only if PlayerGui has no MTL_Cutscene
-- CutsceneController finds things BY NAME. Keep these names when reskinning:
--   Fade, BarTop, BarBottom, Subtitle/Speaker, Subtitle/Line, Title/Main, Title/Rule, Title/Sub,
--   Skip/Hint, Skip/Bar/Fill, Tap
local Theme = require(script.Parent.Parent.Theme)

local C = Theme.Colors
local K = Theme.Cutscene

local function new(className: string, props: { [string]: any }, children: { Instance }?): any
	local inst = Instance.new(className)
	for k, v in props do
		if k ~= "Parent" then
			(inst :: any)[k] = v
		end
	end
	for _, child in children or {} do
		child.Parent = inst
	end
	if props.Parent then
		inst.Parent = props.Parent
	end
	return inst
end


local Cutscene = {}

function Cutscene.build(): ScreenGui
	local gui = new("ScreenGui", {
		Name = "MTL_Cutscene",
		ResetOnSpawn = false,
		IgnoreGuiInset = true,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		DisplayOrder = 50, -- above everything
		Enabled = false,
	})

	-- full-screen catcher for clicks/taps (tap = next line, hold = skip). Under everything else.
	new("TextButton", {
		Name = "Tap",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Text = "",
		AutoButtonColor = false,
		ZIndex = 1,
		Parent = gui,
	})

	new("Frame", {
		Name = "BarTop",
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.fromScale(0, 0), -- slides to (0, BarShare)
		Size = UDim2.fromScale(1, K.BarShare),
		BackgroundColor3 = K.Bar,
		BorderSizePixel = 0,
		ZIndex = 3,
		Parent = gui,
	})
	new("Frame", {
		Name = "BarBottom",
		AnchorPoint = Vector2.new(0, 0),
		Position = UDim2.fromScale(0, 1), -- slides to (0, 1 - BarShare)
		Size = UDim2.fromScale(1, K.BarShare),
		BackgroundColor3 = K.Bar,
		BorderSizePixel = 0,
		ZIndex = 3,
		Parent = gui,
	})

	-- subtitles live INSIDE the bottom letterbox bar, like film: white on black, no outline needed, never over the
	-- picture. Speaker name small and coloured on top, the line under it. Sizes scale with the bar (phones too).
	local sub = new("Frame", {
		Name = "Subtitle",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 1 - K.BarShare / 2),
		Size = UDim2.fromScale(0.62, K.BarShare * 0.86),
		BackgroundTransparency = 1,
		ZIndex = 4,
		Parent = gui,
	}, { new("UISizeConstraint", { MaxSize = Vector2.new(980, 140) }) })
	new("TextLabel", {
		Name = "Speaker",
		Size = UDim2.fromScale(1, 0.3),
		BackgroundTransparency = 1,
		FontFace = Font.new("rbxasset://fonts/families/Montserrat.json", Enum.FontWeight.Bold),
		Text = "",
		TextColor3 = K.SpeakerDefault,
		TextScaled = true,
		ZIndex = 4,
		Parent = sub,
	}, { new("UITextSizeConstraint", { MaxTextSize = 15, MinTextSize = 9 }) })
	new("TextLabel", {
		Name = "Line",
		Position = UDim2.fromScale(0, 0.34),
		Size = UDim2.fromScale(1, 0.66),
		BackgroundTransparency = 1,
		FontFace = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Medium),
		Text = "",
		TextColor3 = K.SubtitleText,
		TextScaled = true,
		TextWrapped = true,
		TextYAlignment = Enum.TextYAlignment.Top,
		LineHeight = 1.05,
		ZIndex = 4,
		Parent = sub,
	}, { new("UITextSizeConstraint", { MaxTextSize = 23, MinTextSize = 11 }) })

	-- chapter title card: a heavy wide title, a thin gold rule, a quiet subtitle (on black or over the picture)
	local title = new("Frame", {
		Name = "Title",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.47),
		Size = UDim2.new(0.8, 0, 0, 120),
		BackgroundTransparency = 1,
		Visible = false,
		ZIndex = 6,
		Parent = gui,
	}, { new("UISizeConstraint", { MaxSize = Vector2.new(900, 120) }) })
	new("TextLabel", {
		Name = "Main",
		Size = UDim2.new(1, 0, 0, 66),
		BackgroundTransparency = 1,
		FontFace = Font.new("rbxasset://fonts/families/Montserrat.json", Enum.FontWeight.Heavy),
		Text = "",
		TextColor3 = K.TitleColor,
		TextScaled = true,
		ZIndex = 6,
		Parent = title,
	}, {
		new("UITextSizeConstraint", { MaxTextSize = 60, MinTextSize = 24 }),
		new("UIStroke", { Color = K.SubtitleShadow, Transparency = 0.7, Thickness = 1.5 }),
	})
	new("Frame", {
		Name = "Rule",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 74),
		Size = UDim2.fromOffset(64, 2),
		BackgroundColor3 = K.TitleSub,
		BorderSizePixel = 0,
		ZIndex = 6,
		Parent = title,
	})
	new("TextLabel", {
		Name = "Sub",
		Position = UDim2.fromOffset(0, 84),
		Size = UDim2.new(1, 0, 0, 24),
		BackgroundTransparency = 1,
		FontFace = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Medium),
		Text = "",
		TextColor3 = K.TitleSub,
		TextSize = 19,
		ZIndex = 6,
		Parent = title,
	}, { new("UIStroke", { Color = K.SubtitleShadow, Transparency = 0.75, Thickness = 1 }) })

	-- fade to/from black (between the bars and the title card)
	new("Frame", {
		Name = "Fade",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = K.Fade,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		ZIndex = 5,
		Parent = gui,
	})

	-- skip hint: bottom right, inside the bottom bar
	local skip = new("Frame", {
		Name = "Skip",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -24, 1 - K.BarShare / 2, 0),
		Size = UDim2.fromOffset(190, 30),
		BackgroundTransparency = 1,
		Visible = false,
		ZIndex = 7,
		Parent = gui,
	})
	new("TextLabel", {
		Name = "Hint",
		Size = UDim2.new(1, 0, 0, 18),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Bold,
		Text = "Hold SPACE to skip",
		TextColor3 = C.TextDim,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Right,
		ZIndex = 7,
		Parent = skip,
	})
	local bar = new("Frame", {
		Name = "Bar",
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, 0, 0, 22),
		Size = UDim2.new(0.6, 0, 0, 3),
		BackgroundColor3 = C.TextDim,
		BackgroundTransparency = 0.6,
		BorderSizePixel = 0,
		ZIndex = 7,
		Parent = skip,
	}, { new("UICorner", { CornerRadius = UDim.new(1, 0) }) })
	new("Frame", {
		Name = "Fill",
		Size = UDim2.fromScale(0, 1),
		BackgroundColor3 = K.SkipFill,
		BorderSizePixel = 0,
		ZIndex = 7,
		Parent = bar,
	}, { new("UICorner", { CornerRadius = UDim.new(1, 0) }) })

	return gui
end

return Cutscene
]======])
put("ReplicatedStorage/MTL/UI/Build", "Gun", "ModuleScript", [======[--!strict
-- Builds the MTL_Gun ScreenGui (Piece 5): crosshair, hitmarker, ammo panel, weapon bar, touch buttons and the
-- hurt vignette. Used two ways, same as HUD/Phone/Job:
--   1. Edit time: tools/Install.lua saves it into StarterGui as real instances (Alex reskins it there)
--   2. Runtime fallback: GunController builds it only if PlayerGui has no MTL_Gun
-- GunController finds things BY NAME. Keep these names when reskinning:
--   Crosshair/{Top, Bottom, Left, Right, Dot}   Hint
--   Hitmarker/{A, B, C, D}
--   Ammo/{Gun, Mag, Reserve, Reload/Fill, Help}
--   WeaponBar/{SlotTemplate/{Key, Title, Count}}   (slots are clones named Slot_<GunId>)
--   Touch/{Fire, Aim, Reload}
--   Hurt/{Left, Right, Top, Bottom}
-- IgnoreGuiInset = true so the crosshair sits exactly on the camera's centre ray.
local Theme = require(script.Parent.Parent.Theme)

local C = Theme.Colors
local G = Theme.Gun

local function new(className: string, props: { [string]: any }, children: { Instance }?): any
	local inst = Instance.new(className)
	for k, v in props do
		if k ~= "Parent" then
			(inst :: any)[k] = v
		end
	end
	for _, child in children or {} do
		child.Parent = inst
	end
	if props.Parent then
		inst.Parent = props.Parent
	end
	return inst
end

local function corner(r: UDim?)
	return new("UICorner", { CornerRadius = r or Theme.Corner })
end

local function stroke(t: number?)
	return new("UIStroke", { Color = C.Stroke, Transparency = t or C.StrokeTransparency, Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border })
end

local function bar(name: string, size: UDim2, parent: Instance, color: Color3?): Frame
	return new("Frame", {
		Name = name,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Size = size,
		BackgroundColor3 = color or G.Crosshair,
		BorderSizePixel = 0,
		Parent = parent,
	}, { new("UIStroke", { Color = G.CrosshairShadow, Transparency = 0.55, Thickness = 1 }) })
end

local function label(name: string, props: { [string]: any }): TextLabel
	local base = {
		Name = name,
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Bold,
		TextColor3 = C.Text,
		TextSize = 14,
		Size = UDim2.new(1, 0, 0, 18),
	}
	for k, v in props do
		base[k] = v
	end
	return new("TextLabel", base)
end

local Build = {}

function Build.build(): ScreenGui
	local gui = new("ScreenGui", {
		Name = "MTL_Gun",
		ResetOnSpawn = false,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		DisplayOrder = 7, -- above HUD (5) and Job (6), below the phone (10)
		IgnoreGuiInset = true,
		Enabled = true,
	})

	-- crosshair: four bars that open with the current spread + a dot
	local cross = new("Frame", {
		Name = "Crosshair",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(0, 0),
		BackgroundTransparency = 1,
		Visible = false,
		Parent = gui,
	})
	bar("Top", UDim2.fromOffset(2, 9), cross)
	bar("Bottom", UDim2.fromOffset(2, 9), cross)
	bar("Left", UDim2.fromOffset(9, 2), cross)
	bar("Right", UDim2.fromOffset(9, 2), cross)
	local dot = bar("Dot", UDim2.fromOffset(3, 3), cross)
	dot.Position = UDim2.fromOffset(0, 0)
	label("Hint", {
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0.5, 34),
		Size = UDim2.fromOffset(260, 20),
		TextSize = 15,
		Text = "",
		TextStrokeTransparency = 0.5,
		Visible = false,
		Parent = gui,
	})

	-- hitmarker: an X of four short bars
	local hm = new("Frame", {
		Name = "Hitmarker",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(28, 28),
		BackgroundTransparency = 1,
		Visible = false,
		Parent = gui,
	})
	for i, name in { "A", "B", "C", "D" } do
		local b = bar(name, UDim2.fromOffset(2, 8), hm, G.Hit)
		local sx = if i == 1 or i == 4 then -1 else 1
		local sy = if i <= 2 then -1 else 1
		b.Position = UDim2.new(0.5, sx * 8, 0.5, sy * 8)
		b.Rotation = if sx * sy > 0 then -45 else 45
	end

	-- ammo panel (left of the phone; GunController moves it next to the phone at runtime)
	local ammo = new("Frame", {
		Name = "Ammo",
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.new(1, -360, 1, -24),
		Size = UDim2.fromOffset(170, 70),
		BackgroundColor3 = G.Panel,
		BackgroundTransparency = C.GlassTransparency,
		Visible = false,
		Parent = gui,
	}, { corner(), stroke() })
	label("Gun", { Position = UDim2.fromOffset(12, 8), Size = UDim2.new(1, -24, 0, 14), TextSize = 12, TextColor3 = C.TextDim, TextXAlignment = Enum.TextXAlignment.Left, Text = "", Parent = ammo })
	label("Mag", {
		Position = UDim2.fromOffset(12, 22),
		Size = UDim2.fromOffset(70, 34),
		FontFace = Theme.Fonts.Mono,
		TextSize = 32,
		TextXAlignment = Enum.TextXAlignment.Left,
		Text = "0",
		Parent = ammo,
	})
	label("Reserve", {
		Position = UDim2.fromOffset(84, 34),
		Size = UDim2.fromOffset(74, 20),
		FontFace = Theme.Fonts.Mono,
		TextSize = 16,
		TextColor3 = C.TextDim,
		TextXAlignment = Enum.TextXAlignment.Left,
		Text = "/ 0",
		Parent = ammo,
	})
	local reload = new("Frame", {
		Name = "Reload",
		Position = UDim2.new(0, 12, 1, -9),
		Size = UDim2.new(1, -24, 0, 3),
		BackgroundColor3 = C.Stroke,
		BackgroundTransparency = 0.85,
		BorderSizePixel = 0,
		Visible = false,
		Parent = ammo,
	}, { corner(UDim.new(1, 0)) })
	new("Frame", { Name = "Fill", Size = UDim2.fromScale(0, 1), BackgroundColor3 = C.Accent, BorderSizePixel = 0, Parent = reload }, { corner(UDim.new(1, 0)) })
	label("Help", {
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, 0, 0, -6),
		Size = UDim2.new(1, 0, 0, 14),
		TextSize = 12,
		TextColor3 = C.TextDim,
		TextXAlignment = Enum.TextXAlignment.Left,
		FontFace = Theme.Fonts.Body,
		TextStrokeTransparency = 0.7,
		Text = "",
		Parent = ammo,
	})

	-- weapon bar: bottom centre, one slot per gun you own
	local wb = new("Frame", {
		Name = "WeaponBar",
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 1, -18),
		Size = UDim2.fromOffset(600, 46),
		BackgroundTransparency = 1,
		Visible = false,
		Parent = gui,
	}, {
		new("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			HorizontalAlignment = Enum.HorizontalAlignment.Center,
			VerticalAlignment = Enum.VerticalAlignment.Bottom,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 6),
		}),
	})
	local slot = new("TextButton", {
		Name = "SlotTemplate",
		Size = UDim2.fromOffset(104, 42),
		BackgroundColor3 = G.Panel,
		BackgroundTransparency = C.GlassTransparency,
		AutoButtonColor = false,
		Text = "",
		Visible = false,
		Parent = wb,
	}, { corner(Theme.CornerSmall), new("UIStroke", { Name = "Stroke", Color = C.Stroke, Transparency = C.StrokeTransparency, Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }) })
	label("Key", { Position = UDim2.fromOffset(6, 4), Size = UDim2.fromOffset(14, 14), TextSize = 11, TextColor3 = C.TextDim, Text = "1", Parent = slot })
	label("Title", { Position = UDim2.fromOffset(22, 4), Size = UDim2.new(1, -28, 0, 16), TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Text = "Gun", Parent = slot })
	label("Count", { Position = UDim2.fromOffset(22, 22), Size = UDim2.new(1, -28, 0, 14), TextSize = 11, FontFace = Theme.Fonts.Mono, TextColor3 = C.TextDim, TextXAlignment = Enum.TextXAlignment.Left, Text = "", Parent = slot })

	-- touch buttons: above the jump button, right thumb
	local touch = new("Frame", {
		Name = "Touch",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Visible = false,
		Parent = gui,
	})
	local function round(name: string, text: string, size: number, pos: UDim2): TextButton
		return new("TextButton", {
			Name = name,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = pos,
			Size = UDim2.fromOffset(size, size),
			BackgroundColor3 = G.Panel,
			BackgroundTransparency = 0.35,
			AutoButtonColor = false,
			FontFace = Theme.Fonts.Display,
			Text = text,
			TextColor3 = C.Text,
			TextSize = math.floor(size * 0.24),
			Parent = touch,
		}, { corner(UDim.new(1, 0)), new("UIStroke", { Color = C.Stroke, Transparency = 0.6, Thickness = 2, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }) })
	end
	round("Fire", "FIRE", 86, UDim2.new(1, -70, 1, -215))
	round("Aim", "AIM", 64, UDim2.new(1, -160, 1, -185))
	round("Reload", "R", 48, UDim2.new(1, -60, 1, -300))

	-- hurt vignette: four soft edges, the one facing the shooter flashes
	local hurt = new("Frame", { Name = "Hurt", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Parent = gui })
	local function edge(name: string, size: UDim2, pos: UDim2, anchor: Vector2, rotation: number)
		new("Frame", {
			Name = name,
			AnchorPoint = anchor,
			Position = pos,
			Size = size,
			BackgroundColor3 = G.Hurt,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Parent = hurt,
		}, {
			new("UIGradient", {
				Rotation = rotation,
				Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.1), NumberSequenceKeypoint.new(1, 1) }),
			}),
		})
	end
	edge("Left", UDim2.fromScale(0.22, 1), UDim2.fromScale(0, 0), Vector2.new(0, 0), 0)
	edge("Right", UDim2.fromScale(0.22, 1), UDim2.fromScale(1, 0), Vector2.new(1, 0), 180)
	edge("Top", UDim2.fromScale(1, 0.25), UDim2.fromScale(0, 0), Vector2.new(0, 0), 90)
	edge("Bottom", UDim2.fromScale(1, 0.25), UDim2.fromScale(0, 1), Vector2.new(0, 1), 270)

	return gui
end

return Build
]======])
put("ReplicatedStorage/MTL/UI/Build", "HUD", "ModuleScript", [======[--!strict
-- Builds the MTL_HUD ScreenGui. Used two ways:
--   1. Edit time (Studio command bar / MCP): require(...).build().Parent = game.StarterGui  -> real instances Alex can reskin
--   2. Runtime fallback: HUDController builds it only if PlayerGui has no MTL_HUD (StarterGui copy missing).
-- Controllers find things BY NAME. Keep these names when reskinning:
--   Top/Cash/{Icon, Amount}, Top/Status/{XP, Boosts, Level/{Center/Num}, Health/{Center/Glyph}}   (rings: see HUD.ring)
--   Objective/Dot, Objective/Text, Toasts, Banner/Title, Banner/Sub, Pops
--   Menu/Toggle, Menu/Panel/Collapse, Menu/Panel/Grid/TileTemplate/{Icon, Label}, Panels/Dim + the Store / Emotes popups
--   Hotbar/SlotTemplate/{Disc/Icon, Key, ItemName}
-- Map markers sit in their own ScreenGui (MTL_Markers, built at runtime by MapMarkers with HUD.marker()).
local Theme = require(script.Parent.Parent.Theme)
local LowPoly = require(script.Parent.Parent.LowPoly)

local C = Theme.Colors
local H = Theme.HUD
local L = (Theme :: any).LowPoly
local RGB = Color3.fromRGB
-- low-poly base colours for each kind of panel
local LP = {
	Cash = RGB(44, 168, 64),
	Tile = RGB(40, 42, 50),
	Panel = RGB(22, 23, 29),
	Slot = RGB(58, 60, 68),
	Marker = RGB(26, 27, 33),
}

local function new(className: string, props: { [string]: any }, children: { Instance }?): any
	local inst = Instance.new(className)
	for k, v in props do
		if k ~= "Parent" then
			(inst :: any)[k] = v
		end
	end
	for _, child in children or {} do
		child.Parent = inst
	end
	if props.Parent then
		inst.Parent = props.Parent
	end
	return inst
end

local function corner(r: UDim?)
	return new("UICorner", { CornerRadius = r or Theme.Corner })
end

local function stroke(t: number?)
	return new("UIStroke", { Color = C.Stroke, Transparency = t or C.StrokeTransparency, Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border })
end

-- soft text outline: enough to read over the world, not a cartoon border
local function textStroke(thick: number?)
	return new("UIStroke", { Color = H.LabelStroke, Transparency = if thick then 0.45 else 0.6, Thickness = math.min(thick or 1, 1.5) })
end

local function vgrad(top: Color3, bottom: Color3)
	return new("UIGradient", { Rotation = 90, Color = ColorSequence.new(top, bottom) })
end

-- emoji (or Alex's image when Theme.HUD.Images[key] is set) centred in `parent`
local function icon(parent: Instance, emoji: string, size: number, imageKey: string?): GuiObject
	local img = imageKey and H.Images[imageKey]
	if img and img ~= "" and img ~= "rbxassetid://0" then
		return new("ImageLabel", {
			Name = "Icon",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(size, size),
			BackgroundTransparency = 1,
			Image = img,
			ScaleType = Enum.ScaleType.Fit,
			Parent = parent,
		})
	end
	return new("TextLabel", {
		Name = "Icon",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(size, size),
		BackgroundTransparency = 1,
		Text = emoji,
		TextScaled = true,
		FontFace = Theme.Fonts.Body,
		TextColor3 = C.Text,
		Parent = parent,
	})
end

local HUD = {}
HUD.icon = icon

-- A round progress ring. Progress is drawn by two half-masks, each holding a full circle stroke with a hard
-- transparency step; HUD.setRing() turns the gradients. Children: Track, Right/Arc, Left/Arc, Center.
function HUD.ring(name: string, color: Color3, size: number, thick: number): Frame
	local ring = new("Frame", {
		Name = name,
		Size = UDim2.fromOffset(size, size),
		BackgroundTransparency = 1,
	})
	local inset = UDim2.new(1, -thick * 2, 1, -thick * 2)
	new("Frame", {
		Name = "Track",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = inset,
		BackgroundColor3 = H.Tile,
		BackgroundTransparency = 0.15,
		Parent = ring,
	}, {
		corner(UDim.new(1, 0)),
		new("UIStroke", { Color = H.RingTrack, Transparency = 0.35, Thickness = thick }),
	})
	local step = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 0),
		NumberSequenceKeypoint.new(0.5, 0),
		NumberSequenceKeypoint.new(0.502, 1),
		NumberSequenceKeypoint.new(1, 1),
	})
	for _, side in { "Right", "Left" } do
		local half = new("Frame", {
			Name = side,
			Position = if side == "Right" then UDim2.fromScale(0.5, 0) else UDim2.fromScale(0, 0),
			Size = UDim2.fromScale(0.5, 1),
			BackgroundTransparency = 1,
			ClipsDescendants = true,
			Parent = ring,
		})
		local arc = new("Frame", {
			Name = "Arc",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = if side == "Right" then UDim2.fromScale(0, 0.5) else UDim2.fromScale(1, 0.5),
			Size = UDim2.new(2, -thick * 2, 1, -thick * 2),
			BackgroundTransparency = 1,
			Parent = half,
		}, { corner(UDim.new(1, 0)) })
		new("UIStroke", { Name = "Stroke", Color = color, Thickness = thick, Parent = arc }, {
			new("UIGradient", { Name = "Gradient", Transparency = step, Rotation = 0 }),
		})
	end
	new("Frame", {
		Name = "Center",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.new(1, -thick * 2, 1, -thick * 2),
		BackgroundTransparency = 1,
		Parent = ring,
	})
	return ring
end

-- p = 0..1, clockwise from the top
function HUD.setRing(ring: Instance, p: number, color: Color3?)
	local a = math.clamp(p, 0, 1) * 360
	for _, side in { "Right", "Left" } do
		local half = ring:FindFirstChild(side)
		local arc = half and half:FindFirstChild("Arc")
		local s = arc and arc:FindFirstChild("Stroke") :: UIStroke?
		if s then
			local g = s:FindFirstChild("Gradient") :: UIGradient?
			if g then
				g.Rotation = if side == "Right" then math.clamp(a, 0, 180) else math.clamp(a, 180, 360)
			end
			if color then
				s.Color = color
			end
		end
	end
end

