		FontFace = H.Font,
		Text = "",
		TextColor3 = H.TileActive,
		TextSize = 13,
		Visible = false,
		Parent = slot,
	}, { textStroke(1.5) })

	-- low-poly pass: chunky faceted panels, bold outlines, small hard corners (Theme.LowPoly)
	LowPoly.style(cash, LP.Cash, { corner = UDim.new(0, 10) })
	cash.Inner:FindFirstChildOfClass("UICorner").CornerRadius = UDim.new(0, 6)
	LowPoly.style(objective, LP.Panel, { corner = L.CornerSmall, outline = L.OutlineThin, rim = false })
	objective.BackgroundTransparency = 0.12
	LowPoly.style(toggle, LP.Tile)
	LowPoly.style(panel, LP.Panel, { corner = UDim.new(0, 10) })
	panel.BackgroundTransparency = 0.1
	LowPoly.style(panel.Collapse, LP.Tile, { corner = L.CornerSmall, rim = false })
	LowPoly.style(tile, LP.Tile)
	LowPoly.style(disc, LP.Slot, { corner = UDim.new(0, 10) })
	for _, ring in { level, health } do
		local track = ring.Track
		track:FindFirstChildOfClass("UIStroke").Color = L.Outline
		track:FindFirstChildOfClass("UIStroke").Transparency = 0
	end
	toggle.Key:FindFirstChildOfClass("UICorner").CornerRadius = L.CornerSmall
	toggle.Key:FindFirstChildOfClass("UIStroke").Color = L.Outline

	return gui
end

-- One toast row (built at runtime per message). Reskin by editing this function or Theme.
function HUD.toast(text: string, color: Color3?): Frame
	local row = new("Frame", {
		Name = "Toast",
		Size = UDim2.fromOffset(0, 32),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundColor3 = C.Glass,
		BackgroundTransparency = C.GlassTransparency,
	}, {
		corner(L.CornerSmall),
		LowPoly.outline(L.OutlineThin),
		new("UIPadding", { PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12) }),
	})
	new("Frame", {
		Name = "Accent",
		Position = UDim2.new(0, -12, 0, 0),
		Size = UDim2.new(0, 3, 1, 0),
		BackgroundColor3 = color or C.Accent,
		BorderSizePixel = 0,
		Parent = row,
	})
	new("TextLabel", {
		Name = "Text",
		Size = UDim2.fromScale(0, 1),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Body,
		Text = text,
		TextColor3 = C.Text,
		TextSize = 15,
		Parent = row,
	})
	return row
end

function HUD.pop(text: string, color: Color3): TextLabel
	return new("TextLabel", {
		Name = "Pop",
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, 0, 0, 40),
		Size = UDim2.new(1, 0, 0, 30),
		BackgroundTransparency = 1,
		FontFace = H.CashFont,
		Text = text,
		TextColor3 = color,
		TextSize = 26,
		TextXAlignment = Enum.TextXAlignment.Right,
	}, { textStroke(2) })
end

-- A popup panel (Store, Emotes): title bar with a close button and a scrolling List. Built at runtime.
function HUD.panel(name: string, title: string, width: number, height: number): Frame
	local p = new("Frame", {
		Name = name,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(width, height),
		BackgroundColor3 = C.Glass,
		BackgroundTransparency = 0.08,
		Visible = false,
	}, {
		new("UIScale", { Name = "Pop" }),
	})
	LowPoly.style(p, LP.Panel, { corner = UDim.new(0, 10) })
	new("TextLabel", {
		Name = "Title",
		Position = UDim2.fromOffset(22, 14),
		Size = UDim2.new(1, -70, 0, 34),
		BackgroundTransparency = 1,
		FontFace = H.Font,
		Text = title,
		TextColor3 = C.Text,
		TextSize = 26,
		TextXAlignment = Enum.TextXAlignment.Left,
		Parent = p,
	}, { textStroke(2) })
	new("TextButton", {
		Name = "Close",
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -10, 0, 10),
		Size = UDim2.fromOffset(36, 36),
		BackgroundColor3 = C.Danger,
		AutoButtonColor = true,
		FontFace = H.Font,
		Text = "X",
		TextColor3 = C.Text,
		TextSize = 18,
		Parent = p,
	}, { textStroke(1.5) })
	LowPoly.style(p.Close, C.Danger, { corner = L.CornerSmall, rim = false })
	new("ScrollingFrame", {
		Name = "List",
		Position = UDim2.fromOffset(12, 60),
		Size = UDim2.new(1, -24, 1, -72),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		ScrollBarThickness = 4,
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		CanvasSize = UDim2.new(),
		Parent = p,
	}, {
		new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }),
		new("UIPadding", { PaddingTop = UDim.new(0, 4), PaddingLeft = UDim.new(0, 3), PaddingBottom = UDim.new(0, 6) }),
	})
	return p
end

-- One row in a panel list: icon tile, title + blurb, and a button on the right.
function HUD.panelRow(emoji: string, title: string, blurb: string, buttonText: string, buttonColor: Color3?): Frame
	local row = new("Frame", {
		Name = "Row",
		Size = UDim2.new(1, -6, 0, 64),
		BackgroundColor3 = Color3.new(1, 1, 1),
	})
	LowPoly.style(row, LP.Tile, { outline = L.OutlineThin })
	local ic = new("Frame", { Name = "IconBox", Position = UDim2.fromOffset(8, 8), Size = UDim2.fromOffset(48, 48), BackgroundTransparency = 1, Parent = row })
	icon(ic, emoji, 40)
	new("TextLabel", {
		Name = "Title",
		Position = UDim2.fromOffset(66, 10),
		Size = UDim2.new(1, -170, 0, 22),
		BackgroundTransparency = 1,
		FontFace = H.Font,
		Text = title,
		TextColor3 = C.Text,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = row,
	}, { textStroke(1.2) })
	new("TextLabel", {
		Name = "Blurb",
		Position = UDim2.fromOffset(66, 32),
		Size = UDim2.new(1, -170, 0, 18),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Body,
		Text = blurb,
		TextColor3 = C.TextDim,
		TextSize = 13,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = row,
	})
	new("TextButton", {
		Name = "Button",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -10, 0.5, 0),
		Size = UDim2.fromOffset(88, 38),
		BackgroundColor3 = buttonColor or H.CashTop,
		AutoButtonColor = true,
		FontFace = H.Font,
		Text = buttonText,
		TextColor3 = C.Text,
		TextSize = 15,
		Parent = row,
	}, { textStroke(1.5) })
	LowPoly.style(row.Button, buttonColor or LP.Cash, { corner = L.CornerSmall, outline = L.OutlineThin, rim = false })
	return row
end

-- One map marker: dark disc with the emoji, a name + distance tag under it.
function HUD.marker(emoji: string, name: string, size: number): Frame
	local m = new("Frame", {
		Name = "Marker",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Size = UDim2.fromOffset(size, size),
		BackgroundTransparency = 1,
	}, { new("UIScale", { Name = "Scale" }) })
	local disc = new("Frame", {
		Name = "Disc",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = H.Marker,
		BackgroundTransparency = H.MarkerTransparency,
		Parent = m,
	})
	LowPoly.style(disc, LP.Marker, { corner = UDim.new(0, 8), outline = L.OutlineThin, rim = false })
	disc.BackgroundTransparency = H.MarkerTransparency
	icon(disc, emoji, math.floor(size * 0.58))
	new("TextLabel", {
		Name = "Tag",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 1, 6),
		Size = UDim2.fromOffset(0, 0),
		AutomaticSize = Enum.AutomaticSize.XY,
		BackgroundColor3 = LP.Panel,
		BackgroundTransparency = 0.15,
		FontFace = H.Font,
		RichText = true,
		Text = name,
		TextColor3 = C.Text,
		TextSize = 14,
		Visible = false,
		Parent = m,
	}, {
		corner(L.CornerSmall),
		LowPoly.outline(L.OutlineThin),
		new("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8), PaddingTop = UDim.new(0, 3), PaddingBottom = UDim.new(0, 4) }),
	})
	return m
end

-- A store tab button (Tab_<id>). MenuController restyles the selected one.
function HUD.storeTab(id: string, label: string): TextButton
	local b = new("TextButton", {
		Name = "Tab_" .. id,
		Size = UDim2.fromOffset(170, 40),
		AutoButtonColor = false,
		FontFace = H.Font,
		Text = label,
		TextColor3 = C.Text,
		TextSize = 15,
	}, { textStroke(1.5) })
	LowPoly.style(b, LP.Tile, { corner = L.CornerSmall, outline = L.OutlineThin, rim = false })
	return b
end

-- One big product card: art panel with a huge icon, ribbon, title, blurb and a price button (Card_<item>).
-- Children MenuController uses: Buy (button) / Buy/Text (price label), Owned.
function HUD.storeCard(def: any): Frame
	local card = new("Frame", {
		Name = "Card_" .. def.item,
		Size = UDim2.fromOffset(236, 330),
		BackgroundColor3 = Color3.new(1, 1, 1),
	}, { new("UIScale", { Name = "Pop" }) })
	LowPoly.style(card, LP.Tile)
	local art = new("Frame", {
		Name = "Art",
		Position = UDim2.fromOffset(10, 10),
		Size = UDim2.new(1, -20, 0, 160),
		BackgroundColor3 = Color3.new(1, 1, 1),
		ClipsDescendants = true,
		Parent = card,
	})
	LowPoly.style(art, def.color or LP.Cash, { corner = L.CornerSmall, outline = L.OutlineThin, rim = false, angle = 120 })
	-- soft light behind the icon
	new("Frame", {
		Name = "Glow",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(130, 130),
		BackgroundColor3 = Color3.new(1, 1, 1),
		BackgroundTransparency = 0.82,
		Parent = art,
	}, { corner(UDim.new(1, 0)) })
	local ic = icon(art, def.emoji, 92, "Store_" .. def.item)
	ic.Rotation = -6
	if def.ribbon then
		new("TextLabel", {
			Name = "Ribbon",
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, 4, 0, 14),
			Size = UDim2.fromOffset(0, 24),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundColor3 = C.Gold,
			FontFace = H.Font,
			Text = def.ribbon,
			TextColor3 = Color3.fromRGB(40, 26, 0),
			TextSize = 12,
			ZIndex = 3,
			Parent = card,
		}, {
			corner(L.CornerSmall),
			LowPoly.outline(L.OutlineThin),
			new("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }),
		})
	end
	new("TextLabel", {
		Name = "Title",
		Position = UDim2.fromOffset(16, 182),
		Size = UDim2.new(1, -32, 0, 26),
		BackgroundTransparency = 1,
		FontFace = H.Font,
		Text = def.title,
		TextColor3 = C.Text,
		TextSize = 21,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = card,
	}, { textStroke(1.5) })
	new("TextLabel", {
		Name = "Blurb",
		Position = UDim2.fromOffset(16, 212),
		Size = UDim2.new(1, -32, 0, 44),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Body,
		Text = def.blurb,
		TextColor3 = C.TextDim,
		TextSize = 14,
		LineHeight = 1.1,
		TextWrapped = true,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
		Parent = card,
	})
	local buy = new("TextButton", {
		Name = "Buy",
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 1, -14),
		Size = UDim2.new(1, -28, 0, 48),
		AutoButtonColor = false,
		FontFace = H.CashFont,
		Text = "...",
		TextColor3 = C.Text,
		TextSize = 20,
		Parent = card,
	}, { textStroke(2), new("UIScale", { Name = "Press" }) })
	LowPoly.style(buy, LP.Cash, { corner = L.CornerSmall })
	return card
end

return HUD
