put("ReplicatedStorage/MTL/UI/Build", "Job", "ModuleScript", [======[--!strict
-- Builds the MTL_Job ScreenGui (Piece 2): the job panel, the task minigames, the shift/check-in card and the
-- reward fly-ups. Used two ways, same as HUD/Phone:
--   1. Edit time: tools/Install.lua saves it into StarterGui as real instances (Alex reskins it there)
--   2. Runtime fallback: JobController builds it only if PlayerGui has no MTL_Job
-- JobController finds things BY NAME. Keep these names when reskinning:
--   Panel/Accent, Panel/Body/{JobTitle, Task, Steps, Progress/Fill, ProgressText, Status, Hint, Action}
--   Minigame/{Title, Close, ActionButton, Hold/Bar/Fill, Hold/Percent, Timing/Track/Zone, Timing/Track/Needle,
--             Timing/Pips, Sequence/Ticket, Sequence/Buttons}
--   Card/{Title, Body, Primary, Secondary}    Flash    Fly
local Theme = require(script.Parent.Parent.Theme)

local C = Theme.Colors
local J = Theme.Job

local function new(className: string, props: { [string]: any }, children: { Instance }?): any
	local inst = Instance.new(className)
	for k, v in props do
		if k ~= "Parent" then
			(inst :: any)[k] = v
		end
	end
	for _, child in children or {} do
		child.Parent = inst
	end
	if props.Parent then
		inst.Parent = props.Parent
	end
	return inst
end

local function corner(r: UDim?)
	return new("UICorner", { CornerRadius = r or Theme.Corner })
end

local function stroke(t: number?)
	return new("UIStroke", { Color = C.Stroke, Transparency = t or C.StrokeTransparency, Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border })
end

local function pad(n: number)
	return new("UIPadding", { PaddingLeft = UDim.new(0, n), PaddingRight = UDim.new(0, n), PaddingTop = UDim.new(0, n), PaddingBottom = UDim.new(0, n) })
end

local function text(name: string, props: { [string]: any }): TextLabel
	local base = {
		Name = name,
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Body,
		TextColor3 = C.Text,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		Size = UDim2.new(1, 0, 0, 18),
	}
	for k, v in props do
		base[k] = v
	end
	return new("TextLabel", base)
end

local function button(name: string, label: string, primary: boolean, props: { [string]: any }?): TextButton
	local base: { [string]: any } = {
		Name = name,
		AutoButtonColor = true,
		BackgroundColor3 = if primary then C.Accent else Theme.Phone.Card,
		FontFace = Theme.Fonts.Bold,
		Text = label,
		TextColor3 = if primary then C.Glass else C.Text,
		TextSize = 15,
		Size = UDim2.new(1, 0, 0, 38),
	}
	for k, v in props or {} do
		base[k] = v
	end
	return new("TextButton", base, { corner(Theme.CornerSmall) })
end

local Build = {}

function Build.build(): ScreenGui
	local gui = new("ScreenGui", {
		Name = "MTL_Job",
		ResetOnSpawn = false,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		DisplayOrder = 6, -- above the HUD (5), below the phone (10)
		IgnoreGuiInset = false,
		ScreenInsets = Enum.ScreenInsets.CoreUISafeInsets, -- same space as MTL_HUD (fly-ups land on its cash label)
	})

	-- job panel: top-right, under the cash/level block
	local panel = new("Frame", {
		Name = "Panel",
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -16, 0, 120),
		Size = UDim2.fromOffset(250, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = C.Glass,
		BackgroundTransparency = C.GlassTransparency,
		Visible = false,
		Parent = gui,
	}, { corner(), stroke() })
	new("Frame", {
		Name = "Accent", -- strip on the left edge: green on shift, grey off, red when leaving
		Position = UDim2.fromOffset(0, 10),
		Size = UDim2.new(0, 3, 1, -20),
		BackgroundColor3 = C.Accent,
		BorderSizePixel = 0,
		Parent = panel,
	}, { corner(UDim.new(1, 0)) })
	local body = new("Frame", {
		Name = "Body",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Parent = panel,
	}, { pad(12), new("UIListLayout", { Padding = UDim.new(0, 5), SortOrder = Enum.SortOrder.LayoutOrder }) })
	panel = body -- the rows below go inside Body
	text("JobTitle", { LayoutOrder = 1, Text = "STOCKER  ·  LIBERTY FOOD MART", TextColor3 = C.TextDim, TextSize = 11, FontFace = Theme.Fonts.Bold, Parent = panel })
	text("Task", {
		LayoutOrder = 2,
		Text = "Grab a box from the stockroom",
		FontFace = Theme.Fonts.Bold,
		TextSize = 17,
		TextWrapped = true,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.new(1, 0, 0, 20),
		Parent = panel,
	})
	text("Steps", { LayoutOrder = 3, Text = "Step 1 of 2", TextColor3 = J.Marker, TextSize = 12, FontFace = Theme.Fonts.Bold, Parent = panel })
	new("Frame", {
		Name = "Progress",
		LayoutOrder = 4,
		Size = UDim2.new(1, 0, 0, 6),
		BackgroundColor3 = J.Track,
		BorderSizePixel = 0,
		Parent = panel,
	}, {
		corner(UDim.new(1, 0)),
		new("Frame", { Name = "Fill", Size = UDim2.fromScale(0, 1), BackgroundColor3 = C.Accent, BorderSizePixel = 0 }, { corner(UDim.new(1, 0)) }),
	})
	text("ProgressText", { LayoutOrder = 5, Text = "Shift 0 / 8  ·  $0", TextColor3 = C.TextDim, TextSize = 12, Parent = panel })
	text("Status", { LayoutOrder = 6, Text = "", TextColor3 = C.Gold, TextSize = 13, FontFace = Theme.Fonts.Bold, TextWrapped = true, AutomaticSize = Enum.AutomaticSize.Y, Visible = false, Parent = panel })
	text("Hint", { LayoutOrder = 7, Text = "", TextColor3 = C.TextDim, TextSize = 12, TextWrapped = true, AutomaticSize = Enum.AutomaticSize.Y, Visible = false, Parent = panel })
	button("Action", "Clock in", true, { LayoutOrder = 8, Size = UDim2.new(1, 0, 0, 32), TextSize = 13, Visible = false, Parent = panel })

	-- minigame: bottom centre (clear of the thumbstick and the jump button on phones)
	local mg = new("Frame", {
		Name = "Minigame",
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 1, -110),
		Size = UDim2.fromOffset(440, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = C.Glass,
		BackgroundTransparency = C.GlassTransparency,
		Visible = false,
		Parent = gui,
	}, {
		corner(),
		stroke(),
		pad(14),
		new("UIListLayout", { Padding = UDim.new(0, 10), SortOrder = Enum.SortOrder.LayoutOrder, HorizontalAlignment = Enum.HorizontalAlignment.Center }),
		new("UISizeConstraint", { MaxSize = Vector2.new(440, math.huge) }),
		new("UIScale", { Name = "Scale" }),
	})
	text("Title", { LayoutOrder = 1, Text = "MOPPING", FontFace = Theme.Fonts.Display, TextSize = 22, TextXAlignment = Enum.TextXAlignment.Center, Size = UDim2.new(1, 0, 0, 26), Parent = mg })
	button("Close", "X", false, {
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, 4, 0, -4),
		Size = UDim2.fromOffset(28, 28),
		TextSize = 13,
		BackgroundTransparency = 0.4,
		Parent = mg,
	})

	-- hold
	local hold = new("Frame", { Name = "Hold", LayoutOrder = 2, Size = UDim2.new(1, 0, 0, 30), BackgroundTransparency = 1, Visible = false, Parent = mg })
	new("Frame", { Name = "Bar", Size = UDim2.new(1, 0, 0, 16), Position = UDim2.fromOffset(0, 0), BackgroundColor3 = J.Track, BorderSizePixel = 0, Parent = hold }, {
		corner(UDim.new(1, 0)),
		new("Frame", { Name = "Fill", Size = UDim2.fromScale(0, 1), BackgroundColor3 = C.Accent, BorderSizePixel = 0 }, { corner(UDim.new(1, 0)) }),
	})
	text("Percent", { Position = UDim2.fromOffset(0, 16), Size = UDim2.new(1, 0, 0, 14), Text = "", TextSize = 11, TextColor3 = C.TextDim, TextXAlignment = Enum.TextXAlignment.Center, Parent = hold })

	-- timing
	local timing = new("Frame", { Name = "Timing", LayoutOrder = 3, Size = UDim2.new(1, 0, 0, 46), BackgroundTransparency = 1, Visible = false, Parent = mg })
	local track = new("Frame", { Name = "Track", Size = UDim2.new(1, 0, 0, 24), BackgroundColor3 = J.Track, BorderSizePixel = 0, ClipsDescendants = false, Parent = timing }, { corner(UDim.new(0, 6)) })
	new("Frame", { Name = "Zone", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromScale(0.5, 0), Size = UDim2.fromScale(0.22, 1), BackgroundColor3 = J.Zone, BackgroundTransparency = 0.15, BorderSizePixel = 0, Parent = track }, { corner(UDim.new(0, 6)) })
	new("Frame", { Name = "Needle", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0, 0.5), Size = UDim2.new(0, 4, 1, 10), BackgroundColor3 = J.Needle, BorderSizePixel = 0, ZIndex = 3, Parent = track }, { corner(UDim.new(1, 0)) })
	new("Frame", { Name = "Pips", Position = UDim2.fromOffset(0, 30), Size = UDim2.new(1, 0, 0, 14), BackgroundTransparency = 1, Parent = timing }, {
		new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, HorizontalAlignment = Enum.HorizontalAlignment.Center, Padding = UDim.new(0, 6) }),
	})

	-- sequence
	local seq = new("Frame", { Name = "Sequence", LayoutOrder = 4, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Visible = false, Parent = mg }, {
		new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }),
	})
	new("Frame", { Name = "Ticket", LayoutOrder = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = Color3.fromRGB(245, 240, 225), Parent = seq }, {
		corner(Theme.CornerSmall),
		pad(8),
		new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Wraps = true, Padding = UDim.new(0, 6), HorizontalAlignment = Enum.HorizontalAlignment.Center }),
	})
	new("Frame", { Name = "Buttons", LayoutOrder = 2, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Parent = seq }, {
		new("UIGridLayout", { CellSize = UDim2.new(0.333, -6, 0, 40), CellPadding = UDim2.fromOffset(8, 8), SortOrder = Enum.SortOrder.LayoutOrder, HorizontalAlignment = Enum.HorizontalAlignment.Center }),
	})

	button("ActionButton", "HOLD  [E]", true, { LayoutOrder = 9, Size = UDim2.new(0.6, 0, 0, 46), TextSize = 17, Parent = mg })

	-- centre card: shift complete / check in
	local card = new("Frame", {
		Name = "Card",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.52),
		Size = UDim2.fromOffset(330, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = C.Glass,
		BackgroundTransparency = 0.08,
		Visible = false,
		Parent = gui,
	}, {
		corner(),
		stroke(),
		pad(16),
		new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }),
		new("UIScale", { Name = "Scale" }),
	})
	text("Title", { LayoutOrder = 1, Text = "SHIFT COMPLETE", FontFace = Theme.Fonts.Display, TextSize = 22, TextXAlignment = Enum.TextXAlignment.Center, Size = UDim2.new(1, 0, 0, 26), Parent = card })
	text("Body", { LayoutOrder = 2, Text = "", TextColor3 = C.TextDim, TextWrapped = true, AutomaticSize = Enum.AutomaticSize.Y, TextXAlignment = Enum.TextXAlignment.Center, Parent = card })
	button("Primary", "Next shift", true, { LayoutOrder = 3, Parent = card })
	button("Secondary", "Clock out", false, { LayoutOrder = 4, Parent = card })

	-- big centre word after a task (PERFECT / SLOPPY)
	text("Flash", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.62),
		Size = UDim2.fromOffset(400, 40),
		Text = "",
		FontFace = Theme.Fonts.Display,
		TextSize = 34,
		TextColor3 = J.Perfect,
		TextXAlignment = Enum.TextXAlignment.Center,
		TextTransparency = 1,
		Parent = gui,
	})
	gui.Flash:SetAttribute("Note", "PERFECT / SLOPPY pop")
	new("UIStroke", { Color = C.Shadow, Transparency = 0.4, Thickness = 2, Parent = gui.Flash })

	-- reward fly-ups (+$8 from the shelf to the cash counter)
	new("Frame", { Name = "Fly", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 10, Parent = gui })

	return gui
end

return Build
]======])
put("ReplicatedStorage/MTL/UI/Build", "Mission", "ModuleScript", [======[--!strict
-- Builds the MTL_Mission ScreenGui (Piece 3): mission tracker, hold prompt, aim meter, crew barks, alarm edges,
-- payout screen and the offer card. Used two ways, same as HUD/Phone/Job:
--   1. Edit time: tools/Install.lua saves it into StarterGui as real instances (Alex reskins it there)
--   2. Runtime fallback: MissionController builds it only if PlayerGui has no MTL_Mission
-- MissionController finds things BY NAME. Keep these names when reskinning:
--   Tracker/Accent, Tracker/Body/{Kicker, Name, Steps, Timer}
--   Prompt (button)/{Key, Verb, Bar/Fill}      Meter/{Label, Bar/Fill}      AimButton
--   Bark/{Speaker, Line}      Alarm/{Top, Bottom, Left, Right}
--   Payout/{Dim, Card/{Kicker, Title, Rows, Total/{Label, Value}, XP, Note, Continue}}
--   Offer/{Dim, Card/{Kicker, Title, Sub, Tiles, Later}}
-- Runtime pieces (rows, tiles) come from Mission.stepRow / Mission.payoutRow / Mission.offerTile below.
local Theme = require(script.Parent.Parent.Theme)

local C = Theme.Colors
local M = Theme.Mission

local function new(className: string, props: { [string]: any }, children: { Instance }?): any
	local inst = Instance.new(className)
	for k, v in props do
		if k ~= "Parent" then
			(inst :: any)[k] = v
		end
	end
	for _, child in children or {} do
		child.Parent = inst
	end
	if props.Parent then
		inst.Parent = props.Parent
	end
	return inst
end

local function corner(r: UDim?)
	return new("UICorner", { CornerRadius = r or Theme.Corner })
end

local function stroke(t: number?, color: Color3?)
	return new("UIStroke", { Color = color or C.Stroke, Transparency = t or C.StrokeTransparency, Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border })
end

local function textStroke()
	return new("UIStroke", { Color = C.Shadow, Transparency = 0.5, Thickness = 1.5 })
end

local function pad(l: number, t: number?)
	return new("UIPadding", {
		PaddingLeft = UDim.new(0, l),
		PaddingRight = UDim.new(0, l),
		PaddingTop = UDim.new(0, t or l),
		PaddingBottom = UDim.new(0, t or l),
	})
end

local function list(gap: number, horizontal: boolean?, align: Enum.HorizontalAlignment?)
	return new("UIListLayout", {
		FillDirection = if horizontal then Enum.FillDirection.Horizontal else Enum.FillDirection.Vertical,
		Padding = UDim.new(0, gap),
		SortOrder = Enum.SortOrder.LayoutOrder,
		HorizontalAlignment = align or Enum.HorizontalAlignment.Left,
	})
end

local function label(props: { [string]: any }): TextLabel
	local base = {
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Body,
		TextColor3 = C.Text,
		TextSize = 14,
		Text = "",
	}
	for k, v in props do
		base[k] = v
	end
	return new("TextLabel", base)
end

local function bar(name: string, parent: Instance, props: { [string]: any }, fillColor: Color3): Frame
	local b = new("Frame", {
		Name = name,
		BackgroundColor3 = C.Glass,
		BackgroundTransparency = 0.3,
		BorderSizePixel = 0,
		Parent = parent,
	}, { corner(UDim.new(1, 0)) })
	for k, v in props do
		(b :: any)[k] = v
	end
	new("Frame", { Name = "Fill", Size = UDim2.fromScale(0, 1), BackgroundColor3 = fillColor, BorderSizePixel = 0, Parent = b }, { corner(UDim.new(1, 0)) })
	return b
end

local function fullScreen(name: string, parent: Instance): Frame
	local f = new("Frame", { Name = name, Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Visible = false, ZIndex = 20, Parent = parent })
	new("Frame", {
		Name = "Dim",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = M.Dim,
		BackgroundTransparency = M.DimTransparency,
		BorderSizePixel = 0,
		ZIndex = 20,
		Parent = f,
	})
	return f
end

local function card(parent: Instance, width: number): Frame
	return new("Frame", {
		Name = "Card",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(width, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = M.Card,
		BackgroundTransparency = 0.04,
		ZIndex = 21,
		Parent = parent,
	}, { corner(UDim.new(0, 16)), stroke(0.85), pad(22, 20), list(10, false, Enum.HorizontalAlignment.Center), new("UIScale", { Name = "Pop" }) })
end

local function button(parent: Instance, name: string, text: string, primary: boolean, order: number): TextButton
	return new("TextButton", {
		Name = name,
		LayoutOrder = order,
		Size = UDim2.new(1, 0, 0, 44),
		BackgroundColor3 = if primary then C.Accent else M.Tile,
		BackgroundTransparency = if primary then 0 else 0.2,
		AutoButtonColor = true,
		FontFace = Theme.Fonts.Bold,
		Text = text,
		TextColor3 = if primary then C.Glass else C.TextDim,
		TextSize = 16,
		ZIndex = 22,
		Parent = parent,
	}, { corner(Theme.CornerSmall) })
end

local Mission = {}

function Mission.build(): ScreenGui
	local gui = new("ScreenGui", {
		Name = "MTL_Mission",
		ResetOnSpawn = false,
		IgnoreGuiInset = false,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		DisplayOrder = 8, -- above the HUD (5) and job (6), below the phone (10). Payout/offer hide the phone.
		ScreenInsets = Enum.ScreenInsets.CoreUISafeInsets,
	})

	-- tracker: top right, where the job panel sits (no shift can run during a mission)
	local tracker = new("Frame", {
		Name = "Tracker",
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -16, 0, 120),
		Size = UDim2.fromOffset(250, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = C.Glass,
		BackgroundTransparency = C.GlassTransparency,
		Visible = false,
		Parent = gui,
	}, { corner(), stroke() })
	new("Frame", { Name = "Accent", Size = UDim2.new(0, 3, 1, 0), BackgroundColor3 = M.Accent, BorderSizePixel = 0, Parent = tracker })
	local body = new("Frame", {
		Name = "Body",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Parent = tracker,
	}, { pad(14, 12), list(6) })
	label({ Name = "Kicker", LayoutOrder = 1, Size = UDim2.new(1, 0, 0, 14), Text = "MISSION", FontFace = Theme.Fonts.Bold, TextColor3 = M.Accent, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, Parent = body })
	label({ Name = "MissionName", LayoutOrder = 2, Size = UDim2.new(1, 0, 0, 22), Text = "", FontFace = Theme.Fonts.Display, TextSize = 18, TextXAlignment = Enum.TextXAlignment.Left, Parent = body })
	new("Frame", { Name = "Steps", LayoutOrder = 3, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Parent = body }, { list(4) })
	label({ Name = "Timer", LayoutOrder = 4, Size = UDim2.new(1, 0, 0, 18), Text = "", FontFace = Theme.Fonts.Mono, TextColor3 = C.Gold, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left, Visible = false, Parent = body })

	-- hold prompt: bottom centre. It is also the touch/mouse button (press and hold).
	local prompt = new("TextButton", {
		Name = "Prompt",
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 1, -130),
		Size = UDim2.fromOffset(230, 58),
		BackgroundColor3 = C.Glass,
		BackgroundTransparency = C.GlassTransparency,
		AutoButtonColor = false,
		Text = "",
		Visible = false,
		Parent = gui,
	}, { corner(UDim.new(0, 14)), stroke(0.8), new("UIScale", { Name = "Pop" }) })
	label({
		Name = "Key",
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 12, 0.5, -4),
		Size = UDim2.fromOffset(34, 34),
		BackgroundColor3 = C.Text,
		BackgroundTransparency = 0,
		Text = "E",
		FontFace = Theme.Fonts.Display,
		TextColor3 = C.Glass,
		TextSize = 18,
		Parent = prompt,
	}).Parent = prompt
	corner(Theme.CornerSmall).Parent = prompt.Key
	label({
		Name = "Verb",
		Position = UDim2.fromOffset(56, 8),
		Size = UDim2.new(1, -66, 0, 26),
		Text = "Hold",
		FontFace = Theme.Fonts.Bold,
		TextSize = 17,
		TextXAlignment = Enum.TextXAlignment.Left,
		Parent = prompt,
	})
	bar("Bar", prompt, { Position = UDim2.new(0, 56, 1, -16), Size = UDim2.new(1, -70, 0, 6) }, M.Meter)

	-- aim meter: just under the screen centre (the crosshair)
	local meter = new("Frame", {
		Name = "Meter",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0.5, 46),
		Size = UDim2.fromOffset(220, 34),
		BackgroundTransparency = 1,
		Visible = false,
		Parent = gui,
	})
	label({ Name = "Label", Size = UDim2.new(1, 0, 0, 16), Text = "AIM AT THE CLERK", FontFace = Theme.Fonts.Bold, TextSize = 13, TextColor3 = C.Text, Parent = meter }).Parent = meter
	textStroke().Parent = meter.Label
	bar("Bar", meter, { Position = UDim2.fromOffset(0, 22), Size = UDim2.new(1, 0, 0, 7) }, M.Meter)

	-- touch only: the aim button (fallback aim when the Guns piece isn't installed)
	new("TextButton", {
		Name = "AimButton",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -150, 0.62, 0),
		Size = UDim2.fromOffset(72, 72),
		BackgroundColor3 = C.Glass,
		BackgroundTransparency = 0.25,
		AutoButtonColor = false,
		FontFace = Theme.Fonts.Display,
		Text = "AIM",
		TextColor3 = C.Text,
		TextSize = 16,
		Visible = false,
		Parent = gui,
	}, { corner(UDim.new(1, 0)), stroke(0.6) })

	-- crew barks during play: bottom centre, above the prompt
	local bark = new("Frame", {
		Name = "Bark",
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 1, -200),
		Size = UDim2.fromOffset(0, 40),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundColor3 = C.Glass,
		BackgroundTransparency = C.GlassTransparency,
		Visible = false,
		Parent = gui,
	}, { corner(UDim.new(1, 0)), stroke(), pad(16, 0), list(8, true) })
	bark.UIListLayout.VerticalAlignment = Enum.VerticalAlignment.Center
	label({ Name = "Speaker", LayoutOrder = 1, Size = UDim2.fromOffset(0, 40), AutomaticSize = Enum.AutomaticSize.X, FontFace = Theme.Fonts.Display, TextSize = 15, TextColor3 = M.Accent, Parent = bark })
	label({ Name = "Line", LayoutOrder = 2, Size = UDim2.fromOffset(0, 40), AutomaticSize = Enum.AutomaticSize.X, FontFace = Theme.Fonts.Bold, TextSize = 15, Parent = bark })

	-- alarm: red pulsing screen edges while escaping
	local alarm = new("Frame", { Name = "Alarm", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Visible = false, ZIndex = 0, Parent = gui })
	local function edge(name: string, pos: UDim2, size: UDim2, rot: number)
		new("Frame", {
			Name = name,
			Position = pos,
			Size = size,
			BackgroundColor3 = M.Alarm,
			BorderSizePixel = 0,
			ZIndex = 0,
			Parent = alarm,
		}, {
			new("UIGradient", {
				Rotation = rot,
				Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.35), NumberSequenceKeypoint.new(1, 1) }),
			}),
		})
	end
	edge("Top", UDim2.fromScale(0, 0), UDim2.fromScale(1, 0.14), 90)
	edge("Bottom", UDim2.fromScale(0, 0.86), UDim2.fromScale(1, 0.14), -90)
	edge("Left", UDim2.fromScale(0, 0), UDim2.fromScale(0.1, 1), 0)
	edge("Right", UDim2.fromScale(0.9, 0), UDim2.fromScale(0.1, 1), 180)

	-- payout screen
	local payout = fullScreen("Payout", gui)
	local pc = card(payout, 380)
	label({ Name = "Kicker", LayoutOrder = 1, Size = UDim2.new(1, 0, 0, 16), Text = "JOB DONE", FontFace = Theme.Fonts.Bold, TextColor3 = M.Accent, TextSize = 13, ZIndex = 22, Parent = pc })
	label({ Name = "Title", LayoutOrder = 2, Size = UDim2.new(1, 0, 0, 34), Text = "Liberty Food Mart", FontFace = Theme.Fonts.Display, TextSize = 28, ZIndex = 22, Parent = pc })
	new("Frame", { Name = "Rows", LayoutOrder = 3, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, ZIndex = 22, Parent = pc }, { list(6) })
	local total = new("Frame", { Name = "Total", LayoutOrder = 4, Size = UDim2.new(1, 0, 0, 52), BackgroundTransparency = 1, ZIndex = 22, Parent = pc })
	new("Frame", { Name = "Rule", Size = UDim2.new(1, 0, 0, 1), BackgroundColor3 = C.Stroke, BackgroundTransparency = 0.85, BorderSizePixel = 0, ZIndex = 22, Parent = total })
	label({ Name = "Label", Position = UDim2.fromOffset(0, 10), Size = UDim2.new(0.5, 0, 0, 40), Text = "YOU GOT", FontFace = Theme.Fonts.Bold, TextColor3 = C.TextDim, TextSize = 15, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 22, Parent = total })
	label({ Name = "Value", AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 6), Size = UDim2.new(0.6, 0, 0, 44), Text = "$0", FontFace = Theme.Fonts.Display, TextColor3 = C.Accent, TextSize = 38, TextXAlignment = Enum.TextXAlignment.Right, ZIndex = 22, Parent = total })
	label({ Name = "XP", LayoutOrder = 5, Size = UDim2.new(1, 0, 0, 18), Text = "", FontFace = Theme.Fonts.Bold, TextColor3 = C.AccentAlt, TextSize = 15, ZIndex = 22, Parent = pc })
	label({ Name = "Note", LayoutOrder = 6, Size = UDim2.new(1, 0, 0, 18), Text = "", TextColor3 = C.TextDim, TextSize = 13, TextWrapped = true, AutomaticSize = Enum.AutomaticSize.Y, ZIndex = 22, Parent = pc })
	button(pc, "Continue", "CONTINUE", true, 7)

	-- offer card (dismissable, no timers)
	local offer = fullScreen("Offer", gui)
	local oc = card(offer, 460)
	label({ Name = "Kicker", LayoutOrder = 1, Size = UDim2.new(1, 0, 0, 16), Text = "LEVEL UP YOUR TAKE", FontFace = Theme.Fonts.Bold, TextColor3 = C.Gold, TextSize = 13, ZIndex = 22, Parent = oc })
	label({ Name = "Title", LayoutOrder = 2, Size = UDim2.new(1, 0, 0, 30), Text = "Double every dollar", FontFace = Theme.Fonts.Display, TextSize = 24, ZIndex = 22, Parent = oc })
	label({ Name = "Sub", LayoutOrder = 3, Size = UDim2.new(1, 0, 0, 18), Text = "", TextColor3 = C.TextDim, TextSize = 14, TextWrapped = true, AutomaticSize = Enum.AutomaticSize.Y, ZIndex = 22, Parent = oc })
	new("Frame", { Name = "Tiles", LayoutOrder = 4, Size = UDim2.new(1, 0, 0, 150), BackgroundTransparency = 1, ZIndex = 22, Parent = oc }, { list(12, true, Enum.HorizontalAlignment.Center) })
	button(oc, "Later", "Maybe later", false, 5)

	return gui
end

-- One checklist row in the tracker. state: "done" | "current" | "todo"
function Mission.stepRow(text: string, state: string): Frame
	local row = new("Frame", { Name = "Step", Size = UDim2.new(1, 0, 0, 20), BackgroundTransparency = 1 })
	local color = if state == "done" then M.Done elseif state == "current" then C.Text else M.Pending
	new("Frame", {
		Name = "Dot",
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 0, 0.5, 0),
		Size = UDim2.fromOffset(8, 8),
		BackgroundColor3 = if state == "current" then M.Accent else color,
		BackgroundTransparency = if state == "todo" then 0.6 else 0,
		Parent = row,
	}, { corner(UDim.new(1, 0)) })
	label({
		Name = "Text",
		Position = UDim2.fromOffset(16, 0),
		Size = UDim2.new(1, -16, 1, 0),
		Text = if state == "done" then text .. "  ✓" else text,
		FontFace = if state == "current" then Theme.Fonts.Bold else Theme.Fonts.Body,
		TextColor3 = color,
		TextSize = 14,
		TextTransparency = if state == "done" then 0.25 else 0,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = row,
	})
	return row
end

-- One line on the payout card: "Register take ........ $1,500"
function Mission.payoutRow(text: string, value: string, color: Color3?): Frame
	local row = new("Frame", { Name = "Row", Size = UDim2.new(1, 0, 0, 22), BackgroundTransparency = 1, ZIndex = 22 })
	label({ Name = "Label", Size = UDim2.new(0.6, 0, 1, 0), Text = text, TextColor3 = C.TextDim, TextSize = 15, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 22, Parent = row })
	label({ Name = "Value", AnchorPoint = Vector2.new(1, 0), Position = UDim2.fromScale(1, 0), Size = UDim2.new(0.4, 0, 1, 0), Text = value, FontFace = Theme.Fonts.Bold, TextColor3 = color or C.Text, TextSize = 15, TextXAlignment = Enum.TextXAlignment.Right, ZIndex = 22, Parent = row })
	return row
end

-- One offer tile: icon, title, sub, price button. The controller fills Price/Buy text.
function Mission.offerTile(title: string, sub: string, icon: string?): Frame
	local tile = new("Frame", {
		Name = "Tile",
		Size = UDim2.fromOffset(196, 150),
		BackgroundColor3 = M.Tile,
		ZIndex = 22,
	}, { corner(UDim.new(0, 12)), stroke(0.8, M.TileHighlight), pad(12, 12) })
	new("ImageLabel", {
		Name = "Icon",
		Size = UDim2.fromOffset(28, 28),
		BackgroundColor3 = M.TileHighlight,
		BackgroundTransparency = if icon and icon ~= "rbxassetid://0" then 1 else 0,
		Image = if icon and icon ~= "rbxassetid://0" then icon else "",
		ZIndex = 22,
		Parent = tile,
	}, { corner(UDim.new(0, 8)) })
	label({ Name = "Title", Position = UDim2.fromOffset(0, 34), Size = UDim2.new(1, 0, 0, 22), Text = title, FontFace = Theme.Fonts.Display, TextSize = 18, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 22, Parent = tile })
	label({ Name = "Sub", Position = UDim2.fromOffset(0, 56), Size = UDim2.new(1, 0, 0, 18), Text = sub, TextColor3 = C.TextDim, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 22, Parent = tile })
	new("TextButton", {
		Name = "Buy",
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.fromScale(0, 1),
		Size = UDim2.new(1, 0, 0, 38),
		BackgroundColor3 = M.TileHighlight,
		AutoButtonColor = true,
		FontFace = Theme.Fonts.Bold,
		Text = "...",
		TextColor3 = C.Glass,
		TextSize = 15,
		ZIndex = 23,
		Parent = tile,
	}, { corner(Theme.CornerSmall) })
	return tile
end

return Mission
]======])
put("ReplicatedStorage/MTL/UI/Build", "Phone", "ModuleScript", [======[--!strict
-- Builds the MTL_Phone ScreenGui. Used two ways (same as HUD):
--   1. Edit time (Install.lua / command bar): saved into StarterGui as real instances Alex can reskin
--   2. Runtime fallback: PhoneController builds it only if PlayerGui has no MTL_Phone
-- PhoneController finds things BY NAME. Keep these names when reskinning (replace images/colours freely):
--   Phone (moves; has UIScale)            Phone/Body (the clickable phone, ImageButton)
--   Phone/Badge                            red count when closed
--   Body/Screen                            clips everything inside the glass
--   Screen/Wallpaper  Screen/StatusBar/{Time,Notch,Status}
--   Screen/Home/{Clock,Date,Grid}          Grid/App_<AppId>/{Icon,Glyph,Label}  (built from Config/Phone.Apps)
--   Screen/AppHost                         apps mount here
--   Screen/Banner/{Icon,Title,Body}        notification that slides down from the top
--   Screen/Call/{Avatar,Caller,Status,Caption/{Who,Line},Choices,Answer,Decline,HangUp,Skip}
--   Screen/HomeBar                         tap = home, drag down = close
-- Layout is in design pixels (Config/Phone.Tuning.DesignSize, 300 x 620); UIScale fits it to the screen.
local Theme = require(script.Parent.Parent.Theme)
local UIKit = require(script.Parent.Parent.UIKit)
local PhoneConfig = require(script.Parent.Parent.Parent.Config.Phone) -- relative, so the installer's temp copy works

local C = Theme.Colors
local P = Theme.Phone
local new = UIKit.new
local corner = UIKit.corner

local Build = {}

-- shared low-poly look (UI/LowPoly.lua, from the HUD work). Optional: falls back to the local facets below.
local okLP, LowPoly = pcall(function()
	return require(script.Parent.Parent:WaitForChild("LowPoly", 2)) :: any
end)
if not okLP then
	LowPoly = nil
end

-- Low-poly shading: a hard-edged (stepped) gradient, so a flat surface reads as two or three facets of a
-- polygon instead of a smooth blend. `bands` = colours from one side to the other; `rot` = facet direction.
local function facets(bands: { Color3 }, rot: number): UIGradient
	local kps = {}
	local n = #bands
	for i, c in bands do
		local a = (i - 1) / n
		local b = i / n
		table.insert(kps, ColorSequenceKeypoint.new(if i == 1 then 0 else a + 0.001, c))
		table.insert(kps, ColorSequenceKeypoint.new(b, c))
	end
	return new("UIGradient", { Rotation = rot, Color = ColorSequence.new(kps) })
end
Build.facets = facets

local function shade(c: Color3, k: number): Color3
	return if k >= 0 then c:Lerp(Color3.new(1, 1, 1), k) else c:Lerp(Color3.new(0, 0, 0), -k)
end
Build.shade = shade

local STATUS_H = 30
local HOMEBAR_H = 22

local function circleButton(name: string, color: Color3, glyph: string, label: string, pos: UDim2, parent: Instance): TextButton
	local b = new("TextButton", {
		Name = name,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = pos,
		Size = UDim2.fromOffset(64, 64),
		BackgroundColor3 = color,
		AutoButtonColor = false,
		FontFace = Theme.Fonts.Display,
		Text = glyph,
		TextColor3 = C.Text,
		TextSize = 24,
		Parent = parent,
	}, { corner(UDim.new(1, 0)) })
	new("TextLabel", {
		Name = "Label",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 1, 6),
		Size = UDim2.fromOffset(100, 16),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Body,
		Text = label,
		TextColor3 = C.TextDim,
		TextSize = 13,
		Parent = b,
	})
	return b
end

-- One home-screen icon. Exposed so PhoneController can add icons for apps that aren't in the saved GUI yet.
function Build.appIcon(app: any, order: number): TextButton
	local icon = P.Icons[app.id] or "rbxassetid://0"
	local tile = new("TextButton", {
		Name = "App_" .. app.id,
		LayoutOrder = order,
		BackgroundTransparency = 1,
		Text = "",
		AutoButtonColor = false,
	})
	local square = new("ImageLabel", {
		Name = "Icon",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.fromScale(0.5, 0),
		Size = UDim2.fromOffset(56, 56),
		BackgroundColor3 = P.AppColors[app.id] or C.AccentAlt,
		Image = if icon == "rbxassetid://0" then "" else icon, -- TODO(Alex art): app icon
		Parent = tile,
	}, {
		corner(P.IconCorner or P.Corner),
		-- soft top-lit gloss, like a real app icon
		new("UIGradient", {
			Rotation = 90,
			Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(200, 200, 205)),
		}),
		new("UIStroke", { Color = Color3.new(1, 1, 1), Transparency = 0.82, Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }),
	})
	if P.LowPoly then
		local col = P.AppColors[app.id] or C.AccentAlt
		if LowPoly then
			LowPoly.style(square, col, { outline = 2, corner = UDim.new(0, 6) })
		else
			square:FindFirstChildOfClass("UIGradient"):Destroy()
			square.BackgroundColor3 = Color3.new(1, 1, 1)
			facets({ shade(col, P.FacetLight), col, shade(col, -P.FacetDark) }, 32).Parent = square
		end
	end
	new("TextLabel", {
		Name = "Glyph",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Display,
		Text = if icon == "rbxassetid://0" then (P.Glyphs and P.Glyphs[app.id]) or app.glyph or string.sub(app.title, 1, 1) else "",
		TextColor3 = C.Text,
		TextSize = 28,
		Parent = square,
	})
	new("TextLabel", {
		Name = "Label",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 60),
		Size = UDim2.new(1, 8, 0, 16),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Body,
		Text = app.title,
		TextColor3 = C.Text,
		TextSize = 11,
		Parent = tile,
	}, { new("UIStroke", { Color = C.Shadow, Transparency = 0.45, Thickness = 1 }) })
	return tile
end

function Build.build(): ScreenGui
	local size = PhoneConfig.Tuning.DesignSize
	local pad = P.BezelPadding

	local gui = new("ScreenGui", {
		Name = "MTL_Phone",
		ResetOnSpawn = false,
		IgnoreGuiInset = true,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		DisplayOrder = 10, -- above the HUD (5)
		ScreenInsets = Enum.ScreenInsets.DeviceSafeInsets,
	})

	local phone = new("Frame", {
		Name = "Phone",
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.new(1, -PhoneConfig.Tuning.Margin, 1, size.Y * 0.85),
		Size = UDim2.fromOffset(size.X, size.Y),
		Rotation = PhoneConfig.Tuning.TiltDegrees,
		BackgroundTransparency = 1,
		Parent = gui,
	}, { new("UIScale", { Scale = 1 }) })

	-- low poly: a solid slab edge (the phone's thickness) peeking out bottom-right; smooth: a soft shadow
	new("Frame", {
		Name = "Shadow",
		Position = if P.LowPoly then UDim2.fromOffset(5, 6) else UDim2.fromOffset(0, 10),
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = if P.LowPoly then P.FrameEdge else C.Shadow,
		BackgroundTransparency = if P.LowPoly then 0 else 0.55,
		ZIndex = 0,
		Parent = phone,
	}, { corner(P.FrameCorner) })

	local body = new("ImageButton", {
		Name = "Body",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = P.Frame,
		AutoButtonColor = false,
		Image = "", -- TODO(Alex art): phone frame/case image
		Parent = phone,
	}, {
		corner(P.FrameCorner),
		-- metal band round the edge, catching light at the top
		new("UIStroke", { Color = Color3.new(1, 1, 1), Thickness = 3, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, {
			new("UIGradient", { Rotation = 90, Color = ColorSequence.new(P.Rim or P.FrameStroke, P.Frame) }),
		}),
	})
	if not P.LowPoly then
		-- the glass: a faint diagonal sheen across the body
		new("UIGradient", {
			Rotation = 120,
			Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
				ColorSequenceKeypoint.new(1, Color3.fromRGB(215, 215, 222)),
			}),
			Parent = body,
		})
	end
	if P.LowPoly then
		-- faceted body with a hard dark outline, like the HUD panels
		if LowPoly then
			LowPoly.style(body, P.Frame, { outline = 3, corner = P.FrameCorner })
		else
			body.BackgroundColor3 = Color3.new(1, 1, 1)
			facets({ shade(P.Frame, P.FacetLight), P.Frame, shade(P.Frame, -P.FacetDark) }, 32).Parent = body
		end
	end

	-- side buttons (purely visual)
	new("Frame", { Name = "SideButton", Position = UDim2.new(1, 0, 0, 130), Size = UDim2.fromOffset(4, 60), BackgroundColor3 = P.Rim or P.FrameStroke, BorderSizePixel = 0, Parent = phone }, { corner(UDim.new(0, 2)) })
	new("Frame", { Name = "VolumeButton", Position = UDim2.new(0, -4, 0, 110), Size = UDim2.fromOffset(4, 40), BackgroundColor3 = P.Rim or P.FrameStroke, BorderSizePixel = 0, Parent = phone }, { corner(UDim.new(0, 2)) })
	new("Frame", { Name = "VolumeButton2", Position = UDim2.new(0, -4, 0, 160), Size = UDim2.fromOffset(4, 40), BackgroundColor3 = P.Rim or P.FrameStroke, BorderSizePixel = 0, Parent = phone }, { corner(UDim.new(0, 2)) })

	local screen = new("Frame", {
		Name = "Screen",
		Position = UDim2.fromOffset(pad, pad),
		Size = UDim2.new(1, -pad * 2, 1, -pad * 2),
		BackgroundColor3 = P.Screen,
		ClipsDescendants = true,
		Parent = body,
	}, { corner(P.ScreenCorner) })

	local wall = new("ImageLabel", {
		Name = "Wallpaper",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = Color3.new(1, 1, 1),
		Image = if P.Wallpaper == "rbxassetid://0" then "" else P.Wallpaper,
		ScaleType = Enum.ScaleType.Crop,
		Parent = screen,
	}, { corner(P.ScreenCorner) })
	if P.LowPoly then
		-- faceted placeholder wallpaper: hard diagonal bands, like a low-poly sky
		local g = facets({
			P.WallTop,
			P.WallTop:Lerp(P.WallBottom, 0.33),
			P.WallTop:Lerp(P.WallBottom, 0.66),
			P.WallBottom,
		}, 70)
		g.Parent = wall
	elseif P.Wallpaper == "rbxassetid://0" then
		-- placeholder wallpaper: Miami sunset sky + a striped retro sun sinking behind a dark sea
		new("UIGradient", {
			Rotation = 90,
			Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, P.WallTop),
				ColorSequenceKeypoint.new(0.5, P.WallMid or P.WallTop),
				ColorSequenceKeypoint.new(0.72, P.WallLow or P.WallBottom),
				ColorSequenceKeypoint.new(1, P.WallLow or P.WallBottom),
			}),
			Parent = wall,
		})
		local sunCols = P.Sun or { C.Gold, C.Danger }
		local sun = new("Frame", {
			Name = "Sun",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.58),
			Size = UDim2.fromOffset(170, 170),
			BackgroundColor3 = Color3.new(1, 1, 1),
			BorderSizePixel = 0,
			Parent = wall,
		}, { corner(UDim.new(1, 0)), new("UIGradient", { Rotation = 90, Color = ColorSequence.new(sunCols[1], sunCols[2]) }) })
		-- stripes cut through the lower half of the sun (wallpaper-coloured bands)
		for k = 0, 4 do
			local y = 0.56 + k * 0.085
			new("Frame", {
				Name = "SunStripe",
				Position = UDim2.fromScale(0, y),
				Size = UDim2.new(1, 0, 0, 3 + k * 2),
				BackgroundColor3 = (P.WallMid or P.WallTop):Lerp(P.WallLow or P.WallBottom, 0.75), -- sky colour behind the lower sun, so the bands read as cuts
				BorderSizePixel = 0,
				Parent = sun,
			})
		end
		new("Frame", {
			Name = "Sea",
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.fromScale(0, 1),
			Size = UDim2.fromScale(1, 0.3),
			BackgroundColor3 = P.WallBottom,
			BorderSizePixel = 0,
			Parent = wall,
		}, { new("UIGradient", { Rotation = 90, Transparency = NumberSequence.new(0.15, 0) }) })
		-- darken the top a touch so the clock reads
		new("Frame", {
			Name = "Shade",
			Size = UDim2.fromScale(1, 0.45),
			BackgroundColor3 = Color3.new(0, 0, 0),
			BorderSizePixel = 0,
			Parent = wall,
		}, { new("UIGradient", { Rotation = 90, Transparency = NumberSequence.new(0.55, 1) }) })
	else
		new("UIGradient", {
			Rotation = 90,
			Color = ColorSequence.new(P.WallTop, P.WallBottom),
			Parent = wall,
		})
	end

	-- status bar: time · notch · signal/battery
	local status = new("Frame", {
		Name = "StatusBar",
		Size = UDim2.new(1, 0, 0, STATUS_H),
		BackgroundTransparency = 1,
		ZIndex = 20,
		Parent = screen,
	})
	new("TextLabel", {
		Name = "Time",
		Position = UDim2.fromOffset(20, 0),
		Size = UDim2.new(0.35, 0, 1, 0),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Bold,
		Text = "9:41 AM",
		TextColor3 = C.Text,
		TextSize = 13,
		TextXAlignment = Enum.TextXAlignment.Left,
		ZIndex = 20,
		Parent = status,
	})
	new("Frame", {
		Name = "Notch",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 7),
		Size = UDim2.fromOffset(84, 22),
		BackgroundColor3 = Color3.new(0, 0, 0),
		ZIndex = 21,
		Parent = status,
	}, { corner(UDim.new(1, 0)) })
	new("TextLabel", {
		Name = "Status",
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -46, 0, 0),
		Size = UDim2.new(0, 24, 1, 0),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Bold,
		Text = "5G",
		TextColor3 = C.Text,
		TextSize = 11,
		TextXAlignment = Enum.TextXAlignment.Right,
		ZIndex = 20,
		Parent = status,
	})
	-- drawn signal bars + battery (right of "5G")
	local bars = new("Frame", { Name = "Signal", AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -74, 0.5, 1), Size = UDim2.fromOffset(16, 10), BackgroundTransparency = 1, ZIndex = 20, Parent = status })
	for k = 1, 4 do
		new("Frame", { Name = "Bar", AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, (k - 1) * 4, 1, 0), Size = UDim2.fromOffset(3, 2 + k * 2), BackgroundColor3 = C.Text, BorderSizePixel = 0, ZIndex = 20, Parent = bars }, { corner(UDim.new(0, 1)) })
	end
	local batt = new("Frame", { Name = "Battery", AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -18, 0.5, 1), Size = UDim2.fromOffset(22, 11), BackgroundTransparency = 1, ZIndex = 20, Parent = status }, {
		corner(UDim.new(0, 3)),
		new("UIStroke", { Color = C.Text, Transparency = 0.45, Thickness = 1 }),
	})
	new("Frame", { Name = "Level", Position = UDim2.fromOffset(2, 2), Size = UDim2.new(0.82, -4, 1, -4), BackgroundColor3 = C.Text, BorderSizePixel = 0, ZIndex = 20, Parent = batt }, { corner(UDim.new(0, 2)) })
	new("Frame", { Name = "Nub", AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(1, 1, 0.5, 0), Size = UDim2.fromOffset(2, 4), BackgroundColor3 = C.Text, BackgroundTransparency = 0.45, BorderSizePixel = 0, ZIndex = 20, Parent = batt })

	-- home screen
	local home = new("Frame", {
		Name = "Home",
		Position = UDim2.fromOffset(0, STATUS_H),
		Size = UDim2.new(1, 0, 1, -(STATUS_H + HOMEBAR_H)),
		BackgroundTransparency = 1,
		Parent = screen,
	})
	new("TextLabel", {
		Name = "Clock",
		Position = UDim2.fromOffset(0, 30),
		Size = UDim2.new(1, 0, 0, 64),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Display,
		Text = "9:41",
		TextColor3 = C.Text,
		TextSize = 62,
		Parent = home,
	}, { new("UIStroke", { Color = Color3.new(0, 0, 0), Transparency = 0.8, Thickness = 1 }) })
	new("TextLabel", {
		Name = "Date",
		Position = UDim2.fromOffset(0, 8),
		Size = UDim2.new(1, 0, 0, 18),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Bold,
		Text = "Vice Bay",
		TextColor3 = C.Text,
		TextTransparency = 0.1,
		TextSize = 14,
		Parent = home,
	})
	local grid = new("Frame", {
		Name = "Grid",
		Position = UDim2.fromOffset(12, 118),
		Size = UDim2.new(1, -24, 1, -118 - 96),
		BackgroundTransparency = 1,
		Parent = home,
	}, {
		new("UIGridLayout", {
			CellSize = UDim2.fromOffset(62, 82),
			CellPadding = UDim2.fromOffset(4, 10),
			HorizontalAlignment = Enum.HorizontalAlignment.Left,
			SortOrder = Enum.SortOrder.LayoutOrder,
		}),
		new("UIPadding", { PaddingLeft = UDim.new(0, 2) }),
	})
	-- dock: frosted bar along the bottom with the four everyday apps
	local dock = new("Frame", {
		Name = "Dock",
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 1, -6),
		Size = UDim2.new(1, -16, 0, 84),
		BackgroundColor3 = P.GlassTint or Color3.new(1, 1, 1),
		BackgroundTransparency = P.GlassAlpha or 0.82,
		Parent = home,
	}, {
		corner(UDim.new(0, 26)),
		new("UIStroke", { Color = Color3.new(1, 1, 1), Transparency = 0.8, Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }),
		new("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			HorizontalAlignment = Enum.HorizontalAlignment.Center,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 4),
			SortOrder = Enum.SortOrder.LayoutOrder,
		}),
		new("UIPadding", { PaddingTop = UDim.new(0, 10) }),
	})
	local inDock: { [string]: number } = {}
	for i, id in P.Dock or {} do
		inDock[id] = i
	end
	for i, app in PhoneConfig.Apps do
		local tile = Build.appIcon(app, i)
		if inDock[app.id] then
			tile.LayoutOrder = inDock[app.id]
			tile.Size = UDim2.fromOffset(62, 74)
			tile.Label.Visible = false -- real docks don't label
			tile.Parent = dock
		else
			tile.Parent = grid
		end
	end

	-- apps mount here (same area as Home)
	new("Frame", {
		Name = "AppHost",
		Position = UDim2.fromOffset(0, STATUS_H),
		Size = UDim2.new(1, 0, 1, -(STATUS_H + HOMEBAR_H)),
		BackgroundTransparency = 1, -- the Screen's own (rounded) background shows behind apps
		Visible = false,
		Parent = screen,
