		Parent = caption,
	})
	new("TextLabel", {
		Name = "Hint",
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.fromScale(1, 1),
		Size = UDim2.new(1, 0, 0, 14),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Body,
		Text = "tap to continue",
		TextColor3 = C.TextDim,
		TextSize = 11,
		TextXAlignment = Enum.TextXAlignment.Right,
		ZIndex = 12,
		Parent = caption,
	})
	new("Frame", {
		Name = "Choices",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 398),
		Size = UDim2.new(1, -28, 0, 100),
		BackgroundTransparency = 1,
		Visible = false,
		ZIndex = 11,
		Parent = call,
	}, { UIKit.list(8) })
	local inner = size.X - pad * 2
	circleButton("Decline", P.Decline, "✕", "Decline", UDim2.fromOffset(inner * 0.27, size.Y - pad * 2 - 90), call).ZIndex = 11
	circleButton("Answer", P.Answer, "✆", "Answer", UDim2.fromOffset(inner * 0.73, size.Y - pad * 2 - 90), call).ZIndex = 11
	local hang = circleButton("HangUp", P.Decline, "✕", "Hang up", UDim2.fromOffset(inner * 0.5, size.Y - pad * 2 - 90), call)
	hang.ZIndex = 11
