put("ServerScriptService/MTL", "Main", "Script", [======[--!strict
-- Boots every server service in order (Master Plan §3.2). New services: add a line here, in dependency order.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local Net = require(ReplicatedStorage.MTL.Net)
Net.init()

local Services = script.Parent.Services
local order = {
	"DataService",
	"TimeService", -- the world clock (clients draw the lighting from it)
	"MonetizationService",
	"EconomyService",
	"WaypointService",
	"StoryService",
	"PhoneService",
	"PhoneStory", -- story beats that arrive by phone (needs Story + Phone)
	"JobService", -- Piece 2: jobs, shifts, tasks (needs Economy, Story, Phone, Waypoints)
	"GunService", -- Piece 5: guns, ammo, shot validation (needs Economy, Story, Phone, Jobs)
	"CutsceneService", -- Piece 3: plays cutscenes on the client, waits for CutsceneDone; builds crew rigs
	"StoryWelcome", -- welcome scenes for new players: Welcome (Arrive) + FirstDay (FirstShift) (needs Story, Cutscene)
	"MissionService", -- Piece 3: step-by-step missions (needs Waypoints, Cutscene; uses GunService if present)
	"StoryCrew", -- Piece 3: stages GangMeet -> MissionDone (needs Story, Phone, Mission, Cutscene, Monetization)
	"PropertyService", -- Piece 4: the flat, rooms, power bill, bed, stages FindAPlace -> CommuteToWork (needs Story, Phone, Cutscene)
	"GoalService", -- Piece 4: FreePlay goals + the objective line in free play
}

local loaded = {}
for _, name in order do
	local module = Services:FindFirstChild(name)
	if not module then
		warn("[MTL Main] missing service", name)
		continue
	end
	local ok, svc = pcall(require, module)
	if ok and type(svc) == "table" and svc.init then
		local initOk, err = pcall(svc.init)
		if initOk then
			loaded[name] = svc
		else
			warn("[MTL Main] init failed:", name, err)
		end
	else
		warn("[MTL Main] require failed:", name, svc)
	end
end

-- Start loading players only once every service is listening.
if loaded.DataService then
	loaded.DataService.start()
end

-- Studio test helper: from the server Command Bar / MCP:
--   _G.MTL.Story.debugSet(game.Players:GetPlayers()[1], "FirstShift")
--   _G.MTL.Economy.addXP(game.Players:GetPlayers()[1], 500, "Debug")
if RunService:IsStudio() then
	_G.MTL = {
		Data = loaded.DataService,
		Time = loaded.TimeService,
		Economy = loaded.EconomyService,
		Story = loaded.StoryService,
		Waypoints = loaded.WaypointService,
		Monetization = loaded.MonetizationService,
		Phone = loaded.PhoneService,
		Jobs = loaded.JobService,
		Guns = loaded.GunService,
		Cutscenes = loaded.CutsceneService,
		Missions = loaded.MissionService,
		StoryCrew = loaded.StoryCrew,
		Property = loaded.PropertyService,
		Goals = loaded.GoalService,
	}
end

-- Studio-only test hook for tools that run in a different Lua VM (Studio MCP / command bar can't see _G.MTL):
--   game.ServerStorage.MTL_Debug:Invoke("Economy", "addXP", player, 500, "Debug")
--   game.ServerStorage.MTL_Debug:Invoke("Data", "snapshot", player)
if RunService:IsStudio() then
	local old = game:GetService("ServerStorage"):FindFirstChild("MTL_Debug")
	if old then
		old:Destroy()
	end
	local bf = Instance.new("BindableFunction")
	bf.Name = "MTL_Debug"
	bf.OnInvoke = function(service: string, fn: string, ...)
		local svc = _G.MTL and _G.MTL[service]
		assert(svc and type(svc[fn]) == "function", "[MTL Debug] no " .. tostring(service) .. "." .. tostring(fn))
		return svc[fn](...)
	end
	bf.Parent = game:GetService("ServerStorage")
end

print("[MTL Main] server ready:", #order, "services")
]======])
put("ServerScriptService/MTL/Services", "Analytics", "ModuleScript", [======[--!strict
-- Thin, crash-proof wrapper over AnalyticsService. Only records in the published game (Studio calls are no-ops there).
local AnalyticsService = game:GetService("AnalyticsService")

local Analytics = {}

local function try(fn, ...)
	local ok, err = pcall(fn, ...)
	if not ok then
		warn("[MTL Analytics]", err)
	end
end

-- Story stage -> onboarding funnel step (step number = stage index in Config/Story).
function Analytics.onboarding(player: Player, step: number, name: string)
	try(function()
		AnalyticsService:LogOnboardingFunnelStepEvent(player, step, name)
	end)
end

-- Recurring funnels (job app, shop): one sessionId per visit.
function Analytics.funnel(player: Player, funnel: string, sessionId: string, step: number, name: string)
	try(function()
		AnalyticsService:LogFunnelStepEvent(player, funnel, sessionId, step, name)
	end)
end

-- Every cash change. source = true for money in, false for money out. reason is our own short id ("Job:Supermarket").
function Analytics.cash(player: Player, source: boolean, amount: number, balance: number, reason: string)
	if amount <= 0 then
		return
	end
	try(function()
		local flow = if source then Enum.AnalyticsEconomyFlowType.Source else Enum.AnalyticsEconomyFlowType.Sink
		local kind = if string.find(reason, "^Purchase") then Enum.AnalyticsEconomyTransactionType.IAP.Name
			elseif source then Enum.AnalyticsEconomyTransactionType.Gameplay.Name
			else Enum.AnalyticsEconomyTransactionType.Shop.Name
		AnalyticsService:LogEconomyEvent(player, flow, "Cash", amount, balance, kind, reason)
	end)
end

return Analytics
]======])
put("ServerScriptService/MTL/Services", "CutsceneService", "ModuleScript", [======[--!strict
-- Server side of cutscenes. The client plays the scene (CutsceneController); the server only says "play" and waits.
--   CutsceneService.play(player, id, { anchor = CFrame?, marks = { Name = Vector3 }? }) -> (finished, skipped)
--       marks (Piece 4): named points local to the anchor (e.g. the PC chair in this player's room) that the scene
--       uses as "#Name"; the scene's own `marks` are the defaults.
--       Yields until the client reports CutsceneDone (token-checked) or a timeout (scene length + 10 s), or the
--       player leaves (finished = false). Either way the caller moves the story on: skipping still advances.
--   CutsceneService.isPlaying(player) -> boolean
--   CutsceneService.rig(actorId) -> Model?     a fresh copy of a crew/NPC rig (server NPCs, e.g. the clerk)
-- Rigs: on init, every Config/Missions.Actors entry gets an R15 rig in ReplicatedStorage.MTL_Actors.<Id>, built
-- from its colours (HumanoidDescription). A rig Alex already put there is kept as-is (that's how real art drops in).
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Net = require(ReplicatedStorage.MTL.Net)
local Missions = require(ReplicatedStorage.MTL.Config.Missions)
local CutsceneRules = require(ReplicatedStorage.MTL.Rules.CutsceneRules)
local RateLimiter = require(script.Parent.RateLimiter)

local CutsceneService = {}

type Pending = { id: string, token: number, done: BindableEvent, skipped: boolean, finished: boolean }
local pending: { [Player]: Pending } = {}
local tokenCounter = 0
local limiter = RateLimiter.new(4, 6)

local function log(...)
	print("[MTL Cutscene]", ...)
end

local function library(): Folder
	local lib = ReplicatedStorage:FindFirstChild("MTL_Actors")
	if not lib then
		local f = Instance.new("Folder")
		f.Name = "MTL_Actors"
		f.Parent = ReplicatedStorage
		lib = f
	end
	return lib :: Folder
end

local function buildRig(id: string, cfg: any): Model?
	local desc = Instance.new("HumanoidDescription")
	desc.HeadColor = cfg.Skin
	desc.LeftArmColor = cfg.Skin
	desc.RightArmColor = cfg.Skin
	desc.TorsoColor = cfg.Shirt
	desc.LeftLegColor = cfg.Pants
	desc.RightLegColor = cfg.Pants
	if type(cfg.ShirtId) == "number" and cfg.ShirtId ~= 0 then
		desc.Shirt = cfg.ShirtId
	end
	if type(cfg.PantsId) == "number" and cfg.PantsId ~= 0 then
		desc.Pants = cfg.PantsId
	end
	local ok, model = pcall(function()
		return Players:CreateHumanoidModelFromDescription(desc, Enum.HumanoidRigType.R15)
	end)
	desc:Destroy()
	if not ok or not model then
		warn("[MTL Cutscene] couldn't build rig", id, model)
		return nil
	end
	model.Name = id
	for _, d in model:GetDescendants() do
		if d:IsA("BaseScript") then
			d:Destroy()
		elseif d:IsA("BasePart") then
			d.CanCollide = false
		end
	end
	local hum = model:FindFirstChildOfClass("Humanoid")
	if hum then
		hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
	end
	if cfg.Height and cfg.Height ~= 1 then
		pcall(function()
			model:ScaleTo(cfg.Height)
		end)
	end
	return model
end

function CutsceneService.rig(actorId: string): Model?
	local lib = library()
	local t = lib:FindFirstChild(actorId) or lib:WaitForChild(actorId, 8)
	if not t or not t:IsA("Model") then
		return nil
	end
	local was = t.Archivable
	t.Archivable = true
	local copy = t:Clone()
	t.Archivable = was
	return copy
end

function CutsceneService.isPlaying(player: Player): boolean
	return pending[player] ~= nil
end

local function sceneLength(id: string): number?
	local folder = ReplicatedStorage.MTL:FindFirstChild("Cutscenes")
	local module = folder and folder:FindFirstChild(id)
	if not module then
		return nil
	end
	local ok, scene = pcall(require, module)
	if not ok or type(scene) ~= "table" then
		return nil
	end
	return CutsceneRules.length(scene)
end

function CutsceneService.play(player: Player, id: string, opts: { [string]: any }?): (boolean, boolean)
	local o = opts or {}
	local length = sceneLength(id)
	if not length then
		warn("[MTL Cutscene] unknown scene", id)
		return true, true
	end
	local old = pending[player]
	if old then
		old.finished = false
		old.done:Fire()
	end
	tokenCounter += 1
	local p: Pending = { id = id, token = tokenCounter, done = Instance.new("BindableEvent"), skipped = false, finished = false }
	pending[player] = p
	local anchor: CFrame? = o.anchor
	if anchor then
		pcall(function()
			player:RequestStreamAroundAsync(anchor.Position, 5)
		end)
	end
	if pending[player] ~= p or not player.Parent then
		return false, false
	end
	Net.get("PlayCutscene"):FireClient(player, { id = id, token = p.token, anchor = anchor, marks = o.marks })
	log(player.Name, "play", id)
	local token = p.token
	task.delay(length + 10, function()
		local now = pending[player]
		if now and now.token == token then
			warn("[MTL Cutscene]", player.Name, id, "timed out; moving on")
			now.finished = true
			now.skipped = true
			now.done:Fire()
		end
	end)
	p.done.Event:Wait()
	p.done:Destroy()
	if pending[player] == p then
		pending[player] = nil
	end
	return p.finished, p.skipped
end

function CutsceneService.init()
	task.spawn(function()
		local lib = library()
		for id, cfg in Missions.Actors do
			if not lib:FindFirstChild(id) then
				local m = buildRig(id, cfg)
				if m then
					m.Parent = lib
				end
			end
		end
		log("actor rigs ready")
	end)

	Net.get("CutsceneDone").OnServerEvent:Connect(function(player, payload)
		if not limiter:allow(player) or type(payload) ~= "table" then
			return
		end
		local p = pending[player]
		if not p or payload.token ~= p.token or payload.id ~= p.id then
			return
		end
		p.finished = true
		p.skipped = payload.skipped == true
		p.done:Fire()
	end)

	Players.PlayerRemoving:Connect(function(player)
		local p = pending[player]
		if p then
			p.finished = false
			p.done:Fire()
		end
	end)
end

return CutsceneService
]======])
put("ServerScriptService/MTL/Services", "DataService", "ModuleScript", [======[--!strict
-- Loads/saves each player's profile with ProfileStore (Vendor/ProfileStore.lua, the same vetted copy as hood/).
-- In Studio it runs in Mock mode: progress resets on Stop, on purpose.
-- Other services read/write `DataService.get(player)` (the live Data table) and call `DataService.push(player)`
-- after changing it. Pushes are batched to one per frame.
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Net = require(ReplicatedStorage.MTL.Net)
local Signal = require(ReplicatedStorage.MTL.Signal)
local Schema = require(script.Parent.ProfileSchema)
local ProfileStore = require(script.Parent.Parent.Vendor.ProfileStore)

local DataService = {}
DataService.Ready = Signal.new() -- (player, data) after load
DataService.Releasing = Signal.new() -- (player, data) just before the session ends
DataService.Mode = if RunService:IsStudio() then "Mock" else "Live"

local profiles: { [Player]: any } = {}
local pushQueued: { [Player]: boolean } = {}
local store

local function log(...)
	print("[MTL Data]", ...)
end

function DataService.get(player: Player): any?
	local p = profiles[player]
	return if p and p:IsActive() then p.Data else nil
end

function DataService.profile(player: Player): any?
	local p = profiles[player]
	return if p and p:IsActive() then p else nil
end

function DataService.snapshot(player: Player): any?
	local data = DataService.get(player)
	if not data then
		return nil
	end
	local snap = Schema.public(data)
	snap.DataMode = DataService.Mode
	return snap
end

function DataService.push(player: Player)
	if pushQueued[player] then
		return
	end
	pushQueued[player] = true
	task.defer(function()
		pushQueued[player] = nil
		local snap = DataService.snapshot(player)
		if snap and player.Parent then
			Net.get("ProfileUpdated"):FireClient(player, snap)
		end
	end)
end

local function onPlayerAdded(player: Player)
	local profile = store:StartSessionAsync("Player_" .. player.UserId, {
		Cancel = function()
			return player.Parent ~= Players
		end,
	})
	if not profile then
		player:Kick("Couldn't load your save. Please rejoin.")
		return
	end
	profile:AddUserId(player.UserId)
	profile:Reconcile()
	Schema.sanitize(profile.Data)
	profile.OnSessionEnd:Connect(function()
		profiles[player] = nil
		if player.Parent == Players then
			player:Kick("Your save was opened somewhere else. Please rejoin.")
		end
	end)
	if player.Parent ~= Players then
		profile:EndSession()
		return
	end
	profiles[player] = profile
	profile.Data.Stats.Joins += 1
	log(player.Name, "loaded", DataService.Mode, "stage", profile.Data.Story.Stage, "level", profile.Data.Level)
	DataService.Ready:Fire(player, profile.Data)
	player:SetAttribute("MTL_Ready", true)
	DataService.push(player)
end

local function onPlayerRemoving(player: Player)
	local profile = profiles[player]
	if profile then
		DataService.Releasing:Fire(player, profile.Data)
		profiles[player] = nil
		profile:EndSession()
	end
end

function DataService.init()
	local s = ProfileStore.New(Schema.StoreName, Schema.Template)
	store = if DataService.Mode == "Mock" then s.Mock else s

	Net.get("RequestSnapshot").OnServerInvoke = function(player)
		return DataService.snapshot(player)
	end

	log("store ready (" .. DataService.Mode .. ")")
end

-- Called by Main AFTER every service's init, so all Ready listeners are connected before anyone loads.
function DataService.start()
	Players.PlayerAdded:Connect(function(p)
		task.spawn(onPlayerAdded, p)
	end)
	Players.PlayerRemoving:Connect(onPlayerRemoving)
	for _, p in Players:GetPlayers() do
		task.spawn(onPlayerAdded, p)
	end
end

return DataService
]======])
put("ServerScriptService/MTL/Services", "EconomyService", "ModuleScript", [======[--!strict
-- THE only place cash and XP change. Applies 2x passes and boosts, levels players up, keeps leaderstats in sync,
-- logs analytics, and tells the client (Reward / LevelUp remotes). Every other system calls this.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Economy = require(ReplicatedStorage.MTL.Config.Economy)
local LevelRules = require(ReplicatedStorage.MTL.Rules.LevelRules)
local Net = require(ReplicatedStorage.MTL.Net)
local Signal = require(ReplicatedStorage.MTL.Signal)
local DataService = require(script.Parent.DataService)
local MonetizationService = require(script.Parent.MonetizationService)
local Analytics = require(script.Parent.Analytics)

local EconomyService = {}
EconomyService.LevelUp = Signal.new() -- (player, newLevel)
EconomyService.CashChanged = Signal.new() -- (player, newCash, delta, reason)

local function log(...)
	print("[MTL Economy]", ...)
end

local function syncLeaderstats(player: Player, data: any)
	local ls = player:FindFirstChild("leaderstats")
	if not ls then
		return
	end
	local cash = ls:FindFirstChild("Cash") :: IntValue?
	local level = ls:FindFirstChild("Level") :: IntValue?
	if cash then
		cash.Value = data.Cash
	end
	if level then
		level.Value = data.Level
	end
end

function EconomyService.cashMultiplier(player: Player): number
	local data = DataService.get(player)
	local m = 1
	if MonetizationService.owns(player, "Cash2x") then
		m *= Economy.CashMultiplier.Pass
	end
	if data and data.Boosts.Cash2xSeconds > 0 then
		m *= Economy.CashMultiplier.Boost
	end
	return math.min(m, Economy.CashMultiplier.Max)
end

function EconomyService.xpMultiplier(player: Player): number
	local data = DataService.get(player)
	local m = 1
	if MonetizationService.owns(player, "XP2x") then
		m *= Economy.XPMultiplier.Pass
	end
	if data and data.Boosts.XP2xSeconds > 0 then
		m *= Economy.XPMultiplier.Boost
	end
	return math.min(m, Economy.XPMultiplier.Max)
end

function EconomyService.cash(player: Player): number
	local data = DataService.get(player)
	return if data then data.Cash else 0
end

-- Pays the player. `boosted` = apply 2x (true for earnings; false for refunds, purchases, story grants).
-- Returns the amount actually paid. `at` (optional) = world position for the "+$8" pop.
function EconomyService.addCash(player: Player, amount: number, reason: string, boosted: boolean?, at: Vector3?): number
	local data = DataService.get(player)
	if not data or type(amount) ~= "number" or amount ~= amount or amount <= 0 then
		return 0
	end
	local paid = math.floor(amount * (if boosted == false then 1 else EconomyService.cashMultiplier(player)) + 0.5)
	data.Cash = math.min(data.Cash + paid, Economy.MaxCash)
	data.Stats.Earned += paid
	syncLeaderstats(player, data)
	Analytics.cash(player, true, paid, data.Cash, reason)
	EconomyService.CashChanged:Fire(player, data.Cash, paid, reason)
	Net.get("Reward"):FireClient(player, { cash = paid, at = at, reason = reason })
	DataService.push(player)
	return paid
end

-- Takes money if the player has enough. Returns true on success.
function EconomyService.spend(player: Player, amount: number, reason: string): boolean
	local data = DataService.get(player)
	if not data or type(amount) ~= "number" or amount ~= amount or amount < 0 then
		return false
	end
	amount = math.floor(amount)
	if data.Cash < amount then
		return false
	end
	data.Cash -= amount
	data.Stats.Spent += amount
	syncLeaderstats(player, data)
	Analytics.cash(player, false, amount, data.Cash, reason)
	EconomyService.CashChanged:Fire(player, data.Cash, -amount, reason)
	DataService.push(player)
	return true
end

-- Gives XP (2x applied). Returns the XP given and whether the player levelled up.
function EconomyService.addXP(player: Player, amount: number, reason: string, at: Vector3?): (number, boolean)
	local data = DataService.get(player)
	if not data or type(amount) ~= "number" or amount ~= amount or amount <= 0 then
		return 0, false
	end
	local given = math.floor(amount * EconomyService.xpMultiplier(player) + 0.5)
	local level, xp, gained = LevelRules.add(data.Level, data.XP, given)
	data.Level, data.XP = level, xp
	syncLeaderstats(player, data)
	Net.get("Reward"):FireClient(player, { xp = given, at = at, reason = reason })
	for _, l in gained do
		log(player.Name, "reached level", l)
		player:SetAttribute("MTL_Level", l)
		Net.get("LevelUp"):FireClient(player, { level = l, unlocks = LevelRules.unlocks(l) })
		EconomyService.LevelUp:Fire(player, l)
	end
	DataService.push(player)
	return given, #gained > 0
end

local function onReady(player: Player, data: any)
	local ls = Instance.new("Folder")
	ls.Name = "leaderstats"
	local cash = Instance.new("IntValue")
	cash.Name = "Cash"
	cash.Parent = ls
	local level = Instance.new("IntValue")
	level.Name = "Level"
	level.Parent = ls
	ls.Parent = player
	player:SetAttribute("MTL_Level", data.Level)
	syncLeaderstats(player, data)

	-- Bridge for older scripts that change leaderstats.Cash directly (the existing StockMarket): any change we
	-- didn't make becomes a real cash change here, so the save stays the truth. (Server-only value: clients can't
	-- write it.) Our own writes always set Value == data.Cash, so they're ignored.
	-- Reads cash.Value NOW rather than the event's argument: with deferred events, two of our own writes in one
	-- frame would otherwise look like an outside change.
	cash.Changed:Connect(function()
		local value = cash.Value
		local d = DataService.get(player)
		if not d or value == d.Cash then
			return
		end
		local delta = value - d.Cash
		if delta > 0 then
			EconomyService.addCash(player, delta, "Stocks:Sell", false)
		elseif not EconomyService.spend(player, -delta, "Stocks:Buy") then
			syncLeaderstats(player, d) -- tried to spend more than they have: put the real number back
		end
	end)
end

function EconomyService.init()
	DataService.Ready:Connect(onReady)

	-- Boosts count down in PLAY time only (no real-time timers), and play time is tracked.
	task.spawn(function()
		while true do
			task.wait(5)
			for _, player in Players:GetPlayers() do
				local data = DataService.get(player)
				if data then
					data.Stats.PlayTime += 5
					local b = data.Boosts
					local before = b.XP2xSeconds > 0 or b.Cash2xSeconds > 0
					b.XP2xSeconds = math.max(0, b.XP2xSeconds - 5)
					b.Cash2xSeconds = math.max(0, b.Cash2xSeconds - 5)
					if before then
						DataService.push(player)
					end
				end
			end
		end
	end)
end

-- The existing StockMarket script reads/writes leaderstats.Cash. That works as-is through the bridge in onReady
-- (Jobs piece). Cleaner, when someone has Studio open: point its getCash/setCash here instead:
--   getCash = function(p) return EconomyService.cash(p) end
--   setCash = function(p, v) local d = v - EconomyService.cash(p)
--     if d > 0 then EconomyService.addCash(p, d, "Stocks:Sell", false) elseif d < 0 then EconomyService.spend(p, -d, "Stocks:Buy") end end

return EconomyService
]======])
put("ServerScriptService/MTL/Services", "GoalService", "ModuleScript", [======[--!strict
-- Story Piece 4: FreePlay goals (Master Plan §1 stage 13). Config/Goals + Rules/GoalRules do the thinking; this
-- service, for players in FreePlay:
--   * keeps the HUD objective line on the top unfinished goal ("Goal: Turn the power on  ($120 / $300)")
--   * rewards each goal ONCE when it's first done (XP through EconomyService, so 2x XP applies; saved in
--     Goals.Done[id] before anything is paid, so it can never pay twice) with a banner
-- The phone's Goals app (Apps/Goals.lua) shows the full list from the same rules.
--   GoalService.refresh(player)   re-check now (other systems may call it after a big change)
--   GoalService.GoalDone: Signal(player, goalId)
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Signal = require(ReplicatedStorage.MTL.Signal)
local Goals = require(ReplicatedStorage.MTL.Config.Goals)
local GoalRules = require(ReplicatedStorage.MTL.Rules.GoalRules)
local DataService = require(script.Parent.DataService)
local EconomyService = require(script.Parent.EconomyService)
local StoryService = require(script.Parent.StoryService)
local Notify = require(script.Parent.Notify)

local GoalService = {}
GoalService.GoalDone = Signal.new() -- (player, goalId)

local lastObjective: { [Player]: string } = {}
local CHECK_EVERY = 1.5

local function log(...)
	print("[MTL Goals]", ...)
end

function GoalService.refresh(player: Player)
	if StoryService.stage(player) ~= "FreePlay" then
		lastObjective[player] = nil
		return
	end
	local d = DataService.get(player)
	if not d then
		return
	end
	d.Goals = d.Goals or { Done = {} }
	d.Goals.Done = d.Goals.Done or {}
	local fresh = GoalRules.newlyDone(d)
	if #fresh > 0 then
		local xp = 0
		for _, e in fresh do
			d.Goals.Done[e.id] = os.time() -- recorded first: never paid twice
		end
		DataService.push(player)
		for _, e in fresh do
			if e.reward > 0 then
				xp += EconomyService.addXP(player, e.reward, "Goal:" .. e.id)
			end
			GoalService.GoalDone:Fire(player, e.id)
			log(player.Name, "goal done", e.id)
		end
		if #fresh == 1 then
			Notify.banner(player, "GOAL DONE", fresh[1].title .. (if xp > 0 then ("  ·  +" .. xp .. " XP") else ""))
		else
			Notify.banner(player, "GOALS DONE", #fresh .. " goals" .. (if xp > 0 then ("  ·  +" .. xp .. " XP") else ""))
		end
	end
	local text = GoalRules.objective(d, Goals.ObjectivePrefix)
	if text ~= lastObjective[player] then
		lastObjective[player] = text
		Notify.objective(player, text)
	end
end

function GoalService.init()
	StoryService.onEnter("FreePlay", function(player)
		lastObjective[player] = nil
		task.wait(1)
		GoalService.refresh(player)
	end)
	Players.PlayerRemoving:Connect(function(player)
		lastObjective[player] = nil
	end)
	task.spawn(function()
		while true do
			task.wait(CHECK_EVERY)
			for _, player in Players:GetPlayers() do
				local ok, err = pcall(GoalService.refresh, player)
				if not ok then
					warn("[MTL Goals] refresh failed:", err)
				end
			end
		end
	end)
	log("ready:", #Goals.List, "goals")
end

return GoalService
]======])
put("ServerScriptService/MTL/Services", "GunModels", "ModuleScript", [======[--!strict
-- Gun models for GunService (Piece 5). Real model if Alex put one in ReplicatedStorage.MTL_Assets.Guns.<Model>,
-- otherwise a clean placeholder built from parts (dark metal, readable silhouette per gun type).
--
-- A real model needs: a BasePart named "Handle" (the grip), an Attachment named "Muzzle" anywhere inside
-- (barrel tip, its -Z/LookVector pointing out of the barrel), optionally an Attachment "Grip" in the Handle
-- (where the palm sits). The barrel should point along the Handle's LookVector (-Z). Every part is welded
-- to the Handle here and made massless / non-colliding / non-queryable, so they never block bullets or physics.
--
-- Sounds: Fire, Tail, Empty, ReloadStart, ReloadEnd, Equip are created in the Handle from Config/Guns.Sounds
-- (or the gun's own Sounds table). The client plays them locally.
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Guns = require(ReplicatedStorage.MTL.Config.Guns)

local GunModels = {}

local METAL = Color3.fromRGB(32, 33, 37)
local METAL_LIGHT = Color3.fromRGB(58, 60, 66)
local WOOD = Color3.fromRGB(105, 66, 38)

local function part(model: Model, name: string, size: Vector3, cf: CFrame, color: Color3?, material: Enum.Material?): Part
	local p = Instance.new("Part")
	p.Name = name
	p.Size = size
	p.CFrame = cf
	p.Color = color or METAL
	p.Material = material or Enum.Material.Metal
	p.TopSurface = Enum.SurfaceType.Smooth
	p.BottomSurface = Enum.SurfaceType.Smooth
	p.Parent = model
	return p
end

-- All placeholder shapes are laid out with the barrel along -Z and the grip (Handle) at the origin.
local SHAPES: { [string]: (Model) -> (Vector3) } = {
	Pistol = function(m)
		part(m, "Slide", Vector3.new(0.24, 0.26, 1.05), CFrame.new(0, 0.32, -0.32), METAL_LIGHT)
		part(m, "Frame", Vector3.new(0.22, 0.14, 0.8), CFrame.new(0, 0.14, -0.25))
		part(m, "Guard", Vector3.new(0.06, 0.16, 0.3), CFrame.new(0, 0.0, -0.22))
		return Vector3.new(0, 0.32, -0.88)
	end,
	Revolver = function(m)
		part(m, "Barrel", Vector3.new(0.18, 0.2, 1.1), CFrame.new(0, 0.34, -0.6), METAL_LIGHT)
		local cyl = part(m, "Cylinder", Vector3.new(0.36, 0.34, 0.34), CFrame.new(0, 0.26, -0.12) * CFrame.Angles(0, math.rad(90), 0))
		cyl.Shape = Enum.PartType.Cylinder
		part(m, "Frame", Vector3.new(0.2, 0.18, 0.5), CFrame.new(0, 0.16, -0.05))
		return Vector3.new(0, 0.34, -1.16)
	end,
	Uzi = function(m)
		part(m, "Body", Vector3.new(0.28, 0.34, 1.0), CFrame.new(0, 0.3, -0.25), METAL_LIGHT)
		part(m, "Barrel", Vector3.new(0.12, 0.12, 0.35), CFrame.new(0, 0.32, -0.92))
		part(m, "Mag", Vector3.new(0.16, 0.6, 0.2), CFrame.new(0, -0.35, 0.02))
		return Vector3.new(0, 0.32, -1.1)
	end,
	Shotgun = function(m)
		part(m, "Receiver", Vector3.new(0.26, 0.32, 0.9), CFrame.new(0, 0.26, -0.3), METAL_LIGHT)
		part(m, "Barrel", Vector3.new(0.14, 0.14, 2.1), CFrame.new(0, 0.36, -1.75))
		part(m, "Pump", Vector3.new(0.22, 0.2, 0.7), CFrame.new(0, 0.18, -1.45), WOOD, Enum.Material.Wood)
		part(m, "Stock", Vector3.new(0.22, 0.38, 1.1), CFrame.new(0, 0.12, 0.75) * CFrame.Angles(math.rad(-8), 0, 0), WOOD, Enum.Material.Wood)
		return Vector3.new(0, 0.36, -2.8)
	end,
	AK = function(m)
		part(m, "Receiver", Vector3.new(0.26, 0.34, 1.3), CFrame.new(0, 0.28, -0.35), METAL_LIGHT)
		part(m, "Barrel", Vector3.new(0.1, 0.1, 1.3), CFrame.new(0, 0.34, -1.6))
		part(m, "Handguard", Vector3.new(0.22, 0.22, 0.7), CFrame.new(0, 0.26, -1.25), WOOD, Enum.Material.Wood)
		part(m, "Mag", Vector3.new(0.16, 0.7, 0.26), CFrame.new(0, -0.2, -0.55) * CFrame.Angles(math.rad(18), 0, 0))
		part(m, "Stock", Vector3.new(0.2, 0.36, 1.0), CFrame.new(0, 0.16, 0.8) * CFrame.Angles(math.rad(-6), 0, 0), WOOD, Enum.Material.Wood)
		return Vector3.new(0, 0.34, -2.28)
	end,
}

local function weldAll(model: Model, handle: BasePart)
	for _, d in model:GetDescendants() do
		if d:IsA("BasePart") then
			d.Anchored = false
			d.CanCollide = false
			d.CanQuery = false
			d.CanTouch = false
			d.Massless = true
			d.CastShadow = d == handle or d.Size.Magnitude > 0.6
			if d ~= handle then
				local hasWeld = false
				for _, w in d:GetChildren() do
					if (w:IsA("WeldConstraint") or w:IsA("Weld")) then
						hasWeld = true
					end
				end
				if not hasWeld then
					local w = Instance.new("WeldConstraint")
					w.Part0 = handle
					w.Part1 = d
					w.Parent = d
				end
			end
		end
	end
end

local function addSounds(handle: BasePart, gunId: string)
	local def = Guns.Defs[gunId]
	local own = (def and def.Sounds) or {}
	for slot, default in Guns.Sounds do
		if slot == "Hit" or slot == "Kill" or slot == "Hurt" then
			continue -- UI sounds, played by the client from Config/Guns directly
		end
		local id = own[slot] or default
		if id ~= "" and not handle:FindFirstChild(slot) then
			local s = Instance.new("Sound")
			s.Name = slot
			s.SoundId = id
			s.Volume = if slot == "Fire" then 0.8 else 0.5
			s.RollOffMode = Enum.RollOffMode.InverseTapered
			s.RollOffMinDistance = if slot == "Tail" then 60 else 12
			s.RollOffMaxDistance = if slot == "Tail" then 900 else 350
			s.Parent = handle
		end
	end
end

local function placeholder(gunId: string, shape: string): Model
	local m = Instance.new("Model")
	m.Name = gunId
	local handle = part(m, "Handle", Vector3.new(0.2, 0.55, 0.3), CFrame.new(0, -0.05, 0.05))
	local build = SHAPES[shape] or SHAPES.Pistol
	local muzzlePos = build(m)
	local muzzle = Instance.new("Attachment")
	muzzle.Name = "Muzzle"
	muzzle.CFrame = handle.CFrame:ToObjectSpace(CFrame.new(muzzlePos))
	muzzle.Parent = handle
	local grip = Instance.new("Attachment")
	grip.Name = "Grip"
	grip.CFrame = handle.CFrame:ToObjectSpace(CFrame.new(0, 0.05, 0.05)) -- palm a little above the grip centre
	grip.Parent = handle
	m.PrimaryPart = handle
	return m
end

-- Returns a fresh, unparented model with Handle (PrimaryPart), Muzzle + Grip attachments and sounds.
function GunModels.build(gunId: string): Model
	local def = Guns.Defs[gunId]
	local shape = (def and def.Model) or "Pistol"
	local assets = ReplicatedStorage:FindFirstChild("MTL_Assets")
	local folder = assets and assets:FindFirstChild("Guns")
	local source = folder and folder:FindFirstChild(shape)
	local model: Model
	if source and source:IsA("Model") and source:FindFirstChild("Handle", true) then
		model = source:Clone()
		model.Name = gunId
	else
		model = placeholder(gunId, shape)
	end
	local handle = model:FindFirstChild("Handle", true) :: BasePart
	model.PrimaryPart = handle
	if not model:FindFirstChild("Muzzle", true) then
		local a = Instance.new("Attachment")
		a.Name = "Muzzle"
		a.Position = Vector3.new(0, 0.3, -1)
		a.Parent = handle
	end
	if not handle:FindFirstChild("Grip") then
		local a = Instance.new("Attachment")
		a.Name = "Grip"
		a.Parent = handle
	end
	weldAll(model, handle)
	addSounds(handle, gunId)
	model:SetAttribute("MTL_GunId", gunId)
	return model
end

return GunModels
]======])
put("ServerScriptService/MTL/Services", "GunService", "ModuleScript", [======[--!strict
-- Guns (Piece 5): owning, equipping and holstering guns, ammo and reloads, and the server side of every shot.
-- The server owns every decision. The client (GunController) predicts ammo and draws effects at once, then sends
-- GunFire; this service checks it (holding that gun, ammo, fire rate, muzzle near the head, aim cone, range,
-- lag-compensated hitbox, no wall in between, path + safe-zone rules) and only then deals damage and confirms
-- the hit back to the shooter (hitmarker). Research: [[Gun Mechanics]].
--
-- API (Master Plan §3.5):
--   GunService.give(player, gunId, opts?) -> ok     opts = { temporary = true, mode = "Intimidate"|"Live", ammo = n }
--       temporary guns are never saved; removed by take(), on MissionDone (story) or when the player leaves.
--       permanent: adds the gun to Inventory.Guns (+ opts.ammo rounds of its ammo type, full mag).
--   GunService.take(player, gunId)                  removes a temporary gun (or a permanent one if no temp exists)
--   GunService.lend(player, gunId, opts) / GunService.unlend(player)   aliases for missions (temporary Intimidate)
--   GunService.equip(player, gunId, force?) -> ok, reason   force = skip path / shift / safe-zone checks
--   GunService.holster(player, reason?)
--   GunService.equipped(player) -> gunId?, mode?
--   GunService.owns(player, gunId) -> bool
--   GunService.addAmmo(player, ammoType, n) -> added
--   GunService.isInFight(player) -> bool             shot at / hit by a player in the last Tuning.FightSeconds
--   GunService.inSafeZone(player) -> bool, zoneId?
--   GunService.addFireGuard(fn(player, gunId) -> (ok, reason?))
--   Signals: Equipped(player, gunId, mode) · Holstered(player, gunId, reason) · Fired(player, gunId, hitPos, hitModel?)
--            Damaged(attacker, victimModel, damage, head, killed) · Killed(attacker, victimModel)
--            Intimidating(player, targetModel, heldSeconds)   ~4x/s while aiming at a model tagged MTL_Intimidate
--   NPCs: a Humanoid model takes damage only if it has attribute MTL_Damageable = true.
--   Player attributes: character MTL_Gun = equipped gun id ("" when holstered), MTL_GunMode, MTL_Aiming, MTL_AimPitch.
--
-- Wired here: Criminal path to use live guns; holster on clock-in, on Civilian switch, in safe zones and in
-- cutscenes (client asks); no path switch / clock-in mid-fight; the starter Pistol on Config/Guns.Starter stage;
-- Plug app phone actions buyGun{gun} / buyAmmo{ammo}.
local CollectionService = game:GetService("CollectionService")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")

local Net = require(ReplicatedStorage.MTL.Net)
local Signal = require(ReplicatedStorage.MTL.Signal)
local Guns = require(ReplicatedStorage.MTL.Config.Guns)
local Locations = require(ReplicatedStorage.MTL.Config.Locations)
local GunRules = require(ReplicatedStorage.MTL.Rules.GunRules)
local DataService = require(script.Parent.DataService)
local EconomyService = require(script.Parent.EconomyService)
local StoryService = require(script.Parent.StoryService)
local PhoneService = require(script.Parent.PhoneService)
local JobService = require(script.Parent.JobService)
local Notify = require(script.Parent.Notify)
local RateLimiter = require(script.Parent.RateLimiter)
local GunModels = require(script.Parent.GunModels)

local GunService = {}
GunService.Equipped = Signal.new()
GunService.Holstered = Signal.new()
GunService.Fired = Signal.new()
GunService.Damaged = Signal.new()
GunService.Killed = Signal.new()
GunService.Intimidating = Signal.new()

local T = Guns.Tuning
local MODEL_NAME = "MTL_Gun"
local GRIP_NAME = "MTL_GunGrip"
local DANGER = Color3.fromRGB(255, 86, 96)

type Temp = { mode: string, mag: number, reserve: number }
type Live = {
	equipped: string?,
	mode: string,
	equippedAt: number,
	selected: string?, -- last gun taken out (shown in the holster)
	temp: { [string]: Temp },
	reload: { gun: string, untilT: number, prevMag: number, prevReserve: number }?,
	bucket: any,
	lastCombat: number?,
	aiming: boolean,
	aimPitch: number,
	aimTarget: Instance?,
	aimSince: number,
	lastPing: number,
	lastSafeToast: number,
}

local live: { [Player]: Live } = {}
local fireGuards: { (Player, string) -> (boolean, string?) } = {}
local history: { [Player]: { times: { number }, cfs: { CFrame } } } = {}

local fireLimiter = RateLimiter.new(30, 12)
local actionLimiter = RateLimiter.new(6, 6)
local aimLimiter = RateLimiter.new(T.AimSendHz * 2, T.AimSendHz * 2)

local function log(...)
	print("[MTL Guns]", ...)
end

local function now(): number
	return Workspace:GetServerTimeNow()
end

local function state(player: Player): Live
	local s = live[player]
	if not s then
		s = {
			equipped = nil,
			mode = "Live",
			equippedAt = 0,
			selected = nil,
			temp = {},
			reload = nil,
			bucket = GunRules.newBucket(T.FireBurst, now()),
			lastCombat = nil,
			aiming = false,
			aimPitch = 0,
			aimTarget = nil,
			aimSince = 0,
			lastPing = 0,
			lastSafeToast = -1e9,
		}
		live[player] = s
	end
	return s
end

local function isVector3(v: any): boolean
	return typeof(v) == "Vector3" and v.X == v.X and v.Y == v.Y and v.Z == v.Z and v.Magnitude < 1e6
end

local function character(player: Player): (Model?, Humanoid?, BasePart?)
	local char = player.Character
	if not char then
		return nil, nil, nil
	end
	local hum = char:FindFirstChildOfClass("Humanoid")
	local root = char:FindFirstChild("HumanoidRootPart") :: BasePart?
	return char, hum, root
end

local function alive(player: Player): boolean
	local _, hum, root = character(player)
	return hum ~= nil and root ~= nil and hum.Health > 0
end

---------------------------------------------------------------- ownership + ammo

function GunService.owns(player: Player, gunId: string): boolean
	if state(player).temp[gunId] then
		return true
	end
	local data = DataService.get(player)
	return data ~= nil and data.Inventory.Guns[gunId] == true
end

local function modeOf(player: Player, gunId: string): string
	local t = state(player).temp[gunId]
	return if t then t.mode else "Live"
end

local function getMag(player: Player, gunId: string): number
	local t = state(player).temp[gunId]
	if t then
		return t.mag
	end
	local data = DataService.get(player)
	return if data then (data.Inventory.Mags[gunId] or 0) else 0
end

local function setMag(player: Player, gunId: string, n: number)
	local t = state(player).temp[gunId]
	if t then
		t.mag = n
		return
	end
	local data = DataService.get(player)
	if data then
		data.Inventory.Mags[gunId] = n
	end
end

local function getReserve(player: Player, gunId: string): number
	local t = state(player).temp[gunId]
	if t then
		return t.reserve
	end
	local data = DataService.get(player)
	local def = Guns.Defs[gunId]
	return if data and def then (data.Inventory.Ammo[def.Ammo] or 0) else 0
end

local function setReserve(player: Player, gunId: string, n: number)
	local t = state(player).temp[gunId]
	if t then
		t.reserve = n
		return
	end
	local data = DataService.get(player)
	local def = Guns.Defs[gunId]
	if data and def then
		data.Inventory.Ammo[def.Ammo] = n
	end
end

-- Guns this player can pick from, in Config order (temporary ones included).
local function gunList(player: Player): { string }
	local out = {}
	for _, id in Guns.Order do
		if GunService.owns(player, id) then
			table.insert(out, id)
		end
	end
	return out
end

local function sendState(player: Player)
	local s = state(player)
	local list = {}
	for _, id in gunList(player) do
		table.insert(list, {
			id = id,
			mode = modeOf(player, id),
			temp = s.temp[id] ~= nil,
			mag = getMag(player, id),
			reserve = getReserve(player, id),
		})
	end
	local reload = s.reload
	Net.get("GunState"):FireClient(player, {
		equipped = s.equipped,
		mode = if s.equipped then s.mode else nil,
		guns = list,
		reloading = if reload and reload.untilT > now() then reload.gun else nil,
	})
end
GunService.sendState = sendState

---------------------------------------------------------------- safe zones

local zoneCenters: { { id: string, pos: Vector3, radius: number, height: number } } = {}

local function buildZones()
	table.clear(zoneCenters)
	for _, z in Guns.SafeZones do
		local loc = (Locations :: any)[z.location]
		local pos = if typeof(loc) == "Vector3" then loc elseif type(loc) == "table" then loc[z.field or "Door"] else nil
		if typeof(pos) == "Vector3" then
			table.insert(zoneCenters, { id = z.id, pos = pos, radius = z.radius, height = z.height or 20 })
		else
			warn("[MTL Guns] safe zone", z.id, "has no position in Config/Locations")
		end
	end
end

local function pointSafe(p: Vector3): (boolean, string?)
	for _, z in zoneCenters do
		if GunRules.inZone(p.X, p.Y, p.Z, z.pos.X, z.pos.Y, z.pos.Z, z.radius, z.height) then
			return true, z.id
		end
	end
	for _, part in CollectionService:GetTagged("MTL_SafeZone") do
		if part:IsA("BasePart") then
			local l = part.CFrame:PointToObjectSpace(p)
			local h = part.Size / 2
			if GunRules.boxDistance(l.X, l.Y, l.Z, h.X, h.Y, h.Z) <= 0 then
				return true, part:GetAttribute("ZoneId") or part.Name
			end
		end
	end
	return false, nil
end

function GunService.inSafeZone(player: Player): (boolean, string?)
	if JobService.isOnShift(player) then
		return true, "Shift"
	end
	local _, _, root = character(player)
	if not root then
		return false, nil
	end
	return pointSafe(root.Position)
end

local function path(player: Player): string
	local data = DataService.get(player)
	return if data then data.Path else "Civilian"
end

---------------------------------------------------------------- models (hand / holster)

local function limbs(char: Model): (BasePart?, BasePart?, BasePart?)
	local hand = (char:FindFirstChild("RightHand") or char:FindFirstChild("Right Arm")) :: BasePart?
	local hip = (char:FindFirstChild("LowerTorso") or char:FindFirstChild("Torso")) :: BasePart?
	local back = (char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")) :: BasePart?
	return hand, hip, back
end

local function clearModel(char: Model?)
	if not char then
		return
	end
	local old = char:FindFirstChild(MODEL_NAME)
	if old then
		old:Destroy()
	end
end

-- Puts the selected gun in the hand (inHand) or on the hip/back.
local function placeModel(player: Player, gunId: string?, inHand: boolean)
	local char = character(player)
	if not char then
		return
	end
	local existing = char:FindFirstChild(MODEL_NAME) :: Model?
	if not gunId then
		clearModel(char)
		return
	end
	local model = existing
	if not model or model:GetAttribute("MTL_GunId") ~= gunId then
		clearModel(char)
		model = GunModels.build(gunId)
		assert(model)
		model.Name = MODEL_NAME
	end
	assert(model)
	local handle = model.PrimaryPart :: BasePart
	local grip = handle:FindFirstChild("Grip") :: Attachment?
	local hand, hip, back = limbs(char)
	local motor = handle:FindFirstChild(GRIP_NAME) :: Motor6D?
	if not motor then
		local m = Instance.new("Motor6D")
		m.Name = GRIP_NAME
		m.Part1 = handle
		m.Parent = handle
		motor = m
	end
	assert(motor)
	local def = Guns.Defs[gunId]
	if inHand and hand then
		local att = hand:FindFirstChild("RightGripAttachment") :: Attachment?
		local at = if att then att.Position elseif hand.Name == "Right Arm" then Vector3.new(0, -1, 0) else Vector3.new(0, -0.15, 0)
		motor.Part0 = hand
		motor.C0 = CFrame.new(at) * CFrame.Angles(math.rad(-90), 0, 0) -- barrel along the arm
	elseif def and def.Slot == "Primary" and back then
		motor.Part0 = back
		motor.C0 = CFrame.new(0, 0, 0.75) * CFrame.Angles(0, 0, math.rad(-40)) * CFrame.Angles(0, math.rad(90), 0)
	elseif hip then
		motor.Part0 = hip
		local side = if hip.Name == "Torso" then Vector3.new(1.05, -0.9, 0) else Vector3.new(1.0, -0.1, 0.05)
		motor.C0 = CFrame.new(side) * CFrame.Angles(math.rad(-90), 0, 0) -- barrel down, grip up
	end
	motor.C1 = if grip then grip.CFrame else CFrame.new()
	model.Parent = char
	char:SetAttribute("MTL_Gun", if inHand then gunId else "")
end

---------------------------------------------------------------- equip / holster

local function cancelReload(player: Player)
	local s = state(player)
	local r = s.reload
	if r and r.untilT > now() and GunService.owns(player, r.gun) then
		setMag(player, r.gun, r.prevMag) -- unequipped mid-reload: the reload didn't happen
		setReserve(player, r.gun, r.prevReserve)
	end
	s.reload = nil
end

function GunService.equipped(player: Player): (string?, string?)
	local s = live[player]
	if s and s.equipped then
		return s.equipped, s.mode
	end
	return nil, nil
end

function GunService.holster(player: Player, reason: string?)
	local s = state(player)
	local was = s.equipped
	if not was then
		return
	end
	cancelReload(player)
	s.equipped = nil
	s.aiming = false
	s.aimTarget = nil
	local char = player.Character
	if char then
		char:SetAttribute("MTL_GunMode", nil)
		char:SetAttribute("MTL_Aiming", false)
	end
	-- the holster shows a live gun only on the criminal path (story guns just disappear)
	local show = s.selected and GunService.owns(player, s.selected) and modeOf(player, s.selected) == "Live" and path(player) == "Criminal"
	placeModel(player, if show then s.selected else nil, false)
	DataService.push(player)
	sendState(player)
	GunService.Holstered:Fire(player, was, reason or "player")
end

function GunService.equip(player: Player, gunId: string, force: boolean?): (boolean, string?)
	local def = Guns.Defs[gunId]
	if not def then
		return false, "Unknown gun"
	end
	if not GunService.owns(player, gunId) then
		return false, "You don't have that"
	end
	local s = state(player)
	local mode = modeOf(player, gunId)
	if not force then
		local safe = GunService.inSafeZone(player)
		local ok, reason = GunRules.canEquip(path(player), mode, JobService.isOnShift(player) ~= nil, safe, alive(player))
		if not ok then
			return false, reason
		end
	elseif not alive(player) then
		return false, "You're down"
	end
	if s.equipped == gunId then
		return true, nil
	end
	if s.equipped then
		cancelReload(player)
	end
	s.equipped = gunId
	s.mode = mode
	s.selected = gunId
	s.equippedAt = now()
	placeModel(player, gunId, true)
	local char = player.Character
	if char then
		char:SetAttribute("MTL_GunMode", mode)
	end
	sendState(player)
	GunService.Equipped:Fire(player, gunId, mode)
	return true, nil
end

---------------------------------------------------------------- give / take / ammo

function GunService.give(player: Player, gunId: string, opts: { [string]: any }?): boolean
	local def = Guns.Defs[gunId]
	local data = DataService.get(player)
	if not def or not data then
		return false
	end
	local o = opts or {}
	local s = state(player)
	if o.temporary or o.noDamage then
		local mode = if o.noDamage then "Intimidate" else (o.mode or "Live")
		if not Guns.Modes[mode] then
			mode = "Intimidate"
		end
		s.temp[gunId] = { mode = mode, mag = math.min(def.Mag, o.ammo or def.Mag), reserve = math.max(0, (o.ammo or def.Mag) - def.Mag) }
	else
		data.Inventory.Guns[gunId] = true
		if data.Inventory.Mags[gunId] == nil then
			data.Inventory.Mags[gunId] = def.Mag
		end
		if o.ammo and o.ammo > 0 then
			GunService.addAmmo(player, def.Ammo, o.ammo)
		end
		DataService.push(player)
	end
	sendState(player)
	return true
end

function GunService.take(player: Player, gunId: string)
	local s = state(player)
	if s.equipped == gunId then
		GunService.holster(player, "taken")
	end
	if s.temp[gunId] then
		s.temp[gunId] = nil
	else
		local data = DataService.get(player)
		if data then
			data.Inventory.Guns[gunId] = nil
			data.Inventory.Mags[gunId] = nil
			DataService.push(player)
		end
	end
	if s.selected == gunId then
		s.selected = nil
		if not s.equipped then
			placeModel(player, nil, false)
		end
	end
	sendState(player)
end

local function takeTemporary(player: Player)
	local s = state(player)
	local ids = {}
	for id in s.temp do
		table.insert(ids, id)
	end
	for _, id in ids do
		GunService.take(player, id)
	end
end

-- Mission helpers (the Story thread's names): a temporary, no-damage gun.
function GunService.lend(player: Player, gunId: string, opts: { [string]: any }?): boolean
	local o = table.clone(opts or {})
	o.temporary = true
	if o.mode == nil then
		o.mode = if o.noDamage == false then "Live" else "Intimidate"
	end
	o.noDamage = nil
	return GunService.give(player, gunId, o)
end

function GunService.unlend(player: Player)
	takeTemporary(player)
end

function GunService.addAmmo(player: Player, ammoType: string, n: number): number
	local data = DataService.get(player)
	local pack = Guns.Ammo[ammoType]
	if not data or not pack or type(n) ~= "number" or n <= 0 then
		return 0
	end
	local have = data.Inventory.Ammo[ammoType] or 0
	local new = math.min(pack.Max, have + math.floor(n))
	data.Inventory.Ammo[ammoType] = new
	DataService.push(player)
	sendState(player)
	return new - have
end

---------------------------------------------------------------- fights / guards

function GunService.isInFight(player: Player): boolean
	local s = live[player]
	return s ~= nil and GunRules.inFight(s.lastCombat, now(), T.FightSeconds)
end

function GunService.addFireGuard(fn: (Player, string) -> (boolean, string?))
	table.insert(fireGuards, fn)
end

---------------------------------------------------------------- lag compensation

local function recordHistory()
	local t = now()
	local keep = math.ceil(T.HistorySeconds * T.HistoryHz) + 1
	for _, player in Players:GetPlayers() do
		local _, hum, root = character(player)
		if root and hum and hum.Health > 0 then
			local h = history[player]
			if not h then
				h = { times = {}, cfs = {} }
				history[player] = h
			end
			table.insert(h.times, t)
			table.insert(h.cfs, root.CFrame)
			while #h.times > keep do
				table.remove(h.times, 1)
				table.remove(h.cfs, 1)
			end
		end
	end
end

-- Root CFrames to test a hit against (rewound samples + now).
local function rootSamples(victim: Player?, root: BasePart, shotT: number): { CFrame }
	local out = { root.CFrame }
	if victim then
		local h = history[victim]
		if h then
			for _, i in GunRules.rewindSamples(h.times, shotT, now(), T.MaxRewind, T.RewindWindow) do
				table.insert(out, h.cfs[i])
			end
		end
	end
	return out
end

---------------------------------------------------------------- shooting

local function humanoidModel(inst: Instance): (Model?, Humanoid?)
	local cur: Instance? = inst
	while cur and cur ~= Workspace do
		if cur:IsA("Model") then
			local hum = cur:FindFirstChildOfClass("Humanoid")
			if hum then
				return cur, hum
			end
		end
		cur = cur.Parent
	end
	return nil, nil
end

local function characterList(): { Instance }
	local list = {}
	for _, p in Players:GetPlayers() do
		if p.Character then
			table.insert(list, p.Character)
		end
	end
	return list
end

local wallParams = RaycastParams.new()
wallParams.FilterType = Enum.RaycastFilterType.Exclude
wallParams.RespectCanCollide = true
wallParams.IgnoreWater = true

-- true if the map (not characters) blocks the line a -> b (with a little slack at the end).
local function blocked(a: Vector3, b: Vector3, extra: { Instance }?): boolean
	local list = characterList()
	for _, e in extra or {} do
		table.insert(list, e)
	end
	wallParams.FilterDescendantsInstances = list
	local d = b - a
	local len = d.Magnitude
	if len < 0.05 then
		return false
	end
	local hit = Workspace:Raycast(a, d.Unit * math.max(0, len - 1), wallParams)
	return hit ~= nil
end

type HitResult = { model: Model, hum: Humanoid, damage: number, head: boolean, pos: Vector3 }

-- Validates one claimed hit. Returns nil if anything is off.
local function checkHit(shooter: Player, s: Live, def: any, origin: Vector3, pos: Vector3, part: any, shotT: number): HitResult?
	if typeof(part) ~= "Instance" or not part:IsA("BasePart") or not part:IsDescendantOf(Workspace) then
		return nil
	end
	local model, hum = humanoidModel(part)
	if not model or not hum or hum.Health <= 0 or model == shooter.Character then
		return nil
	end
	local victim = Players:GetPlayerFromCharacter(model)
	local root = model:FindFirstChild("HumanoidRootPart") :: BasePart?
	if not root then
		return nil
	end
	-- rules first (cheap)
	local attackerSafe = GunService.inSafeZone(shooter)
	local targetSafe = if victim then (GunService.inSafeZone(victim)) else false
	local ok = GunRules.canDamage(s.mode, path(shooter), attackerSafe, {
		isPlayer = victim ~= nil,
		path = if victim then path(victim) else nil,
		safe = targetSafe,
		damageable = model:GetAttribute("MTL_Damageable") == true,
		self = victim == shooter,
	})
	if not ok then
		return nil
	end
	-- lag-compensated hitbox: the part's offset from the root now, applied to each rewound root
	local rel = root.CFrame:ToObjectSpace(part.CFrame)
	local half = part.Size / 2
	local head = part.Name == "Head"
	local tol = if head then T.HeadTolerance else T.BodyTolerance
	local best = math.huge
	for _, cf in rootSamples(victim, root, shotT) do
		local l = (cf * rel):PointToObjectSpace(pos)
		best = math.min(best, GunRules.boxDistance(l.X, l.Y, l.Z, half.X, half.Y, half.Z))
		if best <= tol then
			break
		end
	end
	if best > tol then
		log(shooter.Name, "hit rejected: off hitbox by", math.floor(best * 10) / 10)
		return nil
	end
	if blocked(origin, pos, { model }) then
		log(shooter.Name, "hit rejected: wall")
		return nil
	end
	local dmg = GunRules.damage(def, (pos - origin).Magnitude, head)
	if dmg <= 0 then
		return nil
	end
	return { model = model, hum = hum, damage = dmg, head = head, pos = pos }
end

local function fxTargets(origin: Vector3, except: Player): { Player }
	local out = {}
	for _, p in Players:GetPlayers() do
		if p ~= except then
			local _, _, root = character(p)
			if root and (root.Position - origin).Magnitude <= T.FxRange then
				table.insert(out, p)
			end
		end
	end
	return out
end

local function reject(player: Player, why: string)
	-- the client predicted a shot the server didn't take: resend the truth so its counter snaps back
	sendState(player)
	if RunService:IsStudio() then
		log(player.Name, "shot rejected:", why)
	end
end

local function onFire(player: Player, p: any)
	if not fireLimiter:allow(player) or type(p) ~= "table" then
		return
	end
	local s = live[player]
	if not s or not s.equipped or p.gun ~= s.equipped then
		return reject(player, "not holding that gun")
	end
	local gunId = s.equipped :: string
	local def = Guns.Defs[gunId]
	local t = now()
	if not isVector3(p.origin) or not isVector3(p.dir) or type(p.t) ~= "number" or type(p.rays) ~= "table" then
		return reject(player, "bad payload")
	end
	local origin: Vector3, dir: Vector3 = p.origin, p.dir
	if dir.Magnitude < 0.5 or dir.Magnitude > 1.5 then
		return reject(player, "bad dir")
	end
	dir = dir.Unit
	local rays = p.rays
	if #rays < 1 or #rays > (def.Pellets or 1) then
		return reject(player, "bad ray count")
	end
	local char, hum = character(player)
	if not char or not hum or hum.Health <= 0 then
		return
	end
	if t - s.equippedAt < def.EquipTime * T.EquipGrace then
		return reject(player, "still equipping")
	end
	local r = s.reload
	if r and r.untilT > t then
		return reject(player, "reloading")
	end
	local mag = getMag(player, gunId)
	if mag <= 0 then
		return reject(player, "empty")
	end
	if not GunRules.rateAllow(s.bucket, def, t, T.FireRateTolerance, T.FireBurst) then
		return reject(player, "too fast")
	end
	local head = char:FindFirstChild("Head") :: BasePart?
	if not head or (origin - head.Position).Magnitude > T.OriginTolerance then
		return reject(player, "origin far from head")
	end
	if blocked(head.Position, origin) then
		return reject(player, "origin through a wall")
	end
	if s.mode == "Live" then
		local safe = GunService.inSafeZone(player)
		if safe then
			GunService.holster(player, "safe")
			return reject(player, "safe zone")
		end
	end
	for _, guard in fireGuards do
		local ok, why = guard(player, gunId)
		if not ok then
			return reject(player, why or "guard")
		end
	end

	setMag(player, gunId, mag - 1)

	-- each ray: clamp it to the cone and range; validate hits
	local maxAngle = GunRules.maxSpread(def) + T.AngleTolerance
	local ends: { Vector3 } = {}
	local totals: { [Model]: HitResult } = {}
	local firstModel: Model? = nil
	for i = 1, #rays do
		local ray = rays[i]
		local pos = if type(ray) == "table" then ray.pos else nil
		if not isVector3(pos) then
			pos = origin + dir * def.Range
		end
		local v = pos - origin
		local dist = v.Magnitude
		local okCone = dist > 0.01 and GunRules.angle(v.X, v.Y, v.Z, dir.X, dir.Y, dir.Z) <= maxAngle
		if not okCone or dist > def.Range + 5 then
			pos = origin + dir * math.min(math.max(dist, 1), def.Range)
		else
			local hit = checkHit(player, s, def, origin, pos, if type(ray) == "table" then ray.part else nil, p.t)
			if hit then
				local acc = totals[hit.model]
				if acc then
					acc.damage += hit.damage
					acc.head = acc.head or hit.head
				else
					totals[hit.model] = hit
				end
				firstModel = firstModel or hit.model
			end
		end
		table.insert(ends, pos)
	end

	-- effects for everyone else
	local fx = { type = "shot", shooter = player, gun = gunId, origin = origin, ends = ends }
	for _, other in fxTargets(origin, player) do
		Net.get("GunFx"):FireClient(other, fx)
	end
	GunService.Fired:Fire(player, gunId, ends[1], firstModel)

	-- damage
	for model, hit in totals do
		local before = hit.hum.Health
		hit.hum:TakeDamage(hit.damage)
		local killed = before > 0 and hit.hum.Health <= 0
		local victim = Players:GetPlayerFromCharacter(model)
		hit.hum:SetAttribute("MTL_LastAttacker", player.UserId)
		if victim then
			s.lastCombat = t
			state(victim).lastCombat = t
			Net.get("GunFx"):FireClient(victim, { type = "hurt", from = origin, damage = hit.damage })
		end
		Net.get("GunFx"):FireClient(player, { type = "hit", pos = hit.pos, head = hit.head, kill = killed, damage = hit.damage })
		GunService.Damaged:Fire(player, model, hit.damage, hit.head, killed)
		if killed then
			GunService.Killed:Fire(player, model)
			if victim then
				Notify.toast(player, "You dropped " .. victim.DisplayName, DANGER)
			end
		end
	end
	if getMag(player, gunId) <= 0 then
		sendState(player)
	end
end

local function onReload(player: Player, p: any)
	if not actionLimiter:allow(player) or type(p) ~= "table" then
		return
	end
	local s = live[player]
	if not s or not s.equipped or p.gun ~= s.equipped then
		return
	end
	local gunId = s.equipped :: string
	local def = Guns.Defs[gunId]
	local t = now()
	if s.reload and s.reload.untilT > t then
		return
	end
	local mag, reserve = getMag(player, gunId), getReserve(player, gunId)
	if not GunRules.canReload(mag, def.Mag, reserve) then
		return sendState(player)
	end
	local newMag, newReserve = GunRules.reload(mag, def.Mag, reserve)
	s.reload = { gun = gunId, untilT = t + def.Reload * T.ReloadGrace, prevMag = mag, prevReserve = reserve }
	setMag(player, gunId, newMag)
	setReserve(player, gunId, newReserve)
	DataService.push(player)
	sendState(player)
end

local function onAction(player: Player, p: any)
	if not actionLimiter:allow(player) or type(p) ~= "table" then
		return
	end
	if p.type == "equip" and type(p.gun) == "string" then
		local ok, reason = GunService.equip(player, p.gun)
		if not ok then
			Notify.toast(player, reason or "Can't take that out right now")
			sendState(player)
		end
	elseif p.type == "holster" then
		GunService.holster(player, if p.reason == "cutscene" then "cutscene" else "player")
	elseif p.type == "sync" then
		sendState(player)
	end
end

---------------------------------------------------------------- aiming (pose + intimidation)

local aimParams = RaycastParams.new()
aimParams.FilterType = Enum.RaycastFilterType.Exclude
aimParams.IgnoreWater = true

local function validIntimidateTarget(player: Player, target: any): boolean
	if typeof(target) ~= "Instance" or not target:IsA("Model") or not CollectionService:HasTag(target, "MTL_Intimidate") then
		return false
	end
	local char, _, root = character(player)
	local head = char and char:FindFirstChild("Head") :: BasePart?
	local tRoot = (target:FindFirstChild("HumanoidRootPart") or target.PrimaryPart) :: BasePart?
	if not head or not root or not tRoot then
		return false
	end
	local d = tRoot.Position - head.Position
	if d.Magnitude > T.IntimidateRange then
		return false
	end
	local look = root.CFrame.LookVector
	if GunRules.angle(look.X, 0, look.Z, d.X, 0, d.Z) > T.IntimidateFacing then
		return false
	end
	aimParams.FilterDescendantsInstances = { char :: Instance }
	local hit = Workspace:Raycast(head.Position, d, aimParams)
	return hit == nil or hit.Instance:IsDescendantOf(target)
end

local function onAim(player: Player, p: any)
	if not aimLimiter:allow(player) or type(p) ~= "table" then
		return
	end
	local s = live[player]
	if not s or not s.equipped then
		return
	end
	local char = player.Character
	if not char then
		return
	end
	local aiming = p.aiming == true -- really aiming (intimidation needs this)
	local raised = aiming or p.raised == true -- arms up (aiming or just fired from the hip): pose for others
	local pitch = if type(p.pitch) == "number" and p.pitch == p.pitch then math.clamp(p.pitch, -80, 80) else 0
	if raised ~= s.aiming then
		s.aiming = raised
		char:SetAttribute("MTL_Aiming", raised)
	end
	if math.abs(pitch - s.aimPitch) >= 2 then
		s.aimPitch = pitch
		char:SetAttribute("MTL_AimPitch", math.floor(pitch + 0.5))
	end
	-- intimidation: continuous aim at the same tagged model
	local t = os.clock()
	local target = if aiming and validIntimidateTarget(player, p.target) then p.target else nil
	if target ~= s.aimTarget then
		s.aimTarget = target
		s.aimSince = t
		s.lastPing = 0
	end
	if target and t - s.lastPing >= T.IntimidatePing then
		s.lastPing = t
		GunService.Intimidating:Fire(player, target, t - s.aimSince)
	end
end

---------------------------------------------------------------- shop (Plug app)

local function onBuyGun(player: Player, p: any)
	local gunId = type(p) == "table" and p.gun
	local def = type(gunId) == "string" and Guns.Defs[gunId]
	local data = DataService.get(player)
	if not def or not data then
		return
	end
	local ok, why = GunRules.canBuyGun(def, data.Level, data.Cash, data.Path, data.Inventory.Guns[gunId] == true)
	if not ok then
		Notify.toast(player, why or "Can't buy that")
		return
	end
	if not EconomyService.spend(player, def.Price, "Shop:Gun:" .. gunId) then
		Notify.toast(player, "Not enough cash")
		return
	end
	GunService.give(player, gunId, { ammo = def.Mag * 2 })
	Notify.toast(player, def.Display .. " is yours. It's on your weapon bar.", Color3.fromRGB(64, 220, 160))
	log(player.Name, "bought", gunId)
end

local function onBuyAmmo(player: Player, p: any)
	local ammo = type(p) == "table" and p.ammo
	local pack = type(ammo) == "string" and Guns.Ammo[ammo]
	local data = DataService.get(player)
	if not pack or not data then
		return
	end
	local user = false
	for id in data.Inventory.Guns do
		local def = Guns.Defs[id]
		if def and def.Ammo == ammo then
			user = true
		end
	end
	local ok, why = GunRules.canBuyAmmo(pack, data.Inventory.Ammo[ammo] or 0, data.Cash, data.Path, user)
	if not ok then
		Notify.toast(player, why or "Can't buy that")
		return
	end
	if EconomyService.spend(player, pack.Price, "Shop:Ammo:" .. ammo) then
		GunService.addAmmo(player, ammo, pack.Count)
	end
end

---------------------------------------------------------------- lifecycle

local function onCharacter(player: Player, char: Model)
	local s = state(player)
	s.equipped = nil
	s.reload = nil
	s.aiming = false
	s.aimTarget = nil
	char:SetAttribute("MTL_Gun", "")
	local hum = char:WaitForChild("Humanoid", 10) :: Humanoid?
	if hum then
		hum.Died:Connect(function()
			if s.equipped then
				GunService.holster(player, "died")
			end
			clearModel(char)
		end)
	end
	-- show the last gun in the holster again
	task.wait(0.2)
	if player.Character == char and s.selected and GunService.owns(player, s.selected) and modeOf(player, s.selected) == "Live" and path(player) == "Criminal" then
		placeModel(player, s.selected, false)
	end
	sendState(player)
end

local function onReady(player: Player, data: any)
	-- the saved mag can't be more than the gun holds (config changes)
	for id in data.Inventory.Guns do
		local def = Guns.Defs[id]
		if not def then
			data.Inventory.Guns[id] = nil
		else
			data.Inventory.Mags[id] = math.clamp(data.Inventory.Mags[id] or def.Mag, 0, def.Mag)
		end
	end
	local s = state(player)
	for _, id in Guns.Order do
		if data.Inventory.Guns[id] then
			s.selected = s.selected or id
		end
	end
	if player.Character then
		task.spawn(onCharacter, player, player.Character)
	end
	player.CharacterAdded:Connect(function(c)
		onCharacter(player, c)
	end)
end

-- Auto-holster: live guns go away in safe zones, on shift, or off the criminal path.
local function watchdog()
	while true do
		task.wait(T.SafeCheckSeconds)
		for player, s in live do
			if s.equipped and s.mode == "Live" and player.Parent then
				local safe, zone = GunService.inSafeZone(player)
				if safe or path(player) ~= "Criminal" then
					GunService.holster(player, "safe")
					if os.clock() - s.lastSafeToast > 8 then
						s.lastSafeToast = os.clock()
						Notify.toast(player, if zone == "Shift" then "Gun away: you're on shift" elseif safe then "Safe zone: gun holstered" else "Gun away: Civilian lifestyle")
					end
				end
			end
		end
	end
end

function GunService.init()
	buildZones()
	Net.get("GunFire").OnServerEvent:Connect(onFire)
	Net.get("GunReload").OnServerEvent:Connect(onReload)
	Net.get("GunAction").OnServerEvent:Connect(onAction)
	Net.get("GunAim").OnServerEvent:Connect(onAim)
	DataService.Ready:Connect(onReady)

	local acc = 0
	RunService.Heartbeat:Connect(function(dt)
		acc += dt
		if acc >= 1 / T.HistoryHz then
			acc = 0
			recordHistory()
		end
	end)
	task.spawn(watchdog)

	Players.PlayerRemoving:Connect(function(player)
		live[player] = nil
		history[player] = nil
	end)

	-- path: Civilian puts guns away; no switching mid-fight
	PhoneService.addPathGuard(function(player)
		if GunService.isInFight(player) then
			return false, "You're in a fight. Wait a bit."
		end
		return true, nil
	end)
	PhoneService.PathChanged:Connect(function(player, new)
		if new ~= "Criminal" then
			local _, mode = GunService.equipped(player)
			if mode == "Live" then
				GunService.holster(player, "path")
			end
			local s = state(player)
			if not s.equipped then
				placeModel(player, nil, false)
			end
		else
			local s = state(player)
			if not s.equipped and s.selected and GunService.owns(player, s.selected) then
				placeModel(player, s.selected, false)
			end
		end
		sendState(player)
	end)

	-- jobs: no clock-in mid-fight; clocking in puts the gun away
	JobService.addShiftGuard(function(player)
		if GunService.isInFight(player) then
			return false, "You're in a fight. Lose them first."
		end
		return true, nil
	end)
	JobService.ClockedIn:Connect(function(player)
		local _, mode = GunService.equipped(player)
		if mode == "Live" then
			GunService.holster(player, "shift")
		end
	end)

	-- story: the crew hands you a real piece after the first job; mission guns go back
	local st = Guns.Starter
	if st.GrantOnStage ~= "" then
		StoryService.onEnter(st.GrantOnStage, function(player, resumed)
			takeTemporary(player)
			if resumed then
				return
			end
			if not GunService.owns(player, st.Gun) then
				GunService.give(player, st.Gun, { ammo = st.Ammo })
				Notify.toast(player, "Dre slid you a " .. Guns.Defs[st.Gun].Display .. ". Press 1 to take it out.", Color3.fromRGB(64, 220, 160))
			end
		end)
	end

	PhoneService.onAction("buyGun", onBuyGun)
	PhoneService.onAction("buyAmmo", onBuyAmmo)

	-- the Plug app appears once the player is on the criminal path (and stays)
	local function plug(player: Player)
		local data = DataService.get(player)
		if data and data.Path == "Criminal" and not data.Phone.Apps.Plug then
			PhoneService.unlockApp(player, "Plug")
		end
	end
	DataService.Ready:Connect(function(player, data)
		if data.Phone.Apps.Plug == nil then
			data.Phone.Apps.Plug = false -- not a default app: hidden until the criminal path (the phone hides false)
		end
		plug(player)
	end)
	PhoneService.PathChanged:Connect(plug)

	log("ready:", #Guns.Order, "guns,", #zoneCenters, "safe zones")
end

---------------------------------------------------------------- Studio helpers

-- _G.MTL.Guns.debug(p, "Uzi")  -> Criminal path, gun + 120 rounds, equipped (skips the story)
function GunService.debug(player: Player, gunId: string?)
	local id = gunId or "Pistol"
	PhoneService.setPath(player, "Criminal", true)
	GunService.give(player, id, { ammo = 120 })
	return GunService.equip(player, id, true)
end

-- _G.MTL.Guns.dummy(p)            -> a damageable target dummy 15 studs in front of you
-- _G.MTL.Guns.dummy(p, "clerk")   -> an MTL_Intimidate dummy (aim at it to see the Intimidating signal)
function GunService.dummy(player: Player, kind: string?): Model?
	local _, _, root = character(player)
	if not root then
		return nil
	end
	local ok, rig = pcall(function()
		return Players:CreateHumanoidModelFromDescription(Instance.new("HumanoidDescription"), Enum.HumanoidRigType.R15)
	end)
	if not ok or not rig then
		warn("[MTL Guns] couldn't make a dummy:", rig)
		return nil
	end
	rig.Name = if kind == "clerk" then "MTL_TestClerk" else "MTL_TestDummy"
	rig:PivotTo(CFrame.lookAt(root.Position + root.CFrame.LookVector * 15, root.Position))
	if kind == "clerk" then
		CollectionService:AddTag(rig, "MTL_Intimidate")
	else
		rig:SetAttribute("MTL_Damageable", true)
		local hum = rig:FindFirstChildOfClass("Humanoid")
		if hum then
			hum.Died:Connect(function()
				task.wait(3)
				rig:Destroy()
			end)
		end
	end
	rig.Parent = Workspace
	return rig
end

return GunService
]======])
put("ServerScriptService/MTL/Services", "JobService", "ModuleScript", [======[--!strict
-- Jobs (Piece 2): picking a job, clocking in/out, handing out tasks, checking them, paying for them.
-- The server owns every decision: which task, which station, whether you're close enough, whether the minigame
-- took long enough, how much it pays. The client (JobController) only draws markers/minigames and reports.
--
-- API (Master Plan §3.5):
--   JobService.isOnShift(player) -> jobId?
--   JobService.current(player) -> jobId?                  the job the player has picked (data.Job.Current)
--   JobService.setJob(player, jobId, force?) -> ok, reason the same check the phone's CHOOSE button runs
--   JobService.clockIn(player, force?) -> ok, reason       force = skip the distance check (story/debug)
--   JobService.clockOut(player, reason?)                   reason: "player" | "left" | "story" | "switch" | ...
--   JobService.workplace(player) -> (Vector3?, label?)     where the player's job is (for the commute funnel)
--   JobService.addShiftGuard(fn(player, jobId) -> (ok, reason?))   e.g. MissionService: no shifts mid-mission
--   Signals: ClockedIn(player, jobId) · ClockedOut(player, jobId, reason) · TaskDone(player, jobId, taskId, paid, xp)
--            ShiftDone(player, jobId, shiftEarned, bonus) · JobChosen(player, jobId, oldJobId)
--
-- Story hooks wired here: FirstShift (story job, auto clock-in in the store), ChooseJob ends when a job is picked,
-- CommuteToWork ends when the player clocks in at their job, BlockedStages end the shift (Config/Jobs).
local CollectionService = game:GetService("CollectionService")
local HttpService = game:GetService("HttpService")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Net = require(ReplicatedStorage.MTL.Net)
local Signal = require(ReplicatedStorage.MTL.Signal)
local Jobs = require(ReplicatedStorage.MTL.Config.Jobs)
local Locations = require(ReplicatedStorage.MTL.Config.Locations)
local JobRules = require(ReplicatedStorage.MTL.Rules.JobRules)
local StoryRules = require(ReplicatedStorage.MTL.Rules.StoryRules)
local Format = require(ReplicatedStorage.MTL.Format)
local DataService = require(script.Parent.DataService)
local EconomyService = require(script.Parent.EconomyService)
local StoryService = require(script.Parent.StoryService)
local PhoneService = require(script.Parent.PhoneService)
local WaypointService = require(script.Parent.WaypointService)
local Notify = require(script.Parent.Notify)
local Analytics = require(script.Parent.Analytics)
local RateLimiter = require(script.Parent.RateLimiter)

local JobService = {}
JobService.ClockedIn = Signal.new()
JobService.ClockedOut = Signal.new()
JobService.TaskDone = Signal.new()
JobService.ShiftDone = Signal.new()
JobService.JobChosen = Signal.new()

local V = Jobs.Validation
local rng = Random.new()
local function rand(): number
	return rng:NextNumber()
end

type Task = {
	id: number,
	key: string,
	step: number,
	stations: { string },
	items: { [number]: { string } },
	stepStartedAt: number,
	begunAt: number?,
	scores: { number },
}

type Shift = {
	job: string,
	session: string,
	startedAt: number,
	done: number,
	total: number,
	earned: number,
	complete: boolean,
	task: Task?,
	history: { string },
	lastStation: { [string]: string },
	waitingUntil: number?,
	leavingSince: number?,
	carry: string?,
	result: any?,
	-- post jobs
	postTimer: number,
	onPost: boolean,
	paused: boolean,
	checkInToken: string?,
	checkInDue: number,
}

local shifts: { [Player]: Shift } = {}
local guards: { (Player, string) -> (boolean, string?) } = {}
local taskCounter = 0
local limiter = RateLimiter.new(V.RatePerSecond, V.RatePerSecond * 2)

local function log(...)
	print("[MTL Jobs]", ...)
end

local function now(): number
	return os.clock()
end

---------------------------------------------------------------- positions

local function normal(s: string): string
	return (string.lower(s):gsub("[^%w]", ""))
end

-- The map's JobSpot parts (tagged by the Map thread, attribute Job = "Car Wash" ...) replace placeholder sites.
local function resolveMapSites()
	local spots = CollectionService:GetTagged("JobSpot")
	for jobId, def in Jobs.Defs do
		if not def.mapJob then
			continue
		end
		local wanted = {}
		for _, n in def.mapJob do
			wanted[normal(n)] = true
		end
		for _, spot in spots do
			local name = spot:GetAttribute("Job")
			if type(name) == "string" and wanted[normal(name)] then
				local pos = if spot:IsA("BasePart") then spot.Position elseif spot:IsA("Model") then spot:GetPivot().Position else nil
				local loc = Locations[def.site]
				if pos and type(loc) == "table" then
					local p = Vector3.new(pos.X, pos.Y + 1, pos.Z)
					loc.Inside, loc.Door, loc.Placeholder = p, p, false
					log("job site", jobId, "from map JobSpot", spot:GetFullName())
				end
				break
			end
		end
	end
end

local function siteCenter(jobId: string): Vector3
	local def = Jobs.Defs[jobId]
	local loc = Locations[def.site] :: any
	return loc.Inside or loc.Door
end

-- Returns position, radius, and the placeholder prop name (nil when a real map part marks the station).
local function station(jobId: string, stationId: string): (Vector3, number, string?)
	local def = Jobs.Defs[jobId]
	local cfg = def.stations[stationId]
	local folder = workspace:FindFirstChild("MTL_Stations")
	local jobFolder = folder and folder:FindFirstChild(jobId)
	local part = jobFolder and jobFolder:FindFirstChild(stationId)
	if part and part:IsA("BasePart") then
		local r = part:GetAttribute("Radius")
		local prop = part:GetAttribute("Prop") -- clear this attribute once a real map object stands there
		return part.Position, if type(r) == "number" then r else cfg.radius or 6, if type(prop) == "string" and prop ~= "" then prop else nil
	end
	if cfg.pos then
		return cfg.pos, cfg.radius or 6, cfg.prop
	end
	return siteCenter(jobId) + (cfg.offset or Vector3.zero), cfg.radius or 6, cfg.prop
end

local function root(player: Player): BasePart?
	local char = player.Character
	return char and char:FindFirstChild("HumanoidRootPart") :: BasePart?
end

local function flatDistance(a: Vector3, b: Vector3): number
	local d = a - b
	return Vector2.new(d.X, d.Z).Magnitude
end

local function near(player: Player, pos: Vector3, radius: number): boolean
	local r = root(player)
	if not r then
		return false
	end
	return flatDistance(r.Position, pos) <= radius + V.StationSlack and math.abs(r.Position.Y - pos.Y) <= 20
end

local function atSite(player: Player, jobId: string): boolean
	local r = root(player)
	if not r then
		return false
	end
	local clockPos = station(jobId, "TimeClock")
	return flatDistance(r.Position, siteCenter(jobId)) <= V.ClockInRadius or flatDistance(r.Position, clockPos) <= V.ClockInRadius
end

---------------------------------------------------------------- carry (a prop in your hands, everyone sees it)

local function removeCarry(player: Player, s: Shift)
	s.carry = nil
	local char = player.Character
	if not char then
		return
	end
	local prop = char:FindFirstChild("MTL_Carry")
	if prop then
		prop:Destroy()
	end
	local hum = char:FindFirstChildOfClass("Humanoid")
	local old = char:GetAttribute("MTL_WalkSpeedBeforeCarry")
	if hum and type(old) == "number" then
		hum.WalkSpeed = old
		char:SetAttribute("MTL_WalkSpeedBeforeCarry", nil)
	end
end

local function addCarry(player: Player, s: Shift, kind: string)
	removeCarry(player, s)
	local char = player.Character
	local r = root(player)
	local spec = Jobs.Carry.Props[kind]
	if not char or not r or not spec then
		return
	end
	s.carry = kind
	local part = Instance.new("Part")
	part.Name = "MTL_Carry"
	part.Shape = spec.shape or Enum.PartType.Block
	part.Size = spec.size
	part.Color = spec.color
	part.Material = spec.material or Enum.Material.SmoothPlastic
	part.CanCollide = false
	part.CanQuery = false
	part.CanTouch = false
	part.Massless = true
	local weld = Instance.new("Weld")
	weld.Part0 = r
	weld.Part1 = part
	weld.C0 = spec.offset or CFrame.new(0, 0.2, -1.5)
	weld.Parent = part
	-- A real model in ReplicatedStorage.MTL_JobProps.Carry.<kind> (pivot = its centre) replaces the plain part's look.
	local props = game:GetService("ReplicatedStorage"):FindFirstChild("MTL_JobProps")
	local template = props and props:FindFirstChild("Carry") and props.Carry:FindFirstChild(kind)
	if template and template:IsA("Model") then
		part.Transparency = 1
		part.CFrame = r.CFrame * weld.C0
		local m = template:Clone()
		m:PivotTo(part.CFrame)
		for _, d in m:GetDescendants() do
			if d:IsA("BasePart") then
				d.Anchored = false
				d.CanCollide, d.CanQuery, d.CanTouch = false, false, false
				d.Massless = true
				local wc = Instance.new("WeldConstraint")
				wc.Part0 = part
				wc.Part1 = d
				wc.Parent = d
			end
		end
		m.Parent = part
	end
	part:SetAttribute("Kind", kind)
	part.Parent = char
	local hum = char:FindFirstChildOfClass("Humanoid")
	if hum then
		char:SetAttribute("MTL_WalkSpeedBeforeCarry", hum.WalkSpeed)
		hum.WalkSpeed = math.min(hum.WalkSpeed, Jobs.Carry.WalkSpeed)
	end
end

---------------------------------------------------------------- state to the client

local function stationInfo(jobId: string, stationId: string): any
	local pos, radius, prop = station(jobId, stationId)
	return { id = stationId, pos = pos, radius = radius, prop = prop }
end

local function taskInfo(player: Player, s: Shift, t: Task): any
	local def = Jobs.Tasks[t.key]
	local step = def.steps[t.step]
	local data = DataService.get(player)
	local level = if data then data.Level else 1
	local doneBefore = if data then (data.Job.TasksDone[t.key] or 0) else 0
	local info: { [string]: any } = {
		id = t.id,
		key = t.key,
		title = def.title,
		step = t.step,
		steps = #def.steps,
		kind = step.kind,
		prompt = step.prompt,
		text = step.text,
		verb = step.verb,
		fx = step.fx,
		far = step.far,
		carrying = s.carry,
		station = stationInfo(s.job, t.stations[t.step]),
		hint = if doneBefore < 2 and t.step == 1 then def.hint else nil,
	}
	if step.kind == "hold" then
		info.seconds = JobRules.holdSeconds(step, level)
	elseif step.kind == "timing" then
		info.hits, info.zone, info.speed = step.hits or 3, step.zone or 0.22, step.speed or 1
	elseif step.kind == "sequence" then
		info.items = t.items[t.step]
		-- buttons: the ticket items plus (for big pools) a couple of decoys, shuffled
		local buttons = table.clone(info.items)
		if not step.keepOrder then
			for _, p in step.pool do
				if #buttons >= math.min(#step.pool, (step.count or 4) + 2) then
					break
				end
				if not table.find(buttons, p) then
					table.insert(buttons, p)
				end
			end
		end
		for i = #buttons, 2, -1 do
			local j = rng:NextInteger(1, i)
			buttons[i], buttons[j] = buttons[j], buttons[i]
		end
		info.buttons = buttons
	end
	return info
end

local function placeholderProps(jobId: string): { any }
	local out = {}
	for id in Jobs.Defs[jobId].stations do
		local pos, _, prop = station(jobId, id)
		if prop then
			table.insert(out, { id = id, prop = prop, pos = pos })
		end
	end
	return out
end

local function sendState(player: Player)
	local data = DataService.get(player)
	if not data or not player.Parent then
		return
	end
	local s = shifts[player]
	local jobId = if s then s.job else data.Job.Current
	local def = JobRules.def(jobId)
	if not def then
		Net.get("JobState"):FireClient(player, { job = nil })
		return
	end
	local st: { [string]: any } = {
		job = jobId,
		title = def.title,
		role = def.role,
		kind = def.kind,
		place = def.place,
		onShift = s ~= nil,
		clock = stationInfo(jobId, "TimeClock"),
		site = { pos = siteCenter(jobId), radius = V.ClockInRadius },
		props = placeholderProps(jobId),
		storyJob = data.Story.Stage == "FirstShift",
	}
	if s then
		st.shift = { done = s.done, total = s.total, earned = s.earned, complete = s.complete }
		if s.task then
			st.task = taskInfo(player, s, s.task)
		end
		if s.waitingUntil then
			st.waiting = math.max(0, s.waitingUntil - now())
		end
		if s.leavingSince then
			st.leaving = math.max(0, V.LeaveGrace - (now() - s.leavingSince))
		end
		if def.kind == "post" then
			local perMin = JobRules.perMinute(jobId, data.Level)
			st.post = { station = stationInfo(jobId, "Post"), onPost = s.onPost, paused = s.paused, checkIn = s.checkInToken, perMinute = perMin, payEvery = Jobs.Post.PayEvery, timer = s.postTimer }
		end
		st.result = s.result
		s.result = nil -- one-shot (the PERFECT flourish plays once)
	end
	Net.get("JobState"):FireClient(player, st)
end

---------------------------------------------------------------- tasks

local function assignTask(player: Player, s: Shift)
	local data = DataService.get(player)
	if not data then
		return
	end
	local key = JobRules.pickTask(s.job, data.Level, s.history, rand)
	if not key then
		s.task = nil
		return
	end
	table.insert(s.history, key)
	if #s.history > 6 then
		table.remove(s.history, 1)
	end
	taskCounter += 1
	local def = Jobs.Tasks[key]
	local t: Task = { id = taskCounter, key = key, step = 1, stations = {}, items = {}, stepStartedAt = now(), begunAt = nil, scores = {} }
	for i, step in def.steps do
		local memo = key .. "#" .. i
		t.stations[i] = JobRules.pickStation(step.at, s.lastStation[memo], rand)
		s.lastStation[memo] = t.stations[i]
		if step.kind == "sequence" then
			t.items[i] = JobRules.sequenceItems(step, rand)
		end
	end
	s.task = t
	s.waitingUntil = nil
end

local function bossText(player: Player, jobId: string, which: string)
	local def = Jobs.Defs[jobId]
	local lines = def.boss and Jobs.BossLines[def.boss]
	local line = lines and lines[which]
	if type(line) == "table" then
		line = line[rng:NextInteger(1, #line)]
	end
	if type(line) == "string" then
		PhoneService.text(player, def.boss, line)
	end
end

local function finishShift(player: Player, s: Shift)
	local data = DataService.get(player)
	if not data then
		return
	end
	s.complete = true
	s.task = nil
	s.waitingUntil = nil
	removeCarry(player, s)
	data.Job.Shifts[s.job] = (data.Job.Shifts[s.job] or 0) + 1
	local share = JobRules.shiftBonusShare(data.Level)
	local bonus = 0
	if share > 0 and s.earned > 0 then
		bonus = EconomyService.addCash(player, math.floor(s.earned * share + 0.5), "Job:ShiftBonus", false)
	end
	local sub = if bonus > 0 then ("+" .. Format.cash(bonus) .. " shift bonus")
		else ("Earned " .. Format.cash(s.earned) .. ". Shift bonus unlocks at Level " .. Jobs.Shift.BonusLevel)
	Notify.banner(player, "SHIFT COMPLETE", sub)
	local count = data.Job.Shifts[s.job]
	if count <= 2 or count % 3 == 0 then
		bossText(player, s.job, "ShiftDone")
	end
	Analytics.funnel(player, "Shift", s.session, 4, "ShiftDone")
	JobService.ShiftDone:Fire(player, s.job, s.earned, bonus)
	log(player.Name, "finished a shift at", s.job, "earned", s.earned, "bonus", bonus)
end

local function completeTask(player: Player, s: Shift, t: Task, at: Vector3)
	local data = DataService.get(player)
	if not data then
		return
	end
	local def = Jobs.Tasks[t.key]
	local score: number? = nil
	for _, sc in t.scores do
		score = if score then math.min(score, sc) else sc
	end
	local distance: number? = nil
	if def.distancePay then
		local a = station(s.job, t.stations[1])
		local b = station(s.job, t.stations[#def.steps])
		distance = flatDistance(a, b)
	end
	local pay, xp, label = JobRules.taskReward(t.key, data.Level, score, distance)
	removeCarry(player, s)
	local paid = EconomyService.addCash(player, pay, "Job:" .. s.job, true, at)
	local gotXP = EconomyService.addXP(player, xp, "Job:" .. s.job, at)
	s.earned += paid
	s.done += 1
	local before = data.Job.TasksDone[t.key] or 0
	data.Job.TasksDone[t.key] = before + 1
	s.result = { label = label, cash = paid, xp = gotXP, at = at, perfectBonus = label == "PERFECT" and data.Level >= Jobs.Quality.PerfectBonusLevel }
	JobService.TaskDone:Fire(player, s.job, t.key, paid, gotXP)
	if s.done == 1 then
		Analytics.funnel(player, "Shift", s.session, 2, "FirstTask")
		local total = 0
		for _, n in data.Job.TasksDone do
			total += n
		end
		if total == 1 then
			bossText(player, s.job, "FirstTask") -- the very first task in the game
		end
	elseif s.done == math.floor(s.total / 2) then
		Analytics.funnel(player, "Shift", s.session, 3, "HalfShift")
	end
	if s.done >= s.total then
		finishShift(player, s)
		return
	end
	local jobDef = Jobs.Defs[s.job]
	if jobDef.gap then
		s.task = nil
		s.waitingUntil = now() + rng:NextNumber(jobDef.gap[1], jobDef.gap[2])
	else
		assignTask(player, s)
	end
end

---------------------------------------------------------------- shifts

function JobService.isOnShift(player: Player): string?
	local s = shifts[player]
	return if s then s.job else nil
end

function JobService.current(player: Player): string?
	local data = DataService.get(player)
	local id = data and data.Job.Current
	return if id and id ~= "" then id else nil
end

function JobService.workplace(player: Player): (Vector3?, string?)
	local id = JobService.current(player)
	if not id then
		return nil, nil
	end
	local loc = Locations[Jobs.Defs[id].site] :: any
	return loc.Door or loc.Inside, Jobs.Defs[id].title
end

function JobService.addShiftGuard(fn: (Player, string) -> (boolean, string?))
	table.insert(guards, fn)
end

function JobService.clockOut(player: Player, reason: string?)
	local s = shifts[player]
	if not s then
		return
	end
	removeCarry(player, s)
	shifts[player] = nil
	local why = reason or "player"
	if why == "player" then
		Notify.toast(player, "Clocked out. This shift: " .. Format.cash(s.earned))
	elseif why == "left" then
		Notify.toast(player, "You left work, so your shift ended.")
	end
	log(player.Name, "clocked out of", s.job, why)
	JobService.ClockedOut:Fire(player, s.job, why)
	sendState(player)
	-- the story shift can't be abandoned: point back at the store (walking in clocks you in again)
	if StoryService.stage(player) == "FirstShift" and why ~= "story" then
		local loc = Locations[Jobs.Defs[Jobs.StoryJob].site] :: any
		WaypointService.set(player, "Story", loc.Door, { label = Jobs.Defs[Jobs.StoryJob].title, radius = loc.Radius })
	end
end

local function startShift(player: Player, jobId: string)
	local def = Jobs.Defs[jobId]
	local s: Shift = {
		job = jobId,
		session = HttpService:GenerateGUID(false),
		startedAt = now(),
		done = 0,
		total = JobRules.shiftLength(jobId),
		earned = 0,
		complete = false,
		task = nil,
		history = if shifts[player] then shifts[player].history else {},
		lastStation = {},
		waitingUntil = nil,
		leavingSince = nil,
		carry = nil,
		result = nil,
		postTimer = 0,
		onPost = false,
		paused = false,
		checkInToken = nil,
		checkInDue = now() + Jobs.Post.CheckInEvery,
	}
	shifts[player] = s
	if def.kind == "tasks" then
		assignTask(player, s)
	end
	Analytics.funnel(player, "Shift", s.session, 1, "ClockIn")
end

function JobService.clockIn(player: Player, force: boolean?): (boolean, string?)
	local data = DataService.get(player)
	if not data then
		return false, "Loading"
	end
	if shifts[player] then
		return false, "You're already on shift"
	end
	local jobId = data.Job.Current
	local ok, reason = JobRules.canWork(jobId, data.Level, data.Story.Stage)
	if not ok then
		return false, reason
	end
	for _, g in guards do
		local gOk, gReason = g(player, jobId)
		if not gOk then
			return false, gReason or "Not now"
		end
	end
	if not force and not atSite(player, jobId) then
		return false, "Go to " .. Jobs.Defs[jobId].title .. " to clock in"
	end
	startShift(player, jobId)
	local def = Jobs.Defs[jobId]
	Notify.toast(player, "Clocked in: " .. def.role .. " at " .. def.title)
	log(player.Name, "clocked in at", jobId)
	JobService.ClockedIn:Fire(player, jobId)
	sendState(player)
	return true, nil
end

local function nextShift(player: Player)
	local s = shifts[player]
	if not s or not s.complete then
		return
	end
	startShift(player, s.job)
	sendState(player)
end

-- Picks the player's job (the phone's CHOOSE button). force = skip the stage/level rules (story/debug).
function JobService.setJob(player: Player, jobId: string, force: boolean?): (boolean, string?)
	local data = DataService.get(player)
	if not data or not Jobs.Defs[jobId] then
		return false, "Unknown job"
	end
	if not force then
		local ok, reason = JobRules.canChoose(jobId, data.Level, data.Story.Stage)
		if not ok then
			return false, reason
		end
	end
	local old = data.Job.Current
	if old == jobId then
		if data.Story.Stage == Jobs.ChooseFromStage then
			-- Piece 4: at ChooseJob you still hold the story job (the Food Mart); picking it again is a real choice
			JobService.JobChosen:Fire(player, jobId, old)
			sendState(player)
			return true, nil
		end
		return false, "That's already your job"
	end
	if shifts[player] then
		JobService.clockOut(player, "switch")
	end
	data.Job.Current = jobId
	player:SetAttribute("MTL_Job", jobId)
	DataService.push(player)
	JobService.JobChosen:Fire(player, jobId, old)
	sendState(player)
	return true, nil
end

---------------------------------------------------------------- client actions

local function onStepAction(player: Player, s: Shift, payload: any, begin: boolean)
	local t = s.task
	if not t or payload.task ~= t.id or payload.step ~= t.step then
		sendState(player) -- out of sync (lag, double press): resend the truth
		return
	end
	local def = Jobs.Tasks[t.key]
	local step = def.steps[t.step]
	local pos, radius = station(s.job, t.stations[t.step])
	if not near(player, pos, radius) then
		Notify.toast(player, "Get closer")
		sendState(player)
		return
	end
	local data = DataService.get(player)
	local level = if data then data.Level else 1
	if begin then
		if JobRules.isMinigame(step.kind) then
			t.begunAt = now()
		end
		return
	end
	if now() - t.stepStartedAt < V.MinPromptSeconds then
		return
	end
	if JobRules.isMinigame(step.kind) then
		if not t.begunAt or now() - t.begunAt < JobRules.minStepSeconds(step, level) then
			log(player.Name, "step too fast", t.key, t.step)
			t.begunAt = nil
			sendState(player)
			return
		end
		local score = if type(payload.score) == "number" and payload.score == payload.score then math.clamp(payload.score, 0, 1) else 0.8
		table.insert(t.scores, score)
	end
	-- what this step does to your hands
	if step.kind == "drop" then
		removeCarry(player, s)
	end
	if step.carry then
		addCarry(player, s, step.carry)
	end
	if t.step >= #def.steps then
		completeTask(player, s, t, pos)
	else
		t.step += 1
		t.stepStartedAt = now()
		t.begunAt = nil
	end
	sendState(player)
end

local function onCheckIn(player: Player, s: Shift, payload: any)
	if s.checkInToken and payload.token == s.checkInToken then
		s.checkInToken = nil
		s.paused = false
		s.checkInDue = now() + Jobs.Post.CheckInEvery
		Notify.toast(player, "Checked in. Back on the clock.")
		sendState(player)
	end
end

local function onJobAction(player: Player, payload: any)
	if type(payload) ~= "table" or type(payload.type) ~= "string" or not limiter:allow(player) then
		return
	end
	if not DataService.get(player) then
		return
	end
	local kind = payload.type
	if kind == "clockIn" then
		local ok, reason = JobService.clockIn(player)
		if not ok and reason then
			Notify.toast(player, reason)
		end
		return
	elseif kind == "clockOut" then
		JobService.clockOut(player, "player")
		return
	elseif kind == "sync" then
		sendState(player)
		return
	end
	local s = shifts[player]
	if not s then
		return
	end
	if kind == "begin" or kind == "step" then
		onStepAction(player, s, payload, kind == "begin")
	elseif kind == "checkIn" then
		onCheckIn(player, s, payload)
	elseif kind == "nextShift" then
		nextShift(player)
	end
end

---------------------------------------------------------------- the shift loop (1 Hz)

local function tickPost(player: Player, s: Shift, dt: number)
	local data = DataService.get(player)
	if not data or s.complete then
		return
	end
	local pos, radius = station(s.job, "Post")
	local onPost = near(player, pos, radius)
	local changed = onPost ~= s.onPost
	s.onPost = onPost
	if not s.checkInToken and now() >= s.checkInDue then
		s.checkInToken = HttpService:GenerateGUID(false)
		s.paused = true
		changed = true
		PhoneService.notify(player, { app = "Jobs", title = "Radio", text = "Still on post? Check in to keep getting paid." })
	end
	if onPost and not s.paused then
		s.postTimer += dt
		if s.postTimer >= Jobs.Post.PayEvery then
			s.postTimer -= Jobs.Post.PayEvery
			local pay, xp = JobRules.postTick(s.job, data.Level)
			local paid = EconomyService.addCash(player, pay, "Job:" .. s.job, true, pos)
			EconomyService.addXP(player, xp, "Job:" .. s.job, pos)
			s.earned += paid
			s.done += 1
			if s.done >= s.total then
				finishShift(player, s)
			end
			changed = true
		end
	end
	if changed then
		sendState(player)
	end
end

local function tick(dt: number)
	local t = now()
	for player, s in shifts do
		if not player.Parent then
			shifts[player] = nil
			continue
		end
		local r = root(player)
		if not r then
			continue
		end
		local def = Jobs.Defs[s.job]
		-- left work?
		local leaveRadius = def.leaveRadius or V.LeaveRadius
		local away = flatDistance(r.Position, siteCenter(s.job)) > leaveRadius
		if away and not s.leavingSince then
			s.leavingSince = t
			Notify.toast(player, "Head back to work or your shift ends in " .. V.LeaveGrace .. "s", Color3.fromRGB(255, 205, 80))
			sendState(player)
		elseif not away and s.leavingSince then
			s.leavingSince = nil
			sendState(player)
		elseif away and s.leavingSince and t - s.leavingSince >= V.LeaveGrace then
			JobService.clockOut(player, "left")
			continue
		end
		if def.kind == "post" then
			tickPost(player, s, dt)
		elseif s.waitingUntil and t >= s.waitingUntil and not s.complete then
			assignTask(player, s)
			sendState(player)
		end
	end
end

---------------------------------------------------------------- story

local function wireStory()
	-- 2. FirstShift: the story job is set for you and you clock in when you walk into the store
	StoryService.onEnter("FirstShift", function(player)
		local data = DataService.get(player)
		if not data then
			return
		end
		if data.Job.Current == "" then
			data.Job.Current = Jobs.StoryJob
			player:SetAttribute("MTL_Job", Jobs.StoryJob)
			DataService.push(player)
		end
		if atSite(player, Jobs.StoryJob) then
			JobService.clockIn(player, true)
		else
			local loc = Locations[Jobs.Defs[Jobs.StoryJob].site] :: any
			WaypointService.set(player, "Story", loc.Door, { label = Jobs.Defs[Jobs.StoryJob].title, radius = loc.Radius })
		end
		sendState(player)
	end)
	WaypointService.Arrived:Connect(function(player, id)
		if id == "Story" and StoryService.stage(player) == "FirstShift" and not shifts[player] then
			JobService.clockIn(player, true)
		end
	end)

	-- stages that can't have a shift (robbery, cutscenes) end it
	StoryService.StageChanged:Connect(function(player, newStage)
		if Jobs.BlockedStages[newStage] and shifts[player] then
			JobService.clockOut(player, "story")
		end
		sendState(player)
	end)

	-- 10. ChooseJob ends when a job is picked; 12. CommuteToWork ends when you clock in there
	JobService.JobChosen:Connect(function(player)
		StoryService.advance(player, "ChooseJob")
	end)
	JobService.ClockedIn:Connect(function(player)
		StoryService.advance(player, "CommuteToWork")
	end)

	-- new jobs on level-up -> a phone ping (only once the player picks their own job)
	EconomyService.LevelUp:Connect(function(player, level)
		local stage = StoryService.stage(player)
		if not stage or not StoryRules.reached(stage, Jobs.ChooseFromStage) then
			return
		end
		for _, id in JobRules.unlockedAt(level) do
			local def = Jobs.Defs[id]
			PhoneService.notify(player, { app = "Jobs", title = "New job unlocked", text = def.role .. " at " .. def.title })
		end
		sendState(player)
	end)
end

---------------------------------------------------------------- init

function JobService.init()
	resolveMapSites()
	-- station marker parts (tools/PlaceJobStations.lua) are for editing only: invisible in game
	local stations = workspace:FindFirstChild("MTL_Stations")
	if stations then
		for _, d in stations:GetDescendants() do
			if d:IsA("BasePart") then
				d.Transparency = 1
				d.CanCollide = false
				d.CanQuery = false
			end
		end
	end

	Net.get("JobAction").OnServerEvent:Connect(function(player, payload)
		local ok, err = pcall(onJobAction, player, payload)
		if not ok then
			warn("[MTL Jobs] action failed:", err)
		end
	end)

	-- the phone's CHOOSE button
	PhoneService.onAction("chooseJob", function(player, payload)
		if type(payload.job) ~= "string" then
			return
		end
		local ok, reason = JobService.setJob(player, payload.job)
		if not ok then
			Notify.toast(player, reason or "Can't pick that job")
			return
		end
		local def = Jobs.Defs[payload.job]
		Notify.toast(player, "New job: " .. def.role .. " at " .. def.title)
		if StoryService.stage(player) == "FreePlay" then
			PhoneService.route(player, def.place)
		end
	end)

	DataService.Ready:Connect(function(player, data)
		if data.Job.Current ~= "" and not Jobs.Defs[data.Job.Current] then
			data.Job.Current = "" -- a job that was removed from the config
		end
		player:SetAttribute("MTL_Job", if data.Job.Current ~= "" then data.Job.Current else nil)
		task.defer(sendState, player)
	end)
	Net.get("ClientReady").OnServerEvent:Connect(function(player)
		sendState(player)
	end)

	-- dying drops what you carry; the step goes back to the pickup
	local function watchCharacter(player: Player)
		player.CharacterRemoving:Connect(function()
			local s = shifts[player]
			if not s then
				return
			end
			s.carry = nil
			local t = s.task
			if t and t.step > 1 then
				t.step, t.stepStartedAt, t.begunAt, t.scores = 1, now(), nil, {}
				task.delay(1, sendState, player)
			end
		end)
	end
	Players.PlayerAdded:Connect(watchCharacter)
	for _, p in Players:GetPlayers() do
		watchCharacter(p)
	end
	Players.PlayerRemoving:Connect(function(player)
		shifts[player] = nil
	end)

	wireStory()

	task.spawn(function()
		local last = now()
		while true do
			task.wait(1)
			local t = now()
			local ok, err = pcall(tick, t - last)
			if not ok then
				warn("[MTL Jobs] tick failed:", err)
			end
			last = t
		end
	end)
	log("ready:", #Jobs.Order, "jobs")
end

-- Studio testing (server Command Bar): _G.MTL.Jobs.debug(player, "Mechanic") -> picks it and clocks in where you stand
function JobService.debug(player: Player, jobId: string)
	assert(game:GetService("RunService"):IsStudio(), "[MTL Jobs] debug is Studio-only")
	if shifts[player] then
		JobService.clockOut(player, "debug")
	end
	local data = DataService.get(player)
	if data then
		data.Job.Current = jobId
	end
	return JobService.clockIn(player, true)
end

return JobService
]======])
put("ServerScriptService/MTL/Services", "MissionService", "ModuleScript", [======[--!strict
-- Runs missions step by step (Config/Missions.<Id>.Steps). The server owns every step: it sets the one "Story"
-- waypoint, checks distances, hold times and aim (anti-exploit), and tells the client what to show (MissionState).
-- Piece 3 ships one mission, FirstMission (rob Liberty Food Mart); the runner is generic for later story missions.
--
-- API (Master Plan §3.5):
--   MissionService.start(player, missionId)        teleports to the start, gives the mission gun, step 1
--   MissionService.stop(player, reason?)           abandon (no reward); cleans up mask / bag / gun
--   MissionService.cleanup(player)                 remove mission gear (mask, cash bag, temporary gun)
--   MissionService.active(player) -> missionId?
--   MissionService.point(missionId, name) -> (CFrame, radius)   resolved spot (map part wins over config)
--   MissionService.send(player, payload)           a MissionState message (StoryCrew: payout, meet...)
--   MissionService.onAction(type, fn(player, payload))  extra MissionAction types (StoryCrew: closeOffer, buy)
--   MissionService.Completed: Signal(player, missionId, result = { seconds, escapeSeconds, clean })
--   MissionService.StepDone: Signal(player, missionId, stepId)
-- Guns (optional, Guns thread): GunService.give/take/equip + Intimidating/Fired signals. Without GunService the aim
-- step falls back to a built-in hold-aim the server validates (distance + facing + hold time).
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")
local HttpService = game:GetService("HttpService")

local Net = require(ReplicatedStorage.MTL.Net)
local Signal = require(ReplicatedStorage.MTL.Signal)
local Missions = require(ReplicatedStorage.MTL.Config.Missions)
local Locations = require(ReplicatedStorage.MTL.Config.Locations)
local MissionRules = require(ReplicatedStorage.MTL.Rules.MissionRules)
local Rig = require(ReplicatedStorage.MTL.Rig)
local WaypointService = require(script.Parent.WaypointService)
local Notify = require(script.Parent.Notify)
local Analytics = require(script.Parent.Analytics)
local RateLimiter = require(script.Parent.RateLimiter)
local CutsceneService = require(script.Parent.CutsceneService)

local MissionService = {}
MissionService.Completed = Signal.new() -- (player, missionId, result)
MissionService.StepDone = Signal.new() -- (player, missionId, stepId)

type Run = {
	id: string,
	def: any,
	index: number,
	startedAt: number,
	stepAt: number,
	begunAt: number?,
	alarmAt: number?,
	session: string,
	token: number,
	lastProgress: number,
	finishing: boolean,
}

local runs: { [Player]: Run } = {}
local handlers: { [string]: (Player, any) -> () } = {}
local limiter = RateLimiter.new(6, 10)
local tokenCounter = 0
local WAYPOINT = "Story" -- the one main waypoint (Research: Onboarding Funnels)
local POINT_FOLDER = "MTL_Stations" -- Workspace.MTL_Stations.<MissionId>.<Point> parts override config spots

local function log(...)
	print("[MTL Mission]", ...)
end

local function now(): number
	return os.clock()
end

local function root(player: Player): BasePart?
	local c = player.Character
	return c and c:FindFirstChild("HumanoidRootPart") :: BasePart?
end

---------------------------------------------------------------- optional GunService (Guns thread)

local gunsCache: any = false
local function guns(): any?
	if gunsCache ~= false then
		return gunsCache
	end
	local m = script.Parent:FindFirstChild("GunService")
	if not m then
		return nil -- not installed yet: check again next time
	end
	local ok, g = pcall(require, m)
	gunsCache = if ok and type(g) == "table" then g else nil
	return gunsCache
end

local function gunCall(name: string, ...: any): any
	local g = guns()
	local fn = g and g[name]
	if type(fn) ~= "function" then
		return nil
	end
	local ok, res = pcall(fn, ...)
	if not ok then
		warn("[MTL Mission] GunService." .. name, "failed:", res)
		return nil
	end
	return res
end

---------------------------------------------------------------- points

local pointCache: { [string]: { [string]: { cf: CFrame, radius: number } } } = {}

local function floorAt(pos: Vector3): number
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	local ex: { Instance } = {}
	local stations = workspace:FindFirstChild(POINT_FOLDER)
	if stations then
		table.insert(ex, stations)
	end
	for _, p in Players:GetPlayers() do
		if p.Character then
			table.insert(ex, p.Character)
		end
	end
	params.FilterDescendantsInstances = ex
	local hit = workspace:Raycast(pos + Vector3.new(0, 6, 0), Vector3.new(0, -40, 0), params)
	return if hit then hit.Position.Y else pos.Y - 1
end

function MissionService.point(missionId: string, name: string): (CFrame, number)
	local cache = pointCache[missionId]
	if cache and cache[name] then
		return cache[name].cf, cache[name].radius
	end
	local def = (Missions :: any)[missionId]
	local cfg = def.Points[name]
	local cf: CFrame
	local radius = cfg.radius or 8
	local folder = workspace:FindFirstChild(POINT_FOLDER)
	local mf = folder and folder:FindFirstChild(missionId)
	local part = mf and mf:FindFirstChild(name)
	if part and part:IsA("BasePart") then
		local p = part.Position
		cf = CFrame.new(p.X, floorAt(p), p.Z) * part.CFrame.Rotation
		local r = part:GetAttribute("Radius")
		if type(r) == "number" then
			radius = r
		end
	else
		local base = Locations.FoodMart.Inside
		local p = base + (cfg.offset or Vector3.zero)
		cf = CFrame.new(p.X, floorAt(p), p.Z) * CFrame.Angles(0, math.rad(cfg.yaw or 0), 0)
	end
	pointCache[missionId] = cache or {}
	pointCache[missionId][name] = { cf = cf, radius = radius }
	return cf, radius
end

---------------------------------------------------------------- client messages

function MissionService.send(player: Player, payload: { [string]: any })
	Net.get("MissionState"):FireClient(player, payload)
end

local function bark(player: Player, line: { string }?)
	if line then
		MissionService.send(player, { type = "bark", who = line[1], text = line[2] })
	end
end

local function sendState(player: Player)
	local run = runs[player]
	if not run then
		MissionService.send(player, { type = "clear" })
		return
	end
	local def = run.def
	local step = def.Steps[run.index]
	local pcf, radius = MissionService.point(run.id, step.point)
	local car = MissionService.point(run.id, "Car")
	MissionService.send(player, {
		type = "state",
		mission = run.id,
		title = def.Title,
		index = run.index,
		steps = MissionRules.checklist(def, run.index),
		step = {
			id = step.id,
			kind = step.kind,
			text = step.text,
			verb = step.verb,
			seconds = step.seconds,
			pos = pcf.Position,
			radius = radius,
		},
		car = car,
		clerk = MissionService.point(run.id, "Clerk").Position,
		register = MissionService.point(run.id, "Register").Position,
		alarm = run.alarmAt ~= nil,
		alarmFor = if run.alarmAt then now() - run.alarmAt else nil,
		cleanSeconds = if def.CleanGetaway then def.CleanGetaway.Seconds else nil,
		aimFallback = guns() == nil or guns().Intimidating == nil,
	})
end

---------------------------------------------------------------- gear (mask, cash bag) on the real character

local function headOf(char: Model): BasePart?
	return char:FindFirstChild("Head") :: BasePart?
end

local function weldTo(part: BasePart, to: BasePart, offset: CFrame)
	part.CFrame = to.CFrame * offset
	local w = Instance.new("WeldConstraint")
	w.Part0 = to
	w.Part1 = part
	w.Parent = part
end

local function putMask(player: Player)
	local char = player.Character
	local head = char and headOf(char)
	if not char or not head or char:FindFirstChild("MTL_Mask") then
		return
	end
	local lib = ReplicatedStorage:FindFirstChild("MTL_Actors")
	local acc = lib and lib:FindFirstChild("Mask") -- TODO(Alex art): an Accessory named Mask here replaces the placeholder
	local hum = char:FindFirstChildOfClass("Humanoid")
	if acc and acc:IsA("Accessory") and hum then
		local a = acc:Clone()
		a.Name = "MTL_Mask"
		hum:AddAccessory(a)
		return
	end
	local m = Instance.new("Part")
	m.Name = "MTL_Mask"
	m.Size = head.Size * Vector3.new(1.08, 1.06, 1.08)
	m.Color = Color3.fromRGB(18, 18, 20)
	m.Material = Enum.Material.Fabric
	m.CanCollide = false
	m.CanQuery = false
	m.Massless = true
	for _, x in { -0.22, 0.22 } do
		local eye = Instance.new("Part")
		eye.Name = "EyeHole"
		eye.Size = Vector3.new(0.28, 0.16, 0.05)
		eye.Color = Color3.fromRGB(235, 235, 240)
		eye.CanCollide = false
		eye.CanQuery = false
		eye.Massless = true
		eye.Parent = m
		weldTo(eye, head, CFrame.new(x * head.Size.X, 0.1 * head.Size.Y, -head.Size.Z * 0.55))
	end
	m.Parent = char
	weldTo(m, head, CFrame.new())
end

local function putBag(player: Player)
	local char = player.Character
	if not char or char:FindFirstChild("MTL_CashBag") then
		return
	end
	local torso = (char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")) :: BasePart?
	if not torso then
		return
	end
	local bag = Instance.new("Part")
	bag.Name = "MTL_CashBag"
	bag.Size = Vector3.new(1.6, 1.8, 0.9)
	bag.Color = Color3.fromRGB(40, 70, 50)
	bag.Material = Enum.Material.Fabric
	bag.CanCollide = false
	bag.CanQuery = false
	bag.Massless = true
	bag.Parent = char
	weldTo(bag, torso, CFrame.new(0, -0.1, torso.Size.Z / 2 + 0.45))
end

function MissionService.cleanup(player: Player)
	local char = player.Character
	if char then
		for _, n in { "MTL_Mask", "MTL_CashBag" } do
			local g = char:FindFirstChild(n)
			if g then
				g:Destroy()
			end
		end
	end
	local run = runs[player]
	local gun = if run and run.def.Gun then run.def.Gun.Id else Missions.FirstMission.Gun.Id
	gunCall("take", player, gun)
end

---------------------------------------------------------------- the clerk (one shared server NPC while anyone robs)

local clerk: Model? = nil
local clerkJoints: Rig.Joints? = nil
local clerkScared = false
local clerkSpawning = false

local function anyRun(id: string): boolean
	for _, r in runs do
		if r.id == id then
			return true
		end
	end
	return false
end

local function spawnClerk(missionId: string)
	if clerk or clerkSpawning then
		return
	end
	clerkSpawning = true
	local def = (Missions :: any)[missionId]
	local m = CutsceneService.rig(def.Clerk)
	clerkSpawning = false
	if not m or not anyRun(missionId) then
		if m then
			m:Destroy()
		end
		return
	end
	local cf = MissionService.point(missionId, "Clerk")
	local r = m:FindFirstChild("HumanoidRootPart") :: BasePart
	for _, d in m:GetDescendants() do
		if d:IsA("BasePart") then
			d.Anchored = d == r
			d.CanCollide = false
			d.Massless = true
		end
	end
	m.Name = "MTL_Clerk"
	m:SetAttribute("MTL_Mission", missionId)
	CollectionService:AddTag(m, "MTL_Intimidate")
	m.PrimaryPart = r
	r.CFrame = cf + Vector3.new(0, Rig.rootHeight(m), 0)
	m.Parent = workspace
	clerk = m
	clerkJoints = Rig.joints(m)
	clerkScared = false
end

local function scareClerk(player: Player)
	if not clerk or not clerkJoints then
		return
	end
	if not clerkScared then
		clerkScared = true
		Rig.apply(clerkJoints, Rig.compose({ pose = "HandsUp", poseT0 = -10, breath = false }, 0), "C0")
	end
	-- face whoever is robbing
	local r = clerk.PrimaryPart
	local pr = root(player)
	if r and pr then
		local p = r.Position
		local look = Vector3.new(pr.Position.X, p.Y, pr.Position.Z)
		if (look - p).Magnitude > 0.5 then
			r.CFrame = CFrame.lookAt(p, look)
		end
	end
end

local function calmClerk()
	if clerk and clerkJoints and clerkScared then
		clerkScared = false
		Rig.reset(clerkJoints, "C0")
	end
end

local function refreshClerk(missionId: string)
	if not anyRun(missionId) then
		if clerk then
			clerk:Destroy()
			clerk, clerkJoints, clerkScared = nil, nil, false
		end
		return
	end
	-- nobody past the threat any more -> calm again
	local threatened = false
	for _, r in runs do
		local s = r.def.Steps[r.index]
		local ti = MissionRules.stepIndex(r.def, "Threaten") or math.huge
		if r.id == missionId and s and r.index > ti then
			threatened = true
		end
	end
	if not threatened then
		calmClerk()
	end
end

---------------------------------------------------------------- steps

local function teleportToStart(player: Player, run: Run)
	local car = MissionService.point(run.id, "Car")
	local r = root(player)
	if r then
		-- behind the car (its +Z side), facing it: the mask box is in the trunk
		local spot = car * CFrame.new(0, 0, 9.5)
		local pos = spot.Position + Vector3.new(0, 3, 0)
		r.CFrame = CFrame.lookAt(pos, pos + car.LookVector)
		r.AssemblyLinearVelocity = Vector3.zero
	end
end

local enterStep: (Player, Run) -> ()

local function completeStep(player: Player, run: Run)
	local def = run.def
	local step = def.Steps[run.index]
	log(player.Name, run.id, "step done:", step.id)
	Analytics.funnel(player, run.id, run.session, run.index + 1, step.id)
	MissionService.StepDone:Fire(player, run.id, step.id)
	-- side effects of finishing a step
	if step.id == "Mask" then
		putMask(player)
	elseif step.kind == "aim" then
		scareClerk(player)
		bark(player, step.after)
	elseif step.id == "Grab" then
		putBag(player)
	end
	if MissionRules.isLast(def, run.index) then
		run.finishing = true
		WaypointService.clear(player, WAYPOINT)
		local escape = if run.alarmAt then now() - run.alarmAt else nil
		local take, bonus, clean = MissionRules.payout(def, escape)
		local result = { seconds = now() - run.startedAt, escapeSeconds = escape, clean = clean, take = take, bonus = bonus }
		runs[player] = nil
		MissionService.send(player, { type = "clear", reason = "done" })
		refreshClerk(run.id)
		log(player.Name, run.id, "complete in", math.floor(result.seconds), "s")
		MissionService.Completed:Fire(player, run.id, result)
		return
	end
	run.index += 1
	enterStep(player, run)
end

enterStep = function(player: Player, run: Run)
	local def = run.def
	local step = def.Steps[run.index]
	run.stepAt = now()
	run.begunAt = nil
	run.lastProgress = 0
	if step.alarm and not run.alarmAt then
		run.alarmAt = now()
	end
	local pcf, radius = MissionService.point(run.id, step.point)
	-- zone steps finish on arrival; hold/aim steps use the waypoint only to guide (arrival just clears the marker)
	WaypointService.set(player, WAYPOINT, pcf.Position, {
		label = step.text,
		radius = if step.kind == "zone" then radius else math.min(radius, 6),
		breadcrumbs = true,
	})
	Notify.objective(player, step.text)
	if step.kind == "aim" then
		gunCall("equip", player, def.Gun.Id)
	end
	bark(player, step.bark)
	sendState(player)
end

function MissionService.active(player: Player): string?
	local r = runs[player]
	return r and r.id
end

local wired = false
local function wireGuns()
	if wired then
		return
	end
	local g = guns()
	if not g then
		return
	end
	wired = true
	if g.Intimidating and g.Intimidating.Connect then
		g.Intimidating:Connect(function(player: Player, target: Instance?, held: number)
			local run = runs[player]
			if not run or run.finishing then
				return
			end
			local step = run.def.Steps[run.index]
			if step.kind ~= "aim" or not target or target:GetAttribute("MTL_Mission") ~= run.id then
				return
			end
			local value = math.clamp((held or 0) / step.seconds, 0, 1)
			if math.abs(value - run.lastProgress) >= 0.05 or value >= 1 then
				run.lastProgress = value
				MissionService.send(player, { type = "progress", value = value })
			end
			if held >= step.seconds then
				completeStep(player, run)
			end
		end)
	end
	if g.Fired and g.Fired.Connect then
		-- a shot during the stick-up scares the clerk straight away (intimidate guns deal no damage)
		g.Fired:Connect(function(player: Player)
			local run = runs[player]
			if run and not run.finishing and run.def.Steps[run.index].kind == "aim" then
				local r = root(player)
				local cpos = MissionService.point(run.id, "Clerk").Position
				if r and (r.Position - cpos).Magnitude <= run.def.AimRange then
					completeStep(player, run)
				end
			end
		end)
	end
end

function MissionService.start(player: Player, missionId: string)
	local def = (Missions :: any)[missionId]
	assert(def and def.Steps, "[MTL Mission] unknown mission " .. tostring(missionId))
	if runs[player] then
		return
	end
	wireGuns()
	-- no shift during a mission
	local jm = script.Parent:FindFirstChild("JobService")
	if jm then
		local ok, js = pcall(require, jm)
		if ok and js.isOnShift and js.isOnShift(player) then
			js.clockOut(player, "story")
		end
	end
	tokenCounter += 1
	local run: Run = {
		id = missionId,
		def = def,
		index = 1,
		startedAt = now(),
		stepAt = now(),
		begunAt = nil,
		alarmAt = nil,
		session = HttpService:GenerateGUID(false),
		token = tokenCounter,
		lastProgress = 0,
		finishing = false,
	}
	runs[player] = run
	local car = MissionService.point(missionId, "Car")
	pcall(function()
		player:RequestStreamAroundAsync(car.Position, 5)
	end)
	if runs[player] ~= run then
		return
	end
	teleportToStart(player, run)
	if def.Gun then
		gunCall("give", player, def.Gun.Id, { temporary = true, mode = "Intimidate", ammo = def.Gun.Ammo })
	end
	task.spawn(spawnClerk, missionId)
	Analytics.funnel(player, missionId, run.session, 1, "Start")
	log(player.Name, "start", missionId)
	enterStep(player, run)
end

-- Back to step 1 at the car (after dying or wandering off). No penalty: the crew just pulls you back.
local function restart(player: Player, why: string)
	local run = runs[player]
	if not run or run.finishing then
		return
	end
	MissionService.cleanup(player)
	run.index = 1
	run.alarmAt = nil
	run.startedAt = now()
	teleportToStart(player, run)
	if run.def.Gun then
		gunCall("give", player, run.def.Gun.Id, { temporary = true, mode = "Intimidate", ammo = run.def.Gun.Ammo })
	end
	Notify.toast(player, why)
	refreshClerk(run.id)
	enterStep(player, run)
end

function MissionService.stop(player: Player, reason: string?)
	local run = runs[player]
	if not run then
		return
	end
	MissionService.cleanup(player)
	runs[player] = nil
	WaypointService.clear(player, WAYPOINT)
	MissionService.send(player, { type = "clear", reason = reason or "stopped" })
	refreshClerk(run.id)
	log(player.Name, "stopped", run.id, reason or "")
end

function MissionService.onAction(actionType: string, fn: (Player, any) -> ())
	handlers[actionType] = fn
end

---------------------------------------------------------------- client actions

local function onAction(player: Player, payload: any)
	if type(payload) ~= "table" or type(payload.type) ~= "string" then
		return
	end
	local custom = handlers[payload.type]
	if custom then
		custom(player, payload)
		return
	end
	local run = runs[player]
	if not run or run.finishing then
		return
	end
	local def = run.def
	local step = def.Steps[run.index]
	if payload.step ~= step.id then
		return
	end
	local r = root(player)
	if not r then
		return
	end
	local pcf, radius = MissionService.point(run.id, step.point)
	local flatDist = Vector2.new(r.Position.X - pcf.Position.X, r.Position.Z - pcf.Position.Z).Magnitude
	if step.kind == "hold" then
		if flatDist > radius + 4 then
			return
		end
		if payload.type == "begin" then
			run.begunAt = now()
		elseif payload.type == "step" and run.begunAt then
			if MissionRules.holdOk(step.seconds, now() - run.begunAt, def.MinHoldShare) then
				completeStep(player, run)
			else
				run.begunAt = nil
			end
		end
	elseif step.kind == "aim" then
		-- built-in aim (only when GunService doesn't drive this step)
		local g = guns()
		if g and g.Intimidating then
			return
		end
		local look = r.CFrame.LookVector
		local ok = MissionRules.facingOk(r.Position.X, r.Position.Z, look.X, look.Z, pcf.Position.X, pcf.Position.Z, def.AimDot, def.AimRange)
		if payload.type == "begin" then
			run.begunAt = if ok then now() else nil
		elseif payload.type == "step" and run.begunAt then
			if ok and MissionRules.holdOk(step.seconds, now() - run.begunAt, def.MinHoldShare) then
				completeStep(player, run)
			else
				run.begunAt = nil
			end
		end
	end
end

function MissionService.init()
	Net.get("MissionAction").OnServerEvent:Connect(function(player, payload)
		if not limiter:allow(player) then
			return
		end
		local ok, err = pcall(onAction, player, payload)
		if not ok then
			warn("[MTL Mission] action failed:", err)
		end
	end)

	-- zone steps: the server-checked waypoint arrival
	WaypointService.Arrived:Connect(function(player, id)
		local run = runs[player]
		if id ~= WAYPOINT or not run or run.finishing then
			return
		end
		local step = run.def.Steps[run.index]
		if step.kind == "zone" then
			completeStep(player, run)
		end
	end)

	Net.get("ClientReady").OnServerEvent:Connect(function(player)
		if runs[player] then
			sendState(player)
		end
	end)

	local function watch(player: Player)
		player.CharacterAdded:Connect(function()
			if runs[player] then
				task.wait(0.6)
				restart(player, "The crew got you back to the car. Run it again.")
			end
		end)
	end
	Players.PlayerAdded:Connect(watch)
	for _, p in Players:GetPlayers() do
		watch(p)
	end
	Players.PlayerRemoving:Connect(function(player)
		local run = runs[player]
		runs[player] = nil
		if run then
			refreshClerk(run.id)
		end
	end)

	-- wandering far from the job: back to the car (never a fail screen)
	task.spawn(function()
		while true do
			task.wait(1)
			for player, run in runs do
				local r = root(player)
				local def = run.def
				if r and def.ResetRadius and not run.finishing then
					local d = (r.Position - Locations.FoodMart.Inside).Magnitude
					if d > def.ResetRadius then
						task.spawn(restart, player, "Too far from the job. The crew picked you up.")
					end
				end
				-- keep the clerk facing the robber while the robbery is on
				if clerkScared and run.index > (MissionRules.stepIndex(def, "Threaten") or math.huge) then
					scareClerk(player)
				end
			end
		end
	end)
	log("ready")
end

-- Studio test (server Command Bar): _G.MTL.Missions.debugStep(player) completes the current step.
function MissionService.debugStep(player: Player)
	assert(game:GetService("RunService"):IsStudio(), "[MTL Mission] debugStep is Studio-only")
	local run = runs[player]
	if run then
		completeStep(player, run)
	end
end

return MissionService
]======])
put("ServerScriptService/MTL/Services", "MonetizationService", "ModuleScript", [======[--!strict
-- Game passes (checked with Roblox, cached as player attributes MTL_Pass_<Name>), purchase prompts, and the ONE
-- ProcessReceipt for developer products (boosts). Kid-safe rules: grant only here on the server, grant once per
-- PurchaseId, answer PurchaseGranted only after the grant is SAVED, never sell an id of 0 ("Coming soon").
--   MonetizationService.owns(player, passName) -> bool
--   MonetizationService.prompt(player, passOrProductName)   (the phone's "buy" action calls this; whitelisted names)
--   MonetizationService.PassChanged: Signal(player, passName, owned)
--   MonetizationService.ProductGranted: Signal(player, productName)
-- Products (Config/Monetization.Products): XPBoost / CashBoost = 2x for Economy.BoostSecondsPerPurchase of PLAY
-- time, stacking (EconomyService counts it down and applies it). StarterPack pass: its cash is granted once per save.
local MarketplaceService = game:GetService("MarketplaceService")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Monetization = require(ReplicatedStorage.MTL.Config.Monetization)
local Economy = require(ReplicatedStorage.MTL.Config.Economy)
local Signal = require(ReplicatedStorage.MTL.Signal)
local Notify = require(script.Parent.Notify)
local DataService = require(script.Parent.DataService)

local MonetizationService = {}
MonetizationService.PassChanged = Signal.new() -- (player, passName, owned)
MonetizationService.ProductGranted = Signal.new() -- (player, productName)

local MAX_PURCHASE_IDS = 200 -- receipts kept per save (Roblox only retries recent ones)

local function attr(name: string): string
	return "MTL_Pass_" .. name
end

function MonetizationService.owns(player: Player, passName: string): boolean
	return player:GetAttribute(attr(passName)) == true
end

local function check(player: Player, passName: string, id: number)
	if id == 0 then
		player:SetAttribute(attr(passName), false)
		return
	end
	local ok, owned = pcall(MarketplaceService.UserOwnsGamePassAsync, MarketplaceService, player.UserId, id)
	if ok then
		local was = player:GetAttribute(attr(passName)) == true
		player:SetAttribute(attr(passName), owned == true)
		if was ~= (owned == true) then
			MonetizationService.PassChanged:Fire(player, passName, owned == true)
		end
	else
		warn("[MTL Monetization] pass check failed", passName, owned)
	end
end

-- Opens the Roblox purchase prompt. Id 0 = not set up yet -> "coming soon", never a prompt.
function MonetizationService.prompt(player: Player, name: string)
	local passId = Monetization.Passes[name]
	if passId ~= nil then
		if passId == 0 then
			Notify.toast(player, "Coming soon")
			return
		end
		if MonetizationService.owns(player, name) then
			Notify.toast(player, "You already own this")
			return
		end
		MarketplaceService:PromptGamePassPurchase(player, passId)
		return
	end
	local productId = Monetization.Products[name]
	if productId ~= nil then
		if productId == 0 then
			Notify.toast(player, "Coming soon")
			return
		end
		MarketplaceService:PromptProductPurchase(player, productId)
		return
	end
	warn("[MTL Monetization] unknown pass/product", name)
end

---------------------------------------------------------------- developer products

-- What each product does. Return true when granted. Runs at most once per PurchaseId.
local productGrants: { [string]: (Player, any) -> boolean } = {
	XPBoost = function(player, data)
		data.Boosts.XP2xSeconds += Economy.BoostSecondsPerPurchase
		Notify.banner(player, "2x XP", math.floor(Economy.BoostSecondsPerPurchase / 60) .. " minutes of play time added")
		return true
	end,
	CashBoost = function(player, data)
		data.Boosts.Cash2xSeconds += Economy.BoostSecondsPerPurchase
		Notify.banner(player, "2x CASH", math.floor(Economy.BoostSecondsPerPurchase / 60) .. " minutes of play time added")
		return true
	end,
}

local function trimPurchases(purchases: { [string]: number })
	local list = {}
	for id, t in purchases do
		table.insert(list, { id = id, t = if type(t) == "number" then t else 0 })
	end
	if #list <= MAX_PURCHASE_IDS then
		return
	end
	table.sort(list, function(a, b)
		return a.t < b.t
	end)
	for i = 1, #list - MAX_PURCHASE_IDS do
		purchases[list[i].id] = nil
	end
end

local function isSaved(profile: any, purchaseId: string): boolean
	local saved = profile.LastSavedData
	return saved ~= nil and saved.Purchases ~= nil and saved.Purchases[purchaseId] ~= nil
end

local function processReceipt(receipt: any): Enum.ProductPurchaseDecision
	local player = Players:GetPlayerByUserId(receipt.PlayerId)
	if not player then
		return Enum.ProductPurchaseDecision.NotProcessedYet -- Roblox retries next time they join
	end
	local profile = DataService.profile(player)
	while not profile and player.Parent == Players do
		task.wait(0.5)
		profile = DataService.profile(player)
	end
	if not profile or not profile:IsActive() then
		return Enum.ProductPurchaseDecision.NotProcessedYet
	end
	local name: string? = nil
	for n, id in Monetization.Products do
		if id ~= 0 and id == receipt.ProductId then
			name = n
		end
	end
	local grant = name and productGrants[name]
	if not grant then
		warn("[MTL Monetization] receipt for an unknown product", receipt.ProductId)
		return Enum.ProductPurchaseDecision.NotProcessedYet
	end
	local purchaseId = tostring(receipt.PurchaseId)
	local data = profile.Data
	if data.Purchases[purchaseId] == nil then
		local ok, result = pcall(grant, player, data)
		if not ok or result ~= true then
			warn("[MTL Monetization] grant failed", name, result)
			return Enum.ProductPurchaseDecision.NotProcessedYet
		end
		data.Purchases[purchaseId] = os.time()
		trimPurchases(data.Purchases)
		DataService.push(player)
		MonetizationService.ProductGranted:Fire(player, name)
		print("[MTL Monetization]", player.Name, "bought", name)
	end
	-- answer "granted" only once the save that holds this PurchaseId is written
	if isSaved(profile, purchaseId) then
		return Enum.ProductPurchaseDecision.PurchaseGranted
	end
	while profile:IsActive() do
		local before = profile.LastSavedData
		profile:Save()
		if profile.LastSavedData == before then
			profile.OnAfterSave:Wait()
		end
		if isSaved(profile, purchaseId) then
			return Enum.ProductPurchaseDecision.PurchaseGranted
		end
		if profile:IsActive() then
			task.wait(10)
		end
	end
	return Enum.ProductPurchaseDecision.NotProcessedYet
end

-- StarterPack pass: its cash lands once per save (the pass itself is never saved, only "already given").
local function grantStarterPack(player: Player)
	local data = DataService.get(player)
	if not data or data.Purchases["Pass:StarterPack"] or not MonetizationService.owns(player, "StarterPack") then
		return
	end
	data.Purchases["Pass:StarterPack"] = os.time()
	data.Cash = math.min(data.Cash + (Monetization.StarterPack.Cash or 0), Economy.MaxCash)
	local ls = player:FindFirstChild("leaderstats")
	local cash = ls and ls:FindFirstChild("Cash") :: IntValue?
	if cash then
		cash.Value = data.Cash
	end
	DataService.push(player)
	Notify.banner(player, "STARTER PACK", "+$" .. tostring(Monetization.StarterPack.Cash))
end

function MonetizationService.init()
	local byId: { [number]: string } = {}
	for name, id in Monetization.Passes do
		if id ~= 0 then
			byId[id] = name
		end
	end

	local function onJoin(player: Player)
		for name, id in Monetization.Passes do
			task.spawn(check, player, name, id)
		end
	end
	Players.PlayerAdded:Connect(onJoin)
	for _, p in Players:GetPlayers() do
		onJoin(p)
	end

	MarketplaceService.PromptGamePassPurchaseFinished:Connect(function(player, passId, purchased)
		local name = byId[passId]
		if name and purchased then
			check(player, name, passId) -- re-check with Roblox, never trust the event alone
		end
	end)

	MarketplaceService.ProcessReceipt = processReceipt -- the ONLY ProcessReceipt in the place

	MonetizationService.PassChanged:Connect(function(player, name, owned)
		if name == "StarterPack" and owned then
			grantStarterPack(player)
		end
	end)
	DataService.Ready:Connect(function(player)
		-- ownership may have been checked before the save loaded
		task.delay(3, grantStarterPack, player)
	end)

	-- Phone/UI "buy" buttons: PhoneAction { type = "buy", item = "XP2x" | "XPBoost" | ... }
	-- Required lazily: PhoneService boots after this service.
	task.defer(function()
		local PhoneService = require(script.Parent.PhoneService) :: any
		PhoneService.onAction("buy", function(player, payload)
			local item = payload.item
			if type(item) == "string" and (Monetization.Passes[item] ~= nil or Monetization.Products[item] ~= nil) then
				MonetizationService.prompt(player, item)
			end
		end)
	end)
end

return MonetizationService
]======])
put("ServerScriptService/MTL/Services", "Notify", "ModuleScript", [======[--!strict
-- Server -> client messages for the HUD. kinds: "toast" (small, stacks), "objective" (the one top line),
-- "banner" (big centre words: LEVEL UP, MISSION COMPLETE; use rarely).
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Net = require(ReplicatedStorage.MTL.Net)

local Notify = {}

function Notify.toast(player: Player, text: string, color: Color3?)
	Net.get("Notify"):FireClient(player, { kind = "toast", text = text, color = color })
end

function Notify.objective(player: Player, text: string)
	player:SetAttribute("MTL_Objective", text) -- also kept as an attribute so a respawned HUD can read it
	Net.get("Notify"):FireClient(player, { kind = "objective", text = text })
end

function Notify.banner(player: Player, text: string, sub: string?, color: Color3?)
	Net.get("Notify"):FireClient(player, { kind = "banner", text = text, sub = sub, color = color })
end

return Notify
]======])
put("ServerScriptService/MTL/Services", "PhoneService", "ModuleScript", [======[--!strict
-- The phone's server side: texts, calls, notifications, app unlocks, GPS routes, Lifestyle switch, settings.
-- The save holds the truth (data.Phone, see Rules/PhoneRules for shapes); the client renders from its snapshot and
-- uses PhoneEvent only for the moment something arrives (banner, ring). Every PhoneAction is validated here.
--
-- API (Master Plan §3.5):
--   PhoneService.text(player, contactId, text, opts?)   opts = { link = {kind="waypoint", place=GPSPlaceId, label?}
--                                                                        | {kind="app", app=AppId}, silent = bool }
--   PhoneService.call(player, callId) -> bool          rings; result comes back on CallEnded
--   PhoneService.CallEnded: Signal(player, callId, outcome)
--        outcome = a choice id from Config/Phone.Calls[callId].choices, or "answered" | "missed" | "declined" | "hungUp"
--   PhoneService.openApp(player, appId)  PhoneService.unlockApp(player, appId)
--   PhoneService.notify(player, { app, title, text })   a banner on the phone without a text thread
--   PhoneService.setPath(player, path, force?) -> ok, reason
--   PhoneService.PathChanged: Signal(player, newPath, oldPath)
--   PhoneService.addPathGuard(fn(player, wanted) -> (ok, reason?))   e.g. GunService blocks switching mid-fight
--   PhoneService.onAction(type, fn(player, payload))   other pieces handle their own phone buttons (Jobs: "chooseJob")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Net = require(ReplicatedStorage.MTL.Net)
local Signal = require(ReplicatedStorage.MTL.Signal)
local PhoneConfig = require(ReplicatedStorage.MTL.Config.Phone)
local Locations = require(ReplicatedStorage.MTL.Config.Locations)
local Story = require(ReplicatedStorage.MTL.Config.Story)
local PhoneRules = require(ReplicatedStorage.MTL.Rules.PhoneRules)
local DataService = require(script.Parent.DataService)
local WaypointService = require(script.Parent.WaypointService)
local Notify = require(script.Parent.Notify)
local RateLimiter = require(script.Parent.RateLimiter)

local PhoneService = {}
PhoneService.CallEnded = Signal.new() -- (player, callId, outcome)
PhoneService.PathChanged = Signal.new() -- (player, newPath, oldPath)
PhoneService.TextSent = Signal.new() -- (player, contactId, text)

type CallState = { id: string, state: string, token: number, outgoing: boolean }
local calls: { [Player]: CallState } = {}
local lastPathSwitch: { [Player]: number } = {}
local handlers: { [string]: (Player, any) -> () } = {}
local pathGuards: { (Player, string) -> (boolean, string?) } = {}
local limiter = RateLimiter.new(8, 14)
local tokenCounter = 0

local function log(...)
	print("[MTL Phone]", ...)
end

local function fire(player: Player, payload: { [string]: any })
	Net.get("PhoneEvent"):FireClient(player, payload)
end

local function phoneData(player: Player): any?
	local data = DataService.get(player)
	if not data then
		return nil
	end
	local p = data.Phone
	p.Texts = p.Texts or {}
	p.Unread = p.Unread or {}
	p.Recents = p.Recents or {}
	p.Contacts = p.Contacts or {}
	p.Apps = p.Apps or {}
	return p
end

local function contactName(id: string): string
	local c = Story.Contacts[id]
	return if c then c.Name else id
end

---------------------------------------------------------------- texts

function PhoneService.text(player: Player, contactId: string, text: string, opts: { [string]: any }?): boolean
	local p = phoneData(player)
	if not p or type(text) ~= "string" or text == "" then
		return false
	end
	local o = opts or {}
	local msg: { [string]: any } = { me = false, text = text, t = os.time() }
	if type(o.link) == "table" then
		msg.link = o.link
	end
	p.Texts[contactId] = PhoneRules.appendText(p.Texts[contactId] or {}, msg)
	p.Contacts[contactId] = true
	if not o.silent then
		p.Unread[contactId] = (p.Unread[contactId] or 0) + 1
	end
	DataService.push(player)
	fire(player, { type = "text", contact = contactId, name = contactName(contactId), text = text, silent = o.silent == true })
	PhoneService.TextSent:Fire(player, contactId, text)
	return true
end

-- A line the PLAYER "sent" (scripted replies, e.g. after a choice). Never counts as unread.
function PhoneService.textFromMe(player: Player, contactId: string, text: string)
	local p = phoneData(player)
	if not p then
		return
	end
	p.Texts[contactId] = PhoneRules.appendText(p.Texts[contactId] or {}, { me = true, text = text, t = os.time() })
	p.Contacts[contactId] = true
	DataService.push(player)
end

---------------------------------------------------------------- notifications / apps

function PhoneService.notify(player: Player, n: { app: string?, title: string, text: string? })
	fire(player, { type = "notify", app = n.app, title = n.title, text = n.text or "" })
end

function PhoneService.openApp(player: Player, appId: string)
	fire(player, { type = "open", app = appId })
end

function PhoneService.unlockApp(player: Player, appId: string)
	local p = phoneData(player)
	if not p or p.Apps[appId] then
		return
	end
	p.Apps[appId] = true
	DataService.push(player)
	local info = PhoneRules.appInfo(appId)
	fire(player, { type = "unlockApp", app = appId, title = if info then info.title else appId })
end

---------------------------------------------------------------- calls

function PhoneService.isInCall(player: Player): boolean
	return calls[player] ~= nil
end

local function addRecent(player: Player, callId: string?, contact: string, kind: string, callBack: boolean)
	local p = phoneData(player)
	if not p then
		return
	end
	if callId then
		PhoneRules.clearCallBack(p.Recents, callId)
	end
	PhoneRules.addRecent(p.Recents, {
		call = callId,
		contact = contact,
		kind = kind,
		t = os.time(),
		callBack = callBack,
		seen = kind ~= "missed",
	})
	p.Contacts[contact] = true
	DataService.push(player)
end

local function endCall(player: Player, outcome: string)
	local c = calls[player]
	if not c then
		return
	end
	calls[player] = nil
	fire(player, { type = "call", state = "ended", call = c.id, outcome = outcome })
	log(player.Name, "call", c.id, "->", outcome)
	PhoneService.CallEnded:Fire(player, c.id, outcome)
end

local function connect(player: Player, c: CallState)
	local cfg = PhoneConfig.Calls[c.id]
	c.state = "connected"
	fire(player, {
		type = "call",
		state = "connected",
		call = c.id,
		contact = cfg.contact,
		name = contactName(cfg.contact),
		lines = cfg.lines,
		choices = cfg.choices,
		outgoing = c.outgoing,
	})
end

-- Rings the player with a scripted call from Config/Phone.Calls. Returns false if they're already on a call.
function PhoneService.call(player: Player, callId: string): boolean
	local cfg = PhoneConfig.Calls[callId]
	assert(cfg, "[MTL Phone] unknown call " .. tostring(callId))
	if calls[player] or not DataService.get(player) then
		return false
	end
	tokenCounter += 1
	local c: CallState = { id = callId, state = "ringing", token = tokenCounter, outgoing = false }
	calls[player] = c
	fire(player, { type = "call", state = "ringing", call = callId, contact = cfg.contact, name = contactName(cfg.contact) })
	log(player.Name, "ringing", callId)
	local token = c.token
	task.delay(PhoneConfig.Tuning.RingSeconds, function()
		local now = calls[player]
		if now and now.token == token and now.state == "ringing" then
			addRecent(player, callId, cfg.contact, "missed", cfg.callBack == true)
			endCall(player, "missed")
		end
	end)
	return true
end

local function onAnswer(player: Player, payload: any)
	local c = calls[player]
	if c and c.state == "ringing" and payload.call == c.id then
		connect(player, c)
	end
end

local function onDecline(player: Player, payload: any)
	local c = calls[player]
	if c and c.state == "ringing" and payload.call == c.id then
		local cfg = PhoneConfig.Calls[c.id]
		addRecent(player, c.id, cfg.contact, "declined", cfg.callBack == true)
		endCall(player, "declined")
	end
end

local function onChoice(player: Player, payload: any)
	local c = calls[player]
	if not (c and c.state == "connected" and payload.call == c.id) then
		return
	end
	local choice = payload.choice
	if not PhoneRules.validChoice(c.id, choice) then
		return
	end
	local cfg = PhoneConfig.Calls[c.id]
	local keep = false
	for _, ch in cfg.choices or {} do
		if ch.id == choice and ch.keepCallBack then
			keep = true
		end
	end
	addRecent(player, c.id, cfg.contact, if c.outgoing then "outgoing" else "answered", keep and cfg.callBack == true)
	endCall(player, choice)
end

local function onHangUp(player: Player, payload: any)
	local c = calls[player]
	if not (c and c.state == "connected" and payload.call == c.id) then
		return
	end
	local cfg = PhoneConfig.Calls[c.id]
	if cfg.choices then
		-- hung up before answering the question: they can call back
		addRecent(player, c.id, cfg.contact, if c.outgoing then "outgoing" else "answered", cfg.callBack == true)
		endCall(player, "hungUp")
	else
		addRecent(player, c.id, cfg.contact, if c.outgoing then "outgoing" else "answered", false)
		endCall(player, "answered")
	end
end

local function onCallBack(player: Player, payload: any)
	local p = phoneData(player)
	if not p or calls[player] or type(payload.call) ~= "string" then
		return
	end
	local entry = PhoneRules.findCallBack(p.Recents, payload.call)
	if not entry or not PhoneConfig.Calls[payload.call] then
		return
	end
	tokenCounter += 1
	local c: CallState = { id = payload.call, state = "connected", token = tokenCounter, outgoing = true }
	calls[player] = c
	connect(player, c)
end

---------------------------------------------------------------- lifestyle / settings

function PhoneService.addPathGuard(fn: (Player, string) -> (boolean, string?))
	table.insert(pathGuards, fn)
end

-- force = story/admin switch (skips stage, cooldown and guards).
function PhoneService.setPath(player: Player, wanted: string, force: boolean?): (boolean, string?)
	local data = DataService.get(player)
	if not data then
		return false, "Not loaded"
	end
	if not force then
		local ok, reason = PhoneRules.canSwitchPath(data.Story.Stage, data.Path, wanted, lastPathSwitch[player] or -1e9, os.clock())
		if not ok then
			return false, reason
		end
		for _, guard in pathGuards do
			local gOk, gReason = guard(player, wanted)
			if not gOk then
				return false, gReason or "Can't switch right now"
			end
		end
	elseif wanted ~= "Civilian" and wanted ~= "Criminal" then
		return false, "Unknown lifestyle"
	end
	local old = data.Path
	if old == wanted then
		return true, nil
	end
	data.Path = wanted
	lastPathSwitch[player] = os.clock()
	player:SetAttribute("MTL_Path", wanted)
	DataService.push(player)
	log(player.Name, "path", old, "->", wanted)
	PhoneService.PathChanged:Fire(player, wanted, old)
	return true, nil
end

local function onSetPath(player: Player, payload: any)
	local ok, reason = PhoneService.setPath(player, payload.path)
	if ok then
		Notify.toast(player, "Lifestyle: " .. tostring(payload.path), if payload.path == "Criminal" then Color3.fromRGB(255, 86, 96) else nil)
	else
		Notify.toast(player, reason or "Can't switch right now")
	end
	fire(player, { type = "pathResult", ok = ok, reason = reason })
end

local function onSetSetting(player: Player, payload: any)
	local data = DataService.get(player)
	if data and PhoneRules.validSetting(payload.key, payload.value) then
		data.Settings[payload.key] = payload.value
		DataService.push(player)
	end
end

---------------------------------------------------------------- GPS / links

-- Sets the GPS route to a place id from Config/Phone.Places (server checks it's visible to this player).
function PhoneService.route(player: Player, placeId: string): boolean
	local data = DataService.get(player)
	local place = PhoneRules.place(placeId)
	if not data or not place then
		return false
	end
	local ownsHome = next(data.Home.Owned) ~= nil
	if not PhoneRules.placeVisible(place, data.Story.Stage, ownsHome) then
		return false
	end
	local pos, radius = PhoneRules.placePosition(place, Locations)
	if not pos then
		warn("[MTL Phone] no position for place", placeId)
		return false
	end
	WaypointService.set(player, PhoneConfig.GPSWaypointId, pos, { label = place.label, radius = radius })
	player:SetAttribute("MTL_GPS", placeId)
	return true
end

function PhoneService.clearRoute(player: Player)
	WaypointService.clear(player, PhoneConfig.GPSWaypointId)
	player:SetAttribute("MTL_GPS", nil)
end

local function onOpenLink(player: Player, payload: any)
	local p = phoneData(player)
	if not p or type(payload.contact) ~= "string" or type(payload.index) ~= "number" then
		return
	end
	local thread = p.Texts[payload.contact]
	local msg = thread and thread[math.floor(payload.index)]
	local link = msg and msg.link
	if type(link) ~= "table" then
		return
	end
	if link.kind == "waypoint" and type(link.place) == "string" then
		if PhoneService.route(player, link.place) then
			Notify.toast(player, "Route set: " .. (link.label or link.place))
		end
	elseif link.kind == "app" and type(link.app) == "string" then
		PhoneService.openApp(player, link.app)
	end
end

---------------------------------------------------------------- actions

function PhoneService.onAction(actionType: string, fn: (Player, any) -> ())
	assert(handlers[actionType] == nil, "[MTL Phone] action already handled: " .. actionType)
	handlers[actionType] = fn
end

-- Messages quick replies: the player sends one of Config/Phone.QuickReplies into a thread they already have;
-- the contact may answer back with a canned line after a short pause.
local lastReply: { [Player]: number } = {}
local lastAutoReply: { [Player]: { [string]: number } } = {}

local function onQuickReply(player: Player, payload: any)
	local p = phoneData(player)
	local contact, index = payload.contact, payload.index
	if not p or type(contact) ~= "string" or type(index) ~= "number" then
		return
	end
	local text = PhoneConfig.QuickReplies[math.floor(index)]
	if not text or not p.Contacts[contact] or not p.Texts[contact] then
		return
	end
	local now = os.clock()
	if now - (lastReply[player] or -1e9) < PhoneConfig.ReplyCooldown then
		return
	end
	lastReply[player] = now
	PhoneService.textFromMe(player, contact, text)
	local seen = lastAutoReply[player] or {}
	lastAutoReply[player] = seen
	if now - (seen[contact] or -1e9) < PhoneConfig.AutoReplyCooldown then
		return
	end
	seen[contact] = now
	local pool = PhoneConfig.AutoReplies[contact] or PhoneConfig.AutoReplies.default
	if not pool or #pool == 0 then
		return
	end
	local answer = pool[math.random(1, #pool)]
	fire(player, { type = "typing", contact = contact })
	task.delay(1.6 + math.random() * 1.4, function()
		if player.Parent then
			PhoneService.text(player, contact, answer)
		end
	end)
end

local builtIn: { [string]: (Player, any) -> () } = {
	quickReply = onQuickReply,
	answerCall = onAnswer,
	declineCall = onDecline,
	callChoice = onChoice,
	hangUp = onHangUp,
	callBack = onCallBack,
	setPath = onSetPath,
	setSetting = onSetSetting,
	openLink = onOpenLink,
	readThread = function(player, payload)
		local p = phoneData(player)
		if p and type(payload.contact) == "string" and p.Unread[payload.contact] then
			p.Unread[payload.contact] = nil
			DataService.push(player)
		end
	end,
	seenRecents = function(player)
		local p = phoneData(player)
		if not p then
			return
		end
		local changed = false
		for _, r in p.Recents do
			if not r.seen then
				r.seen = true
				changed = true
			end
		end
		if changed then
			DataService.push(player)
		end
	end,
	gpsRoute = function(player, payload)
		if type(payload.place) == "string" then
			PhoneService.route(player, payload.place)
		end
	end,
	gpsClear = function(player)
		PhoneService.clearRoute(player)
	end,
}

function PhoneService.init()
	Net.get("PhoneAction").OnServerEvent:Connect(function(player: Player, payload: any)
		if type(payload) ~= "table" or type(payload.type) ~= "string" then
			return
		end
		if not limiter:allow(player) or not DataService.get(player) then
			return
		end
		local fn = builtIn[payload.type] or handlers[payload.type]
		if not fn then
			if payload.type == "chooseJob" then
				Notify.toast(player, "Jobs open in the next update") -- until the Jobs piece registers chooseJob
			end
			return
		end
		local ok, err = pcall(fn, player, payload)
		if not ok then
			warn("[MTL Phone] action", payload.type, "failed:", err)
		end
	end)

	DataService.Ready:Connect(function(player, data)
		player:SetAttribute("MTL_Path", data.Path)
		-- apps added to Config after a save was made get installed if they're defaults
		for _, app in PhoneConfig.Apps do
			if app.default and data.Phone.Apps[app.id] == nil then
				data.Phone.Apps[app.id] = true
			end
		end
	end)

	-- a client that (re)starts listening mid-ring sees the ring again
	Net.get("ClientReady").OnServerEvent:Connect(function(player)
		local c = calls[player]
		if c then
			local cfg = PhoneConfig.Calls[c.id]
			if c.state == "ringing" then
				fire(player, { type = "call", state = "ringing", call = c.id, contact = cfg.contact, name = contactName(cfg.contact) })
			else
				connect(player, c)
			end
		end
	end)

	WaypointService.Arrived:Connect(function(player, id)
		if id == PhoneConfig.GPSWaypointId then
			local place = PhoneRules.place(player:GetAttribute("MTL_GPS"))
			player:SetAttribute("MTL_GPS", nil)
			Notify.toast(player, "Arrived" .. (if place then ": " .. place.label else ""))
		end
	end)

	Players.PlayerRemoving:Connect(function(player)
		calls[player] = nil
		lastPathSwitch[player] = nil
		lastReply[player] = nil
		lastAutoReply[player] = nil
	end)
end

return PhoneService
]======])
put("ServerScriptService/MTL/Services", "PhoneStory", "ModuleScript", [======[--!strict
-- Story beats that arrive through the phone. Kept apart from PhoneService (pure phone plumbing) and StoryService
-- (the stage machine) so neither has to require the other. The Story thread extends THIS file for later stages.
--   Arrive  -> text from Mr. Patel ("you start today, come inside")
--   FirstShift, Level 3 (Levels.CriminalTeaseLevel) -> one short text from "Unknown" so the call at Level 4 isn't
--              out of nowhere. Once (skipped if the Unknown thread already has anything in it).
--   TheCall -> the unknown number rings. "I'm in" moves the story to GangMeet. Declined / missed / hung up:
--              the call waits in Recents with a call-back button and the objective says so. Never forced.
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Levels = require(ReplicatedStorage.MTL.Config.Levels)
local PhoneRules = require(ReplicatedStorage.MTL.Rules.PhoneRules)
local DataService = require(script.Parent.DataService)
local EconomyService = require(script.Parent.EconomyService)
local StoryService = require(script.Parent.StoryService)
local PhoneService = require(script.Parent.PhoneService)
local Notify = require(script.Parent.Notify)

local PhoneStory = {}

local RECRUIT = "Recruit"

local function hasText(player: Player, contact: string): boolean
	local data = DataService.get(player)
	local thread = data and data.Phone.Texts and data.Phone.Texts[contact]
	return thread ~= nil and #thread > 0
end

local function canCallBack(player: Player, callId: string): boolean
	local data = DataService.get(player)
	return data ~= nil and PhoneRules.findCallBack(data.Phone.Recents or {}, callId) ~= nil
end

local function ringRecruit(player: Player, delaySeconds: number)
	task.delay(delaySeconds, function()
		if player.Parent and StoryService.stage(player) == "TheCall" and not PhoneService.isInCall(player) then
			PhoneService.call(player, RECRUIT)
		end
	end)
end

function PhoneStory.init()
	-- 1. Arrive: the boss texts you (once; a rejoin keeps the old text in Messages)
	StoryService.onEnter("Arrive", function(player, resumed)
		if resumed and hasText(player, "Patel") then
			return
		end
		task.wait(1.5)
		PhoneService.text(player, "Patel", "Hey, it's Mr. Patel from Liberty Food Mart. You start today!")
		task.wait(1.2)
		PhoneService.text(player, "Patel", "Come inside the store, I'll show you the shelves.")
	end)

	-- 2. FirstShift: the tease. Waits out the level-up banner, then buzzes once.
	EconomyService.LevelUp:Connect(function(player, level)
		if level ~= Levels.CriminalTeaseLevel or level >= Levels.CriminalCallLevel then
			return
		end
		task.delay(4, function()
			if player.Parent and StoryService.stage(player) == "FirstShift" and not hasText(player, "Unknown") then
				PhoneService.text(player, "Unknown", "saw you working at Patel's. you move quick.")
				task.wait(1.4)
				PhoneService.text(player, "Unknown", "keep your phone on.")
			end
		end)
	end)

	-- 3. TheCall: ring. Resumed with a call waiting in Recents -> just remind; otherwise ring again.
	StoryService.onEnter("TheCall", function(player, resumed)
		if resumed and canCallBack(player, RECRUIT) then
			Notify.objective(player, "Call back the unknown number")
			return
		end
		ringRecruit(player, if resumed then 6 else 3)
	end)

	PhoneService.CallEnded:Connect(function(player, callId, outcome)
		if callId ~= RECRUIT or StoryService.stage(player) ~= "TheCall" then
			return
		end
		if outcome == "accept" then
			PhoneService.textFromMe(player, "Unknown", "I'm in.")
			StoryService.advance(player, "TheCall")
		else
			Notify.objective(player, "Call back the unknown number")
			if outcome == "missed" then
				Notify.toast(player, "Missed call: Unknown number")
			end
		end
	end)
end

return PhoneStory
]======])
put("ServerScriptService/MTL/Services", "ProfileSchema", "ModuleScript", [======[--!strict
-- The save template (Master Plan §3.4) and the public snapshot sent to the owning client.
-- Adding a field: add it here with a default (Reconcile fills it in for old saves) and note it in the Master Plan.
-- Never rename or remove a field without a migration in DataService.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Economy = require(ReplicatedStorage.MTL.Config.Economy)
local StoryRules = require(ReplicatedStorage.MTL.Rules.StoryRules)

local Schema = {}

Schema.StoreName = "MTL_Profile_v1"
Schema.Version = 1

Schema.Template = {
	Version = 1,
	Cash = Economy.StartCash,
	Bank = 0,
	XP = 0,
	Level = 1,
	Path = "Civilian", -- "Civilian" | "Criminal"
	Story = { Stage = StoryRules.first(), Done = {}, Data = {} }, -- Data: per-stage scratch (e.g. chosen meet spot)
	Job = { Current = "", Shifts = {}, TasksDone = {} },
	Home = { Owned = {}, Current = "", PowerPaidUntil = 0, PowerOn = false }, -- Owned[homeId] = os.time() bought · PowerOn (Piece 4: one bill turns it on)
	Goals = { Done = {} }, -- Piece 4: Done[goalId] = os.time() the FreePlay goal's reward was given (Config/Goals)
	Inventory = { Guns = {}, Ammo = {}, Mags = {}, Items = {} }, -- Guns[gunId]=true · Ammo[ammoType]=reserve rounds · Mags[gunId]=rounds in the mag
	Phone = { Contacts = {}, Texts = {}, Unread = {}, Recents = {}, Apps = { Jobs = true, Messages = true, Calls = true, Map = true, Settings = true, Goals = false } }, -- shapes: Rules/PhoneRules · Goals unlocks at FreePlay (Piece 4)
	Boosts = { XP2xSeconds = 0, Cash2xSeconds = 0 }, -- remaining PLAY seconds
	Purchases = {}, -- [PurchaseId] = os.time()
	Stats = { Earned = 0, Spent = 0, Robberies = 0, PlayTime = 0, Joins = 0 },
	Settings = { Music = true, Sound = true, ReducedMotion = false },
}

local PRIVATE = { Purchases = true }

local function deepCopy(t: any): any
	if type(t) ~= "table" then
		return t
	end
	local out = {}
	for k, v in t do
		out[k] = deepCopy(v)
	end
	return out
end
Schema.deepCopy = deepCopy

-- Fixes anything a bad save or an old version could have broken. Returns the same table.
function Schema.sanitize(data: any)
	if type(data.Cash) ~= "number" or data.Cash ~= data.Cash then
		data.Cash = Economy.StartCash
	end
	data.Cash = math.clamp(math.floor(data.Cash), 0, Economy.MaxCash)
	if type(data.Level) ~= "number" or data.Level < 1 then
		data.Level = 1
	end
	if type(data.XP) ~= "number" or data.XP < 0 then
		data.XP = 0
	end
	if data.Path ~= "Civilian" and data.Path ~= "Criminal" then
		data.Path = "Civilian"
	end
	if not StoryRules.isValid(data.Story.Stage) then
		data.Story.Stage = StoryRules.first()
	end
	return data
end

function Schema.public(data: any)
	local out = {}
	for k, v in data do
		if not PRIVATE[k] then
			out[k] = deepCopy(v)
		end
	end
	return out
end

return Schema
]======])
put("ServerScriptService/MTL/Services", "PropertyService", "ModuleScript", [======[--!strict
-- Story Piece 4: homes. Buying the flat in the Ends, the instanced dirty room, walking in and out, the power bill,
-- the bed, and the story stages that happen at home (Master Plan §1 stages 8-12; 13 FreePlay's welcome).
--
--   8  FindAPlace     Dre texts, Story waypoint to the flat's door, the FOR SALE card pops up when you get there
--                     (and from the door prompt). BUY -> cash spent, the flat is yours -> MoveIn.
--   9  MoveIn         fade into YOUR copy of the room, you're sat on the bed (hidden), the PowerOut cutscene plays
--                     (sit at the PC, no power, keyboard smash, bed, phone) -> ChooseJob.
--   10 ChooseJob      the phone rises on the Jobs app (client); JobService advances when a job is picked.
--   11 FirstNight     the bed glows + "Sleep" prompt (outside: a waypoint home). Sleep -> NextDay cutscene -> 12.
--   12 CommuteToWork  the boss texts; waypoint to the front door, then (outside) to work. JobService advances on
--                     clock-in. 13 FreePlay: the Goals app unlocks (GoalService runs the list).
--
-- Rooms: one per owner, built far from the map at a slot (Config/Property.Slots), streamed to the owner only
-- (PersistentPerPlayer). Alex's model ServerStorage.MTL_FlatInterior replaces the placeholder (see Config/Property).
--
-- API:
--   PropertyService.owns(player, homeId?) -> bool       PropertyService.isInside(player) -> bool
--   PropertyService.room(player) -> Room?               (builds it if the player owns a home)
--   PropertyService.enter(player, opts?) / leave(player, opts?)    opts.instant = no fade, opts.keepBlack = no fade-in
--   PropertyService.payPower(player) -> ok, reason      PropertyService.give(player, homeId)  (Studio / story safety)
--   Signals: Bought(player, homeId) · Entered(player, homeId) · Left(player, homeId) · PowerChanged(player, on)
-- Player attribute MTL_InHome = homeId while inside (the Jobs app measures distances from the front door then).
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ServerStorage = game:GetService("ServerStorage")
local CollectionService = game:GetService("CollectionService")
local RunService = game:GetService("RunService")

