---------------------------------------------------------------- rooms

local function template(): Model?
	local t = ServerStorage:FindFirstChild("MTL_FlatInterior")
	return if t and t:IsA("Model") and t.PrimaryPart then t else nil
end

local function promptOn(room: Room, key: string, at: BasePart, opts: { [string]: any }): ProximityPrompt
	local p = Instance.new("ProximityPrompt")
	p.Name = "MTL_Prompt_" .. key
	p.ActionText = opts.action or "Use"
	p.ObjectText = opts.object or ""
	p.HoldDuration = opts.hold or 0
	p.MaxActivationDistance = opts.distance or Property.Interior.PromptDistance
	p.RequiresLineOfSight = false
	p.Parent = at
	room.prompts[key] = p
	return p
end

local onRoomPrompt: (Player, Room, string) -> () -- set below

local function bedText(player: Player): string
	return if StoryService.stage(player) == "FirstNight" then "Sleep" else "Sit"
end

local function buildRoom(player: Player, homeId: string): Room?
	local slot = PropertyRules.freeSlot(takenSlots)
	if not slot then
		warn("[MTL Property] no free room slot for", player.Name)
		return nil
	end
	local t = template()
	local model: Model
	if t then
		local was = t.Archivable
		t.Archivable = true
		model = t:Clone()
		t.Archivable = was
	else
		model = buildPlaceholder()
	end
	local origin = CFrame.new(PropertyRules.slotOrigin(slot))
	model:PivotTo(origin)
	model.Name = "Flat_" .. player.UserId
	model:SetAttribute("Owner", player.UserId)
	model:SetAttribute("Home", homeId)
	local d = DataService.get(player)
	model:SetAttribute("PowerOn", d ~= nil and d.Home.PowerOn == true)
	pcall(function()
		model.ModelStreamingMode = Enum.ModelStreamingMode.PersistentPerPlayer
	end)
	model.Parent = folder("MTL_Flats")
	pcall(function()
		model:AddPersistentPlayer(player)
	end)
	takenSlots[slot] = true
	local room: Room = {
		owner = player,
		home = homeId,
		slot = slot,
		model = model,
		origin = origin,
		marks = {},
		parts = {},
		seat = nil,
		prompts = {},
	}
	for name, default in Property.Interior.Points do
		local p = model:FindFirstChild(name, true)
		if p and p:IsA("BasePart") then
			room.parts[name] = p
			room.marks[name] = origin:PointToObjectSpace(p.Position)
		else
			room.marks[name] = default
		end
	end
	for _, extra in { "ExitDoor", "Mattress" } do
		local p = model:FindFirstChild(extra, true)
		if p and p:IsA("BasePart") then
			room.parts[extra] = p
		end
	end
	local seat = model:FindFirstChild("BedSeat", true)
	room.seat = if seat and seat:IsA("Seat") then seat else nil
	-- prompts (this room is only ever reached by its owner, so the server can set the texts)
	local function anchorPart(name: string, lift: number): BasePart
		local base = room.parts[name]
		local pos = if base then base.Position else origin:PointToWorldSpace(room.marks[name])
		local a = Instance.new("Part")
		a.Name = "PromptAt_" .. name
		a.Size = V(0.4, 0.4, 0.4)
		a.Transparency = 1
		a.Anchored = true
		a.CanCollide = false
		a.CanQuery = false
		a.CanTouch = false
		a.Position = pos + V(0, lift, 0)
		a.Parent = model
		return a
	end
	local h = Property.Homes[homeId]
	promptOn(room, "Exit", room.parts.ExitDoor or anchorPart("Exit", 3), { action = "Leave", object = h and h.title or "" })
	promptOn(room, "Bed", anchorPart("BedSeat", 0.8), { action = bedText(player), object = "Bed" })
	promptOn(room, "PC", room.parts.Screen or anchorPart("Screen", 0), { action = "Use PC", object = "PC" })
	promptOn(room, "Breaker", room.parts.Breaker or anchorPart("Breaker", 0), {
		action = "Pay power bill · " .. money(Property.Power.Bill),
		object = "Breaker box",
		hold = 0.5,
	})
	for key, p in room.prompts do
		p.Triggered:Connect(function(who)
			if who == player then
				onRoomPrompt(player, room, key)
			end
		end)
	end
	if d and d.Home.PowerOn then
		room.prompts.Breaker.Enabled = false
	end
	rooms[player] = room
	log(player.Name, "room built in slot", slot, if t then "(Alex's model)" else "(placeholder)")
	return room
end

function PropertyService.room(player: Player): Room?
	local r = rooms[player]
	if r and r.model.Parent then
		return r
	end
	local homeId = homeOf(player)
	if not homeId then
		return nil
	end
	return buildRoom(player, homeId)
end

local function roomCFrame(room: Room, mark: string, faceTo: Vector3?): CFrame
	local p = room.origin:PointToWorldSpace(room.marks[mark])
	local dir = if faceTo then (faceTo - p) else room.origin:VectorToWorldSpace(V(0, 0, -1))
	dir = V(dir.X, 0, dir.Z)
	if dir.Magnitude < 0.01 then
		dir = V(0, 0, -1)
	end
	return CFrame.lookAt(p, p + dir.Unit)
end

local function syncPrompts(player: Player)
	local room = rooms[player]
	if not room then
		return
	end
	room.prompts.Bed.ActionText = bedText(player)
	local d = DataService.get(player)
	room.prompts.Breaker.Enabled = not (d and d.Home.PowerOn)
end

---------------------------------------------------------------- moving in and out

local function unseat(player: Player)
	local hum = humanoid(player)
	if hum and hum.SeatPart then
		local w = hum.SeatPart:FindFirstChild("SeatWeld")
		if w then
			w:Destroy()
		end
		hum.Sit = false
	end
end

local function teleport(player: Player, cf: CFrame, hold: boolean?)
	local char = player.Character
	local r = root(player)
	if not char or not r then
		return
	end
	unseat(player)
	pcall(function()
		player:RequestStreamAroundAsync(cf.Position, 4)
	end)
	-- hold the body still for a moment so it can't drop through a floor that is still streaming in
	local still = hold ~= false
	if still then
		r.Anchored = true
	end
	char:PivotTo(cf + V(0, 3, 0))
	r.AssemblyLinearVelocity = Vector3.zero
	if still then
		task.delay(0.6, function()
			if r.Parent then
				r.Anchored = false
			end
		end)
	end
end

local function setInside(player: Player, room: Room?, on: boolean)
	inside[player] = on
	player:SetAttribute("MTL_InHome", if on and room then room.home else nil)
end

-- Fade -> teleport -> fade in. opts.instant: no fade (spawning). opts.keepBlack: stay black (a cutscene follows).
local function move(player: Player, cf: CFrame, opts: { [string]: any }?)
	local o = opts or {}
	if o.instant then
		teleport(player, cf)
		return
	end
	fire(player, { type = "fade", seconds = Property.Door.FadeOut })
	task.wait(Property.Door.FadeOut)
	pcall(function()
		player:RequestStreamAroundAsync(cf.Position, 4)
	end)
	task.wait(Property.Door.Hold)
	teleport(player, cf)
	if not o.keepBlack then
		fire(player, { type = "arrived" })
	end
end

function PropertyService.enter(player: Player, opts: { [string]: any }?): Room?
	local room = PropertyService.room(player)
	if not room then
		return nil
	end
	if inside[player] then
		return room
	end
	local exitPos = room.origin:PointToWorldSpace(room.marks.Exit)
	local entry = room.origin:PointToWorldSpace(room.marks.Entry)
	move(player, roomCFrame(room, "Entry", entry + (entry - exitPos)), opts)
	setInside(player, room, true)
	syncPrompts(player)
	PropertyService.Entered:Fire(player, room.home)
	return room
end

local function outsideCFrame(homeId: string): CFrame
	local h = Property.Homes[homeId]
	local loc = (Locations :: any)[h and h.location or "EndsFlat"]
	local door, out = loc.Door, loc.Out or (loc.Door + V(0, 0, -8))
	local away = out - door
	away = V(away.X, 0, away.Z)
	if away.Magnitude < 0.01 then
		away = V(0, 0, -1)
	end
	return CFrame.lookAt(out, out + away.Unit)
end

function PropertyService.leave(player: Player, opts: { [string]: any }?)
	local room = rooms[player]
	if not room or not inside[player] then
		return
	end
	move(player, outsideCFrame(room.home), opts)
	setInside(player, room, false)
	PropertyService.Left:Fire(player, room.home)
end

local function seatOnBed(player: Player, room: Room)
	local hum = humanoid(player)
	if not hum or not room.seat then
		return
	end
	local r = root(player)
	if r then
		r.Anchored = false -- a seat can't pull an anchored body onto it
	end
	teleport(player, room.seat.CFrame, false)
	task.wait()
	pcall(function()
		(room.seat :: Seat):Sit(hum)
	end)
end

---------------------------------------------------------------- buying

local function sendListing(player: Player, homeId: string)
	local d = DataService.get(player)
	local h = Property.Homes[homeId]
	if not d or not h then
		return
	end
	local ok, reason, short = PropertyRules.canBuy(d, homeId)
	fire(player, {
		type = "listing",
		home = homeId,
		title = h.title,
		area = h.area,
		price = h.price,
		blurb = h.blurb,
		facts = h.facts,
		photo = h.photo,
		cash = d.Cash,
		canBuy = ok,
		reason = reason,
		short = short,
	})
	Analytics.funnel(player, "Flat", tostring(player.UserId), 1, "Listing")
end

local function doorPosition(homeId: string): Vector3
	for _, p in CollectionService:GetTagged("MTL_FlatDoor") do
		if p:IsA("BasePart") and p:GetAttribute("Id") == homeId then
			return p.Position
		end
	end
	local h = Property.Homes[homeId]
	return ((Locations :: any)[h.location]).Door
end

local function nearDoor(player: Player, homeId: string): boolean
	local r = root(player)
	if not r then
		return false
	end
	local d = r.Position - doorPosition(homeId)
	return Vector2.new(d.X, d.Z).Magnitude <= Property.Door.Radius + 4 and math.abs(d.Y) < 20
end

function PropertyService.give(player: Player, homeId: string)
	local d = DataService.get(player)
	if not d or not Property.Homes[homeId] then
		return
	end
	d.Home.Owned[homeId] = d.Home.Owned[homeId] or os.time()
	d.Home.Current = homeId
	DataService.push(player)
end

local function buy(player: Player, homeId: string)
	local d = DataService.get(player)
	local h = Property.Homes[homeId]
	if not d or not h or busy[player] then
		return
	end
	local ok, reason, short = PropertyRules.canBuy(d, homeId)
	if not ok then
		if short > 0 then
			Notify.toast(player, "You need " .. money(short) .. " more.")
		else
			Notify.toast(player, reason or "Can't buy that")
		end
		sendListing(player, homeId)
		return
	end
	if not nearDoor(player, homeId) then
		Notify.toast(player, "Go to the front door to buy it.")
		return
	end
	if not EconomyService.spend(player, h.price, "Home:" .. homeId) then
		sendListing(player, homeId)
		return
	end
	PropertyService.give(player, homeId)
	fire(player, { type = "listing", close = true, bought = true })
	Notify.banner(player, "IT'S YOURS", h.title .. " · " .. h.area)
	Analytics.funnel(player, "Flat", tostring(player.UserId), 2, "Bought")
	log(player.Name, "bought", homeId, "for", h.price)
	WaypointService.clear(player, "Story")
	PropertyService.Bought:Fire(player, homeId)
	task.wait(1.2) -- let the banner land before the fade
	if not player.Parent then
		return
	end
	if StoryService.stage(player) == "FindAPlace" then
		StoryService.advance(player, "FindAPlace") -- MoveIn walks you in
	else
		PropertyService.enter(player)
	end
end

---------------------------------------------------------------- power

function PropertyService.payPower(player: Player): (boolean, string?)
	local d = DataService.get(player)
	if not d then
		return false, "Loading"
	end
	if not PropertyRules.ownsAny(d) then
		return false, "You don't have a place yet"
	end
	if d.Home.PowerOn then
		return false, "The power's already on"
	end
	local bill = Property.Power.Bill
	if not EconomyService.spend(player, bill, "Bill:Power") then
		return false, "You need " .. money(bill - d.Cash) .. " more for the power bill"
	end
	d.Home.PowerOn = true
	DataService.push(player)
	local room = rooms[player]
	if room then
		room.model:SetAttribute("PowerOn", true)
	end
	syncPrompts(player)
	Notify.toast(player, "Power's on. The light finally stopped flickering.")
	fire(player, { type = "power", on = true })
	PropertyService.PowerChanged:Fire(player, true)
	log(player.Name, "paid the power bill")
	return true, nil
end

---------------------------------------------------------------- scenes

local function playMoveIn(player: Player)
	if busy[player] then
		return
	end
	busy[player] = true
	local d = DataService.get(player)
	if d and not PropertyRules.ownsAny(d) then
		warn("[MTL Property]", player.Name, "is at MoveIn without a home; giving the starter flat")
		PropertyService.give(player, Property.StarterHome)
	end
	local wasInside = inside[player]
	local room = PropertyService.enter(player, { keepBlack = true })
	if not room or not player.Parent then
		busy[player] = nil
		return
	end
	seatOnBed(player, room) -- hidden during the scene; when it ends you're sat right where the scene left you
	CutsceneService.play(player, "PowerOut", { anchor = room.origin, marks = room.marks })
	busy[player] = nil
	if not player.Parent then
		return
	end
	if wasInside then
		fire(player, { type = "arrived" }) -- (no fade was used; harmless)
	end
	StoryService.advance(player, "MoveIn")
end

local function playSleep(player: Player)
	local room = rooms[player]
	if busy[player] or not room or StoryService.stage(player) ~= "FirstNight" then
		return
	end
	busy[player] = true
	fire(player, { type = "bed", on = false })
	seatOnBed(player, room)
	CutsceneService.play(player, "NextDay", { anchor = room.origin, marks = room.marks })
	busy[player] = nil
	if not player.Parent then
		return
	end
	local exitPos = room.origin:PointToWorldSpace(room.marks.Exit)
	teleport(player, roomCFrame(room, "BedStand", exitPos))
	StoryService.advance(player, "FirstNight")
end

---------------------------------------------------------------- prompts

onRoomPrompt = function(player: Player, room: Room, key: string)
	if busy[player] or not limiter:allow(player) then
		return
	end
	if key == "Exit" then
		PropertyService.leave(player)
	elseif key == "Bed" then
		if StoryService.stage(player) == "FirstNight" then
			playSleep(player)
		else
			seatOnBed(player, room)
		end
	elseif key == "PC" then
		local d = DataService.get(player)
		Notify.toast(player, if d and d.Home.PowerOn then Property.PC.OnText else Property.PC.OffText)
	elseif key == "Breaker" then
		local ok, reason = PropertyService.payPower(player)
		if not ok and reason then
			Notify.toast(player, reason)
		end
	end
end

local function makeDoor(homeId: string)
	local h = Property.Homes[homeId]
	local doorPart: BasePart? = nil
	for _, p in CollectionService:GetTagged("MTL_FlatDoor") do
		if p:IsA("BasePart") and p:GetAttribute("Id") == homeId then
			doorPart = p
		end
	end
	if not doorPart then
		local p = Instance.new("Part")
		p.Name = "Door_" .. homeId
		p.Size = V(4, 7, 1)
		p.Transparency = 1
		p.Anchored = true
		p.CanCollide = false
		p.CanQuery = false
		p.CanTouch = false
		p.Position = doorPosition(homeId) + V(0, 1.5, 0)
		p.Parent = folder("MTL_Property")
		doorPart = p
	end
	assert(doorPart)
	doorPart:SetAttribute("MTL_Home", homeId)
	CollectionService:AddTag(doorPart, "MTL_HomeDoor") -- the client finds it to set its own prompt text + highlight
	local prompt = Instance.new("ProximityPrompt")
	prompt.Name = "MTL_DoorPrompt"
	prompt.ActionText = "Door" -- each client rewrites this locally ("For sale · $1,200" / "Go inside")
	prompt.ObjectText = h.title .. " · " .. h.area
	prompt.HoldDuration = 0
	prompt.MaxActivationDistance = 10
	prompt.RequiresLineOfSight = false
	prompt.Parent = doorPart
	prompt.Triggered:Connect(function(player)
		if busy[player] or not limiter:allow(player) then
			return
		end
		local now = os.clock()
		if lastDoor[player] and now - lastDoor[player] < Property.Door.EnterCooldown then
			return
		end
		lastDoor[player] = now
		local d = DataService.get(player)
		if not d then
			return
		end
		if PropertyRules.owns(d, homeId) then
			if StoryService.stage(player) == "MoveIn" then
				task.spawn(playMoveIn, player)
			else
				PropertyService.enter(player)
			end
		elseif StoryRules.reached(d.Story.Stage, "FindAPlace") then
			sendListing(player, homeId)
		else
			Notify.toast(player, "This place isn't for sale yet.")
		end
	end)
end

---------------------------------------------------------------- the commute funnel (stage 12)

local function refreshCommute(player: Player)
	if StoryService.stage(player) ~= "CommuteToWork" then
		return
	end
	local js = script.Parent:FindFirstChild("JobService")
	local JobService: any = js and require(js) :: any
	if JobService and JobService.isOnShift(player) then
		StoryService.advance(player, "CommuteToWork")
		return
	end
	local room = rooms[player]
	if inside[player] and room then
		local door = room.origin:PointToWorldSpace(room.marks.Exit)
		WaypointService.set(player, "Story", door, { label = "Front door", radius = 2.5, breadcrumbs = false })
		Notify.objective(player, "Head out to work: use the front door")
		fire(player, { type = "exit", on = true })
		return
	end
	fire(player, { type = "exit", on = false })
	local pos, label = nil, nil
	if JobService then
		pos, label = JobService.workplace(player)
	end
	if not pos then
		Notify.objective(player, "Pick a job in your phone's Jobs app")
		return
	end
	local def = Jobs.Defs[JobService.current(player)]
	local loc = def and (Locations :: any)[def.site]
	WaypointService.set(player, "Story", pos, { label = "Work: " .. tostring(label), radius = (loc and loc.Radius) or 14 })
	Notify.objective(player, "Get to work: " .. tostring(label))
end

local function refreshNight(player: Player)
	if StoryService.stage(player) ~= "FirstNight" then
		return
	end
	if inside[player] then
		WaypointService.clear(player, "Story")
		Notify.objective(player, "Get some sleep. Work starts tomorrow.")
		fire(player, { type = "bed", on = true })
	else
		fire(player, { type = "bed", on = false })
		local homeId = homeOf(player)
		if homeId then
			WaypointService.set(player, "Story", doorPosition(homeId), { label = "Home", radius = Property.Door.Radius })
			Notify.objective(player, "Go home and get some sleep")
		end
	end
end

---------------------------------------------------------------- init

function PropertyService.init()
	for id in Property.Homes do
		makeDoor(id)
	end

	Net.get("PropertyAction").OnServerEvent:Connect(function(player, payload)
		if type(payload) ~= "table" or not limiter:allow(player) then
			return
		end
		if payload.type == "buy" and type(payload.home) == "string" and Property.Homes[payload.home] then
			task.spawn(buy, player, payload.home)
		end
	end)
	PhoneService.onAction("payPower", function(player)
		local ok, reason = PropertyService.payPower(player)
		if not ok and reason then
			Notify.toast(player, reason)
		end
	end)

	-- 8. FindAPlace
	StoryService.onEnter("FindAPlace", function(player)
		local d = DataService.get(player)
		if not d then
			return
		end
		if PropertyRules.ownsAny(d) then
			StoryService.advance(player, "FindAPlace")
			return
		end
		local homeId = Property.StarterHome
		local h = Property.Homes[homeId]
		WaypointService.set(player, "Story", doorPosition(homeId), { label = h.title .. " · for sale", radius = Property.Door.Radius })
		Notify.objective(player, "Buy the flat in the Ends: " .. money(h.price))
		local sd = StoryService.data(player)
		if sd and not sd.FlatTexted then
			sd.FlatTexted = true
			task.wait(1.2)
			for i, t in Property.Texts.FindAPlace do
				PhoneService.text(player, t.who, if t.link then (t.text .. " It's on your map.") else t.text)
				if i < #Property.Texts.FindAPlace then
					task.wait(1.6)
				end
			end
		end
	end)
	WaypointService.Arrived:Connect(function(player, id)
		if id ~= "Story" then
			return
		end
		local stage = StoryService.stage(player)
		if stage == "FindAPlace" then
			sendListing(player, Property.StarterHome) -- the card pops up when you reach the door
			Notify.objective(player, "Buy the flat: " .. money(Property.Homes[Property.StarterHome].price))
		elseif stage == "CommuteToWork" and not inside[player] then
			Notify.objective(player, "Clock in at the time clock")
		elseif stage == "FirstNight" and not inside[player] then
			Notify.objective(player, "Go inside and get some sleep")
		end
	end)

	-- 9. MoveIn
	StoryService.onEnter("MoveIn", function(player)
		playMoveIn(player)
	end)

	-- 10. ChooseJob: the phone opens on the Jobs app (the client waits until the scene is over)
	StoryService.onEnter("ChooseJob", function(player)
		WaypointService.clear(player, "Story")
		fire(player, { type = "phone", app = "Jobs" })
	end)

	-- 11. FirstNight / 12. CommuteToWork
	StoryService.onEnter("FirstNight", function(player)
		syncPrompts(player)
		refreshNight(player)
	end)
	StoryService.onEnter("CommuteToWork", function(player, resumed)
		syncPrompts(player)
		if not resumed then
			local d = DataService.get(player)
			local def = d and Jobs.Defs[d.Job.Current]
			local boss = def and def.boss
			task.wait(1.4)
			if boss then
				PhoneService.text(player, boss, Property.Texts.Wake[boss] or Property.Texts.Wake.default)
			end
		end
		refreshCommute(player)
	end)

	-- 13. FreePlay: the Goals app + one welcome text (GoalService keeps the objective line on the next goal)
	StoryService.onEnter("FreePlay", function(player, resumed)
		PhoneService.unlockApp(player, "Goals")
		syncPrompts(player)
		if not resumed then
			Notify.banner(player, "FREE PLAY", "Work, hustle, get rich. Your call.")
			task.wait(2.5)
			PhoneService.text(player, Property.Texts.FreePlay.who, Property.Texts.FreePlay.text)
		end
	end)

	PropertyService.Entered:Connect(function(player)
		refreshCommute(player)
		refreshNight(player)
	end)
	PropertyService.Left:Connect(function(player)
		refreshCommute(player)
		refreshNight(player)
	end)
	StoryService.StageChanged:Connect(function(player)
		syncPrompts(player)
	end)

	-- returning players wake up at home (first spawn of the session); a respawn puts you outside like normal
	DataService.Ready:Connect(function(player, data)
		task.spawn(function()
			local char = player.Character or player.CharacterAdded:Wait()
			if not char then
				return
			end
			char:WaitForChild("HumanoidRootPart", 10)
			task.wait(0.3)
			if player.Parent and PropertyRules.spawnsAtHome(data) and data.Story.Stage ~= "MoveIn" then
				PropertyService.enter(player, { instant = true })
			end
		end)
	end)
	local function watch(player: Player)
		player.CharacterAdded:Connect(function()
			if inside[player] then
				setInside(player, rooms[player], false)
			end
			task.delay(1.5, function()
				if player.Parent then
					refreshCommute(player)
					refreshNight(player)
				end
			end)
		end)
	end
	Players.PlayerAdded:Connect(watch)
	for _, p in Players:GetPlayers() do
		watch(p)
	end
	Players.PlayerRemoving:Connect(function(player)
		local room = rooms[player]
		if room then
			takenSlots[room.slot] = nil
			room.model:Destroy()
		end
		rooms[player] = nil
		inside[player] = nil
		busy[player] = nil
		lastDoor[player] = nil
	end)

	-- respawned / rejoined clients re-get their home state (door text, bed glow)
	Net.get("ClientReady").OnServerEvent:Connect(function(player)
		local stage = StoryService.stage(player)
		if stage == "FirstNight" then
			fire(player, { type = "bed", on = inside[player] == true })
		elseif stage == "CommuteToWork" then
			fire(player, { type = "exit", on = inside[player] == true })
		end
	end)
	log("ready")
end

-- Studio helpers (server Command Bar): _G.MTL.Property.debug(player) gives the flat and walks you in;
-- _G.MTL.Property.leave(player) / _G.MTL.Property.payPower(player).
function PropertyService.debug(player: Player)
	assert(RunService:IsStudio(), "Studio-only")
	PropertyService.give(player, Property.StarterHome)
	task.spawn(PropertyService.enter, player)
end

return PropertyService
]======])
put("ServerScriptService/MTL/Services", "RateLimiter", "ModuleScript", [======[--!strict
-- Per-player token bucket for client->server remotes. RateLimiter.new(perSecond, burst):allow(player) -> bool
local Players = game:GetService("Players")

local RateLimiter = {}
RateLimiter.__index = RateLimiter

local all = {}

function RateLimiter.new(perSecond: number, burst: number?)
	local self = setmetatable({ rate = perSecond, burst = burst or perSecond, buckets = {} }, RateLimiter)
	table.insert(all, self)
	return self
end

function RateLimiter:allow(player: Player): boolean
	local now = os.clock()
	local b = self.buckets[player]
	if not b then
		b = { tokens = self.burst, t = now }
		self.buckets[player] = b
	end
	b.tokens = math.min(self.burst, b.tokens + (now - b.t) * self.rate)
	b.t = now
	if b.tokens >= 1 then
		b.tokens -= 1
		return true
	end
	return false
end

Players.PlayerRemoving:Connect(function(player)
	for _, limiter in all do
		limiter.buckets[player] = nil
	end
end)

return RateLimiter
]======])
put("ServerScriptService/MTL/Services", "StoryCrew", "ModuleScript", [======[--!strict
-- Story Piece 3 glue: stages 4-7 (Master Plan §1). TheCall itself lives in PhoneStory (the Phone piece).
--   GangMeet     accepting the call made you Criminal; a meet spot is picked (saved), the unknown number texts it,
--                the Story waypoint + breadcrumbs lead there; the crew waits by a car with hazards (client props).
--   GangIntro    you're placed facing the crew, the GangIntro cutscene plays (skippable), the crew joins Contacts.
--   FirstMission MissionService runs "FirstMission" (rob Liberty Food Mart). On completion: pay once (saved
--                before anything else, so a disconnect can't lose or double it), RobberyOutro cutscene, drop-off.
--   MissionDone  payout screen, then the 2x Money offer (dismissable, no timers). Closing it -> FindAPlace.
-- Piece 4 hooks: StoryService.onEnter("FindAPlace"...) etc.; the drop-off is next to Locations.EndsFlat;
-- Story.Data.FirstMissionResult holds what the job paid; CutsceneService.play works for the power-out scene.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")
local Players = game:GetService("Players")

local Missions = require(ReplicatedStorage.MTL.Config.Missions)
local Locations = require(ReplicatedStorage.MTL.Config.Locations)
local Monetization = require(ReplicatedStorage.MTL.Config.Monetization)
local MissionRules = require(ReplicatedStorage.MTL.Rules.MissionRules)
local Net = require(ReplicatedStorage.MTL.Net)
local DataService = require(script.Parent.DataService)
local EconomyService = require(script.Parent.EconomyService)
local MonetizationService = require(script.Parent.MonetizationService)
local StoryService = require(script.Parent.StoryService)
local PhoneService = require(script.Parent.PhoneService)
local WaypointService = require(script.Parent.WaypointService)
local Notify = require(script.Parent.Notify)
local CutsceneService = require(script.Parent.CutsceneService)
local MissionService = require(script.Parent.MissionService)

local StoryCrew = {}

local MISSION = "FirstMission"

local function log(...)
	print("[MTL StoryCrew]", ...)
end

local function sdata(player: Player): any?
	return StoryService.data(player)
end

local function root(player: Player): BasePart?
	local c = player.Character
	return c and c:FindFirstChild("HumanoidRootPart") :: BasePart?
end

local function floorAt(pos: Vector3): number
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	local ex: { Instance } = {}
	for _, p in Players:GetPlayers() do
		if p.Character then
			table.insert(ex, p.Character)
		end
	end
	params.FilterDescendantsInstances = ex
	local hit = workspace:Raycast(pos + Vector3.new(0, 6, 0), Vector3.new(0, -40, 0), params)
	return if hit then hit.Position.Y else pos.Y - 1
end

---------------------------------------------------------------- the meet spot

type Spot = { id: string, label: string, cf: CFrame }

-- A map part tagged MTL_MeetSpot with attribute Id = "<spot id>" wins over the placeholder position (its
-- LookVector = from the crew toward where the player stands). Otherwise the crew faces the Food Mart, the way the
-- player comes from.
local function resolveSpot(cfg: any): Spot
	for _, part in CollectionService:GetTagged("MTL_MeetSpot") do
		if part:IsA("BasePart") and part:GetAttribute("Id") == cfg.Id then
			local p = part.Position
			return { id = cfg.Id, label = cfg.Label, cf = CFrame.new(p.X, floorAt(p), p.Z) * part.CFrame.Rotation }
		end
	end
	local p = cfg.Position
	local y = floorAt(p)
	local toward = Locations.FoodMart.Door
	local from = Vector3.new(p.X, y, p.Z)
	local look = Vector3.new(toward.X, y, toward.Z)
	local cf = if (look - from).Magnitude > 1 then CFrame.lookAt(from, look) else CFrame.new(from)
	if type(cfg.Yaw) == "number" then
		cf = CFrame.new(from) * CFrame.Angles(0, math.rad(cfg.Yaw), 0)
	end
	return { id = cfg.Id, label = cfg.Label, cf = cf }
end

local function meetSpot(player: Player): Spot?
	local sd = sdata(player)
	if not sd then
		return nil
	end
	local cfg = MissionRules.findSpot(Locations.MeetSpots, sd.MeetSpot)
	if not cfg then
		cfg = MissionRules.pickSpot(Locations.MeetSpots, Random.new():NextNumber())
		if not cfg then
			return nil
		end
		sd.MeetSpot = cfg.Id
		DataService.push(player)
		log(player.Name, "meet spot:", cfg.Id)
	end
	return resolveSpot(cfg)
end

local function sendMeet(player: Player)
	local spot = meetSpot(player)
	if spot then
		MissionService.send(player, { type = "meet", cframe = spot.cf, label = spot.label })
	end
end

local function standAt(player: Player, spot: Spot)
	local r = root(player)
	if not r then
		return
	end
	local stand = spot.cf:PointToWorldSpace(Missions.Meet.Layout.Player.at)
	local pos = stand + Vector3.new(0, 3, 0)
	local crew = Vector3.new(spot.cf.Position.X, pos.Y, spot.cf.Position.Z)
	r.CFrame = CFrame.lookAt(pos, crew)
	r.AssemblyLinearVelocity = Vector3.zero
end

---------------------------------------------------------------- mission end

local function dropOff(): CFrame
	local door = Locations.EndsFlat.Door
	local p = door + Missions.DropOffOffset
	local y = floorAt(p)
	return CFrame.lookAt(Vector3.new(p.X, y + 3, p.Z), Vector3.new(door.X, y + 3, door.Z))
end

-- Pays once. The result is saved in Story.Data before the outro, so rejoining never re-pays or loses it.
local function payOnce(player: Player, result: any): any?
	local sd = sdata(player)
	local data = DataService.get(player)
	if not sd or not data then
		return nil
	end
	if sd.FirstMissionResult then
		return sd.FirstMissionResult
	end
	local def = Missions.FirstMission
	local mult = EconomyService.cashMultiplier(player)
	local base = (result.take or def.Pay) + (result.bonus or 0)
	local paid = EconomyService.addCash(player, base, "Mission:FirstMission", true)
	local xp = EconomyService.addXP(player, def.XP, "Mission:FirstMission")
	data.Stats.Robberies += 1
	sd.FirstMissionResult = {
		take = result.take or def.Pay,
		bonus = result.bonus or 0,
		clean = result.clean == true,
		escape = result.escapeSeconds,
		seconds = result.seconds,
		paid = paid,
		xp = xp,
		mult = mult,
		at = os.time(),
	}
	DataService.push(player)
	log(player.Name, "paid", paid, "for", MISSION)
	return sd.FirstMissionResult
end

local function outroAndAdvance(player: Player)
	local car = MissionService.point(MISSION, "Car")
	CutsceneService.play(player, "RobberyOutro", { anchor = car })
	if not player.Parent then
		return
	end
	MissionService.cleanup(player)
	local r = root(player)
	if r then
		r.CFrame = dropOff()
		r.AssemblyLinearVelocity = Vector3.zero
	end
	StoryService.advance(player, MISSION)
end

---------------------------------------------------------------- payout + offer

local function offerItems(player: Player): { any }
	local out = {}
	for _, it in Missions.Offer.Items do
		local id = if it.kind == "pass" then Monetization.Passes[it.item] else Monetization.Products[it.item]
		table.insert(out, {
			item = it.item,
			kind = it.kind,
			title = it.title,
			sub = it.sub,
			id = id or 0,
			owned = it.kind == "pass" and MonetizationService.owns(player, it.item),
		})
	end
	return out
end

local function sendPayout(player: Player)
	local sd = sdata(player)
	local def = Missions.FirstMission
	local res = sd and sd.FirstMissionResult
	if not res then
		-- reached by debugSet without playing the mission: show the numbers, pay nothing
		res = { take = def.Pay, bonus = 0, clean = false, paid = 0, xp = 0, mult = 1, debug = true }
	end
	MissionService.send(player, {
		type = "payout",
		title = def.Title,
		take = res.take,
		bonus = res.bonus,
		clean = res.clean,
		escape = res.escape,
		cleanSeconds = def.CleanGetaway.Seconds,
		paid = res.paid,
		xp = res.xp,
		mult = res.mult,
		doubled = (res.take + res.bonus) * 2,
		debug = res.debug == true,
		offer = offerItems(player),
	})
end

---------------------------------------------------------------- init

function StoryCrew.init()
	-- 4. GangMeet
	StoryService.onEnter("GangMeet", function(player, resumed)
		local data = DataService.get(player)
		if not data then
			return
		end
		if data.Path ~= "Criminal" then
			PhoneService.setPath(player, "Criminal", true) -- you said "I'm in" (Master Plan §1 branching)
		end
		local jm = script.Parent:FindFirstChild("JobService")
		if jm then
			local ok, js = pcall(require, jm)
			if ok and js.isOnShift and js.isOnShift(player) then
				js.clockOut(player, "story")
				Notify.toast(player, "You clocked out early.")
			end
		end
		local spot = meetSpot(player)
		if not spot then
			warn("[MTL StoryCrew] no meet spots configured; skipping the meet")
			StoryService.advance(player, "GangMeet")
			return
		end
		WaypointService.set(player, "Story", spot.cf.Position, { label = spot.label, radius = Missions.Meet.Radius })
		Notify.objective(player, "Go to the meet: " .. spot.label)
		sendMeet(player)
		local sd = sdata(player)
		if sd and not sd.MeetTexted then
			sd.MeetTexted = true
			task.wait(1.5)
			for i, line in Missions.Meet.Texts do
				PhoneService.text(player, "Unknown", string.format(line, spot.label))
				if i < #Missions.Meet.Texts then
					task.wait(1.4)
				end
			end
		end
	end)
	WaypointService.Arrived:Connect(function(player, id)
		if id == "Story" and StoryService.stage(player) == "GangMeet" then
			StoryService.advance(player, "GangMeet")
		end
	end)

	-- 5. GangIntro
	StoryService.onEnter("GangIntro", function(player)
		local spot = meetSpot(player)
		MissionService.send(player, { type = "meetClear" })
		if spot then
			standAt(player, spot)
			CutsceneService.play(player, "GangIntro", { anchor = spot.cf })
		end
		if not player.Parent then
			return
		end
		local data = DataService.get(player)
		if data then
			for _, id in { "Dre", "Smoke", "Nina" } do
				data.Phone.Contacts[id] = true
			end
			DataService.push(player)
		end
		StoryService.advance(player, "GangIntro")
	end)

	-- 6. FirstMission
	StoryService.onEnter(MISSION, function(player)
		local sd = sdata(player)
		if sd and sd.FirstMissionResult then
			-- the job was done and paid, the player left during the outro: just finish the beat
			outroAndAdvance(player)
			return
		end
		MissionService.start(player, MISSION)
	end)
	MissionService.Completed:Connect(function(player, missionId, result)
		if missionId ~= MISSION or StoryService.stage(player) ~= MISSION then
			return
		end
		payOnce(player, result)
		outroAndAdvance(player)
	end)

	-- 7. MissionDone: payout, then the offer; closing the offer moves on to free play (FindAPlace)
	StoryService.onEnter("MissionDone", function(player)
		Notify.objective(player, "")
		task.wait(0.3)
		sendPayout(player)
	end)
	MissionService.onAction("closeOffer", function(player)
		if StoryService.stage(player) == "MissionDone" then
			StoryService.advance(player, "MissionDone")
		end
	end)
	MissionService.onAction("buy", function(player, payload)
		local item = payload.item
		for _, it in Missions.Offer.Items do
			if it.item == item then
				MonetizationService.prompt(player, item)
				return
			end
		end
	end)
	-- a pass bought on the offer card: refresh the card (shows OWNED)
	MonetizationService.PassChanged:Connect(function(player)
		if StoryService.stage(player) == "MissionDone" then
			sendPayout(player)
		end
	end)

	-- respawned / rejoined clients re-get what they need
	Net.get("ClientReady").OnServerEvent:Connect(function(player)
		local stage = StoryService.stage(player)
		if stage == "GangMeet" then
			sendMeet(player)
		end
	end)
	log("ready")
end

-- Studio test helpers (server Command Bar): _G.MTL.StoryCrew.meet(player) teleports you to your meet spot.
function StoryCrew.meet(player: Player)
	assert(game:GetService("RunService"):IsStudio(), "Studio-only")
	local spot = meetSpot(player)
	if spot then
		standAt(player, spot)
	end
end

return StoryCrew
]======])
put("ServerScriptService/MTL/Services", "StoryService", "ModuleScript", [======[--!strict
-- The story stage machine (Master Plan §1). Stages only move forward, only here.
-- Systems register what happens when a player ENTERS a stage with onEnter(stage, fn(player, resumed)).
-- `resumed` is true when the player rejoined mid-stage: re-send waypoints/texts, don't re-grant rewards.
--
-- Piece 0 wires the first two stages as the working example:
--   Arrive     -> objective + waypoint to the Food Mart door; arriving advances to FirstShift
--   FirstShift -> reaching Config.Levels.CriminalCallLevel advances to TheCall (the Phone/Story pieces handle the call)
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Story = require(ReplicatedStorage.MTL.Config.Story)
local Levels = require(ReplicatedStorage.MTL.Config.Levels)
local Locations = require(ReplicatedStorage.MTL.Config.Locations)
local StoryRules = require(ReplicatedStorage.MTL.Rules.StoryRules)
local Signal = require(ReplicatedStorage.MTL.Signal)
local DataService = require(script.Parent.DataService)
local EconomyService = require(script.Parent.EconomyService)
local WaypointService = require(script.Parent.WaypointService)
local Notify = require(script.Parent.Notify)
local Analytics = require(script.Parent.Analytics)

local StoryService = {}
StoryService.StageChanged = Signal.new() -- (player, newStage, oldStage)

local enterHooks: { [string]: { (Player, boolean) -> () } } = {}

local function log(...)
	print("[MTL Story]", ...)
end

function StoryService.stage(player: Player): string?
	local data = DataService.get(player)
	return if data then data.Story.Stage else nil
end

function StoryService.reached(player: Player, target: string): boolean
	local s = StoryService.stage(player)
	return s ~= nil and StoryRules.reached(s, target)
end

-- Per-stage scratch data saved with the profile (e.g. which meet spot was picked).
function StoryService.data(player: Player): { [string]: any }?
	local data = DataService.get(player)
	return if data then data.Story.Data else nil
end

function StoryService.onEnter(stage: string, fn: (Player, boolean) -> ())
	assert(StoryRules.isValid(stage), "[MTL Story] unknown stage " .. stage)
	enterHooks[stage] = enterHooks[stage] or {}
	table.insert(enterHooks[stage], fn)
end

local function runEnter(player: Player, stage: string, resumed: boolean)
	player:SetAttribute("MTL_Stage", stage)
	local objective = Story.Objectives[stage]
	if objective and objective ~= "" then
		Notify.objective(player, objective)
	end
	for _, fn in enterHooks[stage] or {} do
		task.spawn(function()
			local ok, err = pcall(fn, player, resumed)
			if not ok then
				warn("[MTL Story] onEnter", stage, "failed:", err)
			end
		end)
	end
end

-- Moves the player from `fromStage` to the next stage. Does nothing if they aren't at `fromStage`
-- (so double calls and late events are harmless). Returns true if it moved.
function StoryService.advance(player: Player, fromStage: string): boolean
	local data = DataService.get(player)
	if not data or data.Story.Stage ~= fromStage then
		return false
	end
	local nextStage = StoryRules.nextOf(fromStage)
	if not nextStage then
		return false
	end
	data.Story.Done[fromStage] = os.time()
	data.Story.Stage = nextStage
	log(player.Name, fromStage, "->", nextStage)
	Analytics.onboarding(player, StoryRules.index(nextStage) :: number, nextStage)
	DataService.push(player)
	StoryService.StageChanged:Fire(player, nextStage, fromStage)
	runEnter(player, nextStage, false)
	return true
end

-- Studio/debug only: jump a player to any stage (used by threads to test their piece without replaying the story).
function StoryService.debugSet(player: Player, stage: string)
	assert(game:GetService("RunService"):IsStudio(), "[MTL Story] debugSet is Studio-only")
	local data = DataService.get(player)
	if data and StoryRules.isValid(stage) then
		data.Story.Stage = stage
		DataService.push(player)
		runEnter(player, stage, false)
	end
end

function StoryService.init()
	DataService.Ready:Connect(function(player, data)
		local stage = data.Story.Stage
		local isNew = stage == StoryRules.first() and data.Stats.Joins <= 1
		if isNew then
			Analytics.onboarding(player, 1, stage)
		end
		-- wait for the character so waypoints/cutscenes have someone to point at
		if not player.Character then
			player.CharacterAdded:Wait()
		end
		task.wait(1)
		runEnter(player, stage, not isNew)
	end)

	-- Stage 1: Arrive -> walk to the Food Mart
	StoryService.onEnter("Arrive", function(player)
		WaypointService.set(player, "Story", Locations.FoodMart.Door, {
			label = "Liberty Food Mart",
			radius = Locations.FoodMart.Radius,
		})
	end)
	WaypointService.Arrived:Connect(function(player, id)
		if id == "Story" and StoryService.stage(player) == "Arrive" then
			StoryService.advance(player, "Arrive")
		end
	end)

	-- Stage 2: FirstShift -> the Jobs piece runs the shift; reaching the call level moves the story on
	EconomyService.LevelUp:Connect(function(player, level)
		if level >= Levels.CriminalCallLevel then
			StoryService.advance(player, "FirstShift")
		end
	end)
	StoryService.onEnter("FirstShift", function(player)
		local data = DataService.get(player)
		if data and data.Level >= Levels.CriminalCallLevel then
			StoryService.advance(player, "FirstShift") -- already high enough (e.g. levelled during a resume)
		end
	end)
end

return StoryService
]======])
put("ServerScriptService/MTL/Services", "StoryWelcome", "ModuleScript", [======[--!strict
-- The welcome scenes that bring a NEW player into the story (Research: Cinematic Cutscenes):
--   Arrive     (first join only) -> cutscene "Welcome": the city, you, Mr. Patel's text, hand-off at the spawn
--   FirstShift (first time only) -> cutscene "FirstDay": Mr. Patel meets you inside Liberty Food Mart
-- Both are skippable; skipping changes nothing else (the waypoint, texts and shift run as before, the tutorial
-- coach waits until the scene is over). Returning players (resumed) never see them again.
-- Studio: set workspace attribute MTL_SkipWelcome = true to skip both while testing other pieces.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local Locations = require(ReplicatedStorage.MTL.Config.Locations)
local StoryService = require(script.Parent.StoryService)
local CutsceneService = require(script.Parent.CutsceneService)

local StoryWelcome = {}

local function skipped(): boolean
	return RunService:IsStudio() and workspace:GetAttribute("MTL_SkipWelcome") == true
end

-- The store scene's anchor: standing inside the door, looking into the store (local -Z = into the store).
function StoryWelcome.storeAnchor(): CFrame
	local door, inside = Locations.FoodMart.Door, Locations.FoodMart.Inside
	return CFrame.lookAt(door, Vector3.new(inside.X, door.Y, inside.Z))
end

function StoryWelcome.init()
	StoryService.onEnter("Arrive", function(player, resumed)
		if resumed or skipped() then
			return
		end
		CutsceneService.play(player, "Welcome", { anchor = CFrame.new(Locations.Spawn) })
	end)
	StoryService.onEnter("FirstShift", function(player, resumed)
		if resumed or skipped() then
			return
		end
		CutsceneService.play(player, "FirstDay", { anchor = StoryWelcome.storeAnchor() })
	end)
end

return StoryWelcome
]======])
put("ServerScriptService/MTL/Services", "TimeService", "ModuleScript", [======[--!strict
-- The world clock (Master Plan §4 "Lighting and time of day"). The server owns the time; every client draws the
-- lighting itself from two Workspace attributes, so the sun moves every frame with no network traffic:
--   MTL_DayEpoch  (number)  server time (workspace:GetServerTimeNow()) when the cycle was at position 0 (Morning)
--   MTL_DayFrozen (number?) a clock hour to hold the whole server at (debug / events); nil = running
-- The server never writes Lighting (it would replicate and fight the clients' smooth values).
--   TimeService.clock() -> hour 0-24        TimeService.phase() -> "Morning" | "Day" | "Evening" | "Night"
--   TimeService.setClock(hour)              jump the world to that time (keeps running)
--   TimeService.freeze(hour?)               hold the world at that hour (nil = run again from there)
--   TimeService.PhaseChanged: Signal(phase)
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Signal = require(ReplicatedStorage.MTL.Signal)
local DayNight = require(ReplicatedStorage.MTL.Config.DayNight)
local DayNightRules = require(ReplicatedStorage.MTL.Rules.DayNightRules)

local TimeService = {}
TimeService.PhaseChanged = Signal.new() -- (phase)

local function log(...)
	print("[MTL Time]", ...)
end

local function now(): number
	return workspace:GetServerTimeNow()
end

function TimeService.clock(): number
	local frozen = workspace:GetAttribute("MTL_DayFrozen")
	if type(frozen) == "number" then
		return frozen
	end
	local epoch = workspace:GetAttribute("MTL_DayEpoch")
	if type(epoch) ~= "number" then
		return DayNight.StartClock
	end
	return DayNightRules.clockAt(now() - epoch)
end

function TimeService.phase(): string
	return DayNightRules.phaseOf(TimeService.clock())
end

function TimeService.setClock(hour: number)
	assert(type(hour) == "number", "[MTL Time] setClock(hour)")
	workspace:SetAttribute("MTL_DayEpoch", now() - DayNightRules.positionFor(hour))
	if workspace:GetAttribute("MTL_DayFrozen") ~= nil then
		workspace:SetAttribute("MTL_DayFrozen", hour % 24)
	end
	log("clock set to", string.format("%.2f", hour % 24), TimeService.phase())
end

function TimeService.freeze(hour: number?)
	if hour == nil then
		-- run again from the held time, no jump
		local held = TimeService.clock()
		workspace:SetAttribute("MTL_DayFrozen", nil)
		TimeService.setClock(held)
		return
	end
	workspace:SetAttribute("MTL_DayFrozen", hour % 24)
	TimeService.setClock(hour)
end

function TimeService.init()
	workspace:SetAttribute("MTL_DayFrozen", nil)
	TimeService.setClock(DayNight.StartClock)
	local last = TimeService.phase()
	task.spawn(function()
		while true do
			task.wait(1)
			local p = TimeService.phase()
			if p ~= last then
				last = p
				log("phase", p)
				TimeService.PhaseChanged:Fire(p)
			end
		end
	end)
end

return TimeService
]======])
put("ServerScriptService/MTL/Services", "WaypointService", "ModuleScript", [======[--!strict
-- Server-owned waypoints. set() shows a marker + ground breadcrumbs on the player's screen (WayfindingController)
-- and the SERVER checks arrival (distance from the character), then fires Arrived. Clients can't fake arriving.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Net = require(ReplicatedStorage.MTL.Net)
local Signal = require(ReplicatedStorage.MTL.Signal)

local WaypointService = {}
WaypointService.Arrived = Signal.new() -- (player, id)

type Waypoint = { id: string, position: Vector3, label: string, radius: number, breadcrumbs: boolean }
local active: { [Player]: { [string]: Waypoint } } = {}

-- opts: { label = "Liberty Food Mart", radius = 12, breadcrumbs = true }
function WaypointService.set(player: Player, id: string, position: Vector3, opts: { [string]: any }?)
	local o = opts or {}
	local wp: Waypoint = {
		id = id,
		position = position,
		label = o.label or "",
		radius = o.radius or 12,
		breadcrumbs = if o.breadcrumbs == nil then true else o.breadcrumbs,
	}
	active[player] = active[player] or {}
	active[player][id] = wp
	Net.get("Waypoint"):FireClient(player, wp)
end

function WaypointService.clear(player: Player, id: string)
	local list = active[player]
	if list and list[id] then
		list[id] = nil
		Net.get("Waypoint"):FireClient(player, { id = id, clear = true })
	end
end

function WaypointService.has(player: Player, id: string): boolean
	return active[player] ~= nil and active[player][id] ~= nil
end

-- Re-sends every active waypoint (after a respawn the client rebuilds its markers).
function WaypointService.resend(player: Player)
	for _, wp in active[player] or {} do
		Net.get("Waypoint"):FireClient(player, wp)
	end
end

function WaypointService.init()
	Players.PlayerRemoving:Connect(function(p)
		active[p] = nil
	end)
	Net.get("ClientReady").OnServerEvent:Connect(function(p)
		WaypointService.resend(p) -- covers first join and every respawn (the client re-sends ClientReady)
	end)

	task.spawn(function()
		while true do
			task.wait(0.25)
			for player, list in active do
				local char = player.Character
				local root = char and char:FindFirstChild("HumanoidRootPart") :: BasePart?
				if root then
					for id, wp in list do
						-- flat distance + generous height, so stairs/kerbs never block arrival
						local d = root.Position - wp.position
						if Vector2.new(d.X, d.Z).Magnitude <= wp.radius and math.abs(d.Y) <= 20 then
							list[id] = nil
							Net.get("Waypoint"):FireClient(player, { id = id, clear = true, arrived = true })
							WaypointService.Arrived:Fire(player, id)
						end
					end
				end
			end
		end
	end)
end

return WaypointService
]======])
put("ServerScriptService/MTL/Vendor", "ProfileStore", "ModuleScript", [======[--[[
MAD STUDIO (by loleris)

-[ProfileStore]---------------------------------------

	Periodic DataStore saving solution with session locking
	
	WARNINGS FOR "Profile.Data" VALUES:
	 	! Do not create numeric tables with gaps - attempting to store such tables will result in an error.
		! Do not create mixed tables (some values indexed by number and others by a string key)
			- only numerically indexed  data will be stored.
		! Do not index tables by anything other than numbers and strings.
		! Do not reference Roblox Instances
		! Do not reference userdata (Vector3, Color3, CFrame...) - Serialize userdata before referencing
		! Do not reference functions
		
	Members:
	
		ProfileStore.IsClosing          [bool]
			-- Set to true after a game:BindToClose() trigger
			
		ProfileStore.IsCriticalState    [bool]
			-- Set to true when ProfileStore experiences too many consecutive errors
		
		ProfileStore.OnError            [Signal] (message, store_name, profile_key)
			-- Most ProfileStore errors will be caught and passed to this signal
			
		ProfileStore.OnOverwrite        [Signal] (store_name, profile_key)
			-- Triggered when a DataStore key was likely used to store data that wasn't
			a ProfileStore profile or the ProfileStore structure was invalidly manually
			altered for that DataStore key
			
		ProfileStore.OnCriticalToggle   [Signal] (is_critical)
			-- Triggered when ProfileStore experiences too many consecutive errors
		
		ProfileStore.DataStoreState     [string] ("NotReady", "NoInternet", "NoAccess", "Access")
			-- This value resembles ProfileStore's access to the DataStore; The value starts
			as "NotReady" and will eventually change to one of the other 3 possible values.
	
	Functions:
	
		ProfileStore.New(store_name, template?) --> [ProfileStore]
			store_name   [string] -- DataStore name
			template     [table] or nil -- Profiles will default to given table (hard-copy) when no data was saved previously
			
		ProfileStore.SetConstant(name, value)
			name    [string]
			value   [number]
				
	Members [ProfileStore]:
	
		ProfileStore.Mock   [ProfileStore]
			-- Reflection of ProfileStore methods, but the methods will now query a mock
			DataStore with no relation to the real DataStore
			
		ProfileStore.Name   [string]
		
	Methods [ProfileStore]:
	
		ProfileStore:StartSessionAsync(profile_key, params?) --> [Profile] or nil
			profile_key [string] -- DataStore key
			params      nil or [table]: -- Custom params; E.g. {Steal = true}
				{
					Steal = true, -- Pass this to disregard an existing session lock
					Cancel = fn() -> (boolean), -- Pass this to create a request cancel condition.
						-- If the cancel function returns true, ProfileStore will stop trying to
						-- start the session and return nil
				}
			
		ProfileStore:MessageAsync(profile_key, message) --> is_success [bool]
			profile_key [string] -- DataStore key
			message     [table] -- Data to be messaged to the profile
			
		ProfileStore:GetAsync(profile_key, version?) --> [Profile] or nil
			-- Reads a profile without starting a session - will not autosave
			profile_key   [string] -- DataStore key
			version       nil or [string] -- DataStore key version

		ProfileStore:VersionQuery(profile_key, sort_direction?, min_date?, max_date?) --> [VersionQuery]
			profile_key      [string]
			sort_direction   nil or [Enum.SortDirection]
			min_date         nil or [DateTime]
			max_date         nil or [DateTime]
			
		ProfileStore:RemoveAsync(profile_key) --> is_success [bool]
			-- Completely removes profile data from the DataStore / mock DataStore with no way to recover it.

	Methods [VersionQuery]:

		VersionQuery:NextAsync() --> [Profile] or nil -- (Yields)
			-- Returned profile is similar to profiles returned by ProfileStore:GetAsync()
		
	Members [Profile]:
	
		Profile.Data               [table]
			-- When the profile is active changes to this table are guaranteed to be saved
		Profile.LastSavedData      [table] (Read-only)
			-- Last snapshot of "Profile.Data" that has been successfully saved to the DataStore;
			Useful for proper developer product purchase receipt handling
		
		Profile.FirstSessionTime   [number] (Read-only)
			-- os.time() timestamp of the first profile session
			
		Profile.SessionLoadCount   [number] (Read-only) -- Amount of times a session was started for this profile
			
		Profile.Session            [table] (Read-only) {PlaceId = number, JobId = string} / nil
			-- Set to a table if this profile is in use by a server; nil if released

		Profile.RobloxMetaData     [table] -- Writable table that gets saved automatically and once the profile is released
		Profile.UserIds            [table] -- (Read-only) -- {user_id [number], ...} -- User ids associated with this profile

		Profile.KeyInfo            [DataStoreKeyInfo] -- Changes before OnAfterSave signal
		
		Profile.OnSave             [Signal] ()
			-- Triggered right before changes to Profile.Data are saved to the DataStore
			
		Profile.OnLastSave         [Signal] (reason [string]: "Manual", "External", "Shutdown")
			-- Triggered right before changes to Profile.Data are saved to the DataStore
			for the last time; A reason is provided for the last save:
				- "Manual"   - Profile:EndSession() was called
				- "Shutdown" - The server that has ownership of this profile is shutting down
				- "External" - Another server has started a session for this profile
			Note that this event will not trigger for when a profile session is ended by
			another server trying to take ownership of the session - this is impossible to
			do without compromising on ProfileStore's speed.
			
		Profile.OnSessionEnd       [Signal] ()
			-- Triggered when the profile session is terminated on this server
		
		Profile.OnAfterSave        [Signal] (last_saved_data)
			-- Triggered after a successful save
			last_saved_data [table] -- Profile.LastSavedData
			
		Profile.ProfileStore       [ProfileStore] -- ProfileStore object this profile belongs to
		Profile.Key                [string] -- DataStore key
		
	Methods [Profile]:
	
		Profile:IsActive() --> [bool] -- If "true" is returned, changes to Profile.Data are guaranteed to save;
			This guarantee is only valid until code yields (e.g. task.wait() is used).
			
		Profile:Reconcile() -- Fills in missing (nil) [string_key] = [value] pairs to the Profile.Data structure
			from the "template" argument that was passed to "ProfileStore.New()"
			
		Profile:EndSession() -- Call after the server has finished working with this profile
			e.g., after the player leaves (Profile object will become inactive)

		Profile:AddUserId(user_id) -- Associates user_id with profile (GDPR compliance)
			user_id   [number]

		Profile:RemoveUserId(user_id) -- Removes user_id association with profile (safe function)
			user_id   [number]
			
		Profile:MessageHandler(fn) -- Sets a message handler for this profile
			fn [function] (message [table], processed [function]())
			-- The handler function receives a message table and a callback function;
			The callback function is to be called when a message has been processed
			- this will discard the message from the profile message cache; If the
			callback function is not called, other message handlers will also be triggered
			with unprocessed message data.
			
		Profile:Save() -- If the profile session is still active makes an UpdateAsync call
			to the DataStore to immediately save profile data

		Profile:SetAsync() -- Forcefully saves changes to the profile; Only for profiles
			loaded with ProfileStore:GetAsync() or ProfileStore:VersionQuery()
		
--]]

local AUTO_SAVE_PERIOD = 300 -- (Seconds) Time between when changes to a profile are saved to the DataStore
local LOAD_REPEAT_PERIOD = 10 -- (Seconds) Time between successive profile reads when handling a session conflict
local FIRST_LOAD_REPEAT = 5 -- (Seconds) Time between first and second profile read when handling a session conflict
local SESSION_STEAL = 40 -- (Seconds) Time until a session conflict is resolved with the waiting server stealing the session
local ASSUME_DEAD = 630 -- (Seconds) If a profile hasn't had updates for this long, quickly assume an active session belongs to a crashed server
local START_SESSION_TIMEOUT = 120 -- (Seconds) If a session can't be started for a profile for this long, stop repeating calls to the DataStore

local CRITICAL_STATE_ERROR_COUNT = 5 -- Assume critical state if this many issues happen in a short amount of time
local CRITICAL_STATE_ERROR_EXPIRE = 120 -- (Seconds) Individual issue expiration
local CRITICAL_STATE_EXPIRE = 120 -- (Seconds) Critical state expiration

local MAX_MESSAGE_QUEUE = 1000 -- Max messages saved in a profile that were sent using "ProfileStore:MessageAsync()"

----- Dependencies -----

-- local Util = require(game.ReplicatedStorage.Shared.Util)
-- local Signal = Util.Signal

local Signal do

	local FreeRunnerThread

	--[[
		Yield-safe coroutine reusing by stravant;
		Sources:
		https://devforum.roblox.com/t/lua-signal-class-comparison-optimal-goodsignal-class/1387063
		https://gist.github.com/stravant/b75a322e0919d60dde8a0316d1f09d2f
	--]]

	local function AcquireRunnerThreadAndCallEventHandler(fn, ...)
		local acquired_runner_thread = FreeRunnerThread
		FreeRunnerThread = nil
		fn(...)
		-- The handler finished running, this runner thread is free again.
		FreeRunnerThread = acquired_runner_thread
	end

	local function RunEventHandlerInFreeThread(...)
		AcquireRunnerThreadAndCallEventHandler(...)
		while true do
			AcquireRunnerThreadAndCallEventHandler(coroutine.yield())
		end
	end

	local Connection = {}
	Connection.__index = Connection

	local SignalClass = {}
	SignalClass.__index = SignalClass

	function Connection:Disconnect()

		if self.is_connected == false then
			return
		end

		local signal = self.signal
		self.is_connected = false
		signal.listener_count -= 1

		if signal.head == self then
			signal.head = self.next
		else
			local prev = signal.head
			while prev ~= nil and prev.next ~= self do
				prev = prev.next
			end
			if prev ~= nil then
				prev.next = self.next
			end
		end

	end

	function SignalClass.New()

		local self = {
			head = nil,
			listener_count = 0,
		}
		setmetatable(self, SignalClass)

		return self

	end

	function SignalClass:Connect(listener: (...any) -> ())

		if type(listener) ~= "function" then
			error(`[{script.Name}]: \"listener\" must be a function; Received {typeof(listener)}`)
		end

		local connection = {
			listener = listener,
			signal = self,
			next = self.head,
			is_connected = true,
		}
		setmetatable(connection, Connection)

		self.head = connection
		self.listener_count += 1

		return connection

	end

	function SignalClass:GetListenerCount(): number
		return self.listener_count
	end

	function SignalClass:Fire(...)
		local item = self.head
		while item ~= nil do
			if item.is_connected == true then
				if not FreeRunnerThread then
					FreeRunnerThread = coroutine.create(RunEventHandlerInFreeThread)
				end
				task.spawn(FreeRunnerThread, item.listener, ...)
			end
			item = item.next
		end
	end

	function SignalClass:Wait()
		local co = coroutine.running()
		local connection
		connection = self:Connect(function(...)
			connection:Disconnect()
			task.spawn(co, ...)
		end)
		return coroutine.yield()
	end

	Signal = table.freeze({
		New = SignalClass.New,
	})

end

----- Private -----

local ActiveSessionCheck = {} -- {[session_token] = profile, ...}
local AutoSaveList = {} -- {profile, ...} -- Loaded profile table which will be circularly auto-saved
local IssueQueue = {} -- {issue_time, ...}

local DataStoreService = game:GetService("DataStoreService")
local MessagingService = game:GetService("MessagingService")
local HttpService = game:GetService("HttpService")
local RunService = game:GetService("RunService")

local PlaceId = game.PlaceId
local JobId = game.JobId

local AutoSaveIndex = 1 -- Next profile to auto save
local LastAutoSave = os.clock()

local LoadIndex = 0

local ActiveProfileLoadJobs = 0 -- Number of active threads that are loading in profiles
local ActiveProfileSaveJobs = 0 -- Number of active threads that are saving profiles

local CriticalStateStart = 0 -- os.clock()

local IsStudio = RunService:IsStudio()
local DataStoreState: "NotReady" | "NoInternet" | "NoAccess" | "Access" = "NotReady"

local MockStore = {}
local UserMockStore = {}
local MockFlag = false

local OnError = Signal.New() -- (message, store_name, profile_key)
local OnOverwrite = Signal.New() -- (store_name, profile_key)

local UpdateQueue = { -- For stability sake, we won't do UpdateAsync calls for the same key until all previous calls finish
	--[[
		[session_token] = {
			coroutine, ...
		},
		...
	--]]
}

local function WaitInUpdateQueue(session_token) --> next_in_queue()

	local is_first = false

	if UpdateQueue[session_token] == nil then
		is_first = true
		UpdateQueue[session_token] = {}
	end

	local queue = UpdateQueue[session_token]

	if is_first == false then
		table.insert(queue, coroutine.running())
		coroutine.yield()
	end

	return function()
		local next_co = table.remove(queue, 1)
		if next_co ~= nil then
			coroutine.resume(next_co)
		else
			UpdateQueue[session_token] = nil
		end
	end

end

local function SessionToken(store_name, profile_key, is_mock)

	local session_token = "L_" -- Live

	if is_mock == true then
		session_token = "U_" -- User mock
	elseif DataStoreState ~= "Access" then
		session_token = "M_" -- Mock, cause no DataStore access
	end

	session_token ..= store_name .. "\0" .. profile_key

	return session_token

end

local function DeepCopyTable(t)
	local copy = {}
	for key, value in pairs(t) do
		if type(value) == "table" then
			copy[key] = DeepCopyTable(value)
		else
			copy[key] = value
		end
	end
	return copy
end

local function ReconcileTable(target, template)
	for k, v in pairs(template) do
		if type(k) == "string" then -- Only string keys will be reconciled
			if target[k] == nil then
				if type(v) == "table" then
					target[k] = DeepCopyTable(v)
				else
					target[k] = v
				end
			elseif type(target[k]) == "table" and type(v) == "table" then
				ReconcileTable(target[k], v)
			end
		end
	end
end

local function RegisterError(error_message, store_name, profile_key) -- Called when a DataStore API call errors
	warn(`[{script.Name}]: DataStore API error (STORE:{store_name}; KEY:{profile_key}) - {tostring(error_message)}`)
	table.insert(IssueQueue, os.clock()) -- Adding issue time to queue
	OnError:Fire(tostring(error_message), store_name, profile_key)
end

local function RegisterOverwrite(store_name, profile_key) -- Called when a corrupted profile is loaded
	warn(`[{script.Name}]: Invalid profile was overwritten (STORE:{store_name}; KEY:{profile_key})`)
	OnOverwrite:Fire(store_name, profile_key)
end

local function NewMockDataStoreKeyInfo(params)

	local version_id_string = tostring(params.VersionId or 0)
	local meta_data = params.MetaData or {}
	local user_ids = params.UserIds or {}

	return {
		CreatedTime = params.CreatedTime,
		UpdatedTime = params.UpdatedTime,
		Version = string.rep("0", 16) .. "."
			.. string.rep("0", 10 - string.len(version_id_string)) .. version_id_string
			.. "." .. string.rep("0", 16) .. "." .. "01",

		GetMetadata = function()
			return DeepCopyTable(meta_data)
		end,

		GetUserIds = function()
			return DeepCopyTable(user_ids)
		end,
	}

end

local function MockUpdateAsync(mock_data_store, profile_store_name, key, transform_function, is_get_call) --> loaded_data, key_info

	local profile_store = mock_data_store[profile_store_name]

	if profile_store == nil then
		profile_store = {}
		mock_data_store[profile_store_name] = profile_store
	end

	local epoch_time = math.floor(os.time() * 1000)
	local mock_entry = profile_store[key]
	local mock_entry_was_nil = false

	if mock_entry == nil then
		mock_entry_was_nil = true
		if is_get_call ~= true then
			mock_entry = {
				Data = nil,
				CreatedTime = epoch_time,
				UpdatedTime = epoch_time,
				VersionId = 0,
				UserIds = {},
				MetaData = {},
			}
			profile_store[key] = mock_entry
		end
	end

	local mock_key_info = mock_entry_was_nil == false and NewMockDataStoreKeyInfo(mock_entry) or nil

	local transform, user_ids, roblox_meta_data = transform_function(mock_entry and mock_entry.Data, mock_key_info)

	if transform == nil then
		return nil
	else
		if mock_entry ~= nil and is_get_call ~= true then
			mock_entry.Data = DeepCopyTable(transform)
			mock_entry.UserIds = DeepCopyTable(user_ids or {})
			mock_entry.MetaData = DeepCopyTable(roblox_meta_data or {})
			mock_entry.VersionId += 1
			mock_entry.UpdatedTime = epoch_time
		end

		return DeepCopyTable(transform), mock_entry ~= nil and NewMockDataStoreKeyInfo(mock_entry) or nil
	end

end

local function UpdateAsync(profile_store, profile_key, transform_params, is_user_mock, is_get_call, version) --> loaded_data, key_info
	--transform_params = {
	--	ExistingProfileHandle = function(latest_data),
	--	MissingProfileHandle = function(latest_data),
	--	EditProfile = function(latest_data),
	--}

	local loaded_data, key_info
	
	local next_in_queue = WaitInUpdateQueue(SessionToken(profile_store.Name, profile_key, is_user_mock))

	local success = true

	local success, error_message = pcall(function()
		local transform_function = function(latest_data)

			local missing_profile = false
			local overwritten = false
			local global_updates = {0, {}}

			if latest_data == nil then

				missing_profile = true

			elseif type(latest_data) ~= "table" then

				missing_profile = true
				overwritten = true

			else

				if type(latest_data.Data) == "table" and type(latest_data.MetaData) == "table" and type(latest_data.GlobalUpdates) == "table" then

					-- Regular profile structure detected:

					latest_data.WasOverwritten = false -- Must be set to false if set previously
					global_updates = latest_data.GlobalUpdates

					if transform_params.ExistingProfileHandle ~= nil then
						transform_params.ExistingProfileHandle(latest_data)
					end

				elseif latest_data.Data == nil and latest_data.MetaData == nil and type(latest_data.GlobalUpdates) == "table" then

					-- Regular structure not detected, but GlobalUpdate data exists:

					latest_data.WasOverwritten = false -- Must be set to false if set previously
					global_updates = latest_data.GlobalUpdates or global_updates
					missing_profile = true

				else

					missing_profile = true
					overwritten = true

				end

			end

			-- Profile was not created or corrupted and no GlobalUpdate data exists:
			if missing_profile == true then
				latest_data = {
					-- Data = nil,
					-- MetaData = nil,
					GlobalUpdates = global_updates,
				}
				if transform_params.MissingProfileHandle ~= nil then
					transform_params.MissingProfileHandle(latest_data)
				end
			end

			-- Editing profile:
			if transform_params.EditProfile ~= nil then
				transform_params.EditProfile(latest_data)
			end

			-- Invalid data handling (Silently override with empty profile)
			if overwritten == true then
				latest_data.WasOverwritten = true -- Temporary tag that will be removed on first save
			end

			return latest_data, latest_data.UserIds, latest_data.RobloxMetaData
		end

		if is_user_mock == true then -- Used when the profile is accessed through ProfileStore.Mock

			loaded_data, key_info = MockUpdateAsync(UserMockStore, profile_store.Name, profile_key, transform_function, is_get_call)
			task.wait() -- Simulate API call yield

		elseif DataStoreState ~= "Access" then -- Used when API access is disabled

			loaded_data, key_info = MockUpdateAsync(MockStore, profile_store.Name, profile_key, transform_function, is_get_call)
			task.wait() -- Simulate API call yield

		else

			if is_get_call == true then

				if version ~= nil then

					local success, error_message = pcall(function()
						loaded_data, key_info = profile_store.data_store:GetVersionAsync(profile_key, version)
					end)

					if success == false and type(error_message) == "string" and string.find(error_message, "not valid") ~= nil then
						warn(`[{script.Name}]: Passed version argument is not valid; Traceback:\n` .. debug.traceback())
					end

				else

					loaded_data, key_info = profile_store.data_store:GetAsync(profile_key)

				end

				loaded_data = transform_function(loaded_data)

			else

				loaded_data, key_info = profile_store.data_store:UpdateAsync(profile_key, transform_function)

			end

		end

	end)

	next_in_queue()

	if success == true and type(loaded_data) == "table" then
		-- Invalid data handling:
		if loaded_data.WasOverwritten == true and is_get_call ~= true then
			RegisterOverwrite(
				profile_store.Name,
				profile_key
			)
		end
		-- Return loaded_data:
		return loaded_data, key_info
	else
		-- Error handling:
		RegisterError(
			error_message or "Undefined error",
			profile_store.Name,
			profile_key
		)
		-- Return nothing:
		return nil
	end

end

local function IsThisSession(session_tag)
	return session_tag[1] == PlaceId and session_tag[2] == JobId
end

local function ReadMockFlag(): boolean
	local is_mock = MockFlag
	MockFlag = false
	return is_mock
end

local function WaitForStoreReady(profile_store)
	while profile_store.is_ready == false do
		task.wait()
	end
end

local function AddProfileToAutoSave(profile)

	ActiveSessionCheck[profile.session_token] = profile

	-- Add at AutoSaveIndex and move AutoSaveIndex right:

	table.insert(AutoSaveList, AutoSaveIndex, profile)

	if #AutoSaveList > 1 then
		AutoSaveIndex = AutoSaveIndex + 1
	elseif #AutoSaveList == 1 then
		-- First profile created - make sure it doesn't get immediately auto saved:
		LastAutoSave = os.clock()
	end

end

local function RemoveProfileFromAutoSave(profile)

	ActiveSessionCheck[profile.session_token] = nil

	local auto_save_index = table.find(AutoSaveList, profile)

	if auto_save_index ~= nil then
		table.remove(AutoSaveList, auto_save_index)
		if auto_save_index < AutoSaveIndex then
			AutoSaveIndex = AutoSaveIndex - 1 -- Table contents were moved left before AutoSaveIndex so move AutoSaveIndex left as well
		end
		if AutoSaveList[AutoSaveIndex] == nil then -- AutoSaveIndex was at the end of the AutoSaveList - reset to 1
			AutoSaveIndex = 1
		end
	end

end

local function SaveProfileAsync(profile, is_ending_session, is_overwriting, last_save_reason)

	if type(profile.Data) ~= "table" then
		error(`[{script.Name}]: Developer code likely set "Profile.Data" to a non-table value! (STORE:{profile.ProfileStore.Name}; KEY:{profile.Key})`)
	end

	profile.OnSave:Fire()
	if is_ending_session == true then
		profile.OnLastSave:Fire(last_save_reason or "Manual")
	end

	if is_ending_session == true and is_overwriting ~= true then
		if profile.roblox_message_subscription ~= nil then
			profile.roblox_message_subscription:Disconnect()
		end
		RemoveProfileFromAutoSave(profile)
		profile.OnSessionEnd:Fire()
	end

	ActiveProfileSaveJobs = ActiveProfileSaveJobs + 1

	-- Compare "SessionLoadCount" when writing to profile to prevent a rare case of repeat last save when the profile is loaded on the same server again

	local repeat_save_flag = true -- Released Profile save calls have to repeat until they succeed
	local exp_backoff = 1

	while repeat_save_flag == true do

		if is_ending_session ~= true then
			repeat_save_flag = false
		end

		local loaded_data, key_info = UpdateAsync(
			profile.ProfileStore,
			profile.Key,
			{
				ExistingProfileHandle = nil,
				MissingProfileHandle = nil,
				EditProfile = function(latest_data)
					
					-- Check if this session still owns the profile:

					local session_owns_profile = false

					if is_overwriting ~= true then

						local active_session = latest_data.MetaData.ActiveSession
						local session_load_count = latest_data.MetaData.SessionLoadCount

						if type(active_session) == "table" then
							session_owns_profile = IsThisSession(active_session) and session_load_count == profile.load_index
						end

					else
						session_owns_profile = true
					end

					-- We may only edit the profile if this server has ownership of the profile:

					if session_owns_profile == true then

						-- Clear processed updates (messages):

						local locked_updates = profile.locked_global_updates -- [index] = true, ...
						local active_updates = latest_data.GlobalUpdates[2]
						-- ProfileService module format: {{update_id, version_id, update_locked, update_data}, ...}
						-- ProfileStore module format: {{update_id, update_data}, ...}

						if next(locked_updates) ~= nil then
							local i = 1
							while i <= #active_updates do
								local update = active_updates[i]
								if locked_updates[update[1]] == true then
									table.remove(active_updates, i)
								else
									i += 1
								end
							end
						end

						-- Save profile data:

						latest_data.Data = profile.Data
						latest_data.RobloxMetaData = profile.RobloxMetaData
						latest_data.UserIds = profile.UserIds

						if is_overwriting ~= true then

							latest_data.MetaData.LastUpdate = os.time()

							if is_ending_session == true then
								latest_data.MetaData.ActiveSession = nil
							end

						else

							latest_data.MetaData.ActiveSession = nil
							latest_data.MetaData.ForceLoadSession = nil

						end

					end

				end,
			},
			profile.is_mock
		)

		if loaded_data ~= nil and key_info ~= nil then

			if is_overwriting == true then
				break
			end
			
			repeat_save_flag = false
			
			local active_session = loaded_data.MetaData.ActiveSession
			local session_load_count = loaded_data.MetaData.SessionLoadCount
			local session_owns_profile = false

			if type(active_session) == "table" then
				session_owns_profile = IsThisSession(active_session) and session_load_count == profile.load_index
			end
			
			local force_load_session = loaded_data.MetaData.ForceLoadSession
			local force_load_pending = false
			if type(force_load_session) == "table" then
				force_load_pending = not IsThisSession(force_load_session)
			end
			
			local is_active = profile:IsActive()
			
			-- If another server is trying to start a session for this profile - end the session:

			if force_load_pending == true and session_owns_profile == true then
				if is_active == true then
					SaveProfileAsync(profile, true, false, "External")
				end
				break
			end
			
			-- Clearing processed update list / Detecting new updates:

			local locked_updates = profile.locked_global_updates -- [index] = true, ...
			local received_updates = profile.received_global_updates -- [index] = true, ...
			local active_updates = loaded_data.GlobalUpdates[2]

			local new_updates = {} -- {}, ...
			local still_pending = {} -- [index] = true, ...

			for _, update in ipairs(active_updates) do
				if locked_updates[update[1]] == true then
					still_pending[update[1]] = true
				elseif received_updates[update[1]] ~= true then
					received_updates[update[1]] = true
					table.insert(new_updates, update)
				end
			end

			for index in pairs(locked_updates) do
				if still_pending[index] ~= true then
					locked_updates[index] = nil
				end
			end

			-- Updating profile values:

			profile.KeyInfo = key_info
			profile.LastSavedData = loaded_data.Data
			profile.global_updates = loaded_data.GlobalUpdates and loaded_data.GlobalUpdates[2] or {}

			if session_owns_profile == true then
				if is_active == true and is_ending_session ~= true then

					-- Processing new global updates (messages):

					for _, update in ipairs(new_updates) do

						local index = update[1]
						local update_data = update[#update] -- Backwards compatibility with ProfileService

						for _, handler in ipairs(profile.message_handlers) do

							local is_processed = false
							local processed_callback = function()
								is_processed = true
								locked_updates[index] = true
							end
							
							local send_update_data = DeepCopyTable(update_data)

							task.spawn(handler, send_update_data, processed_callback)

							if is_processed == true then
								break
							end

						end

					end

				end
			else
				
				if profile.roblox_message_subscription ~= nil then
					profile.roblox_message_subscription:Disconnect()
				end

				if is_active == true then
					RemoveProfileFromAutoSave(profile)
					profile.OnSessionEnd:Fire()
				end

			end

			profile.OnAfterSave:Fire(profile.LastSavedData)

		elseif repeat_save_flag == true then
			
			-- DataStore call likely resulted in an error; Repeat the DataStore call shortly
			task.wait(exp_backoff)
			exp_backoff = math.min(if last_save_reason == "Shutdown" then 8 else 20, exp_backoff * 2)

		end

	end

	ActiveProfileSaveJobs = ActiveProfileSaveJobs - 1

end

----- Public -----

--[[
	Saved profile structure:
	
	{
		Data = {},
		
		MetaData = {
			ProfileCreateTime = 0,
			SessionLoadCount = 0,
			ActiveSession = {place_id, game_job_id, unique_session_id} / nil,
			ForceLoadSession = {place_id, game_job_id} / nil,
			LastUpdate = 0, -- os.time()
			MetaTags = {}, -- Backwards compatibility with ProfileService
		},
		
		RobloxMetaData = {},
		UserIds = {},
		
		GlobalUpdates = {
			update_index,
			{
				{update_index, data}, ...
			},
		},
	}

--]]

export type JSONAcceptable = { JSONAcceptable } | { [string]: JSONAcceptable } | number | string | boolean | buffer

export type Profile<T> = {
	Data: T & JSONAcceptable,
	LastSavedData: T & JSONAcceptable,
	FirstSessionTime: number,
	SessionLoadCount: number,
	Session: {PlaceId: number, JobId: string}?,
	RobloxMetaData: JSONAcceptable,
	UserIds: {number},
	KeyInfo: DataStoreKeyInfo,
	OnSave: {Connect: (self: any, listener: () -> ()) -> ({Disconnect: (self: any) -> ()})},
	OnLastSave: {Connect: (self: any, listener: (reason: "Manual" | "External" | "Shutdown") -> ()) -> ({Disconnect: (self: any) -> ()})},
	OnSessionEnd: {Connect: (self: any, listener: () -> ()) -> ({Disconnect: (self: any) -> ()})},
	OnAfterSave: {Connect: (self: any, listener: (last_saved_data: T & JSONAcceptable) -> ()) -> ({Disconnect: (self: any) -> ()})},
	ProfileStore: JSONAcceptable,
	Key: string,

	IsActive: (self: any) -> (boolean),
	Reconcile: (self: any) -> (),
	EndSession: (self: any) -> (),
	AddUserId: (self: any, user_id: number) -> (),
	RemoveUserId: (self: any, user_id: number) -> (),
	MessageHandler: (self: any, fn: (message: JSONAcceptable, processed: () -> ()) -> ()) -> (),
	Save: (self: any) -> (),
	SetAsync: (self: any) -> (),
}

export type VersionQuery<T> = {
	NextAsync: (self: any) -> (Profile<T>?),
}

type ProfileStoreStandard<T> = {
	Name: string,
	StartSessionAsync: (self: any, profile_key: string, params: {Steal: boolean?}) -> (Profile<T>?),
	MessageAsync: (self: any, profile_key: string, message: JSONAcceptable) -> (boolean),
	GetAsync: (self: any, profile_key: string, version: string?) -> (Profile<T>?),
	VersionQuery: (self: any, profile_key: string, sort_direction: Enum.SortDirection?, min_date: DateTime | number | nil, max_date: DateTime | number | nil) -> (VersionQuery<T>),
	RemoveAsync: (self: any, profile_key: string) -> (boolean),
}

export type ProfileStore<T> = {
	Mock: ProfileStoreStandard<T>,
} & ProfileStoreStandard<T>

type ConstantName = "AUTO_SAVE_PERIOD" | "LOAD_REPEAT_PERIOD" | "FIRST_LOAD_REPEAT" | "SESSION_STEAL"
| "ASSUME_DEAD" | "START_SESSION_TIMEOUT" | "CRITICAL_STATE_ERROR_COUNT" | "CRITICAL_STATE_ERROR_EXPIRE"
| "CRITICAL_STATE_EXPIRE" | "MAX_MESSAGE_QUEUE"

export type ProfileStoreModule = {
	IsClosing: boolean,
	IsCriticalState: boolean,
	OnError: {Connect: (self: any, listener: (message: string, store_name: string, profile_key: string) -> ()) -> ({Disconnect: (self: any) -> ()})},
	OnOverwrite: {Connect: (self: any, listener: (store_name: string, profile_key: string) -> ()) -> ({Disconnect: (self: any) -> ()})},
	OnCriticalToggle: {Connect: (self: any, listener: (is_critical: boolean) -> ()) -> ({Disconnect: (self: any) -> ()})},
	DataStoreState: "NotReady" | "NoInternet" | "NoAccess" | "Access",
	New: <T>(store_name: string, template: (T & JSONAcceptable)?) -> (ProfileStore<T>),
	SetConstant: (name: ConstantName, value: number) -> ()
}

local Profile = {}
Profile.__index = Profile

function Profile.New(raw_data, key_info, profile_store, key, is_mock, session_token)

	local data = raw_data.Data or {}
	local session = raw_data.MetaData and raw_data.MetaData.ActiveSession or nil

	local global_updates = raw_data.GlobalUpdates and raw_data.GlobalUpdates[2] or {}
	local received_global_updates = {}

	for _, update in ipairs(global_updates) do
		received_global_updates[update[1]] = true
	end

	local self = {

		Data = data,
		LastSavedData = DeepCopyTable(data),

		FirstSessionTime = raw_data.MetaData and raw_data.MetaData.ProfileCreateTime or 0,
		SessionLoadCount = raw_data.MetaData and raw_data.MetaData.SessionLoadCount or 0,
		Session = session and {PlaceId = session[1], JobId = session[2]},

		RobloxMetaData = raw_data.RobloxMetaData or {},
		UserIds = raw_data.UserIds or {},
		KeyInfo = key_info,

		OnAfterSave = Signal.New(),
		OnSave = Signal.New(),
		OnLastSave = Signal.New(),
		OnSessionEnd = Signal.New(),

		ProfileStore = profile_store,
		Key = key,

		load_timestamp = os.clock(),
		is_mock = is_mock,
		session_token = session_token or "",
		load_index = raw_data.MetaData and raw_data.MetaData.SessionLoadCount or 0,
		locked_global_updates = {},
		received_global_updates = received_global_updates,
		message_handlers = {},
		global_updates = global_updates,

	}
	setmetatable(self, Profile)

	return self

end

function Profile:IsActive()
	return ActiveSessionCheck[self.session_token] == self
end

function Profile:Reconcile()
	ReconcileTable(self.Data, self.ProfileStore.template)
end

function Profile:EndSession()
	if self:IsActive() == true then
		task.spawn(SaveProfileAsync, self, true, nil, "Manual") -- Call save function in a new thread with release_from_session = true
	end
end

function Profile:AddUserId(user_id) -- Associates user_id with profile (GDPR compliance)

	if type(user_id) ~= "number" or user_id % 1 ~= 0 then
		warn(`[{script.Name}]: Invalid UserId argument for :AddUserId() ({tostring(user_id)}); Traceback:\n` .. debug.traceback())
		return
	end

	if user_id < 0 and self.is_mock ~= true and DataStoreState == "Access" then
		return -- Avoid giving real Roblox APIs negative UserId's
	end

	if table.find(self.UserIds, user_id) == nil then
		table.insert(self.UserIds, user_id)
	end

end

function Profile:RemoveUserId(user_id) -- Removes user_id association with profile (safe function)

	if type(user_id) ~= "number" or user_id % 1 ~= 0 then
		warn(`[{script.Name}]: Invalid UserId argument for :RemoveUserId() ({tostring(user_id)}); Traceback:\n` .. debug.traceback())
		return
	end

	local index = table.find(self.UserIds, user_id)

	if index ~= nil then
		table.remove(self.UserIds, index)
	end

end

function Profile:SetAsync() -- Saves the profile to the DataStore and removes the session lock

	if self.view_mode ~= true then
		error(`[{script.Name}]: :SetAsync() can only be used in view mode`)
	end

	SaveProfileAsync(self, nil, true)

end

function Profile:MessageHandler(fn)

	if type(fn) ~= "function" then
		error(`[{script.Name}]: fn argument is not a function`)
	end

	if self.view_mode ~= true and self:IsActive() ~= true then
		return -- Don't process messages if the profile session was ended
	end

	local locked_updates = self.locked_global_updates
	table.insert(self.message_handlers, fn)

	for _, update in ipairs(self.global_updates) do

		local index = update[1]
		local update_data = update[#update] -- Backwards compatibility with ProfileService

		if locked_updates[index] ~= true then

			local processed_callback = function()
				locked_updates[index] = true
			end
			
			local send_update_data = DeepCopyTable(update_data)

			task.spawn(fn, send_update_data, processed_callback)

		end

	end

end

function Profile:Save()
	
	if self.view_mode == true then
		error(`[{script.Name}]: Can't save profile in view mode; Should you be calling :SetAsync() instead?`)
	end
	
	if self:IsActive() == false then
		warn(`[{script.Name}]: Attempted saving an inactive profile (STORE:{self.ProfileStore.Name}; KEY:{self.Key});`
			.. ` Traceback:\n` .. debug.traceback())
		return
	end
	
	-- Move the profile right behind the auto save index to delay the next auto save for it:
	RemoveProfileFromAutoSave(self)
	AddProfileToAutoSave(self)
	
	-- Perform save in new thread:
	task.spawn(SaveProfileAsync, self)

end

local ProfileStore: ProfileStoreModule = {

	IsClosing = false,
	IsCriticalState = false,
	OnError = OnError, -- (message, store_name, profile_key)
	OnOverwrite = OnOverwrite, -- (store_name, profile_key)
	OnCriticalToggle = Signal.New(), -- (is_critical)
	DataStoreState = "NotReady", -- ("NotReady", "NoInternet", "NoAccess", "Access")

}
ProfileStore.__index = ProfileStore

function ProfileStore.SetConstant(name, value)

	if type(value) ~= "number" then
		error(`[{script.Name}]: Invalid value type`)
	end

	if name == "AUTO_SAVE_PERIOD" then
		AUTO_SAVE_PERIOD = value
	elseif name == "LOAD_REPEAT_PERIOD" then
		LOAD_REPEAT_PERIOD = value
	elseif name == "FIRST_LOAD_REPEAT" then
		FIRST_LOAD_REPEAT = value
	elseif name == "SESSION_STEAL" then
		SESSION_STEAL = value
	elseif name == "ASSUME_DEAD" then
		ASSUME_DEAD = value
	elseif name == "START_SESSION_TIMEOUT" then
		START_SESSION_TIMEOUT = value
	elseif name == "CRITICAL_STATE_ERROR_COUNT" then
		CRITICAL_STATE_ERROR_COUNT = value
	elseif name == "CRITICAL_STATE_ERROR_EXPIRE" then
		CRITICAL_STATE_ERROR_EXPIRE = value
	elseif name == "CRITICAL_STATE_EXPIRE" then
		CRITICAL_STATE_EXPIRE = value
	elseif name == "MAX_MESSAGE_QUEUE" then
		MAX_MESSAGE_QUEUE = value
	else
		error(`[{script.Name}]: Invalid constant name was provided`)
	end

end

function ProfileStore.Test()
	return {
		ActiveSessionCheck = ActiveSessionCheck,
		AutoSaveList = AutoSaveList,
		ActiveProfileLoadJobs = ActiveProfileLoadJobs,
		ActiveProfileSaveJobs = ActiveProfileSaveJobs,
		MockStore = MockStore,
		UserMockStore = UserMockStore,
		UpdateQueue = UpdateQueue,
	}
end

function ProfileStore.New(store_name, template)

	template = template or {}

	if type(store_name) ~= "string" then
		error(`[{script.Name}]: Invalid or missing "store_name"`)
	elseif string.len(store_name) == 0 then
		error(`[{script.Name}]: store_name cannot be an empty string`)
	elseif string.len(store_name) > 50 then
		error(`[{script.Name}]: store_name is too long`)
	end

	if type(template) ~= "table" then
		error(`[{script.Name}]: Invalid template argument`)
	end

	local self
	self = {

		Mock = {

			Name = store_name,

			StartSessionAsync = function(_, profile_key)
				MockFlag = true
				return self:StartSessionAsync(profile_key)
			end,
			MessageAsync = function(_, profile_key, message)
				MockFlag = true
				return self:MessageAsync(profile_key, message)
			end,
			GetAsync = function(_, profile_key, version)
				MockFlag = true
				return self:GetAsync(profile_key, version)
			end,
			VersionQuery = function(_, profile_key, sort_direction, min_date, max_date)
				MockFlag = true
				return self:VersionQuery(profile_key, sort_direction, min_date, max_date)
			end,
			RemoveAsync = function(_, profile_key)
				MockFlag = true
				return self:RemoveAsync(profile_key)
			end
		},

		Name = store_name,

		template = template,
		data_store = nil,
		load_jobs = {},
		mock_load_jobs = {},
		is_ready = true,

	}
	setmetatable(self, ProfileStore)

	local options = Instance.new("DataStoreOptions")
	options:SetExperimentalFeatures({v2 = true})

	if DataStoreState == "NotReady" then

		-- The module is not sure whether DataStores are accessible yet:

		self.is_ready = false

		task.spawn(function()

			repeat task.wait() until DataStoreState ~= "NotReady"

			if DataStoreState == "Access" then
				self.data_store = DataStoreService:GetDataStore(store_name, nil, options)
			end

			self.is_ready = true

		end)

	elseif DataStoreState == "Access" then

		self.data_store = DataStoreService:GetDataStore(store_name, nil, options)

	end

	return self

end

local function RobloxMessageSubscription(profile, unique_session_id)

	local last_roblox_message = 0
	
	local roblox_message_subscription = MessagingService:SubscribeAsync("PS_" .. unique_session_id, function(message)
		if type(message.Data) == "table" and message.Data.LoadCount == profile.SessionLoadCount then
			-- High reaction rate, based on numPlayers × 10 DataStore budget as of writing
			if os.clock() - last_roblox_message > 6 then 
				last_roblox_message = os.clock()
				if profile:IsActive() == true then
					if message.Data.EndSession == true then
						SaveProfileAsync(profile, true, false, "External")
					else
						profile:Save()
					end
				end
			end
		end
	end)

	if profile:IsActive() == true then
		profile.roblox_message_subscription = roblox_message_subscription
	else
		roblox_message_subscription:Disconnect()
	end

end

function ProfileStore:StartSessionAsync(profile_key, params)

	local is_mock = ReadMockFlag()

	if type(profile_key) ~= "string" then
		error(`[{script.Name}]: profile_key must be a string`)
	elseif string.len(profile_key) == 0 then
		error(`[{script.Name}]: Invalid profile_key`)
	elseif string.len(profile_key) > 50 then
		error(`[{script.Name}]: profile_key is too long`)
	end
	
	if params ~= nil and type(params) ~= "table" then
		error(`[{script.Name}]: Invalid params`)
	end
	
	params = params or {}

	if ProfileStore.IsClosing == true then
		return nil
	end
	
	WaitForStoreReady(self)

	local session_token = SessionToken(self.Name, profile_key, is_mock)

	if ActiveSessionCheck[session_token] ~= nil then
		error(`[{script.Name}]: Profile (STORE:{self.Name}; KEY:{profile_key}) is already loaded in this session`)
	end

	ActiveProfileLoadJobs = ActiveProfileLoadJobs + 1
	
	local is_user_cancel = false
	
	local function cancel_condition()
		if is_user_cancel == false then
			if params.Cancel ~= nil then
				is_user_cancel = params.Cancel() == true
			end
			return is_user_cancel
		end
		return true
	end
	
	local user_steal = params.Steal == true

	local force_load_steps = 0 -- Session conflict handling values
	local request_force_load = true
	local steal_session = false

	local start = os.clock()
	local exp_backoff = 1

	while ProfileStore.IsClosing == false and cancel_condition() == false do

		-- Load profile:

		-- SPECIAL CASE - If StartSessionAsync is called for the same key again before another StartSessionAsync finishes,
		-- grab the DataStore return for the new call. The early call will return nil. This is supposed to retain
		-- expected and efficient behavior in cases where a player would quickly rejoin the same server.

		LoadIndex += 1
		local load_id = LoadIndex
		local profile_load_jobs = is_mock == true and self.mock_load_jobs or self.load_jobs
		local profile_load_job = profile_load_jobs[profile_key] -- {load_id, {loaded_data, key_info} or nil}

		local loaded_data, key_info
		local unique_session_id = HttpService:GenerateGUID(false)

		if profile_load_job ~= nil then

			profile_load_job[1] = load_id -- Steal load job
			while profile_load_job[2] == nil do -- Wait for job to finish
				task.wait()
			end
			if profile_load_job[1] == load_id then -- Load job hasn't been double-stolen
				loaded_data, key_info = table.unpack(profile_load_job[2])
				profile_load_jobs[profile_key] = nil
			else
				ActiveProfileLoadJobs = ActiveProfileLoadJobs - 1
				return nil
			end

		else

			profile_load_job = {load_id, nil}
			profile_load_jobs[profile_key] = profile_load_job

			profile_load_job[2] = table.pack(UpdateAsync(
				self,
				profile_key,
				{
					ExistingProfileHandle = function(latest_data)

						if ProfileStore.IsClosing == true or cancel_condition() == true then
							return
						end

						local active_session = latest_data.MetaData.ActiveSession
						local force_load_session = latest_data.MetaData.ForceLoadSession

						if active_session == nil then
							latest_data.MetaData.ActiveSession = {PlaceId, JobId, unique_session_id}
							latest_data.MetaData.ForceLoadSession = nil
						elseif type(active_session) == "table" then
							if IsThisSession(active_session) == false then
								local last_update = latest_data.MetaData.LastUpdate
								if last_update ~= nil then
									if os.time() - last_update > ASSUME_DEAD then
										latest_data.MetaData.ActiveSession = {PlaceId, JobId, unique_session_id}
										latest_data.MetaData.ForceLoadSession = nil
										return
									end
								end
								if steal_session == true or user_steal == true then
									local force_load_interrupted = if force_load_session ~= nil then not IsThisSession(force_load_session) else true
									if force_load_interrupted == false or user_steal == true then
										latest_data.MetaData.ActiveSession = {PlaceId, JobId, unique_session_id}
										latest_data.MetaData.ForceLoadSession = nil
									end
								elseif request_force_load == true then
									latest_data.MetaData.ForceLoadSession = {PlaceId, JobId}
								end
							else
								latest_data.MetaData.ForceLoadSession = nil
							end
						end

					end,
					MissingProfileHandle = function(latest_data)
						
						local is_cancel = ProfileStore.IsClosing == true or cancel_condition() == true

						latest_data.Data = DeepCopyTable(self.template)
						latest_data.MetaData = {
							ProfileCreateTime = os.time(),
							SessionLoadCount = 0,
							ActiveSession = if is_cancel == false then {PlaceId, JobId, unique_session_id} else nil,
							ForceLoadSession = nil,
							MetaTags = {}, -- Backwards compatibility with ProfileService
						}

					end,
					EditProfile = function(latest_data)

						if ProfileStore.IsClosing == true or cancel_condition() == true then
							return
						end

						local active_session = latest_data.MetaData.ActiveSession
						if active_session ~= nil and IsThisSession(active_session) == true then
							latest_data.MetaData.SessionLoadCount = latest_data.MetaData.SessionLoadCount + 1
							latest_data.MetaData.LastUpdate = os.time()
						end

					end,
				},
				is_mock
				))
			if profile_load_job[1] == load_id then -- Load job hasn't been stolen
				loaded_data, key_info = table.unpack(profile_load_job[2])
				profile_load_jobs[profile_key] = nil
			else
				ActiveProfileLoadJobs = ActiveProfileLoadJobs - 1
				return nil -- Load job stolen
			end
		end

		-- Handle load_data:

		if loaded_data ~= nil and key_info ~= nil then
			local active_session = loaded_data.MetaData.ActiveSession
			if type(active_session) == "table" then

				if IsThisSession(active_session) == true then

					-- Profile is now taken by this session:

					local profile = Profile.New(loaded_data, key_info, self, profile_key, is_mock, session_token)
					AddProfileToAutoSave(profile)
					
					if is_mock ~= true and DataStoreState == "Access" then
						
						-- Use MessagingService to quickly detect session conflicts and resolve them quickly:
						task.spawn(RobloxMessageSubscription, profile, unique_session_id) -- Blocking prevention
						
					end

					if ProfileStore.IsClosing == true or cancel_condition() == true then
						-- The server has initiated a shutdown by the time this profile was loaded
						SaveProfileAsync(profile, true) -- Release profile and yield until the DataStore call is finished
						profile = nil -- Don't return the profile object
					end

					ActiveProfileLoadJobs = ActiveProfileLoadJobs - 1
					return profile

				else
					
					if ProfileStore.IsClosing == true or cancel_condition() == true then
						ActiveProfileLoadJobs = ActiveProfileLoadJobs - 1
						return nil
					end

					-- Profile is taken by some other session:

					local force_load_session = loaded_data.MetaData.ForceLoadSession
					local force_load_interrupted = if force_load_session ~= nil then not IsThisSession(force_load_session) else true

					if force_load_interrupted == false then

						if request_force_load == false then
							force_load_steps = force_load_steps + 1
							if force_load_steps >= math.ceil(SESSION_STEAL / LOAD_REPEAT_PERIOD) then
								steal_session = true
							end
						end
						
						-- Request the remote server to end its session:
						if type(active_session[3]) == "string" then
							local session_load_count = loaded_data.MetaData.SessionLoadCount or 0
							task.spawn(MessagingService.PublishAsync, MessagingService, "PS_" .. active_session[3], {LoadCount = session_load_count, EndSession = true})
						end
						
						-- Attempt to load the profile again after a delay
						local wait_until = os.clock() + if request_force_load == true then FIRST_LOAD_REPEAT else LOAD_REPEAT_PERIOD
						repeat task.wait() until os.clock() >= wait_until or ProfileStore.IsClosing == true

					else
						-- Another session tried to load this profile:
						ActiveProfileLoadJobs = ActiveProfileLoadJobs - 1
						return nil
					end

					request_force_load = false -- Only request a force load once

				end

			else
				ActiveProfileLoadJobs = ActiveProfileLoadJobs - 1
				return nil -- In this scenario it is likely that this server started shutting down
			end
		else
			
			-- A DataStore call has likely ended in an error:

			local default_timeout = false

			if params.Cancel == nil then
				default_timeout = os.clock() - start >= START_SESSION_TIMEOUT
			end
			
			if default_timeout == true or ProfileStore.IsClosing == true or cancel_condition() == true then
				ActiveProfileLoadJobs = ActiveProfileLoadJobs - 1
				return nil
			end
			
			task.wait(exp_backoff)  -- Repeat the call shortly
			exp_backoff = math.min(20, exp_backoff * 2)
			
		end

	end

	ActiveProfileLoadJobs = ActiveProfileLoadJobs - 1
	return nil -- Game started shutting down or the request was cancelled - don't return the profile

end

function ProfileStore:MessageAsync(profile_key, message)

	local is_mock = ReadMockFlag()

	if type(profile_key) ~= "string" then
		error(`[{script.Name}]: profile_key must be a string`)
	elseif string.len(profile_key) == 0 then
		error(`[{script.Name}]: Invalid profile_key`)
	elseif string.len(profile_key) > 50 then
		error(`[{script.Name}]: profile_key is too long`)
	end

	if type(message) ~= "table" then
		error(`[{script.Name}]: message must be a table`)
	end

	if ProfileStore.IsClosing == true then
		return false
	end

	WaitForStoreReady(self)

	local exp_backoff = 1

	while ProfileStore.IsClosing == false do

		-- Updating profile:

		local loaded_data = UpdateAsync(
			self,
			profile_key,
			{
				ExistingProfileHandle = nil,
				MissingProfileHandle = nil,
				EditProfile = function(latest_data)

					local global_updates = latest_data.GlobalUpdates
					local update_list = global_updates[2]
					--{
					--	update_index,
					--	{
					--		{update_index, data}, ...
					--	},
					--},

					global_updates[1] += 1
					table.insert(update_list, {global_updates[1], message})

					-- Clearing queue if above limit:

					while #update_list > MAX_MESSAGE_QUEUE do
						table.remove(update_list, 1)
					end

				end,
			},
			is_mock
		)

		if loaded_data ~= nil then
			
			local session_token = SessionToken(self.Name, profile_key, is_mock)
			
			local profile = ActiveSessionCheck[session_token]
			
			if profile ~= nil then
				
				-- The message was sent to a profile that is active in this server:
				profile:Save()
				
			else
				
				local meta_data = loaded_data.MetaData or {}
				local active_session = meta_data.ActiveSession
				local session_load_count = meta_data.SessionLoadCount or 0
				
				if type(active_session) == "table" and type(active_session[3]) == "string" then
					-- Request the remote server to auto-save sooner and receive the message:
					task.spawn(MessagingService.PublishAsync, MessagingService, "PS_" .. active_session[3], {LoadCount = session_load_count})
				end
				
			end

			return true

		else

			task.wait(exp_backoff) -- A DataStore call has likely ended in an error - repeat the call shortly
			exp_backoff = math.min(20, exp_backoff * 2)

		end

	end

	return false

end

function ProfileStore:GetAsync(profile_key, version)

	local is_mock = ReadMockFlag()

	if type(profile_key) ~= "string" then
		error(`[{script.Name}]: profile_key must be a string`)
	elseif string.len(profile_key) == 0 then
		error(`[{script.Name}]: Invalid profile_key`)
	elseif string.len(profile_key) > 50 then
		error(`[{script.Name}]: profile_key is too long`)
	end

	if ProfileStore.IsClosing == true then
		return nil
	end

	WaitForStoreReady(self)

	if version ~= nil and (is_mock or DataStoreState ~= "Access") then
		return nil -- No version support in mock mode
	end

	local exp_backoff = 1

	while ProfileStore.IsClosing == false do

		-- Load profile:

		local loaded_data, key_info = UpdateAsync(
			self,
			profile_key,
			{
				ExistingProfileHandle = nil,
				MissingProfileHandle = function(latest_data)

					latest_data.Data = DeepCopyTable(self.template)
					latest_data.MetaData = {
						ProfileCreateTime = os.time(),
						SessionLoadCount = 0,
						ActiveSession = nil,
						ForceLoadSession = nil,
						MetaTags = {}, -- Backwards compatibility with ProfileService
					}

				end,
				EditProfile = nil,
			},
			is_mock,
			true, -- Use :GetAsync()
			version -- DataStore key version
		)

		-- Handle load_data:

		if loaded_data ~= nil then

			if key_info == nil then
				return nil -- Load was successful, but the key was empty - return no profile object
			end

			local profile = Profile.New(loaded_data, key_info, self, profile_key, is_mock)
			profile.view_mode = true

			return profile

		else

			task.wait(exp_backoff) -- A DataStore call has likely ended in an error - repeat the call shortly
			exp_backoff = math.min(20, exp_backoff * 2)

		end

	end

	return nil -- Game started shutting down - don't return the profile

end

function ProfileStore:RemoveAsync(profile_key)

	local is_mock = ReadMockFlag()

	if type(profile_key) ~= "string" or string.len(profile_key) == 0 then
		error(`[{script.Name}]: Invalid profile_key`)
	end

	if ProfileStore.IsClosing == true then
		return false
	end

	WaitForStoreReady(self)

	local wipe_status = false
	
	local next_in_queue = WaitInUpdateQueue(SessionToken(self.Name, profile_key, is_mock))

	if is_mock == true then -- Used when the profile is accessed through ProfileStore.Mock

		local mock_data_store = UserMockStore[self.Name]

		if mock_data_store ~= nil then
			mock_data_store[profile_key] = nil
			if next(mock_data_store) == nil then
				UserMockStore[self.Name] = nil
			end
		end

		wipe_status = true
		task.wait() -- Simulate API call yield

	elseif DataStoreState ~= "Access" then -- Used when API access is disabled

		local mock_data_store = MockStore[self.Name]

		if mock_data_store ~= nil then
			mock_data_store[profile_key] = nil
			if next(mock_data_store) == nil then
				MockStore[self.Name] = nil
			end
		end

		wipe_status = true
		task.wait() -- Simulate API call yield

	else -- Live DataStore

		wipe_status = pcall(function()
			self.data_store:RemoveAsync(profile_key)
		end)

	end
	
	next_in_queue()

	return wipe_status

end

local ProfileVersionQuery = {}
ProfileVersionQuery.__index = ProfileVersionQuery

function ProfileVersionQuery.New(profile_store, profile_key, sort_direction, min_date, max_date, is_mock)

	local self = {
		profile_store = profile_store,
		profile_key = profile_key,
		sort_direction = sort_direction,
		min_date = min_date,
		max_date = max_date,

		query_pages = nil,
		query_index = 0,
		query_failure = false,

		is_query_yielded = false,
		query_queue = {},

		is_mock = is_mock,
	}
	setmetatable(self, ProfileVersionQuery)

	return self

end

function MoveVersionQueryQueue(self) -- Hidden ProfileVersionQuery method
	while #self.query_queue > 0 do

		local queue_entry = table.remove(self.query_queue, 1)

		task.spawn(queue_entry)

		if self.is_query_yielded == true then
			break
		end

	end
end

local VersionQueryNextAsyncStackingFlag = false
local WarnAboutVersionQueryOnce = false

function ProfileVersionQuery:NextAsync()

	local is_stacking = VersionQueryNextAsyncStackingFlag == true
	VersionQueryNextAsyncStackingFlag = false

	WaitForStoreReady(self.profile_store)

	if ProfileStore.IsClosing == true then
		return nil -- Silently fail :NextAsync() requests
	end

	if self.is_mock == true or DataStoreState ~= "Access" then
		if IsStudio == true and WarnAboutVersionQueryOnce == false then
			WarnAboutVersionQueryOnce = true
			warn(`[{script.Name}]: :VersionQuery() is not supported in mock mode!`)
		end
		return nil -- Silently fail :NextAsync() requests
	end

	local profile
	local is_finished = false

	local function query_job()

		if self.query_failure == true then
			is_finished = true
			return
		end

		-- First "next" call loads version pages:

		if self.query_pages == nil then

			self.is_query_yielded = true

			task.spawn(function()
				VersionQueryNextAsyncStackingFlag = true
				profile = self:NextAsync()
				is_finished = true
			end)

			local list_success, error_message = pcall(function()
				self.query_pages = self.profile_store.data_store:ListVersionsAsync(
					self.profile_key,
					self.sort_direction,
					self.min_date,
					self.max_date
				)
				self.query_index = 0
			end)

			if list_success == false or self.query_pages == nil then
				warn(`[{script.Name}]: Version query fail - {tostring(error_message)}`)
				self.query_failure = true
			end

			self.is_query_yielded = false

			MoveVersionQueryQueue(self)

			return

		end

		local current_page = self.query_pages:GetCurrentPage()
		local next_item = current_page[self.query_index + 1]

		-- No more entries:

		if self.query_pages.IsFinished == true and next_item == nil then
			is_finished = true
			return
		end

		-- Load next page when this page is over:

		if next_item == nil then

			self.is_query_yielded = true
			task.spawn(function()
				VersionQueryNextAsyncStackingFlag = true
				profile = self:NextAsync()
				is_finished = true
			end)

			local success, error_message = pcall(function()
				self.query_pages:AdvanceToNextPageAsync()
				self.query_index = 0
			end)

			if success == false or #self.query_pages:GetCurrentPage() == 0 then
				self.query_failure = true
			end

			self.is_query_yielded = false
			MoveVersionQueryQueue(self)

			return

		end

		-- Next page item:

		self.query_index += 1
		profile = self.profile_store:GetAsync(self.profile_key, next_item.Version)
		is_finished = true

	end

	if self.is_query_yielded == false then
		query_job()
	else
		if is_stacking == true then
			table.insert(self.query_queue, 1, query_job)
		else
			table.insert(self.query_queue, query_job)
		end
	end

	while is_finished == false do
		task.wait()
	end

	return profile

end

function ProfileStore:VersionQuery(profile_key, sort_direction, min_date, max_date)

	local is_mock = ReadMockFlag()

	if type(profile_key) ~= "string" or string.len(profile_key) == 0 then
		error(`[{script.Name}]: Invalid profile_key`)
	end

	-- Type check:

	if sort_direction ~= nil and (typeof(sort_direction) ~= "EnumItem"
		or sort_direction.EnumType ~= Enum.SortDirection) then
		error(`[{script.Name}]: Invalid sort_direction ({tostring(sort_direction)})`)
	end

	if min_date ~= nil and typeof(min_date) ~= "DateTime" and typeof(min_date) ~= "number" then
		error(`[{script.Name}]: Invalid min_date ({tostring(min_date)})`)
	end

	if max_date ~= nil and typeof(max_date) ~= "DateTime" and typeof(max_date) ~= "number" then
		error(`[{script.Name}]: Invalid max_date ({tostring(max_date)})`)
	end

	min_date = typeof(min_date) == "DateTime" and min_date.UnixTimestampMillis or min_date
	max_date = typeof(max_date) == "DateTime" and max_date.UnixTimestampMillis or max_date

	return ProfileVersionQuery.New(self, profile_key, sort_direction, min_date, max_date, is_mock)

end

-- DataStore API access check:

if IsStudio == true then

	task.spawn(function()

		local new_state = "NoAccess"

		local status, message = pcall(function()
			-- This will error if current instance has no Studio API access:
			DataStoreService:GetDataStore("____PS"):SetAsync("____PS", os.time())
		end)

		local no_internet_access = status == false and string.find(message, "ConnectFail", 1, true) ~= nil

		if no_internet_access == true then
			warn(`[{script.Name}]: No internet access - check your network connection`)
		end

		if status == false and
			(string.find(message, "403", 1, true) ~= nil or -- Cannot write to DataStore from studio if API access is not enabled
				string.find(message, "must publish", 1, true) ~= nil or -- Game must be published to access live keys
				no_internet_access == true) then -- No internet access

			new_state = if no_internet_access == true then "NoInternet" else "NoAccess"
			print(`[{script.Name}]: Roblox API services unavailable - data will not be saved`)
		else
			new_state = "Access"
			print(`[{script.Name}]: Roblox API services available - data will be saved`)
		end

		DataStoreState = new_state
		ProfileStore.DataStoreState = new_state

	end)

else
	
	DataStoreState = "Access"
	ProfileStore.DataStoreState = "Access"
	
end

-- Update loop:

RunService.Heartbeat:Connect(function()

	-- Auto saving:

	local auto_save_list_length = #AutoSaveList
	if auto_save_list_length > 0 then
		local auto_save_index_speed = AUTO_SAVE_PERIOD / auto_save_list_length
		local os_clock = os.clock()
		while os_clock - LastAutoSave > auto_save_index_speed do
			LastAutoSave = LastAutoSave + auto_save_index_speed
			local profile = AutoSaveList[AutoSaveIndex]
			if os_clock - profile.load_timestamp < AUTO_SAVE_PERIOD / 2 then
				-- This profile is freshly loaded - auto saving immediately is not necessary:
				profile = nil
				for _ = 1, auto_save_list_length - 1 do
					-- Move auto save index to the right:
					AutoSaveIndex = AutoSaveIndex + 1
					if AutoSaveIndex > auto_save_list_length then
						AutoSaveIndex = 1
					end
					profile = AutoSaveList[AutoSaveIndex]
					if os_clock - profile.load_timestamp >= AUTO_SAVE_PERIOD / 2 then
						break
					else
						profile = nil
					end
				end
			end
			-- Move auto save index to the right:
			AutoSaveIndex = AutoSaveIndex + 1
			if AutoSaveIndex > auto_save_list_length then
				AutoSaveIndex = 1
			end
			-- Perform save call:
			if profile ~= nil then
				task.spawn(SaveProfileAsync, profile) -- Auto save profile in new thread
			end
		end
	end

	-- Critical state handling:

	if ProfileStore.IsCriticalState == false then
		if #IssueQueue >= CRITICAL_STATE_ERROR_COUNT then
			ProfileStore.IsCriticalState = true
			ProfileStore.OnCriticalToggle:Fire(true)
			CriticalStateStart = os.clock()
			warn(`[{script.Name}]: Entered critical state`)
		end
	else
		if #IssueQueue >= CRITICAL_STATE_ERROR_COUNT then
			CriticalStateStart = os.clock()
		elseif os.clock() - CriticalStateStart > CRITICAL_STATE_EXPIRE then
			ProfileStore.IsCriticalState = false
			ProfileStore.OnCriticalToggle:Fire(false)
			warn(`[{script.Name}]: Critical state ended`)
		end
	end

	-- Issue queue:

	while true do
		local issue_time = IssueQueue[1]
		if issue_time == nil then
			break
		elseif os.clock() - issue_time > CRITICAL_STATE_ERROR_EXPIRE then
			table.remove(IssueQueue, 1)
		else
			break
		end
	end

end)

-- Release all loaded profiles when the server is shutting down:

task.spawn(function()

	while DataStoreState == "NotReady" do
		task.wait()
	end

	if DataStoreState ~= "Access" then

		game:BindToClose(function()
			ProfileStore.IsClosing = true
			task.wait() -- Mock shutdown delay
		end)

		return -- Don't wait for profiles to properly save in mock mode so studio could end the simulation faster

	end

	game:BindToClose(function()

		ProfileStore.IsClosing = true

		-- Release all active profiles:
		-- (Clone AutoSaveList to a new table because AutoSaveList changes when profiles are released)

		local on_close_save_job_count = 0
		local active_profiles = {}
		for index, profile in ipairs(AutoSaveList) do
			active_profiles[index] = profile
		end

		-- Release the profiles; Releasing profiles can trigger listeners that release other profiles, so check active state:
		for _, profile in ipairs(active_profiles) do
			if profile:IsActive() == true then
				on_close_save_job_count = on_close_save_job_count + 1
				task.spawn(function() -- Save profile on new thread
					SaveProfileAsync(profile, true, nil, "Shutdown")
					on_close_save_job_count = on_close_save_job_count - 1
				end)
			end
		end

		-- Yield until all active profile jobs are finished:
		while on_close_save_job_count > 0 or ActiveProfileLoadJobs > 0 or ActiveProfileSaveJobs > 0 do
			task.wait()
		end

		return -- We're done!

	end)

end)

return ProfileStore
]======])
put("StarterPlayer/StarterPlayerScripts/MTL", "Client", "LocalScript", [======[--!strict
-- Boots every client controller in order. Each starts on its own (pcall), so one failure can't stop the rest,
-- and errors go to Output on "[MTL Client]" lines (no red box on screen).
-- New controllers: add them here in dependency order.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Net = require(ReplicatedStorage.MTL.Net)
local Controllers = script.Parent:WaitForChild("Controllers")

local order = {
	"ClientData",
	"UIState",
	"MovementController", -- sprint, speed easing, camera feel, lean, jump cooldown (the only WalkSpeed writer)
	"HUDController",
	"WayfindingController",
	"PhoneController",
	"JobController", -- Piece 2 (helpers JobFX + JobMinigames are required by it, not booted here)
	"GunController", -- Piece 5 (helpers GunFX + GunPose are required by it)
	"MenuController", -- HUD: the icon menu + Store / Emotes (needs PhoneController)
	"HotbarController", -- HUD: bottom slots (needs GunController)
	"MapMarkers", -- HUD: emoji markers over places
	"CutsceneController", -- Piece 3 (helper Actors is required by it)
	"MissionController", -- Piece 3 (needs CutsceneController)
	"PropertyController", -- Piece 4: the flat (needs CutsceneController, PhoneController, WayfindingController)
	"LightingController", -- time of day + street lights (needs CutsceneController for the story holds)
	"TutorialController", -- the new-player coach card (needs HUD, Phone, Menu, Cutscene)
}

-- Wait for the saved screens (StarterGui/MTL_*) to be copied into PlayerGui first, otherwise a controller that
-- starts before the first spawn builds its own copy and the player ends up with two of every screen.
do
	local StarterGui = game:GetService("StarterGui")
	local pg = Players.LocalPlayer:WaitForChild("PlayerGui")
	for _, g in StarterGui:GetChildren() do
		if g:IsA("ScreenGui") and string.sub(g.Name, 1, 4) == "MTL_" then
			pg:WaitForChild(g.Name, 10)
		end
	end
end

local MTL = {}
for _, name in order do
	local module = Controllers:WaitForChild(name, 10)
	if not module then
		warn("[MTL Client] missing controller", name)
		continue
	end
	local ok, ctrl = pcall(require, module)
	if not ok then
		warn("[MTL Client] require failed:", name, ctrl)
		continue
	end
	MTL[name] = ctrl
	if type(ctrl) == "table" and ctrl.init then
		local initOk, err = pcall(ctrl.init)
		if not initOk then
			warn("[MTL Client] init failed:", name, err)
		end
	end
end

-- Tell the server we're listening (it re-sends waypoints). Again after every respawn.
Net.get("ClientReady"):FireServer()
Players.LocalPlayer.CharacterAdded:Connect(function()
	task.wait(0.5)
	Net.get("ClientReady"):FireServer()
end)

print("[MTL Client] ready")
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Apps", "Calls", "ModuleScript", [======[--!strict
-- Phone app: Recents (missed in red, "Call back" on calls that wait for an answer) and Contacts.
-- Calling a contact with no scripted call plays the local "Calling... / No answer" screen.
local App = { id = "Calls", title = "Phone" }

local KIND_TEXT = {
	missed = "Missed call",
	declined = "Declined",
	answered = "Incoming",
	outgoing = "Outgoing",
}

local function name(ctx: any, id: string): string
	if id == "Unknown" then
		return "Unknown number"
	end
	local c = ctx.Story.Contacts[id]
	return if c then c.Name else id
end

local function glyph(ctx: any, id: string): string
	return if id == "Unknown" then "?" else string.sub(name(ctx, id), 1, 1)
end

-- the newest Recents entry for this contact that can be called back
local function callBackFor(d: any, contact: string): any?
	for _, r in d.Phone.Recents or {} do
		if r.contact == contact and r.callBack then
			return r
		end
	end
	return nil
end

local function tabs(ctx: any, active: string, onPick: (string) -> ())
	local UIKit, Theme = ctx.UIKit, ctx.Theme
	local bar = UIKit.new("Frame", {
		Name = "Tabs",
		Position = UDim2.fromOffset(12, 46),
		Size = UDim2.new(1, -24, 0, 32),
		BackgroundColor3 = Theme.Phone.Card,
		Parent = ctx.frame,
	}, { UIKit.corner(UDim.new(1, 0)), UIKit.list(0, true), UIKit.padding(3) })
	for i, t in { "Recents", "Contacts" } do
		local on = t == active
		local b = UIKit.new("TextButton", {
			Name = t,
			LayoutOrder = i,
			Size = UDim2.new(0.5, 0, 1, 0),
			BackgroundColor3 = if on then Theme.Phone.CardHover else Theme.Phone.Card,
			BackgroundTransparency = if on then 0 else 1,
			AutoButtonColor = false,
			FontFace = Theme.Fonts.Bold,
			Text = t,
			TextColor3 = if on then Theme.Colors.Text else Theme.Colors.TextDim,
			TextSize = 14,
			Parent = bar,
		}, { UIKit.corner(UDim.new(1, 0)) })
		b.Activated:Connect(function()
			onPick(t)
		end)
	end
end

local show: (any, string) -> ()

local function recents(ctx: any, list: ScrollingFrame, d: any)
	local UIKit, Theme = ctx.UIKit, ctx.Theme
	local entries = d.Phone.Recents or {}
	if #entries == 0 then
		UIKit.empty(list, "No calls yet.")
		return
	end
	local now = os.time()
	for i, r in entries do
		local missed = r.kind == "missed" or r.kind == "declined"
		local row = UIKit.row(list, {
			title = name(ctx, r.contact),
			sub = (KIND_TEXT[r.kind] or r.kind) .. "  ·  " .. ctx.Rules.ago(now - (r.t or now)),
			right = if r.callBack then "Call back" else nil,
			rightColor = if r.callBack then Theme.Colors.Accent else nil,
			glyph = glyph(ctx, r.contact),
			order = i,
			onClick = function()
				if r.callBack and r.call then
					ctx.action("callBack", { call = r.call })
				else
					ctx.Phone.fakeCall(name(ctx, r.contact), ctx.Config.NoAnswer[r.contact])
				end
			end,
		})
		if missed then
			row.Title.TextColor3 = Theme.Colors.Danger
		end
		if r.callBack then
			-- accent outline so the one thing to do here is obvious
			local stroke = UIKit.stroke(0.4, Theme.Colors.Accent)
			stroke.Parent = row
		end
	end
end

local function contacts(ctx: any, list: ScrollingFrame, d: any)
	local UIKit = ctx.UIKit
	local ids = {}
	for id in d.Phone.Contacts or {} do
		table.insert(ids, id)
	end
	table.sort(ids, function(a, b)
		return name(ctx, a) < name(ctx, b)
	end)
	if #ids == 0 then
		UIKit.empty(list, "No contacts yet.")
		return
	end
	for i, id in ids do
		local c = ctx.Story.Contacts[id]
		UIKit.row(list, {
			title = name(ctx, id),
			sub = c and c.Subtitle or nil,
			right = "Call",
			glyph = glyph(ctx, id),
			order = i,
			onClick = function()
				local cb = callBackFor(d, id)
				if cb then
					ctx.action("callBack", { call = cb.call })
				else
					ctx.Phone.fakeCall(name(ctx, id), ctx.Config.NoAnswer[id])
				end
			end,
		})
	end
end

show = function(ctx: any, tab: string)
	ctx.clear()
	ctx.tab = tab
	ctx.UIKit.header(ctx.frame, "Phone")
	tabs(ctx, tab, function(t)
		if t ~= ctx.tab then
			show(ctx, t)
		end
	end)
	local list = ctx.UIKit.scroll(ctx.frame, 84, tab)
	local token = {}
	ctx.token = token
	ctx.onData(function(d: any)
		if ctx.token ~= token then
			return
		end
		for _, c in list:GetChildren() do
			if c:IsA("GuiObject") then
				c:Destroy()
			end
		end
		if tab == "Recents" then
			recents(ctx, list, d)
		else
			contacts(ctx, list, d)
		end
	end)
end

function App.mount(_frame: Frame, ctx: any)
	show(ctx, ctx.args.tab or "Recents")
	local d = ctx.data()
	if d and ctx.Rules.missedCount(d.Phone) > 0 then
		ctx.action("seenRecents")
	end
end

return App
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Apps", "Camera", "ModuleScript", [======[--!strict
-- Camera: the phone becomes a viewfinder (you see the world through the glass, the HUD hides). Photo or Selfie
-- (the camera swings round in front of your face). The shutter takes a real Roblox screenshot (CaptureService)
-- with the phone hidden for that frame, flashes, and drops the photo in the roll. The roll keeps this session's
-- photos; "Save" asks Roblox to save one to the player's Captures gallery.
local Lighting = game:GetService("Lighting")
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")

local UIState = require(script.Parent.Parent.Controllers.UIState)

local App = { id = "Camera", title = "Camera" }

local player = Players.LocalPlayer
local roll: { string } = {} -- contentIds taken this session, newest last
local MAX_ROLL = 24

local function captureService(): any?
	local ok, svc = pcall(function()
		return game:GetService("CaptureService")
	end)
	return if ok then svc else nil
end

---------------------------------------------------------------- filters
-- Colour filters for the viewfinder (a ColorCorrection on Lighting, client only, so it's in the photo too).
local FILTERS = {
	{ name = "Normal" },
	{ name = "Vivid", saturation = 0.35, contrast = 0.12 },
	{ name = "Miami", tint = Color3.fromRGB(255, 214, 236), saturation = 0.25, contrast = 0.05, brightness = 0.02 },
	{ name = "Sunset", tint = Color3.fromRGB(255, 220, 180), saturation = 0.15, contrast = 0.08 },
	{ name = "Night", tint = Color3.fromRGB(190, 210, 255), saturation = -0.2, contrast = 0.15, brightness = -0.04 },
	{ name = "Noir", saturation = -1, contrast = 0.25 },
	{ name = "Faded", saturation = -0.35, contrast = -0.15, brightness = 0.05 },
}
local filterIndex = 1

local function setFilter(i: number?)
	local old = Lighting:FindFirstChild("MTL_CameraFilter")
	local f = if i then FILTERS[i] else nil
	if not f or f.name == "Normal" then
		if old then
			old:Destroy()
		end
		return
	end
	local cc = (old or Instance.new("ColorCorrectionEffect")) :: ColorCorrectionEffect
	cc.Name = "MTL_CameraFilter"
	cc.TintColor = f.tint or Color3.new(1, 1, 1)
	cc.Saturation = f.saturation or 0
	cc.Contrast = f.contrast or 0
	cc.Brightness = f.brightness or 0
	cc.Parent = Lighting
end

---------------------------------------------------------------- selfie camera

local selfieConn: RBXScriptConnection? = nil
local savedCamType: Enum.CameraType? = nil
local savedFov: number? = nil

local function stopSelfie()
	if selfieConn then
		selfieConn:Disconnect()
		selfieConn = nil
	end
	local cam = workspace.CurrentCamera
	if cam and savedCamType then
		cam.CameraType = savedCamType
		if savedFov then
			cam.FieldOfView = savedFov
		end
		local hum = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
		if hum then
			cam.CameraSubject = hum
		end
	end
	savedCamType = nil
	savedFov = nil
end

local function startSelfie()
	local cam = workspace.CurrentCamera
	if not cam or selfieConn then
		return
	end
	savedCamType = cam.CameraType
	savedFov = cam.FieldOfView
	cam.CameraType = Enum.CameraType.Scriptable
	local smooth: CFrame? = nil
	selfieConn = RunService.RenderStepped:Connect(function(dt)
		local char = player.Character
		local head = char and char:FindFirstChild("Head") :: BasePart?
		if not head then
			return
		end
		-- arm's length in front of the face, a little above and to the side, looking back at you
		local h = head.CFrame
		local eye = h.Position + h.LookVector * 3.6 + h.UpVector * 0.55 + h.RightVector * 0.9
		local want = CFrame.lookAt(eye, h.Position + h.UpVector * 0.15)
		smooth = if smooth then smooth:Lerp(want, math.clamp(dt * 12, 0, 1)) else want
		cam.CFrame = smooth :: CFrame
		cam.FieldOfView = 62
	end)
end

---------------------------------------------------------------- views

local render: (any) -> ()

local function flash(ctx: any)
	local gui = ctx.frame:FindFirstAncestorOfClass("ScreenGui")
	if not gui then
		return
	end
	local f = gui:FindFirstChild("Flash") :: Frame?
	if not f then
		f = ctx.UIKit.new("Frame", {
			Name = "Flash",
			Size = UDim2.fromScale(1, 1),
			BackgroundColor3 = Color3.new(1, 1, 1),
			BackgroundTransparency = 1,
			ZIndex = 100,
			Parent = gui,
		})
	end
	assert(f)
	f.BackgroundTransparency = 0.25
	game:GetService("TweenService"):Create(f, TweenInfo.new(0.45, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundTransparency = 1 }):Play()
end

local busy = false
local lastShot = -1e9

local function shoot(ctx: any)
	-- one photo per press: ignore repeats (Space can also reach a focused button)
	if busy or os.clock() - lastShot < 1 then
		return
	end
	lastShot = os.clock()
	local cs = captureService()
	busy = true
	ctx.sfx("PhoneShutter")
	if not cs then
		flash(ctx)
		busy = false
		ctx.Phone.notify({ title = "Camera", text = "Photos aren't available here" })
		return
	end
	-- hide the phone for the frame the picture is taken
	ctx.Phone.setCaptureHidden(true)
	RunService.RenderStepped:Wait()
	local done = false
	local ok = pcall(function()
		cs:CaptureScreenshot(function(contentId: any)
			done = true
			ctx.Phone.setCaptureHidden(false)
			flash(ctx)
			if contentId then
				table.insert(roll, tostring(contentId))
				while #roll > MAX_ROLL do
					table.remove(roll, 1)
				end
			end
			busy = false
			if ctx.frame.Parent then
				render(ctx)
			end
		end)
	end)
	if not ok then
		done = true
		busy = false
		ctx.Phone.setCaptureHidden(false)
		flash(ctx)
		ctx.Phone.notify({ title = "Camera", text = "Couldn't take the photo" })
		return
	end
	-- never leave the phone hidden if Roblox doesn't answer
	task.delay(1.5, function()
		if not done then
			ctx.Phone.setCaptureHidden(false)
			busy = false
		end
	end)
end

local function save(ctx: any, contentId: string, status: TextLabel)
	local cs = captureService()
	if not cs then
		status.Text = "Saving isn't available here"
		return
	end
	local ok = pcall(function()
		cs:PromptSaveCapturesToGallery({ contentId }, function(results: any)
			local saved = type(results) == "table" and results[contentId] == true
			if status.Parent then
				status.Text = if saved then "Saved to your Captures" else "Not saved"
			end
		end)
	end)
	if not ok then
		status.Text = "Saving isn't available here"
	end
end

local function showPhoto(ctx: any, index: number)
	ctx.clear()
	ctx.view = "photo"
	stopSelfie()
	setFilter(nil)
	ctx.Phone.setViewfinder(false)
	local UIKit = ctx.UIKit
	UIKit.header(ctx.frame, string.format("Photo %d of %d", index, #roll), function()
		ctx.view = "roll"
		render(ctx)
	end)
	local id = roll[index]
	UIKit.new("ImageLabel", {
		Name = "Photo",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 50),
		Size = UDim2.new(1, -20, 1, -150),
		BackgroundColor3 = Color3.new(0, 0, 0),
		Image = id or "",
		ScaleType = Enum.ScaleType.Fit,
		Parent = ctx.frame,
	}, { UIKit.corner(UDim.new(0, 18)) })
	local bottom = UIKit.new("Frame", {
		Name = "Actions",
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 1, -8),
		Size = UDim2.new(1, -20, 0, 84),
		BackgroundTransparency = 1,
		Parent = ctx.frame,
	}, { UIKit.list(6) })
	local status = UIKit.label(bottom, "", { size = 12, dim = true, align = Enum.TextXAlignment.Center, order = 2, name = "Status" })
	UIKit.button(bottom, "Save to Captures", {
		order = 1,
		onClick = function()
			if id then
				status.Text = "..."
				save(ctx, id, status)
			end
		end,
	})
end

local function showRoll(ctx: any)
	ctx.clear()
	ctx.view = "roll"
	stopSelfie()
	setFilter(nil)
	ctx.Phone.setViewfinder(false)
	local UIKit = ctx.UIKit
	UIKit.header(ctx.frame, "Photos", function()
		ctx.view = "camera"
		render(ctx)
	end)
	local list = UIKit.scroll(ctx.frame, 44, "Roll")
	list:FindFirstChildOfClass("UIListLayout"):Destroy()
	UIKit.new("UIGridLayout", {
		CellSize = UDim2.fromOffset(84, 112),
		CellPadding = UDim2.fromOffset(6, 6),
		SortOrder = Enum.SortOrder.LayoutOrder,
		Parent = list,
	})
	if #roll == 0 then
		UIKit.empty(list, "No photos yet.")
	end
	for i = #roll, 1, -1 do
		local b = UIKit.new("ImageButton", {
			Name = "Photo",
			LayoutOrder = #roll - i,
			BackgroundColor3 = Color3.new(0, 0, 0),
			Image = roll[i],
			ScaleType = Enum.ScaleType.Crop,
			AutoButtonColor = false,
			Parent = list,
		}, { UIKit.corner(UDim.new(0, 10)) })
		b.Activated:Connect(function()
			showPhoto(ctx, i)
		end)
	end
end

local function showCamera(ctx: any)
	ctx.clear()
	ctx.view = "camera"
	local UIKit, Theme = ctx.UIKit, ctx.Theme
	local C = Theme.Colors
	ctx.Phone.setViewfinder(true)
	setFilter(filterIndex)
	if ctx.selfie then
		startSelfie()
	else
		stopSelfie()
	end

	-- mode switch (top)
	local modes = UIKit.new("Frame", {
		Name = "Modes",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 8),
		Size = UDim2.fromOffset(170, 30),
		BackgroundColor3 = Color3.new(0, 0, 0),
		BackgroundTransparency = 0.45,
		Parent = ctx.frame,
	}, { UIKit.corner(UDim.new(1, 0)), UIKit.list(0, true), UIKit.padding(3) })
	for i, m in { "PHOTO", "SELFIE" } do
		local on = (m == "SELFIE") == (ctx.selfie == true)
		local b = UIKit.new("TextButton", {
			Name = "Mode_" .. m,
			LayoutOrder = i,
			Size = UDim2.new(0.5, 0, 1, 0),
			BackgroundColor3 = C.Text,
			BackgroundTransparency = if on then 0 else 1,
			AutoButtonColor = false,
			FontFace = Theme.Fonts.Bold,
			Text = m,
			TextColor3 = if on then Color3.new(0, 0, 0) else C.Text,
			TextSize = 12,
			Parent = modes,
		}, { UIKit.corner(UDim.new(1, 0)) })
		b.Activated:Connect(function()
			local want = m == "SELFIE"
			if want ~= (ctx.selfie == true) then
				ctx.selfie = want
				showCamera(ctx)
			end
		end)
	end

	-- framing guides (rule of thirds, very faint)
	local guides = UIKit.new("Frame", {
		Name = "Guides",
		Position = UDim2.fromOffset(0, 46),
		Size = UDim2.new(1, 0, 1, -142),
		BackgroundTransparency = 1,
		Parent = ctx.frame,
	})
	for i = 1, 2 do
		UIKit.new("Frame", { Name = "GuideV", Position = UDim2.fromScale(i / 3, 0), Size = UDim2.new(0, 1, 1, 0), BackgroundColor3 = C.Text, BackgroundTransparency = 0.82, BorderSizePixel = 0, Parent = guides })
		UIKit.new("Frame", { Name = "GuideH", Position = UDim2.fromScale(0, i / 3), Size = UDim2.new(1, 0, 0, 1), BackgroundColor3 = C.Text, BackgroundTransparency = 0.82, BorderSizePixel = 0, Parent = guides })
	end

	-- bottom bar: last photo · shutter · flip
	local bar = UIKit.new("Frame", {
		Name = "Controls",
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 1, 0),
		Size = UDim2.new(1, 0, 0, 96),
		BackgroundColor3 = Color3.new(0, 0, 0),
		BackgroundTransparency = 0.35,
		Parent = ctx.frame,
	})
	local thumb = UIKit.new("ImageButton", {
		Name = "Roll",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.18, 0, 0.5, 0),
		Size = UDim2.fromOffset(46, 46),
		BackgroundColor3 = Color3.fromRGB(30, 30, 34),
		Image = roll[#roll] or "",
		ScaleType = Enum.ScaleType.Crop,
		AutoButtonColor = false,
		Parent = bar,
	}, { UIKit.corner(UDim.new(0, 12)), UIKit.stroke(0.3, C.Text) })
	thumb.Activated:Connect(function()
		showRoll(ctx)
	end)
	local shutter = UIKit.new("TextButton", {
		Name = "Shutter",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(66, 66),
		BackgroundColor3 = C.Text,
		AutoButtonColor = false,
		Text = "",
		Parent = bar,
	}, { UIKit.corner(UDim.new(1, 0)), UIKit.new("UIStroke", { Color = Color3.new(0, 0, 0), Thickness = 3, Transparency = 0.2 }) })
	shutter:SetAttribute("MTL_NoTapSound", true)
	shutter.Selectable = false
	local ring = UIKit.new("Frame", {
		Name = "Ring",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(78, 78),
		BackgroundTransparency = 1,
		Parent = bar,
	}, { UIKit.corner(UDim.new(1, 0)), UIKit.new("UIStroke", { Color = C.Text, Thickness = 3 }) })
	ring.ZIndex = shutter.ZIndex - 1
	local sscale = UIKit.new("UIScale", { Parent = shutter })
	shutter.MouseButton1Down:Connect(function()
		ctx.Motion.tween(sscale, ctx.Motion.Fast, { Scale = 0.88 })
	end)
	shutter.MouseButton1Up:Connect(function()
		ctx.Motion.tween(sscale, ctx.Motion.Fast, { Scale = 1 })
	end)
	shutter.Activated:Connect(function()
		ctx.Motion.tween(sscale, ctx.Motion.Fast, { Scale = 1 })
		shoot(ctx)
	end)
	local flip = UIKit.new("TextButton", {
		Name = "Flip",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.82, 0, 0.5, 0),
		Size = UDim2.fromOffset(46, 46),
		BackgroundColor3 = Color3.fromRGB(30, 30, 34),
		AutoButtonColor = false,
		FontFace = Theme.Fonts.Bold,
		Text = "Flip",
		TextColor3 = C.Text,
		TextSize = 12,
		Parent = bar,
	}, { UIKit.corner(UDim.new(1, 0)) })
	flip.Activated:Connect(function()
		ctx.selfie = not ctx.selfie
		showCamera(ctx)
	end)
	-- filter strip (above the controls): tap a name, or step through with Z / X
	local strip = UIKit.new("ScrollingFrame", {
		Name = "Filters",
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, 0, 1, -100),
		Size = UDim2.new(1, 0, 0, 30),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.X,
		ScrollingDirection = Enum.ScrollingDirection.X,
		ScrollBarThickness = 0,
		Parent = ctx.frame,
	}, {
		UIKit.new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 4), VerticalAlignment = Enum.VerticalAlignment.Center }),
		UIKit.new("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }),
	})
	for i, f in FILTERS do
		local on = i == filterIndex
		local b = UIKit.new("TextButton", {
			Name = "Filter_" .. f.name,
			LayoutOrder = i,
			Size = UDim2.fromOffset(0, 24),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundColor3 = if on then C.Gold else Color3.new(0, 0, 0),
			BackgroundTransparency = if on then 0 else 0.45,
			AutoButtonColor = false,
			FontFace = Theme.Fonts.Bold,
			Text = string.upper(f.name),
			TextColor3 = if on then Color3.new(0, 0, 0) else C.Text,
			TextSize = 11,
			Parent = strip,
		}, { UIKit.corner(UDim.new(1, 0)), UIKit.padding(10, 0, 0) })
		b.Activated:Connect(function()
			filterIndex = i
			showCamera(ctx)
		end)
	end
	if filterIndex > 4 then
		task.defer(function()
			strip.CanvasPosition = Vector2.new(math.max(0, strip.AbsoluteCanvasSize.X - strip.AbsoluteWindowSize.X), 0)
		end)
	end
	local hint = UIKit.label(ctx.frame, if UserInputService.TouchEnabled then "" else "Space = photo   Z / X = filter", { size = 11, dim = true, align = Enum.TextXAlignment.Center, name = "Hint" })
	hint.AnchorPoint = Vector2.new(0.5, 1)
	hint.Position = UDim2.new(0.5, 0, 1, -134)
end

render = function(ctx: any)
	if ctx.view == "roll" then
		showRoll(ctx)
	else
		showCamera(ctx)
	end
end

function App.mount(_frame: Frame, ctx: any)
	ctx.view = "camera"
	ctx.selfie = false
	UIState.push("PhoneCamera", { hideHUD = true, hideWaypoints = true })
	-- putting the phone away leaves the camera (camera back to normal, HUD back)
	ctx.track(ctx.Phone.Closed:Connect(function()
		ctx.home()
	end))
	-- Space = shutter while the viewfinder is up
	ctx.track(UserInputService.InputBegan:Connect(function(input, processed)
		if processed or ctx.view ~= "camera" then
			return
		end
		if input.KeyCode == Enum.KeyCode.Space then
			shoot(ctx)
		elseif input.KeyCode == Enum.KeyCode.Z or input.KeyCode == Enum.KeyCode.X then
			-- (not Q/E: E is the interact key and would hop you into cars)
			local dir = if input.KeyCode == Enum.KeyCode.X then 1 else -1
			filterIndex = (filterIndex - 1 + dir) % #FILTERS + 1
			ctx.sfx("PhoneTap")
			showCamera(ctx)
		end
	end))
	render(ctx)
end

function App.unmount(ctx: any)
	stopSelfie()
	setFilter(nil)
	ctx.Phone.setViewfinder(false)
	ctx.Phone.setCaptureHidden(false)
	UIState.pop("PhoneCamera")
end

return App
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Apps", "Goals", "ModuleScript", [======[--!strict
-- Goals app (Piece 4, Master Plan §1 stage 13 FreePlay): "what do I do now?". Unlocks when free play starts.
--   NEXT UP  the top unfinished goal, big, with a progress bar and its one button (Pay $300 / Route to work / Open)
--   GOALS    every other goal: done ones ticked, "Coming soon" ones greyed (kid-safe: nothing fake is sold)
-- Same rules as the server (Rules/GoalRules over the save snapshot), so the list and the HUD line always agree.
-- Buttons: PhoneAction payPower / gpsRoute{place}; opening another app goes through ctx.Phone.open.
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local GoalRules = require(ReplicatedStorage.MTL.Rules.GoalRules)
local Jobs = require(ReplicatedStorage.MTL.Config.Jobs)

local App = { id = "Goals", title = "Goals" }

local function progressBar(UIKit: any, Theme: any, parent: Instance, p: number, order: number, color: Color3?)
	local track = UIKit.new("Frame", {
		Name = "Progress",
		LayoutOrder = order,
		Size = UDim2.new(1, 0, 0, 8),
		BackgroundColor3 = Theme.Phone.CardHover,
		Parent = parent,
	}, { UIKit.corner(UDim.new(1, 0)) })
	UIKit.new("Frame", {
		Name = "Fill",
		Size = UDim2.fromScale(math.clamp(p, 0, 1), 1),
		BackgroundColor3 = color or Theme.Colors.Accent,
		Parent = track,
	}, { UIKit.corner(UDim.new(1, 0)) })
	return track
end

local function doAction(ctx: any, d: any, action: any)
	if type(action) ~= "table" then
		return
	end
	if action.kind == "payPower" then
		ctx.action("payPower", {})
	elseif action.kind == "route" then
		local place = action.place
		if place == "@job" then
			local def = Jobs.Defs[d.Job and d.Job.Current or ""]
			place = def and def.place
		end
		if place then
			ctx.action("gpsRoute", { place = place })
			ctx.close()
		end
	elseif action.kind == "app" and action.app then
		ctx.Phone.open(action.app)
	end
end

local function render(ctx: any, d: any)
	ctx.clear()
	local UIKit, Theme = ctx.UIKit, ctx.Theme
	local C = Theme.Colors
	UIKit.header(ctx.frame, "Goals")
	local list = UIKit.scroll(ctx.frame, 44, "Goals")
	local entries = GoalRules.evaluate(d)
	local top = GoalRules.top(d)
	local order = 0
	local function nextOrder(): number
		order += 1
		return order
	end

	if top then
		UIKit.section(list, "NEXT UP", nextOrder())
		local card = UIKit.card(list, nextOrder(), "Top")
		UIKit.stroke(0, C.Gold).Parent = card
		UIKit.label(card, top.title, { size = 18, bold = true, wrap = true, name = "Title", order = 1 })
		UIKit.label(card, top.sub or "", { size = 12, dim = true, wrap = true, name = "Sub", order = 2 })
		progressBar(UIKit, Theme, card, top.progress, 3, C.Gold)
		UIKit.label(card, top.progressText .. (if top.reward > 0 then ("   ·   +" .. top.reward .. " XP") else ""), { size = 12, color = C.Gold, name = "ProgressText", order = 4 })
		if top.action then
			-- always pressable: the server checks the cash and answers with a toast ("You need $80 more...")
			UIKit.button(card, top.action.label or "Go", {
				style = "primary",
				name = "Action",
				order = 10,
				onClick = function()
					doAction(ctx, d, top.action)
				end,
			})
		end
	else
		UIKit.section(list, "NEXT UP", nextOrder())
		UIKit.empty(list, "You've done every goal there is for now. More come with every update.", nextOrder())
	end

	UIKit.section(list, "GOALS", nextOrder())
	for _, e in entries do
		if top and e.id == top.id then
			continue
		end
		local card = UIKit.card(list, nextOrder(), "Goal_" .. e.id)
		UIKit.label(card, (if e.done then "DONE  ·  " else "") .. e.title, {
			size = 15,
			bold = true,
			wrap = true,
			color = if e.done then C.Accent elseif e.soon then C.TextDim else C.Text,
			name = "Title",
			order = 1,
		})
		UIKit.label(card, if e.soon then ("Coming soon. " .. (e.sub or "")) else (e.sub or ""), { size = 12, dim = true, wrap = true, name = "Sub", order = 2 })
		if not e.soon and not e.done then
			progressBar(UIKit, Theme, card, e.progress, 3)
			UIKit.label(card, e.progressText, { size = 11, dim = true, name = "ProgressText", order = 4 })
		end
		if e.soon then
			card.BackgroundTransparency = 0.4
		end
	end
end

function App.mount(frame: Frame, ctx: any)
	local last = ""
	ctx.onData(function(d)
		if not d or not frame.Parent then
			return
		end
		-- re-render only when something a goal reads changed
		local claimed = 0
		for _ in (d.Goals and d.Goals.Done) or {} do
			claimed += 1
		end
		local key = table.concat({
			tostring(d.Cash),
			tostring(d.Level),
			tostring(d.Path),
			tostring(d.Home and d.Home.PowerOn),
			tostring(d.Job and d.Job.Current),
			tostring(d.Job and d.Job.Current and d.Job.Shifts and d.Job.Shifts[d.Job.Current]),
			tostring(claimed),
		}, "|")
		if key ~= last then
			last = key
			render(ctx, d)
		end
	end)
end

return App
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Apps", "Jobs", "ModuleScript", [======[--!strict
-- Jobs app (Piece 2). Three blocks, top to bottom:
--   1. YOUR JOB   what you do, where, this shift's progress, one big button that's always the right next step
--                 (Route to work -> Clock in -> End shift)
--   2. 2x XP      pass / 30-minute boost (kid-safe: Roblox's own prompt shows the price, no timers, "Coming soon"
--                 while the ids are 0, a clear "owned" state). Shown from stage TheCall on, never on a first join.
--   3. FIND WORK  every job you can see at this story stage: pay per minute, XP per minute, how hands-on it is,
--                 distance, CHOOSE / Route. Locked jobs show the level they open at.
-- Story funnel screens (Piece 4), nothing else on screen while they're up:
--   ChooseJob  (stage 10) "STEP 1 OF 2 · Pick your job": 3 big cards (the Food Mart you robbed, the mechanic, the
--              restaurant): photo slot, one story line, pay/min, how hands-on, distance from home, one CHOOSE button.
--              CHOOSE -> a confirm screen ("Work at Westside Auto Repair?") -> chooseJob{job}.
--   FirstNight (stage 11) "You're hired" + "STEP 2 OF 2 · Get some sleep" + one button that puts the phone away.
-- Before ChooseJob the only job listed is the Food Mart (the story job).
-- Buttons: PhoneAction chooseJob{job} / gpsRoute{place} / buy{item}; JobAction clockIn / clockOut.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Jobs = require(ReplicatedStorage.MTL.Config.Jobs)
local Locations = require(ReplicatedStorage.MTL.Config.Locations)
local Property = require(ReplicatedStorage.MTL.Config.Property)
local Story = require(ReplicatedStorage.MTL.Config.Story)
local UserInputService = game:GetService("UserInputService")
local JobRules = require(ReplicatedStorage.MTL.Rules.JobRules)
local StoryRules = require(ReplicatedStorage.MTL.Rules.StoryRules)
local Motion = require(ReplicatedStorage.MTL.UI.Motion)

local App = { id = "Jobs", title = "Jobs" }

local player = Players.LocalPlayer

local function jobController(): any?
	local controllers = script.Parent.Parent:FindFirstChild("Controllers")
	local m = controllers and controllers:FindFirstChild("JobController")
	if not m then
		return nil
	end
	local ok, jc = pcall(require, m)
	return if ok then jc else nil
end

local function myRoot(): BasePart?
	local char = player.Character
	return char and char:FindFirstChild("HumanoidRootPart") :: BasePart?
end

-- Where distances are measured from: you, or your front door while you're inside your home (rooms are far away).
local function origin(): Vector3?
	local homeId = player:GetAttribute("MTL_InHome")
	local h = type(homeId) == "string" and (Property.Homes :: any)[homeId]
	local loc = h and (Locations :: any)[h.location]
	if loc and loc.Door then
		return loc.Door
	end
	local r = myRoot()
	return r and r.Position
end

local function homeDoor(): Vector3?
	local h = (Property.Homes :: any)[Property.StarterHome]
	local loc = h and (Locations :: any)[h.location]
	return loc and loc.Door
end

local function distance(jobId: string, js: any): number?
	local from = origin()
	if not from then
		return nil
	end
	-- the server's site position is the truth (it may come from the map's JobSpot); config is the fallback
	local pos: Vector3? = nil
	if js and js.job == jobId and js.site then
		pos = js.site.pos
	else
		local def = Jobs.Defs[jobId]
		local loc = def and Locations[def.site] :: any
		pos = loc and (loc.Inside or loc.Door)
	end
	return if pos then (from - pos).Magnitude else nil
end

local function sitePos(jobId: string): Vector3?
	local def = Jobs.Defs[jobId]
	local loc = def and Locations[def.site] :: any
	return loc and (loc.Door or loc.Inside)
end

local function keyHint(): string
	if UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
		return "tap Sleep"
	elseif UserInputService.GamepadEnabled and not UserInputService.KeyboardEnabled then
		return "press X to Sleep"
	end
	return "press E to Sleep"
end

---------------------------------------------------------------- story funnel screens (Piece 4)

local JOB_COLORS = {
	Supermarket = Color3.fromRGB(64, 160, 110),
	Mechanic = Color3.fromRGB(70, 110, 190),
	Restaurant = Color3.fromRGB(200, 96, 60),
}

local function step(ctx: any, parent: Instance, text: string, order: number)
	ctx.UIKit.label(parent, text, { size = 11, bold = true, color = ctx.Theme.Colors.Gold, order = order, name = "Step" })
end

-- STEP 1 OF 2: three big cards, one CHOOSE each. `ctx.pick` = the job waiting for "Yes, I'll take it".
local function renderChoose(ctx: any, d: any, js: any, rerender: () -> ())
	ctx.clear()
	local UIKit, Theme, Format = ctx.UIKit, ctx.Theme, ctx.Format
	local C = Theme.Colors
	local level = d.Level or 1
	local pick = ctx.pick
	if pick and Jobs.Defs[pick] then
		-- confirm
		local def = Jobs.Defs[pick]
		UIKit.header(ctx.frame, "Jobs", function()
			ctx.pick = nil
			rerender()
		end)
		local list = UIKit.scroll(ctx.frame, 44, "Confirm")
		step(ctx, list, "STEP 1 OF 2  ·  PICK YOUR JOB", 1)
		UIKit.label(list, "Work at " .. def.title .. "?", { size = 20, bold = true, wrap = true, order = 2, name = "Question" })
		local card = UIKit.card(list, 3, "ConfirmCard")
		UIKit.stroke(0, JOB_COLORS[pick] or C.Accent).Parent = card
		UIKit.label(card, def.role, { size = 17, bold = true, order = 1, name = "Role" })
		UIKit.label(card, def.blurb or "", { size = 13, dim = true, wrap = true, order = 2 })
		local cash, xp = JobRules.perMinute(pick, level)
		UIKit.label(card, string.format("~%s/min  ·  ~%d XP/min", Format.cash(cash), xp), { size = 13, color = C.Accent, order = 3 })
		local boss = def.boss and Story.Contacts[def.boss]
		UIKit.label(card, "First shift: tomorrow morning." .. (if boss then (" Your boss: " .. boss.Name .. ".") else ""), { size = 13, wrap = true, order = 4 })
		local waiting = ctx.sent == pick
		local yes = UIKit.button(list, if waiting then "Signing you up..." else "Yes, I'll take it", {
			style = "primary",
			name = "Confirm",
			order = 5,
			height = 48,
			disabled = waiting,
			onClick = function()
				ctx.sent = pick
				ctx.action("chooseJob", { job = pick })
				rerender()
				task.delay(4, function()
					if ctx.sent == pick and ctx.frame.Parent then
						ctx.sent = nil -- the server said no (a toast explains); let them try again
						rerender()
					end
				end)
			end,
		})
		yes.Name = "Confirm"
		UIKit.button(list, "Back", {
			style = "secondary",
			name = "Back",
			order = 6,
			onClick = function()
				ctx.pick = nil
				ctx.sent = nil
				rerender()
			end,
		})
		UIKit.label(list, "You can switch jobs any time in this app.", { size = 12, dim = true, wrap = true, order = 7 })
		return
	end

	UIKit.header(ctx.frame, "Jobs")
	local list = UIKit.scroll(ctx.frame, 44, "Choose")
	step(ctx, list, "STEP 1 OF 2  ·  PICK YOUR JOB", 1)
	UIKit.label(list, "Pick your job", { size = 22, bold = true, order = 2, name = "Title" })
	UIKit.label(list, "Three places are hiring. You start tomorrow morning.", { size = 13, dim = true, wrap = true, order = 3 })
	local home = homeDoor()
	local cards = {}
	for i, id in Jobs.StarterJobs do
		local def = Jobs.Defs[id]
		if not def then
			continue
		end
		local card = UIKit.card(list, 10 + i, "Job_" .. id)
		-- photo band. TODO(Alex art): a job photo (ImageLabel "Photo"); until then a coloured band + the role
		local band = UIKit.new("Frame", {
			Name = "Band",
			LayoutOrder = 0,
			Size = UDim2.new(1, 0, 0, 56),
			BackgroundColor3 = JOB_COLORS[id] or C.Accent,
			ClipsDescendants = true,
			Parent = card,
		}, { UIKit.corner(Theme.CornerSmall) })
		UIKit.new("ImageLabel", { Name = "Photo", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Image = "rbxassetid://0", ScaleType = Enum.ScaleType.Crop, Parent = band })
		UIKit.new("TextLabel", {
			Name = "BandText",
			Position = UDim2.fromOffset(12, 0),
			Size = UDim2.new(1, -24, 1, 0),
			BackgroundTransparency = 1,
			FontFace = Theme.Fonts.Display,
			Text = string.upper(def.role),
			TextColor3 = C.Text,
			TextSize = 22,
			TextXAlignment = Enum.TextXAlignment.Left,
			Parent = band,
		})
		UIKit.label(card, def.title, { size = 16, bold = true, name = "Place", order = 1 })
		local hook = (Property.JobHooks :: any)[id]
		if hook then
			UIKit.label(card, hook, { size = 12, wrap = true, name = "Hook", order = 2 })
		end
		local cash = JobRules.perMinute(id, level)
		local site = sitePos(id)
		local distText = if home and site then ("  ·  " .. Format.distance((home - site).Magnitude) .. " from home") else ""
		UIKit.label(card, string.format("~%s/min  ·  %s", Format.cash(cash), JobRules.tierLabel(def.tier)) .. distText, { size = 12, color = C.Accent, name = "Pay", order = 3 })
		local choose = UIKit.button(card, "CHOOSE", {
			style = "primary",
			name = "Choose",
			order = 10,
			height = 44,
			onClick = function()
				ctx.pick = id
				rerender()
			end,
		})
		choose.Name = "Choose"
		table.insert(cards, card)
	end
	-- the story asks for a choice: pulse the cards once, gently
	if not (d.Settings and d.Settings.ReducedMotion) and not ctx.pulsed then
		ctx.pulsed = true
		for i, card in cards do
			local s = UIKit.new("UIScale", { Parent = card })
			task.delay(0.2 + 0.15 * i, function()
				Motion.tween(s, Motion.Fast, { Scale = 1.03 }).Completed:Wait()
				Motion.tween(s, Motion.Normal, { Scale = 1 })
			end)
		end
	end
end

-- STEP 2 OF 2: hired, now sleep.
local function renderHired(ctx: any, d: any)
	ctx.clear()
	local UIKit, Theme = ctx.UIKit, ctx.Theme
	local C = Theme.Colors
	UIKit.header(ctx.frame, "Jobs")
	local list = UIKit.scroll(ctx.frame, 44, "Hired")
	local def = JobRules.def(d.Job and d.Job.Current or "")
	local badge = UIKit.new("TextLabel", {
		Name = "HiredBadge",
		LayoutOrder = 1,
		Size = UDim2.new(1, 0, 0, 64),
		BackgroundColor3 = C.Accent,
		FontFace = Theme.Fonts.Display,
		Text = "YOU'RE HIRED",
		TextColor3 = C.Glass,
		TextSize = 24,
		Parent = list,
	}, { UIKit.corner(Theme.Corner) })
	badge.Name = "HiredBadge"
	if def then
		UIKit.label(list, def.role .. " at " .. def.title, { size = 17, bold = true, wrap = true, order = 2, name = "Job" })
		local boss = def.boss and Story.Contacts[def.boss]
		UIKit.label(list, "First shift: tomorrow morning." .. (if boss then (" " .. boss.Name .. " will text you when you wake up.") else ""), { size = 13, dim = true, wrap = true, order = 3 })
	end
	step(ctx, list, "STEP 2 OF 2  ·  GET SOME SLEEP", 4)
	UIKit.label(list, "Your bed is glowing. Walk over and " .. keyHint() .. ".", { size = 15, wrap = true, order = 5, name = "Next" })
	UIKit.button(list, "Put the phone away", {
		style = "primary",
		name = "Close",
		order = 6,
		height = 46,
		onClick = function()
			ctx.close()
		end,
	})
end

local function buttonRow(UIKit: any, parent: Instance, order: number): Frame
	return UIKit.new("Frame", {
		Name = "Buttons",
		LayoutOrder = order,
		Size = UDim2.new(1, 0, 0, 40),
		BackgroundTransparency = 1,
		Parent = parent,
	}, { UIKit.list(8, true) })
end

local function render(ctx: any, d: any, js: any)
	-- story funnel screens (Piece 4) take the whole app
	if d.Story.Stage == Jobs.ChooseFromStage then
		renderChoose(ctx, d, js, function()
			render(ctx, ctx.data() or d, js)
		end)
		return
	elseif d.Story.Stage == "FirstNight" then
		renderHired(ctx, d)
		return
	end
	ctx.clear()
	local UIKit, Theme, Format = ctx.UIKit, ctx.Theme, ctx.Format
	local C = Theme.Colors
	UIKit.header(ctx.frame, "Jobs")
	local list = UIKit.scroll(ctx.frame, 44, "Jobs")
	local stage = d.Story.Stage
	local level = d.Level or 1
	local current = d.Job and d.Job.Current or ""
	local choosing = stage == Jobs.ChooseFromStage
	local order = 0
	local function nextOrder(): number
		order += 1
		return order
	end
	local function jc(kind: string)
		local controller = jobController()
		if controller then
			controller.action(kind)
		end
	end

	---------------------------------------------------------------- 1. your job
	local mine = JobRules.def(current)
	if mine and not choosing then
		UIKit.section(list, "YOUR JOB", nextOrder())
		local card = UIKit.card(list, nextOrder(), "MyJob")
		UIKit.stroke(0, C.Accent).Parent = card
		-- TODO(Alex art): job photo / logo at the top of the card
		UIKit.label(card, mine.role, { size = 17, bold = true, name = "Role", order = 1 })
		UIKit.label(card, mine.title, { dim = true, name = "Place", order = 2 })
		local onShift = js ~= nil and js.onShift == true and js.job == current
		local dist = distance(current, js)
		local statusText
		if onShift and js.shift then
			statusText = if js.shift.complete then "Shift complete"
				else string.format("On shift  ·  %d / %d  ·  %s", js.shift.done, js.shift.total, Format.cash(js.shift.earned))
		else
			statusText = "Off the clock" .. (if dist then ("  ·  " .. Format.distance(dist) .. " away") else "")
		end
		UIKit.label(card, statusText, { size = 12, color = if onShift then C.Accent else C.TextDim, name = "Status", order = 3 })
		local storyShift = stage == "FirstShift"
		if storyShift then
			UIKit.label(card, "Mr. Patel's counting on you. Keep working your shift.", { size = 12, dim = true, wrap = true, order = 4 })
		end
		local buttons = buttonRow(UIKit, card, 10)
		local nearWork = (dist or math.huge) <= Jobs.Validation.ClockInRadius
		local primaryText: string, style: string, onClick: () -> ()
		if onShift then
			primaryText, style, onClick = "End shift", "secondary", function()
				jc("clockOut")
			end
		elseif nearWork then
			primaryText, style, onClick = "Clock in", "primary", function()
				jc("clockIn")
				ctx.close()
			end
		else
			primaryText, style, onClick = "Route to work", "primary", function()
				ctx.action("gpsRoute", { place = mine.place })
				ctx.close()
			end
		end
		local primary = UIKit.button(buttons, primaryText, { style = style, name = "Primary", onClick = onClick })
		primary.Size = UDim2.new(1, 0, 1, 0)
		buttons.Visible = not (storyShift and onShift) -- the story shift: nothing to press, just work
	end

	---------------------------------------------------------------- 2. 2x XP
	if StoryRules.reached(stage, "TheCall") then
		UIKit.section(list, "LEVEL UP FASTER", nextOrder())
		local card = UIKit.card(list, nextOrder(), "Boost")
		local ownsPass = player:GetAttribute("MTL_Pass_XP2x") == true
		local boostLeft = (d.Boosts and d.Boosts.XP2xSeconds) or 0
		if ownsPass then
			UIKit.label(card, "2x XP pass: owned", { bold = true, color = C.Accent, order = 1 })
			UIKit.label(card, "Every job gives double XP. Forever.", { size = 12, dim = true, wrap = true, order = 2 })
		else
			UIKit.label(card, "2x XP", { size = 17, bold = true, order = 1 })
			UIKit.label(card, "Double XP on every job. The pass is forever. The boost is 30 minutes of play time and stacks.", { size = 12, dim = true, wrap = true, order = 2 })
		end
		if boostLeft > 0 then
			UIKit.label(card, string.format("Boost on: %d min of play time left", math.ceil(boostLeft / 60)), { size = 12, color = C.AccentAlt, order = 3 })
		end
		local buttons = buttonRow(UIKit, card, 10)
		if not ownsPass then
			local pass = UIKit.button(buttons, "2x XP forever", {
				style = "primary",
				name = "BuyPass",
				onClick = function()
					ctx.action("buy", { item = "XP2x" })
				end,
			})
			pass.Size = UDim2.new(0.5, -4, 1, 0)
		end
		local boost = UIKit.button(buttons, "30 min boost", {
			style = "secondary",
			name = "BuyBoost",
			onClick = function()
				ctx.action("buy", { item = "XPBoost" })
			end,
		})
		boost.Size = if ownsPass then UDim2.new(1, 0, 1, 0) else UDim2.new(0.5, -4, 1, 0)
	end

	---------------------------------------------------------------- 3. find work
	local visible = JobRules.visibleJobs(stage)
	UIKit.section(list, if choosing then "PICK YOUR JOB" elseif #visible == 1 then "HIRING" else "FIND WORK", nextOrder())
	if choosing then
		UIKit.label(list, "Pick where you work. You can switch later in this app.", { wrap = true, order = nextOrder(), dim = true })
	elseif not StoryRules.reached(stage, Jobs.ChooseFromStage) then
		UIKit.label(list, "More jobs open up once you've got your own place.", { wrap = true, order = nextOrder(), dim = true, size = 12 })
	end
	local cards = {}
	local tier = 1
	for _, id in visible do
		local def = Jobs.Defs[id]
		local isMine = id == current
		if isMine and not choosing then
			continue -- already shown in YOUR JOB
		end
		if not choosing and def.tier ~= tier then
			tier = def.tier
			UIKit.label(list, if tier == 2 then "LEVEL 8+  ·  LAID BACK" else "LEVEL 15+  ·  AFK-FRIENDLY", { size = 11, bold = true, dim = true, order = nextOrder() })
		end
		local locked = level < def.level
		local card = UIKit.card(list, nextOrder(), "Job_" .. id)
		if isMine then
			UIKit.stroke(0, C.Accent).Parent = card
		end
		-- TODO(Alex art): job photo at the top of the card
		UIKit.label(card, def.role .. "  ·  " .. def.title, { size = 15, bold = true, name = "Title", order = 1 })
		UIKit.label(card, def.blurb or "", { size = 12, dim = true, wrap = true, name = "Blurb", order = 2 })
		local cash, xp = JobRules.perMinute(id, level)
		local info = string.format("~%s/min  ·  ~%d XP/min  ·  %s", Format.cash(cash), xp, JobRules.tierLabel(def.tier))
		UIKit.label(card, info, { size = 12, color = if locked then C.TextDim else C.Accent, name = "Pay", order = 3 })
		local dist = distance(id, js)
		if dist then
			UIKit.label(card, Format.distance(dist) .. " away", { size = 11, dim = true, name = "Distance", order = 4 })
		end
		local buttons = buttonRow(UIKit, card, 10)
		local canPick = JobRules.canChoose(id, level, stage)
		local chooseText = if isMine then "YOUR JOB" elseif locked then ("LEVEL " .. def.level) elseif not canPick then "SOON" else "CHOOSE"
		local choose = UIKit.button(buttons, chooseText, {
			style = "primary",
			disabled = isMine or locked or not canPick,
			name = "Choose",
			onClick = function()
				ctx.action("chooseJob", { job = id })
			end,
		})
		choose.Size = UDim2.new(0.62, -4, 1, 0)
		local route = UIKit.button(buttons, "Route", {
			style = "secondary",
			name = "Route",
			disabled = def.place == nil,
			onClick = function()
				ctx.action("gpsRoute", { place = def.place })
			end,
		})
		route.Size = UDim2.new(0.38, -4, 1, 0)
		table.insert(cards, card)
	end

	-- the story asks for a choice: pulse the cards once, gently
	if choosing and not (d.Settings and d.Settings.ReducedMotion) then
		for i, card in cards do
			local s = UIKit.new("UIScale", { Parent = card })
			task.delay(0.15 * i, function()
				Motion.tween(s, Motion.Fast, { Scale = 1.03 }).Completed:Wait()
				Motion.tween(s, Motion.Normal, { Scale = 1 })
			end)
		end
	end
end

function App.mount(frame: Frame, ctx: any)
	local lastKey = ""
	local controller = jobController()
	local function refresh()
		local d = ctx.data()
		if not d or not frame.Parent then
			return
		end
		local js = controller and controller.state()
		local shiftKey = if js and js.onShift and js.shift then (tostring(js.shift.done) .. "/" .. tostring(js.shift.complete)) else "off"
		local k = table.concat({
			tostring(d.Story.Stage),
			tostring(d.Level),
			tostring(d.Job and d.Job.Current),
			shiftKey,
			tostring(math.ceil(((d.Boosts and d.Boosts.XP2xSeconds) or 0) / 60)),
			tostring(player:GetAttribute("MTL_Pass_XP2x")),
		}, "|")
		if k ~= lastKey then
			lastKey = k
			render(ctx, d, js)
		end
	end
	ctx.onData(function()
		refresh()
	end)
	if controller and controller.Changed then
		ctx.track(controller.Changed:Connect(refresh))
	end
	ctx.track(player:GetAttributeChangedSignal("MTL_Pass_XP2x"):Connect(refresh))
end

return App
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Apps", "Map", "ModuleScript", [======[--!strict
-- GPS: a small north-up map (places + you), and the list of places with live distances. "Route" asks the server
-- to set the GPS waypoint (marker + ground breadcrumbs from WayfindingController); the server checks the place.
-- The map is a placeholder plot until Alex sends a map image (TODO(Alex art): Theme.Phone.MapImage + world bounds).
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Locations = require(ReplicatedStorage.MTL.Config.Locations)

local App = { id = "Map", title = "GPS" }

local MAP_H = 190

local function root(): BasePart?
	local char = Players.LocalPlayer.Character
	return char and char:FindFirstChild("HumanoidRootPart") :: BasePart?
end

local function visiblePlaces(ctx: any, d: any): { any }
	local out = {}
	local ownsHome = d.Home and d.Home.Owned and next(d.Home.Owned) ~= nil
	for _, place in ctx.Config.Places do
		if ctx.Rules.placeVisible(place, d.Story.Stage, ownsHome == true) then
			local pos = ctx.Rules.placePosition(place, Locations)
			if pos then
				table.insert(out, { place = place, pos = pos })
			end
		end
	end
	return out
end

local function build(ctx: any, d: any)
	ctx.clear()
	local UIKit, Theme, Format = ctx.UIKit, ctx.Theme, ctx.Format
	local C, P = Theme.Colors, Theme.Phone
	UIKit.header(ctx.frame, "GPS")
	local list = UIKit.scroll(ctx.frame, 44, "Places")

	local places = visiblePlaces(ctx, d)

	-- map plot
	local map = UIKit.new("Frame", {
		Name = "MapView",
		LayoutOrder = 0,
		Size = UDim2.new(1, 0, 0, MAP_H),
		BackgroundColor3 = P.Card,
		ClipsDescendants = true,
		Parent = list,
	}, { UIKit.corner(Theme.Corner) })
	UIKit.label(map, "N", { size = 11, dim = true, bold = true, align = Enum.TextXAlignment.Center }).Size = UDim2.new(1, 0, 0, 16)

	local r = root()
	local minX, maxX, minZ, maxZ = math.huge, -math.huge, math.huge, -math.huge
	local function grow(v: Vector3)
		minX, maxX = math.min(minX, v.X), math.max(maxX, v.X)
		minZ, maxZ = math.min(minZ, v.Z), math.max(maxZ, v.Z)
	end
	for _, p in places do
		grow(p.pos)
	end
	if r then
		grow(r.Position)
	end
	if minX == math.huge then
		minX, maxX, minZ, maxZ = -100, 100, -100, 100
	end
	local pad = 80
	minX -= pad
	maxX += pad
	minZ -= pad
	maxZ += pad
	local span = math.max(maxX - minX, maxZ - minZ)
	local cx, cz = (minX + maxX) / 2, (minZ + maxZ) / 2
	local function toMap(v: Vector3): UDim2
		-- uniform scale, north (-Z) up; the frame is wider than tall so fit to height
		local u = (v.X - cx) / span
		local w = (v.Z - cz) / span
		return UDim2.new(0.5, u * MAP_H, 0.5, w * MAP_H)
	end

	local active = Players.LocalPlayer:GetAttribute("MTL_GPS")
	for _, p in places do
		local on = p.place.id == active
		local dot = UIKit.new("Frame", {
			Name = "Dot_" .. p.place.id,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = toMap(p.pos),
			Size = UDim2.fromOffset(if on then 14 else 10, if on then 14 else 10),
			BackgroundColor3 = if on then C.Accent elseif p.place.category == "Home" then C.Gold else C.AccentAlt,
			Parent = map,
		}, { UIKit.corner(UDim.new(1, 0)), UIKit.stroke(0.2, P.Card) })
		local lbl = UIKit.label(dot, p.place.label, { size = 10, align = Enum.TextXAlignment.Center })
		lbl.AnchorPoint = Vector2.new(0.5, 0)
		lbl.Position = UDim2.new(0.5, 0, 1, 1)
		lbl.Size = UDim2.fromOffset(110, 12)
	end
	local me = UIKit.new("TextLabel", {
		Name = "You",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Size = UDim2.fromOffset(16, 16),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Display,
		Text = "▲",
		TextColor3 = C.Text,
		TextSize = 14,
		ZIndex = 3,
		Visible = r ~= nil,
		Parent = map,
	}, { UIKit.new("UIStroke", { Color = C.Shadow, Thickness = 1.5, Transparency = 0.3 }) })

	-- route controls
	if active then
		UIKit.button(list, "Clear route", {
			style = "secondary",
			order = 1,
			onClick = function()
				ctx.action("gpsClear")
			end,
		})
	end
	UIKit.section(list, "Places", 2)
	local distLabels: { [string]: TextLabel } = {}
	for i, p in places do
		local on = p.place.id == active
		local row = UIKit.row(list, {
			title = p.place.label,
			sub = p.place.category,
			right = if on then "On route" else "Route",
			rightColor = if on then C.Accent else C.Text,
			glyph = string.sub(p.place.label, 1, 1),
			glyphColor = if p.place.category == "Home" then C.Gold else C.AccentAlt,
			order = 2 + i,
			onClick = function()
				if not on then
					ctx.action("gpsRoute", { place = p.place.id })
				end
			end,
		})
		distLabels[p.place.id] = row:FindFirstChild("Sub") :: TextLabel
	end
	if #places == 0 then
		UIKit.empty(list, "Nowhere to go yet.", 3)
	end

	-- live: your dot and the distances
	local token = {}
	ctx.liveToken = token
	task.spawn(function()
		while ctx.liveToken == token and ctx.frame.Parent do
			local rp = root()
			if rp then
				me.Visible = true
				me.Position = toMap(rp.Position)
				local look = rp.CFrame.LookVector
				me.Rotation = math.deg(math.atan2(look.X, -look.Z))
				for _, p in places do
					local l = distLabels[p.place.id]
					if l then
						l.Text = p.place.category .. "  ·  " .. Format.distance((rp.Position - p.pos).Magnitude)
					end
				end
			end
			task.wait(0.25)
		end
	end)
end

function App.mount(_frame: Frame, ctx: any)
	local lastKey = ""
	local function key(d: any): string
		local owned = d.Home and d.Home.Owned and next(d.Home.Owned) ~= nil
		return tostring(d.Story.Stage) .. "|" .. tostring(owned) .. "|" .. tostring(Players.LocalPlayer:GetAttribute("MTL_GPS"))
	end
	ctx.onData(function(d: any)
		local k = key(d)
		if k ~= lastKey then
			lastKey = k
			build(ctx, d)
		end
	end)
	ctx.track(Players.LocalPlayer:GetAttributeChangedSignal("MTL_GPS"):Connect(function()
		local d = ctx.data()
		if d then
			lastKey = key(d)
			build(ctx, d)
		end
	end))
end

function App.unmount(ctx: any)
	ctx.liveToken = nil
end

return App
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Apps", "Messages", "ModuleScript", [======[--!strict
-- Messages: conversation list -> conversation, laid out like a real phone's messaging app (big title, avatar
-- rows, grouped bubbles with a sharp "tail" corner, time separators, Delivered, typing dots, a compose bar with
-- suggestion chips). Texts come from the save snapshot (data.Phone.Texts); opening a thread marks it read.
-- Messages with a link show a button under the bubble (e.g. "Set route").
-- Open straight into a thread: Phone.open("Messages", { contact = "Patel" }).
-- Sending: the player picks a suggestion (Config/Phone.QuickReplies). It types into the compose field, then Send
-- posts it (server action "quickReply" checks the index). The contact may answer after a "typing" pause.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TextService = game:GetService("TextService")
local TweenService = game:GetService("TweenService")

-- shared low-poly look (HUD thread's module); the app still works if it isn't there
local okLP, LowPoly = pcall(function()
	return require(ReplicatedStorage.MTL.UI.LowPoly) :: any
end)
if not okLP then
	LowPoly = nil
end

local App = { id = "Messages", title = "Messages" }

local BUBBLE_MAX = 196
local TEXT_SIZE = 14
local GROUP_GAP = 2 -- between bubbles from the same person
local BLOCK_GAP = 10 -- when the sender changes
local TIME_GAP = 15 * 60 -- show a time separator after this much silence
local COMPOSE_H = 46
local CHIPS_H = 38

local sizeCache: { [string]: Vector2 } = {}

-- avatar colours (deterministic per contact)
local AVATAR = {
	Color3.fromRGB(86, 120, 220),
	Color3.fromRGB(220, 110, 70),
	Color3.fromRGB(70, 170, 120),
	Color3.fromRGB(170, 90, 200),
	Color3.fromRGB(210, 160, 60),
	Color3.fromRGB(60, 160, 190),
}

local function name(ctx: any, id: string): string
	if id == "Unknown" then
		return "Unknown number"
	end
	local c = ctx.Story.Contacts[id]
	return if c then c.Name else id
end

local function avatarColor(id: string): Color3
	if id == "Unknown" then
		return Color3.fromRGB(90, 94, 106)
	end
	local h = 0
	for i = 1, #id do
		h += string.byte(id, i) * i
	end
	return AVATAR[h % #AVATAR + 1]
end

local function initial(ctx: any, id: string): string
	return if id == "Unknown" then "?" else string.upper(string.sub(name(ctx, id), 1, 1))
end

local function clock(t: number): string
	local s = os.date("%I:%M %p", t)
	return (string.gsub(s, "^0", ""))
end

local function dayLabel(t: number): string
	local now = os.time()
	local d, today = os.date("*t", t), os.date("*t", now)
	if d.year == today.year and d.yday == today.yday then
		return "Today " .. clock(t)
	end
	local y = os.date("*t", now - 86400)
	if d.year == y.year and d.yday == y.yday then
		return "Yesterday " .. clock(t)
	end
	return os.date("%a %b %d", t) .. " " .. clock(t)
end

local function textSize(ctx: any, text: string): Vector2
	local cached = sizeCache[text]
	if cached then
		return cached
	end
	local ok, bounds = pcall(function()
		local params = Instance.new("GetTextBoundsParams")
		params.Text = text
		params.Font = ctx.Theme.Fonts.Body
		params.Size = TEXT_SIZE
		params.Width = BUBBLE_MAX - 32
		return TextService:GetTextBoundsAsync(params)
	end)
	local v = if ok and bounds then bounds else Vector2.new(math.min(BUBBLE_MAX - 32, #text * 7.5), TEXT_SIZE + 4)
	sizeCache[text] = v
	return v
end

local function avatar(ctx: any, parent: Instance, id: string, size: number, props: { [string]: any }?): Frame
	-- a Frame (shaded) with the letter as a separate label, so the shading never tints the letter
	local UIKit = ctx.UIKit
	local a = UIKit.new("Frame", {
		Name = "Avatar",
		Size = UDim2.fromOffset(size, size),
		BackgroundColor3 = avatarColor(id),
		Parent = parent,
	}, {
		UIKit.corner(UDim.new(1, 0)),
		-- soft top-lit shading, like a contact photo placeholder
		UIKit.new("UIGradient", { Rotation = 90, Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(190, 190, 196)) }),
	})
	if LowPoly and ctx.Theme.Phone.LowPoly then
		LowPoly.style(a, avatarColor(id), { outline = 2, corner = UDim.new(0, 4), rim = false })
	end
	UIKit.new("TextLabel", {
		Name = "Letter",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		FontFace = ctx.Theme.Fonts.Display,
		Text = initial(ctx, id),
		TextColor3 = Color3.new(1, 1, 1),
		TextSize = math.floor(size * 0.45),
		ZIndex = a.ZIndex,
		Parent = a,
	})
	for k, v in props or {} do
		(a :: any)[k] = v
	end
	local letter = a:FindFirstChild("Letter") :: TextLabel
	letter.ZIndex = a.ZIndex
	return a
end

---------------------------------------------------------------- conversation

local function bubble(ctx: any, parent: Instance, msg: any, order: number, contact: string, index: number, tail: boolean, gapAfter: number): Frame
	local UIKit, Theme = ctx.UIKit, ctx.Theme
	local P = Theme.Phone
	local me = msg.me == true
	local holder = UIKit.new("Frame", {
		Name = "Message",
		LayoutOrder = order,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Parent = parent,
	}, {
		UIKit.new("UIListLayout", {
			HorizontalAlignment = if me then Enum.HorizontalAlignment.Right else Enum.HorizontalAlignment.Left,
			Padding = UDim.new(0, 4),
			SortOrder = Enum.SortOrder.LayoutOrder,
		}),
		UIKit.new("UIPadding", {
			PaddingLeft = UDim.new(0, 10),
			PaddingRight = UDim.new(0, 10),
			PaddingBottom = UDim.new(0, gapAfter),
		}),
	})
	local ts = textSize(ctx, msg.text)
	-- generous slack: the phone is drawn scaled, and scaled text renders a little wider than measured
	local w = math.min(BUBBLE_MAX, math.ceil(ts.X * 1.1) + 32)
	local color = if me then P.BubbleMe else P.Bubble
	-- the bubble is a padded Frame with the text as a child label (padding a TextLabel directly makes Roblox
	-- clip the start of wrapped lines when the phone is scaled)
	local b = UIKit.new("Frame", {
		Name = "Bubble",
		LayoutOrder = 1,
		Size = UDim2.fromOffset(w, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = color,
		Parent = holder,
	}, { UIKit.corner(UDim.new(0, 17)), UIKit.padding(13, 8) })
	UIKit.new("TextLabel", {
		Name = "Text",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Body,
		Text = msg.text,
		TextColor3 = if me then P.BubbleMeText else Theme.Colors.Text,
		TextSize = TEXT_SIZE,
		TextWrapped = true,
		TextXAlignment = Enum.TextXAlignment.Left,
		ZIndex = b.ZIndex + 1,
		Parent = b,
	})
	if tail then
		-- the last bubble of a run gets one sharp corner on the sender's side (the "tail")
		UIKit.new("Frame", {
			Name = "Tail",
			AnchorPoint = if me then Vector2.new(1, 1) else Vector2.new(0, 1),
			Position = if me then UDim2.fromScale(1, 1) else UDim2.fromScale(0, 1),
			Size = UDim2.fromOffset(12, 12),
			BackgroundColor3 = color,
			BorderSizePixel = 0,
			ZIndex = b.ZIndex,
			Parent = b,
		})
	end
	if type(msg.link) == "table" then
		local label = if msg.link.kind == "waypoint" then "Set route: " .. (msg.link.label or "location") else "Open"
		local btn = UIKit.new("TextButton", {
			Name = "Link",
			LayoutOrder = 2,
			Size = UDim2.fromOffset(BUBBLE_MAX, 34),
			BackgroundColor3 = P.Card,
			AutoButtonColor = false,
			FontFace = Theme.Fonts.Bold,
			Text = label,
			TextColor3 = Theme.Colors.Accent,
			TextSize = 13,
			Parent = holder,
		}, { UIKit.corner(UDim.new(0, 14)), UIKit.stroke(0.85) })
		btn.Activated:Connect(function()
			ctx.action("openLink", { contact = contact, index = index })
		end)
	end
	return holder
end

local function separator(ctx: any, parent: Instance, text: string, order: number)
	ctx.UIKit.new("TextLabel", {
		Name = "Time",
		LayoutOrder = order,
		Size = UDim2.new(1, 0, 0, 26),
		BackgroundTransparency = 1,
		FontFace = ctx.Theme.Fonts.Bold,
		Text = text,
		TextColor3 = ctx.Theme.Colors.TextDim,
		TextSize = 11,
		Parent = parent,
	})
end

local function showThread(ctx: any, contact: string)
	ctx.clear()
	ctx.args.contact = contact
	local UIKit, Theme = ctx.UIKit, ctx.Theme
	local P, C = Theme.Phone, Theme.Colors
	local token = {}
	ctx.threadToken = token

	-- header: back · avatar + name (centre)
	local header = UIKit.new("Frame", {
		Name = "Header",
		Size = UDim2.new(1, 0, 0, 62),
		BackgroundColor3 = P.Screen,
		BackgroundTransparency = 0.1,
		ZIndex = 5,
		Parent = ctx.frame,
	})
	UIKit.new("Frame", {
		Name = "Line",
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.fromScale(0, 1),
		Size = UDim2.new(1, 0, 0, 1),
		BackgroundColor3 = P.Divider,
		BackgroundTransparency = 0.9,
		BorderSizePixel = 0,
		ZIndex = 5,
		Parent = header,
	})
	local back = UIKit.new("TextButton", {
		Name = "Back",
		Position = UDim2.fromOffset(2, 10),
		Size = UDim2.fromOffset(40, 40),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Bold,
		Text = "<",
		TextColor3 = C.AccentAlt,
		TextSize = 34,
		ZIndex = 6,
		Parent = header,
	})
	back.Activated:Connect(function()
		ctx.args.contact = nil
		App.mount(ctx.frame, ctx)
	end)
	avatar(ctx, header, contact, 30, { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 6), ZIndex = 6 })
	UIKit.new("TextLabel", {
		Name = "Name",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 40),
		Size = UDim2.new(1, -100, 0, 16),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Bold,
		Text = name(ctx, contact),
		TextColor3 = C.Text,
		TextSize = 12,
		TextTruncate = Enum.TextTruncate.AtEnd,
		ZIndex = 6,
		Parent = header,
	})

	-- conversation
	local list = UIKit.new("ScrollingFrame", {
		Name = "Thread",
		Position = UDim2.fromOffset(0, 62),
		Size = UDim2.new(1, 0, 1, -62 - COMPOSE_H - CHIPS_H),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		ScrollBarThickness = 2,
		ScrollBarImageTransparency = 0.6,
		Parent = ctx.frame,
	}, {
		UIKit.new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }),
		UIKit.new("UIPadding", { PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 8) }),
	})
	local function toBottom()
		task.defer(function()
			if list.Parent then
				list.CanvasPosition = Vector2.new(0, math.max(0, list.AbsoluteCanvasSize.Y - list.AbsoluteWindowSize.Y))
			end
		end)
	end

	-- suggestion chips (what the player can say), like a keyboard's suggestion strip
	local chips = UIKit.new("ScrollingFrame", {
		Name = "Replies",
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, 0, 1, -COMPOSE_H),
		Size = UDim2.new(1, 0, 0, CHIPS_H),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.X,
		ScrollingDirection = Enum.ScrollingDirection.X,
		ScrollBarThickness = 0,
		Parent = ctx.frame,
	}, {
		UIKit.new("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 6),
		}),
		UIKit.new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10) }),
	})

	-- compose bar: [ Text message        ] [Send]
	local bar = UIKit.new("Frame", {
		Name = "Compose",
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.fromScale(0, 1),
		Size = UDim2.new(1, 0, 0, COMPOSE_H),
		BackgroundColor3 = P.Screen,
		BackgroundTransparency = 0.1,
		Parent = ctx.frame,
	})
	local field = UIKit.new("TextLabel", {
		Name = "Field",
		Position = UDim2.fromOffset(10, 6),
		Size = UDim2.new(1, -74, 0, 34),
		BackgroundColor3 = P.Card,
		FontFace = Theme.Fonts.Body,
		Text = "Text message",
		TextColor3 = C.TextDim,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = bar,
	}, { UIKit.corner(UDim.new(1, 0)), UIKit.padding(12, 0, 0), UIKit.stroke(0.88) })
	local send = UIKit.new("TextButton", {
		Name = "Send",
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -10, 0, 6),
		Size = UDim2.fromOffset(54, 34),
		BackgroundColor3 = P.Card,
		AutoButtonColor = false,
		FontFace = Theme.Fonts.Bold,
		Text = "Send",
		TextColor3 = C.TextDim,
		TextSize = 13,
		Parent = bar,
	}, { UIKit.corner(UDim.new(1, 0)) })
	send:SetAttribute("MTL_NoTapSound", true)

	local draft: number? = nil -- index into QuickReplies typed into the field
	local typingDraft = false
	local lastSent = -1e9
	local function setDraft(i: number?, partial: string?)
		draft = i
		local ready = i ~= nil and not typingDraft
		if i then
			field.Text = (partial or ctx.Config.QuickReplies[i]) .. (if typingDraft then "|" else "")
			field.TextColor3 = C.Text
		else
			field.Text = "Text message"
			field.TextColor3 = C.TextDim
		end
		send.BackgroundColor3 = if ready then C.Accent else P.Card
		send.TextColor3 = if ready then P.BubbleMeText else C.TextDim
	end
	for i, text in ctx.Config.QuickReplies do
		local chip = UIKit.new("TextButton", {
			Name = "Reply",
			LayoutOrder = i,
			Size = UDim2.fromOffset(0, 30),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundColor3 = P.CardHover,
			AutoButtonColor = false,
			FontFace = Theme.Fonts.Bold,
			Text = text,
			TextColor3 = C.Text,
			TextSize = 13,
			Parent = chips,
		}, { UIKit.corner(UDim.new(1, 0)), UIKit.padding(12, 0, 0), UIKit.stroke(0.85) })
		chip:SetAttribute("MTL_NoTapSound", true)
		chip.Activated:Connect(function()
			if typingDraft then
				return
			end
			-- types it into the field a few letters at a time (key taps), then Send lights up
			typingDraft = true
			task.spawn(function()
				local n = #text
				local step = math.max(1, n // 6)
				local k = 0
				while k < n do
					if ctx.threadToken ~= token then
						return
					end
					k = math.min(n, k + step)
					setDraft(i, string.sub(text, 1, k))
					ctx.sfx("PhoneType")
					task.wait(0.05 + math.random() * 0.03)
				end
				typingDraft = false
				setDraft(i)
			end)
		end)
	end
	send.Activated:Connect(function()
		if not draft or typingDraft or os.clock() - lastSent < ctx.Config.ReplyCooldown then
			return
		end
		lastSent = os.clock()
		local i = draft
		ctx.sfx("PhoneSend")
		ctx.action("quickReply", { contact = contact, index = i })
		setDraft(nil)
	end)

	-- typing dots (animated) when the contact is about to answer
	local typing: Frame? = nil
	local typingToken = {}
	local function showTyping(on: boolean)
		typingToken = {}
		if typing then
			typing:Destroy()
			typing = nil
		end
		if not on or not list.Parent then
			return
		end
		local mine = typingToken
		local holder = UIKit.new("Frame", {
			Name = "Typing",
			LayoutOrder = 1000000,
			Size = UDim2.new(1, 0, 0, 40),
			BackgroundTransparency = 1,
			Parent = list,
		}, { UIKit.new("UIPadding", { PaddingLeft = UDim.new(0, 10) }) })
		typing = holder
		local b = UIKit.new("Frame", {
			Name = "Bubble",
			Position = UDim2.fromOffset(0, 4),
			Size = UDim2.fromOffset(58, 32),
			BackgroundColor3 = P.Bubble,
			Parent = holder,
		}, { UIKit.corner(UDim.new(0, 17)) })
		UIKit.new("Frame", {
			Name = "Tail",
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.fromScale(0, 1),
			Size = UDim2.fromOffset(10, 10),
			BackgroundColor3 = P.Bubble,
			BorderSizePixel = 0,
			Parent = b,
		})
		local dots = {}
		for d = 1, 3 do
			dots[d] = UIKit.new("Frame", {
				Name = "Dot",
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.new(0, 14 + (d - 1) * 15, 0.5, 0),
				Size = UDim2.fromOffset(7, 7),
				BackgroundColor3 = C.TextDim,
				BorderSizePixel = 0,
				Parent = b,
			}, { UIKit.corner(UDim.new(1, 0)) })
		end
		task.spawn(function()
			local t0 = os.clock()
			while typingToken == mine and holder.Parent do
				local t = os.clock() - t0
				for d, dot in dots do
					local k = math.max(0, math.sin(t * 7 - d * 0.9))
					dot.BackgroundTransparency = 0.6 - k * 0.6
					dot.Position = UDim2.new(0, 14 + (d - 1) * 15, 0.5, -k * 3)
				end
				task.wait()
			end
		end)
		toBottom()
	end
	ctx.showTyping = function(c: string)
		if c == contact and ctx.threadToken == token then
			showTyping(true)
			task.delay(5, function()
				if ctx.threadToken == token then
					showTyping(false)
				end
			end)
		end
	end

	local shown = -1
	local function render(d: any)
		if ctx.threadToken ~= token then
			return
		end
		local thread = d.Phone.Texts and d.Phone.Texts[contact] or {}
		local grew = shown >= 0 and #thread > shown
		shown = #thread
		-- the contact's reply replaces the dots; my own new message must not wipe them (they arrive right after)
		local keepTyping = typing ~= nil and thread[#thread] ~= nil and thread[#thread].me == true
		if not keepTyping then
			showTyping(false)
		elseif typing then
			typing.Parent = nil
		end
		for _, c in list:GetChildren() do
			if c:IsA("GuiObject") then
				c:Destroy()
			end
		end
		if #thread == 0 then
			UIKit.empty(list, "No messages yet.")
		end
		local order = 0
		local lastHolder: Frame? = nil
		for i, msg in thread do
			local prev, nextMsg = thread[i - 1], thread[i + 1]
			local t = msg.t or 0
			if not prev or (t - (prev.t or 0)) >= TIME_GAP then
				order += 1
				separator(ctx, list, if t > 0 then dayLabel(t) else "", order)
			end
			local sameNext = nextMsg ~= nil and (nextMsg.me == true) == (msg.me == true) and ((nextMsg.t or 0) - t) < TIME_GAP
			order += 1
			lastHolder = bubble(ctx, list, msg, order, contact, i, not sameNext, if sameNext then GROUP_GAP else BLOCK_GAP)
			if msg.me and i == #thread then
				order += 1
				UIKit.new("TextLabel", {
					Name = "Delivered",
					LayoutOrder = order,
					Size = UDim2.new(1, -12, 0, 14),
					BackgroundTransparency = 1,
					FontFace = Theme.Fonts.Bold,
					Text = "Delivered",
					TextColor3 = C.TextDim,
					TextSize = 10,
					TextXAlignment = Enum.TextXAlignment.Right,
					Parent = list,
				})
			end
		end
		if keepTyping and typing then
			typing.Parent = list
		end
		-- the newest bubble pops in
		if grew and lastHolder then
			local bb = lastHolder:FindFirstChild("Bubble") :: GuiObject?
			if bb then
				local s = UIKit.new("UIScale", { Scale = 0.85, Parent = bb })
				TweenService:Create(s, TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
			end
		end
		toBottom()
		if d.Phone.Unread and (d.Phone.Unread[contact] or 0) > 0 then
			ctx.action("readThread", { contact = contact })
		end
	end
	ctx.onData(render)
end

---------------------------------------------------------------- conversation list

local function showList(ctx: any)
	ctx.clear()
	ctx.showTyping = nil
	local UIKit, Theme = ctx.UIKit, ctx.Theme
	local P, C = Theme.Phone, Theme.Colors
	UIKit.new("TextLabel", {
		Name = "Title",
		Position = UDim2.fromOffset(16, 4),
		Size = UDim2.new(1, -32, 0, 40),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Display,
		Text = "Messages",
		TextColor3 = C.Text,
		TextSize = 28,
		TextXAlignment = Enum.TextXAlignment.Left,
		Parent = ctx.frame,
	})
	local list = UIKit.new("ScrollingFrame", {
		Name = "Threads",
		Position = UDim2.fromOffset(0, 50),
		Size = UDim2.new(1, 0, 1, -50),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 2,
		ScrollBarImageTransparency = 0.6,
		Parent = ctx.frame,
	}, { UIKit.new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }) })
	local token = {}
	ctx.threadToken = token
	ctx.onData(function(d: any)
		if ctx.threadToken ~= token then
			return
		end
		for _, c in list:GetChildren() do
			if c:IsA("GuiObject") then
				c:Destroy()
			end
		end
		local threads = ctx.Rules.threads(d.Phone)
		if #threads == 0 then
			UIKit.empty(list, "No messages yet. People text you as the story moves on.")
		end
		local now = os.time()
		for i, th in threads do
			local unread = th.unread > 0
			local row = UIKit.new("TextButton", {
				Name = "Thread_" .. th.contact,
				LayoutOrder = i,
				Size = UDim2.new(1, 0, 0, 68),
				BackgroundColor3 = P.CardHover,
				BackgroundTransparency = 1,
				AutoButtonColor = false,
				Text = "",
				Parent = list,
			})
			row.MouseEnter:Connect(function()
				row.BackgroundTransparency = 0.6
			end)
			row.MouseLeave:Connect(function()
				row.BackgroundTransparency = 1
			end)
			if unread then
				UIKit.new("Frame", {
					Name = "Unread",
					AnchorPoint = Vector2.new(0.5, 0.5),
					Position = UDim2.new(0, 8, 0.5, 0),
					Size = UDim2.fromOffset(7, 7),
					BackgroundColor3 = C.AccentAlt,
					BorderSizePixel = 0,
					Parent = row,
				}, { UIKit.corner(UDim.new(1, 0)) })
			end
			avatar(ctx, row, th.contact, 44, { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 16, 0.5, 0) })
			UIKit.new("TextLabel", {
				Name = "Name",
				Position = UDim2.fromOffset(72, 12),
				Size = UDim2.new(1, -144, 0, 18),
				BackgroundTransparency = 1,
				FontFace = Theme.Fonts.Bold,
				Text = name(ctx, th.contact),
				TextColor3 = C.Text,
				TextSize = 15,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				Parent = row,
			})
			UIKit.new("TextLabel", {
				Name = "When",
				AnchorPoint = Vector2.new(1, 0),
				Position = UDim2.new(1, -14, 0, 13),
				Size = UDim2.fromOffset(60, 16),
				BackgroundTransparency = 1,
				FontFace = Theme.Fonts.Body,
				Text = ctx.Rules.ago(now - th.t),
				TextColor3 = if unread then C.AccentAlt else C.TextDim,
				TextSize = 12,
				TextXAlignment = Enum.TextXAlignment.Right,
				Parent = row,
			})
			UIKit.new("TextLabel", {
				Name = "Preview",
				Position = UDim2.fromOffset(72, 31),
				Size = UDim2.new(1, -90, 0, 32),
				BackgroundTransparency = 1,
				FontFace = Theme.Fonts.Body,
				Text = (if th.last.me then "You: " else "") .. th.last.text,
				TextColor3 = if unread then C.Text else C.TextDim,
				TextSize = 13,
				TextWrapped = true,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextYAlignment = Enum.TextYAlignment.Top,
				TextTruncate = Enum.TextTruncate.AtEnd,
				Parent = row,
			})
			UIKit.new("Frame", {
				Name = "Line",
				AnchorPoint = Vector2.new(0, 1),
				Position = UDim2.new(0, 72, 1, 0),
				Size = UDim2.new(1, -72, 0, 1),
				BackgroundColor3 = P.Divider,
				BackgroundTransparency = 0.92,
				BorderSizePixel = 0,
				Parent = row,
			})
			row.Activated:Connect(function()
				showThread(ctx, th.contact)
			end)
		end
	end)
end

function App.mount(_frame: Frame, ctx: any)
	if ctx.args.contact then
		showThread(ctx, ctx.args.contact)
	else
		showList(ctx)
	end
end

-- a text arriving while Messages is open: the list/thread re-renders from the snapshot; only banner if it's
-- for another thread
function App.onEvent(msg: any, ctx: any)
	if msg.type == "typing" and ctx.showTyping and ctx.args.contact == msg.contact then
		ctx.showTyping(msg.contact)
		return
	end
	-- only while the phone is up (when it's down the controller already shows the linked banner); tapping it
	-- jumps to that thread
	if msg.type == "text" and not msg.silent and ctx.Phone.isOpen() and ctx.args.contact ~= msg.contact then
		ctx.Phone.notify({
			app = "Messages",
			title = msg.name or "Message",
			text = msg.text,
			args = { contact = msg.contact },
			glyph = string.sub(msg.name or "?", 1, 1),
			force = true,
		})
	end
end

return App
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Apps", "Plug", "ModuleScript", [======[--!strict
-- Plug app (Piece 5): guns and ammo for the criminal path. Installed by GunService once the player is
-- Criminal (hidden before). Prices, levels and packs come from Config/Guns; the server re-checks everything.
--   GUNS   each gun: damage / fire rate / mag as plain bars, level + price, BUY (or OWNED / Level N)
--   AMMO   one row per ammo type you have a gun for: rounds you carry, +pack for $
-- Buttons: PhoneAction buyGun{gun} / buyAmmo{ammo}.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Guns = require(ReplicatedStorage.MTL.Config.Guns)
local GunRules = require(ReplicatedStorage.MTL.Rules.GunRules)
local Format = require(ReplicatedStorage.MTL.Format)

local App = { id = "Plug", title = "Plug" }

local player = Players.LocalPlayer

local function money(n: number): string
	return Format.cash(n)
end

-- Normalised 0..1 stats for the little bars (relative to the best gun in the list).
local function stats(id: string): (number, number, number)
	local def = Guns.Defs[id]
	local maxDps, maxRpm, maxMag = 0, 0, 0
	for _, g in Guns.Defs do
		maxDps = math.max(maxDps, g.Damage * (g.Pellets or 1))
		maxRpm = math.max(maxRpm, g.RPM)
		maxMag = math.max(maxMag, g.Mag)
	end
	return (def.Damage * (def.Pellets or 1)) / maxDps, def.RPM / maxRpm, def.Mag / maxMag
end

local function statBar(parent: Instance, ctx: any, label: string, v: number, order: number)
	local UIKit, Theme = ctx.UIKit, ctx.Theme
	local row = UIKit.new("Frame", { Name = "Stat_" .. label, LayoutOrder = order, Size = UDim2.new(1, 0, 0, 14), BackgroundTransparency = 1, Parent = parent })
	UIKit.label(row, label, { size = 11, dim = true }).Size = UDim2.new(0, 60, 1, 0)
	local track = UIKit.new("Frame", {
		Position = UDim2.new(0, 64, 0.5, -2),
		Size = UDim2.new(1, -64, 0, 4),
		BackgroundColor3 = Theme.Colors.Stroke,
		BackgroundTransparency = 0.85,
		BorderSizePixel = 0,
		Parent = row,
	}, { UIKit.corner(UDim.new(1, 0)) })
	UIKit.new("Frame", { Size = UDim2.fromScale(math.clamp(v, 0.05, 1), 1), BackgroundColor3 = Theme.Colors.Danger, BorderSizePixel = 0, Parent = track }, { UIKit.corner(UDim.new(1, 0)) })
end

local function render(ctx: any, d: any)
	ctx.clear()
	local UIKit, Theme = ctx.UIKit, ctx.Theme
	local C = Theme.Colors
	UIKit.header(ctx.frame, "Plug")
	local list = UIKit.scroll(ctx.frame, 44, "Plug")
	local inv = d.Inventory or {}
	local owned = inv.Guns or {}
	local ammo = inv.Ammo or {}
	local criminal = d.Path == "Criminal"

	if not criminal then
		local card = UIKit.card(list, 1)
		UIKit.label(card, "Plug only deals with the Criminal lifestyle.", { wrap = true, order = 1 })
		UIKit.label(card, "Switch in Settings > Lifestyle.", { wrap = true, dim = true, size = 12, order = 2 })
		return
	end

	UIKit.section(list, "Guns", 10)
	for i, id in Guns.Order do
		local def = Guns.Defs[id]
		local mine = owned[id] == true
		local card = UIKit.card(list, 10 + i, "Gun_" .. id)
		UIKit.label(card, def.Display, { size = 16, bold = true, order = 1 })
		local sub = (if def.Auto then "Full auto" elseif (def.Pellets or 1) > 1 then "Pump" else "Semi auto") .. " · " .. def.Mag .. " rounds · " .. def.Ammo
		UIKit.label(card, sub, { size = 12, dim = true, order = 2 })
		local dmg, rate, magV = stats(id)
		statBar(card, ctx, "Damage", dmg, 3)
		statBar(card, ctx, "Fire rate", rate, 4)
		statBar(card, ctx, "Mag", magV, 5)
		local ttk = GunRules.shotsToKill(def, 100, 20)
		UIKit.label(card, "Drops someone in " .. ttk .. (if ttk == 1 then " shot" else " shots") .. " up close", { size = 11, dim = true, order = 6 })
		local ok, why = GunRules.canBuyGun(def, d.Level, d.Cash, d.Path, mine)
		if mine then
			UIKit.button(card, "Owned", { style = "secondary", order = 7, disabled = true })
		elseif ok then
			UIKit.button(card, "Buy · " .. money(def.Price), {
				style = "danger",
				order = 7,
				onClick = function()
					ctx.action("buyGun", { gun = id })
				end,
			})
		else
			local text = if d.Level < (def.Level or 1) then ("Level " .. def.Level .. " · " .. money(def.Price)) else ((why or "Locked") .. " · " .. money(def.Price))
			UIKit.button(card, text, { style = "secondary", order = 7, disabled = true })
		end
	end

	UIKit.section(list, "Ammo", 40)
	local any = false
	local types: { string } = {}
	local seen: { [string]: boolean } = {}
	for _, id in Guns.Order do
		local def = Guns.Defs[id]
		if owned[id] and not seen[def.Ammo] then
			seen[def.Ammo] = true
			table.insert(types, def.Ammo)
		end
	end
	for i, a in types do
		any = true
		local pack = Guns.Ammo[a]
		if pack then
			local have = ammo[a] or 0
			local ok, why = GunRules.canBuyAmmo(pack, have, d.Cash, d.Path, true)
			UIKit.row(list, {
				title = pack.Display .. "  ·  " .. have .. " / " .. pack.Max,
				sub = "+" .. pack.Count .. " rounds",
				right = if ok then money(pack.Price) else (why or ""),
				rightColor = if ok then C.Accent else C.TextDim,
				order = 40 + i,
				name = "Ammo_" .. a,
				onClick = function()
					if ok then
						ctx.action("buyAmmo", { ammo = a })
					end
				end,
			})
		end
	end
	if not any then
		UIKit.empty(list, "Buy a gun first.", 41)
	end
	UIKit.label(list, "Guns stay holstered in safe zones and on shift. Civilians can't be shot.", { wrap = true, size = 11, dim = true, order = 60, align = Enum.TextXAlignment.Center })
end

function App.mount(_frame: Frame, ctx: any)
	local lastKey = ""
	ctx.onData(function(d: any)
		local inv = d.Inventory or {}
		local parts = { tostring(d.Path), tostring(d.Level), tostring(d.Cash) }
		for _, id in Guns.Order do
			table.insert(parts, tostring((inv.Guns or {})[id]))
		end
		for a in Guns.Ammo do
			table.insert(parts, a .. "=" .. tostring((inv.Ammo or {})[a]))
		end
		table.sort(parts)
		local k = table.concat(parts, "|")
		if k ~= lastKey then
			lastKey = k
			render(ctx, d)
		end
	end)
	local _ = player
end

return App
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Apps", "Settings", "ModuleScript", [======[--!strict
-- Settings: Lifestyle (Civilian / Criminal, Master Plan §1 branching rules), sound/music/reduced motion, help.
-- Lifestyle is locked until free play (after the first mission). Switching asks for a confirm, then the server
-- checks the stage, the cooldown and any guards (e.g. no switching mid-fight) and answers with "pathResult".
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local StoryRules = require(ReplicatedStorage.MTL.Rules.StoryRules)

local App = { id = "Settings", title = "Settings" }

local render: (any, any) -> ()

local function confirm(ctx: any, path: string)
	ctx.clear()
	ctx.confirming = path
	local UIKit, Theme = ctx.UIKit, ctx.Theme
	local info = ctx.Config.Paths[path]
	UIKit.header(ctx.frame, "Lifestyle", function()
		ctx.confirming = nil
		local d = ctx.data()
		if d then
			render(ctx, d)
		end
	end)
	local list = UIKit.scroll(ctx.frame, 44, "Confirm")
	local card = UIKit.card(list, 1)
	UIKit.label(card, "Switch to " .. info.title .. "?", { size = 18, bold = true, order = 1 })
	UIKit.label(card, info.blurb, { wrap = true, dim = true, order = 2 })
	UIKit.label(card, "You can switch back later.", { size = 12, dim = true, order = 3 })
	local status = UIKit.label(list, "", { wrap = true, order = 4, align = Enum.TextXAlignment.Center, name = "Status" })
	status.TextColor3 = Theme.Colors.Danger
	ctx.statusLabel = status
	UIKit.button(list, "Switch to " .. info.title, {
		style = if path == "Criminal" then "danger" else "primary",
		order = 5,
		onClick = function()
			status.Text = "..."
			ctx.action("setPath", { path = path })
		end,
	})
	UIKit.button(list, "Cancel", {
		style = "secondary",
		order = 6,
		onClick = function()
			ctx.confirming = nil
			local d = ctx.data()
			if d then
				render(ctx, d)
			end
		end,
	})
end

render = function(ctx: any, d: any)
	ctx.clear()
	ctx.statusLabel = nil
	local UIKit, Theme = ctx.UIKit, ctx.Theme
	local C = Theme.Colors
	UIKit.header(ctx.frame, "Settings")
	local list = UIKit.scroll(ctx.frame, 44, "Settings")

	-- Lifestyle
	UIKit.section(list, "Lifestyle", 1)
	local open = StoryRules.freePlayOpen(d.Story.Stage)
	for i, path in { "Civilian", "Criminal" } do
		local info = ctx.Config.Paths[path]
		local mine = d.Path == path
		local row = UIKit.row(list, {
			title = info.title,
			sub = info.blurb,
			right = if mine then "Current" elseif open then "Switch" else "Locked",
			rightColor = if mine then C.Accent elseif open then C.Text else C.TextDim,
			dot = if mine then (if path == "Criminal" then C.Danger else C.Accent) else nil,
			order = 1 + i,
			name = "Path_" .. path,
			onClick = function()
				if open and not mine then
					confirm(ctx, path)
				end
			end,
		})
		row.Size = UDim2.new(1, 0, 0, 62)
		row.Sub.TextWrapped = true
		row.Sub.Size = UDim2.new(row.Sub.Size.X.Scale, row.Sub.Size.X.Offset, 0, 30)
	end
	if not open then
		UIKit.label(list, "Unlocks after your first mission.", { size = 12, dim = true, order = 4 })
	end

	-- Sound & motion
	UIKit.section(list, "Sound & motion", 10)
	local s = d.Settings or {}
	local function setter(key: string)
		return function(v: boolean)
			ctx.action("setSetting", { key = key, value = v })
		end
	end
	UIKit.toggle(list, "Sound effects", s.Sound ~= false, setter("Sound"), 11)
	UIKit.toggle(list, "Music", s.Music ~= false, setter("Music"), 12)
	UIKit.toggle(list, "Reduced motion", s.ReducedMotion == true, setter("ReducedMotion"), 13)

	-- Help
	UIKit.section(list, "Help", 20)
	local help = UIKit.card(list, 21)
	local touch = game:GetService("UserInputService").TouchEnabled
	UIKit.label(help, if touch then "Tap the phone to open it. Drag the top or bottom bar down to put it away." else "Press M or click the phone to open it. Press M again or click the world to put it away.", { wrap = true, dim = true, size = 13, order = 1 })
	if d.DataMode == "Mock" then
		UIKit.label(help, "Studio test mode: progress resets when you stop.", { wrap = true, size = 12, order = 2, color = C.Gold })
	end
	UIKit.label(list, "Miami Trap Life · " .. Players.LocalPlayer.Name, { size = 11, dim = true, order = 30, align = Enum.TextXAlignment.Center })
end

function App.mount(_frame: Frame, ctx: any)
	local lastKey = ""
	ctx.onData(function(d: any)
		if ctx.confirming then
			-- the switch went through while confirming -> back to the list
			if d.Path == ctx.confirming then
				ctx.confirming = nil
			else
				return
			end
		end
		local st = d.Settings or {}
		local k = table.concat({ tostring(d.Story.Stage), tostring(d.Path), tostring(st.Sound), tostring(st.Music), tostring(st.ReducedMotion) }, "|")
		if k ~= lastKey then
			lastKey = k
			render(ctx, d)
		end
	end)
end

function App.onEvent(msg: any, ctx: any)
	if msg.type == "pathResult" and not msg.ok and ctx.statusLabel and ctx.statusLabel.Parent then
		ctx.statusLabel.Text = msg.reason or "Can't switch right now"
	end
end

return App
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "Actors", "ModuleScript", [======[--!strict
-- Local (this client only) actors and props for cutscenes and mission scenes. Nothing here replicates, so every
-- player's scene is private and costs the server nothing. Required by CutsceneController and MissionController.
--   Actors.spawn(rigName, parent) -> Actor?      rigName = a ReplicatedStorage.MTL_Actors.<Name> rig, or "@player"
--   Actors.place(actor, groundCFrame)            feet on the floor at that CFrame (facing its LookVector)
--   Actors.render(actor, state, now)             Rig.State -> pose (call every frame)
--   Actors.setHidden(actor, bool)   Actors.destroy(actor)
--   Actors.prop(name, opts) -> Model             "CrewCar" (opts.hazards), "Mask", "CashBag", or registerProp()
--   Actors.registerProp(name, fn(opts) -> Model) Piece 4: PC, bed, etc. (or drop a model in MTL_Actors.<name>)
--   Actors.floor(position, ignore?) -> y         ground height under a point (falls back to the point's y)
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local Rig = require(ReplicatedStorage.MTL.Rig)
local Missions = require(ReplicatedStorage.MTL.Config.Missions)
local Theme = require(ReplicatedStorage.MTL.UI.Theme)

local player = Players.LocalPlayer

local Actors = {}

export type Actor = {
	name: string,
	model: Model,
	root: BasePart,
	joints: Rig.Joints,
	height: number,
	parts: { BasePart },
	decals: { Decal },
	hidden: boolean,
	tracks: { [string]: AnimationTrack },
	lastGesture: string?,
}

local function folder(): Folder
	local f = workspace:FindFirstChild("MTL_LocalScene")
	if not f then
		f = Instance.new("Folder")
		f.Name = "MTL_LocalScene"
		f.Parent = workspace
	end
	return f :: Folder
end
Actors.folder = folder

local ignoreParams = RaycastParams.new()
ignoreParams.FilterType = Enum.RaycastFilterType.Exclude

function Actors.floor(pos: Vector3, ignore: { Instance }?): number
	local list: { Instance } = { folder() }
	for _, p in Players:GetPlayers() do
		if p.Character then
			table.insert(list, p.Character)
		end
	end
	for _, i in ignore or {} do
		table.insert(list, i)
	end
	-- only real, solid ground counts: invisible lot "Footprint" volumes, trigger zones and glass-free markers made
	-- actors float (Alex: "the character floats"), so skip anything you can walk through or can't see
	ignoreParams.RespectCanCollide = true
	local origin = pos + Vector3.new(0, 4, 0)
	for _ = 1, 6 do
		ignoreParams.FilterDescendantsInstances = list
		local hit = workspace:Raycast(origin, Vector3.new(0, -40, 0), ignoreParams)
		if not hit then
			return pos.Y
		end
		local part = hit.Instance :: BasePart
		if part:IsA("BasePart") and part.Transparency < 0.95 then
			return hit.Position.Y
		end
		table.insert(list, part)
	end
	return pos.Y
end

local function strip(model: Instance)
	for _, d in model:GetDescendants() do
		if d:IsA("BaseScript") or d:IsA("Tool") or d:IsA("ForceField") or d:IsA("Sound") then
			d:Destroy()
		end
	end
end

-- A simple blocky R6 rig, used only if neither a template nor the server-built rig exists (the scene still plays).
local function fallbackRig(name: string): Model
	local cfg = (Missions.Actors :: any)[name] or {}
	local skin = cfg.Skin or Color3.fromRGB(200, 160, 130)
	local shirt = cfg.Shirt or Color3.fromRGB(80, 80, 90)
	local pants = cfg.Pants or Color3.fromRGB(40, 40, 46)
	local m = Instance.new("Model")
	m.Name = name
	local function p(n: string, size: Vector3, color: Color3): Part
		local part = Instance.new("Part")
		part.Name = n
		part.Size = size
		part.Color = color
		part.TopSurface = Enum.SurfaceType.Smooth
		part.BottomSurface = Enum.SurfaceType.Smooth
		part.CanCollide = false
		part.Parent = m
		return part
	end
	local root = p("HumanoidRootPart", Vector3.new(2, 2, 1), skin)
	root.Transparency = 1
	local torso = p("Torso", Vector3.new(2, 2, 1), shirt)
	local head = p("Head", Vector3.new(1.2, 1.2, 1.2), skin)
	local ra = p("Right Arm", Vector3.new(1, 2, 1), skin)
	local la = p("Left Arm", Vector3.new(1, 2, 1), skin)
	local rl = p("Right Leg", Vector3.new(1, 2, 1), pants)
	local ll = p("Left Leg", Vector3.new(1, 2, 1), pants)
	local function motor(n: string, p0: BasePart, p1: BasePart, c0: CFrame, c1: CFrame)
		local mt = Instance.new("Motor6D")
		mt.Name = n
		mt.Part0 = p0
		mt.Part1 = p1
		mt.C0 = c0
		mt.C1 = c1
		mt.Parent = p0
	end
	local R90 = CFrame.Angles(0, math.rad(90), 0)
	local L90 = CFrame.Angles(0, math.rad(-90), 0)
	motor("RootJoint", root, torso, CFrame.new(), CFrame.new())
	motor("Neck", torso, head, CFrame.new(0, 1, 0), CFrame.new(0, -0.6, 0))
	motor("Right Shoulder", torso, ra, CFrame.new(1, 0.5, 0) * R90, CFrame.new(-0.5, 0.5, 0) * R90)
	motor("Left Shoulder", torso, la, CFrame.new(-1, 0.5, 0) * L90, CFrame.new(0.5, 0.5, 0) * L90)
	motor("Right Hip", torso, rl, CFrame.new(1, -1, 0) * R90, CFrame.new(0.5, 1, 0) * R90)
	motor("Left Hip", torso, ll, CFrame.new(-1, -1, 0) * L90, CFrame.new(-0.5, 1, 0) * L90)
	local h = Instance.new("Humanoid")
	h.RigType = Enum.HumanoidRigType.R6
	h.Parent = m
	m.PrimaryPart = root
	return m
end

-- wait = true for crew rigs (the server builds them a moment after it starts); props never wait.
local function template(name: string, wait: boolean?): Model?
	local lib = ReplicatedStorage:FindFirstChild("MTL_Actors")
	if not lib and wait then
		lib = ReplicatedStorage:WaitForChild("MTL_Actors", 3)
	end
	local t = lib and (lib:FindFirstChild(name) or (if wait then lib:WaitForChild(name, 3) else nil))
	return if t and t:IsA("Model") then t else nil
end

function Actors.spawn(rigName: string, parent: Instance?): Actor?
	local model: Model? = nil
	if rigName == "@player" then
		local char = player.Character
		if char then
			local was = char.Archivable
			char.Archivable = true
			local ok, clone = pcall(function()
				return char:Clone()
			end)
			char.Archivable = was
			if ok and clone then
				model = clone
			end
		end
	else
		local t = template(rigName, true)
		if t then
			local was = t.Archivable
			t.Archivable = true
			model = t:Clone()
			t.Archivable = was
		end
	end
	if not model then
		model = fallbackRig(if rigName == "@player" then player.Name else rigName)
	end
	assert(model)
	strip(model)
	local root = model:FindFirstChild("HumanoidRootPart") :: BasePart?
	local hum = model:FindFirstChildOfClass("Humanoid")
	if not root or not hum then
		model:Destroy()
		warn("[MTL Cutscene] rig has no Humanoid/HumanoidRootPart:", rigName)
		return nil
	end
	model.Name = "Actor_" .. (if rigName == "@player" then "Player" else rigName)
	hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
	hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
	hum.BreakJointsOnDeath = false
	hum.EvaluateStateMachine = false -- a puppet: no physics states fighting our CFrames
	local parts, decals = {}, {}
	for _, d in model:GetDescendants() do
		if d:IsA("BasePart") then
			d.Anchored = false
			d.CanCollide = false
			d.CanQuery = false
			d.CanTouch = false
			d.Massless = true
			table.insert(parts, d)
		elseif d:IsA("Decal") then
			table.insert(decals, d)
		end
	end
	root.Anchored = true
	model.PrimaryPart = root
	model.Parent = parent or folder()
	local actor: Actor = {
		name = rigName,
		model = model,
		root = root,
		joints = Rig.joints(model),
		height = Rig.rootHeight(model),
		parts = parts,
		decals = decals,
		hidden = false,
		tracks = {},
		lastGesture = nil,
	}
	return actor
end

-- Puts the actor's feet on the floor at `cf` (cf.Position is a floor point; the actor faces cf.LookVector).
function Actors.place(actor: Actor, cf: CFrame, drop: number?)
	actor.root.CFrame = cf + Vector3.new(0, actor.height - (drop or 0), 0)
end

function Actors.setHidden(actor: Actor, hidden: boolean)
	if actor.hidden == hidden then
		return
	end
	actor.hidden = hidden
	for _, p in actor.parts do
		p.LocalTransparencyModifier = if hidden then 1 else 0
	end
	for _, d in actor.decals do
		d.LocalTransparencyModifier = if hidden then 1 else 0
	end
end

-- Real animations (Config/Missions.Animations). Layers:
--   base    Idle (no held pose) or Walk (while walking), looped, under everything
--   gesture one-shot (Wave, Point, Nod...) on top, Action priority
-- While any animation plays, the Animator owns Motor6D.Transform; our head turn (look at the speaker) then goes
-- into the Neck's C0 instead, so both show. Held poses (Lean, Phone, Sit...) and gestures without an id stay
-- procedural (Rig.lua writes Transform). R6 rigs are always procedural.
local function animId(name: string): number?
	local id = (Missions.Animations :: any)[name]
	return if type(id) == "number" and id ~= 0 then id else nil
end

local function loadTrack(actor: Actor, name: string): AnimationTrack?
	local track = actor.tracks[name]
	if track then
		return track
	end
	local id = animId(name)
	local hum = actor.model:FindFirstChildOfClass("Humanoid")
	if not id or not hum or hum.RigType ~= Enum.HumanoidRigType.R15 then
		return nil
	end
	local animator = hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum)
	local anim = Instance.new("Animation")
	anim.AnimationId = "rbxassetid://" .. id
	local ok, t = pcall(function()
		return (animator :: Animator):LoadAnimation(anim)
	end)
	if not ok or not t then
		return nil
	end
	if name == "Idle" then
		t.Priority = Enum.AnimationPriority.Idle
		t.Looped = true
	elseif name == "Walk" then
		t.Priority = Enum.AnimationPriority.Movement
		t.Looped = true
	else
		t.Priority = Enum.AnimationPriority.Action
		t.Looped = false
	end
	actor.tracks[name] = t
	return t
end

local function setBase(actor: Actor, name: string?)
	local a = actor :: any
	if a.base == name then
		return
	end
	if a.base and actor.tracks[a.base] then
		actor.tracks[a.base]:Stop(0.25)
	end
	a.base = nil
	if name then
		local t = loadTrack(actor, name)
		if t then
			t:Play(0.25)
			if name == "Walk" then
				t:AdjustSpeed(Missions.WalkAnimSpeed or 0.8)
			end
			a.base = name
		end
	end
end

local function neckC0(actor: Actor, yaw: number?)
	local j = actor.joints.Neck
	if not j then
		return
	end
	if yaw and yaw ~= 0 then
		local r = CFrame.fromEulerAnglesYXZ(0, math.clamp(yaw, -0.8, 0.8), 0)
		j.motor.C0 = j.c0 * (j.rot0:Inverse() * r * j.rot0)
	else
		j.motor.C0 = j.c0
	end
end

function Actors.render(actor: Actor, state: Rig.State, now: number)
	local s = state
	local a = actor :: any
	-- gesture: start its animation once when it begins
	if s.gesture and s.gesture ~= actor.lastGesture then
		actor.lastGesture = s.gesture
		local t = loadTrack(actor, s.gesture)
		if t then
			t:Play(0.15)
		end
	elseif not s.gesture then
		actor.lastGesture = nil
	end
	local gTrack = s.gesture and actor.tracks[s.gesture]
	local gestureAnimated = gTrack ~= nil and gTrack.IsPlaying
	local held = s.pose ~= nil and s.pose ~= "None"
	local proceduralGesture = s.gesture ~= nil and not gestureAnimated and Rig.Gestures[s.gesture] ~= nil
	-- base layer: idle when standing free, walk while walking; off for held poses and procedural gestures
	local base: string? = nil
	if (s.walk or 0) > 0.05 then
		base = "Walk"
	elseif not held and not proceduralGesture then
		base = "Idle"
	end
	setBase(actor, base)
	local animated = gestureAnimated or (a.base ~= nil and actor.tracks[a.base] ~= nil and actor.tracks[a.base].IsPlaying)
	if animated and not held and not proceduralGesture then
		-- the Animator drives the body; we only turn the head (through C0)
		neckC0(actor, s.lookYaw)
		a.c0Used = true
	else
		if a.c0Used then
			neckC0(actor, nil)
			a.c0Used = false
		end
		local copy = s
		if gestureAnimated then
			copy = table.clone(s) :: any
			copy.gesture = nil
		end
		Rig.apply(actor.joints, Rig.compose(copy, now), "Transform")
	end
end

function Actors.destroy(actor: Actor?)
	if actor and actor.model then
		actor.model:Destroy()
	end
end

---------------------------------------------------------------- props

local propBuilders: { [string]: (any) -> Model } = {}

function Actors.registerProp(name: string, fn: (any) -> Model)
	propBuilders[name] = fn
end

local function part(props: { [string]: any }): Part
	local p = Instance.new("Part")
	p.Anchored = true
	p.CanCollide = false
	p.CanQuery = false
	p.CanTouch = false
	p.TopSurface = Enum.SurfaceType.Smooth
	p.BottomSurface = Enum.SurfaceType.Smooth
	for k, v in props do
		if k ~= "Parent" then
			(p :: any)[k] = v
		end
	end
	p.Parent = props.Parent
	return p
end
Actors.part = part

-- Placeholder getaway car (front = -Z, origin at the floor). Alex: a model named CrewCar in MTL_Actors replaces it
-- (PrimaryPart at floor level, front facing -Z; parts named "Hazard" blink when hazards are on).
Actors.registerProp("CrewCar", function(opts: any): Model
	local m = Instance.new("Model")
	m.Name = "CrewCar"
	local body = Color3.fromRGB(32, 34, 40)
	local base = part({ Name = "Base", Size = Vector3.new(6.4, 0.2, 13), Transparency = 1, CFrame = CFrame.new(0, 0.1, 0), Parent = m })
	part({ Name = "Body", Size = Vector3.new(6.4, 2.2, 13), Color = body, Material = Enum.Material.SmoothPlastic, CFrame = CFrame.new(0, 2.1, 0), Parent = m })
	part({ Name = "Cabin", Size = Vector3.new(5.8, 1.9, 6.4), Color = body, Material = Enum.Material.SmoothPlastic, CFrame = CFrame.new(0, 4.15, 0.6), Parent = m })
	part({ Name = "Glass", Size = Vector3.new(5.9, 1.5, 6.5), Color = Color3.fromRGB(20, 26, 36), Material = Enum.Material.Glass, Transparency = 0.25, CFrame = CFrame.new(0, 4.2, 0.6), Parent = m })
	for i, z in { -4.4, 4.4 } do
		for j, x in { -3.1, 3.1 } do
			part({
				Name = "Wheel",
				Shape = Enum.PartType.Cylinder,
				Size = Vector3.new(0.9, 2.4, 2.4),
				Color = Color3.fromRGB(18, 18, 20),
				CFrame = CFrame.new(x, 1.2, z),
				Parent = m,
			})
			local front = i == 1
			local light = part({
				Name = "Hazard",
				Size = Vector3.new(0.9, 0.4, 0.2),
				Color = Theme.Mission.Hazard,
				Material = Enum.Material.Neon,
				CFrame = CFrame.new(x * 0.8, 2.6, if front then -6.55 else 6.55),
				Transparency = 0.6,
				Parent = m,
			})
			light:SetAttribute("Side", j)
			if front then
				part({ Name = "Headlight", Size = Vector3.new(1.2, 0.5, 0.2), Color = Color3.fromRGB(255, 250, 230), Material = Enum.Material.Neon, CFrame = CFrame.new(x * 0.62, 2.4, -6.55), Parent = m })
			else
				part({ Name = "Taillight", Size = Vector3.new(1.2, 0.5, 0.2), Color = Color3.fromRGB(200, 20, 30), Material = Enum.Material.Neon, CFrame = CFrame.new(x * 0.62, 2.4, 6.55), Parent = m })
			end
		end
	end
	local lamp = Instance.new("PointLight")
	lamp.Name = "HazardLight"
	lamp.Color = Theme.Mission.Hazard
	lamp.Range = 16
	lamp.Brightness = 0
	lamp.Parent = base
	m.PrimaryPart = base
	return m
end)

Actors.registerProp("Mask", function(): Model
	local m = Instance.new("Model")
	m.Name = "Mask"
	local b = part({ Name = "Box", Size = Vector3.new(1.6, 0.8, 1.2), Color = Color3.fromRGB(150, 110, 70), Material = Enum.Material.Cardboard, CFrame = CFrame.new(0, 0.4, 0), Parent = m })
	part({ Name = "Mask", Size = Vector3.new(1, 0.3, 0.9), Color = Color3.fromRGB(20, 20, 22), CFrame = CFrame.new(0, 0.95, 0), Parent = m })
	m.PrimaryPart = b
	return m
end)

-- A prop by name: a template in ReplicatedStorage.MTL_Actors wins over the built-in placeholder.
function Actors.prop(name: string, opts: any?): Model?
	local t = template(name)
	local m: Model? = nil
	if t then
		local was = t.Archivable
		t.Archivable = true
		m = t:Clone()
		t.Archivable = was
		for _, d in (m :: Model):GetDescendants() do
			if d:IsA("BasePart") then
				d.Anchored = true
				d.CanCollide = false
				d.CanQuery = false
			end
		end
	elseif propBuilders[name] then
		m = propBuilders[name](opts or {})
	end
	if not m then
		warn("[MTL Cutscene] unknown prop", name)
		return nil
	end
	strip(m)
	m.Parent = (opts and opts.parent) or folder()
	if opts and opts.hazards then
		Actors.hazards(m, true)
	end
	return m
end

-- Blinking hazard lights on a car prop (parts named "Hazard" + a light named "HazardLight").
function Actors.hazards(m: Model, on: boolean)
	m:SetAttribute("MTL_Hazards", on)
	if not on or m:GetAttribute("MTL_HazardLoop") then
		return
	end
	m:SetAttribute("MTL_HazardLoop", true)
	task.spawn(function()
		while m.Parent and m:GetAttribute("MTL_Hazards") do
			local lit = (os.clock() * 1.4) % 1 < 0.5
			for _, d in m:GetDescendants() do
				if d.Name == "Hazard" and d:IsA("BasePart") then
					d.Transparency = if lit then 0 else 0.6
				elseif d.Name == "HazardLight" and d:IsA("Light") then
					d.Brightness = if lit then 2 else 0
				end
			end
			RunService.Heartbeat:Wait()
		end
		if m.Parent then
			m:SetAttribute("MTL_HazardLoop", nil)
		end
	end)
end

return Actors
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "CarGlow", "ModuleScript", [======[--!strict
-- Makes the map's cars read from across the street (client only, nothing replicates):
--   * the paint gets a little reflectance so it catches the sky, street lights and shop glow instead of
--     sinking into the night shade
--   * at dusk the head lights go white Neon and the tail lights red Neon (bloom makes them glow), and the
--     closest few cars also cast a small red/white light onto the road
-- A car is any Model with a "Color" body part and "Glass" light parts (the map's ParkedCar / Sedan kit).
local RunService = game:GetService("RunService")

local CarGlow = {}

local PAINT_REFLECTANCE = 0.12
local ON_AT = 0.55 -- nightness above which the lights switch on
local LIT_CARS = 10 -- closest cars that get real lights
local LIT_RADIUS = 160
local REFRESH = 0.5

local WHITE = Color3.fromRGB(255, 244, 226)
local RED = Color3.fromRGB(255, 40, 32)

type Light = { part: BasePart, material: Enum.Material, color: Color3, red: boolean }
type Car = { root: BasePart, lights: { Light }, glow: { PointLight } }

local cars: { Car } = {}
local seen: { [Instance]: boolean } = {} -- parts already handled
local lightsOn = false

local function isRedGlass(p: BasePart): boolean
	local c = p.Color
	return c.R > 0.5 and c.G < 0.35 and c.B < 0.35
end

local function isWhiteGlass(p: BasePart): boolean
	local c = p.Color
	return p.Material == Enum.Material.Neon or (c.R > 0.85 and c.G > 0.85 and c.B > 0.85)
end

local byModel: { [Instance]: Car } = {}

-- the car a part belongs to: the closest ancestor Model that has a "Color" body part
local function carModelOf(part: Instance): Model?
	local m = part:FindFirstAncestorWhichIsA("Model")
	while m do
		if m:FindFirstChild("Color", true) then
			return m
		end
		m = m:FindFirstAncestorWhichIsA("Model")
	end
	return nil
end

-- parts stream in one by one, so cars are built up part by part
local function addPart(d: BasePart)
	if seen[d] then
		return
	end
	local isBody = d.Name == "Color"
	local isLight = d.Name == "Glass" or d.Name == "Tail" or d.Name == "Lights"
	if not isBody and not isLight then
		return
	end
	local model = carModelOf(d)
	if not model then
		return
	end
	seen[d] = true
	local car = byModel[model]
	if not car then
		local root = model:FindFirstChild("Color", true) :: BasePart
		car = { root = root, lights = {}, glow = {} }
		byModel[model] = car
		table.insert(cars, car)
	end
	if isBody then
		d.Reflectance = math.max(d.Reflectance, PAINT_REFLECTANCE)
		return
	end
	local red = isRedGlass(d)
	if red or isWhiteGlass(d) then
		local l = { part = d, material = d.Material, color = d.Color, red = red }
		table.insert(car.lights, l)
		if lightsOn then
			d.Material = Enum.Material.Neon
			d.Color = if red then RED else WHITE
		end
	end
end

local function scan(root: Instance)
	for _, d in root:GetDescendants() do
		if d:IsA("BasePart") then
			addPart(d)
		end
	end
end

local function setLights(car: Car, on: boolean)
	for _, l in car.lights do
		if not l.part.Parent then
			continue
		end
		if on then
			l.part.Material = Enum.Material.Neon
			l.part.Color = if l.red then RED else WHITE
		else
			l.part.Material = l.material
			l.part.Color = l.color
		end
	end
end

local function clearGlow(car: Car)
	for _, g in car.glow do
		g:Destroy()
	end
	car.glow = {}
end

local function addGlow(car: Car)
	if #car.glow > 0 then
		return
	end
	local front, back
	for _, l in car.lights do
		if l.red and not back then
			back = l.part
		elseif not l.red and not front then
			front = l.part
		end
	end
	for _, spec in { { front, WHITE, 1.4, 14 }, { back, RED, 0.9, 8 } } do
		local p = spec[1] :: BasePart?
		if p then
			local light = Instance.new("PointLight")
			light.Name = "MTL_CarGlow"
			light.Color = spec[2] :: Color3
			light.Brightness = spec[3] :: number
			light.Range = spec[4] :: number
			light.Shadows = false
			light.Parent = p
			table.insert(car.glow, light)
		end
	end
end

function CarGlow.init(nightness: () -> number)
	local map = workspace:FindFirstChild("ViceBay")
	if map then
		scan(map)
	end
	workspace.DescendantAdded:Connect(function(d)
		if d:IsA("BasePart") then
			addPart(d)
		end
	end)

	local timer = 0
	RunService.Heartbeat:Connect(function(dt)
		timer += dt
		if timer < REFRESH then
			return
		end
		timer = 0
		local on = nightness() >= ON_AT
		if on ~= lightsOn then
			lightsOn = on
			for _, car in cars do
				setLights(car, on)
				if not on then
					clearGlow(car)
				end
			end
		end
		if not on then
			return
		end
		-- real lights only on the closest cars
		local cam = workspace.CurrentCamera.CFrame.Position
		local near = {}
		for _, car in cars do
			if car.root.Parent and #car.lights > 0 then
				local d = (car.root.Position - cam).Magnitude
				if d < LIT_RADIUS then
					table.insert(near, { car = car, d = d })
				end
			end
		end
		table.sort(near, function(a, b)
			return a.d < b.d
		end)
		local keep = {}
		for i = 1, math.min(#near, LIT_CARS) do
			keep[near[i].car] = true
			addGlow(near[i].car)
		end
		for _, car in cars do
			if not keep[car] and #car.glow > 0 then
				clearGlow(car)
			end
		end
	end)
end

return CarGlow
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "ClientData", "ModuleScript", [======[--!strict
-- The client's copy of its own save (public snapshot). Read-only on the client: changes come from the server.
--   ClientData.get() -> snapshot or nil
--   ClientData.Changed:Connect(function(new, old) ... end)
--   ClientData.waitReady() -> snapshot
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Net = require(ReplicatedStorage.MTL.Net)
local Signal = require(ReplicatedStorage.MTL.Signal)

local ClientData = {}
ClientData.Changed = Signal.new()

local current: any = nil

function ClientData.get(): any
	return current
end

function ClientData.waitReady(): any
	while not current do
		ClientData.Changed:Wait()
	end
	return current
end

local function set(snap: any)
	if type(snap) ~= "table" then
		return
	end
	local old = current
	current = snap
	ClientData.Changed:Fire(snap, old)
end

function ClientData.init()
	Net.get("ProfileUpdated").OnClientEvent:Connect(set)
	task.spawn(function()
		local player = Players.LocalPlayer
		while player:GetAttribute("MTL_Ready") ~= true do
			player:GetAttributeChangedSignal("MTL_Ready"):Wait()
		end
		if not current then
			local ok, snap = pcall(function()
				return Net.get("RequestSnapshot"):InvokeServer()
			end)
			if ok and not current then
				set(snap)
			end
		end
	end)
end

return ClientData
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "CutsceneController", "ModuleScript", [======[--!strict
-- Plays cutscenes: data modules in ReplicatedStorage/MTL/Cutscenes/<Id>.lua (Research: Cutscenes).
-- Everything on screen is a pure function of one clock `t` (camera, actors, fades, subtitles), run on RenderStepped,
-- so a SKIP just jumps the clock to the end and runs ONE cleanup path (pcall'd; it always restores the camera,
-- controls, HUD and phone, even if the scene errors). Tap = finish the line / jump to the next line. Hold = skip
-- (after a 1 s grace). Actors and props are local clones: private to this player, free for the server.
--
-- API:
--   Cutscene.play(id, { anchor = CFrame?, token = number?, marks = {Name = Vector3}? }) -> skipped   (yields until done)
--   Cutscene.isPlaying() -> boolean
--   Cutscene.releaseBlack(fadeSeconds?)   end a scene's "holdBlack" (MissionController calls it when its screen
--                                         is ready; it also releases by itself after 6 s)
--   Cutscene.registerAction(name, fn(ctx, action))   custom beats: an action { t = 3, call = "PcScreen" }
--        ctx = { t, anchor, actors = {name -> Actor}, props = {name -> Model}, camera, scene }
--   Cutscene.Started: Signal(id)   Cutscene.Finished: Signal(id, skipped)
-- The server version is CutsceneService.play(player, id, opts) (it fires PlayCutscene and waits for CutsceneDone).
--
-- Scene data (see Cutscenes/GangIntro.lua for a full example). All positions are LOCAL to `anchor`:
--   length, skippable, holdBlack, fadeIn, grade = {TintColor, Saturation, Contrast, Brightness}, dof, ambience
--   actors = { Name = { rig = "Dre" | "@player", at = Vector3 | "@here", face = Vector3 | "@here" | "@Actor", pose? } }
--   props  = { Name = { prop = "CrewCar", at = CFrame, hazards? } }
--   shots  = { { t, from = Cam, to = Cam?, dur?, ease?, fov, fovTo?, handheld? } }
--      Cam = { pos = Vector3, look = Vector3 | "Actor" | "Prop" } | { two = {A, B}, dist?, side?, height? }
--          | { close = A, dist?, side? } | { ots = {listener, speaker}, dist?, side? (shoulder offset, 1.6) }
--          | { path = {Vector3, ...}, look = ... | lookPath = {Vector3, ...} }   (Catmull-Rom spline, smooth through every point)
--          | { gameplay = true, dist?, height? }   right behind the REAL character, where the gameplay camera sits:
--            end a scene on it and the hand-off into play has no snap (Research: Cinematic Cutscenes §5)
--      shot.safe = false skips the wall check (aerials: a look point near a building would pull the camera inside)
--      shot.focus = "Actor" | Vector3 (rack the depth of field to it; default = the look point), shot.blur = 0..1
--   hour = 7.5 (LightingController holds this time of day for this player during the scene, then blends back)
--   music = Theme.Cutscene.Sounds key or id (fades in at the start, out at the end) · stream = { local points to
--   stream in under the opening black } · placePlayer = { at, face } (moves the REAL character there at the start,
--   so a hand-off lands on it)
--   lines  = { { t, who, text, dur? } }
--   actions = { { t, actor, walk = Vector3, dur, ease? } | { t, actor, turn = Vector3 | "@Actor", dur? }
--             | { t, actor, gesture, dur } | { t, actor, pose = "Lean" | "None" } | { t, actor, hide = bool }
--             | { t, prop, move = CFrame, dur, ease? } | { t, sound } | { t, shake, dur } | { t, fade = "in"|"out", dur }
--             | { t, title, sub?, dur } | { t, call = "Name" } }
--   marks  = { Name = Vector3 } (Piece 4) named LOCAL points, so one scene fits any room layout. Any position above
--            (actor at/face, walk, turn, shot pos/look) may be "#Name" or { mark = "Name", off = Vector3 }.
--            Cutscene.play(id, { marks = {...} }) / CutsceneService.play(player, id, { marks }) override them.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local Lighting = game:GetService("Lighting")
local SoundService = game:GetService("SoundService")

local Net = require(ReplicatedStorage.MTL.Net)
local Signal = require(ReplicatedStorage.MTL.Signal)
local Theme = require(ReplicatedStorage.MTL.UI.Theme)
local Motion = require(ReplicatedStorage.MTL.UI.Motion)
local Story = require(ReplicatedStorage.MTL.Config.Story)
local CutsceneRules = require(ReplicatedStorage.MTL.Rules.CutsceneRules)
local Rig = require(ReplicatedStorage.MTL.Rig)
local Build = require(ReplicatedStorage.MTL.UI.Build.Cutscene)
local UIState = require(script.Parent.UIState)
local Actors = require(script.Parent.Actors)

local player = Players.LocalPlayer
local K = Theme.Cutscene

local Cutscene = {}
Cutscene.Started = Signal.new()
Cutscene.Finished = Signal.new()

local gui: any
local playing = false
local stopRequested = false
local blackToken = 0
local customActions: { [string]: (any, any) -> () } = {}

local UP = Vector3.new(0, 1, 0)

local function log(...)
	print("[MTL Cutscene]", ...)
end

local function soundId(key: any): string?
	if type(key) ~= "string" or key == "" then
		return nil
	end
	local fromTheme = (Theme.Mission.Sounds :: any)[key] or (K.Sounds :: any)[key]
	if fromTheme == nil then
		local sfx = ((Theme :: any).Sfx or {})[key] -- the shared UI library (UI/Sfx.lua names), e.g. "PhoneVibrate"
		fromTheme = if type(sfx) == "table" then sfx.id else sfx
	end
	local id = if fromTheme ~= nil then fromTheme else key
	if type(id) ~= "string" or id == "" or id == "rbxassetid://0" then
		return nil
	end
	return id
end

local function playSound(key: any, volume: number?)
	local id = soundId(key)
	if not id then
		return
	end
	local s = Instance.new("Sound")
	s.SoundId = id
	s.Volume = volume or 0.6
	SoundService:PlayLocalSound(s)
	task.delay(4, function()
		s:Destroy()
	end)
end

function Cutscene.registerAction(name: string, fn: (any, any) -> ())
	customActions[name] = fn
end

function Cutscene.isPlaying(): boolean
	return playing
end

-- Everything that isn't ours (the place's stock ticker, chat, player list...) hides during a scene and comes back.
local hiddenGuis: { ScreenGui } = {}
local hiddenCore: { Enum.CoreGuiType } = {}
local function hideOthers(on: boolean)
	local StarterGui = game:GetService("StarterGui")
	if on then
		local pg = player:FindFirstChild("PlayerGui")
		for _, g in (if pg then pg:GetChildren() else {}) do
			if g:IsA("ScreenGui") and g.Enabled and string.sub(g.Name, 1, 4) ~= "MTL_" then
				g.Enabled = false
				table.insert(hiddenGuis, g)
			end
		end
		for _, t in { Enum.CoreGuiType.Chat, Enum.CoreGuiType.PlayerList, Enum.CoreGuiType.Backpack, Enum.CoreGuiType.EmotesMenu } do
			local okGet, was = pcall(function()
				return StarterGui:GetCoreGuiEnabled(t)
			end)
			if okGet and was then
				pcall(function()
					StarterGui:SetCoreGuiEnabled(t, false)
				end)
				table.insert(hiddenCore, t)
			end
		end
	else
		for _, g in hiddenGuis do
			if g.Parent then
				g.Enabled = true
			end
		end
		for _, t in hiddenCore do
			pcall(function()
				StarterGui:SetCoreGuiEnabled(t, true)
			end)
		end
		table.clear(hiddenGuis)
		table.clear(hiddenCore)
	end
end

local function getGui()
	local pg = player:WaitForChild("PlayerGui")
	local existing = pg:FindFirstChild("MTL_Cutscene")
	if existing then
		return existing
	end
	local built = Build.build()
	built.Parent = pg
	return built
end

local function setBars(on: boolean, instant: boolean?)
	local share = K.BarShare
	local top = if on then UDim2.fromScale(0, share) else UDim2.fromScale(0, 0)
	local bottom = if on then UDim2.fromScale(0, 1 - share) else UDim2.fromScale(0, 1)
	if instant then
		gui.BarTop.Position = top
		gui.BarBottom.Position = bottom
	else
		local info = TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		Motion.tween(gui.BarTop, info, { Position = top })
		Motion.tween(gui.BarBottom, info, { Position = bottom })
	end
end

local function skipHintText(): string
	if UserInputService.GamepadEnabled and not UserInputService.KeyboardEnabled then
		return "Hold A to skip"
	elseif UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
		return "Hold to skip"
	end
	return "Hold SPACE to skip"
end

-- Ends a held black screen (fade back to the world).
function Cutscene.releaseBlack(fadeSeconds: number?)
	blackToken += 1
	UIState.pop("CutsceneBlack")
	if not gui or playing then
		return
	end
	local fade = gui.Fade
	local t = Motion.tween(fade, TweenInfo.new(fadeSeconds or 0.6, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), { BackgroundTransparency = 1 })
	local token = blackToken
	t.Completed:Connect(function()
		if token == blackToken and not playing then
			gui.Enabled = false
		end
	end)
end

local function holdBlack()
	blackToken += 1
	local token = blackToken
	gui.Enabled = true
	gui.Fade.BackgroundTransparency = 0
	UIState.push("CutsceneBlack", { hideHUD = true, hidePhone = true, hideWaypoints = true, lockControls = true })
	task.delay(6, function()
		if token == blackToken then
			Cutscene.releaseBlack()
		end
	end)
end

---------------------------------------------------------------- evaluation helpers

type ActorRun = {
	actor: Actors.Actor,
	def: any,
	startPos: Vector3, -- local
	startDir: Vector3, -- local flat facing
	segs: { any },
	floorY: { [number]: number }, -- world floor height at each segment end (index 0 = start)
}

local function flat(v: Vector3): Vector3
	local f = Vector3.new(v.X, 0, v.Z)
	return if f.Magnitude > 1e-4 then f.Unit else Vector3.new(0, 0, -1)
end

local function lerpDir(a: Vector3, b: Vector3, w: number): Vector3
	local ya = math.atan2(-a.X, -a.Z)
	local yb = math.atan2(-b.X, -b.Z)
	local d = (yb - ya + math.pi) % (2 * math.pi) - math.pi
	local y = ya + d * w
	return Vector3.new(-math.sin(y), 0, -math.cos(y))
end

-- Where the camera aims for an actor: a steady point at head height above the ROOT, not the head part itself.
-- The head bobs with the walk/idle animations; aiming at it made the camera wobble (Alex: "it moves around when
-- he walks"). The offset is measured once, when the actor is first looked at.
local function headOf(actor: Actors.Actor): Vector3
	local a = actor :: any
	if a.headOffset == nil then
		local head = actor.model:FindFirstChild("Head") :: BasePart?
		a.headOffset = if head then math.clamp(head.Position.Y - actor.root.Position.Y, 0.8, 4) else 1.5
	end
	return actor.root.Position + Vector3.new(0, a.headOffset, 0)
end

---------------------------------------------------------------- marks (Piece 4)

-- A copy of `scene` with every "#Mark" / { mark, off } position turned into a local Vector3.
local function withMarks(scene: any, marks: any): any
	if scene.marks == nil and marks == nil then
		return scene
	end
	local all: { [string]: Vector3 } = {}
	for k, v in scene.marks or {} do
		all[k] = v
	end
	for k, v in (if type(marks) == "table" then marks else {}) do
		if type(k) == "string" and typeof(v) == "Vector3" then
			all[k] = v
		end
	end
	local function r(v: any): any
		if type(v) == "string" and string.sub(v, 1, 1) == "#" then
			local m = all[string.sub(v, 2)]
			if not m then
				warn("[MTL Cutscene] unknown mark", v)
			end
			return m or Vector3.zero
		elseif type(v) == "table" and type(v.mark) == "string" then
			local m = all[v.mark]
			if not m then
				warn("[MTL Cutscene] unknown mark", v.mark)
			end
			return (m or Vector3.zero) + (if typeof(v.off) == "Vector3" then v.off else Vector3.zero)
		end
		return v
	end
	local function cam(c: any): any
		if type(c) ~= "table" then
			return c
		end
		local out = table.clone(c)
		if out.pos ~= nil then
			out.pos = r(out.pos)
		end
		if out.look ~= nil then
			out.look = r(out.look)
		end
		return out
	end
	local copy = table.clone(scene)
	copy.actors = {}
	for name, def in scene.actors or {} do
		local d = table.clone(def)
		d.at = r(d.at)
		d.face = r(d.face)
		copy.actors[name] = d
	end
	copy.actions = {}
	for i, a in scene.actions or {} do
		local c = table.clone(a)
		if c.walk ~= nil then
			c.walk = r(c.walk)
		end
		if c.turn ~= nil then
			c.turn = r(c.turn)
		end
		copy.actions[i] = c
	end
	copy.shots = {}
	for i, sh in scene.shots or {} do
		local c = table.clone(sh)
		c.from = cam(c.from)
		c.to = cam(c.to)
		copy.shots[i] = c
	end
	return copy
end

---------------------------------------------------------------- play

function Cutscene.play(id: string, opts: { [string]: any }?): boolean
	local o = opts or {}
	if playing then
		stopRequested = true
		while playing do
			task.wait()
		end
	end
	local module = ReplicatedStorage.MTL:FindFirstChild("Cutscenes") and ReplicatedStorage.MTL.Cutscenes:FindFirstChild(id)
	if not module then
		warn("[MTL Cutscene] no scene", id)
		return true
	end
	local okReq, scene = pcall(require, module)
	if not okReq or type(scene) ~= "table" then
		warn("[MTL Cutscene] bad scene", id, scene)
		return true
	end
	local problems = CutsceneRules.validate(scene)
	if #problems > 0 then
		warn("[MTL Cutscene]", id, "has problems:", table.concat(problems, "; "))
	end
	scene = withMarks(scene, o.marks)

	playing = true
	stopRequested = false
	blackToken += 1 -- a new scene takes over any held black
	UIState.pop("CutsceneBlack")
	local length = CutsceneRules.length(scene)
	local camera = workspace.CurrentCamera
	local anchor: CFrame = o.anchor or CFrame.new((player.Character and player.Character:GetPivot().Position) or Vector3.zero)
	local skipped = false
	local finished = false
	local conns: { RBXScriptConnection } = {}
	local actorRuns: { [string]: ActorRun } = {}
	local actors: { [string]: Actors.Actor } = {}
	local props: { [string]: Model } = {}
	local propRuns: { [string]: { base: CFrame, segs: { any } } } = {}
	local effects: { Instance } = {}
	local ambience: Sound? = nil
	local music: Sound? = nil
	local realParts: { BasePart | Decal } = {}
	local savedType = camera.CameraType
	local savedFov = camera.FieldOfView
	local t = 0
	local lastT = -1
	local typedDone: { [number]: boolean } = {}
	local pressStart: number? = nil
	local playClock = 0 -- real seconds since start (for the skip grace)
	local ctx: any = { anchor = anchor, actors = actors, props = props, camera = camera, scene = scene, t = 0 }

	Cutscene.Started:Fire(id, scene)
	log("play", id, string.format("%.1fs", length))

	local function cleanup()
		for _, c in conns do
			c:Disconnect()
		end
		for _, a in actors do
			Actors.destroy(a)
		end
		for _, p in props do
			p:Destroy()
		end
		for _, e in effects do
			e:Destroy()
		end
		for _, snd in { ambience, music } do
			local s = snd :: Sound
			Motion.tween(s, TweenInfo.new(if s == music then 1.5 else 0.5), { Volume = 0 })
			task.delay(1.6, function()
				s:Destroy()
			end)
		end
		for _, p in realParts do
			(p :: any).LocalTransparencyModifier = 0
		end
		local char = player.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		local lastShot = scene.shots and scene.shots[#scene.shots]
		local endsInPlay = lastShot and ((lastShot.to and lastShot.to.gameplay) or lastShot.from.gameplay)
		local handoff = endsInPlay
		if endsInPlay and char then
			local root = char:FindFirstChild("HumanoidRootPart") :: BasePart?
			if skipped and root then
				-- skipped: jump straight to where the hand-off would have ended (behind you), not a random angle
				local spec = if lastShot.to and lastShot.to.gameplay then lastShot.to else lastShot.from
				local focus = root.Position + UP * 1.5
				local back = flat(root.CFrame.LookVector)
				camera.CFrame = CFrame.lookAt(focus - back * (spec.dist or 12) + UP * (spec.height or 3.4), focus)
			end
			camera.Focus = CFrame.new(char:GetPivot().Position + UP * 1.5)
		end
		camera.CameraType = if savedType == Enum.CameraType.Scriptable then Enum.CameraType.Custom else savedType
		if hum then
			camera.CameraSubject = hum
		end
		-- a close hand-off (e.g. indoors: the default 12.5-stud zoom would sit outside the window) keeps its distance:
		-- clamp the zoom for a moment; raising the limit again doesn't zoom back out
		local handDist = handoff and ((lastShot.to and lastShot.to.dist) or lastShot.from.dist)
		if type(handDist) == "number" then
			local maxZoom = player.CameraMaxZoomDistance
			player.CameraMaxZoomDistance = math.max(handDist, player.CameraMinZoomDistance)
			task.delay(0.25, function()
				player.CameraMaxZoomDistance = maxZoom
			end)
		end
		camera.FieldOfView = if savedFov >= 20 and savedFov <= 120 then savedFov else 70
		gui.Subtitle.Speaker.Text = ""
		gui.Subtitle.Line.Text = ""
		gui.Title.Visible = false
		gui.Skip.Visible = false
		setBars(false)
		hideOthers(false)
		player:SetAttribute("MTL_Cutscene", nil)
	end

	local function finish(wasSkipped: boolean)
		if finished then
			return
		end
		finished = true
		skipped = wasSkipped
		local ok, err = pcall(cleanup)
		if not ok then
			warn("[MTL Cutscene] cleanup error:", err)
			camera.CameraType = Enum.CameraType.Custom
		end
		if scene.holdBlack then
			holdBlack()
		else
			Motion.tween(gui.Fade, TweenInfo.new(0.35), { BackgroundTransparency = 1 })
			local token = blackToken
			task.delay(0.4, function()
				if not playing and token == blackToken then
					gui.Enabled = false
				end
			end)
		end
		UIState.pop("Cutscene")
		playing = false
		if o.token then
			Net.get("CutsceneDone"):FireServer({ id = id, token = o.token, skipped = wasSkipped })
		end
		log("done", id, if wasSkipped then "(skipped)" else "")
		Cutscene.Finished:Fire(id, wasSkipped)
	end

	local okSetup, setupErr = pcall(function()
		gui.Enabled = true
		gui.Fade.BackgroundTransparency = 0 -- hide the setup frame
		gui.Title.Visible = false
		gui.Subtitle.Speaker.Text = ""
		gui.Subtitle.Line.Text = ""
		gui.Skip.Visible = false
		gui.Skip.Bar.Fill.Size = UDim2.fromScale(0, 1)
		gui.Skip.Hint.Text = skipHintText()
		setBars(true)
		hideOthers(true)
		player:SetAttribute("MTL_Cutscene", id) -- other camera effects (run sway, shake) must stay off while this is set
		UIState.push("Cutscene", { hideHUD = true, hidePhone = true, hideWaypoints = true, lockControls = true })
		camera.CameraType = Enum.CameraType.Scriptable

		-- hide the real character (the clone stars instead)
		local char = player.Character
		if char then
			for _, d in char:GetDescendants() do
				if d:IsA("BasePart") or d:IsA("Decal") then
					table.insert(realParts, d)
				end
			end
		end
		local here = if char then anchor:ToObjectSpace(char:GetPivot()) else CFrame.new()

		-- actors
		for name, def in scene.actors or {} do
			local actor = Actors.spawn(def.rig)
			if actor then
				actors[name] = actor
				local at = if def.at == "@here" then Vector3.new(here.Position.X, 0, here.Position.Z) else (def.at or Vector3.zero)
				actorRuns[name] = { actor = actor, def = def, startPos = at, startDir = Vector3.new(0, 0, -1), segs = {}, floorY = {} }
			end
		end
		-- facing needs every actor's start position
		for name, run in actorRuns do
			local face = run.def.face
			local dir = Vector3.new(0, 0, -1)
			if typeof(face) == "Vector3" then
				dir = flat(face - run.startPos)
			elseif face == "@here" then
				dir = flat(here.LookVector)
			elseif type(face) == "string" and string.sub(face, 1, 1) == "@" then
				local other = actorRuns[string.sub(face, 2)]
				if other then
					dir = flat(other.startPos - run.startPos)
				end
			end
			run.startDir = dir
		end
		-- motion segments per actor (walk/turn), in order, each starting where the last ended
		for _, a in scene.actions or {} do
			local run = a.actor and actorRuns[a.actor]
			if run and (a.walk or a.turn) then
				table.insert(run.segs, a)
			end
		end
		for name, run in actorRuns do
			local pos = run.startPos
			run.floorY[0] = Actors.floor(anchor:PointToWorldSpace(pos))
			for i, sgm in run.segs do
				if sgm.walk then
					pos = sgm.walk
				end
				run.floorY[i] = Actors.floor(anchor:PointToWorldSpace(pos))
			end
		end
		-- props
		for name, def in scene.props or {} do
			local m = Actors.prop(def.prop, { hazards = def.hazards })
			if m then
				props[name] = m
				local base = def.at or CFrame.new()
				local floorY = Actors.floor(anchor:PointToWorldSpace(base.Position))
				local world = anchor * base
				m:PivotTo(world + Vector3.new(0, floorY - world.Position.Y, 0))
				local segs = {}
				for _, a in scene.actions or {} do
					if a.prop == name and a.move then
						table.insert(segs, a)
					end
				end
				propRuns[name] = { base = base, segs = segs, floorY = floorY } :: any
			end
		end
		-- grade, depth of field, ambience
		if scene.grade then
			local cc = Instance.new("ColorCorrectionEffect")
			cc.Name = "MTL_CutsceneGrade"
			cc.TintColor = scene.grade.TintColor or Color3.new(1, 1, 1)
			cc.Saturation = scene.grade.Saturation or 0
			cc.Contrast = scene.grade.Contrast or 0
			cc.Brightness = scene.grade.Brightness or 0
			cc.Parent = Lighting
			table.insert(effects, cc)
		end
		if scene.dof then
			local dof = Instance.new("DepthOfFieldEffect")
			dof.Name = "MTL_CutsceneDOF"
			dof.FarIntensity = 0.35
			dof.NearIntensity = 0
			dof.InFocusRadius = 7
			dof.FocusDistance = 12
			dof.Parent = Lighting
			table.insert(effects, dof)
			ctx.dof = dof
		end
		local amb = soundId(scene.ambience)
		if amb then
			local s = Instance.new("Sound")
			s.Name = "MTL_Ambience"
			s.SoundId = amb
			s.Looped = true
			s.Volume = 0.35
			s.Parent = gui
			s:Play()
			ambience = s
		end
		local mus = soundId(scene.music)
		if mus then
			local s = Instance.new("Sound")
			s.Name = "MTL_Music"
			s.SoundId = mus
			s.Looped = true
			s.Volume = 0
			s.Parent = gui
			s:Play()
			Motion.tween(s, TweenInfo.new(2, Enum.EasingStyle.Sine), { Volume = scene.musicVolume or 0.4 })
			music = s
		end
		-- the real character stands where the scene will end (hidden until then), so a hand-off lands on it
		if type(scene.placePlayer) == "table" and char then
			local at = scene.placePlayer.at
			local face = scene.placePlayer.face
			if at == "@here" then
				at = Vector3.new(here.Position.X, 0, here.Position.Z)
			end
			if typeof(at) == "Vector3" then
				local floorY = Actors.floor(anchor:PointToWorldSpace(at), { char })
				local w = anchor:PointToWorldSpace(at)
				local root = char:FindFirstChild("HumanoidRootPart") :: BasePart?
				local hip = if root then (char:GetPivot().Position.Y - Actors.floor(char:GetPivot().Position, { char })) else 3
				local pos = Vector3.new(w.X, floorY + math.clamp(hip, 2, 6), w.Z)
				local dir = if typeof(face) == "Vector3" then flat(anchor:PointToWorldSpace(face) - pos) else flat(char:GetPivot().LookVector)
				char:PivotTo(CFrame.lookAt(pos, pos + dir))
				if root then
					root.AssemblyLinearVelocity = Vector3.zero
				end
			end
		end
	end)
	if not okSetup then
		warn("[MTL Cutscene] setup failed:", setupErr)
		finish(true)
		return true
	end
	-- stream far shots in while the screen is still black (StreamingEnabled), never longer than 2.5 s
	if type(scene.stream) == "table" and #scene.stream > 0 then
		local pending = #scene.stream
		for _, lp in scene.stream do
			task.spawn(function()
				pcall(function()
					player:RequestStreamAroundAsync(anchor:PointToWorldSpace(lp), 2.5)
				end)
				pending -= 1
			end)
		end
		local waited = 0
		while pending > 0 and waited < 2.5 do
			waited += task.wait()
		end
	end

	---------------------------------------------------------------- per-frame evaluation

	local function actorTransform(run: ActorRun, now: number): (CFrame, number, number, Vector3)
		local pos, dir = run.startPos, run.startDir
		local floorA = run.floorY[0]
		local floorY = floorA
		local walking, walkDist = 0, 0
		for i, sgm in run.segs do
			local t0 = sgm.t or 0
			if now < t0 then
				break
			end
			local dur = math.max(sgm.dur or 0.4, 0.01)
			local a = math.clamp((now - t0) / dur, 0, 1)
			local floorB = run.floorY[i] or floorA
			if sgm.walk then
				local from, to = pos, sgm.walk :: Vector3
				local e = CutsceneRules.ease(sgm.ease or "Sine", a)
				pos = from:Lerp(to, e)
				local travel = to - from
				if travel.Magnitude > 0.05 then
					dir = lerpDir(dir, flat(travel), math.clamp(a * 5, 0, 1))
				end
				floorY = floorA + (floorB - floorA) * e
				if a < 1 then
					walking = math.min(1, a * 6, (1 - a) * 6)
					walkDist = (to - from).Magnitude * e
				end
			elseif sgm.turn then
				local target: Vector3? = nil
				if typeof(sgm.turn) == "Vector3" then
					target = sgm.turn
				elseif type(sgm.turn) == "string" then
					local other = actorRuns[(string.gsub(sgm.turn, "^@", ""))]
					target = other and other.startPos
				end
				if target then
					dir = lerpDir(dir, flat(target - pos), CutsceneRules.ease("Sine", a))
				end
			end
			floorA = floorB
		end
		local worldPos = anchor:PointToWorldSpace(pos)
		local worldDir = anchor:VectorToWorldSpace(dir)
		local cf = CFrame.lookAt(Vector3.new(worldPos.X, floorY, worldPos.Z), Vector3.new(worldPos.X, floorY, worldPos.Z) + worldDir)
		return cf, walking, walkDist, worldDir
	end

	local function lastOf(list: { any }, now: number, field: string): (any?, any?)
		local cur, prev = nil, nil
		for _, a in list do
			if (a.t or 0) > now then
				break
			end
			if a[field] ~= nil then
				prev = cur
				cur = a
			end
		end
		return cur, prev
	end

	local function actorActions(name: string): { any }
		local out = {}
		for _, a in scene.actions or {} do
			if a.actor == name then
				table.insert(out, a)
			end
		end
		return out
	end
	local perActor: { [string]: { any } } = {}
	for name in actorRuns do
		perActor[name] = actorActions(name)
	end

	local function lookPoint(look: any): Vector3
		if typeof(look) == "Vector3" then
			return anchor:PointToWorldSpace(look)
		elseif type(look) == "string" then
			if actors[look] then
				return headOf(actors[look])
			elseif props[look] then
				return props[look]:GetPivot().Position + Vector3.new(0, 2.5, 0)
			end
		end
		return anchor.Position + UP * 3
	end

	local function spline(points: { Vector3 }, a: number): Vector3
		local n = #points
		if n == 1 then
			return points[1]
		end
		local s = math.clamp(a, 0, 1) * (n - 1)
		local i = math.min(math.floor(s) + 1, n - 1)
		local u = s - (i - 1)
		local p0, p1, p2, p3 = points[math.max(i - 1, 1)], points[i], points[i + 1], points[math.min(i + 2, n)]
		local u2, u3 = u * u, u * u * u
		return 0.5 * ((2 * p1) + (-p0 + p2) * u + (2 * p0 - 5 * p1 + 4 * p2 - p3) * u2 + (-p0 + 3 * p1 - 3 * p2 + p3) * u3)
	end

	local function resolveCam(spec: any, alpha: number?): (Vector3, Vector3)
		if spec.path then
			local a = alpha or 0
			local pos = anchor:PointToWorldSpace(spline(spec.path, a))
			local look = if spec.lookPath then anchor:PointToWorldSpace(spline(spec.lookPath, a)) else lookPoint(spec.look)
			return pos, look
		elseif spec.gameplay then
			local char = player.Character
			local root = char and char:FindFirstChild("HumanoidRootPart") :: BasePart?
			if root then
				local focus = root.Position + UP * 1.5
				local back = flat(root.CFrame.LookVector)
				return focus - back * (spec.dist or 12) + UP * (spec.height or 3.4), focus
			end
		end
		if spec.pos then
			return anchor:PointToWorldSpace(spec.pos), lookPoint(spec.look)
		elseif spec.two then
			local a, b = actors[spec.two[1]], actors[spec.two[2]]
			if a and b then
				local ha, hb = headOf(a), headOf(b)
				local mid = (ha + hb) / 2
				local d = flat(hb - ha)
				local perp = Vector3.new(-d.Z, 0, d.X) * (spec.side or 1)
				return mid + perp * (spec.dist or 12) + UP * (spec.height or 0.5), mid
			end
		elseif spec.close then
			local a = actors[spec.close]
			if a then
				local h = headOf(a)
				local fwd = flat(a.root.CFrame.LookVector)
				local right = flat(a.root.CFrame.RightVector)
				return h + fwd * (spec.dist or 5) + right * 1.3 * (spec.side or 1) + UP * 0.25, h
			end
		elseif spec.ots then
			local l, s = actors[spec.ots[1]], actors[spec.ots[2]]
			if l and s then
				local hl, hs = headOf(l), headOf(s)
				local dir = (hs - hl)
				dir = if dir.Magnitude > 0.01 then dir.Unit else Vector3.new(0, 0, -1)
				local right = dir:Cross(UP)
				right = if right.Magnitude > 0.01 then right.Unit else Vector3.new(1, 0, 0)
				return hl - dir * (spec.dist or 4.5) + right * (spec.side or 1.6) + UP * 0.45, hs
			end
		end
		return anchor.Position + Vector3.new(0, 8, 20), anchor.Position
	end

	local camParams = RaycastParams.new()
	camParams.FilterType = Enum.RaycastFilterType.Exclude
	local function safeCam(pos: Vector3, look: Vector3): Vector3
		local list: { Instance } = { Actors.folder() }
		for _, p in Players:GetPlayers() do
			if p.Character then
				table.insert(list, p.Character)
			end
		end
		camParams.FilterDescendantsInstances = list
		local d = pos - look
		local hit = workspace:Raycast(look, d, camParams)
		if hit then
			return hit.Position - d.Unit * 0.6
		end
		return pos
	end

	local function shakeAt(now: number): Vector3
		local v = Vector3.zero
		for _, a in scene.actions or {} do
			if a.shake and now >= a.t and now < a.t + (a.dur or 0.5) then
				local k = (1 - (now - a.t) / (a.dur or 0.5)) * a.shake
				v += Vector3.new(math.noise(now * 25, 1.3) * k, math.noise(now * 25, 7.1) * k, 0)
			end
		end
		return v
	end

	local function blackAt(now: number): number
		local black = 1 - math.clamp(now / math.max(scene.fadeIn or 0.6, 0.01), 0, 1)
		local f, prevF = lastOf(scene.actions or {}, now, "fade")
		if f then
			local a = math.clamp((now - f.t) / math.max(f.dur or 0.5, 0.01), 0, 1)
			if f.fade == "out" then
				black = math.max(black, a)
			elseif prevF and prevF.fade == "out" then
				black = 1 - a -- fading back in after a fade out (Piece 4: "NEXT DAY")
			else
				black = math.min(black, 1 - a)
			end
			if f.fade == "out" and a >= 1 then
				black = 1
			end
		end
		return black
	end

	local function render(now: number)
		ctx.t = now
		-- actors
		local line, lineIndex = CutsceneRules.lineAt(scene.lines or {}, now)
		for name, run in actorRuns do
			local actor = run.actor
			local cf, walking, walkDist = actorTransform(run, now)
			local list = perActor[name]
			local poseA, poseB = lastOf(list, now, "pose")
			local g: any = nil
			for _, a in list do
				if a.gesture and now >= a.t and now <= a.t + (a.dur or 1.2) then
					g = a
				end
			end
			local hideA = lastOf(list, now, "hide")
			local poseName = if poseA then poseA.pose elseif run.def.pose then run.def.pose else "None"
			local prevName = if poseB then poseB.pose elseif poseA and run.def.pose then run.def.pose else "None"
			local state: any = {
				pose = poseName,
				prevPose = prevName,
				poseT0 = if poseA then poseA.t else -10,
				gesture = if g then g.gesture else nil,
				gestureT0 = if g then g.t else nil,
				gestureDur = if g then g.dur else nil,
				walk = walking,
				walkPhase = walkDist * 1.5,
			}
			-- heads follow whoever is talking (the speaker looks at the player)
			local target: Actors.Actor? = nil
			if line and line.who then
				if line.who == name then
					target = actors.Player
				else
					target = actors[line.who]
				end
			end
			if target and target ~= actor then
				local rel = cf:PointToObjectSpace(headOf(target))
				state.lookYaw = math.atan2(-rel.X, -rel.Z)
			end
			Actors.place(actor, cf, Rig.drop(state))
			Actors.setHidden(actor, hideA ~= nil and hideA.hide == true)
			Actors.render(actor, state, now)
		end
		-- props
		for name, pr in propRuns :: any do
			local m = props[name]
			local cfLocal = pr.base
			for _, sgm in pr.segs do
				if now < sgm.t then
					break
				end
				local a = CutsceneRules.ease(sgm.ease or "Sine", (now - sgm.t) / math.max(sgm.dur or 1, 0.01))
				cfLocal = cfLocal:Lerp(sgm.move, a)
			end
			local world = anchor * cfLocal
			m:PivotTo(world + Vector3.new(0, pr.floorY - (anchor * pr.base).Position.Y, 0))
		end
		-- camera
		local shots = scene.shots
		local si = math.max(CutsceneRules.indexAt(shots, now), 1)
		local shot = shots[si]
		local alpha = CutsceneRules.shotAlpha(shot, now)
		local p1, l1 = resolveCam(shot.from, alpha)
		local pos, look = p1, l1
		if shot.to then
			local p2, l2 = resolveCam(shot.to, alpha)
			pos, look = p1:Lerp(p2, alpha), l1:Lerp(l2, alpha)
		end
		if shot.safe ~= false then
			pos = safeCam(pos, look)
		end
		local fov = shot.fov or 60
		if shot.fovTo then
			fov += (shot.fovTo - fov) * alpha
		end
		local hand = shot.handheld or 0
		local noise = Vector3.zero
		local roll = 0
		if hand > 0 then
			noise = Vector3.new(math.noise(now * 7.3, 0.2), math.noise(now * 8.1, 3.7), math.noise(now * 6.7, 9.1)) * hand * 10
			roll = math.noise(now * 5.3, 4.4) * hand * 0.6
		end
		local shake = shakeAt(now)
		camera.CFrame = CFrame.lookAt(pos + noise + shake, look + noise * 0.5) * CFrame.Angles(0, 0, roll)
		camera.FieldOfView = math.clamp(fov, 20, 80)
		if ctx.dof then
			local focusAt = if shot.focus ~= nil then lookPoint(shot.focus) else look
			ctx.dof.FocusDistance = math.clamp((pos - focusAt).Magnitude, 0, 200)
			ctx.dof.FarIntensity = shot.blur or 0.35
		end
		-- the real character stays hidden (camera scripts may reset it)
		for _, p in realParts do
			(p :: any).LocalTransparencyModifier = 1
		end
		-- fade + title
		gui.Fade.BackgroundTransparency = 1 - blackAt(now)
		local title = nil
		for _, a in scene.actions or {} do
			if a.title and now >= a.t and now <= a.t + (a.dur or 2) then
				title = a
			end
		end
		if title then
			gui.Title.Visible = true
			gui.Title.Main.Text = title.title
			gui.Title.Sub.Text = title.sub or ""
			local lt = now - title.t
			local alphaT = math.min(lt / 0.3, ((title.dur or 2) - lt) / 0.3, 1)
			gui.Title.Main.TextTransparency = 1 - math.clamp(alphaT, 0, 1)
			gui.Title.Sub.TextTransparency = 1 - math.clamp(alphaT - 0.15, 0, 1)
			local rule = gui.Title:FindFirstChild("Rule")
			if rule then
				rule.BackgroundTransparency = 1 - math.clamp(alphaT - 0.1, 0, 1)
				rule.Visible = (title.sub or "") ~= ""
			end
		else
			gui.Title.Visible = false
		end
		-- subtitles
		if line then
			local who = line.who
			local contact = who and (Story.Contacts :: any)[who]
			gui.Subtitle.Speaker.Text = string.upper(if contact then contact.Name else (who or ""))
			gui.Subtitle.Speaker.TextColor3 = (K.Speakers :: any)[who] or K.SpeakerDefault
			gui.Subtitle.Line.Text = line.text
			gui.Subtitle.Line.MaxVisibleGraphemes = if typedDone[lineIndex] then -1 else CutsceneRules.typed(line.text, line.t, now)
		else
			gui.Subtitle.Speaker.Text = ""
			gui.Subtitle.Line.Text = ""
		end
		-- one-shot actions crossed since the last frame
		if now > lastT then
			local late = now - lastT > 0.3 -- seeking: skip sounds
			for _, a in CutsceneRules.crossed(scene.actions or {}, lastT, now) do
				if a.sound and not late then
					playSound(a.sound, a.volume)
				elseif a.title and not late then
					playSound("Title", 0.5)
				elseif a.call and customActions[a.call] then
					local ok, err = pcall(customActions[a.call], ctx, a)
					if not ok then
						warn("[MTL Cutscene] action", a.call, "failed:", err)
					end
				end
			end
		end
		lastT = now
	end

	---------------------------------------------------------------- input: tap = line, hold = skip

	local function tap()
		local lines = scene.lines or {}
		local target, finishLine = CutsceneRules.tapTarget(lines, t)
		if finishLine then
			local _, i = CutsceneRules.lineAt(lines, t)
			typedDone[i] = true
		elseif target and target < length then
			t = target
		end
	end
	local function pressBegin()
		pressStart = os.clock()
	end
	local function pressEnd()
		if pressStart and os.clock() - pressStart < CutsceneRules.SkipHold then
			tap()
		end
		pressStart = nil
		gui.Skip.Bar.Fill.Size = UDim2.fromScale(0, 1)
	end
	local SKIP_KEYS = { [Enum.KeyCode.Space] = true, [Enum.KeyCode.Return] = true, [Enum.KeyCode.ButtonA] = true }
	table.insert(conns, UserInputService.InputBegan:Connect(function(input)
		if SKIP_KEYS[input.KeyCode] then
			pressBegin()
		end
	end))
	table.insert(conns, UserInputService.InputEnded:Connect(function(input)
		if SKIP_KEYS[input.KeyCode] then
			pressEnd()
		end
	end))
	table.insert(conns, gui.Tap.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			pressBegin()
		end
	end))
	table.insert(conns, gui.Tap.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			pressEnd()
		end
	end))

	---------------------------------------------------------------- run

	local done = Instance.new("BindableEvent")
	-- bound LAST in the render step, after every camera script, so nothing (gameplay sway, camera modules) can move
	-- the cutscene camera; unbound with the other connections
	local bindName = "MTL_CutsceneCam"
	table.insert(conns, ({ Disconnect = function()
		RunService:UnbindFromRenderStep(bindName)
	end } :: any))
	RunService:BindToRenderStep(bindName, Enum.RenderPriority.Last.Value, function(dt)
		if finished then
			return
		end
		playClock += dt
		t += dt
		local skippable = scene.skippable ~= false
		if skippable and playClock >= CutsceneRules.SkipGrace then
			gui.Skip.Visible = true
			if pressStart then
				local held = os.clock() - pressStart
				gui.Skip.Bar.Fill.Size = UDim2.fromScale(math.clamp(held / CutsceneRules.SkipHold, 0, 1), 1)
				if held >= CutsceneRules.SkipHold then
					playSound("Skip", 0.4)
					finish(true)
					done:Fire()
					return
				end
			end
		end
		if stopRequested then
			finish(true)
			done:Fire()
			return
		end
		local ok, err = pcall(render, math.min(t, length))
		if not ok then
			warn("[MTL Cutscene] render error:", err)
			finish(true)
			done:Fire()
			return
		end
		if t >= length then
			finish(false)
			done:Fire()
		end
	end)
	-- a respawn mid-scene ends it cleanly
	table.insert(conns, player.CharacterRemoving:Connect(function()
		task.defer(function()
			if not finished then
				finish(true)
				done:Fire()
			end
		end)
	end))
	if not finished then
		done.Event:Wait()
	end
	done:Destroy()
	return skipped
end

function Cutscene.init()
	gui = getGui()
	gui.Enabled = false
	Net.get("PlayCutscene").OnClientEvent:Connect(function(msg)
		if type(msg) ~= "table" or type(msg.id) ~= "string" then
			return
		end
		task.spawn(Cutscene.play, msg.id, {
			anchor = if typeof(msg.anchor) == "CFrame" then msg.anchor else nil,
			token = msg.token,
			marks = if type(msg.marks) == "table" then msg.marks else nil,
		})
	end)
end

return Cutscene
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "GunController", "ModuleScript", [======[--!strict
-- Guns on the client (Piece 5): input, aim camera, firing with instant local effects, recoil, crosshair,
-- hitmarkers, ammo HUD, weapon bar, touch + gamepad, and other players' shot effects.
-- The server decides everything (GunService); this side predicts the ammo counter and draws.
--
-- Controls
--   PC       1-5 take out a gun (same key again or X puts it away) · LMB fire · hold RMB aim · R reload
--   Gamepad  Y next gun (after the last = holster) · R2 fire · L2 aim · B reload
--   Touch    weapon bar at the bottom · FIRE (hold) · AIM (toggle) · R
-- Phone: while the phone is open (or was closed this instant by a click on the world) guns don't fire or aim,
-- and opening it drops the aim. Cutscenes (UIState lockControls) drop the aim and put live guns away.
--
-- API (Master Plan §3.6)
--   GunController.equipped() -> gunId?          GunController.isAiming() -> bool
--   GunController.mode() -> "Live"|"Intimidate"|nil   GunController.state() -> last GunState
--   GunController.equip(gunId) / GunController.holster()   (asks the server)
--   GunController.Changed: Signal()             equip / holster / aim changes
local CollectionService = game:GetService("CollectionService")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")
local UserInputService = game:GetService("UserInputService")
local Workspace = game:GetService("Workspace")
local Lighting = game:GetService("Lighting")

local Net = require(ReplicatedStorage.MTL.Net)
local Signal = require(ReplicatedStorage.MTL.Signal)
local Guns = require(ReplicatedStorage.MTL.Config.Guns)
local GunRules = require(ReplicatedStorage.MTL.Rules.GunRules)
local Theme = require(ReplicatedStorage.MTL.UI.Theme)
local Build = require(ReplicatedStorage.MTL.UI.Build.Gun)
local UIState = require(script.Parent.UIState)
local ClientData = require(script.Parent.ClientData)
local GunFX = require(script.Parent.GunFX)
local GunPose = require(script.Parent.GunPose)
local MovementController = require(script.Parent.MovementController)

local T = Guns.Tuning
local G = Theme.Gun
local C = Theme.Colors

local GunController = {}
GunController.Changed = Signal.new()

local player = Players.LocalPlayer
local rng = Random.new()

-- server truth
local serverState: any = { guns = {} }
-- local (predicted) state of the gun in hand
local equipped: string? = nil
local mode: string? = nil
local def: any = nil
local mag = 0
local reserve = 0
local equipAt = 0
local reloadUntil = 0
local reloadStart = 0
local pendingServer: any = nil -- server state that arrived mid-reload (applied when it ends)
-- input
local trigger = false
local semiQueued = -1
local aimHeld = false
local aimToggle = false
local aiming = false
local nextShot = 0
local bloom = 0
local shots = 0
local hipTurnUntil = 0
local phoneClosedAt = -1
local lastAimSend = 0
local lastAimSent: any = {}
local intimidateTarget: Model? = nil
-- camera
local pitchSpring = { x = 0, v = 0 }
local yawSpring = { x = 0, v = 0 }
local lastPitch, lastYaw = 0, 0
local stayPitch, stayYaw = 0, 0
local assistPitch, assistYaw, assistLeft = 0, 0, 0
local shake = 0
local camTween: Tween? = nil
local offTween: Tween? = nil
local mouseHidden = false
local turnedOff = false -- we switched Humanoid.AutoRotate off to face the aim
-- ui
local gui: ScreenGui
local hitUntil = 0

---------------------------------------------------------------- helpers

local Phone: any = nil
local Jobs: any = nil
local function lazy()
	if not Phone then
		local m = script.Parent:FindFirstChild("PhoneController")
		if m then
			local ok, p = pcall(require, m)
			Phone = if ok then p else false
		end
	end
	if not Jobs then
		local m = script.Parent:FindFirstChild("JobController")
		if m then
			local ok, j = pcall(require, m)
			Jobs = if ok then j else false
		end
	end
end

local function phoneOpen(): boolean
	return Phone and Phone.isOpen and Phone.isOpen() or false
end

local function onShift(): boolean
	local s = Jobs and Jobs.state and Jobs.state()
	return type(s) == "table" and s.onShift == true
end

local function char(): (Model?, Humanoid?, BasePart?)
	local c = player.Character
	if not c then
		return nil, nil, nil
	end
	return c, c:FindFirstChildOfClass("Humanoid"), c:FindFirstChild("HumanoidRootPart") :: BasePart?
end

local function gunModel(c: Model?): Model?
	local m = c and c:FindFirstChild("MTL_Gun")
	return if m and m:IsA("Model") then m else nil
end

local function blocked(): boolean
	if phoneOpen() or os.clock() - phoneClosedAt < 0.2 then
		return true
	end
	local ui = UIState.get()
	if ui.lockControls or ui.hideHUD then
		return true
	end
	if UserInputService:GetFocusedTextBox() then
		return true
	end
	local _, hum = char()
	return not hum or hum.Health <= 0
end

local function reducedMotion(): boolean
	local d = ClientData.get()
	return d ~= nil and d.Settings ~= nil and d.Settings.ReducedMotion == true
end

local function usesMouse(): boolean
	local last = UserInputService:GetLastInputType()
	return UserInputService.MouseEnabled and not (last == Enum.UserInputType.Touch or string.find(last.Name, "Gamepad") ~= nil)
end

local function reloading(): boolean
	return os.clock() < reloadUntil
end

function GunController.equipped(): string?
	return equipped
end
function GunController.mode(): string?
	return mode
end
function GunController.isAiming(): boolean
	return aiming
end
function GunController.state(): any
	return serverState
end

function GunController.equip(gunId: string)
	Net.get("GunAction"):FireServer({ type = "equip", gun = gunId })
end

function GunController.holster(reason: string?)
	if equipped then
		Net.get("GunAction"):FireServer({ type = "holster", reason = reason })
	end
end

---------------------------------------------------------------- raycasts

local castParams = RaycastParams.new()
castParams.FilterType = Enum.RaycastFilterType.Exclude
castParams.IgnoreWater = true

-- Ray that passes through non-colliding scenery (zones, decor) but stops on characters (any part) and walls.
-- Accessories resolve to the body part they're worn on.
local function cast(origin: Vector3, vector: Vector3): (RaycastResult?, BasePart?)
	local c = player.Character
	local ignore: { Instance } = { GunFX.folder() }
	if c then
		table.insert(ignore, c)
	end
	for _ = 1, 6 do
		castParams.FilterDescendantsInstances = ignore
		local r = Workspace:Raycast(origin, vector, castParams)
		if not r then
			return nil, nil
		end
		local inst = r.Instance
		local acc = inst:FindFirstAncestorOfClass("Accessory")
		if acc then
			local w = inst:FindFirstChild("AccessoryWeld") :: any
			local body = w and (if w.Part0 == inst then w.Part1 else w.Part0)
			if body and body:IsA("BasePart") then
				return r, body
			end
			table.insert(ignore, acc)
		elseif GunFX.isCharacterPart(inst) then
			return r, inst :: BasePart
		elseif not inst.CanCollide then
			table.insert(ignore, inst)
		else
			return r, nil
		end
	end
	return nil, nil
end

-- Where on screen the shot goes: the crosshair (centre) when aiming / on touch / on gamepad, else the mouse.
local function aimScreenPoint(): Vector2
	local cam = Workspace.CurrentCamera
	if aiming or not usesMouse() then
		return cam.ViewportSize / 2
	end
	return UserInputService:GetMouseLocation()
end

local function threatModel(model: Model?): boolean
	if not model or not equipped then
		return false
	end
	if CollectionService:HasTag(model, "MTL_Intimidate") then
		return true
	end
	if mode ~= "Live" then
		return false
	end
	local other = Players:GetPlayerFromCharacter(model)
	if other then
		return other ~= player and other:GetAttribute("MTL_Path") == "Criminal" and player:GetAttribute("MTL_Path") == "Criminal"
	end
	return model:GetAttribute("MTL_Damageable") == true
end

local function modelOf(inst: Instance?): Model?
	local cur = inst
	while cur and cur ~= Workspace do
		if cur:IsA("Model") and cur:FindFirstChildOfClass("Humanoid") then
			return cur
		end
		cur = cur.Parent
	end
	return nil
end

---------------------------------------------------------------- HUD

local function ui(path: string): any
	local cur: any = gui
	for name in string.gmatch(path, "[^/]+") do
		cur = cur and cur:FindFirstChild(name)
	end
	return cur
end

local function placeAmmo()
	-- sit just left of the phone (it lives bottom-right); fall back to the built-in position
	local ammo = ui("Ammo")
	local pg = player:FindFirstChild("PlayerGui")
	local phone = pg and pg:FindFirstChild("MTL_Phone")
	local body = phone and phone:FindFirstChild("Body", true) :: GuiObject?
	if ammo and body and body:IsA("GuiObject") and body.AbsoluteSize.X > 0 then
		local cam = Workspace.CurrentCamera
		local x = body.AbsolutePosition.X - 16 - (cam.ViewportSize.X)
		ammo.Position = UDim2.new(1, math.min(-200, x), 1, -24)
	end
end

local function slotKeyLabel(i: number): string
	if UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
		return ""
	end
	return tostring(i)
end

local function refreshBar()
	local bar = ui("WeaponBar")
	if not bar then
		return
	end
	local template = bar:FindFirstChild("SlotTemplate")
	local want: { [string]: boolean } = {}
	for i, g in serverState.guns or {} do
		want["Slot_" .. g.id] = true
		local slot = bar:FindFirstChild("Slot_" .. g.id)
		if not slot and template then
			slot = template:Clone()
			slot.Name = "Slot_" .. g.id
			slot.Visible = true
			slot.Parent = bar
			local id = g.id
			slot.Activated:Connect(function()
				if equipped == id then
					GunController.holster()
				else
					GunController.equip(id)
				end
			end)
		end
		if slot then
			local gdef = Guns.Defs[g.id]
			slot.LayoutOrder = i
			slot.Key.Text = slotKeyLabel(i)
			slot.Title.Text = if gdef then gdef.Display else g.id
			local m = if g.id == equipped then mag else g.mag
			local r = if g.id == equipped then reserve else g.reserve
			slot.Count.Text = if g.mode == "Intimidate" then "story" else (tostring(m) .. " / " .. tostring(r))
			local active = g.id == equipped
			local stroke = slot:FindFirstChild("Stroke") :: UIStroke?
			if stroke then
				stroke.Color = if active then G.SlotActive else C.Stroke
				stroke.Transparency = if active then 0 else C.StrokeTransparency
				stroke.Thickness = if active then 2 else 1
			end
		end
	end
	for _, child in bar:GetChildren() do
		if child:IsA("GuiObject") and child.Name ~= "SlotTemplate" and not want[child.Name] then
			child:Destroy()
		end
	end
	bar.Visible = #(serverState.guns or {}) > 0
end

local function refreshAmmo()
	local ammo = ui("Ammo")
	if not ammo then
		return
	end
	ammo.Visible = equipped ~= nil
	if not equipped or not def then
		return
	end
	ammo.Gun.Text = string.upper(def.Display)
	ammo.Mag.Text = tostring(mag)
	ammo.Reserve.Text = "/ " .. tostring(reserve)
	ammo.Mag.TextColor3 = if mag == 0 then G.Empty elseif mag <= math.ceil(def.Mag * 0.3) then G.Low else C.Text
	local help = ""
	if mag == 0 and reserve == 0 then
		help = if mode == "Live" then "Out of ammo. Get more in the Plug app." else "Out of ammo"
	elseif mag <= math.ceil(def.Mag * 0.3) and reserve > 0 and not reloading() then
		help = if usesMouse() then "R to reload" elseif UserInputService.TouchEnabled then "Tap R to reload" else "B to reload"
	end
	ammo.Help.Text = help
	refreshBar()
end

local function showHitmarker(head: boolean, kill: boolean)
	local hm = ui("Hitmarker")
	if not hm then
		return
	end
	local color = if kill then G.Kill elseif head then G.HitHead else G.Hit
	for _, b in hm:GetChildren() do
		if b:IsA("Frame") then
			b.BackgroundColor3 = color
		end
	end
	local size = if kill then 38 else 28
	hm.Size = UDim2.fromOffset(size * 0.7, size * 0.7)
	hm.Position = UDim2.fromOffset(aimScreenPoint().X, aimScreenPoint().Y)
	hm.Visible = true
	TweenService:Create(hm, TweenInfo.new(0.08, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Size = UDim2.fromOffset(size, size) }):Play()
	hitUntil = os.clock() + T.HitmarkerSeconds * (if kill then 2.5 else 1)
end

local function hurtFlash(from: Vector3?)
	local cam = Workspace.CurrentCamera
	local edge = "Bottom"
	if from then
		local v = cam.CFrame:VectorToObjectSpace(from - cam.CFrame.Position)
		if math.abs(v.X) > math.abs(v.Z) then
			edge = if v.X < 0 then "Left" else "Right"
		else
			edge = if v.Z < 0 then "Top" else "Bottom"
		end
	end
	local hurt = ui("Hurt")
	if not hurt then
		return
	end
	for _, f in hurt:GetChildren() do
		if f:IsA("Frame") then
			f.BackgroundTransparency = if f.Name == edge then 0.15 else 0.75
			TweenService:Create(f, TweenInfo.new(T.HurtSeconds, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { BackgroundTransparency = 1 }):Play()
		end
	end
	shake = math.min(shake + 0.6, 1.5)
end

---------------------------------------------------------------- aim on / off

local function setMouseHidden(hide: boolean)
	if hide ~= mouseHidden then
		mouseHidden = hide
		UserInputService.MouseIconEnabled = not hide
	end
end

local function tweenCamera(fov: number, offset: Vector3)
	local cam = Workspace.CurrentCamera
	local _, hum = char()
	local info = TweenInfo.new(T.AimTween, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
	if camTween then
		camTween:Cancel()
	end
	camTween = TweenService:Create(cam, info, { FieldOfView = fov })
	assert(camTween):Play()
	if hum then
		if offTween then
			offTween:Cancel()
		end
		offTween = TweenService:Create(hum, info, { CameraOffset = offset })
		assert(offTween):Play()
	end
end

local function firstPerson(): boolean
	local c = player.Character
	local head = c and c:FindFirstChild("Head") :: BasePart?
	return head ~= nil and (Workspace.CurrentCamera.CFrame.Position - head.Position).Magnitude < 1.6
end

local function startAimAssist()
	if usesMouse() or not equipped then
		return
	end
	local cam = Workspace.CurrentCamera
	local best, bestAngle = nil :: Vector3?, T.AimAssistDegrees
	local candidates: { Model } = {}
	for _, p in Players:GetPlayers() do
		if p ~= player and p.Character then
			table.insert(candidates, p.Character)
		end
	end
	for _, m in CollectionService:GetTagged("MTL_Intimidate") do
		if m:IsA("Model") then
			table.insert(candidates, m)
		end
	end
	for _, m in candidates do
		if threatModel(m) then
			local part = (m:FindFirstChild("UpperTorso") or m:FindFirstChild("Torso") or m:FindFirstChild("HumanoidRootPart")) :: BasePart?
			if part then
				local d = part.Position - cam.CFrame.Position
				if d.Magnitude <= T.AimAssistRange then
					local look = cam.CFrame.LookVector
					local a = GunRules.angle(look.X, look.Y, look.Z, d.X, d.Y, d.Z)
					if a < bestAngle then
						best, bestAngle = part.Position, a
					end
				end
			end
		end
	end
	if best then
		local v = cam.CFrame:VectorToObjectSpace(best - cam.CFrame.Position)
		assistYaw = math.deg(math.atan2(-v.X, -v.Z))
		assistPitch = math.deg(math.atan2(v.Y, math.sqrt(v.X * v.X + v.Z * v.Z)))
		assistLeft = T.AimAssistSeconds
	end
end

local function setAiming(on: boolean)
	if on == aiming then
		return
	end
	aiming = on
	if on and def then
		tweenCamera(def.AimFov, if firstPerson() then Vector3.zero else T.AimCameraOffset)
		MovementController.setModifier("Aim", T.AimWalkSpeedMult) -- also stops a sprint
		startAimAssist()
	else
		tweenCamera(T.BaseFov, Vector3.zero)
		MovementController.clearModifier("Aim")
		assistLeft = 0
	end
	GunController.Changed:Fire()
end

local function dropInput()
	trigger = false
	semiQueued = -1
	aimHeld = false
	aimToggle = false
	setAiming(false)
end

---------------------------------------------------------------- reload

local function startReload()
	if not equipped or not def or reloading() or not GunRules.canReload(mag, def.Mag, reserve) then
		return
	end
	reloadStart = os.clock()
	reloadUntil = reloadStart + def.Reload
	pendingServer = nil
	Net.get("GunReload"):FireServer({ gun = equipped })
	GunFX.sound(gunModel(player.Character), "ReloadStart")
	local bar = ui("Ammo/Reload")
	if bar then
		bar.Visible = true
	end
	refreshAmmo()
end

local function finishReload()
	reloadUntil = 0
	if def then
		mag, reserve = GunRules.reload(mag, def.Mag, reserve)
	end
	GunFX.sound(gunModel(player.Character), "ReloadEnd")
	local bar = ui("Ammo/Reload")
	if bar then
		bar.Visible = false
	end
	if pendingServer then
		local p = pendingServer
		pendingServer = nil
		for _, g in p.guns or {} do
			if g.id == equipped then
				mag, reserve = g.mag, g.reserve
			end
		end
	end
	refreshAmmo()
end

---------------------------------------------------------------- firing

local function kickCamera()
	if not def then
		return
	end
	local scale = if reducedMotion() then T.ReducedMotionScale else 1
	local up, side = GunRules.recoilKick(def, rng:NextNumber() * 2 - 1, scale * (if aiming then 0.8 else 1))
	local stay, bounce = GunRules.recoilSplit(def, up)
	local sStay, sBounce = GunRules.recoilSplit(def, side)
	stayPitch += stay
	stayYaw += sStay
	pitchSpring.v += GunRules.kickVelocity(bounce, T.RecoilStiffness)
	yawSpring.v += GunRules.kickVelocity(sBounce, T.RecoilStiffness)
	GunPose.kick(def.Recoil.Kick, def.Recoil.KickRot)
end

local function fire()
	local c, hum = char()
	local model = gunModel(c)
	if not c or not hum or not equipped or not def or not model then
		return
	end
	local now = os.clock()
	if now < equipAt + def.EquipTime or reloading() then
		return
	end
	if mag <= 0 then
		GunFX.sound(model, "Empty")
		trigger = false
		if reserve > 0 then
			task.delay(T.AutoReloadDelay, startReload)
		end
		refreshAmmo()
		return
	end
	nextShot = now + GunRules.fireInterval(def)
	mag -= 1
	shots += 1

	local cam = Workspace.CurrentCamera
	local sp = aimScreenPoint()
	local camRay = cam:ViewportPointToRay(sp.X, sp.Y)
	local aimHit = cast(camRay.Origin, camRay.Direction * (def.Range + 30))
	local aimPoint = if aimHit then aimHit.Position else camRay.Origin + camRay.Direction * def.Range
	local head = c:FindFirstChild("Head") :: BasePart?
	local muzzle = GunFX.muzzlePosition(model) or (head and head.Position) or camRay.Origin
	local dir = aimPoint - muzzle
	if dir.Magnitude < 1.5 or dir.Unit:Dot(camRay.Direction) <= 0.2 then
		dir = camRay.Direction
	end
	dir = dir.Unit

	local spread = GunRules.spread(def, {
		aiming = aiming,
		moving = hum.MoveDirection.Magnitude > 0.1,
		airborne = hum.FloorMaterial == Enum.Material.Air,
		bloom = bloom,
	})
	local base = CFrame.lookAt(Vector3.zero, dir)
	local rays = {}
	local pellets = def.Pellets or 1
	for i = 1, pellets do
		local cone = spread + (if pellets > 1 then (def.PelletSpread or 0) else 0)
		local px, py = GunRules.coneOffset(cone, rng:NextNumber(), rng:NextNumber())
		local d = (base * CFrame.Angles(px, py, 0)).LookVector
		local r, body = cast(muzzle, d * def.Range)
		local pos = if r then r.Position else muzzle + d * def.Range
		rays[i] = { pos = pos, part = body }
		if i <= 4 and (pellets > 1 or (shots - 1) % (def.TracerEvery or 1) == 0) then
			GunFX.tracer(muzzle, pos)
		end
		if r then
			GunFX.impact(pos, r.Normal, r.Instance)
		end
	end
	Net.get("GunFire"):FireServer({ gun = equipped, origin = muzzle, dir = dir, t = Workspace:GetServerTimeNow(), rays = rays })

	GunFX.muzzle(model)
	GunFX.sound(model, "Fire")
	GunFX.sound(model, "Tail", 0.6)
	kickCamera()
	bloom = GunRules.bloomAfterShot(def, bloom)
	hipTurnUntil = now + T.HipTurnSeconds
	if not def.Auto then
		trigger = false
	end
	if mag == 0 and reserve > 0 then
		task.delay(T.AutoReloadDelay, startReload)
	end
	refreshAmmo()
end

---------------------------------------------------------------- server events

local function applyState(s: any)
	if type(s) ~= "table" then
		return
	end
	serverState = s
	local was = equipped
	equipped = s.equipped
	mode = s.mode
	if equipped ~= was then
		reloadUntil = 0
		pendingServer = nil
		local bar = ui("Ammo/Reload")
		if bar then
			bar.Visible = false
		end
		if equipped then
			def = Guns.Defs[equipped]
			equipAt = os.clock()
			bloom = 0
			trigger = false
			-- the model arrives with the state; play the equip sound once it's there
			task.delay(0.05, function()
				GunFX.sound(gunModel(player.Character), "Equip", 0.7)
			end)
			if aimHeld or aimToggle then
				setAiming(true)
			end
		else
			def = nil
			dropInput()
		end
		GunController.Changed:Fire()
	end
	if equipped then
		for _, g in s.guns or {} do
			if g.id == equipped then
				if reloading() then
					pendingServer = s
				else
					mag, reserve = g.mag, g.reserve
				end
			end
		end
	end
	refreshAmmo()
	refreshBar()
end

local function otherShot(fx: any)
	local shooter = fx.shooter
	if typeof(shooter) ~= "Instance" or shooter == player or type(fx.ends) ~= "table" then
		return
	end
	local c = (shooter :: Player).Character
	local model = gunModel(c)
	local from = GunFX.muzzlePosition(model) or fx.origin
	if typeof(from) ~= "Vector3" then
		return
	end
	local gdef = Guns.Defs[fx.gun]
	GunFX.muzzle(model)
	GunFX.sound(model, "Fire")
	GunFX.sound(model, "Tail", 0.8)
	for i, pos in fx.ends do
		if i > 4 or typeof(pos) ~= "Vector3" then
			break
		end
		if (gdef and (gdef.Pellets or 1) > 1) or i == 1 then
			GunFX.tracer(from, pos)
		end
		local d = pos - from
		if d.Magnitude > 0.5 then
			castParams.FilterDescendantsInstances = { GunFX.folder(), c :: Instance }
			local r = Workspace:Raycast(from, d + d.Unit * 0.6, castParams)
			if r and (r.Position - pos).Magnitude < 2 then
				GunFX.impact(r.Position, r.Normal, r.Instance)
			end
		end
	end
end

local function onFx(fx: any)
	if type(fx) ~= "table" then
		return
	end
	if fx.type == "shot" then
		otherShot(fx)
	elseif fx.type == "hit" then
		showHitmarker(fx.head == true, fx.kill == true)
		GunFX.ui(if fx.kill then Guns.Sounds.Kill else Guns.Sounds.Hit, if fx.kill then 0.6 else 0.45)
	elseif fx.type == "hurt" then
		hurtFlash(if typeof(fx.from) == "Vector3" then fx.from else nil)
		GunFX.ui(Guns.Sounds.Hurt, 0.5)
	end
end

---------------------------------------------------------------- per frame

local lowHealth: ColorCorrectionEffect? = nil

local function camStep(dt: number)
	local cam = Workspace.CurrentCamera
	-- recoil springs (bounce) + the part that stays (climb) + aim assist, applied as a delta to the camera
	GunRules.springStep(pitchSpring, T.RecoilStiffness, T.RecoilDamping, dt)
	GunRules.springStep(yawSpring, T.RecoilStiffness, T.RecoilDamping, dt)
	local take = math.clamp(dt * 30, 0, 1)
	local sp, sy = stayPitch * take, stayYaw * take
	stayPitch -= sp
	stayYaw -= sy
	local ap, ay = 0, 0
	if assistLeft > 0 then
		local share = math.clamp(dt / assistLeft, 0, 1)
		ap, ay = assistPitch * share, assistYaw * share
		assistPitch -= ap
		assistYaw -= ay
		assistLeft -= dt
	end
	local dPitch = (pitchSpring.x - lastPitch) + sp + ap
	local dYaw = (yawSpring.x - lastYaw) + sy + ay
	lastPitch, lastYaw = pitchSpring.x, yawSpring.x
	local sh = 0
	if shake > 0 then
		shake = math.max(0, shake - dt * 4)
		sh = shake * (if reducedMotion() then T.ReducedMotionScale else 1)
	end
	if math.abs(dPitch) > 1e-5 or math.abs(dYaw) > 1e-5 or sh > 0 then
		local jx = if sh > 0 then (rng:NextNumber() - 0.5) * sh else 0
		local jy = if sh > 0 then (rng:NextNumber() - 0.5) * sh else 0
		cam.CFrame = cam.CFrame * CFrame.Angles(math.rad(dPitch + jx), math.rad(dYaw + jy), 0)
	end

	local c, hum, root = char()
	local now = os.clock()
	if equipped and c and hum and root and hum.Health > 0 then
		-- face where you aim (aiming, or briefly after a hip shot)
		local face = aiming or now < hipTurnUntil
		if face then
			hum.AutoRotate = false
			turnedOff = true
			local look = cam.CFrame.LookVector
			local flat = Vector3.new(look.X, 0, look.Z)
			if flat.Magnitude > 0.05 then
				root.CFrame = CFrame.lookAt(root.Position, root.Position + flat)
			end
		elseif turnedOff then
			hum.AutoRotate = true
			turnedOff = false
		end
		if aiming and usesMouse() and not phoneOpen() then
			UserInputService.MouseBehavior = Enum.MouseBehavior.LockCenter
		end
		local pitch = math.deg(math.asin(math.clamp(cam.CFrame.LookVector.Y, -1, 1)))
		GunPose.setLocal(pitch, face)
	elseif turnedOff then
		turnedOff = false
		if hum then
			hum.AutoRotate = true -- put back what we took (only ours: other systems' AutoRotate is left alone)
		end
	end
end

local function frame(dt: number)
	local now = os.clock()
	if def then
		bloom = GunRules.bloomRecover(def, bloom, dt)
	end
	-- trigger
	if equipped and def and not blocked() then
		local wantAim = aimHeld or aimToggle
		if wantAim ~= aiming then
			setAiming(wantAim)
		end
		if now >= nextShot then
			if trigger then
				fire()
			elseif semiQueued > 0 and now - semiQueued <= T.SemiBuffer then
				semiQueued = -1
				trigger = true
				fire()
			end
		end
	elseif aiming then
		setAiming(false)
	end
	if reloadUntil > 0 and now >= reloadUntil then
		finishReload()
	end

	-- crosshair + hint
	local cam = Workspace.CurrentCamera
	local cross = ui("Crosshair")
	local hint = ui("Hint")
	local hidden = UIState.get().hideHUD == true
	local show = equipped ~= nil and def ~= nil and not phoneOpen() and not hidden
	local isMouse = usesMouse()
	setMouseHidden(show and isMouse)
	if cross then
		cross.Visible = show
		if show and def then
			local _, hum = char()
			local spread = GunRules.spread(def, {
				aiming = aiming,
				moving = hum ~= nil and hum.MoveDirection.Magnitude > 0.1,
				airborne = hum ~= nil and hum.FloorMaterial == Enum.Material.Air,
				bloom = bloom,
			}) + (if (def.Pellets or 1) > 1 then (def.PelletSpread or 0) else 0)
			local gap = math.clamp(GunRules.crosshairGap(spread, cam.FieldOfView, cam.ViewportSize.Y), 3, 120)
			local sp = aimScreenPoint()
			cross.Position = UDim2.fromOffset(sp.X, sp.Y)
			cross.Top.Position = UDim2.fromOffset(0, -gap - 4)
			cross.Bottom.Position = UDim2.fromOffset(0, gap + 4)
			cross.Left.Position = UDim2.fromOffset(-gap - 4, 0)
			cross.Right.Position = UDim2.fromOffset(gap + 4, 0)
			-- threat colour when the crosshair is on someone you can hurt / intimidate
			local ray = cam:ViewportPointToRay(sp.X, sp.Y)
			local r, body = cast(ray.Origin, ray.Direction * math.min(def.Range, 400))
			local m = modelOf(body or (r and r.Instance))
			local threat = threatModel(m)
			local color = if threat then G.CrosshairThreat else G.Crosshair
			for _, b in cross:GetChildren() do
				if b:IsA("Frame") then
					b.BackgroundColor3 = color
				end
			end
			intimidateTarget = if aiming and m and CollectionService:HasTag(m, "MTL_Intimidate") and r and (r.Position - ray.Origin).Magnitude <= T.IntimidateRange + 15 then m else nil
		else
			intimidateTarget = nil
		end
	end
	if hint then
		hint.Visible = show and intimidateTarget ~= nil
		hint.Text = if intimidateTarget then "Keep aiming..." else ""
		hint.TextColor3 = G.CrosshairThreat
		if cross and cross.Visible then
			hint.Position = UDim2.new(0, cross.Position.X.Offset, 0, cross.Position.Y.Offset + 34)
		end
	end
	local hm = ui("Hitmarker")
	if hm and hm.Visible and now >= hitUntil then
		hm.Visible = false
	end
	-- reload bar
	if reloadUntil > 0 and def then
		local fill = ui("Ammo/Reload/Fill")
		if fill then
			fill.Size = UDim2.fromScale(math.clamp((now - reloadStart) / def.Reload, 0, 1), 1)
		end
	end
	-- touch buttons
	local touch = ui("Touch")
	if touch then
		touch.Visible = show and UserInputService.TouchEnabled
		local aimBtn = touch:FindFirstChild("Aim")
		if aimBtn then
			aimBtn.BackgroundColor3 = if aimToggle then G.SlotActive else G.Panel
		end
	end
	local bar = ui("WeaponBar")
	if bar then
		bar.Visible = #(serverState.guns or {}) > 0 and not hidden
	end
	-- aim updates for the server (pose for others + intimidation)
	if equipped and now - lastAimSend >= 1 / T.AimSendHz then
		local pitch = math.floor(math.deg(math.asin(math.clamp(cam.CFrame.LookVector.Y, -1, 1))) + 0.5)
		local raised = aiming or now < hipTurnUntil
		if raised ~= lastAimSent.aiming or math.abs(pitch - (lastAimSent.pitch or 0)) >= 2 or intimidateTarget ~= lastAimSent.target or intimidateTarget then
			lastAimSend = now
			lastAimSent = { aiming = raised, pitch = pitch, target = intimidateTarget }
			Net.get("GunAim"):FireServer({ aiming = aiming, raised = raised, pitch = pitch, target = intimidateTarget })
		end
	end
end

---------------------------------------------------------------- input

local function keyIn(list: { Enum.KeyCode }, key: Enum.KeyCode): boolean
	for _, k in list do
		if k == key then
			return true
		end
	end
	return false
end

local function slotPressed(i: number)
	local g = (serverState.guns or {})[i]
	if not g then
		return
	end
	if equipped == g.id then
		GunController.holster()
	else
		GunController.equip(g.id)
	end
end

local function cycle()
	local list = serverState.guns or {}
	if #list == 0 then
		return
	end
	local idx = 0
	for i, g in list do
		if g.id == equipped then
			idx = i
		end
	end
	if idx >= #list then
		GunController.holster()
	else
		GunController.equip(list[idx + 1].id)
	end
end

local function pressTrigger()
	if not equipped or blocked() then
		return
	end
	trigger = true
	if def and not def.Auto and os.clock() < nextShot then
		semiQueued = os.clock() -- a little early: fire as soon as the gun is ready
		trigger = false
	end
end

local function bindInput()
	local K = Guns.Keys
	UserInputService.InputBegan:Connect(function(input, processed)
		local t = input.UserInputType
		if t == Enum.UserInputType.MouseButton1 then
			if not processed then
				pressTrigger()
			end
			return
		elseif t == Enum.UserInputType.MouseButton2 then
			if not processed and equipped and not blocked() then
				aimHeld = true
			end
			return
		end
		local key = input.KeyCode
		if key == K.FireGamepad then
			pressTrigger()
			return
		elseif key == K.AimGamepad then
			if equipped and not blocked() then
				aimHeld = true
			end
			return
		end
		if processed or blocked() or onShift() then
			return
		end
		if keyIn(K.Reload, key) then
			startReload()
		elseif keyIn(K.Holster, key) then
			GunController.holster()
		elseif keyIn(K.Cycle, key) then
			cycle()
		else
			for i, k in K.Slots do
				if k == key then
					slotPressed(i)
					break
				end
			end
		end
	end)
	UserInputService.InputEnded:Connect(function(input)
		local t = input.UserInputType
		if t == Enum.UserInputType.MouseButton1 or input.KeyCode == K.FireGamepad then
			trigger = false
		elseif t == Enum.UserInputType.MouseButton2 or input.KeyCode == K.AimGamepad then
			aimHeld = false
		end
	end)

	-- touch buttons
	local fireBtn = ui("Touch/Fire")
	if fireBtn then
		fireBtn.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
				pressTrigger()
			end
		end)
		fireBtn.InputEnded:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
				trigger = false
			end
		end)
	end
	local aimBtn = ui("Touch/Aim")
	if aimBtn then
		aimBtn.Activated:Connect(function()
			if equipped then
				aimToggle = not aimToggle
			end
		end)
	end
	local reloadBtn = ui("Touch/Reload")
	if reloadBtn then
		reloadBtn.Activated:Connect(startReload)
	end
end

---------------------------------------------------------------- init

function GunController.init()
	lazy()
	local pg = player:WaitForChild("PlayerGui")
	local existing = pg:FindFirstChild("MTL_Gun")
	if existing and existing:IsA("ScreenGui") then
		gui = existing
	else
		gui = Build.build()
		gui.Parent = pg
	end
	GunFX.init()
	GunPose.init()
	bindInput()

	Net.get("GunState").OnClientEvent:Connect(applyState)
	Net.get("GunFx").OnClientEvent:Connect(onFx)

	RunService:BindToRenderStep("MTL_GunCamera", Enum.RenderPriority.Camera.Value + 1, camStep)
	RunService.RenderStepped:Connect(frame)

	if Phone then
		Phone.Opened:Connect(function()
			dropInput()
		end)
		Phone.Closed:Connect(function()
			phoneClosedAt = os.clock()
		end)
	end
	UIState.Changed:Connect(function(s)
		if s.lockControls or s.hideHUD then
			dropInput()
			if s.lockControls and s.hideHUD and mode == "Live" then
				GunController.holster("cutscene") -- full cutscene: live guns go away (story guns stay)
			end
		end
	end)

	-- low health: the screen drains of colour
	local function watchHealth(c: Model)
		local hum = c:WaitForChild("Humanoid", 10) :: Humanoid?
		if not hum then
			return
		end
		if not lowHealth or not lowHealth.Parent then
			local cc = Instance.new("ColorCorrectionEffect")
			cc.Name = "MTL_LowHealth"
			cc.Parent = Lighting
			lowHealth = cc
		end
		local function upd()
			local h = hum.Health
			local cc = lowHealth :: ColorCorrectionEffect
			local a = if h < T.LowHealth and h > 0 then 1 - h / T.LowHealth else 0
			TweenService:Create(cc, TweenInfo.new(0.3), { Saturation = -0.7 * a, Contrast = 0.1 * a }):Play()
		end
		hum.HealthChanged:Connect(upd)
		upd()
	end
	if player.Character then
		task.spawn(watchHealth, player.Character)
	end
	player.CharacterAdded:Connect(function(c)
		equipped, def, mode = nil, nil, nil
		dropInput()
		task.spawn(watchHealth, c)
	end)

	placeAmmo()
	Workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(placeAmmo)
	task.delay(2, placeAmmo) -- the phone lays itself out after boot

	-- ask for the current state (guns owned) once the save is in
	task.spawn(function()
		ClientData.waitReady()
		Net.get("GunAction"):FireServer({ type = "sync" })
	end)
end

return GunController
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "GunFX", "ModuleScript", [======[--!strict
-- Local-only gun effects (Piece 5), used by GunController for your own shots (instantly) and for other players'
-- shots (from GunFx). Everything is pooled: no Instances are made per shot after warm-up, except sound clones.
--   GunFX.muzzle(gunModel)                         flash + light + smoke at the Muzzle attachment
--   GunFX.tracer(from, to)                         a bright streak that flies from -> to
--   GunFX.impact(pos, normal, hitInstance?)        sparks/dust (+ a bullet hole on anchored parts), blood puff on characters
--   GunFX.sound(gunModel, slot, volumeScale?)      plays a Sound from the gun's Handle (Fire, Tail, Empty, Reload...)
--   GunFX.ui(soundId)                              a 2D UI sound (hit tick, kill)
local Debris = game:GetService("Debris")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local SoundService = game:GetService("SoundService")
local Workspace = game:GetService("Workspace")

local Guns = require(ReplicatedStorage.MTL.Config.Guns)
local Theme = require(ReplicatedStorage.MTL.UI.Theme)

local G = Theme.Gun
local T = Guns.Tuning

local GunFX = {}

local folder: Folder
local function fxFolder(): Folder
	if folder and folder.Parent then
		return folder
	end
	local f = Workspace:FindFirstChild("MTL_GunFX_Local") :: Folder?
	if not f then
		local nf = Instance.new("Folder")
		nf.Name = "MTL_GunFX_Local"
		nf.Parent = Workspace
		f = nf
	end
	assert(f)
	folder = f
	return f
end
GunFX.folder = fxFolder

local function fxPart(name: string): Part
	local p = Instance.new("Part")
	p.Name = name
	p.Anchored = true
	p.CanCollide = false
	p.CanQuery = false
	p.CanTouch = false
	p.CastShadow = false
	p.Material = Enum.Material.Neon
	p.Transparency = 1
	p.Size = Vector3.new(0.1, 0.1, 0.1)
	p.Parent = fxFolder()
	return p
end

---------------------------------------------------------------- muzzle

local function emitter(name: string, props: { [string]: any }): ParticleEmitter
	local e = Instance.new("ParticleEmitter")
	e.Name = name
	e.Enabled = false
	e.Rate = 0
	e.LockedToPart = false
	for k, v in props do
		(e :: any)[k] = v
	end
	return e
end

local function muzzleKit(muzzle: Attachment): Attachment
	local kit = muzzle:FindFirstChild("MTL_FlashKit") :: Attachment?
	if kit then
		return kit
	end
	-- attachments can't hold attachments: the kit lives next to the Muzzle, same CFrame
	local a = Instance.new("Attachment")
	a.Name = "MTL_FlashKit"
	a.CFrame = muzzle.CFrame
	local light = Instance.new("PointLight")
	light.Name = "Light"
	light.Color = G.Flash
	light.Brightness = 5
	light.Range = 12
	light.Shadows = false
	light.Enabled = false
	light.Parent = a
	emitter("Flash", {
		Texture = G.FlashTexture,
		Color = ColorSequence.new(G.Flash),
		LightEmission = 1,
		LightInfluence = 0,
		Lifetime = NumberRange.new(0.03, 0.05),
		Speed = NumberRange.new(0),
		Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.9), NumberSequenceKeypoint.new(1, 0.2) }),
		Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) }),
		Rotation = NumberRange.new(0, 360),
		ZOffset = 0.5,
	}).Parent = a
	emitter("Smoke", {
		Texture = G.SmokeTexture,
		Color = ColorSequence.new(Color3.fromRGB(200, 200, 200)),
		LightInfluence = 1,
		Lifetime = NumberRange.new(0.4, 0.7),
		Speed = NumberRange.new(1, 3),
		SpreadAngle = Vector2.new(15, 15),
		EmissionDirection = Enum.NormalId.Front,
		Acceleration = Vector3.new(0, 2, 0),
		Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.2), NumberSequenceKeypoint.new(1, 0.9) }),
		Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.75), NumberSequenceKeypoint.new(1, 1) }),
	}).Parent = a
	a.Parent = muzzle.Parent
	-- remember it on the muzzle so we find it next time
	local ref = Instance.new("ObjectValue")
	ref.Name = "MTL_FlashKit"
	ref.Value = a
	ref.Parent = muzzle
	return a
end

local function kitFor(gunModel: Instance?): Attachment?
	if not gunModel then
		return nil
	end
	local muzzle = gunModel:FindFirstChild("Muzzle", true) :: Attachment?
	if not muzzle or not muzzle:IsA("Attachment") then
		return nil
	end
	local ref = muzzle:FindFirstChild("MTL_FlashKit") :: ObjectValue?
	if ref and ref.Value and ref.Value.Parent then
		return ref.Value :: Attachment
	end
	if ref then
		ref:Destroy()
	end
	return muzzleKit(muzzle)
end

function GunFX.muzzlePosition(gunModel: Instance?): Vector3?
	local muzzle = gunModel and gunModel:FindFirstChild("Muzzle", true) :: Attachment?
	if muzzle and muzzle:IsA("Attachment") then
		return muzzle.WorldPosition
	end
	return nil
end

function GunFX.muzzle(gunModel: Instance?)
	local kit = kitFor(gunModel)
	if not kit then
		return
	end
	(kit:FindFirstChild("Flash") :: ParticleEmitter):Emit(2);
	(kit:FindFirstChild("Smoke") :: ParticleEmitter):Emit(1)
	local light = kit:FindFirstChild("Light") :: PointLight
	light.Enabled = true
	task.delay(0.05, function()
		light.Enabled = false
	end)
end

---------------------------------------------------------------- tracers

type Tracer = { part: Part, from: Vector3, dir: Vector3, len: number, t: number, total: number }
local tracerPool: { Part } = {}
local flying: { Tracer } = {}

local function getTracer(): Part
	local p = table.remove(tracerPool)
	if p then
		return p
	end
	local np = fxPart("Tracer")
	np.Color = G.Tracer
	return np
end

function GunFX.tracer(from: Vector3, to: Vector3)
	local d = to - from
	local dist = d.Magnitude
	if dist < 2 then
		return
	end
	local p = getTracer()
	p.Size = Vector3.new(T.TracerWidth, T.TracerWidth, math.min(T.TracerLength, dist))
	p.Transparency = 0.1
	table.insert(flying, { part = p, from = from, dir = d.Unit, len = dist, t = 0, total = math.max(dist / T.TracerSpeed, 1 / 60) })
end

---------------------------------------------------------------- impacts

local impactAtt: Attachment? = nil
local function impactKit(): Attachment
	if impactAtt and impactAtt.Parent then
		return impactAtt
	end
	local a = Instance.new("Attachment")
	a.Name = "MTL_ImpactKit"
	emitter("Sparks", {
		Texture = G.SparkTexture,
		Color = ColorSequence.new(G.Spark),
		LightEmission = 1,
		Lifetime = NumberRange.new(0.08, 0.2),
		Speed = NumberRange.new(10, 22),
		SpreadAngle = Vector2.new(40, 40),
		EmissionDirection = Enum.NormalId.Front,
		Acceleration = Vector3.new(0, -60, 0),
		Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.12), NumberSequenceKeypoint.new(1, 0) }),
		Drag = 4,
	}).Parent = a
	emitter("Dust", {
		Texture = G.SmokeTexture,
		Color = ColorSequence.new(G.Dust),
		Lifetime = NumberRange.new(0.3, 0.6),
		Speed = NumberRange.new(2, 5),
		SpreadAngle = Vector2.new(30, 30),
		EmissionDirection = Enum.NormalId.Front,
		Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.3), NumberSequenceKeypoint.new(1, 1) }),
		Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.5), NumberSequenceKeypoint.new(1, 1) }),
		Drag = 3,
	}).Parent = a
	emitter("Blood", {
		Color = ColorSequence.new(G.Blood),
		Lifetime = NumberRange.new(0.15, 0.3),
		Speed = NumberRange.new(3, 7),
		SpreadAngle = Vector2.new(35, 35),
		EmissionDirection = Enum.NormalId.Front,
		Acceleration = Vector3.new(0, -30, 0),
		Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.15), NumberSequenceKeypoint.new(1, 0.05) }),
		Drag = 2,
	}).Parent = a
	a.Parent = Workspace.Terrain
	impactAtt = a
	return a
end

local holes: { Part } = {}
local holeNext = 1

local function hole(pos: Vector3, normal: Vector3)
	local p = holes[holeNext]
	if not p then
		p = fxPart("BulletHole")
		p.Material = Enum.Material.SmoothPlastic
		p.Color = G.Hole
		p.Shape = Enum.PartType.Cylinder
		p.Size = Vector3.new(0.02, 0.22, 0.22)
		holes[holeNext] = p
	end
	assert(p)
	holeNext = holeNext % T.MaxImpacts + 1
	-- cylinder axis is X: point it along the surface normal
	p.CFrame = CFrame.lookAt(pos + normal * 0.01, pos + normal * 2) * CFrame.Angles(0, math.rad(90), 0)
	p.Transparency = 0.05
	local mine = p
	task.delay(T.ImpactSeconds, function()
		if mine.CFrame.Position:FuzzyEq(pos + normal * 0.01, 0.05) then
			mine.Transparency = 1
		end
	end)
end

local function isCharacterPart(inst: Instance?): boolean
	local cur = inst
	while cur and cur ~= Workspace do
		if cur:IsA("Model") and cur:FindFirstChildOfClass("Humanoid") then
			return true
		end
		cur = cur.Parent
	end
	return false
end
GunFX.isCharacterPart = isCharacterPart

function GunFX.impact(pos: Vector3, normal: Vector3?, hit: Instance?)
	local n = if normal and normal.Magnitude > 0.5 then normal.Unit else Vector3.yAxis
	local kit = impactKit()
	kit.WorldCFrame = CFrame.lookAt(pos, pos + n)
	if isCharacterPart(hit) then
		(kit:FindFirstChild("Blood") :: ParticleEmitter):Emit(4)
		return
	end
	(kit:FindFirstChild("Sparks") :: ParticleEmitter):Emit(5);
	(kit:FindFirstChild("Dust") :: ParticleEmitter):Emit(2)
	if hit and hit:IsA("BasePart") and hit.Anchored and hit.Transparency < 0.5 then
		hole(pos, n)
	end
end

---------------------------------------------------------------- sounds

local function soundsOn(): boolean
	local ok, ClientData = pcall(function()
		return require(script.Parent.ClientData)
	end)
	local d = ok and ClientData.get() or nil
	return not (d and d.Settings and d.Settings.Sound == false)
end

function GunFX.sound(gunModel: Instance?, slot: string, volumeScale: number?)
	if not gunModel or not soundsOn() then
		return
	end
	local handle = gunModel:FindFirstChild("Handle", true)
	local s = handle and handle:FindFirstChild(slot) :: Sound?
	if not s or not s:IsA("Sound") or s.SoundId == "" then
		return
	end
	local c = s:Clone()
	c.Volume = s.Volume * (volumeScale or 1)
	c.PlaybackSpeed = s.PlaybackSpeed * (0.95 + math.random() * 0.1) -- tiny pitch variation so rapid fire isn't robotic
	c.Parent = handle
	c:Play()
	Debris:AddItem(c, 4)
end

local uiSounds: { [string]: Sound } = {}
function GunFX.ui(id: string, volume: number?)
	if id == "" or not soundsOn() then
		return
	end
	local s = uiSounds[id]
	if not s then
		local ns = Instance.new("Sound")
		ns.SoundId = id
		ns.Volume = volume or 0.5
		ns.Parent = SoundService
		uiSounds[id] = ns
		s = ns
	end
	SoundService:PlayLocalSound(s :: Sound)
end

---------------------------------------------------------------- update

function GunFX.init()
	fxFolder()
	RunService.RenderStepped:Connect(function(dt)
		for i = #flying, 1, -1 do
			local f = flying[i]
			f.t += dt
			local a = math.clamp(f.t / f.total, 0, 1)
			local headDist = f.len * a
			local segLen = math.min(f.part.Size.Z, headDist)
			local headPos = f.from + f.dir * headDist
			local mid = headPos - f.dir * (segLen / 2)
			f.part.CFrame = CFrame.lookAt(mid, headPos)
			if a >= 1 then
				f.part.Transparency = 1
				table.insert(tracerPool, f.part)
				table.remove(flying, i)
			end
		end
	end)
end

return GunFX
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "GunPose", "ModuleScript", [======[--!strict
-- Procedural arm pose while a gun is out (Piece 5). No animation assets yet, so the arms are posed in code,
-- after the Animator runs each frame (RunService.PreSimulation), on every character whose MTL_Gun attribute
-- names a gun. Your own pitch comes from the camera; other players' from their MTL_AimPitch attribute.
--   aiming / just fired -> arms straight at the aim pitch, left hand on the gun (TwoHanded)
--   otherwise           -> "low ready": same, tipped down by Tuning.LowReadyPitch
-- R15 only (R6 characters just hold the gun at their side). TODO(Alex anims): when real hold/aim/reload
-- animations exist, play them from GunController and turn this off (GunPose.enabled = false).
--   GunPose.setLocal(pitchDeg, raised)   GunPose.kick(amount)   (local gun model kick, studs)
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local Guns = require(ReplicatedStorage.MTL.Config.Guns)

local T = Guns.Tuning

local GunPose = {}
GunPose.enabled = true

local localPitch = 0
local localRaised = false
local kickBack = 0
local kickRot = 0

function GunPose.setLocal(pitchDeg: number, raised: boolean)
	localPitch = pitchDeg
	localRaised = raised
end

function GunPose.kick(back: number, rotDeg: number)
	kickBack = math.min(kickBack + back, 0.6)
	kickRot = math.min(kickRot + rotDeg, 25)
end

type Rig = { right: Motor6D?, left: Motor6D?, grip: Motor6D? }
local rigs: { [Model]: Rig } = {}
local smooth: { [Model]: number } = {}

local function rigOf(char: Model): Rig
	local r = rigs[char]
	if r and r.right and r.right.Parent then
		local gun = char:FindFirstChild("MTL_Gun")
		local grip = gun and gun:FindFirstChild("MTL_GunGrip", true) :: Motor6D?
		r.grip = grip
		return r
	end
	local ua = char:FindFirstChild("RightUpperArm")
	local la = char:FindFirstChild("LeftUpperArm")
	local nr: Rig = {
		right = ua and ua:FindFirstChild("RightShoulder") :: Motor6D?,
		left = la and la:FindFirstChild("LeftShoulder") :: Motor6D?,
		grip = nil,
	}
	rigs[char] = nr
	return nr
end

local function pose(char: Model, pitch: number, raised: boolean, twoHanded: boolean, isLocal: boolean, dt: number)
	local r = rigOf(char)
	if not r.right then
		return
	end
	-- ease between low ready and raised so taking aim reads as a motion, not a pop
	local target = if raised then pitch else pitch + T.LowReadyPitch
	local cur = smooth[char] or target
	cur += (target - cur) * math.clamp(dt * 18, 0, 1)
	smooth[char] = cur
	local p = math.rad(90 + cur)
	r.right.Transform = CFrame.Angles(0, math.rad(12), 0) * CFrame.Angles(p, 0, 0)
	if twoHanded and r.left then
		r.left.Transform = CFrame.Angles(0, math.rad(-38), 0) * CFrame.Angles(p + math.rad(4), 0, 0)
	end
	if isLocal and r.grip then
		r.grip.Transform = CFrame.new(0, 0, kickBack) * CFrame.Angles(math.rad(kickRot), 0, 0)
	end
end

function GunPose.init()
	local me = Players.LocalPlayer
	local step = RunService.PreSimulation
	step:Connect(function(dt)
		-- the local kick springs back
		local decay = math.clamp(dt * T.KickRecover, 0, 1)
		kickBack -= kickBack * decay
		kickRot -= kickRot * decay
		if not GunPose.enabled then
			return
		end
		for _, plr in Players:GetPlayers() do
			local char = plr.Character
			if char then
				local gunId = char:GetAttribute("MTL_Gun")
				if type(gunId) == "string" and gunId ~= "" then
					local def = Guns.Defs[gunId]
					local isLocal = plr == me
					local pitch = if isLocal then localPitch else (char:GetAttribute("MTL_AimPitch") or 0) :: number
					local raised = if isLocal then localRaised else char:GetAttribute("MTL_Aiming") == true
					pose(char, pitch, raised, def ~= nil and def.TwoHanded == true, isLocal, dt)
				else
					smooth[char] = nil
				end
			end
		end
	end)
	Players.PlayerRemoving:Connect(function(plr)
		if plr.Character then
			rigs[plr.Character] = nil
			smooth[plr.Character] = nil
		end
	end)
end

return GunPose
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "HUDController", "ModuleScript", [======[--!strict
-- Cash pill, level + health rings, objective line, toasts, reward pops, level-up banner.
-- (The icon menu is MenuController, the hotbar HotbarController, world markers MapMarkers.)
-- Uses PlayerGui.MTL_HUD (cloned from StarterGui, where Alex can reskin it); builds one only if it's missing.
--   HUD.objective(text)  HUD.toast(text, color?)  HUD.banner(title, sub?, color?)
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local SoundService = game:GetService("SoundService")

local Net = require(ReplicatedStorage.MTL.Net)
local Theme = require(ReplicatedStorage.MTL.UI.Theme)
local Motion = require(ReplicatedStorage.MTL.UI.Motion)
local Format = require(ReplicatedStorage.MTL.Format)
local LevelRules = require(ReplicatedStorage.MTL.Rules.LevelRules)
local Build = require(ReplicatedStorage.MTL.UI.Build.HUD)
local ClientData = require(script.Parent.ClientData)
local UIState = require(script.Parent.UIState)

local player = Players.LocalPlayer
local HUD = {}

local gui: any
local shownCash = 0
local shownLevel = 0
local shownProgress = 0
local objectiveText = ""
local bannerQueue: { { title: string, sub: string?, color: Color3? } } = {}
local bannerBusy = false
local MAX_TOASTS = 4

local function sound(id: string?, volume: number?)
	if not id or id == "" or id == "rbxassetid://0" then
		return
	end
	local s = Instance.new("Sound")
	s.SoundId = id
	s.Volume = volume or 0.5
	SoundService:PlayLocalSound(s)
	task.delay(3, function()
		s:Destroy()
	end)
end

local function getGui()
	local pg = player:WaitForChild("PlayerGui")
	local existing = pg:FindFirstChild("MTL_HUD")
	if existing then
		return existing
	end
	local built = Build.build()
	built.Parent = pg
	return built
end

-- tweens a number and calls fn(value) every frame (ring fills)
local ringTween: Tween? = nil
local function tweenValue(from: number, to: number, duration: number, fn: (number) -> ())
	if ringTween then
		ringTween:Cancel()
	end
	local v = Instance.new("NumberValue")
	v.Value = from
	v.Changed:Connect(fn)
	local t = Motion.tween(v, TweenInfo.new(duration, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Value = to })
	ringTween = t
	t.Completed:Once(function(state)
		if state == Enum.PlaybackState.Completed then
			fn(to)
		end
		v:Destroy()
	end)
end

local function setLevel(level: number, xp: number)
	local ring = gui.Top.Status.Level
	local p = LevelRules.progress(level, xp)
	if level ~= shownLevel and shownLevel ~= 0 then
		-- fill to the end, snap to 0, fill to the new progress
		tweenValue(shownProgress, 1, 0.25, function(v)
			Build.setRing(ring, v)
		end)
		task.wait(0.3)
		shownProgress = 0
	end
	local from = shownProgress
	shownProgress = p
	tweenValue(from, p, 0.5, function(v)
		Build.setRing(ring, v)
	end)
	shownLevel = level
	ring.Center.Num.Text = tostring(level)
	local xpBox = gui.Top.Status.XP
	xpBox.Title.Text = "LEVEL " .. level
	local need = LevelRules.need(level)
	xpBox.Text.Text = if need == math.huge then "MAX" else string.format("%s / %s XP", Format.short(xp), Format.short(need))
end

local function bump(frame: GuiObject)
	local scale = frame:FindFirstChild("Bump") or Instance.new("UIScale")
	scale.Name = "Bump"
	scale.Parent = frame
	scale.Scale = 1.08
	Motion.tween(scale, Motion.Spring, { Scale = 1 })
end

local function render(data: any)
	if not data then
		return
	end
	local cashLabel = gui.Top.Cash.Amount
	if data.Cash ~= shownCash then
		local first = shownCash == 0
		Motion.count(cashLabel, shownCash, data.Cash, if first then 0.01 else 0.6, Format.cash)
		if not first and data.Cash > shownCash then
			bump(gui.Top.Cash)
		end
		shownCash = data.Cash
	end
	setLevel(data.Level, data.XP)

	local b = data.Boosts or {}
	local parts = {}
	if player:GetAttribute("MTL_Pass_Cash2x") or (b.Cash2xSeconds or 0) > 0 then
		table.insert(parts, "2x CASH")
	end
	if player:GetAttribute("MTL_Pass_XP2x") or (b.XP2xSeconds or 0) > 0 then
		table.insert(parts, "2x XP")
	end
	gui.Top.Status.Boosts.Text = table.concat(parts, "  ")
end

-- health ring follows the character
local function watchHealth(char: Model)
	local hum = char:WaitForChild("Humanoid", 10) :: Humanoid?
	if not hum then
		return
	end
	local ring = gui.Top.Status.Health
	local H = Theme.HUD
	local function update()
		local p = if hum.MaxHealth > 0 then hum.Health / hum.MaxHealth else 0
		Build.setRing(ring, p, if p < 0.35 then H.HealthLow else H.Health)
	end
	update()
	hum.HealthChanged:Connect(update)
	hum:GetPropertyChangedSignal("MaxHealth"):Connect(update)
end

-- smaller screens get a smaller HUD (phones), never bigger than designed
local function fitScale()
	local cam = workspace.CurrentCamera
	local function apply()
		local v = cam.ViewportSize
		local s = math.clamp(math.min(v.X / 1280, v.Y / 760), 0.62, 1)
		for _, name in { "Top", "Menu", "Hotbar" } do
			local f = gui:FindFirstChild(name)
			local sc = f and f:FindFirstChild("Scale")
			if sc then
				sc.Scale = s
			end
		end
	end
	apply()
	cam:GetPropertyChangedSignal("ViewportSize"):Connect(apply)
end

function HUD.objective(text: string)
	if text == objectiveText then
		return
	end
	objectiveText = text
	local frame = gui.Objective
	local label = frame.Text
	if text == "" then
		frame.Visible = false
		return
	end
	-- old line out (fade), new line in (drop from above)
	if frame.Visible then
		Motion.tween(label, Motion.Fast, { TextTransparency = 1 }).Completed:Wait()
	end
	label.Text = text
	frame.Position = UDim2.new(0.5, 0, 0, 54)
	label.TextTransparency = 1
	frame.Visible = true
	Motion.tween(frame, Motion.Spring, { Position = UDim2.new(0.5, 0, 0, 64) })
	Motion.tween(label, Motion.Normal, { TextTransparency = 0 })
end

function HUD.toast(text: string, color: Color3?)
	local list = gui.Toasts
	local rows = {}
	for _, c in list:GetChildren() do
		if c:IsA("GuiObject") then
			table.insert(rows, c)
		end
	end
	if #rows >= MAX_TOASTS then
		table.sort(rows, function(a, b)
			return a.LayoutOrder < b.LayoutOrder
		end)
		rows[1]:Destroy()
	end
	local row = Build.toast(text, color)
	row.LayoutOrder = math.floor(os.clock() * 1000) % 2e9
	row.BackgroundTransparency = 1
	row.Text.TextTransparency = 1
	row.Parent = list
	Motion.tween(row, Motion.Normal, { BackgroundTransparency = Theme.Colors.GlassTransparency })
	Motion.tween(row.Text, Motion.Normal, { TextTransparency = 0 })
	task.delay(4, function()
		if row.Parent then
			Motion.tween(row, Motion.Slow, { BackgroundTransparency = 1 })
			Motion.tween(row.Text, Motion.Slow, { TextTransparency = 1 }).Completed:Wait()
			row:Destroy()
		end
	end)
end

local function runBanners()
	if bannerBusy then
		return
	end
	bannerBusy = true
	while #bannerQueue > 0 do
		local item = table.remove(bannerQueue, 1) :: any
		local banner = gui.Banner
		banner.Title.Text = item.title
		banner.Title.TextColor3 = item.color or Theme.Colors.Gold
		banner.Sub.Text = item.sub or ""
		banner.Title.TextTransparency = 1
		banner.Sub.TextTransparency = 1
		banner.Size = UDim2.fromOffset(420, 72)
		banner.Visible = true
		Motion.tween(banner, Motion.Spring, { Size = UDim2.fromOffset(520, 90) })
		Motion.tween(banner.Title, Motion.Fast, { TextTransparency = 0 })
		Motion.tween(banner.Sub, Motion.Normal, { TextTransparency = 0 })
		task.wait(2.2)
		Motion.tween(banner.Title, Motion.Normal, { TextTransparency = 1 })
		Motion.tween(banner.Sub, Motion.Normal, { TextTransparency = 1 }).Completed:Wait()
		banner.Visible = false
		task.wait(0.2)
	end
	bannerBusy = false
end

function HUD.banner(title: string, sub: string?, color: Color3?)
	table.insert(bannerQueue, { title = title, sub = sub, color = color })
	task.spawn(runBanners)
end

local function pop(text: string, color: Color3, delay: number)
	task.delay(delay, function()
		local label = Build.pop(text, color)
		label.Parent = gui.Pops
		label.TextTransparency = 1
		Motion.tween(label, Motion.Fast, { TextTransparency = 0 })
		Motion.tween(label, Motion.Slow, { Position = UDim2.new(1, 0, 0, -10) })
		task.wait(0.9)
		Motion.tween(label, Motion.Normal, { TextTransparency = 1 })
		task.wait(0.3)
		label:Destroy()
	end)
end

function HUD.init()
	gui = getGui()

	ClientData.Changed:Connect(function(data)
		task.spawn(render, data)
	end)
	if ClientData.get() then
		render(ClientData.get())
	end

	UIState.Changed:Connect(function(state)
		gui.Enabled = not state.hideHUD
	end)

	fitScale()
	if player.Character then
		task.spawn(watchHealth, player.Character)
	end
	player.CharacterAdded:Connect(watchHealth)

	local saved = player:GetAttribute("MTL_Objective")
	if type(saved) == "string" then
		task.spawn(HUD.objective, saved)
	end

	Net.get("Notify").OnClientEvent:Connect(function(msg)
		if type(msg) ~= "table" or type(msg.text) ~= "string" then
			return
		end
		if msg.kind == "objective" then
			task.spawn(HUD.objective, msg.text)
		elseif msg.kind == "banner" then
			HUD.banner(msg.text, msg.sub, msg.color)
		else
			HUD.toast(msg.text, msg.color)
		end
	end)

	Net.get("Reward").OnClientEvent:Connect(function(r)
		if type(r) ~= "table" then
			return
		end
		if r.cash then
			pop("+" .. Format.cash(r.cash), Theme.Colors.Accent, 0)
		end
		if r.xp then
			pop("+" .. r.xp .. " XP", Theme.Colors.AccentAlt, 0.12)
		end
	end)

	Net.get("LevelUp").OnClientEvent:Connect(function(info)
		if type(info) ~= "table" then
			return
		end
		local unlocks = info.unlocks or {}
		HUD.banner("LEVEL " .. tostring(info.level), unlocks[1], Theme.Colors.Gold)
		sound(Theme.Sounds and Theme.Sounds.LevelUp)
		for i = 2, #unlocks do
			HUD.toast(unlocks[i], Theme.Colors.Gold)
		end
	end)
end

return HUD
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "HotbarController", "ModuleScript", [======[--!strict
-- The hotbar at the bottom centre (MTL_HUD/Hotbar): round slots with the key number above.
--   Slot 1 = your fists (puts any gun away), then the guns you own (GunController, keys 2-6),
--   then any Roblox Tools in your Backpack (next free numbers). Replaces the gun piece's WeaponBar and the
--   default Roblox backpack bar, so there is only one row of slots on screen.
-- Gun keys live in Config/Guns.Keys (Slots start at Two, One is in Holster).
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local StarterGui = game:GetService("StarterGui")
local UserInputService = game:GetService("UserInputService")

local Theme = require(ReplicatedStorage.MTL.UI.Theme)
local Motion = require(ReplicatedStorage.MTL.UI.Motion)
local Config = require(ReplicatedStorage.MTL.Config.HUD)
local Guns = require(ReplicatedStorage.MTL.Config.Guns)
local UIState = require(script.Parent.UIState)

local player = Players.LocalPlayer
local H = Theme.HUD

local Hotbar = {}

local gui: any
local guns: any = nil -- GunController (optional)
local lastKey = ""
local TOOL_KEYS = {
	Enum.KeyCode.One, Enum.KeyCode.Two, Enum.KeyCode.Three, Enum.KeyCode.Four, Enum.KeyCode.Five,
	Enum.KeyCode.Six, Enum.KeyCode.Seven, Enum.KeyCode.Eight, Enum.KeyCode.Nine,
}

type SlotSpec = { id: string, key: number, name: string, emoji: string, image: string?, active: boolean, press: () -> () }

local function touchOnly(): boolean
	return UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
end

local function equippedTool(): Tool?
	local char = player.Character
	return char and char:FindFirstChildOfClass("Tool")
end

local function backpackTools(): { Tool }
	local list = {}
	local bp = player:FindFirstChildOfClass("Backpack")
	if bp then
		for _, t in bp:GetChildren() do
			if t:IsA("Tool") then
				table.insert(list, t)
			end
		end
	end
	local held = equippedTool()
	if held then
		table.insert(list, held)
	end
	table.sort(list, function(a, b)
		return a.Name < b.Name
	end)
	return list
end

local function specs(): { SlotSpec }
	local out: { SlotSpec } = {}
	local state = guns and guns.state() or {}
	local gunList = state.guns or {}
	local equippedGun = guns and guns.equipped()
	local held = equippedTool()
	table.insert(out, {
		id = "Fists",
		key = 1,
		name = "Fists",
		emoji = Config.Hotbar.FistsEmoji,
		image = H.Images.Fists,
		active = equippedGun == nil and held == nil,
		press = function()
			if guns then
				guns.holster()
			end
			local char = player.Character
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			if hum then
				hum:UnequipTools()
			end
		end,
	})
	for i, g in gunList do
		local def = Guns.Defs[g.id]
		local id = g.id
		table.insert(out, {
			id = "Gun_" .. id,
			key = i + 1,
			name = if def then def.Display else id,
			emoji = Config.Hotbar.GunEmoji,
			image = H.Images["Gun_" .. id],
			active = equippedGun == id,
			press = function()
				if not guns then
					return
				end
				if guns.equipped() == id then
					guns.holster()
				else
					guns.equip(id)
				end
			end,
		})
	end
	for j, tool in backpackTools() do
		local t = tool
		table.insert(out, {
			id = "Tool_" .. t.Name,
			key = #gunList + 1 + j,
			name = t.Name,
			emoji = "🎒",
			image = if t.TextureId ~= "" then t.TextureId else nil,
			active = t == held,
			press = function()
				local char = player.Character
				local hum = char and char:FindFirstChildOfClass("Humanoid")
				if not hum then
					return
				end
				if t.Parent == char then
					hum:UnequipTools()
				else
					if guns then
						guns.holster()
					end
					hum:EquipTool(t)
				end
			end,
		})
	end
	return out
end

local current: { SlotSpec } = {}

local function styleSlot(slot: any, s: SlotSpec)
	local disc = slot.Disc
	disc.Stroke.Color = if s.active then H.TileActive else (Theme :: any).LowPoly.Outline
	disc.Stroke.Thickness = if s.active then 4 else 3
	slot.ItemName.Visible = s.active and s.id ~= "Fists"
	slot.ItemName.Text = string.upper(s.name)
	slot.Key.TextColor3 = if s.active then H.TileActive else Theme.Colors.Text
	slot.Key.Visible = not touchOnly()
end

local function refresh()
	local list = specs()
	current = list
	-- rebuild only when the set of slots changes; otherwise just restyle
	local sig = {}
	for _, s in list do
		table.insert(sig, s.id .. (if s.active then "*" else ""))
	end
	local key = table.concat(sig, "|")
	if key == lastKey then
		return
	end
	local bar = gui.Hotbar
	local template = bar.SlotTemplate
	local want: { [string]: boolean } = {}
	for i, s in list do
		local name = "Slot_" .. s.id
		want[name] = true
		local slot = bar:FindFirstChild(name)
		local wasActive = slot and slot:GetAttribute("Active")
		if not slot then
			slot = template:Clone()
			slot.Name = name
			slot.Visible = true
			local old = slot.Disc:FindFirstChild("Icon")
			if s.image and s.image ~= "" and old then
				old:Destroy()
				local img = Instance.new("ImageLabel")
				img.Name = "Icon"
				img.AnchorPoint = Vector2.new(0.5, 0.5)
				img.Position = UDim2.fromScale(0.5, 0.5)
				img.Size = UDim2.fromOffset(44, 44)
				img.BackgroundTransparency = 1
				img.Image = s.image
				img.Parent = slot.Disc
			elseif old then
				old.Text = s.emoji
			end
			slot.Parent = bar
			local id = s.id
			slot.Activated:Connect(function()
				for _, c in current do
					if c.id == id then
						c.press()
					end
				end
			end)
			slot.Pop.Scale = 0.5
			Motion.tween(slot.Pop, Motion.Spring, { Scale = 1 })
		end
		slot.LayoutOrder = i
		slot.Key.Text = tostring(s.key)
		styleSlot(slot, s)
		if s.active and not wasActive then
			slot.Pop.Scale = 1.15
			Motion.tween(slot.Pop, Motion.Spring, { Scale = 1 })
		end
		slot:SetAttribute("Active", s.active)
	end
	for _, c in bar:GetChildren() do
		if c:IsA("GuiButton") and c.Name ~= "SlotTemplate" and not want[c.Name] then
			c:Destroy()
		end
	end
	lastKey = key
end

-- keep the bar clear of the phone peeking in the bottom-right corner (~340 px)
local function fit()
	local cam = workspace.CurrentCamera
	local bar = gui.Hotbar
	local width = (#current * 76) * (bar.Scale.Scale)
	local vw = cam.ViewportSize.X
	local right = vw / 2 + width / 2
	local shift = math.max(0, right - (vw - 350))
	bar.Position = UDim2.new(0.5, -shift, 1, -10)
end

function Hotbar.init()
	local pg = player:WaitForChild("PlayerGui")
	gui = pg:WaitForChild("MTL_HUD", 10)
	if not gui or not gui:FindFirstChild("Hotbar") then
		warn("[MTL Hotbar] MTL_HUD has no Hotbar (old HUD saved in StarterGui?)")
		return
	end
	local mod = script.Parent:FindFirstChild("GunController")
	if mod then
		local ok, g = pcall(require, mod)
		if ok then
			guns = g
			g.Changed:Connect(refresh)
		end
	end
	-- one bar on screen: hide the default backpack and the gun piece's own bar
	pcall(function()
		StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Backpack, false)
	end)
	task.spawn(function()
		local gunGui = pg:WaitForChild("MTL_Gun", 10)
		local wb = gunGui and gunGui:FindFirstChild("WeaponBar")
		if wb then
			wb:Destroy()
		end
	end)

	-- tool keys (guns handle their own keys in GunController)
	UserInputService.InputBegan:Connect(function(input, processed)
		if processed or UIState.get().lockControls then
			return
		end
		for _, s in current do
			if string.sub(s.id, 1, 5) == "Tool_" and TOOL_KEYS[s.key] == input.KeyCode then
				s.press()
				return
			end
		end
		-- key 1 also drops a held tool (GunController holsters guns on it)
		if input.KeyCode == Enum.KeyCode.One and equippedTool() then
			current[1].press()
		end
	end)

	local function watchChar(char: Model)
		char.ChildAdded:Connect(refresh)
		char.ChildRemoved:Connect(refresh)
	end
	if player.Character then
		watchChar(player.Character)
	end
	player.CharacterAdded:Connect(watchChar)
	player.ChildAdded:Connect(function(c)
		if c:IsA("Backpack") then
			c.ChildAdded:Connect(refresh)
			c.ChildRemoved:Connect(refresh)
		end
	end)
	local bp = player:FindFirstChildOfClass("Backpack")
	if bp then
		bp.ChildAdded:Connect(refresh)
		bp.ChildRemoved:Connect(refresh)
	end

	refresh()
	-- the gun list can change without an equip (bought / given), so check twice a second as well
	task.spawn(function()
		while true do
			task.wait(0.5)
			refresh()
			fit()
		end
	end)
	gui.Hotbar.Visible = true
end

return Hotbar
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "JobController", "ModuleScript", [======[--!strict
-- The job on your screen (Piece 2): the job panel, the marker + glow on the station you need, the prompt there,
-- the minigames, the shift / check-in cards, the PERFECT flourish, reward fly-ups and the level-up ring.
-- Everything it shows comes from the server's JobState; it reports with JobAction and never decides pay.
--   JobController.state() -> last JobState (or nil)      JobController.Changed: Signal(state)
--   JobController.action(type, payload?)                  e.g. JobController.action("clockIn")
-- Funnel (Research "Onboarding Funnels and Wayfinding"): ONE thing to do at a time, always marked in the world
-- (glow + floating marker, breadcrumbs when it's far) and written on the panel, with a coach line the first times.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local GuiService = game:GetService("GuiService")

local Net = require(ReplicatedStorage.MTL.Net)
local Signal = require(ReplicatedStorage.MTL.Signal)
local Theme = require(ReplicatedStorage.MTL.UI.Theme)
local Motion = require(ReplicatedStorage.MTL.UI.Motion)
local Format = require(ReplicatedStorage.MTL.Format)
local Build = require(ReplicatedStorage.MTL.UI.Build.Job)
local UIState = require(script.Parent.UIState)
local Wayfinder = require(script.Parent.WayfindingController)
local JobFX = require(script.Parent.JobFX)
local Minigames = require(script.Parent.JobMinigames)

local player = Players.LocalPlayer
local camera = workspace.CurrentCamera
local C = Theme.Colors
local J = Theme.Job

local JobController = {}
JobController.Changed = Signal.new()

local MARKER_ID = "Job" -- Wayfinder id for the current station
local CLOCK_MARKER_ID = "JobClock"
local SHOW_CLOCK_WITHIN = 140 -- studs from the site: show the "Clock in" marker
local BREADCRUMBS_FROM = 60 -- studs: breadcrumbs on the job marker only when it's this far

local gui: any
local state: any = nil
local stateAt = 0 -- os.clock() when `state` arrived (for countdowns)
local stepKey = "" -- "taskId:step" currently dressed in the world
local stepFx: JobFX.FX? = nil
local cleanupStep: { () -> () } = {}
local postRingOff: (() -> ())? = nil
local postKey = ""
local running: any = nil -- active minigame handle
local anchor: Part
local prompt: ProximityPrompt
local clockAnchor: Part
local clockPrompt: ProximityPrompt
local cardMode = ""
local clockMarker = false -- the "Clock in" Wayfinder marker is up

function JobController.state(): any
	return state
end

function JobController.action(kind: string, payload: { [string]: any }?)
	local p = payload or {}
	p.type = kind
	Net.get("JobAction"):FireServer(p)
end

local function root(): BasePart?
	local char = player.Character
	return char and char:FindFirstChild("HumanoidRootPart") :: BasePart?
end

local function flatDist(a: Vector3, b: Vector3): number
	local d = a - b
	return Vector2.new(d.X, d.Z).Magnitude
end

---------------------------------------------------------------- world anchors + prompts (local parts)

local function makeAnchor(name: string): (Part, ProximityPrompt)
	local p = Instance.new("Part")
	p.Name = name
	p.Anchored, p.CanCollide, p.CanQuery, p.CanTouch = true, false, false, false
	p.Transparency = 1
	p.Size = Vector3.new(1, 1, 1)
	p.Position = Vector3.new(0, -500, 0)
	p.Parent = workspace
	local pp = Instance.new("ProximityPrompt")
	pp.KeyboardKeyCode = Enum.KeyCode.E
	pp.GamepadKeyCode = Enum.KeyCode.ButtonX
	pp.HoldDuration = 0
	pp.RequiresLineOfSight = false
	pp.Enabled = false
	pp.Parent = p
	return p, pp
end

local function placeAnchor(part: Part, pos: Vector3)
	part.Position = Vector3.new(pos.X, JobFX.floor(pos) + 2.5, pos.Z)
end

---------------------------------------------------------------- panel

local function setVisible(obj: GuiObject, on: boolean)
	if obj.Visible ~= on then
		obj.Visible = on
	end
end

local function render()
	local panel = gui.Panel
	local body = panel.Body
	if not state or not state.job then
		setVisible(panel, false)
		return
	end
	local r = root()
	local nearSite = r ~= nil and flatDist(r.Position, state.site.pos) <= SHOW_CLOCK_WITHIN
	setVisible(panel, (state.onShift or nearSite) and not UIState.get().hideHUD)
	body.JobTitle.Text = string.upper(state.role .. "  ·  " .. state.title)
	local accentColor = if state.onShift then C.Accent else C.TextDim
	local age = os.clock() - stateAt

	local taskText, steps, status, hint = "", "", "", ""
	local statusColor = C.Gold
	local actionText: string? = nil
	if not state.onShift then
		taskText = if nearSite then "Clock in at the time clock" else ("Head to " .. state.title)
		steps = ""
		actionText = if nearSite then "Clock in" else nil
	else
		local shift = state.shift
		if shift.complete then
			taskText = "Shift complete"
		elseif state.task then
			local t = state.task
			taskText = t.text
			steps = if t.steps > 1 then string.format("Step %d of %d", t.step, t.steps) else ""
			hint = t.hint or ""
		elseif state.waiting then
			local left = math.max(0, math.ceil(state.waiting - age))
			taskText = "Waiting for the next customer"
			status = if left > 0 then ("Next one in about " .. left .. "s") else "Any second now..."
			statusColor = C.TextDim
		elseif state.post then
			local p = state.post
			if p.paused then
				taskText = "Radio's buzzing. Check in"
				status = "Pay is paused until you check in"
			elseif p.onPost then
				taskText = "On post. Stay in the zone"
				status = string.format("Paid every %ds  ·  about %s/min", p.payEvery or 30, Format.cash(p.perMinute or 0))
				statusColor = C.Accent
			else
				taskText = "Get back to your post"
				status = "Stand inside the green ring to get paid"
			end
		end
		if state.leaving then
			local left = math.max(0, math.ceil(state.leaving - age))
			status = "You're leaving work! Shift ends in " .. left .. "s"
			statusColor = C.Danger
			accentColor = C.Danger
		end
		body.Progress.Fill.Size = UDim2.fromScale(math.clamp(shift.done / math.max(1, shift.total), 0, 1), 1)
		body.ProgressText.Text = string.format("Shift %d / %d  ·  %s earned", shift.done, shift.total, Format.cash(shift.earned))
		actionText = if state.storyJob then nil else "End shift"
	end
	setVisible(body.Progress, state.onShift == true)
	setVisible(body.ProgressText, state.onShift == true)
	body.Task.Text = taskText
	body.Steps.Text = steps
	setVisible(body.Steps, steps ~= "")
	body.Status.Text = status
	body.Status.TextColor3 = statusColor
	setVisible(body.Status, status ~= "")
	body.Hint.Text = hint
	setVisible(body.Hint, hint ~= "")
	panel.Accent.BackgroundColor3 = accentColor
	body.Action.Text = actionText or ""
	setVisible(body.Action, actionText ~= nil)
end

---------------------------------------------------------------- cards (shift complete / check in)

local function showCard(mode: string)
	local card = gui.Card
	if mode == cardMode then
		return
	end
	cardMode = mode
	if mode == "" then
		card.Visible = false
		return
	end
	if mode == "shift" then
		card.Title.Text = "SHIFT COMPLETE"
		card.Body.Text = string.format("You made %s this shift. Run another one?", Format.cash(state.shift.earned))
		card.Primary.Text = "Next shift"
		card.Secondary.Text = "Clock out"
		card.Secondary.Visible = not state.storyJob -- the story shift keeps going
	elseif mode == "checkIn" then
		card.Title.Text = "STILL ON POST?"
		card.Body.Text = "The radio's buzzing. Check in to keep getting paid."
		card.Primary.Text = "Check in"
		card.Secondary.Visible = false
	end
	card.Visible = true
	local scale = card:FindFirstChild("Scale") :: UIScale?
	if scale then
		scale.Scale = 0.85
		Motion.tween(scale, Motion.Spring, { Scale = 1 })
	end
	if GuiService.SelectedObject == nil and game:GetService("UserInputService").GamepadEnabled then
		GuiService.SelectedObject = card.Primary
	end
	JobFX.sound(J.Sounds.Whoosh, 0.35)
end

---------------------------------------------------------------- the current step in the world

local function clearStep()
	for _, fn in cleanupStep do
		fn()
	end
	table.clear(cleanupStep)
	if stepFx then
		stepFx.destroy()
		stepFx = nil
	end
	prompt.Enabled = false
	Wayfinder.clear(MARKER_ID)
	stepKey = ""
end

local function faceStation(pos: Vector3)
	local r = root()
	if not r then
		return
	end
	local flat = Vector3.new(pos.X, r.Position.Y, pos.Z)
	if (flat - r.Position).Magnitude > 0.5 then
		r.CFrame = CFrame.lookAt(r.Position, flat)
	end
end

local function startMinigame(t: any)
	if running then
		return
	end
	local taskId, step = t.id, t.step
	JobController.action("begin", { task = taskId, step = step })
	faceStation(t.station.pos)
	UIState.push("JobTask", { lockControls = true })
	prompt.Enabled = false
	local fx = stepFx or JobFX.forStep(nil, t.station.pos)
	running = Minigames.run(gui, t, fx, function(score)
		running = nil
		UIState.pop("JobTask")
		JobController.action("step", { task = taskId, step = step, score = score })
	end, function()
		running = nil
		UIState.pop("JobTask")
		if state and state.task and state.task.id == taskId then
			prompt.Enabled = true
		end
	end)
end

local function onPrompt()
	if not state or not state.task or running then
		return
	end
	local t = state.task
	if t.kind == "hold" or t.kind == "timing" or t.kind == "sequence" then
		startMinigame(t)
	else
		JobFX.sound(J.Sounds.Prompt, 0.5)
		if t.fx == "Slam" then
			JobFX.sound(J.Sounds.Slam, 0.6)
		end
		prompt.Enabled = false -- until the server answers
		JobController.action("step", { task = t.id, step = t.step })
		task.delay(1.5, function()
			-- server said no (too far / out of sync): it re-sent the state; make sure the prompt is back
			if state and state.task and state.task.id == t.id and state.task.step == t.step and not running then
				prompt.Enabled = true
			end
		end)
	end
end

local function dressStep()
	local t = state and state.onShift and state.task
	local key = if t then (t.id .. ":" .. t.step) else ""
	if key == stepKey then
		-- same step re-sent (the server refused a press: too far / too fast): offer the prompt again
		if t and not running then
			prompt.Enabled = true
		end
		return
	end
	if running then
		running.cancel()
	end
	clearStep()
	if not t then
		return
	end
	stepKey = key
	local pos = t.station.pos
	local radius = t.station.radius
	-- marker + glow + prompt
	local r = root()
	local far = t.far or (r ~= nil and flatDist(r.Position, pos) > BREADCRUMBS_FROM)
	Wayfinder.set(MARKER_ID, pos, { label = t.prompt, radius = radius, breadcrumbs = far })
	table.insert(cleanupStep, JobFX.beacon(pos, radius))
	placeAnchor(anchor, pos)
	prompt.ActionText = t.prompt
	prompt.ObjectText = t.title
	prompt.MaxActivationDistance = radius + 4
	prompt.Enabled = true
	-- the physical bit of the task
	if t.fx == "Bag" then
		table.insert(cleanupStep, JobFX.bag(pos))
	elseif t.fx then
		stepFx = JobFX.forStep(t.fx, pos)
	end
end

local function dressPost()
	local key = ""
	if state and state.onShift and state.post then
		local s = state.post.station
		key = string.format("%d,%d,%d", math.floor(s.pos.X), math.floor(s.pos.Z), math.floor(s.radius))
	end
	if key == postKey then
		return
	end
	postKey = key
	if postRingOff then
		postRingOff()
		postRingOff = nil
		Wayfinder.clear(MARKER_ID)
	end
	if key ~= "" then
		local s = state.post.station
		postRingOff = JobFX.postRing(s.pos, s.radius)
		Wayfinder.set(MARKER_ID, s.pos, { label = "Your post", radius = s.radius, breadcrumbs = false })
	end
end

local function dressClock()
	local show = state and state.job and not state.onShift and not state.storyJob
	if show then
		placeAnchor(clockAnchor, state.clock.pos)
		clockPrompt.ActionText = "Clock in"
		clockPrompt.ObjectText = state.title
		clockPrompt.MaxActivationDistance = state.clock.radius + 4
		clockPrompt.Enabled = true
	else
		clockPrompt.Enabled = false
		Wayfinder.clear(CLOCK_MARKER_ID)
		clockMarker = false
	end
end

---------------------------------------------------------------- results

local function flash(text: string, color: Color3, sub: string?)
	local f = gui.Flash
	f.Text = if sub then (text .. "\n" .. sub) else text
	f.TextColor3 = color
	f.TextTransparency = 0
	f.Size = UDim2.fromOffset(300, 34)
	Motion.tween(f, Motion.Spring, { Size = UDim2.fromOffset(400, 40) })
	task.delay(0.9, function()
		Motion.tween(f, Motion.Slow, { TextTransparency = 1 })
	end)
end

local function onResult(res: any)
	if typeof(res.at) == "Vector3" then
		JobFX.burst(res.at, if res.label == "PERFECT" then J.Perfect else J.Hit)
	end
	if res.label == "PERFECT" then
		flash("PERFECT!", J.Perfect, if res.perfectBonus then "+25% tip" else nil)
	elseif res.label == "SLOPPY" then
		flash("SLOPPY", J.Miss, "-20%")
	end
end

-- "+$8" flies from the world spot to the cash counter, "+22 XP" to the level bar
local function flyUp(text: string, color: Color3, from: Vector3, targetName: string, delay: number)
	task.delay(delay, function()
		local vp, onScreen = camera:WorldToViewportPoint(from + Vector3.new(0, 2, 0))
		if not onScreen then
			return
		end
		local inset = GuiService:GetGuiInset()
		local start = Vector2.new(vp.X, vp.Y) - inset
		local hud = player.PlayerGui:FindFirstChild("MTL_HUD")
		local target = hud and hud:FindFirstChild("Stats") and hud.Stats:FindFirstChild(targetName)
		local label = Instance.new("TextLabel")
		label.AnchorPoint = Vector2.new(0.5, 0.5)
		label.BackgroundTransparency = 1
		label.Size = UDim2.fromOffset(120, 30)
		label.Position = UDim2.fromOffset(start.X, start.Y)
		label.FontFace = Theme.Fonts.Display
		label.TextSize = 24
		label.TextColor3 = color
		label.Text = text
		local stroke = Instance.new("UIStroke")
		stroke.Thickness = 2
		stroke.Transparency = 0.3
		stroke.Parent = label
		label.Parent = gui.Fly
		Motion.tween(label, Motion.Spring, { Position = UDim2.fromOffset(start.X, start.Y - 40) }).Completed:Wait()
		task.wait(0.15)
		if target then
			local tp = target.AbsolutePosition + target.AbsoluteSize / 2
			local tw = Motion.tween(label, TweenInfo.new(0.45, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { Position = UDim2.fromOffset(tp.X, tp.Y), TextSize = 14 })
			tw.Completed:Wait()
		else
			Motion.tween(label, Motion.Slow, { TextTransparency = 1 }).Completed:Wait()
		end
		label:Destroy()
	end)
end

---------------------------------------------------------------- state in

local function onState(st: any)
	local old = state
	state = st
	stateAt = os.clock()
	if not st or not st.job then
		clearStep()
		dressPost()
		dressClock()
		JobFX.setStatic("", nil)
		showCard("")
		render()
		JobController.Changed:Fire(st)
		return
	end
	JobFX.setStatic(st.job, st.props)
	dressStep()
	dressPost()
	dressClock()
	if st.onShift and st.shift and st.shift.complete then
		showCard("shift")
	elseif st.onShift and st.post and st.post.checkIn then
		showCard("checkIn")
	else
		showCard("")
	end
	if st.result then
		onResult(st.result)
	end
	if old and old.onShift and not st.onShift then
		JobFX.clearDynamic()
	end
	render()
	JobController.Changed:Fire(st)
end

function JobController.init()
	local pg = player:WaitForChild("PlayerGui")
	gui = pg:FindFirstChild("MTL_Job")
	if not gui then
		gui = Build.build()
		gui.Parent = pg
	end
	JobFX.init()
	anchor, prompt = makeAnchor("MTL_JobAnchor")
	clockAnchor, clockPrompt = makeAnchor("MTL_JobClockAnchor")
	prompt.Triggered:Connect(onPrompt)
	clockPrompt.Triggered:Connect(function()
		JobFX.sound(J.Sounds.Prompt, 0.5)
		JobController.action("clockIn")
	end)

	gui.Panel.Body.Action.Activated:Connect(function()
		if not state then
			return
		end
		JobController.action(if state.onShift then "clockOut" else "clockIn")
	end)
	gui.Card.Primary.Activated:Connect(function()
		if cardMode == "shift" then
			JobController.action("nextShift")
		elseif cardMode == "checkIn" and state and state.post then
			JobController.action("checkIn", { token = state.post.checkIn })
		end
		showCard("")
	end)
	gui.Card.Secondary.Activated:Connect(function()
		if cardMode == "shift" then
			JobController.action("clockOut")
		end
		showCard("")
	end)

	Net.get("JobState").OnClientEvent:Connect(function(st)
		if type(st) == "table" then
			onState(st)
		end
	end)
	Net.get("Reward").OnClientEvent:Connect(function(r)
		if type(r) ~= "table" or typeof(r.at) ~= "Vector3" then
			return
		end
		if r.cash then
			flyUp("+" .. Format.cash(r.cash), C.Accent, r.at, "Cash", 0)
		end
		if r.xp then
			flyUp("+" .. tostring(r.xp) .. " XP", C.AccentAlt, r.at, "Level", 0.12)
		end
	end)
	Net.get("LevelUp").OnClientEvent:Connect(function()
		JobFX.levelUp(player.Character)
	end)
	UIState.Changed:Connect(function(st)
		gui.Enabled = not st.hideHUD
		render()
	end)

	-- countdowns, panel visibility near the site, the clock-in marker
	local acc = 0
	RunService.Heartbeat:Connect(function(dt)
		acc += dt
		if acc < 0.25 then
			return
		end
		acc = 0
		if state and state.job and not state.onShift and not state.storyJob then
			local r = root()
			local near = r ~= nil and flatDist(r.Position, state.site.pos) <= SHOW_CLOCK_WITHIN
			if near and not clockMarker then
				Wayfinder.set(CLOCK_MARKER_ID, state.clock.pos, { label = "Clock in", radius = state.clock.radius, breadcrumbs = false })
				clockMarker = true
			elseif not near and clockMarker then
				Wayfinder.clear(CLOCK_MARKER_ID)
				clockMarker = false
			end
		elseif clockMarker then
			Wayfinder.clear(CLOCK_MARKER_ID)
			clockMarker = false
		end
		render()
	end)

	-- respawn: anchors live in workspace (not the character), but re-ask the server for the truth
	player.CharacterAdded:Connect(function()
		if running then
			running.cancel()
		end
		stepKey = ""
		task.delay(1, function()
			JobController.action("sync")
		end)
	end)
end

return JobController
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "JobFX", "ModuleScript", [======[--!strict
-- Local-only world dressing for jobs (helper for JobController, not booted on its own).
-- Only YOU see these, so tasks stay per player (nobody else's spill on your floor):
--   * placeholder props at stations that have no real map part yet (shelf, dumpster, car, grill...)
--   * the dynamic bits that make a task feel physical: the spill shrinking as you mop, products popping
--     onto the shelf, the full trash bag, suds, sizzle, price tags, the "done" ring.
-- TODO(Alex art): every placeholder here is plain parts. Real models can replace a prop by putting a Model named
-- like the prop ("Shelf", "Car"...) in ReplicatedStorage.MTL_JobProps: it gets cloned instead.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Players = game:GetService("Players")
local SoundService = game:GetService("SoundService")
local TweenService = game:GetService("TweenService")

local Theme = require(ReplicatedStorage.MTL.UI.Theme)

local J = Theme.Job
local C3 = Color3.fromRGB

local JobFX = {}

local folder: Folder
local staticFolder: Folder
local staticKey = ""

local function new(className: string, props: { [string]: any }): any
	local inst = Instance.new(className)
	for k, v in props do
		if k ~= "Parent" then
			(inst :: any)[k] = v
		end
	end
	if props.Parent then
		inst.Parent = props.Parent
	end
	return inst
end

local function part(props: { [string]: any }): Part
	local base: { [string]: any } = {
		Anchored = true,
		CanCollide = false,
		CanQuery = false,
		CanTouch = false,
		Material = Enum.Material.SmoothPlastic,
		TopSurface = Enum.SurfaceType.Smooth,
		BottomSurface = Enum.SurfaceType.Smooth,
	}
	for k, v in props do
		base[k] = v
	end
	return new("Part", base)
end

function JobFX.sound(id: string?, volume: number?, pitch: number?)
	if not id or id == "" or id == "rbxassetid://0" then
		return
	end
	local s = Instance.new("Sound")
	s.SoundId = id
	s.Volume = volume or 0.5
	s.PlaybackSpeed = math.min(pitch or 1, 1.05) -- never pitch up into squeaky territory (Alex: no high-pitched sounds)
	SoundService:PlayLocalSound(s)
	task.delay(3, function()
		s:Destroy()
	end)
end

-- Floor height under a point (ignores characters and our own FX). Falls back to pos.Y - 2.5 if nothing's there
-- (e.g. not streamed in yet).
function JobFX.floor(pos: Vector3): number
	local params = RaycastParams.new()
	local ignore: { Instance } = { folder }
	for _, p in Players:GetPlayers() do
		if p.Character then
			table.insert(ignore, p.Character)
		end
	end
	params.FilterDescendantsInstances = ignore
	params.FilterType = Enum.RaycastFilterType.Exclude
	local hit = workspace:Raycast(pos + Vector3.new(0, 6, 0), Vector3.new(0, -20, 0), params)
	return if hit then hit.Position.Y else pos.Y - 2.5
end

local function tween(inst: Instance, t: number, props: { [string]: any }, style: Enum.EasingStyle?)
	local tw = TweenService:Create(inst, TweenInfo.new(t, style or Enum.EasingStyle.Quad, Enum.EasingDirection.Out), props)
	tw:Play()
	return tw
end

---------------------------------------------------------------- placeholder props

-- builds a prop with its bottom at y = 0 around the origin; returns a Model
local builders: { [string]: (Model) -> () } = {
	TimeClock = function(m)
		part({ Name = "Post", Size = Vector3.new(0.4, 4, 0.4), Position = Vector3.new(0, 2, 0), Color = C3(60, 60, 66), Parent = m })
		part({ Name = "Box", Size = Vector3.new(1.4, 1.6, 0.6), Position = Vector3.new(0, 4.4, 0), Color = C3(40, 42, 50), Parent = m })
		part({ Name = "Screen", Size = Vector3.new(1, 0.4, 0.1), Position = Vector3.new(0, 4.7, -0.32), Color = J.Hit, Material = Enum.Material.Neon, Parent = m })
	end,
	Boxes = function(m)
		local spots = { Vector3.new(-1.2, 0.8, 0), Vector3.new(1.2, 0.8, 0.2), Vector3.new(0, 2.4, 0.1), Vector3.new(-0.2, 0.8, 1.8) }
		for i, p in spots do
			part({ Name = "Box" .. i, Size = Vector3.new(2, 1.6, 1.6), Position = p, Color = C3(176, 132, 84), Material = Enum.Material.Cardboard, Orientation = Vector3.new(0, (i * 17) % 20 - 10, 0), Parent = m })
		end
	end,
	Shelf = function(m)
		part({ Name = "Back", Size = Vector3.new(6, 6, 0.3), Position = Vector3.new(0, 3, 0.9), Color = C3(210, 212, 218), Parent = m })
		for i = 0, 3 do
			part({ Name = "Board" .. i, Size = Vector3.new(6, 0.2, 1.8), Position = Vector3.new(0, 0.3 + i * 1.6, 0), Color = C3(225, 226, 230), Parent = m })
		end
	end,
	Bin = function(m)
		part({ Name = "Can", Shape = Enum.PartType.Cylinder, Size = Vector3.new(2.6, 2, 2), Position = Vector3.new(0, 1.3, 0), Orientation = Vector3.new(0, 0, 90), Color = C3(90, 96, 104), Material = Enum.Material.Metal, Parent = m })
	end,
	Dumpster = function(m)
		part({ Name = "Body", Size = Vector3.new(6, 3.6, 3.4), Position = Vector3.new(0, 1.8, 0), Color = C3(40, 110, 70), Material = Enum.Material.Metal, Parent = m })
		part({ Name = "Lid", Size = Vector3.new(6.1, 0.2, 3.5), Position = Vector3.new(0, 3.7, 0), Color = C3(30, 30, 34), Parent = m })
	end,
	TireRack = function(m)
		part({ Name = "Frame", Size = Vector3.new(5, 0.3, 1.6), Position = Vector3.new(0, 1.6, 0), Color = C3(70, 70, 80), Material = Enum.Material.Metal, Parent = m })
		for i = -1, 1 do
			part({ Name = "Tire", Shape = Enum.PartType.Cylinder, Size = Vector3.new(0.9, 2.4, 2.4), Position = Vector3.new(i * 1.4, 2.95, 0), Color = C3(28, 28, 30), Parent = m })
		end
	end,
	Car = function(m)
		local body = C3(70 + math.random(0, 150), 70 + math.random(0, 100), 80 + math.random(0, 150))
		part({ Name = "Body", Size = Vector3.new(6, 2, 12), Position = Vector3.new(0, 1.6, 0), Color = body, Material = Enum.Material.Metal, Parent = m })
		part({ Name = "Cabin", Size = Vector3.new(5.2, 1.8, 6), Position = Vector3.new(0, 3.4, 0.6), Color = C3(30, 34, 44), Material = Enum.Material.Glass, Transparency = 0.2, Parent = m })
		for _, x in { -3, 3 } do
			for _, z in { -3.8, 3.8 } do
				part({ Name = "Wheel", Shape = Enum.PartType.Cylinder, Size = Vector3.new(0.8, 2, 2), Position = Vector3.new(x, 1, z), Color = C3(20, 20, 22), Parent = m })
			end
		end
	end,
	Grill = function(m)
		part({ Name = "Base", Size = Vector3.new(4, 3, 2.6), Position = Vector3.new(0, 1.5, 0), Color = C3(60, 62, 70), Material = Enum.Material.Metal, Parent = m })
		part({ Name = "Plate", Size = Vector3.new(3.6, 0.15, 2.2), Position = Vector3.new(0, 3.05, 0), Color = C3(255, 120, 40), Material = Enum.Material.Neon, Transparency = 0.3, Parent = m })
	end,
	Counter = function(m)
		part({ Name = "Top", Size = Vector3.new(6, 3, 2.2), Position = Vector3.new(0, 1.5, 0), Color = C3(235, 235, 238), Parent = m })
	end,
	Table = function(m)
		part({ Name = "Top", Size = Vector3.new(4, 0.25, 4), Position = Vector3.new(0, 2.6, 0), Color = C3(150, 100, 60), Material = Enum.Material.Wood, Parent = m })
		part({ Name = "Leg", Size = Vector3.new(0.4, 2.5, 0.4), Position = Vector3.new(0, 1.25, 0), Color = C3(40, 40, 44), Parent = m })
	end,
	Register = function(m)
		part({ Name = "Counter", Size = Vector3.new(5, 3, 2.2), Position = Vector3.new(0, 1.5, 0), Color = C3(225, 225, 230), Parent = m })
		part({ Name = "Till", Size = Vector3.new(1.4, 0.9, 1), Position = Vector3.new(-1, 3.45, 0), Color = C3(40, 42, 50), Parent = m })
		part({ Name = "Screen", Size = Vector3.new(1, 0.6, 0.1), Position = Vector3.new(-1, 4.1, 0.2), Color = J.Hit, Material = Enum.Material.Neon, Parent = m })
	end,
	Podium = function(m)
		part({ Name = "Stand", Size = Vector3.new(1.6, 3.6, 1.2), Position = Vector3.new(0, 1.8, 0), Color = C3(120, 30, 40), Parent = m })
	end,
	Crates = function(m)
		for i, p in { Vector3.new(-1.3, 1, 0), Vector3.new(1.3, 1, 0), Vector3.new(0, 3, 0) } do
			part({ Name = "Crate" .. i, Size = Vector3.new(2.4, 2, 2), Position = p, Color = C3(150, 110, 70), Material = Enum.Material.WoodPlanks, Parent = m })
		end
	end,
	Post = function(_m) end, -- the post zone ring is drawn by JobFX.postRing (always, even with a map part)
}

local function placeModel(m: Model, pos: Vector3)
	local y = JobFX.floor(pos)
	m:PivotTo(CFrame.new(pos.X, y, pos.Z))
end

-- props = { {id, prop, pos} } from JobState. Rebuilt only when the job (key) changes.
function JobFX.setStatic(key: string, props: { any }?)
	if key == staticKey then
		return
	end
	staticKey = key
	staticFolder:ClearAllChildren()
	for _, p in props or {} do
		local custom = ReplicatedStorage:FindFirstChild("MTL_JobProps")
		local template = custom and custom:FindFirstChild(p.prop)
		local m: Model
		if template and template:IsA("Model") then
			m = template:Clone()
		else
			local build = builders[p.prop]
			if not build then
				continue
			end
			m = Instance.new("Model")
			m.Name = p.prop
			build(m)
			local origin = Instance.new("Part")
			origin.Name = "Origin"
			origin.Anchored, origin.CanCollide, origin.CanQuery, origin.Transparency = true, false, false, 1
			origin.Size = Vector3.new(0.2, 0.2, 0.2)
			origin.Position = Vector3.zero
			origin.Parent = m
			m.PrimaryPart = origin
		end
		m:SetAttribute("Station", p.id)
		m.Parent = staticFolder
		-- place once the area has had a moment to stream in
		task.spawn(function()
			placeModel(m, p.pos)
			task.wait(2)
			if m.Parent then
				placeModel(m, p.pos)
			end
		end)
	end
end

---------------------------------------------------------------- dynamic task FX

export type FX = { progress: (number, boolean?) -> (), hit: () -> (), finish: () -> (), destroy: () -> () }

local function noop() end

-- The task's world bit for a step. `fx` = Config step.fx. Returns handles the minigame drives.
function JobFX.forStep(fx: string?, pos: Vector3): FX
	local y = JobFX.floor(pos)
	local ground = Vector3.new(pos.X, y, pos.Z)
	if fx == "Spill" then
		local size = 5.5
		local puddle = part({
			Name = "Spill",
			Shape = Enum.PartType.Cylinder,
			Size = Vector3.new(0.06, size, size),
			CFrame = CFrame.new(ground + Vector3.new(0, 0.05, 0)) * CFrame.Angles(0, 0, math.rad(90)),
			Color = J.Spill,
			Material = Enum.Material.Glass,
			Transparency = 0.25,
			Reflectance = 0.2,
			Parent = folder,
		})
		return {
			progress = function(p)
				local s = math.max(0.05, size * (1 - p))
				puddle.Size = Vector3.new(0.06, s, s)
			end,
			hit = noop,
			finish = function()
				tween(puddle, 0.25, { Transparency = 1 })
			end,
			destroy = function()
				puddle:Destroy()
			end,
		}
	elseif fx == "ShelfFill" then
		local items: { Part } = {}
		local slots = 9
		local placed = 0
		return {
			progress = function(p)
				local want = math.floor(p * slots + 0.0001)
				while placed < want do
					placed += 1
					local row = math.floor((placed - 1) / 3)
					local col = (placed - 1) % 3
					local target = ground + Vector3.new(-1.6 + col * 1.6, 0.85 + row * 1.6, 0)
					local item = part({
						Name = "Product",
						Size = Vector3.new(0.1, 0.1, 0.1),
						Position = target,
						Color = J.Products[(placed % #J.Products) + 1],
						Parent = folder,
					})
					tween(item, 0.2, { Size = Vector3.new(1.2, 1.1, 0.9) }, Enum.EasingStyle.Back)
					JobFX.sound(J.Sounds.Prompt, 0.25, 0.9 + placed * 0.05)
					table.insert(items, item)
				end
			end,
			hit = noop,
			finish = noop,
			destroy = function()
				-- products stay on the shelf a little while (the world changed because of you), then fade
				for _, it in items do
					task.delay(20, function()
						if it.Parent then
							tween(it, 0.6, { Transparency = 1 }).Completed:Wait()
							it:Destroy()
						end
					end)
				end
			end,
		}
	elseif fx == "Suds" or fx == "Sizzle" then
		local anchor = part({ Name = fx, Size = Vector3.new(4, 0.2, 4), Position = ground + Vector3.new(0, if fx == "Sizzle" then 3.2 else 2, 0), Transparency = 1, Parent = folder })
		local emitter = new("ParticleEmitter", {
			Rate = 0,
			Lifetime = NumberRange.new(0.6, 1.2),
			Speed = NumberRange.new(2, 5),
			SpreadAngle = Vector2.new(40, 40),
			Size = NumberSequence.new(if fx == "Suds" then 0.6 else 0.4, 0),
			Color = ColorSequence.new(if fx == "Suds" then Color3.new(1, 1, 1) else C3(255, 170, 90)),
			Transparency = NumberSequence.new(0.2, 1),
			Parent = anchor,
		})
		return {
			progress = function(p, active)
				emitter.Rate = if active and p < 1 then 30 else 0
			end,
			hit = noop,
			finish = function()
				emitter:Emit(25)
			end,
			destroy = function()
				task.delay(1.5, function()
					anchor:Destroy()
				end)
			end,
		}
	elseif fx == "PriceTag" then
		return {
			progress = noop,
			hit = function()
				local bb = new("BillboardGui", { Size = UDim2.fromOffset(90, 30), StudsOffsetWorldSpace = Vector3.new(math.random(-15, 15) / 10, 3 + math.random() * 1.5, 0), AlwaysOnTop = true, Adornee = nil, Parent = folder })
				local anchor = part({ Name = "Tag", Size = Vector3.new(0.1, 0.1, 0.1), Position = ground, Transparency = 1, Parent = folder })
				bb.Adornee = anchor
				local label = new("TextLabel", {
					Size = UDim2.fromScale(1, 1),
					BackgroundColor3 = Color3.new(1, 1, 1),
					Text = string.format("$%d.%02d", math.random(1, 9), ({ 49, 79, 99, 29 })[math.random(1, 4)]),
					TextColor3 = C3(200, 30, 40),
					FontFace = Theme.Fonts.Bold,
					TextScaled = true,
					Parent = bb,
				})
				new("UICorner", { CornerRadius = UDim.new(0, 4), Parent = label })
				task.delay(1.2, function()
					bb:Destroy()
					anchor:Destroy()
				end)
			end,
			finish = noop,
			destroy = noop,
		}
	end
	return { progress = noop, hit = noop, finish = noop, destroy = noop }
end

-- A full trash bag sitting at the bin until you pick it up. Returns a destroy function.
function JobFX.bag(pos: Vector3): () -> ()
	local y = JobFX.floor(pos)
	local bag = part({ Name = "Bag", Size = Vector3.new(1.5, 2, 1.5), Position = Vector3.new(pos.X + 1.6, y + 1, pos.Z), Color = C3(30, 30, 34), Parent = folder })
	return function()
		bag:Destroy()
	end
end

-- The glowing column on the station you need to go to.
function JobFX.beacon(pos: Vector3, radius: number): () -> ()
	local y = JobFX.floor(pos)
	local ring = part({
		Name = "Beacon",
		Shape = Enum.PartType.Cylinder,
		Size = Vector3.new(0.08, radius * 0.9, radius * 0.9),
		CFrame = CFrame.new(pos.X, y + 0.06, pos.Z) * CFrame.Angles(0, 0, math.rad(90)),
		Color = J.Marker,
		Material = Enum.Material.Neon,
		Transparency = 0.55,
		Parent = folder,
	})
	local column = part({
		Name = "Column",
		Size = Vector3.new(0.5, 9, 0.5),
		Position = Vector3.new(pos.X, y + 4.5, pos.Z),
		Color = J.Marker,
		Material = Enum.Material.Neon,
		Transparency = 0.7,
		Parent = folder,
	})
	local alive = true
	task.spawn(function()
		while alive do
			tween(ring, 0.8, { Transparency = 0.8 }, Enum.EasingStyle.Sine).Completed:Wait()
			if not alive then
				break
			end
			tween(ring, 0.8, { Transparency = 0.45 }, Enum.EasingStyle.Sine).Completed:Wait()
		end
	end)
	return function()
		alive = false
		ring:Destroy()
		column:Destroy()
	end
end

-- The post zone for AFK jobs (stand inside it). Returns a destroy function.
function JobFX.postRing(pos: Vector3, radius: number): () -> ()
	local y = JobFX.floor(pos)
	local ring = part({
		Name = "PostZone",
		Shape = Enum.PartType.Cylinder,
		Size = Vector3.new(0.06, radius * 2, radius * 2),
		CFrame = CFrame.new(pos.X, y + 0.05, pos.Z) * CFrame.Angles(0, 0, math.rad(90)),
		Color = J.Zone,
		Material = Enum.Material.Neon,
		Transparency = 0.82,
		Parent = folder,
	})
	return function()
		ring:Destroy()
	end
end

-- "Done!" ring that bursts out of a station.
function JobFX.burst(pos: Vector3, color: Color3?)
	local y = JobFX.floor(pos)
	local ring = part({
		Name = "Burst",
		Shape = Enum.PartType.Cylinder,
		Size = Vector3.new(0.1, 1, 1),
		CFrame = CFrame.new(pos.X, y + 0.3, pos.Z) * CFrame.Angles(0, 0, math.rad(90)),
		Color = color or J.Hit,
		Material = Enum.Material.Neon,
		Transparency = 0.1,
		Parent = folder,
	})
	tween(ring, 0.45, { Size = Vector3.new(0.1, 12, 12), Transparency = 1 })
	task.delay(0.5, function()
		ring:Destroy()
	end)
end

-- Level-up: a ring of light rising around the character.
function JobFX.levelUp(character: Model?)
	local root = character and character:FindFirstChild("HumanoidRootPart") :: BasePart?
	if not root then
		return
	end
	local base = root.Position - Vector3.new(0, 2.8, 0)
	for i = 0, 2 do
		task.delay(i * 0.12, function()
			local ring = part({
				Name = "LevelRing",
				Shape = Enum.PartType.Cylinder,
				Size = Vector3.new(0.15, 3, 3),
				CFrame = CFrame.new(base) * CFrame.Angles(0, 0, math.rad(90)),
				Color = Theme.Colors.Gold,
				Material = Enum.Material.Neon,
				Transparency = 0.1,
				Parent = folder,
			})
			tween(ring, 0.9, { Size = Vector3.new(0.15, 9, 9), CFrame = CFrame.new(base + Vector3.new(0, 5, 0)) * CFrame.Angles(0, 0, math.rad(90)), Transparency = 1 }, Enum.EasingStyle.Quart)
			task.delay(1, function()
				ring:Destroy()
			end)
		end)
	end
end

function JobFX.clearDynamic()
	for _, c in folder:GetChildren() do
		if c ~= staticFolder then
			c:Destroy()
		end
	end
end

function JobFX.init()
	folder = Instance.new("Folder")
	folder.Name = "MTL_JobFX"
	folder.Parent = workspace
	staticFolder = Instance.new("Folder")
	staticFolder.Name = "Props"
	staticFolder.Parent = folder
end

return JobFX
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "JobMinigames", "ModuleScript", [======[--!strict
-- The three reusable task minigames (helper for JobController, not booted on its own). Research: "Jobs, Leveling
-- and RP Game Feel" (short, readable at a glance, physical feedback, reward at the end).
--   hold     : hold the button while the bar fills. Let go early and it drains (and the score drops a bit).
--   timing   : press when the needle is in the green. Each hit moves the zone and speeds the needle up a touch.
--   sequence : tap the items in the order on the ticket (number keys 1-6 work too).
-- Works with mouse (click/hold the big button), keyboard (E / Space, 1-6), touch (the big button) and gamepad
-- (A / X / R2 to act, B to back out; D-pad/stick to move between sequence buttons).
--   Minigames.run(gui, info, fx, onDone(score), onCancel) -> { cancel = fn }
local GuiService = game:GetService("GuiService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")

local Theme = require(ReplicatedStorage.MTL.UI.Theme)
local Motion = require(ReplicatedStorage.MTL.UI.Motion)
local JobRules = require(ReplicatedStorage.MTL.Rules.JobRules)
local JobFX = require(script.Parent.JobFX)

local C = Theme.Colors
local J = Theme.Job

local ACTION_KEYS = {
	[Enum.KeyCode.E] = true,
	[Enum.KeyCode.Space] = true,
	[Enum.KeyCode.ButtonA] = true,
	[Enum.KeyCode.ButtonX] = true,
	[Enum.KeyCode.ButtonR2] = true,
}
local CANCEL_KEYS = { [Enum.KeyCode.ButtonB] = true, [Enum.KeyCode.Backspace] = true }
local NUMBER_KEYS = { Enum.KeyCode.One, Enum.KeyCode.Two, Enum.KeyCode.Three, Enum.KeyCode.Four, Enum.KeyCode.Five, Enum.KeyCode.Six, Enum.KeyCode.Seven, Enum.KeyCode.Eight }

local Minigames = {}

local function keyHint(): string
	if UserInputService.GamepadEnabled and not UserInputService.KeyboardEnabled then
		return "[A]"
	elseif UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
		return ""
	end
	return "[E]"
end

-- tiny "punch": the panel pops a little bigger and settles
local function punch(scale: UIScale?, amount: number?)
	if not scale then
		return
	end
	scale.Scale = 1 + (amount or 0.04)
	Motion.tween(scale, Motion.Fast, { Scale = 1 })
end

local function shake(frame: GuiObject)
	local base = frame.Position
	task.spawn(function()
		for i, dx in { -8, 7, -5, 3, 0 } do
			frame.Position = base + UDim2.fromOffset(dx, 0)
			task.wait(0.03)
			if i == 5 then
				frame.Position = base
			end
		end
	end)
end

function Minigames.run(gui: any, info: any, fx: JobFX.FX, onDone: (number) -> (), onCancel: () -> ())
	local mg = gui.Minigame
	local scale = mg:FindFirstChild("Scale") :: UIScale?
	local action: TextButton = mg.ActionButton
	local conns: { RBXScriptConnection } = {}
	local finished = false
	local basePos = mg.Position

	mg.Hold.Visible = info.kind == "hold"
	mg.Timing.Visible = info.kind == "timing"
	mg.Sequence.Visible = info.kind == "sequence"
	mg.Title.Text = info.verb or string.upper(info.prompt or "")
	action.Visible = info.kind ~= "sequence"
	mg.Visible = true
	mg.Position = basePos + UDim2.fromOffset(0, 30)
	Motion.tween(mg, Motion.Spring, { Position = basePos })

	local function cleanup()
		for _, c in conns do
			c:Disconnect()
		end
		table.clear(conns)
		mg.Visible = false
		mg.Position = basePos
		if GuiService.SelectedObject and GuiService.SelectedObject:IsDescendantOf(mg) then
			GuiService.SelectedObject = nil
		end
	end

	local function finish(score: number)
		if finished then
			return
		end
		finished = true
		fx.finish()
		JobFX.sound(J.Sounds.Done, 0.6)
		punch(scale, 0.08)
		task.delay(0.18, function()
			cleanup()
			onDone(score)
		end)
	end

	local function cancel()
		if finished then
			return
		end
		finished = true
		cleanup()
		onCancel()
	end

	-- input plumbing shared by hold + timing
	local pressedFns: { () -> () } = {}
	local releasedFns: { () -> () } = {}
	local function onPress(fn: () -> ())
		table.insert(pressedFns, fn)
	end
	local function onRelease(fn: () -> ())
		table.insert(releasedFns, fn)
	end
	local function press()
		for _, fn in pressedFns do
			fn()
		end
	end
	local function release()
		for _, fn in releasedFns do
			fn()
		end
	end
	table.insert(conns, action.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			press()
		end
	end))
	table.insert(conns, action.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			release()
		end
	end))
	table.insert(conns, UserInputService.InputBegan:Connect(function(input, processed)
		if CANCEL_KEYS[input.KeyCode] then
			cancel()
		elseif ACTION_KEYS[input.KeyCode] and info.kind ~= "sequence" and not processed then
			press()
		end
	end))
	table.insert(conns, UserInputService.InputEnded:Connect(function(input)
		if ACTION_KEYS[input.KeyCode] then
			release()
		end
	end))
	table.insert(conns, mg.Close.Activated:Connect(cancel))

	if info.kind == "hold" then
		local seconds = math.max(0.5, info.seconds or 3)
		local fill = mg.Hold.Bar.Fill
		local pct = mg.Hold.Percent
		local p, holding, releases, started = 0, false, 0, false
		action.Text = (("HOLD  " .. keyHint()):gsub("%s+$", ""))
		pct.Text = "Hold to start"
		-- the prompt's own E press is usually still held: start right away
		holding = UserInputService:IsKeyDown(Enum.KeyCode.E)
		onPress(function()
			holding = true
		end)
		onRelease(function()
			if holding and started and p > 0.04 and p < 1 then
				releases += 1
				pct.Text = "Keep holding!"
				fill.BackgroundColor3 = J.Miss
				Motion.tween(fill, Motion.Normal, { BackgroundColor3 = C.Accent })
			end
			holding = false
		end)
		local tickAt = 0
		table.insert(conns, RunService.RenderStepped:Connect(function(dt)
			if finished then
				return
			end
			if holding then
				started = true
				p = math.min(1, p + dt / seconds)
				tickAt += dt
				if tickAt > 0.45 then -- little rhythmic click while you work
					tickAt = 0
					JobFX.sound(if info.fx == "Spill" then J.Sounds.Mop else J.Sounds.Prompt, 0.2, 0.9 + p * 0.4)
				end
				pct.Text = string.format("%d%%", math.floor(p * 100))
			elseif started then
				p = math.max(0, p - dt / seconds * 0.6) -- drains when you let go
			end
			fill.Size = UDim2.fromScale(p, 1)
			fx.progress(p, holding)
			if p >= 1 then
				finish(JobRules.scoreHold(releases))
			end
		end))
	elseif info.kind == "timing" then
		local need = info.hits or 3
		local zoneW = math.clamp(info.zone or 0.22, 0.08, 0.6)
		local speed = info.speed or 1
		local track = mg.Timing.Track
		local zone = track.Zone
		local needle = track.Needle
		local pips = mg.Timing.Pips
		for _, c in pips:GetChildren() do
			if c:IsA("GuiObject") then
				c:Destroy()
			end
		end
		for i = 1, need do
			local pip = Instance.new("Frame")
			pip.Name = "Pip" .. i
			pip.Size = UDim2.fromOffset(14, 14)
			pip.BackgroundColor3 = J.Track
			pip.BorderSizePixel = 0
			local corner = Instance.new("UICorner")
			corner.CornerRadius = UDim.new(1, 0)
			corner.Parent = pip
			pip.Parent = pips
		end
		local hits, misses, t, cooldown = 0, 0, math.random() * 2, 0
		local center = 0.5
		local function placeZone()
			center = 0.15 + math.random() * 0.7
			zone.Size = UDim2.fromScale(zoneW, 1)
			Motion.tween(zone, Motion.Fast, { Position = UDim2.fromScale(center, 0) })
		end
		placeZone()
		action.Text = ((string.upper(info.verb or "PRESS") .. "  " .. keyHint()):gsub("%s+$", ""))
		local function needleX(): number
			local phase = (t * speed) % 2 -- ping-pong 0..1..0
			return if phase <= 1 then phase else 2 - phase
		end
		onPress(function()
			if finished or cooldown > 0 then
				return
			end
			cooldown = 0.18
			local x = needleX()
			if math.abs(x - center) <= zoneW / 2 + 0.015 then
				hits += 1
				local pip = pips:FindFirstChild("Pip" .. hits)
				if pip then
					pip.BackgroundColor3 = J.Hit
				end
				zone.BackgroundColor3 = Color3.new(1, 1, 1)
				Motion.tween(zone, Motion.Normal, { BackgroundColor3 = J.Zone })
				JobFX.sound(J.Sounds.Hit, 0.4, 1 + hits * 0.08)
				fx.hit()
				punch(scale, 0.05)
				if hits >= need then
					finish(JobRules.scoreTiming(hits, misses))
					return
				end
				speed *= 1.08
				placeZone()
			else
				misses += 1
				needle.BackgroundColor3 = J.Miss
				Motion.tween(needle, Motion.Normal, { BackgroundColor3 = J.Needle })
				JobFX.sound(J.Sounds.Miss, 0.4)
				shake(mg)
			end
		end)
		table.insert(conns, RunService.RenderStepped:Connect(function(dt)
			if finished then
				return
			end
			t += dt
			cooldown = math.max(0, cooldown - dt)
			needle.Position = UDim2.fromScale(needleX(), 0.5)
		end))
	elseif info.kind == "sequence" then
		local items: { string } = info.items or {}
		local buttonsList: { string } = info.buttons or items
		local ticket = mg.Sequence.Ticket
		local grid = mg.Sequence.Buttons
		for _, c in ticket:GetChildren() do
			if c:IsA("GuiObject") then
				c:Destroy()
			end
		end
		for _, c in grid:GetChildren() do
			if c:IsA("GuiObject") then
				c:Destroy()
			end
		end
		local chips: { TextLabel } = {}
		for i, name in items do
			local chip = Instance.new("TextLabel")
			chip.Name = "Item" .. i
			chip.AutomaticSize = Enum.AutomaticSize.X
			chip.Size = UDim2.fromOffset(0, 24)
			chip.BackgroundColor3 = Color3.fromRGB(230, 222, 200)
			chip.TextColor3 = Color3.fromRGB(40, 36, 30)
			chip.FontFace = Theme.Fonts.Bold
			chip.TextSize = 13
			chip.Text = string.format("  %d. %s  ", i, name)
			local corner = Instance.new("UICorner")
			corner.CornerRadius = UDim.new(0, 4)
			corner.Parent = chip
			chip.Parent = ticket
			table.insert(chips, chip)
		end
		local nextIndex, mistakes = 1, 0
		local buttons: { TextButton } = {}
		local function tap(name: string, btn: TextButton)
			if finished then
				return
			end
			if name == items[nextIndex] then
				local chip = chips[nextIndex]
				chip.BackgroundColor3 = J.Hit
				chip.Text = "  ✓ " .. name .. "  "
				btn.BackgroundTransparency = 0.7
				btn.Active = false
				btn.AutoButtonColor = false
				JobFX.sound(J.Sounds.Hit, 0.4, 1 + nextIndex * 0.08)
				fx.hit()
				punch(scale, 0.04)
				nextIndex += 1
				if nextIndex > #items then
					finish(JobRules.scoreSequence(mistakes))
				end
			elseif btn.Active then
				mistakes += 1
				btn.BackgroundColor3 = J.Miss
				Motion.tween(btn, Motion.Normal, { BackgroundColor3 = Theme.Phone.Card })
				JobFX.sound(J.Sounds.Miss, 0.4)
				shake(mg)
			end
		end
		for i, name in buttonsList do
			local btn = Instance.new("TextButton")
			btn.Name = "Choice" .. i
			btn.LayoutOrder = i
			btn.BackgroundColor3 = Theme.Phone.Card
			btn.TextColor3 = C.Text
			btn.FontFace = Theme.Fonts.Bold
			btn.TextSize = 13
			btn.TextWrapped = true
			btn.Text = if UserInputService.KeyboardEnabled and i <= #NUMBER_KEYS then (i .. "  " .. name) else name
			btn.Selectable = true
			local corner = Instance.new("UICorner")
			corner.CornerRadius = Theme.CornerSmall
			corner.Parent = btn
			btn.Parent = grid
			table.insert(conns, btn.Activated:Connect(function()
				tap(name, btn)
			end))
			table.insert(buttons, btn)
		end
		table.insert(conns, UserInputService.InputBegan:Connect(function(input, processed)
			if processed then
				return
			end
			local idx = table.find(NUMBER_KEYS, input.KeyCode)
			if idx and buttons[idx] then
				tap(buttonsList[idx], buttons[idx])
			end
		end))
		if UserInputService.GamepadEnabled and buttons[1] then
			GuiService.SelectedObject = buttons[1]
		end
	end

	return { cancel = cancel }
end

return Minigames
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "LightingController", "ModuleScript", [======[--!strict
-- Draws the time of day on this client (Master Plan §4 "Lighting and time of day"; looks in Config/DayNight).
--   * the clock comes from the server (TimeService: Workspace attributes MTL_DayEpoch / MTL_DayFrozen) and the sun
--     moves every frame; the rest of the look (ambient, atmosphere, grade, bloom, sun rays, clouds) is blended
--     between the keyframes a few times a second
--   * street lights: lamp heads glow sodium orange at night (each switches at a slightly different moment), and
--     the closest lamps to the camera get real SpotLights (a fixed pool, so the cost never grows with the map)
--   * story holds: a cutscene can show THIS player another time without touching anyone else. PowerOut = night,
--     NextDay = night, then morning on the "WorldMorning" beat. A hold made in a room ends when you walk out.
-- API:
--   LightingController.clock() -> hour 0-24 (what this player sees)
--   LightingController.phase() -> "Morning" | "Day" | "Evening" | "Night"
--   LightingController.hold(hour, blendSeconds?, untilLeaveRoom?)   LightingController.release(blendSeconds?)
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local Lighting = game:GetService("Lighting")

local DayNight = require(ReplicatedStorage.MTL.Config.DayNight)
local DayNightRules = require(ReplicatedStorage.MTL.Rules.DayNightRules)
local Cutscene = require(script.Parent.CutsceneController)

local player = Players.LocalPlayer
local LightingController = {}

local LOOK_EVERY = 0.12 -- seconds between full look blends (the sun itself moves every frame)

-- the instances we drive (the place's own ones are taken over; missing ones are made)
local atmosphere: Atmosphere
local grade: ColorCorrectionEffect
local bloom: BloomEffect
local rays: SunRaysEffect
local clouds: Clouds?

type Hold = {
	hour: number,
	from: number, -- clock shown when the hold (or release) started
	start: number,
	blend: number,
	room: boolean,
	releasing: boolean,
}
local hold: Hold? = nil
local shownClock = DayNight.StartClock
local lampsValue = 0

local function find(className: string, name: string): any
	local inst = Lighting:FindFirstChild(name)
	if inst and inst.ClassName == className then
		return inst
	end
	inst = Lighting:FindFirstChildOfClass(className :: any)
	if inst and className ~= "ColorCorrectionEffect" then
		return inst
	end
	local made = Instance.new(className :: any)
	made.Name = name
	made.Parent = Lighting
	return made
end

local function worldClock(): number
	local frozen = workspace:GetAttribute("MTL_DayFrozen")
	if type(frozen) == "number" then
		return frozen
	end
	local epoch = workspace:GetAttribute("MTL_DayEpoch")
	if type(epoch) ~= "number" then
		return DayNight.StartClock
	end
	return DayNightRules.clockAt(workspace:GetServerTimeNow() - epoch)
end

local function inRoom(): boolean
	local char = player.Character
	local root = char and char:FindFirstChild("HumanoidRootPart") :: BasePart?
	return root ~= nil and root.Position.Y > DayNight.RoomArea.MinY
end

local function currentClock(): number
	local world = worldClock()
	local h = hold
	if not h then
		return world
	end
	local target = if h.releasing then world else h.hour
	local a = if h.blend <= 0 then 1 else math.clamp((os.clock() - h.start) / h.blend, 0, 1)
	a = a * a * (3 - 2 * a)
	if h.releasing and a >= 1 then
		hold = nil
		return world
	end
	return (h.from + DayNightRules.clockDelta(h.from, target) * a) % 24
end

function LightingController.clock(): number
	return shownClock
end

function LightingController.phase(): string
	return DayNightRules.phaseOf(shownClock)
end

function LightingController.hold(hour: number, blendSeconds: number?, untilLeaveRoom: boolean?)
	hold = {
		hour = hour % 24,
		from = shownClock,
		start = os.clock(),
		blend = blendSeconds or 0,
		room = untilLeaveRoom == true,
		releasing = false,
	}
end

function LightingController.release(blendSeconds: number?)
	local h = hold
	if not h or h.releasing then
		return
	end
	h.releasing = true
	h.from = shownClock
	h.start = os.clock()
	h.blend = blendSeconds or 3
end

----------------------------------------------------------------------------------------------------------------
-- the look

local function lerpN(a: number, b: number, t: number): number
	return a + (b - a) * t
end

local function applyLook(clock: number)
	local a, b, t = DayNightRules.sample(clock)
	local function n(k: string): number
		return lerpN(a[k], b[k], t)
	end
	local function c(k: string): Color3
		return (a[k] :: Color3):Lerp(b[k], t)
	end
	Lighting.Brightness = n("Brightness")
	Lighting.ExposureCompensation = n("Exposure")
	Lighting.Ambient = c("Ambient")
	Lighting.OutdoorAmbient = c("Outdoor")
	Lighting.ColorShift_Top = c("Top")
	Lighting.ColorShift_Bottom = c("Bottom")
	Lighting.EnvironmentDiffuseScale = n("EnvDiffuse")
	Lighting.EnvironmentSpecularScale = n("EnvSpecular")
	Lighting.ShadowSoftness = n("Softness")
	atmosphere.Density = n("Density")
	atmosphere.Offset = n("Offset")
	atmosphere.Color = c("AtmoColor")
	atmosphere.Decay = c("Decay")
	atmosphere.Glare = n("Glare")
	atmosphere.Haze = n("Haze")
	grade.Brightness = n("GBright")
	grade.Contrast = n("Contrast")
	grade.Saturation = n("Saturation")
	grade.TintColor = c("Tint")
	bloom.Intensity = n("Bloom")
	bloom.Size = n("BloomSize")
	bloom.Threshold = n("Threshold")
	rays.Intensity = n("Rays")
	rays.Spread = n("Spread")
	local cl = clouds
	if cl then
		cl.Cover = n("Cover")
		cl.Density = n("CloudDensity")
		cl.Color = c("CloudColor")
	end
	lampsValue = n("Lamps")
end

----------------------------------------------------------------------------------------------------------------
-- street lights

local L = DayNight.Lamps
type Lamp = { head: BasePart, park: boolean, threshold: number, on: boolean?, light: Light? }
local lamps: { [BasePart]: Lamp } = {}
local spotPool: { SpotLight } = {}
local pointPool: { PointLight } = {}
local lit: { Lamp } = {}

local function register(part: Instance)
	if not part:IsA("BasePart") or lamps[part] then
		return
	end
	if part.Material ~= Enum.Material.Neon and not part:GetAttribute("MTL_LampHead") then
		return
	end
	local model = part.Parent
	if not model or not model:IsA("Model") or not L.Models[model.Name] then
		return
	end
	lamps[part] = {
		head = part,
		park = model.Name ~= "StreetLight",
		threshold = L.On + (math.random() - 0.5) * 0.3, -- staggered switch-on, like real photocells
	}
	-- apply the current state right away (streamed in mid-night)
	local on = lampsValue >= lamps[part].threshold
	part.Material = if on then Enum.Material.Neon else Enum.Material.SmoothPlastic
	part.Color = if on then L.HeadNight else L.HeadDay
	lamps[part].on = on
end

local function takeLight(park: boolean): Light
	if park then
		local l = table.remove(pointPool)
		if l then
			return l
		end
		local p = Instance.new("PointLight")
		p.Name = "MTL_LampLight"
		p.Color = L.ParkLight.Color
		p.Range = L.ParkLight.Range
		p.Shadows = false
		return p
	end
	local s = table.remove(spotPool)
	if s then
		return s
	end
	local sp = Instance.new("SpotLight")
	sp.Name = "MTL_LampLight"
	sp.Face = Enum.NormalId.Bottom
	sp.Color = L.Light.Color
	sp.Range = L.Light.Range
	sp.Angle = L.Light.Angle
	return sp
end

local function giveBack(lamp: Lamp)
	local l = lamp.light
	if not l then
		return
	end
	lamp.light = nil
	l.Parent = nil
	if l:IsA("SpotLight") then
		table.insert(spotPool, l)
	elseif l:IsA("PointLight") then
		table.insert(pointPool, l)
	end
end

local function refreshLamps()
	local camPos = workspace.CurrentCamera.CFrame.Position
	local candidates = {}
	for head, lamp in lamps do
		if not head.Parent then
			giveBack(lamp)
			lamps[head] = nil
			continue
		end
		local on = lampsValue >= lamp.threshold
		if on ~= lamp.on then
			lamp.on = on
			head.Material = if on then Enum.Material.Neon else Enum.Material.SmoothPlastic
			head.Color = if on then L.HeadNight else L.HeadDay
		end
		if on then
			local d = (head.Position - camPos).Magnitude
			if d < L.Radius then
				table.insert(candidates, { lamp = lamp, d = d })
			end
		end
	end
	table.sort(candidates, function(x, y)
		return x.d < y.d
	end)
	local keep: { [Lamp]: number } = {}
	for i = 1, math.min(#candidates, L.MaxLights) do
		keep[candidates[i].lamp] = i
	end
	for _, lamp in lit do
		if not keep[lamp] then
			giveBack(lamp)
		end
	end
	lit = {}
	-- lights fade in with the lamps value, so dusk isn't a pop
	local strength = math.clamp((lampsValue - 0.3) / 0.7, 0, 1)
	for lamp, rank in keep do
		local l = lamp.light or takeLight(lamp.park)
		lamp.light = l
		l.Brightness = (if lamp.park then L.ParkLight.Brightness else L.Light.Brightness) * strength
		l.Shadows = (not lamp.park) and rank <= L.Shadows
		l.Parent = lamp.head
		table.insert(lit, lamp)
	end
end

----------------------------------------------------------------------------------------------------------------

function LightingController.init()
	atmosphere = find("Atmosphere", "Atmosphere")
	grade = find("ColorCorrectionEffect", "ColorCorrection")
	bloom = find("BloomEffect", "Bloom")
	rays = find("SunRaysEffect", "SunRays")
	clouds = workspace.Terrain:FindFirstChildOfClass("Clouds")
	Lighting.GlobalShadows = true
	Lighting.GeographicLatitude = DayNight.Latitude
	if DayNight.HideMapSky then
		local sky = Lighting:FindFirstChildOfClass("Sky")
		if sky then
			sky.Parent = nil -- this client only; the place keeps its Sky
		end
	end
	Lighting.FogEnd = 100000 -- the Atmosphere does the haze

	shownClock = worldClock()
	applyLook(shownClock)

	-- lamps: what's streamed in now + whatever streams in later
	local map = workspace:FindFirstChild("ViceBay")
	if map then
		for _, d in map:GetDescendants() do
			register(d)
		end
	end
	workspace.DescendantAdded:Connect(function(d)
		if d:IsA("BasePart") and d.Material == Enum.Material.Neon then
			task.defer(register, d) -- parent model name is set by then
		end
	end)

	-- story holds (only this player sees them)
	local sceneHold = false -- a scene's own `hour` (Research: Cinematic Cutscenes §4), released when it ends
	Cutscene.Started:Connect(function(id, scene)
		if id == "PowerOut" then
			LightingController.hold(DayNight.Story.MoveIn, 0, true)
		elseif id == "NextDay" then
			LightingController.hold(DayNight.Story.Sleep, 0, true)
		elseif type(scene) == "table" and type(scene.hour) == "number" then
			LightingController.hold(scene.hour, 0)
			sceneHold = true
		end
	end)
	Cutscene.Finished:Connect(function()
		if sceneHold then
			sceneHold = false
			LightingController.release(4)
		end
	end)
	Cutscene.registerAction("WorldMorning", function()
		LightingController.hold(DayNight.Story.Wake, 0, true)
	end)

	-- small mood filters on top of the look (grade split, far blur, vignette, dust)
	require(script.Parent.MoodFX).init(LightingController)

	local lookTimer, lampTimer = 0, 0
	RunService.Heartbeat:Connect(function(dt)
		local h = hold
		if h and h.room and not h.releasing and not Cutscene.isPlaying() and not inRoom() then
			LightingController.release(2.5)
		end
		shownClock = currentClock()
		Lighting.ClockTime = shownClock
		lookTimer += dt
		if lookTimer >= LOOK_EVERY then
			lookTimer = 0
			applyLook(shownClock)
		end
		lampTimer += dt
		if lampTimer >= L.Refresh then
			lampTimer = 0
			refreshLamps()
		end
	end)
end

return LightingController
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "MapMarkers", "ModuleScript", [======[--!strict
-- Round emoji markers floating over places in the world (jobs, parks, shops...), from Config/HUD.Markers.
-- Drawn in their own ScreenGui (MTL_Markers, IgnoreGuiInset so they line up with the camera) and placed every
-- frame with WorldToViewportPoint, which keeps them crisp at any distance. Close markers win: a marker that
-- would overlap a nearer one is hidden. The name + distance shows when you're close or looking right at it.
-- Positions come from config (not map parts), so StreamingEnabled never hides them. The map's own POI
-- "MapIcon" billboards are switched off on the client so only one set of icons shows.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local Config = require(ReplicatedStorage.MTL.Config.HUD)
local Theme = require(ReplicatedStorage.MTL.UI.Theme)
local Format = require(ReplicatedStorage.MTL.Format)
local StoryRules = require(ReplicatedStorage.MTL.Rules.StoryRules)
local Build = require(ReplicatedStorage.MTL.UI.Build.HUD)
local ClientData = require(script.Parent.ClientData)
local UIState = require(script.Parent.UIState)

local player = Players.LocalPlayer
local M = Config.Markers

local Markers = {}

type Entry = { def: any, frame: Frame, pos: Vector3, range: number, shown: boolean, alpha: number }
local entries: { Entry } = {}
local gui: ScreenGui
local hidden = false
local OVERLAP = 1.12 -- markers keep this much space between them (1 = just touching); the farther one hides

local function allowed(def: any): boolean
	if not def.requires then
		return true
	end
	local data = ClientData.get()
	local stage = data and data.Story and data.Story.Stage
	return stage ~= nil and StoryRules.reached(stage, def.requires)
end

local function setAlpha(e: Entry, a: number)
	if math.abs(e.alpha - a) < 0.01 then
		return
	end
	e.alpha = a
	local disc = e.frame:FindFirstChild("Disc") :: Frame
	disc.BackgroundTransparency = 1 - (1 - Theme.HUD.MarkerTransparency) * a
	local ic = disc:FindFirstChild("Icon")
	if ic and ic:IsA("TextLabel") then
		ic.TextTransparency = 1 - a
	elseif ic and ic:IsA("ImageLabel") then
		ic.ImageTransparency = 1 - a
	end
	local st = disc:FindFirstChild("Stroke") :: UIStroke?
	if st then
		st.Transparency = 1 - 0.2 * a
	end
end

local function step()
	local cam = workspace.CurrentCamera
	if hidden or not cam then
		for _, e in entries do
			e.frame.Visible = false
		end
		return
	end
	local camPos = cam.CFrame.Position
	local char = player.Character
	local root = char and char:FindFirstChild("HumanoidRootPart") :: BasePart?
	local me = if root then root.Position else camPos
	local vp = cam.ViewportSize
	local centre = vp / 2

	-- nearest first, so the nearer marker wins any overlap
	local visible = {}
	for _, e in entries do
		local d = (e.pos - me).Magnitude
		if d <= e.range and e.def._ok then
			local top = e.pos + Vector3.new(0, M.Height, 0)
			local sp, onScreen = cam:WorldToViewportPoint(top)
			if onScreen and sp.Z > 0 then
				table.insert(visible, { e = e, d = d, sp = Vector2.new(sp.X, sp.Y) })
				continue
			end
		end
		e.frame.Visible = false
	end
	table.sort(visible, function(a, b)
		return a.d < b.d
	end)
	local placed: { { p: Vector2, r: number } } = {}
	local best: Entry? = nil
	local bestScore, bestD = math.huge, 0
	for rank, v in visible do
		local e = v.e
		e.frame.ZIndex = 1000 - rank -- nearer markers draw on top
		local t = math.clamp((v.d - 60) / (M.Range - 60), 0, 1)
		local scale = 1 - (1 - M.MinScale) * t
		local radius = M.Size * scale / 2
		local blocked = false
		for _, p in placed do
			if (p.p - v.sp).Magnitude < (p.r + radius) * OVERLAP then
				blocked = true
				break
			end
		end
		if blocked then
			e.frame.Visible = false
			continue
		end
		table.insert(placed, { p = v.sp, r = radius })
		e.frame.Visible = true
		e.frame.Position = UDim2.fromOffset(v.sp.X, v.sp.Y)
		;(e.frame:FindFirstChild("Scale") :: UIScale).Scale = scale
		-- fade in the last 15% of the range
		local fade = math.clamp((e.range - v.d) / (e.range * 0.15), 0, 1)
		setAlpha(e, fade)
		-- one name tag at a time: the marker you're looking at, else the nearest one you're standing by
		local off = (v.sp - centre).Magnitude
		local score = if off < math.min(vp.X, vp.Y) * 0.12 then off elseif v.d <= M.LabelRange then 1000 + v.d else math.huge
		if score < bestScore then
			bestScore, best, bestD = score, e, v.d
		end
		;(e.frame:FindFirstChild("Tag") :: TextLabel).Visible = false
	end
	if best then
		local tag = best.frame:FindFirstChild("Tag") :: TextLabel
		-- the name tag gets its own space too: hide any other marker it would cover
		local bp = Vector2.new(best.frame.Position.X.Offset, best.frame.Position.Y.Offset)
		local s = (best.frame:FindFirstChild("Scale") :: UIScale).Scale
		local halfW = (#best.def.name * 8 + 70) / 2
		local top, bottom = bp.Y + M.Size * s / 2, bp.Y + M.Size * s / 2 + 30
		for _, e in entries do
			if e ~= best and e.frame.Visible then
				local p = Vector2.new(e.frame.Position.X.Offset, e.frame.Position.Y.Offset)
				local r = M.Size * (e.frame:FindFirstChild("Scale") :: UIScale).Scale / 2
				if math.abs(p.X - bp.X) < halfW + r and p.Y + r > top and p.Y - r < bottom then
					e.frame.Visible = false
				end
			end
		end
		tag.Visible = true
		tag.Text = string.format('%s  <font color="#9FE89A">%s</font>', best.def.name, Format.distance(bestD))
		best.frame.ZIndex = 2000
	end
end

local function refreshAllowed()
	for _, e in entries do
		e.def._ok = allowed(e.def)
	end
end

function Markers.init()
	local pg = player:WaitForChild("PlayerGui")
	local old = pg:FindFirstChild("MTL_Markers")
	if old then
		old:Destroy()
	end
	gui = Instance.new("ScreenGui")
	gui.Name = "MTL_Markers"
	gui.ResetOnSpawn = false
	gui.IgnoreGuiInset = true
	gui.DisplayOrder = 1 -- under the HUD and the phone
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	gui.Parent = pg

	for _, def in M.List do
		local f = Build.marker(def.emoji, def.name, M.Size)
		f.Name = "Marker_" .. def.name
		f.Visible = false
		f.Parent = gui
		table.insert(entries, { def = table.clone(def), frame = f, pos = def.pos, range = def.range or M.Range, shown = false, alpha = -1 })
	end
	-- the map ships its own "MapIcon" billboards on the POIs; these markers replace them, so switch those off
	-- (client only, the map itself is untouched) so the two sets never pile on top of each other
	local function quiet(inst: Instance)
		if inst:IsA("BillboardGui") and inst.Name == "MapIcon" then
			inst.Enabled = false
		end
	end
	for _, d in workspace:GetDescendants() do
		quiet(d)
	end
	workspace.DescendantAdded:Connect(quiet)

	refreshAllowed()
	ClientData.Changed:Connect(refreshAllowed)
	UIState.Changed:Connect(function(state)
		hidden = state.hideHUD or state.hideWaypoints
	end)
	RunService:BindToRenderStep("MTL_MapMarkers", Enum.RenderPriority.Camera.Value + 2, step)
end

return Markers
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "MenuController", "ModuleScript", [======[--!strict
-- The icon menu on the left: hidden until you press Menu/Toggle (or G / DPadLeft), then a 2-column grid of
-- big icon tiles slides out. Tiles come from Config/HUD.Menu. Also runs the Store and Emotes popups.
--   Menu.open()  Menu.close()  Menu.toggle()  Menu.isOpen()  Menu.openPanel("Store" | "Emotes")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local UserInputService = game:GetService("UserInputService")

local Lighting = game:GetService("Lighting")
local MarketplaceService = game:GetService("MarketplaceService")

local Net = require(ReplicatedStorage.MTL.Net)
local Format = require(ReplicatedStorage.MTL.Format)
local Monetization = require(ReplicatedStorage.MTL.Config.Monetization)
local LowPoly = require(ReplicatedStorage.MTL.UI.LowPoly)
local Theme = require(ReplicatedStorage.MTL.UI.Theme)
local Motion = require(ReplicatedStorage.MTL.UI.Motion)
local Config = require(ReplicatedStorage.MTL.Config.HUD)
local StoryRules = require(ReplicatedStorage.MTL.Rules.StoryRules)
local Build = require(ReplicatedStorage.MTL.UI.Build.HUD)
local ClientData = require(script.Parent.ClientData)
local UIState = require(script.Parent.UIState)

local player = Players.LocalPlayer
local H = Theme.HUD

local Menu = {}

local gui: any
local menuOpen = false
local panels: { [string]: Frame } = {}
local openPanelName: string? = nil
local emoteTrack: AnimationTrack? = nil

-- all UI sounds go through the shared Sfx module (Theme.Sfx), so the whole game sounds the same
local Sfx: any = nil
do
	local m = ReplicatedStorage.MTL.UI:FindFirstChild("Sfx")
	if m then
		local ok, mod = pcall(require, m)
		Sfx = if ok then mod else nil
	end
end
local function sound(name: string)
	if Sfx then
		pcall(Sfx.play, name)
	end
end

local function phone(): any
	local m = script.Parent:FindFirstChild("PhoneController")
	if not m then
		return nil
	end
	local ok, p = pcall(require, m)
	return if ok then p else nil
end

-- press feedback: shrink on press, lift on hover
local function juice(button: GuiButton, scale: UIScale)
	button.MouseEnter:Connect(function()
		sound("Hover")
		Motion.tween(scale, Motion.Fast, { Scale = 1.05 })
	end)
	button.MouseLeave:Connect(function()
		Motion.tween(scale, Motion.Fast, { Scale = 1 })
	end)
	button.MouseButton1Down:Connect(function()
		Motion.tween(scale, Motion.Fast, { Scale = 0.92 })
	end)
	button.MouseButton1Up:Connect(function()
		Motion.tween(scale, Motion.Spring, { Scale = 1 })
	end)
end

---------------------------------------------------------------- tiles

local function allowed(entry: any): boolean
	local data = ClientData.get()
	if entry.path and (not data or data.Path ~= entry.path) then
		return false
	end
	if entry.requires then
		local stage = data and data.Story and data.Story.Stage
		if not stage or not StoryRules.reached(stage, entry.requires) then
			return false
		end
	end
	return true
end

local function refreshTiles()
	local grid = gui.Menu.Panel.Grid
	local shown = 0
	for _, entry in Config.Menu do
		local tile = grid:FindFirstChild("Tile_" .. entry.id)
		if tile then
			tile.Visible = allowed(entry)
			shown += if tile.Visible then 1 else 0
		end
	end
	local rows = math.ceil(shown / 2)
	grid.Size = UDim2.fromOffset(192, rows * 92 + math.max(rows - 1, 0) * 8)
end

local function run(entry: any)
	sound("Tap")
	if entry.action == "phone" then
		Menu.close()
		local p = phone()
		if p then
			p.toggle()
		end
	elseif entry.action == "app" then
		Menu.close()
		local p = phone()
		if p then
			p.open(entry.app)
		end
	elseif entry.action == "panel" then
		Menu.openPanel(entry.panel)
	end
end

local function buildTiles()
	local grid = gui.Menu.Panel.Grid
	local template = grid.TileTemplate
	for i, entry in Config.Menu do
		local tile = grid:FindFirstChild("Tile_" .. entry.id)
		if not tile then
			tile = template:Clone()
			tile.Name = "Tile_" .. entry.id
			tile.LayoutOrder = i
			tile.Label.Text = entry.label
			local img = H.Images[entry.id]
			local old = tile:FindFirstChild("Icon")
			if img and img ~= "" and old then
				-- Alex's icon art replaces the emoji
				local pos = old.Position
				old:Destroy()
				local ic = Build.icon(tile, "", 52, entry.id)
				ic.Position = pos
			elseif old then
				old.Text = entry.emoji
			end
			tile.Parent = grid
		end
		local scale = Instance.new("UIScale")
		scale.Parent = tile
		juice(tile, scale)
		tile.Activated:Connect(function()
			run(entry)
		end)
	end
	refreshTiles()
end

---------------------------------------------------------------- open / close

function Menu.isOpen(): boolean
	return menuOpen
end

-- Opening: the button shrinks away and the panel slides out from the left edge in its place.
-- Closing (the ‹ tab on the panel, G, Esc, or picking a tile): the panel slides back and the button pops back.
local SLIDE_IN = TweenInfo.new(0.42, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local SLIDE_OUT = TweenInfo.new(0.24, Enum.EasingStyle.Quint, Enum.EasingDirection.In)
local OPEN_X = UDim2.new(0, 0, 0.5, 0)
local CLOSED_X = UDim2.new(0, -260, 0.5, 0)
local toggleScale: UIScale

function Menu.open()
	if menuOpen then
		return
	end
	menuOpen = true
	refreshTiles()
	local toggle = gui.Menu.Toggle
	Motion.tween(toggleScale, TweenInfo.new(0.16, Enum.EasingStyle.Back, Enum.EasingDirection.In), { Scale = 0 }).Completed:Once(function()
		if menuOpen then
			toggle.Visible = false
		end
	end)
	local panel = gui.Menu.Panel
	panel.Pop.Scale = 1
	panel.Position = CLOSED_X
	panel.Visible = true
	Motion.tween(panel, SLIDE_IN, { Position = OPEN_X })
	-- tiles pop in one after another
	for _, tile in panel.Grid:GetChildren() do
		if tile:IsA("GuiButton") and tile.Visible then
			local sc = tile:FindFirstChildOfClass("UIScale")
			if sc then
				sc.Scale = 0.5
				task.delay(0.06 + tile.LayoutOrder * 0.03, function()
					Motion.tween(sc, Motion.Spring, { Scale = 1 })
				end)
			end
		end
	end
	panel.Collapse.Modal = true -- frees the mouse in shift lock / first person
	sound("Open")
end

function Menu.close()
	if not menuOpen then
		return
	end
	menuOpen = false
	local panel = gui.Menu.Panel
	panel.Collapse.Modal = false
	Motion.tween(panel, SLIDE_OUT, { Position = CLOSED_X }).Completed:Once(function()
		if not menuOpen then
			panel.Visible = false
		end
	end)
	local toggle = gui.Menu.Toggle
	task.delay(0.12, function()
		if menuOpen then
			return
		end
		toggle.Visible = true
		Motion.tween(toggleScale, Motion.Spring, { Scale = 1 })
	end)
	sound("Close")
end

function Menu.toggle()
	if menuOpen then
		Menu.close()
	else
		Menu.open()
	end
end

---------------------------------------------------------------- popups (Store, Emotes)
-- An open popup dims and blurs the game behind it (Panels/Dim + a local BlurEffect); clicking the dim closes it.

local BLUR = 14
local blur: BlurEffect? = nil
local fitScale = 1

local function getBlur(): BlurEffect
	if blur and blur.Parent then
		return blur
	end
	local b = Instance.new("BlurEffect")
	b.Name = "MTL_MenuBlur"
	b.Size = 0
	b.Parent = Lighting
	blur = b
	return b
end

local function backdrop(on: boolean)
	local dim = gui.Panels.Dim
	if on then
		dim.Visible = true
		Motion.tween(dim, Motion.Normal, { BackgroundTransparency = 0.45 })
		Motion.tween(getBlur(), Motion.Normal, { Size = BLUR })
	else
		Motion.tween(getBlur(), Motion.Fast, { Size = 0 })
		Motion.tween(dim, Motion.Fast, { BackgroundTransparency = 1 }).Completed:Once(function()
			if openPanelName == nil then
				dim.Visible = false
			end
		end)
	end
end

local function closePanel()
	if not openPanelName then
		return
	end
	local p = panels[openPanelName]
	openPanelName = nil
	backdrop(false)
	sound("Close")
	if p then
		Motion.tween(p.Pop, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { Scale = fitScale * 0.85 }).Completed:Once(function()
			if openPanelName == nil or panels[openPanelName] ~= p then
				p.Visible = false
			end
		end)
	end
end

local function stopEmote()
	if emoteTrack then
		emoteTrack:Stop(0.25)
		emoteTrack = nil
	end
end

local function playEmote(e: any)
	local char = player.Character
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	local animate = char and char:FindFirstChild("Animate")
	local folder = animate and animate:FindFirstChild(e.anim)
	if not (hum and folder) then
		return
	end
	local anim = folder:FindFirstChildOfClass("Animation")
	if not anim then
		return
	end
	stopEmote()
	local animator = hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum)
	local track = (animator :: Animator):LoadAnimation(anim)
	track.Priority = Enum.AnimationPriority.Action
	track.Looped = string.sub(e.anim, 1, 5) == "dance"
	track:Play(0.2)
	emoteTrack = track
end

---------------------------------------------------------------- the Store

local priceCache: { [string]: string } = {}

-- "R$ 199", "OWNED", or "SOON" (id not set up yet). Asks Roblox once per item.
local function priceText(item: string): (string, boolean)
	local passId = Monetization.Passes[item]
	local productId = Monetization.Products[item]
	if passId and player:GetAttribute("MTL_Pass_" .. item) then
		return "OWNED", false
	end
	local id = passId or productId
	if not id or id == 0 then
		return "SOON", false
	end
	if priceCache[item] then
		return priceCache[item], true
	end
	local ok, info = pcall(function()
		return MarketplaceService:GetProductInfo(id, if passId then Enum.InfoType.GamePass else Enum.InfoType.Product)
	end)
	local text = if ok and info and info.PriceInRobux then "R$ " .. tostring(info.PriceInRobux) else "BUY"
	priceCache[item] = text
	return text, true
end

local function refreshCard(card: Frame, def: any)
	local buy = card:FindFirstChild("Buy") :: TextButton
	local label = buy:FindFirstChild("Text") :: TextLabel
	label.Text = "..."
	task.spawn(function()
		local text, canBuy = priceText(def.item)
		label.Text = text
		LowPoly.style(buy, if canBuy then Color3.fromRGB(44, 168, 64) elseif text == "OWNED" then Color3.fromRGB(60, 96, 70) else Color3.fromRGB(70, 72, 80), { corner = Theme.LowPoly.CornerSmall })
		buy:SetAttribute("CanBuy", canBuy)
	end)
end

local function buildStore(): Frame
	local p = Build.panel("Store", "Store", 860, 600)
	local sub = Instance.new("TextLabel")
	sub.Name = "Sub"
	sub.Position = UDim2.fromOffset(22, 48)
	sub.Size = UDim2.fromOffset(400, 20)
	sub.BackgroundTransparency = 1
	sub.FontFace = Theme.Fonts.Body
	sub.Text = "Upgrade your hustle. Every purchase supports the game."
	sub.TextColor3 = Theme.Colors.TextDim
	sub.TextSize = 14
	sub.TextXAlignment = Enum.TextXAlignment.Left
	sub.Parent = p
	local list = p.List
	list.UIListLayout:Destroy()
	list.Position = UDim2.fromOffset(24, 146)
	list.Size = UDim2.new(1, -48, 1, -166)
	list.ScrollingDirection = Enum.ScrollingDirection.Y
	local grid = Instance.new("UIGridLayout")
	grid.CellSize = UDim2.fromOffset(236, 330)
	grid.CellPadding = UDim2.fromOffset(28, 24)
	grid.HorizontalAlignment = Enum.HorizontalAlignment.Center
	grid.SortOrder = Enum.SortOrder.LayoutOrder
	grid.Parent = list

	-- your cash, top right next to the close button
	local cashChip = Instance.new("TextLabel")
	cashChip.Name = "Wallet"
	cashChip.AnchorPoint = Vector2.new(1, 0)
	cashChip.Position = UDim2.new(1, -66, 0, 16)
	cashChip.Size = UDim2.fromOffset(160, 36)
	cashChip.FontFace = Theme.HUD.CashFont
	cashChip.TextColor3 = Theme.HUD.CashText
	cashChip.TextSize = 20
	cashChip.Text = "$0"
	cashChip.Parent = p
	LowPoly.style(cashChip, Color3.fromRGB(30, 110, 46), { corner = Theme.LowPoly.CornerSmall, outline = Theme.LowPoly.OutlineThin, rim = false })
	local function wallet()
		local data = ClientData.get()
		local t = cashChip:FindFirstChild("Text") :: TextLabel?
		if t and data then
			t.Text = "💵 " .. Format.cash(data.Cash or 0)
		end
	end
	wallet()
	ClientData.Changed:Connect(wallet)

	-- tabs
	local tabs = Instance.new("Frame")
	tabs.Name = "Tabs"
	tabs.Position = UDim2.fromOffset(22, 86)
	tabs.Size = UDim2.new(1, -44, 0, 42)
	tabs.BackgroundTransparency = 1
	tabs.Parent = p
	local tl = Instance.new("UIListLayout")
	tl.FillDirection = Enum.FillDirection.Horizontal
	tl.Padding = UDim.new(0, 10)
	tl.SortOrder = Enum.SortOrder.LayoutOrder
	tl.Parent = tabs

	local cards: { [string]: Frame } = {}
	local function showTab(tabId: string)
		for _, t in Config.StoreTabs do
			local b = tabs:FindFirstChild("Tab_" .. t.id) :: GuiObject
			local on = t.id == tabId
			LowPoly.style(b, if on then Color3.fromRGB(236, 184, 60) else Color3.fromRGB(40, 42, 50), { corner = Theme.LowPoly.CornerSmall, outline = Theme.LowPoly.OutlineThin, rim = false })
		end
		local order = 0
		for _, def in Config.Store do
			local card = cards[def.item]
			card.Visible = def.tab == tabId
			if card.Visible then
				order += 1
				card.LayoutOrder = order
				card.Pop.Scale = 0.85
				task.delay(order * 0.04, function()
					Motion.tween(card.Pop, Motion.Spring, { Scale = 1 })
				end)
				refreshCard(card, def)
			end
		end
		list.CanvasPosition = Vector2.zero
	end
	for i, t in Config.StoreTabs do
		local b = Build.storeTab(t.id, t.label)
		b.LayoutOrder = i
		b.Parent = tabs
		b.Activated:Connect(function()
			sound("Tap")
			showTab(t.id)
		end)
	end
	for _, def in Config.Store do
		local card = Build.storeCard(def)
		card.Parent = list
		cards[def.item] = card
		local buy = card:FindFirstChild("Buy") :: TextButton
		local press = buy:FindFirstChild("Press") :: UIScale
		buy.MouseEnter:Connect(function()
			Motion.tween(card.Pop, Motion.Fast, { Scale = 1.03 })
			sound("Hover")
		end)
		buy.MouseLeave:Connect(function()
			Motion.tween(card.Pop, Motion.Fast, { Scale = 1 })
		end)
		buy.MouseButton1Down:Connect(function()
			Motion.tween(press, Motion.Fast, { Scale = 0.93 })
		end)
		buy.MouseButton1Up:Connect(function()
			Motion.tween(press, Motion.Spring, { Scale = 1 })
		end)
		buy.Activated:Connect(function()
			if buy:GetAttribute("CanBuy") then
				sound("Confirm")
				Net.get("PhoneAction"):FireServer({ type = "buy", item = def.item })
			else
				sound("Error")
			end
		end)
	end
	-- passes owned / bought while the store is open
	player.AttributeChanged:Connect(function(attr)
		if string.sub(attr, 1, 9) == "MTL_Pass_" then
			local item = string.sub(attr, 10)
			for _, def in Config.Store do
				if def.item == item then
					refreshCard(cards[item], def)
				end
			end
		end
	end)
	p:SetAttribute("Tab", Config.StoreTabs[1].id)
	showTab(Config.StoreTabs[1].id)
	return p
end

---------------------------------------------------------------- the emote wheel

local function buildEmotes(): Frame
	local p = Build.panel("Emotes", "Emotes", 440, 460)
	p.List:Destroy()
	local wheel = Instance.new("Frame")
	wheel.Name = "Wheel"
	wheel.AnchorPoint = Vector2.new(0.5, 0.5)
	wheel.Position = UDim2.new(0.5, 0, 0.5, 22)
	wheel.Size = UDim2.fromOffset(340, 340)
	wheel.BackgroundTransparency = 1
	wheel.Parent = p
	local hub = Instance.new("TextLabel")
	hub.Name = "Hub"
	hub.AnchorPoint = Vector2.new(0.5, 0.5)
	hub.Position = UDim2.fromScale(0.5, 0.5)
	hub.Size = UDim2.fromOffset(120, 120)
	hub.FontFace = Theme.HUD.Font
	hub.TextColor3 = Theme.Colors.Text
	hub.TextSize = 16
	hub.TextWrapped = true
	hub.Text = "Choose an emote"
	hub.Parent = wheel
	LowPoly.style(hub, Color3.fromRGB(30, 31, 38), { corner = UDim.new(1, 0), outline = 0, rim = false })
	local ring = Instance.new("UIStroke") -- round joins: a mitred outline draws a square box around a circle
	ring.Color = Theme.LowPoly.Outline
	ring.Thickness = Theme.LowPoly.OutlineThin
	ring.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	ring.Parent = hub
	local hubText = hub:FindFirstChild("Text") :: TextLabel
	local template = gui.Menu.Panel.Grid.TileTemplate
	local n = #Config.Emotes
	for i, e in Config.Emotes do
		local a = math.rad(-90 + (i - 1) * 360 / n)
		local tile = template:Clone()
		tile.Name = "Emote_" .. e.id
		tile.Visible = true
		tile.AnchorPoint = Vector2.new(0.5, 0.5)
		tile.Size = UDim2.fromOffset(86, 86)
		tile.Position = UDim2.new(0.5, math.cos(a) * 124, 0.5, math.sin(a) * 124)
		tile.Label.Text = string.upper(e.label)
		tile.Label.Visible = false
		tile.Icon.Text = e.emoji
		tile.Icon.Position = UDim2.fromScale(0.5, 0.5)
		tile.Parent = wheel
		local scale = Instance.new("UIScale")
		scale.Parent = tile
		juice(tile, scale)
		tile.MouseEnter:Connect(function()
			hubText.Text = e.label
		end)
		tile.MouseLeave:Connect(function()
			hubText.Text = "Choose an emote"
		end)
		tile.Activated:Connect(function()
			sound("Tap")
			playEmote(e)
			closePanel()
		end)
	end
	return p
end

-- popups shrink to fit small screens (phones), never grow past their design size
local function fit(p: Frame)
	local vp = workspace.CurrentCamera.ViewportSize
	local base = p:GetAttribute("BaseSize") :: Vector2?
	if not base then
		base = Vector2.new(p.Size.X.Offset, p.Size.Y.Offset)
		p:SetAttribute("BaseSize", base)
	end
	fitScale = math.clamp(math.min((vp.X - 40) / base.X, (vp.Y - 60) / base.Y), 0.5, 1)
end

function Menu.openPanel(name: string)
	if openPanelName == name then
		closePanel()
		return
	end
	local had = openPanelName ~= nil
	if had then
		local old = panels[openPanelName :: string]
		openPanelName = nil
		if old then
			old.Visible = false
		end
	end
	local p = panels[name]
	if not p then
		p = if name == "Store" then buildStore() elseif name == "Emotes" then buildEmotes() else nil :: any
		if not p then
			return
		end
		p.ZIndex = 2
		p.Parent = gui.Panels
		p.Close.Activated:Connect(closePanel)
		panels[name] = p
	end
	Menu.close()
	openPanelName = name
	fit(p)
	p.Pop.Scale = fitScale * 0.85
	p.Visible = true
	Motion.tween(p.Pop, Motion.Spring, { Scale = fitScale })
	p.Close.Modal = true
	if not had then
		backdrop(true)
	end
	sound("Open")
end

---------------------------------------------------------------- init

function Menu.init()
	local pg = player:WaitForChild("PlayerGui")
	gui = pg:WaitForChild("MTL_HUD", 10)
	if not gui or not gui:FindFirstChild("Menu") then
		warn("[MTL Menu] MTL_HUD has no Menu (old HUD saved in StarterGui?)")
		return
	end
	buildTiles()
	gui.Panels.Dim.Activated:Connect(closePanel)

	local toggle = gui.Menu.Toggle
	toggleScale = Instance.new("UIScale")
	toggleScale.Parent = toggle
	juice(toggle, toggleScale)
	local collapse = gui.Menu.Panel.Collapse
	collapse.Activated:Connect(function()
		sound("Tap")
		Menu.close()
	end)
	toggle.Activated:Connect(function()
		if openPanelName then
			closePanel()
		end
		Menu.toggle()
	end)
	-- touch: no key hint
	if UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
		toggle.Key.Visible = false
	end

	UserInputService.InputBegan:Connect(function(input, processed)
		if processed then
			return
		end
		for _, k in Config.MenuKeys do
			if input.KeyCode == k then
				if openPanelName then
					closePanel()
				end
				Menu.toggle()
				return
			end
		end
		if input.KeyCode == Enum.KeyCode.Escape or input.KeyCode == Enum.KeyCode.ButtonB then
			closePanel()
			Menu.close()
		end
	end)

	ClientData.Changed:Connect(function()
		if menuOpen then
			refreshTiles()
		end
	end)
	UIState.Changed:Connect(function(state)
		if state.hideHUD then
			closePanel()
			Menu.close()
		end
	end)

	-- moving cancels an emote
	game:GetService("RunService").Heartbeat:Connect(function()
		if emoteTrack then
			local char = player.Character
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			if not hum or hum.MoveDirection.Magnitude > 0.1 or hum.Jump then
				stopEmote()
			end
		end
	end)
end

return Menu
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "MissionController", "ModuleScript", [======[--!strict
-- The client side of the story's crew stages and missions (Piece 3). Renders what MissionState says; every step is
-- decided by the server (MissionService / StoryCrew). Uses PlayerGui.MTL_Mission (from StarterGui, reskinnable).
--   meet       the crew waiting at the meet spot by a car with hazard lights (local actors, visible from far off)
--   state      tracker (top right), local props (getaway car, crew, mask box, till), highlight on the target,
--              hold prompt (E / X / press-and-hold the prompt), aim step, alarm + clean-getaway timer
--   bark       a crew line at the bottom of the screen
--   progress   the aim meter when GunService drives the aim step
--   payout     the payout card (counts up), then the offer card (2x Money pass / boost, "Maybe later")
--   MissionController.state() -> last "state" payload    MissionController.Changed: Signal(payload)
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local SoundService = game:GetService("SoundService")
local MarketplaceService = game:GetService("MarketplaceService")

local Net = require(ReplicatedStorage.MTL.Net)
local Signal = require(ReplicatedStorage.MTL.Signal)
local Theme = require(ReplicatedStorage.MTL.UI.Theme)
local Motion = require(ReplicatedStorage.MTL.UI.Motion)
local Format = require(ReplicatedStorage.MTL.Format)
local Story = require(ReplicatedStorage.MTL.Config.Story)
local Missions = require(ReplicatedStorage.MTL.Config.Missions)
local MissionRules = require(ReplicatedStorage.MTL.Rules.MissionRules)
local Build = require(ReplicatedStorage.MTL.UI.Build.Mission)
local UIState = require(script.Parent.UIState)
local Actors = require(script.Parent.Actors)
local Cutscene = require(script.Parent.CutsceneController)

local player = Players.LocalPlayer
local camera = workspace.CurrentCamera
local C = Theme.Colors
local M = Theme.Mission

local MissionController = {}
MissionController.Changed = Signal.new()

local gui: any
local current: any = nil -- last "state" payload
local holding = false
local holdStart = 0
local holdSent = false
local aiming = false
local aimStart: number? = nil
local aimSent = false
local serverProgress = 0
local alarmSound: Sound? = nil
local barkQueue: { { who: string, text: string } } = {}
local barkBusy = false
local payoutMsg: any = nil

local HOLD_KEYS = { [Enum.KeyCode.E] = true, [Enum.KeyCode.ButtonX] = true }
local AIM_INPUTS = { [Enum.UserInputType.MouseButton2] = true }
local AIM_KEYS = { [Enum.KeyCode.ButtonL2] = true }

local function sound(key: string, volume: number?)
	local id = (M.Sounds :: any)[key]
	if type(id) ~= "string" or id == "" or id == "rbxassetid://0" then
		return
	end
	local s = Instance.new("Sound")
	s.SoundId = id
	s.Volume = volume or 0.5
	SoundService:PlayLocalSound(s)
	task.delay(3, function()
		s:Destroy()
	end)
end

local function action(t: string, payload: { [string]: any }?)
	local p = payload or {}
	p.type = t
	Net.get("MissionAction"):FireServer(p)
end

local function root(): BasePart?
	local c = player.Character
	return c and c:FindFirstChild("HumanoidRootPart") :: BasePart?
end

local function getGui()
	local pg = player:WaitForChild("PlayerGui")
	local existing = pg:FindFirstChild("MTL_Mission")
	if existing then
		return existing
	end
	local built = Build.build()
	built.Parent = pg
	return built
end

---------------------------------------------------------------- local scenes (meet + mission props)

type Scene = { folder: Folder, actors: { [string]: { actor: Actors.Actor, cf: CFrame, pose: string } }, props: { [string]: Model } }

local function newScene(name: string): Scene
	local f = Instance.new("Folder")
	f.Name = name
	f.Parent = Actors.folder()
	return { folder = f, actors = {}, props = {} }
end

local function clearScene(s: Scene?)
	if s then
		s.folder:Destroy()
	end
end

local function addActor(s: Scene, name: string, worldPos: Vector3, facePos: Vector3, pose: string)
	if s.actors[name] then
		return
	end
	local a = Actors.spawn(name, s.folder)
	if not a then
		return
	end
	local y = Actors.floor(worldPos)
	local p = Vector3.new(worldPos.X, y, worldPos.Z)
	local f = Vector3.new(facePos.X, y, facePos.Z)
	local cf = if (f - p).Magnitude > 0.1 then CFrame.lookAt(p, f) else CFrame.new(p)
	s.actors[name] = { actor = a, cf = cf, pose = pose }
	Actors.place(a, cf)
end

local function renderScene(s: Scene?)
	if not s then
		return
	end
	local now = os.clock()
	local r = root()
	for _, e in s.actors do
		local state: any = { pose = e.pose, poseT0 = -10 }
		-- glance at the player when they're close
		if r and (r.Position - e.cf.Position).Magnitude < 30 then
			local rel = e.cf:PointToObjectSpace(r.Position)
			state.lookYaw = math.atan2(-rel.X, -rel.Z)
		end
		Actors.render(e.actor, state, now)
	end
end

---------------------------------------------------------------- the meet

local meet: { cframe: CFrame, label: string }? = nil
local meetScene: Scene? = nil

local function buildMeet()
	if not meet or meetScene then
		return
	end
	local cf = meet.cframe
	local L = Missions.Meet.Layout
	local s = newScene("Meet")
	meetScene = s -- claimed before anything yields (rigs may take a moment), so it's built once
	local car = Actors.prop("CrewCar", { parent = s.folder, hazards = true })
	if car then
		local world = cf * L.Car
		local y = Actors.floor(world.Position, { car })
		car:PivotTo(world + Vector3.new(0, y - world.Position.Y, 0))
		s.props.Car = car
	end
	for _, name in { "Dre", "Smoke", "Nina" } do
		local d = (L :: any)[name]
		if meetScene ~= s then
			return -- cleared while building
		end
		addActor(s, name, cf:PointToWorldSpace(d.at), cf:PointToWorldSpace(d.face), d.pose or (if name == "Dre" then "Cross" else "None"))
	end
end

local function clearMeet()
	clearScene(meetScene)
	meetScene = nil
end

---------------------------------------------------------------- mission props

local missionScene: Scene? = nil
local highlight: Highlight? = nil
local tillLight: PointLight? = nil

local function setHighlight(target: Instance?)
	if highlight and highlight.Adornee == target then
		return
	end
	if highlight then
		highlight:Destroy()
		highlight = nil
	end
	if target then
		local h = Instance.new("Highlight")
		h.Name = "MTL_MissionHighlight"
		h.FillTransparency = 1
		h.OutlineColor = C.Gold
		h.OutlineTransparency = 0.15
		h.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
		h.Adornee = target
		h.Parent = Actors.folder()
		highlight = h
	end
end

local function clearMission()
	setHighlight(nil)
	clearScene(missionScene)
	missionScene = nil
	tillLight = nil
end

local syncProps: (any) -> () -- defined below (buildMission refreshes props once the crew rigs arrive)

local function buildMission(state: any)
	if missionScene then
		return
	end
	local s = newScene("Mission")
	missionScene = s -- claimed before anything yields
	local carCf: CFrame = state.car
	local car = Actors.prop("CrewCar", { parent = s.folder, hazards = false })
	if car then
		local y = Actors.floor(carCf.Position, { car })
		car:PivotTo(carCf + Vector3.new(0, y - carCf.Position.Y, 0))
		s.props.Car = car
	end
	-- mask box in the trunk
	local box = Actors.prop("Mask", { parent = s.folder })
	if box then
		local at = carCf * CFrame.new(0, 2.3, 6.2)
		box:PivotTo(at)
		s.props.Mask = box
	end
	-- crew at the car: Nina by the trunk, Dre leaning on the side (Smoke is "in the driver's seat").
	-- Rigs can take a moment to arrive, so they're added in the background.
	task.spawn(function()
		addActor(s, "Nina", carCf:PointToWorldSpace(Vector3.new(3.2, 0, 8.5)), carCf:PointToWorldSpace(Vector3.new(0, 0, 12)), "None")
		addActor(s, "Dre", carCf:PointToWorldSpace(Vector3.new(-4.6, 0, 2)), carCf:PointToWorldSpace(Vector3.new(-8, 0, 8)), "Cross")
		if missionScene == s and current then
			syncProps(current)
		end
	end)
	-- the till at the register: an open cash drawer that glows during the grab
	local reg: Vector3 = state.register
	local y = Actors.floor(reg)
	local till = Instance.new("Model")
	till.Name = "Till"
	local drawer = Actors.part({ Name = "Drawer", Size = Vector3.new(1.6, 0.35, 1.2), Color = Color3.fromRGB(40, 42, 50), CFrame = CFrame.new(reg.X, y + 3.4, reg.Z), Parent = till })
	Actors.part({ Name = "Cash", Size = Vector3.new(1.3, 0.2, 0.9), Color = Color3.fromRGB(90, 170, 100), Material = Enum.Material.Neon, CFrame = CFrame.new(reg.X, y + 3.62, reg.Z), Transparency = 1, Parent = till })
	till.PrimaryPart = drawer
	till.Parent = s.folder
	local light = Instance.new("PointLight")
	light.Color = M.Alarm
	light.Range = 26
	light.Brightness = 0
	light.Parent = drawer
	tillLight = light
	s.props.Till = till
end

syncProps = function(state: any)
	if not missionScene then
		return
	end
	local s = missionScene
	local idx = state.index or 1
	local stepId = state.step and state.step.id
	-- crew climbs in once you're inside the store
	if idx > (MissionRules.stepIndex(Missions.FirstMission, "Enter") or 2) then
		for _, e in s.actors do
			Actors.setHidden(e.actor, true)
		end
	end
	if s.props.Mask then
		s.props.Mask.Parent = if idx > 1 then nil else s.folder
	end
	if s.props.Car then
		Actors.hazards(s.props.Car, state.alarm == true)
	end
	local till = s.props.Till
	if till and till:FindFirstChild("Cash") then
		(till :: any).Cash.Transparency = if stepId == "Grab" then 0.1 else 1
	end
	-- outline the thing to go to
	local target: Instance? = nil
	if stepId == "Mask" then
		target = s.props.Mask or s.props.Car
	elseif stepId == "Threaten" then
		target = workspace:FindFirstChild("MTL_Clerk")
	elseif stepId == "Grab" then
		target = till
	elseif stepId == "Escape" then
		target = s.props.Car
	end
	setHighlight(target)
end

---------------------------------------------------------------- tracker + prompt + meter

local function renderTracker(state: any)
	local tr = gui.Tracker
	tr.Body.MissionName.Text = state.title or ""
	local steps = tr.Body.Steps
	for _, c in steps:GetChildren() do
		if c:IsA("GuiObject") then
			c:Destroy()
		end
	end
	for i, s in state.steps or {} do
		local row = Build.stepRow(s.text, if s.done then "done" elseif s.current then "current" else "todo")
		row.LayoutOrder = i
		row.Parent = steps
	end
	if not tr.Visible then
		tr.Visible = true
		tr.Position = UDim2.new(1, 40, 0, 120)
		Motion.tween(tr, Motion.Spring, { Position = UDim2.new(1, -16, 0, 120) })
	end
end

local function keyGlyph(): string
	if UserInputService.GamepadEnabled and not UserInputService.KeyboardEnabled then
		return "X"
	elseif UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
		return "✋"
	end
	return "E"
end

local function resetHold()
	holding = false
	holdSent = false
	gui.Prompt.Bar.Fill.Size = UDim2.fromScale(0, 1)
end

local function inRange(state: any, extra: number?): boolean
	local r = root()
	local st = state and state.step
	if not r or not st or not st.pos then
		return false
	end
	local d = Vector2.new(r.Position.X - st.pos.X, r.Position.Z - st.pos.Z).Magnitude
	return d <= (st.radius or 6) + (extra or 0)
end

local function beginHold()
	local st = current and current.step
	if not st or st.kind ~= "hold" or not inRange(current) then
		return
	end
	holding = true
	holdStart = os.clock()
	holdSent = false
	action("begin", { step = st.id })
	Motion.tween(gui.Prompt.Pop, Motion.Fast, { Scale = 0.96 })
end

local function endHold()
	if holding then
		resetHold()
		Motion.tween(gui.Prompt.Pop, Motion.Fast, { Scale = 1 })
	end
end

-- built-in aim (only when the Guns piece isn't driving the aim step)
local savedOffset = Vector3.zero
local function setAimCam(on: boolean)
	local char = player.Character
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	if not hum then
		return
	end
	if on then
		savedOffset = hum.CameraOffset
		hum.CameraOffset = Vector3.new(1.75, 0.4, 0)
		hum.AutoRotate = false
		Motion.tween(camera, Motion.Fast, { FieldOfView = 55 })
	else
		hum.CameraOffset = savedOffset
		hum.AutoRotate = true
		Motion.tween(camera, Motion.Fast, { FieldOfView = 70 })
	end
end

local function startAim()
	local st = current and current.step
	if not st or st.kind ~= "aim" or not current.aimFallback or aiming then
		return
	end
	aiming = true
	aimStart = nil
	aimSent = false
	setAimCam(true)
end

local function stopAim()
	if not aiming then
		return
	end
	aiming = false
	aimStart = nil
	setAimCam(false)
	gui.Meter.Bar.Fill.Size = UDim2.fromScale(0, 1)
end

local function facingClerk(): boolean
	local r = root()
	if not r or not current or not current.clerk then
		return false
	end
	local look = r.CFrame.LookVector
	local def = Missions.FirstMission
	return MissionRules.facingOk(r.Position.X, r.Position.Z, look.X, look.Z, current.clerk.X, current.clerk.Z, def.AimDot, def.AimRange)
end

---------------------------------------------------------------- barks

local function runBarks()
	if barkBusy then
		return
	end
	barkBusy = true
	while #barkQueue > 0 do
		local b = table.remove(barkQueue, 1) :: any
		local frame = gui.Bark
		local contact = (Story.Contacts :: any)[b.who]
		frame.Speaker.Text = string.upper(if contact then contact.Name else b.who)
		frame.Speaker.TextColor3 = (Theme.Cutscene.Speakers :: any)[b.who] or M.Accent
		frame.Line.Text = b.text
		frame.Line.MaxVisibleGraphemes = 0
		frame.Visible = true
		local n = utf8.len(b.text) or #b.text
		local t0 = os.clock()
		while os.clock() - t0 < n / 45 do
			frame.Line.MaxVisibleGraphemes = math.floor((os.clock() - t0) * 45)
			task.wait()
		end
		frame.Line.MaxVisibleGraphemes = -1
		task.wait(math.clamp(1.4 + n / 22, 2, 4.5))
		frame.Visible = false
		task.wait(0.15)
	end
	barkBusy = false
end

local function bark(who: string, text: string)
	table.insert(barkQueue, { who = who, text = text })
	task.spawn(runBarks)
end

---------------------------------------------------------------- alarm

local function setAlarm(on: boolean)
	gui.Alarm.Visible = on
	if on and not alarmSound then
		local id = M.Sounds.Alarm
		if id ~= "" and id ~= "rbxassetid://0" then
			local s = Instance.new("Sound")
			s.Name = "MTL_Alarm"
			s.SoundId = id
			s.Looped = true
			s.Volume = 0.25
			s.PlaybackSpeed = 1
			s.Parent = gui
			s:Play()
			alarmSound = s
		end
	elseif not on and alarmSound then
		alarmSound:Destroy()
		alarmSound = nil
	end
end

---------------------------------------------------------------- state

local alarmStartedLocal: number? = nil

local function onState(state: any)
	local first = current == nil or current.mission ~= state.mission
	local stepChanged = current == nil or current.index ~= state.index
	current = state
	if first then
		Cutscene.releaseBlack(0.8)
		clearMeet()
	end
	buildMission(state)
	renderTracker(state)
	syncProps(state)
	if stepChanged then
		resetHold()
		stopAim()
		serverProgress = 0
		gui.Meter.Bar.Fill.Size = UDim2.fromScale(0, 1)
		if not first then
			sound("Step", 0.35)
		end
	end
	if state.alarm then
		if not alarmStartedLocal then
			alarmStartedLocal = os.clock() - (state.alarmFor or 0)
		end
	else
		alarmStartedLocal = nil
	end
	setAlarm(state.alarm == true)
	gui.Prompt.Key.Text = keyGlyph()
	gui.Prompt.Verb.Text = state.step.verb or "Hold"
	gui.Meter.Label.Text = if state.aimFallback
		then (if UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then "HOLD AIM ON THE CLERK" else "HOLD RIGHT-CLICK ON THE CLERK")
		else "AIM AT THE CLERK"
	MissionController.Changed:Fire(state)
end

local function onClear()
	current = nil
	resetHold()
	stopAim()
	setAlarm(false)
	alarmStartedLocal = nil
	clearMission()
	gui.Prompt.Visible = false
	gui.Meter.Visible = false
	gui.AimButton.Visible = false
	if gui.Tracker.Visible then
		local tr = gui.Tracker
		Motion.tween(tr, Motion.Normal, { Position = UDim2.new(1, 40, 0, 120) }).Completed:Wait()
		if not current then
			tr.Visible = false
		end
	end
	MissionController.Changed:Fire(nil)
end

---------------------------------------------------------------- payout + offer

local priceCache: { [string]: string } = {}

local function priceText(item: any, done: (string) -> ())
	if item.owned then
		done("OWNED")
		return
	end
	if not item.id or item.id == 0 then
		done("Coming soon")
		return
	end
	local key = item.kind .. ":" .. item.id
	if priceCache[key] then
		done(priceCache[key])
		return
	end
	task.spawn(function()
		local ok, info = pcall(function()
			return MarketplaceService:GetProductInfo(item.id, if item.kind == "pass" then Enum.InfoType.GamePass else Enum.InfoType.Product)
		end)
		local text = if ok and info and info.PriceInRobux then ("R$ " .. tostring(info.PriceInRobux)) else "Buy"
		priceCache[key] = text
		done(text)
	end)
end

local function hideFull(frame: Frame)
	local card = frame:FindFirstChild("Card") :: any
	if card and card:FindFirstChild("Pop") then
		Motion.tween(card.Pop, Motion.Fast, { Scale = 0.9 })
	end
	task.delay(0.12, function()
		frame.Visible = false
	end)
end

local function showFull(frame: Frame)
	frame.Visible = true
	local card = frame:FindFirstChild("Card") :: any
	if card and card:FindFirstChild("Pop") then
		card.Pop.Scale = 0.85
		Motion.tween(card.Pop, Motion.Spring, { Scale = 1 })
	end
end

local function renderOffer(msg: any)
	local card = gui.Offer.Card
	local take = (msg.take or 0) + (msg.bonus or 0)
	card.Sub.Text = string.format("This job paid %s. With 2x Money it pays %s, and so does every job after it.", Format.cash(take), Format.cash(msg.doubled or take * 2))
	local tiles = card.Tiles
	for _, c in tiles:GetChildren() do
		if c:IsA("GuiObject") then
			c:Destroy()
		end
	end
	for i, item in msg.offer or {} do
		local tile = Build.offerTile(item.title, item.sub, if item.kind == "pass" then M.Icons.Pass else M.Icons.Boost)
		tile.LayoutOrder = i
		tile.Parent = tiles
		local buy = tile.Buy
		buy.Text = "..."
		priceText(item, function(text)
			if buy.Parent then
				buy.Text = text
			end
		end)
		if item.owned then
			buy.AutoButtonColor = false
			buy.BackgroundTransparency = 0.6
		else
			buy.Activated:Connect(function()
				action("buy", { item = item.item })
			end)
		end
	end
end

local function closeOffer()
	hideFull(gui.Offer)
	UIState.pop("Payout")
	action("closeOffer")
	payoutMsg = nil
end

local function showOffer(msg: any)
	local anyToBuy = false
	for _, it in msg.offer or {} do
		if not it.owned then
			anyToBuy = true
		end
	end
	if not anyToBuy then
		closeOffer()
		return
	end
	renderOffer(msg)
	showFull(gui.Offer)
end

local function showPayout(msg: any)
	payoutMsg = msg
	if gui.Offer.Visible then
		renderOffer(msg) -- a pass was bought: refresh the tiles (OWNED)
		return
	end
	Cutscene.releaseBlack(0.9)
	UIState.push("Payout", { hidePhone = true, hideWaypoints = true, lockControls = true })
	local card = gui.Payout.Card
	card.Title.Text = msg.title or ""
	local rows = card.Rows
	for _, c in rows:GetChildren() do
		if c:IsA("GuiObject") then
			c:Destroy()
		end
	end
	local order = 0
	local function row(label: string, value: string, color: Color3?)
		order += 1
		local r = Build.payoutRow(label, value, color)
		r.LayoutOrder = order
		r.Parent = rows
	end
	row("Register take", Format.cash(msg.take or 0))
	if msg.clean then
		row("Clean getaway", "+" .. Format.cash(msg.bonus or 0), C.Gold)
	elseif msg.escape then
		row("Getaway time", MissionRules.clock(msg.escape) .. "  (under " .. MissionRules.clock(msg.cleanSeconds or 30) .. " = bonus)")
	end
	if (msg.mult or 1) > 1 then
		row("2x Money", "x" .. tostring(msg.mult), C.Accent)
	end
	card.XP.Text = if (msg.xp or 0) > 0 then ("+" .. tostring(msg.xp) .. " XP") else ""
	card.Note.Text = if msg.debug then "(Studio debug: reached by debugSet, nothing was paid)" else "Your crew's waiting on you. Spend it well."
	local total = if msg.debug then (msg.take or 0) + (msg.bonus or 0) else (msg.paid or 0)
	card.Total.Value.Text = "$0"
	showFull(gui.Payout)
	task.delay(0.35, function()
		Motion.count(card.Total.Value, 0, total, 1.4, Format.cash)
		for i = 1, 8 do
			task.delay(i * 0.16, sound, "Cash", 0.25)
		end
		task.delay(1.45, sound, "Done", 0.5)
	end)
end

---------------------------------------------------------------- per frame

local function frame()
	renderScene(meetScene)
	renderScene(missionScene)
	-- meet props appear once you're within range (the area is probably streamed in by then)
	if meet and not meetScene then
		local r = root()
		if r and (r.Position - meet.cframe.Position).Magnitude <= Missions.Meet.ShowPropsWithin then
			task.spawn(buildMeet)
		end
	end
	local state = current
	if not state then
		return
	end
	local st = state.step
	local hidden = UIState.get().hideHUD == true
	-- hold prompt
	local showPrompt = st.kind == "hold" and inRange(state) and not hidden
	gui.Prompt.Visible = showPrompt
	if holding then
		if not inRange(state, 3) then
			endHold()
		else
			local a = math.clamp((os.clock() - holdStart) / (st.seconds or 1), 0, 1)
			gui.Prompt.Bar.Fill.Size = UDim2.fromScale(a, 1)
			if a >= 1 and not holdSent then
				holdSent = true
				action("step", { step = st.id })
			end
		end
	end
	-- aim step
	local isAim = st.kind == "aim"
	local near = isAim and inRange(state, 14)
	gui.Meter.Visible = near and not hidden
	gui.AimButton.Visible = near and state.aimFallback and UserInputService.TouchEnabled and not hidden
	if isAim and not state.aimFallback then
		gui.Meter.Bar.Fill.Size = UDim2.fromScale(serverProgress, 1)
	elseif aiming then
		-- turn toward the clerk (light aim assist), fill while facing them
		local r = root()
		if r and state.clerk then
			local target = Vector3.new(state.clerk.X, r.Position.Y, state.clerk.Z)
			local camLook = camera.CFrame.LookVector
			local want = Vector3.new(camLook.X, 0, camLook.Z)
			local toClerk = (target - r.Position)
			if toClerk.Magnitude > 0.5 and want.Magnitude > 0.01 and want.Unit:Dot(toClerk.Unit) > 0.75 then
				want = toClerk -- snap to the clerk when roughly aiming at them
			end
			if want.Magnitude > 0.01 then
				r.CFrame = r.CFrame:Lerp(CFrame.lookAt(r.Position, r.Position + want), 0.25)
			end
		end
		if facingClerk() then
			if not aimStart then
				aimStart = os.clock()
				action("begin", { step = st.id })
			end
			local a = math.clamp((os.clock() - aimStart) / (st.seconds or 2), 0, 1)
			gui.Meter.Bar.Fill.Size = UDim2.fromScale(a, 1)
			if a >= 1 and not aimSent then
				aimSent = true
				action("step", { step = st.id })
			end
		else
			aimStart = nil
			aimSent = false
			gui.Meter.Bar.Fill.Size = UDim2.fromScale(0, 1)
		end
	end
	-- alarm pulse + clean-getaway timer
	if state.alarm and alarmStartedLocal then
		local pulse = 0.5 + 0.5 * math.sin(os.clock() * 7)
		for _, e in gui.Alarm:GetChildren() do
			if e:IsA("Frame") then
				e.BackgroundTransparency = 0.25 + 0.6 * (1 - pulse)
			end
		end
		if tillLight then
			tillLight.Brightness = 3 * pulse
		end
		local left = (state.cleanSeconds or 0) - (os.clock() - alarmStartedLocal)
		local timer = gui.Tracker.Body.Timer
		timer.Visible = state.cleanSeconds ~= nil
		if left > 0 then
			timer.Text = "Clean getaway  " .. MissionRules.clock(left)
			timer.TextColor3 = C.Gold
		else
			timer.Text = "Just get to the car!"
			timer.TextColor3 = C.TextDim
		end
	else
		gui.Tracker.Body.Timer.Visible = false
	end
end

---------------------------------------------------------------- init

function MissionController.state(): any
	return current
end

function MissionController.init()
	gui = getGui()

	Net.get("MissionState").OnClientEvent:Connect(function(msg)
		if type(msg) ~= "table" then
			return
		end
		local kind = msg.type
		if kind == "state" then
			onState(msg)
		elseif kind == "clear" then
			task.spawn(onClear)
		elseif kind == "bark" and type(msg.who) == "string" and type(msg.text) == "string" then
			bark(msg.who, msg.text)
		elseif kind == "progress" and type(msg.value) == "number" then
			serverProgress = math.clamp(msg.value, 0, 1)
		elseif kind == "meet" and typeof(msg.cframe) == "CFrame" then
			meet = { cframe = msg.cframe, label = msg.label or "" }
			clearMeet()
		elseif kind == "meetClear" then
			meet = nil
			clearMeet()
		elseif kind == "payout" then
			showPayout(msg)
		end
	end)

	-- the cutscene builds its own crew at the same spots: hide ours while it plays
	Cutscene.Started:Connect(function()
		if meetScene then
			meetScene.folder.Parent = nil
		end
		if missionScene then
			missionScene.folder.Parent = nil
		end
		endHold()
		stopAim()
	end)
	Cutscene.Finished:Connect(function()
		if meetScene then
			meetScene.folder.Parent = Actors.folder()
		end
		if missionScene then
			missionScene.folder.Parent = Actors.folder()
		end
	end)

	gui.Payout.Card.Continue.Activated:Connect(function()
		hideFull(gui.Payout)
		if payoutMsg then
			task.delay(0.15, showOffer, payoutMsg)
		else
			closeOffer()
		end
	end)
	gui.Offer.Card.Later.Activated:Connect(closeOffer)

	-- hold: keys, or press-and-hold the prompt (mouse/touch)
	UserInputService.InputBegan:Connect(function(input, processed)
		if HOLD_KEYS[input.KeyCode] and not processed then
			beginHold()
		elseif (AIM_INPUTS[input.UserInputType] or AIM_KEYS[input.KeyCode]) then
			startAim()
		end
	end)
	UserInputService.InputEnded:Connect(function(input)
		if HOLD_KEYS[input.KeyCode] then
			endHold()
		elseif AIM_INPUTS[input.UserInputType] or AIM_KEYS[input.KeyCode] then
			stopAim()
		end
	end)
	gui.Prompt.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			beginHold()
		end
	end)
	gui.Prompt.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			endHold()
		end
	end)
	gui.AimButton.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
			startAim()
		end
	end)
	gui.AimButton.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
			stopAim()
		end
	end)

	UIState.Changed:Connect(function(state)
		gui.Enabled = not (state.hideHUD and not UIState.has("Payout"))
	end)

	player.CharacterAdded:Connect(function()
		resetHold()
		aiming = false
	end)

	RunService.RenderStepped:Connect(function()
		local ok, err = pcall(frame)
		if not ok then
			warn("[MTL Mission] frame error:", err)
		end
	end)
end

return MissionController
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "MoodFX", "ModuleScript", [======[--!strict
-- Small screen filters that sit on top of the day-night look (LightingController owns the main grade, bloom,
-- sun rays and atmosphere; this only adds mood and never touches those):
--   * a warm/cool split grade (warm by day, cool blue-violet at night) on its own ColorCorrection
--   * soft depth of field that blurs the far city so the street reads closer and bigger
--   * a vignette: four soft dark edges behind the HUD
--   * floating dust motes around the camera that catch the sun and the street lamps
-- It follows LightingController.clock(), and steps aside while a cutscene runs (cutscenes bring their own DOF).
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local Lighting = game:GetService("Lighting")

local Cutscene = require(script.Parent.CutsceneController)

local MoodFX = {}

local UPDATE_EVERY = 0.15

local Day = {
	Tint = Color3.fromRGB(255, 251, 244),
	Contrast = 0.02,
	Saturation = 0.015,
	FarBlur = 0,
	Vignette = 0.9, -- transparency at the very edge (1 = none)
	Dust = 6,
	Lift = 0, -- extra brightness
}
local Night = {
	Tint = Color3.fromRGB(248, 248, 255),
	Contrast = 0,
	Saturation = -0.01,
	FarBlur = 0,
	Vignette = 0.86,
	Dust = 3,
	Lift = 0.03, -- buildings stay readable at night
}

local function smooth(a: number, b: number, x: number): number
	local t = math.clamp((x - a) / (b - a), 0, 1)
	return t * t * (3 - 2 * t)
end

-- 0 by day, 1 at night, smooth through dusk and dawn
local function nightness(clock: number): number
	local dusk = smooth(17.6, 19.8, clock)
	local dawn = 1 - smooth(5.4, 7.2, clock)
	return math.max(dusk, dawn)
end

local function vignette(parent: Instance): { Frame }
	local gui = Instance.new("ScreenGui")
	gui.Name = "MTL_Vignette"
	gui.IgnoreGuiInset = true
	gui.ResetOnSpawn = false
	gui.DisplayOrder = -10 -- under every HUD
	gui.Parent = parent
	local edges = {}
	local specs = {
		{ pos = UDim2.fromScale(0, 0), size = UDim2.fromScale(1, 0.22), rot = 90 }, -- top
		{ pos = UDim2.fromScale(0, 0.78), size = UDim2.fromScale(1, 0.22), rot = -90 }, -- bottom
		{ pos = UDim2.fromScale(0, 0), size = UDim2.fromScale(0.16, 1), rot = 0 }, -- left
		{ pos = UDim2.fromScale(0.84, 0), size = UDim2.fromScale(0.16, 1), rot = 180 }, -- right
	}
	for _, s in specs do
		local f = Instance.new("Frame")
		f.BorderSizePixel = 0
		f.BackgroundColor3 = Color3.fromRGB(8, 6, 14)
		f.Position = s.pos
		f.Size = s.size
		f.Parent = gui
		local g = Instance.new("UIGradient")
		g.Rotation = s.rot
		g.Parent = f
		table.insert(edges, f)
	end
	return edges
end

local function setVignette(edges: { Frame }, edge: number)
	for _, f in edges do
		local g = f:FindFirstChildOfClass("UIGradient") :: UIGradient
		g.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, edge),
			NumberSequenceKeypoint.new(0.55, math.min(1, edge + 0.3)),
			NumberSequenceKeypoint.new(1, 1),
		})
	end
end

local function dust(): (BasePart, ParticleEmitter)
	local box = Instance.new("Part")
	box.Name = "MTL_DustBox"
	box.Anchored = true
	box.CanCollide = false
	box.CanQuery = false
	box.CanTouch = false
	box.CastShadow = false
	box.Transparency = 1
	box.Size = Vector3.new(70, 26, 70)
	box.Parent = workspace.CurrentCamera
	local e = Instance.new("ParticleEmitter")
	e.Name = "Motes"
	e.Shape = Enum.ParticleEmitterShape.Box
	e.ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume
	e.Texture = "rbxasset://textures/particles/sparkles_main.dds"
	e.Color = ColorSequence.new(Color3.fromRGB(255, 244, 222))
	e.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.06), NumberSequenceKeypoint.new(1, 0.1) })
	e.Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 1),
		NumberSequenceKeypoint.new(0.3, 0.35),
		NumberSequenceKeypoint.new(0.7, 0.45),
		NumberSequenceKeypoint.new(1, 1),
	})
	e.Lifetime = NumberRange.new(6, 10)
	e.Speed = NumberRange.new(0.1, 0.5)
	e.SpreadAngle = Vector2.new(180, 180)
	e.Acceleration = Vector3.new(0.15, -0.05, 0.1)
	e.Drag = 0.4
	e.RotSpeed = NumberRange.new(-20, 20)
	e.LightEmission = 0.4
	e.LightInfluence = 1 -- only shows where light hits it (sun shafts, lamp pools)
	e.Rate = Day.Dust
	e.Parent = box
	return box, e
end

function MoodFX.init(lighting: { clock: () -> number })
	local player = Players.LocalPlayer

	local grade = Lighting:FindFirstChild("MTL_MoodGrade") :: ColorCorrectionEffect?
	if not grade then
		local g = Instance.new("ColorCorrectionEffect")
		g.Name = "MTL_MoodGrade"
		g.Parent = Lighting
		grade = g
	end
	local dof = Lighting:FindFirstChild("MTL_MoodDOF") :: DepthOfFieldEffect?
	if not dof then
		local d = Instance.new("DepthOfFieldEffect")
		d.Name = "MTL_MoodDOF"
		d.Parent = Lighting
		dof = d
	end
	local g = grade :: ColorCorrectionEffect
	local d = dof :: DepthOfFieldEffect
	d.FocusDistance = 0
	d.InFocusRadius = 260 -- nearby blocks stay sharp; only the far skyline goes soft
	d.NearIntensity = 0

	-- cars: shinier paint, and head/tail lights at night
	require(script.Parent.CarGlow).init(function()
		return nightness(lighting.clock())
	end)

	local edges = vignette(player:WaitForChild("PlayerGui"))
	local box, motes = dust()

	local timer = 0
	RunService.RenderStepped:Connect(function(dt)
		local cam = workspace.CurrentCamera
		box.CFrame = CFrame.new(cam.CFrame.Position)
		timer += dt
		if timer < UPDATE_EVERY then
			return
		end
		timer = 0
		local n = nightness(lighting.clock())
		g.TintColor = Day.Tint:Lerp(Night.Tint, n)
		g.Contrast = Day.Contrast + (Night.Contrast - Day.Contrast) * n
		g.Saturation = Day.Saturation + (Night.Saturation - Day.Saturation) * n
		g.Brightness = Day.Lift + (Night.Lift - Day.Lift) * n
		local cut = Cutscene.isPlaying()
		d.Enabled = not cut
		d.FarIntensity = Day.FarBlur + (Night.FarBlur - Day.FarBlur) * n
		setVignette(edges, Day.Vignette + (Night.Vignette - Day.Vignette) * n)
		motes.Rate = if cut then 0 else Day.Dust + (Night.Dust - Day.Dust) * n
	end)
end

return MoodFX
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "MovementController", "ModuleScript", [======[--!strict
-- How moving feels: sprint, eased speed changes, the sprint FOV kick, a small camera bob / strafe roll / landing
-- dip, the character leaning into sprints and turns, and a short jump cooldown. Numbers: Config/Movement.lua
-- (why: Research/Movement and Game Feel.md).
--
-- The only client script that writes Humanoid.WalkSpeed. Speed = base x sprint x every modifier, eased:
--   base   = Config WalkSpeed, or whatever someone else last wrote (the server's job carry writes 12, a map script
--            may write 0): a write we didn't make becomes the new base. When the carry ends it goes back to walk.
--   sprint = PC hold LeftShift · gamepad click L3 (toggle, switches off when you stop) · touch RUN button (same)
--            Never while carrying a job prop (char attribute MTL_WalkSpeedBeforeCarry), aiming, phone open,
--            or UIState lockControls (cutscenes, minigames, payout, fades).
-- In a cutscene (player attribute MTL_Cutscene set, or the camera isn't Custom) there is no sway, roll, dip, FOV
-- kick or lean: the offset comes off and the lean snaps back the moment it starts.
-- Camera effects are a transient offset: last frame's is taken off before the camera module runs
-- (RenderPriority.Camera - 1) and the new one goes on after the gun's recoil step (Camera + 2), so nothing builds
-- up. The FOV kick is additive: if someone else set FieldOfView (gun aim, mission zoom, cutscene, phone camera),
-- their value is the new base and the kick sits on top of it.
--
-- API (Master Plan §3.6)
--   MovementController.setModifier(name, mult) / clearModifier(name)   e.g. setModifier("Aim", 0.6)
--   MovementController.isSprinting() -> bool      MovementController.Changed: Signal(sprinting)
local ContextActionService = game:GetService("ContextActionService")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local Workspace = game:GetService("Workspace")

local Signal = require(ReplicatedStorage.MTL.Signal)
local Movement = require(ReplicatedStorage.MTL.Config.Movement)
local GunRules = require(ReplicatedStorage.MTL.Rules.GunRules)
local UIState = require(script.Parent.UIState)
local ClientData = require(script.Parent.ClientData)

local M = Movement

local MovementController = {}
MovementController.Changed = Signal.new()

local player = Players.LocalPlayer
local SPRINT_ACTION = "MTL_Sprint"
local CARRY_ATTR = "MTL_WalkSpeedBeforeCarry"

-- character
local hum: Humanoid? = nil
local root: BasePart? = nil
local joint: Motor6D? = nil
local jointC0 = CFrame.identity
local pivot = Vector3.zero
local charConns: { RBXScriptConnection } = {}
-- speed
local base = M.WalkSpeed
local current = M.WalkSpeed
local lastWritten: number? = nil
local wasCarrying = false
local modifiers: { [string]: number } = {}
-- sprint input
local held = false
local toggled = false
local idleFor = 0
local sprinting = false
local sprintAmt = 0 -- 0..1, eased: drives bob / lean
-- camera
local applied = CFrame.identity
local fovApplied = 0
local lastFov: number? = nil
local ownFov: { [number]: number } = {} -- FOVs we wrote with a kick in them -> that kick (a later restore of one)
local ownFovCount = 0
local bobPhase = 0
local roll = 0
local land = { x = 0, v = 0 }
local maxFall = 0
-- lean
local leanFwd = { x = 0, v = 0 }
local leanSide = { x = 0, v = 0 }
local lastYaw: number? = nil
local leanWritten = false
-- jump
local jumpGen = 0

local Phone: any = nil

local function reducedMotion(): boolean
	local d = ClientData.get()
	return d ~= nil and d.Settings ~= nil and d.Settings.ReducedMotion == true
end

local function phoneOpen(): boolean
	return Phone and Phone.isOpen and Phone.isOpen() or false
end

local function inCutscene(): boolean
	return player:GetAttribute("MTL_Cutscene") ~= nil
end

local function carrying(): boolean
	local c = player.Character
	return c ~= nil and c:GetAttribute(CARRY_ATTR) ~= nil
end

local function firstPerson(cam: Camera): boolean
	local c = player.Character
	local head = c and c:FindFirstChild("Head") :: BasePart?
	return head ~= nil and (cam.CFrame.Position - head.Position).Magnitude < 1.6
end

-- exponential approach: ~95% of the way in `seconds`
local function approach(from: number, to: number, seconds: number, dt: number): number
	if seconds <= 0 then
		return to
	end
	return from + (to - from) * (1 - math.exp(-3 * dt / seconds))
end

-- spring toward a target (GunRules.springStep springs toward 0)
local function springTo(s: any, target: number, k: number, z: number, dt: number)
	local tmp = { x = s.x - target, v = s.v }
	GunRules.springStep(tmp, k, z, dt)
	s.x, s.v = tmp.x + target, tmp.v
end

local function multiplier(): number
	local m = 1
	for _, v in modifiers do
		m *= v
	end
	return m
end

local function canSprint(h: Humanoid): boolean
	if h.Health <= 0 or h.Sit or modifiers.Aim ~= nil or carrying() or phoneOpen() then
		return false
	end
	if UIState.get().lockControls or inCutscene() or UserInputService:GetFocusedTextBox() then
		return false
	end
	local st = h:GetState()
	return st ~= Enum.HumanoidStateType.Swimming and st ~= Enum.HumanoidStateType.Climbing and st ~= Enum.HumanoidStateType.Seated
end

local function touchButton(): ImageButton?
	local b = ContextActionService:GetButton(SPRINT_ACTION)
	return if b and b:IsA("ImageButton") then b else nil
end

local function setSprinting(on: boolean)
	if on == sprinting then
		return
	end
	sprinting = on
	local b = touchButton()
	if b then
		b.ImageColor3 = if on then Color3.fromRGB(255, 214, 110) else Color3.new(1, 1, 1)
	end
	MovementController.Changed:Fire(on)
end

---------------------------------------------------------------- speed

local function speedStep(h: Humanoid, dt: number)
	local seen = h.WalkSpeed
	local carry = carrying()
	if lastWritten == nil or math.abs(seen - lastWritten) > 0.01 then
		if lastWritten ~= nil then
			-- someone else wrote it. The carry's restore puts back a speed that may have had our sprint in it.
			base = if not carry and wasCarrying then M.WalkSpeed else seen
		end
		current = seen
	end
	wasCarrying = carry

	local moving = h.MoveDirection.Magnitude > 0.1
	if toggled then
		idleFor = if moving then 0 else idleFor + dt
		if idleFor > M.ToggleOffIdleSeconds then
			toggled = false
		end
	end
	setSprinting((held or toggled) and moving and canSprint(h))

	local target = base * multiplier() * (if sprinting then M.SprintSpeed / M.WalkSpeed else 1)
	current = approach(current, target, if target > current then M.EaseUpSeconds else M.EaseDownSeconds, dt)
	if math.abs(target - current) < 0.05 then
		current = target
	end
	if math.abs(h.WalkSpeed - current) > 0.001 then
		h.WalkSpeed = current
	end
	lastWritten = h.WalkSpeed
end

---------------------------------------------------------------- lean

local function leanStep(h: Humanoid, r: BasePart, speed: number, dt: number)
	local j = joint
	if not j or not j.Parent then
		return
	end
	local look = r.CFrame.LookVector
	local yaw = math.atan2(-look.X, -look.Z)
	local yawRate = 0
	if lastYaw and dt > 0 then
		local d = yaw - lastYaw
		d = (d + math.pi) % (2 * math.pi) - math.pi
		yawRate = d / dt
	end
	lastYaw = yaw
	if inCutscene() or Workspace.CurrentCamera.CameraType ~= Enum.CameraType.Custom then
		-- a cutscene may pose / place the character: hand the joint straight back
		leanFwd.x, leanFwd.v, leanSide.x, leanSide.v = 0, 0, 0, 0
		if leanWritten then
			j.C0 = jointC0
			leanWritten = false
		end
		return
	end
	local st = h:GetState()
	local ok = h.Health > 0
		and not h.Sit
		and modifiers.Aim == nil
		and not UIState.get().lockControls
		and st ~= Enum.HumanoidStateType.Climbing
		and st ~= Enum.HumanoidStateType.Swimming
	local fwd = if ok then M.SprintLean * sprintAmt else 0
	local side = if ok then M.TurnLean * math.clamp(yawRate / M.TurnLeanRate, -1, 1) * math.clamp(speed / M.WalkSpeed, 0, 1) else 0
	springTo(leanFwd, fwd, M.LeanStiffness, M.LeanDamping, dt)
	springTo(leanSide, side, M.LeanStiffness, M.LeanDamping, dt)
	if math.abs(leanFwd.x) < 0.01 and math.abs(leanSide.x) < 0.01 and fwd == 0 and side == 0 then
		if leanWritten then
			j.C0 = jointC0
			leanWritten = false
		end
		return
	end
	-- rotate about the feet, in the root part's space: forward = tip the top toward -Z, side = toward the turn
	local rot = CFrame.Angles(math.rad(-leanFwd.x), 0, math.rad(leanSide.x))
	j.C0 = CFrame.new(pivot) * rot * CFrame.new(-pivot) * jointC0
	leanWritten = true
end

---------------------------------------------------------------- camera

local function camActive(cam: Camera): boolean
	if cam.CameraType ~= Enum.CameraType.Custom or inCutscene() then
		return false
	end
	local ui = UIState.get()
	return not (ui.lockCamera or ui.lockControls)
end

local function rememberFov(value: number, kick: number)
	if ownFovCount > 256 then
		table.clear(ownFov)
		ownFovCount = 0
	end
	local key = math.floor(value * 100 + 0.5)
	if ownFov[key] == nil then
		ownFovCount += 1
	end
	ownFov[key] = kick
end

local function fovStep(cam: Camera, active: boolean, dt: number)
	if not active then
		-- a cutscene / scripted camera owns the FOV now; start fresh when we're back
		fovApplied = 0
		lastFov = nil
		return
	end
	local cur = cam.FieldOfView
	local baseFov
	if lastFov and math.abs(cur - lastFov) < 0.001 then
		baseFov = cur - fovApplied
	else
		-- someone else set it. A restore of a value we wrote (saved mid-sprint) still has our kick in it.
		baseFov = cur - (ownFov[math.floor(cur * 100 + 0.5)] or 0)
	end
	local target = if sprinting and not reducedMotion() then M.SprintFov else 0
	fovApplied = approach(fovApplied, target, M.FovEaseSeconds, dt)
	if math.abs(target - fovApplied) < 0.01 then
		fovApplied = target
	end
	local out = math.clamp(baseFov + fovApplied, 1, 120)
	if math.abs(out - cur) > 0.001 then
		cam.FieldOfView = out
	end
	lastFov = cam.FieldOfView
	if fovApplied > 0.3 then
		rememberFov(cam.FieldOfView, fovApplied)
	end
end

-- Camera - 1: take last frame's offset off before the camera module reads the camera
local function preCamera(dt: number)
	local cam = Workspace.CurrentCamera
	if applied ~= CFrame.identity then
		if cam.CameraType == Enum.CameraType.Custom and not inCutscene() then
			cam.CFrame = cam.CFrame * applied:Inverse()
		end
		applied = CFrame.identity
	end

	local h, r = hum, root
	if not h or not r or not h.Parent or not r.Parent then
		return
	end
	speedStep(h, dt)

	local v = r.AssemblyLinearVelocity
	local speed = Vector3.new(v.X, 0, v.Z).Magnitude
	local grounded = h.FloorMaterial ~= Enum.Material.Air
	sprintAmt = approach(sprintAmt, if sprinting and grounded and speed > 4 then 1 else 0, 0.3, dt)
	if v.Y < -maxFall then
		maxFall = -v.Y
	end
	leanStep(h, r, speed, dt)
end

-- Camera + 2: after the camera module (Camera) and the gun's recoil (Camera + 1)
local function postCamera(dt: number)
	local cam = Workspace.CurrentCamera
	local active = camActive(cam)
	fovStep(cam, active, dt)

	springTo(land, 0, 140, 0.7, dt)
	local r = root
	local v = if r and r.Parent then r.AssemblyLinearVelocity else Vector3.zero
	local flat = Vector3.new(v.X, 0, v.Z)
	bobPhase = (bobPhase + flat.Magnitude * M.BobStepsPerStud * dt) % 2
	local lateral = math.clamp(flat:Dot(cam.CFrame.RightVector) / M.SprintSpeed, -1, 1)
	roll = approach(roll, -lateral * M.StrafeRoll, 0.25, dt)

	if not active or not r or reducedMotion() or firstPerson(cam) then
		return
	end
	local pitch = M.BobPitch * sprintAmt * math.sin(2 * math.pi * bobPhase) - M.LandDipMax * land.x
	local rollNow = roll + M.BobRoll * sprintAmt * math.sin(math.pi * bobPhase)
	local offset = CFrame.new(0, -M.LandDipDrop * land.x, 0) * CFrame.Angles(math.rad(pitch), 0, math.rad(rollNow))
	cam.CFrame = cam.CFrame * offset
	applied = offset
end

---------------------------------------------------------------- character

local function onLanded()
	local fall = maxFall
	maxFall = 0
	local share = math.clamp((fall - M.LandDipMinFallSpeed) / (M.LandDipFallSpeed - M.LandDipMinFallSpeed), 0, 1)
	if share > 0 then
		land.v += GunRules.kickVelocity(share, 140)
	end
	-- jump cooldown: no hop for a moment after touching down
	local h = hum
	if h and M.JumpCooldown > 0 then
		jumpGen += 1
		local gen = jumpGen
		h:SetStateEnabled(Enum.HumanoidStateType.Jumping, false)
		task.delay(M.JumpCooldown, function()
			if gen == jumpGen and h.Parent then
				h:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
			end
		end)
	end
end

local function onCharacter(c: Model)
	for _, conn in charConns do
		conn:Disconnect()
	end
	table.clear(charConns)
	local h = c:WaitForChild("Humanoid", 10) :: Humanoid?
	local r = c:WaitForChild("HumanoidRootPart", 10) :: BasePart?
	if not h or not r or player.Character ~= c then
		return
	end
	hum, root = h, r
	base, current, lastWritten, wasCarrying = M.WalkSpeed, h.WalkSpeed, nil, false
	leanFwd.x, leanFwd.v, leanSide.x, leanSide.v, lastYaw, leanWritten = 0, 0, 0, 0, nil, false
	land.x, land.v, maxFall, sprintAmt = 0, 0, 0, 0
	toggled = false
	setSprinting(false)

	-- the lean joint: R15 LowerTorso.Root, R6 HumanoidRootPart.RootJoint. Pivot = the feet, in root space.
	local lt = c:WaitForChild("LowerTorso", 2)
	local j = (lt and lt:FindFirstChild("Root")) or r:FindFirstChild("RootJoint")
	joint = if j and j:IsA("Motor6D") then j else nil
	if joint then
		jointC0 = joint.C0
		local legs = if h.RigType == Enum.HumanoidRigType.R6 then 2 else h.HipHeight
		pivot = Vector3.new(0, -(r.Size.Y / 2 + legs), 0)
	end

	table.insert(charConns, h.StateChanged:Connect(function(_, new)
		if new == Enum.HumanoidStateType.Landed then
			onLanded()
		end
	end))
end

---------------------------------------------------------------- input

local function onSprintAction(_: string, state: Enum.UserInputState, input: InputObject): Enum.ContextActionResult
	if input.UserInputType == Enum.UserInputType.Keyboard then
		held = state == Enum.UserInputState.Begin
		return Enum.ContextActionResult.Pass
	end
	-- gamepad L3 / the touch button: toggle
	if state == Enum.UserInputState.Begin then
		toggled = not toggled
		idleFor = 0
	end
	return Enum.ContextActionResult.Sink
end

local function bindInput()
	local keys: { any } = {}
	for _, k in M.SprintKeys do
		table.insert(keys, k)
	end
	for _, k in M.SprintToggleKeys do
		table.insert(keys, k)
	end
	ContextActionService:BindAction(SPRINT_ACTION, onSprintAction, true, table.unpack(keys))
	ContextActionService:SetTitle(SPRINT_ACTION, M.TouchButton.title)
	ContextActionService:SetPosition(SPRINT_ACTION, M.TouchButton.position)
	UserInputService.WindowFocusReleased:Connect(function()
		held = false
	end)
	-- the touch button hides with the HUD (cutscenes, the phone camera)
	UIState.Changed:Connect(function(s)
		local b = touchButton()
		if b then
			b.Visible = not s.hideHUD
		end
	end)
end

---------------------------------------------------------------- API

function MovementController.setModifier(name: string, mult: number)
	modifiers[name] = mult
end

function MovementController.clearModifier(name: string)
	modifiers[name] = nil
end

function MovementController.isSprinting(): boolean
	return sprinting
end

function MovementController.init()
	bindInput()
	player.CharacterAdded:Connect(onCharacter)
	if player.Character then
		task.spawn(onCharacter, player.Character)
	end
	RunService:BindToRenderStep("MTL_MovePre", Enum.RenderPriority.Camera.Value - 1, preCamera)
	RunService:BindToRenderStep("MTL_MovePost", Enum.RenderPriority.Camera.Value + 2, postCamera)
	-- the phone boots after this controller; pick it up once it has loaded
	task.defer(function()
		local m = script.Parent:WaitForChild("PhoneController", 30)
		if m then
			local ok, p = pcall(require, m)
			Phone = if ok then p else nil
		end
	end)
end

return MovementController
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "PhoneController", "ModuleScript", [======[--!strict
-- The phone (Master Plan §3.6, §3.7). Bottom right, top ~15% peeking out and tilted. Hover lifts it, click/tap or
-- M (DPadUp on a gamepad) raises it with a spring; M, clicking the world, or dragging the top/bottom bar down lowers
-- it. When something arrives while it's down, it peeks higher with a banner ("phone moved = something for me").
-- Incoming calls raise it by themselves. Cutscenes hide it (UIState hidePhone).
--
-- API:
--   Phone.registerApp(appId, { title?, mount = fn(frame, ctx), unmount = fn(ctx)?, onEvent = fn(payload, ctx)? })
--   Phone.open(appId?, args?)  Phone.close()  Phone.home()  Phone.isOpen()  Phone.currentApp()
--   Phone.notify({ app?, title, text?, args? })        banner (tapping it opens `app` with `args`)
--   Phone.incomingCall({ caller, glyph?, onAnswer, onDecline })   local ring (server calls use the same screen)
--   Phone.fakeCall(name, message)                     "Calling..." -> "No answer" (contacts without a script)
--   Phone.Opened / Phone.Closed / Phone.ServerEvent (every PhoneEvent payload) : Signals
-- Apps live in StarterPlayerScripts/MTL/Apps (one ModuleScript each, returning { id = "...", mount = ..., ... });
-- they're loaded automatically. ctx (given to mount) is documented at makeContext below.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local UserInputService = game:GetService("UserInputService")
local RunService = game:GetService("RunService")
local SoundService = game:GetService("SoundService")
local Lighting = game:GetService("Lighting")

local Net = require(ReplicatedStorage.MTL.Net)
local Signal = require(ReplicatedStorage.MTL.Signal)
local Theme = require(ReplicatedStorage.MTL.UI.Theme)
local Motion = require(ReplicatedStorage.MTL.UI.Motion)
local UIKit = require(ReplicatedStorage.MTL.UI.UIKit)
local Format = require(ReplicatedStorage.MTL.Format)
local PhoneConfig = require(ReplicatedStorage.MTL.Config.Phone)
local Story = require(ReplicatedStorage.MTL.Config.Story)
local PhoneRules = require(ReplicatedStorage.MTL.Rules.PhoneRules)
local Build = require(ReplicatedStorage.MTL.UI.Build.Phone)
local Sfx = require(ReplicatedStorage.MTL.UI.Sfx)
local ClientData = require(script.Parent.ClientData)
local UIState = require(script.Parent.UIState)

local player = Players.LocalPlayer
local T = PhoneConfig.Tuning
local P = Theme.Phone

local Phone = {}
Phone.Opened = Signal.new()
Phone.Closed = Signal.new()
Phone.ServerEvent = Signal.new() -- (payload) every PhoneEvent, for apps that care (Settings: pathResult)

type AppSpec = { id: string, title: string?, mount: (Frame, any) -> (), unmount: ((any) -> ())?, onEvent: ((any, any) -> ())? }

local gui: any
local phoneFrame: any
local uiScale: UIScale
local apps: { [string]: AppSpec } = {}
local isOpen = false
local hovering = false
local hidden = false
local pingUntil = 0
local current: { id: string, frame: Frame, ctx: any }? = nil
local scale = 1
local rightInset = T.Margin

-- call state (client view)
type Call = { id: string?, contact: string?, name: string, glyph: string, state: string, openedByCall: boolean, onAnswer: (() -> ())?, onDecline: (() -> ())?, lines: { any }?, choices: { any }?, server: boolean }
local call: Call? = nil
local pendingCall: Call? = nil
-- An app the game asked to open while a cutscene/menu hid the phone: opened as soon as the phone is back.
local pendingOpen: { app: string, args: any }? = nil
-- When the phone last came up. World clicks right after that don't close it (clicking through the end of a cutscene put the phone away again).
local openedAt = -1e9
local OPEN_CLICK_GRACE = 1.0
local ringSound: any = nil
local callToken = 0

local notifyQueue: { any } = {}
local notifyBusy = false

---------------------------------------------------------------- helpers

local function settings(): any
	local d = ClientData.get()
	return (d and d.Settings) or {}
end

local function reducedMotion(): boolean
	return settings().ReducedMotion == true
end

-- Phone sounds go through UI/Sfx (ids in Theme.Sfx). Names used here: PhoneOpen, PhoneClose, PhoneTap, PhoneBack,
-- PhoneNotify, PhoneMessage, PhoneVibrate, PhoneRing (loop), PhoneCallEnd, PhoneShutter, PhoneType, PhoneSend, PhoneToggle.
local function sfx(name: string, opts: any?)
	Sfx.play(name, opts)
end

local function action(actionType: string, payload: { [string]: any }?)
	local p = payload or {}
	p.type = actionType
	Net.get("PhoneAction"):FireServer(p)
end

local function screen(): any
	return phoneFrame.Body.Screen
end

---------------------------------------------------------------- position / motion

local function viewport(): Vector2
	local cam = workspace.CurrentCamera
	return if cam then cam.ViewportSize else Vector2.new(1280, 720)
end

-- On touch screens the jump button sits bottom right: put the phone just left of it.
local function computeRightInset(): number
	local inset = T.Margin
	if UserInputService.TouchEnabled then
		local pg = player:FindFirstChild("PlayerGui")
		local touch = pg and pg:FindFirstChild("TouchGui")
		local frame = touch and touch:FindFirstChild("TouchControlFrame")
		local jump = frame and frame:FindFirstChild("JumpButton") :: GuiObject?
		if jump and jump.Visible then
			inset = math.max(inset, viewport().X - jump.AbsolutePosition.X + 10)
		end
	end
	return inset
end

local function layout()
	local vp = viewport()
	scale = math.clamp(vp.Y * T.HeightOfScreen / T.DesignSize.Y, T.MinScale, T.MaxScale)
	uiScale.Scale = scale
	rightInset = computeRightInset()
end

local function target(): (UDim2, number)
	local h = T.DesignSize.Y * scale
	if hidden then
		return UDim2.new(1, -rightInset, 1, h + 40), T.TiltDegrees
	elseif isOpen then
		return UDim2.new(1, -rightInset, 1, -T.OpenBottom), 0
	end
	local share = T.PeekShare
	if os.clock() < pingUntil then
		share = T.PingShare
	elseif hovering then
		share = T.HoverShare
	end
	return UDim2.new(1, -rightInset, 1, h * (1 - share)), T.TiltDegrees
end

-- The phone moves on a real spring (not a fixed tween), so a new target mid-move (hover, ping, open while it's
-- still lowering) just bends the motion instead of restarting it. Rotation follows the same spring.
local springY, springV, springRot, springRotV = 0, 0, 0, 0
local springTargetY, springTargetRot = 0, 0
local springConn: RBXScriptConnection? = nil

local function stepSpring(dt: number)
	dt = math.min(dt, 1 / 30)
	-- opening is a little bouncy, everything else settles without overshoot
	local freq = if isOpen then T.SpringOpenHz else T.SpringCloseHz
	local damp = if isOpen and not reducedMotion() then T.SpringOpenDamping else 1
	local w = 2 * math.pi * freq
	local function step(x: number, v: number, target: number): (number, number)
		local a = -w * w * (x - target) - 2 * damp * w * v
		v += a * dt
		x += v * dt
		return x, v
	end
	springY, springV = step(springY, springV, springTargetY)
	springRot, springRotV = step(springRot, springRotV, springTargetRot)
	phoneFrame.Position = UDim2.new(1, -rightInset, 1, springY)
	phoneFrame.Rotation = springRot
	if math.abs(springY - springTargetY) < 0.3 and math.abs(springV) < 2 and math.abs(springRot - springTargetRot) < 0.05 then
		springY, springV, springRot, springRotV = springTargetY, 0, springTargetRot, 0
		phoneFrame.Position = UDim2.new(1, -rightInset, 1, springY)
		phoneFrame.Rotation = springRot
		if springConn then
			springConn:Disconnect()
			springConn = nil
		end
	end
end

local function apply(instant: boolean?)
	local pos, rot = target()
	springTargetY, springTargetRot = pos.Y.Offset, rot
	if instant then
		springY, springV, springRot, springRotV = springTargetY, 0, springTargetRot, 0
		phoneFrame.Position = pos
		phoneFrame.Rotation = rot
		return
	end
	if not springConn then
		springConn = RunService.RenderStepped:Connect(function(dt)
			-- half-step twice per frame
			local half = dt / 2
			stepSpring(half)
			if springConn then
				stepSpring(half)
			end
		end)
	end
end

-- Rotated GUI doesn't clip, so a tilted (closed) phone shows the lock-screen look (clock + wallpaper) and the
-- open app is tucked away until the phone comes back up.
local function showContent()
	local s = screen()
	local appUp = isOpen and current ~= nil
	s.AppHost.Visible = appUp
	s.Home.Visible = not appUp
	s.Wallpaper.Visible = not appUp
end

local function refreshBadge()
	local d = ClientData.get()
	local badges = PhoneRules.badges(d and d.Phone)
	local total = 0
	for id, n in badges do
		total += n
		local icon = screen().Home:FindFirstChild("App_" .. id, true)
		if icon then
			UIKit.badge(icon.Icon, n)
		end
	end
	local b = phoneFrame.Badge
	b.Text = if total > 99 then "99+" else tostring(total)
	b.Visible = total > 0 and not isOpen and not hidden
end

---------------------------------------------------------------- apps

function Phone.registerApp(appId: string, spec: any)
	spec.id = appId
	apps[appId] = spec
end

local function makeContext(appId: string, frame: Frame, args: any): any
	local conns: { any } = {}
	-- ctx: everything an app needs, nothing global.
	local ctx = {
		id = appId,
		frame = frame, -- the app's root (fills the screen between status bar and home bar)
		args = args or {}, -- what Phone.open(appId, args) was given (e.g. { contact = "Patel" })
		UIKit = UIKit,
		Theme = Theme,
		Motion = Motion,
		Format = Format,
		Rules = PhoneRules,
		Config = PhoneConfig,
		Story = Story,
		Phone = Phone,
		sfx = sfx, -- ctx.sfx("PhoneShutter")
		data = function()
			return ClientData.get()
		end,
		action = action, -- ctx.action("gpsRoute", { place = "FoodMart" })
		track = function(conn: any) -- connections here are cleaned up on unmount
			table.insert(conns, conn)
			return conn
		end,
		home = function()
			Phone.home()
		end,
		close = function()
			Phone.close()
		end,
	}
	-- ctx.onData(fn(data)) re-runs fn when the save snapshot changes (and once now)
	function ctx.onData(fn: (any) -> ())
		table.insert(conns, ClientData.Changed:Connect(function(new)
			if frame.Parent then
				fn(new)
			end
		end))
		local d = ClientData.get()
		if d then
			task.spawn(fn, d)
		end
	end
	-- ctx.clear(): empties the app frame (apps rebuild their own sub-screens)
	function ctx.clear()
		for _, c in frame:GetChildren() do
			c:Destroy()
		end
	end
	ctx._cleanup = function()
		for _, c in conns do
			if c and c.Disconnect then
				c:Disconnect()
			end
		end
		table.clear(conns)
	end
	return ctx
end

local function unmountCurrent()
	local cur = current
	if not cur then
		return
	end
	current = nil
	local spec = apps[cur.id]
	if spec and spec.unmount then
		pcall(spec.unmount, cur.ctx)
	end
	cur.ctx._cleanup()
	cur.frame:Destroy()
end

local function showHome()
	local wasApp = current ~= nil
	unmountCurrent()
	local s = screen()
	s.AppHost.Visible = false
	s.Home.Visible = true
	s.Wallpaper.Visible = true
	if wasApp and not reducedMotion() then
		local hs = s.Home:FindFirstChildOfClass("UIScale") or UIKit.new("UIScale", { Parent = s.Home })
		hs.Scale = 1.04
		Motion.tween(hs, Motion.AppIn, { Scale = 1 })
	end
end

local function mountApp(appId: string, args: any): boolean
	local spec = apps[appId]
	local d = ClientData.get()
	if not spec then
		warn("[MTL Phone] no app", appId)
		return false
	end
	if d and d.Phone and d.Phone.Apps and d.Phone.Apps[appId] == false then
		return false
	end
	unmountCurrent()
	local host = screen().AppHost
	local frame = UIKit.new("Frame", {
		Name = "App_" .. appId,
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Parent = host,
	})
	local s = UIKit.new("UIScale", { Scale = if reducedMotion() then 1 else 0.96, Parent = frame })
	if not reducedMotion() then
		frame.Position = UDim2.fromOffset(18, 0) -- slides in from the right a touch while it grows
	end
	local ctx = makeContext(appId, frame, args)
	current = { id = appId, frame = frame, ctx = ctx }
	host.Visible = true
	screen().Home.Visible = false
	screen().Wallpaper.Visible = false -- apps sit on the plain screen colour
	local ok, err = pcall(spec.mount, frame, ctx)
	if not ok then
		warn("[MTL Phone] app", appId, "failed:", err)
		UIKit.empty(frame, "This app crashed. Try again.")
	end
	Motion.tween(s, Motion.AppIn, { Scale = 1 })
	Motion.tween(frame, Motion.AppIn, { Position = UDim2.fromOffset(0, 0) })
	return true
end

---------------------------------------------------------------- open / close

function Phone.isOpen(): boolean
	return isOpen
end

function Phone.currentApp(): string?
	return if current then current.id else nil
end

function Phone.open(appId: string?, args: any?)
	if hidden then
		if appId then
			pendingOpen = { app = appId, args = args }
		end
		return
	end
	pendingOpen = nil
	if appId then
		mountApp(appId, args)
	end
	if isOpen then
		return
	end
	isOpen = true
	openedAt = os.clock()
	phoneFrame.Body.Modal = true -- frees the mouse in first person / shift lock
	showContent()
	apply()
	refreshBadge()
	sfx("PhoneOpen")
	Phone.Opened:Fire()
end

function Phone.close()
	if not isOpen then
		return
	end
	if call and call.state ~= "fake" then
		return -- finish or decline the call first (the call screen has the buttons)
	end
	isOpen = false
	hovering = false
	phoneFrame.Body.Modal = false
	apply()
	task.delay(0.2, function()
		if not isOpen then
			showContent()
		end
	end)
	refreshBadge()
	sfx("PhoneClose")
	Phone.Closed:Fire()
end

function Phone.toggle()
	if isOpen then
		Phone.close()
	else
		Phone.open()
	end
end

function Phone.home()
	showHome()
end

Phone.sfx = sfx

-- Camera app: see the world through the glass (screen + wallpaper go transparent; the bezel stays).
function Phone.setViewfinder(on: boolean)
	local s = screen()
	s.BackgroundTransparency = if on then 1 else 0
	s.Wallpaper.Visible = not on and current == nil
	-- the body behind the screen goes clear too (its edge stroke stays as the bezel)
	local body = phoneFrame:FindFirstChild("Body") :: GuiObject?
	if body then
		body.BackgroundTransparency = if on then 1 else 0
		for _, g in body:GetChildren() do
			if g:IsA("UIGradient") then
				g.Enabled = not on
			end
		end
		local rim = body:FindFirstChild("Rim")
		if rim and rim:IsA("GuiObject") then
			rim.Visible = not on
		end
	end
end

-- Camera app: hide the whole phone GUI for the frame a photo is taken (so it isn't in the picture).
function Phone.setCaptureHidden(on: boolean)
	gui.Enabled = not on
end

local function ping()
	if isOpen or hidden then
		return
	end
	pingUntil = os.clock() + T.PingSeconds
	apply()
	task.delay(T.PingSeconds + 0.05, function()
		if os.clock() >= pingUntil then
			apply()
		end
	end)
end

---------------------------------------------------------------- notifications

local function runNotifications()
	if notifyBusy then
		return
	end
	notifyBusy = true
	local banner = screen().Banner
	while #notifyQueue > 0 do
		local n = table.remove(notifyQueue, 1)
		local info = PhoneRules.appInfo(n.app)
		banner.Title.Text = n.title or ""
		banner.Body.Text = n.text or ""
		banner.Icon.Text = (n.app and P.Glyphs and P.Glyphs[n.app]) or n.glyph or (if info then info.glyph else "!")
		banner.Icon.BackgroundColor3 = (n.app and P.AppColors[n.app]) or Theme.Colors.AccentAlt
		banner:SetAttribute("App", n.app)
		banner:SetAttribute("Contact", n.args and n.args.contact or nil)
		-- Rotated GUI doesn't clip, so while the phone is down (tilted) the banner pops in place instead of
		-- sliding in from above the glass.
		local bscale = banner:FindFirstChildOfClass("UIScale") or UIKit.new("UIScale", { Parent = banner })
		local slide = isOpen
		banner.Position = if slide then UDim2.new(0.5, 0, 0, -80) else UDim2.new(0.5, 0, 0, 6)
		bscale.Scale = if slide then 1 else 0.85
		banner.Visible = true
		if n.app ~= "Messages" then
			sfx("PhoneNotify")
		end
		ping()
		local inInfo = if reducedMotion() then Motion.Normal else Motion.Spring
		Motion.tween(banner, inInfo, { Position = UDim2.new(0.5, 0, 0, 6) })
		Motion.tween(bscale, inInfo, { Scale = 1 })
		task.wait(T.NotificationSeconds)
		if isOpen then
			Motion.tween(banner, Motion.Normal, { Position = UDim2.new(0.5, 0, 0, -80) }).Completed:Wait()
		else
			Motion.tween(bscale, Motion.Fast, { Scale = 0.85 }).Completed:Wait()
		end
		bscale.Scale = 1
		banner.Visible = false
	end
	notifyBusy = false
end

-- force = true: show even though the target app is open (apps use it for "another thread" banners)
function Phone.notify(n: { app: string?, title: string, text: string?, args: any?, glyph: string?, force: boolean? })
	if not n.force and isOpen and current and current.id == n.app then
		local spec = apps[n.app]
		if spec and spec.onEvent then
			return -- the open app shows it itself
		end
	end
	table.insert(notifyQueue, n)
	task.spawn(runNotifications)
end

---------------------------------------------------------------- calls

local function callScreen(): any
	return screen().Call
end

local function stopRing()
	if ringSound then
		ringSound:Stop()
		ringSound = nil
	end
end

local function showCallButtons(mode: string)
	local cs = callScreen()
	cs.Answer.Visible = mode == "ringing"
	cs.Decline.Visible = mode == "ringing"
	cs.HangUp.Visible = mode == "connected" or mode == "fake"
	cs.Skip.Visible = mode == "connected"
	cs.Caption.Visible = mode == "connected"
	cs.Choices.Visible = false
end

local function endCallUI(_outcome: string?)
	stopRing()
	sfx("PhoneCallEnd")
	callToken += 1
	local c = call
	call = nil
	local cs = callScreen()
	cs.Status.Text = "Call ended"
	showCallButtons("ended")
	task.delay(0.7, function()
		if call == nil then
			cs.Visible = false
			if c and c.openedByCall and isOpen and not current then
				Phone.close()
			end
		end
	end)
end

-- Shows the scripted lines one at a time (tap to advance, auto after a read-time), then the choices.
local function playLines(c: Call)
	callToken += 1
	local token = callToken
	local cs = callScreen()
	local lines = c.lines or {}
	local index = 0
	local skipAll = false
	local advance = Instance.new("BindableEvent")

	local tapConn = cs.Caption.Activated:Connect(function()
		advance:Fire()
	end)
	local skipConn = cs.Skip.Activated:Connect(function()
		skipAll = true
		advance:Fire()
	end)

	local function showChoices()
		cs.Caption.Visible = #lines > 0
		cs.Skip.Visible = false
		local choices = c.choices
		if not choices or #choices == 0 then
			-- nothing to answer: the call just ends
			if c.server then
				action("hangUp", { call = c.id })
			else
				endCallUI("answered")
			end
			return
		end
		cs.HangUp.Visible = false
		local box = cs.Choices
		for _, ch in box:GetChildren() do
			if ch:IsA("GuiButton") then
				ch:Destroy()
			end
		end
		for i, ch in choices do
			local b = UIKit.button(box, ch.text, {
				style = if i == 1 then "primary" else "secondary",
				order = i,
				onClick = function()
					if call == c then
						action("callChoice", { call = c.id, choice = ch.id })
					end
				end,
			})
			b.ZIndex = 12
		end
		box.Visible = true
	end

	task.spawn(function()
		while token == callToken and call == c do
			index += 1
			local line = lines[index]
			if not line or skipAll then
				break
			end
			cs.Caption.Who.Text = string.upper(line.who == c.contact and c.name or (Story.Contacts[line.who] and Story.Contacts[line.who].Name) or line.who or "")
			local label = cs.Caption.Line
			label.Text = line.text
			label.MaxVisibleGraphemes = if reducedMotion() then -1 else 0
			if not reducedMotion() then
				-- quick typewriter (tap shows the whole line)
				task.spawn(function()
					local n = utf8.len(line.text) or #line.text
					for g = 1, n do
						if label.MaxVisibleGraphemes == -1 or label.Text ~= line.text then
							return
						end
						label.MaxVisibleGraphemes = g
						task.wait(0.018)
					end
					label.MaxVisibleGraphemes = -1
				end)
			end
			local readTime = 1.6 + #line.text * 0.045
			local done = false
			local conn = advance.Event:Connect(function()
				if label.MaxVisibleGraphemes ~= -1 and not skipAll then
					label.MaxVisibleGraphemes = -1 -- first tap finishes the line
				else
					done = true
				end
			end)
			local start = os.clock()
			while not done and os.clock() - start < readTime and token == callToken and call == c do
				task.wait(0.05)
			end
			conn:Disconnect()
		end
		tapConn:Disconnect()
		skipConn:Disconnect()
		advance:Destroy()
		if token == callToken and call == c then
			showChoices()
		end
	end)
end

local function startRingUI(c: Call)
	local cs = callScreen()
	cs.Avatar.Text = c.glyph
	cs.Caller.Text = c.name
	cs.Status.Text = "Incoming call..."
	showCallButtons("ringing")
	cs.Visible = true
	stopRing()
	ringSound = Sfx.loop("PhoneRing")
	-- the phone buzzes while ringing
	if not reducedMotion() then
		local token = callToken
		task.spawn(function()
			local t0 = os.clock()
			while call == c and c.state == "ringing" and token == callToken do
				local t = os.clock() - t0
				local wiggle = if (t % 1.2) < 0.6 then math.sin(t * 60) * 1.6 else 0
				phoneFrame.Rotation = springRot + wiggle -- on top of the spring, so the two never fight
				RunService.RenderStepped:Wait()
			end
			if not hidden then
				phoneFrame.Rotation = springRot
			end
		end)
	end
end

local function beginCall(c: Call)
	if hidden then
		pendingCall = c -- shown when the cutscene/menu that hid the phone ends
		return
	end
	call = c
	c.openedByCall = not isOpen
	if current == nil then
		showHome()
	end
	startRingUI(c)
	Phone.open()
end

-- Local ring (server-driven calls use the same screen through PhoneEvent).
function Phone.incomingCall(opts: { caller: string, glyph: string?, onAnswer: (() -> ())?, onDecline: (() -> ())? })
	beginCall({
		id = nil,
		name = opts.caller,
		glyph = opts.glyph or string.sub(opts.caller, 1, 1),
		state = "ringing",
		openedByCall = false,
		onAnswer = opts.onAnswer,
		onDecline = opts.onDecline,
		server = false,
	})
end

-- Calling a contact who has no scripted call: "Calling..." then the no-answer line.
function Phone.fakeCall(name: string, message: string?)
	if call then
		return
	end
	local c: Call = { id = nil, name = name, glyph = string.sub(name, 1, 1), state = "fake", openedByCall = false, server = false }
	call = c
	callToken += 1
	local token = callToken
	local cs = callScreen()
	cs.Avatar.Text = c.glyph
	cs.Caller.Text = name
	cs.Status.Text = "Calling..."
	showCallButtons("fake")
	cs.Visible = true
	local conn
	conn = cs.HangUp.Activated:Connect(function()
		conn:Disconnect()
		if call == c then
			endCallUI("hungUp")
		end
	end)
	task.delay(2.6, function()
		if call == c and token == callToken then
			cs.Status.Text = message or PhoneConfig.NoAnswer.default
			task.wait(1.8)
			if call == c and token == callToken then
				conn:Disconnect()
				endCallUI("noAnswer")
			end
		end
	end)
end

local function onServerCall(msg: any)
	if msg.state == "ringing" then
		if call and call.server and call.id == msg.call then
			return -- already showing it
		end
		local name = msg.name or "Unknown"
		beginCall({
			id = msg.call,
			name = if msg.contact == "Unknown" then "Unknown number" else name,
			glyph = if msg.contact == "Unknown" then "?" else string.sub(name, 1, 1),
			state = "ringing",
			openedByCall = false,
			server = true,
			contact = msg.contact,
		} :: any)
	elseif msg.state == "connected" then
		local c: any = call
		if not (c and c.server and c.id == msg.call) then
			-- outgoing call-back (or a client that missed the ring): build the screen now
			local name = msg.name or "Unknown"
			c = {
				id = msg.call,
				name = if msg.contact == "Unknown" then "Unknown number" else name,
				glyph = if msg.contact == "Unknown" then "?" else string.sub(name, 1, 1),
				state = "connected",
				openedByCall = not isOpen,
				server = true,
				contact = msg.contact,
			}
			call = c
			if hidden then
				return
			end
			local cs = callScreen()
			cs.Avatar.Text = c.glyph
			cs.Caller.Text = c.name
			cs.Visible = true
			Phone.open()
		end
		stopRing()
		c.state = "connected"
		c.lines = msg.lines
		c.choices = msg.choices
		local cs = callScreen()
		cs.Status.Text = if msg.outgoing then "Connected" else "On call"
		showCallButtons("connected")
		local _, rot = target()
		phoneFrame.Rotation = rot
		playLines(c)
	elseif msg.state == "ended" then
		if pendingCall and pendingCall.id == msg.call then
			pendingCall = nil
		end
		if call and call.server and call.id == msg.call then
			endCallUI(msg.outcome)
		end
	end
end

---------------------------------------------------------------- input

local function hookInput()
	local body = phoneFrame.Body
	body.Activated:Connect(function()
		if not isOpen then
			Phone.open()
		end
	end)
	-- Hover lift. Not MouseEnter/Leave: Roblox fires MouseLeave when a GuiObject moves under a still cursor,
	-- so the lift would cancel itself. Instead test the mouse against where the closed phone sits on screen,
	-- with a bigger zone to stay hovered than to start (so the lift can never un-hover itself).
	UserInputService.InputChanged:Connect(function(input)
		if input.UserInputType ~= Enum.UserInputType.MouseMovement then
			return
		end
		local want = false
		if not isOpen and not hidden then
			local vp = viewport()
			local m = UserInputService:GetMouseLocation()
			local w, h = T.DesignSize.X * scale, T.DesignSize.Y * scale
			local right = vp.X - rightInset
			local share = if hovering then T.HoverShare else T.PeekShare
			local top = vp.Y - h * share - (if hovering then 12 else 4)
			want = m.X >= right - w - 8 and m.X <= right + 8 and m.Y >= top
		end
		if want ~= hovering then
			hovering = want
			apply()
		end
	end)

	local keys: { [Enum.KeyCode]: boolean } = {}
	for _, k in T.ToggleKeys do
		keys[k] = true
	end
	UserInputService.InputBegan:Connect(function(input, processed)
		if processed then
			return
		end
		if keys[input.KeyCode] then
			if UserInputService:GetFocusedTextBox() == nil then
				Phone.toggle()
			end
		elseif input.UserInputType == Enum.UserInputType.MouseButton1 and isOpen then
			if os.clock() - openedAt <= OPEN_CLICK_GRACE then
				openedAt = os.clock() -- still clicking through: keep ignoring until the clicks pause
			else
				Phone.close() -- clicked the world (clicks on GUI are "processed")
			end
		end
	end)

	-- drag the status bar or the home bar down to put the phone away; tap the home bar to go home
	local s = screen()
	local dragStart: Vector3? = nil
	local dragged = false
	local function beginDrag(input: InputObject)
		if not isOpen then
			return
		end
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragStart = input.Position
			dragged = false
		end
	end
	s.HomeBar.InputBegan:Connect(beginDrag)
	s.StatusBar.InputBegan:Connect(beginDrag)
	UserInputService.InputChanged:Connect(function(input)
		local start = dragStart
		if start and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
			if input.Position.Y - start.Y > T.SwipeClosePixels then
				dragStart = nil
				dragged = true
				Phone.close()
			end
		end
	end)
	UserInputService.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragStart = nil
		end
	end)
	s.HomeBar.Activated:Connect(function()
		if not dragged and isOpen and not call then
			showHome()
		end
		dragged = false
	end)

	-- call buttons
	local cs = s.Call
	cs.Answer.Activated:Connect(function()
		local c = call
		if not c or c.state ~= "ringing" then
			return
		end
		stopRing()
		if c.server then
			action("answerCall", { call = c.id })
		else
			c.state = "connected"
			showCallButtons("connected")
			cs.Status.Text = "On call"
			if c.onAnswer then
				task.spawn(c.onAnswer)
			end
			playLines(c)
		end
	end)
	cs.Decline.Activated:Connect(function()
		local c = call
		if not c or c.state ~= "ringing" then
			return
		end
		if c.server then
			action("declineCall", { call = c.id })
			endCallUI("declined") -- feels instant; the server's "ended" is ignored once call is nil
		else
			if c.onDecline then
				task.spawn(c.onDecline)
			end
			endCallUI("declined")
		end
	end)
	cs.HangUp.Activated:Connect(function()
		local c = call
		if c and c.state == "connected" then
			if c.server then
				action("hangUp", { call = c.id })
			else
				endCallUI("hungUp")
			end
		end
	end)

	-- banner tap opens what it's about
	-- (InputEnded too: on the tilted phone Activated was seen to drop some clicks in play-test)
	local lastBannerTap = 0
	local function bannerTap()
		if os.clock() - lastBannerTap < 0.3 then
			return
		end
		lastBannerTap = os.clock()
		local app = s.Banner:GetAttribute("App")
		if type(app) == "string" and apps[app] then
			local contact = s.Banner:GetAttribute("Contact")
			Phone.open(app, if contact then { contact = contact } else nil)
		end
	end
	s.Banner.Activated:Connect(bannerTap)
	s.Banner.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			bannerTap()
		end
	end)

	-- home icons
	for _, app in PhoneConfig.Apps do
		local icon = s.Home:FindFirstChild("App_" .. app.id, true)
		if not icon then
			icon = Build.appIcon(app, 99)
			icon.Parent = s.Home.Grid
		end
		-- press feel: the tile sinks a little under your finger, springs back on release
		local sq = icon:FindFirstChild("Icon")
		if sq then
			local sc = sq:FindFirstChildOfClass("UIScale") or UIKit.new("UIScale", { Parent = sq })
			icon.MouseButton1Down:Connect(function()
				Motion.tween(sc, Motion.Fast, { Scale = 0.9 })
			end)
			icon.MouseButton1Up:Connect(function()
				Motion.tween(sc, Motion.Fast, { Scale = 1 })
			end)
			icon.MouseLeave:Connect(function()
				Motion.tween(sc, Motion.Fast, { Scale = 1 })
			end)
		end
		icon.Activated:Connect(function()
			if isOpen and not call then
				mountApp(app.id)
			elseif not isOpen then
				Phone.open(app.id)
			end
		end)
	end
end

local function refreshIcons(data: any)
	local installed = (data and data.Phone and data.Phone.Apps) or {}
	for _, app in PhoneConfig.Apps do
		local icon = screen().Home:FindFirstChild("App_" .. app.id, true)
		if icon then
			icon.Visible = apps[app.id] ~= nil and installed[app.id] ~= false
		end
	end
end

---------------------------------------------------------------- server events

local function onPhoneEvent(msg: any)
	if type(msg) ~= "table" or type(msg.type) ~= "string" then
		return
	end
	Phone.ServerEvent:Fire(msg)
	if current then
		local spec = apps[current.id]
		if spec and spec.onEvent then
			task.spawn(spec.onEvent, msg, current.ctx)
		end
	end
	if msg.type == "text" then
		if not msg.silent then
			sfx("PhoneMessage")
			if not isOpen then
				task.delay(0.15, sfx, "PhoneVibrate")
			end
			local inThread = isOpen and current and current.id == "Messages" and current.ctx.args.contact == msg.contact
			if not inThread then
				Phone.notify({ app = "Messages", title = msg.name or "Message", text = msg.text, args = { contact = msg.contact }, glyph = string.sub(msg.name or "?", 1, 1) })
			end
		end
	elseif msg.type == "call" then
		onServerCall(msg)
	elseif msg.type == "notify" then
		Phone.notify({ app = msg.app, title = msg.title, text = msg.text })
	elseif msg.type == "unlockApp" then
		Phone.notify({ app = msg.app, title = "New app", text = tostring(msg.title) .. " is on your phone" })
	elseif msg.type == "open" then
		Phone.open(msg.app)
	end
end

---------------------------------------------------------------- init

local function getGui()
	local pg = player:WaitForChild("PlayerGui")
	local existing = pg:FindFirstChild("MTL_Phone")
	if existing then
		return existing
	end
	local built = Build.build()
	built.Parent = pg
	return built
end

local function loadApps()
	local folder = script.Parent.Parent:FindFirstChild("Apps")
	if not folder then
		return
	end
	for _, m in folder:GetChildren() do
		if m:IsA("ModuleScript") then
			local ok, spec = pcall(require, m)
			if ok and type(spec) == "table" and type(spec.mount) == "function" then
				Phone.registerApp(spec.id or m.Name, spec)
			else
				warn("[MTL Phone] bad app module", m.Name, spec)
			end
		end
	end
end

function Phone.init()
	gui = getGui()
	phoneFrame = gui.Phone
	uiScale = phoneFrame:FindFirstChildOfClass("UIScale") or UIKit.new("UIScale", { Parent = phoneFrame })
	loadApps()
	layout()
	apply(true)
	hookInput()

	local cam = workspace.CurrentCamera
	if cam then
		cam:GetPropertyChangedSignal("ViewportSize"):Connect(function()
			layout()
			apply(true)
		end)
	end
	-- the touch jump button appears late on mobile; re-check the inset now and then
	task.spawn(function()
		while true do
			task.wait(2)
			local r = computeRightInset()
			if r ~= rightInset then
				rightInset = r
				apply()
			end
		end
	end)

	UIState.Changed:Connect(function(state)
		local h = state.hidePhone == true
		if h == hidden then
			return
		end
		hidden = h
		if h and isOpen then
			isOpen = false
			phoneFrame.Body.Modal = false
			showContent()
			Phone.Closed:Fire()
		end
		apply()
		refreshBadge()
		if not h and pendingCall then
			local c = pendingCall
			pendingCall = nil
			pendingOpen = nil
			task.delay(0.4, beginCall, c)
		elseif not h and pendingOpen then
			local o = pendingOpen
			task.delay(0.4, function()
				if pendingOpen == o and not hidden then
					Phone.open(o.app, o.args)
				end
			end)
		end
	end)

	ClientData.Changed:Connect(function(data)
		refreshIcons(data)
		refreshBadge()
		Sfx.setMuted(data and data.Settings and data.Settings.Sound == false or false)
	end)

	-- every button on the phone clicks; Back buttons and toggles get their own sound. A button that plays its
	-- own sound (e.g. the camera shutter) sets the attribute MTL_NoTapSound.
	local function hookButton(b: Instance)
		if not b:IsA("GuiButton") or b == phoneFrame:FindFirstChild("Body") then
			return
		end
		b.Activated:Connect(function()
			if b:GetAttribute("MTL_NoTapSound") then
				return
			end
			sfx(if b.Name == "Back" then "PhoneBack" elseif b.Name == "Toggle" then "PhoneToggle" else "PhoneTap")
		end)
	end
	for _, d in gui:GetDescendants() do
		hookButton(d)
	end
	gui.DescendantAdded:Connect(hookButton)
	Sfx.preload()
	if ClientData.get() then
		refreshIcons(ClientData.get())
		refreshBadge()
	end

	Net.get("PhoneEvent").OnClientEvent:Connect(onPhoneEvent)

	-- clock on the status bar and lock screen (game time)
	task.spawn(function()
		while true do
			local mins = Lighting:GetMinutesAfterMidnight()
			local text = PhoneRules.clock(mins)
			local s = screen()
			s.StatusBar.Time.Text = text
			s.Home.Clock.Text = (string.gsub(text, " [AP]M$", ""))
			local date = s.Home:FindFirstChild("Date")
			if date then
				date.Text = os.date("%A, %B ") .. tostring(tonumber(os.date("%d")))
			end
			task.wait(1)
		end
	end)

	print("[MTL Phone] ready,", (function()
		local n = 0
		for _ in apps do
			n += 1
		end
		return n
	end)(), "apps")
end

return Phone
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "PropertyController", "ModuleScript", [======[--!strict
-- Client side of Piece 4 (the flat). Listens to PropertyState (PropertyService) and:
--   * the FOR SALE card (MTL_Property.Listing): BUY sends PropertyAction buy; "Not now" / Esc / B closes it
--   * the door fade when you walk in or out (ends by itself after 4 s, or the moment a cutscene takes over)
--   * the outside door: this player's own prompt text ("For sale · $1,200" / "Go inside"), and while you're house
--     hunting (FindAPlace) a pulsing outline + a FOR SALE sign over it you can see from down the street
--   * highlights inside your room: the bed at FirstNight ("Sleep"), the front door when it's time to go to work
--   * your room's power: the dead bulb, the PC screen and its power light (lit once the bill is paid)
--   * opens the phone on an app when the server asks (the Jobs app after the move-in scene), and nudges the phone
--     while the ChooseJob stage waits for a pick
--   * the custom cutscene beats used by Cutscenes/PowerOut + NextDay: BulbFlicker, BulbOff, PcPower,
--     KeyboardBounce, PhoneOut, MorningLight
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local CollectionService = game:GetService("CollectionService")
local SoundService = game:GetService("SoundService")
local GuiService = game:GetService("GuiService")

local Net = require(ReplicatedStorage.MTL.Net)
local Theme = require(ReplicatedStorage.MTL.UI.Theme)
local Motion = require(ReplicatedStorage.MTL.UI.Motion)
local Format = require(ReplicatedStorage.MTL.Format)
local Property = require(ReplicatedStorage.MTL.Config.Property)
local Locations = require(ReplicatedStorage.MTL.Config.Locations)
local PropertyRules = require(ReplicatedStorage.MTL.Rules.PropertyRules)
local Build = require(ReplicatedStorage.MTL.UI.Build.Property)
local ClientData = require(script.Parent.ClientData)
local UIState = require(script.Parent.UIState)

local player = Players.LocalPlayer
local K = Theme.Property

local PropertyController = {}

local gui: any
local listingHome: string? = nil
local fadeToken = 0
local bedOn = false
local exitOn = false
local sceneLight = { bulbOverride = false, morning = nil :: Light? }

local function log(...)
	print("[MTL Property]", ...)
end

local function sibling(name: string): any?
	local m = script.Parent:FindFirstChild(name)
	if not m then
		return nil
	end
	local ok, mod = pcall(require, m)
	return if ok then mod else nil
end

local function playSound(id: string?, volume: number?)
	if type(id) ~= "string" or id == "" then
		return
	end
	local s = Instance.new("Sound")
	s.SoundId = id
	s.Volume = volume or 0.5
	SoundService:PlayLocalSound(s)
	task.delay(3, function()
		s:Destroy()
	end)
end

local function myRoom(): Model?
	local f = workspace:FindFirstChild("MTL_Flats")
	local m = f and f:FindFirstChild("Flat_" .. player.UserId)
	return if m and m:IsA("Model") then m else nil
end

local function roomPart(name: string): BasePart?
	local m = myRoom()
	local p = m and m:FindFirstChild(name, true)
	return if p and p:IsA("BasePart") then p else nil
end

local function powerOn(): boolean
	local d = ClientData.get()
	return d ~= nil and d.Home ~= nil and d.Home.PowerOn == true
end

---------------------------------------------------------------- fade

local function fadeOut(seconds: number?)
	fadeToken += 1
	local token = fadeToken
	local f = gui.Fade
	f.Visible = true
	Motion.tween(f, TweenInfo.new(seconds or 0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { BackgroundTransparency = 0 })
	UIState.push("PropertyFade", { hideHUD = true, hideWaypoints = true, lockControls = true })
	task.delay(4, function()
		if token == fadeToken then
			PropertyController.fadeIn()
		end
	end)
end

function PropertyController.fadeIn(seconds: number?)
	fadeToken += 1
	local token = fadeToken
	UIState.pop("PropertyFade")
	local f = gui.Fade
	if not f.Visible then
		return
	end
	local t = Motion.tween(f, TweenInfo.new(seconds or 0.45, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), { BackgroundTransparency = 1 })
	t.Completed:Connect(function()
		if token == fadeToken then
			f.Visible = false
		end
	end)
end

local function clearFadeNow()
	fadeToken += 1
	UIState.pop("PropertyFade")
	gui.Fade.BackgroundTransparency = 1
	gui.Fade.Visible = false
end

---------------------------------------------------------------- FOR SALE card

local function closeListing()
	if not gui.Listing.Visible then
		return
	end
	listingHome = nil
	UIState.pop("PropertyListing")
	if GuiService.SelectedObject and GuiService.SelectedObject:IsDescendantOf(gui) then
		GuiService.SelectedObject = nil
	end
	local card = gui.Listing.Card
	Motion.tween(card.Scale, Motion.Fast, { Scale = 0.94 })
	task.delay(0.12, function()
		if not listingHome then
			gui.Listing.Visible = false
		end
	end)
end

local function showListing(msg: any)
	local card = gui.Listing.Card
	listingHome = msg.home
	card.Title.Text = tostring(msg.title or "")
	card.Area.Text = tostring(msg.area or "")
	card.Blurb.Text = tostring(msg.blurb or "")
	card.Price.Text = Format.cash(msg.price or 0)
	card.Cash.Text = "You have " .. Format.cash(msg.cash or 0)
	local photo = card.Photo
	if type(msg.photo) == "string" and msg.photo ~= "rbxassetid://0" then
		photo.Image.Image = msg.photo
		photo.Sign.Visible = false
	end
	-- facts: one row per line
	local facts = card.Facts
	for _, c in facts:GetChildren() do
		if c.Name == "Fact" then
			c:Destroy()
		end
	end
	local template = facts:FindFirstChild("FactTemplate")
	if template then
		for i, f in (if type(msg.facts) == "table" then msg.facts else {}) do
			local row = template:Clone()
			row.Name = "Fact"
			row.LayoutOrder = i
			row.Visible = true
			row.Key.Text = tostring(f[1])
			row.Value.Text = tostring(f[2])
			row.Parent = facts
		end
	end
	local buy = card.Buttons.Buy
	if msg.canBuy then
		card.Short.Text = ""
		card.Short.Visible = false
		buy.Text = "BUY IT · " .. Format.cash(msg.price or 0)
		buy.Active = true
		buy.AutoButtonColor = false
		buy.BackgroundTransparency = 0
		buy.TextTransparency = 0
	else
		local short = tonumber(msg.short) or 0
		card.Short.Visible = true
		card.Short.Text = if short > 0 then ("You need " .. Format.cash(short) .. " more. Work a shift (phone, Jobs app) and come back.")
			else tostring(msg.reason or "Not for sale")
		buy.Text = if short > 0 then ("NEED " .. Format.cash(short)) else "NOT FOR SALE"
		buy.Active = false
		buy.BackgroundTransparency = 0.6
		buy.TextTransparency = 0.4
	end
	gui.Listing.Visible = true
	UIState.push("PropertyListing", { hidePhone = true })
	if UserInputService.GamepadEnabled then
		GuiService.SelectedObject = if buy.Active then buy else card.Buttons.Later
	end
	card.Scale.Scale = 0.9
	Motion.tween(card.Scale, Motion.Spring, { Scale = 1 })
end

---------------------------------------------------------------- outlines

local highlights: { [string]: Highlight } = {}

local function outline(key: string, target: Instance?)
	local old = highlights[key]
	if old then
		old:Destroy()
		highlights[key] = nil
	end
	if not target then
		return
	end
	local h = Instance.new("Highlight")
	h.Name = "MTL_Outline_" .. key
	h.FillTransparency = 1
	h.OutlineColor = K.Highlight
	h.OutlineTransparency = 0.1
	h.DepthMode = Enum.HighlightDepthMode.Occluded
	h.Adornee = target
	h.Parent = workspace -- local (made on the client, never replicates)
	highlights[key] = h
end

-- a glowing frame for invisible door parts (a Highlight can't outline something you can't see)
local doorGlow: Model? = nil
local doorSign: BillboardGui? = nil

local function clearDoorCue()
	if doorGlow then
		doorGlow:Destroy()
		doorGlow = nil
	end
	if doorSign then
		doorSign:Destroy()
		doorSign = nil
	end
	outline("Door", nil)
end

local function doorCue(door: BasePart, price: number)
	clearDoorCue()
	if door.Transparency < 1 then
		outline("Door", door)
	else
		local m = Instance.new("Model")
		m.Name = "MTL_DoorGlow"
		local s = door.Size
		local strips = {
			{ CFrame.new(0, s.Y / 2, 0), Vector3.new(s.X + 0.4, 0.25, 0.25) },
			{ CFrame.new(-s.X / 2, 0, 0), Vector3.new(0.25, s.Y, 0.25) },
			{ CFrame.new(s.X / 2, 0, 0), Vector3.new(0.25, s.Y, 0.25) },
		}
		for _, st in strips do
			local p = Instance.new("Part")
			p.Anchored = true
			p.CanCollide = false
			p.CanQuery = false
			p.CanTouch = false
			p.Material = Enum.Material.Neon
			p.Color = K.Highlight
			p.Transparency = 0.25
			p.Size = st[2]
			p.CFrame = door.CFrame * st[1]
			p.Parent = m
		end
		m.Parent = workspace
		doorGlow = m
	end
	local bb = Instance.new("BillboardGui")
	bb.Name = "MTL_ForSale"
	bb.Size = UDim2.fromOffset(170, 54)
	bb.StudsOffsetWorldSpace = Vector3.new(0, door.Size.Y / 2 + 2.6, 0)
	bb.AlwaysOnTop = true
	bb.MaxDistance = 600
	bb.LightInfluence = 0
	bb.Adornee = door
	local sign = Instance.new("TextLabel")
	sign.Size = UDim2.fromScale(1, 1)
	sign.BackgroundColor3 = K.Sign
	sign.TextColor3 = K.SignText
	sign.FontFace = Theme.Fonts.Display
	sign.TextScaled = true
	sign.Text = "FOR SALE · " .. Format.cash(price)
	sign.Parent = bb
	local corner = Instance.new("UICorner")
	corner.CornerRadius = UDim.new(0, 6)
	corner.Parent = sign
	local pad = Instance.new("UIPadding")
	pad.PaddingLeft = UDim.new(0, 8)
	pad.PaddingRight = UDim.new(0, 8)
	pad.Parent = sign
	bb.Parent = gui
	doorSign = bb
end

local function refreshDoors()
	local d = ClientData.get()
	if not d or not d.Story then
		return
	end
	local hunting = d.Story.Stage == "FindAPlace" and not PropertyRules.ownsAny(d)
	local cued = false
	for _, door in CollectionService:GetTagged("MTL_HomeDoor") do
		if door:IsA("BasePart") then
			local homeId = door:GetAttribute("MTL_Home")
			local prompt = door:FindFirstChild("MTL_DoorPrompt")
			if type(homeId) == "string" and prompt and prompt:IsA("ProximityPrompt") then
				prompt.ActionText = PropertyRules.doorText(d, homeId) -- local only: every player sees their own text
				if hunting and homeId == Property.StarterHome then
					cued = true
					if not doorSign or doorSign.Adornee ~= door then
						doorCue(door, Property.Homes[homeId].price)
					end
				end
			end
		end
	end
	if not cued then
		clearDoorCue()
	end
end

local function refreshRoomCues()
	local bed = roomPart("Mattress") or roomPart("BedSeat")
	outline("Bed", if bedOn and bed then bed else nil)
	local door = roomPart("ExitDoor") or roomPart("Exit")
	outline("Exit", if exitOn and door then door else nil)
	local Wayfinder = sibling("WayfindingController")
	if Wayfinder then
		if bedOn and bed then
			Wayfinder.set("MTL_Bed", bed.Position + Vector3.new(0, 1.5, 0), { label = "Sleep", radius = 3, breadcrumbs = false })
		else
			Wayfinder.clear("MTL_Bed", true)
		end
	end
end

---------------------------------------------------------------- power visuals (your room only)

local function applyPower()
	local on = powerOn()
	local bulb = roomPart("Bulb")
	if bulb and not sceneLight.bulbOverride then
		local light = bulb:FindFirstChildWhichIsA("Light")
		if light then
			light.Enabled = on
		end
		bulb.Material = if on then Enum.Material.Neon else Enum.Material.Glass
		bulb.Color = if on then K.Bulb else Color3.fromRGB(150, 146, 136)
	end
	local screen = roomPart("Screen")
	local display = screen and screen:FindFirstChildWhichIsA("SurfaceGui")
	if display then
		display.Enabled = on
	end
	local led = roomPart("PowerLed")
	if led then
		led.Color = if on then Color3.fromRGB(80, 255, 120) else Color3.fromRGB(60, 10, 10)
	end
end

---------------------------------------------------------------- cutscene beats

local function registerBeats()
	local Cutscene = sibling("CutsceneController")
	if not Cutscene then
		warn("[MTL Property] no CutsceneController; the flat scenes play without their props")
		return
	end
	-- the light switch: a few weak flickers, then dead (only if the power is off)
	Cutscene.registerAction("BulbFlicker", function(_ctx, a)
		local bulb = roomPart("Bulb")
		local light = bulb and bulb:FindFirstChildWhichIsA("Light")
		if not bulb or not light or powerOn() then
			return
		end
		sceneLight.bulbOverride = true
		local stop = os.clock() + (a.dur or 2)
		task.spawn(function()
			local rng = Random.new()
			while os.clock() < stop and bulb.Parent do
				local lit = rng:NextNumber() < 0.45
				light.Enabled = lit
				bulb.Material = if lit then Enum.Material.Neon else Enum.Material.Glass
				task.wait(rng:NextNumber(0.04, 0.16))
			end
			sceneLight.bulbOverride = false
			applyPower()
		end)
	end)
	Cutscene.registerAction("BulbOff", function()
		local bulb = roomPart("Bulb")
		local light = bulb and bulb:FindFirstChildWhichIsA("Light")
		if light then
			sceneLight.bulbOverride = true
			light.Enabled = false
			bulb.Material = Enum.Material.Glass
		end
	end)
	-- press power: the light blinks once, the screen twitches, nothing
	Cutscene.registerAction("PcPower", function()
		local led = roomPart("PowerLed")
		local screen = roomPart("Screen")
		if powerOn() then
			return
		end
		if led then
			led.Color = Color3.fromRGB(255, 40, 40)
			task.delay(0.12, function()
				led.Color = Color3.fromRGB(60, 10, 10)
			end)
		end
		if screen then
			local was = screen.Color
			screen.Color = Color3.fromRGB(40, 44, 40)
			task.delay(0.07, function()
				screen.Color = was
			end)
		end
	end)
	Cutscene.registerAction("KeyboardBounce", function()
		local kb = roomPart("Keyboard")
		if not kb then
			return
		end
		local base = kb:GetAttribute("MTL_Base") :: CFrame?
		if not base then
			base = kb.CFrame
			kb:SetAttribute("MTL_Base", base)
		end
		assert(base)
		local rng = Random.new()
		kb.CFrame = base * CFrame.new(rng:NextNumber(-0.05, 0.05), 0.22, 0) * CFrame.Angles(math.rad(rng:NextNumber(-8, 8)), 0, math.rad(rng:NextNumber(-6, 6)))
		task.delay(0.09, function()
			kb.CFrame = base * CFrame.Angles(0, math.rad(rng:NextNumber(-4, 4)), 0)
		end)
	end)
	-- a phone in the actor's right hand, its screen lighting the face
	Cutscene.registerAction("PhoneOut", function(ctx)
		local actor = ctx.actors and ctx.actors.Player
		local model = actor and actor.model
		local hand = model and (model:FindFirstChild("RightHand") or model:FindFirstChild("Right Arm"))
		if not hand or not hand:IsA("BasePart") then
			return
		end
		local phone = Instance.new("Part")
		phone.Name = "ScenePhone"
		phone.Size = Vector3.new(0.45, 0.85, 0.08)
		phone.Color = Color3.fromRGB(18, 19, 24)
		phone.CanCollide = false
		phone.CanQuery = false
		phone.CanTouch = false
		phone.Massless = true
		local screen = Instance.new("Part")
		screen.Name = "Glow"
		screen.Size = Vector3.new(0.38, 0.75, 0.02)
		screen.Material = Enum.Material.Neon
		screen.Color = Color3.fromRGB(150, 190, 255)
		screen.CanCollide = false
		screen.CanQuery = false
		screen.Massless = true
		local light = Instance.new("PointLight")
		light.Color = Color3.fromRGB(150, 190, 255)
		light.Brightness = 1.2
		light.Range = 5
		light.Parent = screen
		local yOff = if hand.Name == "RightHand" then -0.25 else -1.1
		phone.CFrame = hand.CFrame * CFrame.new(0, yOff, -0.2) * CFrame.Angles(math.rad(-70), 0, 0)
		screen.CFrame = phone.CFrame * CFrame.new(0, 0, -0.05)
		local w1 = Instance.new("WeldConstraint")
		w1.Part0 = hand
		w1.Part1 = phone
		w1.Parent = phone
		local w2 = Instance.new("WeldConstraint")
		w2.Part0 = phone
		w2.Part1 = screen
		w2.Parent = screen
		phone.Parent = model
		screen.Parent = model -- destroyed with the actor when the scene ends
	end)
	-- morning light through the boards (stays a minute, then fades)
	Cutscene.registerAction("MorningLight", function()
		local window = roomPart("Window")
		if not window then
			return
		end
		if sceneLight.morning then
			sceneLight.morning:Destroy()
		end
		local l = Instance.new("SpotLight")
		l.Name = "MTL_Morning"
		l.Face = Enum.NormalId.Back
		l.Color = K.Morning
		l.Brightness = 3
		l.Range = 30
		l.Angle = 70
		l.Shadows = true
		l.Parent = window
		sceneLight.morning = l
		task.delay(60, function()
			if l.Parent then
				Motion.tween(l, TweenInfo.new(4), { Brightness = 0 })
				task.delay(4.2, function()
					l:Destroy()
				end)
			end
		end)
	end)
	Cutscene.Started:Connect(function()
		clearFadeNow() -- the cutscene's own black takes over from the door fade
		closeListing()
	end)
	Cutscene.Finished:Connect(function(id)
		if id == "PowerOut" or id == "NextDay" then
			sceneLight.bulbOverride = false
			applyPower()
			local kb = roomPart("Keyboard")
			local base = kb and kb:GetAttribute("MTL_Base")
			if kb and typeof(base) == "CFrame" then
				kb.CFrame = base
			end
		end
	end)
end

---------------------------------------------------------------- the phone

local phoneWanted: string? = nil

local function openPhoneWhenFree(app: string)
	phoneWanted = app
	task.spawn(function()
		local Phone = sibling("PhoneController")
		local Cutscene = sibling("CutsceneController")
		if not Phone then
			return
		end
		local deadline = os.clock() + 30
		while os.clock() < deadline and phoneWanted == app do
			local st = UIState.get()
			local scene = Cutscene and Cutscene.isPlaying()
			if not scene and not st.hidePhone then
				task.wait(0.4) -- let the camera settle back first
				if not (Cutscene and Cutscene.isPlaying()) and not UIState.get().hidePhone then
					Phone.open(app)
					if Phone.isOpen() and Phone.currentApp() == app then
						break
					end
				end
			end
			task.wait(0.25)
		end
		if phoneWanted == app then
			phoneWanted = nil
		end
	end)
end

-- ChooseJob: if the phone is put away without a pick, nudge it (a banner that opens Jobs), not more than every 25 s
local function nudgeLoop()
	local closedSince: number? = nil
	local lastNudge = 0
	while true do
		task.wait(1)
		local d = ClientData.get()
		local Phone = sibling("PhoneController")
		if d and d.Story and d.Story.Stage == "ChooseJob" and Phone then
			if Phone.isOpen() then
				closedSince = nil
			else
				closedSince = closedSince or os.clock()
				if os.clock() - (closedSince :: number) > 10 and os.clock() - lastNudge > 25 and not UIState.get().hidePhone then
					lastNudge = os.clock()
					Phone.notify({ app = "Jobs", title = "Jobs", text = "3 places are hiring. Tap to pick one." })
				end
			end
		else
			closedSince = nil
		end
	end
end

---------------------------------------------------------------- init

local function getGui()
	local pg = player:WaitForChild("PlayerGui")
	local existing = pg:FindFirstChild("MTL_Property")
	if existing then
		return existing
	end
	local built = Build.build()
	built.Parent = pg
	return built
end

local function onState(msg: any)
	if type(msg) ~= "table" then
		return
	end
	local kind = msg.type
	if kind == "listing" then
		if msg.close then
			closeListing()
			if msg.bought then
				playSound(K.Sounds.Buy, 0.6)
			end
		else
			showListing(msg)
		end
	elseif kind == "fade" then
		closeListing()
		fadeOut(msg.seconds)
	elseif kind == "arrived" then
		PropertyController.fadeIn()
		task.delay(0.6, applyPower)
	elseif kind == "phone" and type(msg.app) == "string" then
		openPhoneWhenFree(msg.app)
	elseif kind == "bed" then
		bedOn = msg.on == true
		refreshRoomCues()
	elseif kind == "exit" then
		exitOn = msg.on == true
		refreshRoomCues()
	elseif kind == "power" then
		applyPower()
	end
end

function PropertyController.init()
	gui = getGui()
	gui.Listing.Visible = false
	gui.Fade.Visible = false
	local card = gui.Listing.Card
	card.Buttons.Buy.Activated:Connect(function()
		if listingHome and card.Buttons.Buy.Active then
			Net.get("PropertyAction"):FireServer({ type = "buy", home = listingHome })
			card.Buttons.Buy.Text = "..."
		end
	end)
	card.Buttons.Later.Activated:Connect(closeListing)
	UserInputService.InputBegan:Connect(function(input, processed)
		if gui.Listing.Visible and (input.KeyCode == Enum.KeyCode.Escape or input.KeyCode == Enum.KeyCode.ButtonB) then
			closeListing()
		end
	end)
	-- walking away closes the card
	RunService.Heartbeat:Connect(function()
		if not listingHome then
			return
		end
		local char = player.Character
		local r = char and char:FindFirstChild("HumanoidRootPart") :: BasePart?
		local h = Property.Homes[listingHome]
		local loc = h and (Locations :: any)[h.location]
		if r and loc and (Vector2.new(r.Position.X - loc.Door.X, r.Position.Z - loc.Door.Z)).Magnitude > Property.Door.Radius + 18 then
			closeListing()
		end
	end)

	Net.get("PropertyState").OnClientEvent:Connect(function(msg)
		local ok, err = pcall(onState, msg)
		if not ok then
			warn("[MTL Property] state failed:", err)
		end
	end)
	ClientData.Changed:Connect(function()
		refreshDoors()
		applyPower()
	end)
	CollectionService:GetInstanceAddedSignal("MTL_HomeDoor"):Connect(function()
		task.defer(refreshDoors)
	end)
	-- your room streams in after you join (and after a rejoin): apply its power + cues when it appears
	task.spawn(function()
		local flats = workspace:WaitForChild("MTL_Flats", 60)
		if flats then
			flats.ChildAdded:Connect(function(c)
				if c.Name == "Flat_" .. player.UserId then
					task.wait(0.5)
					applyPower()
					refreshRoomCues()
				end
			end)
		end
	end)
	-- the outline pulses gently (max one pulse a second; Research: Onboarding)
	RunService.Heartbeat:Connect(function()
		local a = (math.sin(os.clock() * math.pi) + 1) / 2
		local tr = 0.1 + (K.HighlightPulse - 0.1) * a
		for _, h in highlights do
			h.OutlineTransparency = tr
		end
		if doorGlow then
			for _, p in doorGlow:GetChildren() do
				if p:IsA("BasePart") then
					p.Transparency = 0.15 + 0.5 * a
				end
			end
		end
	end)
	registerBeats()
	task.spawn(nudgeLoop)
	task.defer(function()
		ClientData.waitReady()
		refreshDoors()
		applyPower()
	end)
	log("ready")
end

return PropertyController
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "TutorialController", "ModuleScript", [======[--!strict
-- The new-player coach (Research: Cinematic Cutscenes §9). Steps live in Config/Tutorial.lua, the order logic in
-- Rules/TutorialRules.lua. One card at a time, a pulsing ring around the REAL HUD/phone element it talks about
-- (found by name, so the HUD and phone redesigns keep working), and each step ends when the player does the thing.
-- Hidden during cutscenes and anything that hides the HUD. Progress is saved in Settings.Tutorial through the phone's
-- setSetting action (whitelisted in Config/Phone.SettingKeys), so a rejoin never repeats a finished step.
--   Tutorial.restart()   (Studio / Settings later: shows it again from step 1)
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local GuiService = game:GetService("GuiService")

local Net = require(ReplicatedStorage.MTL.Net)
local Theme = require(ReplicatedStorage.MTL.UI.Theme)
local Motion = require(ReplicatedStorage.MTL.UI.Motion)
local Story = require(ReplicatedStorage.MTL.Config.Story)
local Config = require(ReplicatedStorage.MTL.Config.Tutorial)
local TutorialRules = require(ReplicatedStorage.MTL.Rules.TutorialRules)
local Build = require(ReplicatedStorage.MTL.UI.Build.Tutorial)
local ClientData = require(script.Parent.ClientData)
local UIState = require(script.Parent.UIState)

local player = Players.LocalPlayer
local T = (Theme :: any).Tutorial
local Steps = Config.Steps

local Tutorial = {}

local function optional(name: string): any
	local m = script.Parent:FindFirstChild(name)
	if not m then
		return nil
	end
	local ok, mod = pcall(require, m)
	return if ok then mod else nil
end

local Sfx: any = nil
do
	local m = ReplicatedStorage.MTL.UI:FindFirstChild("Sfx")
	if m then
		local ok, mod = pcall(require, m)
		Sfx = if ok then mod else nil
	end
end
local function sound(name: string, volume: number?)
	if Sfx then
		pcall(Sfx.play, name, if volume then { volume = volume } else nil)
	end
end

local gui: any
local Phone: any, Menu: any, HUD: any, Cutscene: any
local localDone = 0 -- steps finished this session (the save catches up a moment later)
local shown: { index: number, step: any, at: number, phoneOpened: boolean, phoneOpenAt: number?, tasksAtStart: number }? = nil
local completing = false
local quietUntil = 0 -- no card before this (os.clock), e.g. right after a cutscene

local function device(): string
	local last = UserInputService:GetLastInputType()
	if last.Name:match("^Gamepad") then
		return "pad"
	elseif last == Enum.UserInputType.Touch then
		return "touch"
	elseif UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
		return "touch"
	elseif UserInputService.GamepadEnabled and not UserInputService.KeyboardEnabled then
		return "pad"
	end
	return "kb"
end

local function savedDone(): number
	local data = ClientData.get()
	local v = data and data.Settings and data.Settings.Tutorial
	return math.max(if type(v) == "number" then v else 0, localDone)
end

local function save(n: number)
	localDone = math.max(localDone, n)
	Net.get("PhoneAction"):FireServer({ type = "setSetting", key = "Tutorial", value = localDone })
end

local function tasksDone(): number
	local data = ClientData.get()
	local n = 0
	for _, c in (data and data.Job and data.Job.TasksDone) or {} do
		if type(c) == "number" then
			n += c
		end
	end
	return n
end

---------------------------------------------------------------- the ring around a HUD element

local onScreen: (GuiObject) -> boolean

-- "**Name": any descendant with that name; when there are several (e.g. a hidden grid copy and the dock icon),
-- the one actually on screen wins
local function deepFind(root: Instance, name: string): Instance?
	local first: Instance? = nil
	for _, d in root:GetDescendants() do
		if d.Name == name then
			if d:IsA("GuiObject") and onScreen(d) then
				return d
			end
			first = first or d
		end
	end
	return first
end

local function findTarget(id: string?): GuiObject?
	local paths = id and (Config.Targets :: any)[id]
	if not paths then
		return nil
	end
	local pg = player:FindFirstChild("PlayerGui")
	for _, path in paths do
		local node: Instance? = pg
		for _, name in path do
			if node and string.sub(name, 1, 2) == "**" then
				node = deepFind(node, string.sub(name, 3))
			else
				node = node and node:FindFirstChild(name)
			end
		end
		if node and node:IsA("GuiObject") then
			return node
		end
	end
	return nil
end

function onScreen(obj: GuiObject): boolean
	local node: Instance? = obj
	while node and node:IsA("GuiObject") do
		if not node.Visible then
			return false
		end
		node = node.Parent
	end
	local sg = obj:FindFirstAncestorOfClass("ScreenGui")
	return sg ~= nil and sg.Enabled and obj.AbsoluteSize.X > 2
end

local function placeRing(now: number)
	local ring, arrow = gui.Ring, gui.Arrow
	local id = shown and shown.step.target
	if shown and shown.step.whileOpenTarget and Phone and Phone.isOpen and Phone.isOpen() then
		id = shown.step.whileOpenTarget
	end
	local target = shown and gui.Card.Visible and findTarget(id)
	if not target or not onScreen(target) then
		ring.Visible = false
		arrow.Visible = false
		return
	end
	local sg = target:FindFirstAncestorOfClass("ScreenGui") :: ScreenGui
	local inset = if sg.IgnoreGuiInset then Vector2.zero else GuiService:GetGuiInset()
	local pad = 8
	local pos = target.AbsolutePosition + inset - Vector2.new(pad, pad)
	local size = target.AbsoluteSize + Vector2.new(pad * 2, pad * 2)
	ring.Position = UDim2.fromOffset(pos.X, pos.Y)
	ring.Size = UDim2.fromOffset(size.X, size.Y)
	local pulse = (math.sin(now * 4) + 1) / 2 -- under 1 pulse a second
	ring.Stroke.Transparency = 0.1 + pulse * 0.45
	ring.Stroke.Thickness = 2.5 + pulse * 1.5
	ring.Visible = true
	-- arrow: above the ring, or below it when the element sits at the top of the screen
	local cam = workspace.CurrentCamera
	local screenH = if cam then cam.ViewportSize.Y else 800
	local above = pos.Y > 70
	local bob = math.sin(now * 5) * 4
	arrow.Text = if above then "▼" else "▲"
	arrow.Position = UDim2.fromOffset(pos.X + size.X / 2, if above then pos.Y - 20 + bob else math.min(pos.Y + size.Y + 20 - bob, screenH - 20))
	arrow.Visible = true
end

---------------------------------------------------------------- the card

local function setDots(index: number)
	local dots = gui.Card.Bottom.Dots
	for _, d in dots:GetChildren() do
		if d:IsA("Frame") and d.Name ~= "DotTemplate" then
			d:Destroy()
		end
	end
	for i = 1, #Steps do
		local d = dots.DotTemplate:Clone()
		d.Name = "Dot" .. i
		d.LayoutOrder = i
		d.Visible = true
		d.BackgroundColor3 = if i <= index then T.Accent else T.Dim
		d.BackgroundTransparency = if i <= index then 0 else 0.5
		d.Size = if i == index then UDim2.fromOffset(18, 8) else UDim2.fromOffset(8, 8)
		d.Parent = dots
	end
end

local function setKeys(list: { string })
	local keys = gui.Card.Keys
	for _, k in keys:GetChildren() do
		if k:IsA("Frame") and k.Name ~= "KeyTemplate" then
			k:Destroy()
		end
	end
	for i, text in list do
		local k = keys.KeyTemplate:Clone()
		k.Name = "Key" .. i
		k.LayoutOrder = i
		k.Label.Text = text
		k.Visible = true
		k.Parent = keys
	end
	keys.Visible = #list > 0
end

local function fillCard()
	if not shown then
		return
	end
	local step, dev = shown.step, device()
	local card = gui.Card
	card.Step.Text = string.format("STEP %d OF %d", shown.index, #Steps)
	card.Title.Text = step.title
	local phoneOpen = Phone and Phone.isOpen and Phone.isOpen()
	local body = if step.done == "phone" and phoneOpen and step.whileOpen then step.whileOpen else step.body
	local text = TutorialRules.text(body, dev)
	if step.liveTask then
		-- say exactly what the job panel wants right now ("Now: Stock the empty shelf")
		local pg = player:FindFirstChild("PlayerGui")
		local panel = pg and pg:FindFirstChild("MTL_Job") and pg.MTL_Job:FindFirstChild("Panel")
		local label = panel and panel:FindFirstChild("Body") and panel.Body:FindFirstChild("Task")
		if label and label:IsA("TextLabel") and label.Text ~= "" then
			text = "Now: " .. label.Text .. ". " .. TutorialRules.text(step.liveTask, dev)
		end
	end
	card.Body.Text = text
	setKeys(if step.done == "phone" and phoneOpen then {} else TutorialRules.keys(step, dev))
	card.Bottom.Ok.Visible = step.ok ~= nil
	card.Bottom.Ok.Text = step.ok or "Got it"
	setDots(shown.index)
end

local function showCard(index: number, step: any)
	shown = { index = index, step = step, at = os.clock(), phoneOpened = false, phoneOpenAt = nil, tasksAtStart = tasksDone() }
	local card = gui.Card
	card.Tick.Visible = false
	fillCard()
	card.Visible = true
	card.Pop.Scale = 0.92
	Motion.tween(card.Pop, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 })
	sound("Open", 0.3)
end

local function hideCard()
	gui.Card.Visible = false
	gui.Ring.Visible = false
	gui.Arrow.Visible = false
end

local function complete()
	local s = shown
	if not s or completing then
		return
	end
	completing = true
	save(s.index)
	sound("Confirm", 0.4)
	local tick = gui.Card.Tick
	tick.Visible = true
	tick.Pop.Scale = 0.4
	Motion.tween(tick.Pop, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 })
	task.delay(Config.Tuning.BetweenSteps, function()
		shown = nil
		completing = false
		hideCard()
		quietUntil = os.clock() + 0.3
		if TutorialRules.finished(Steps, savedDone()) and savedDone() < Config.Skipped then
			if HUD and HUD.toast then
				pcall(HUD.toast, Config.Tuning.DoneToast, T.Accent)
			end
		end
	end)
end

local function stepDone(s: any): boolean
	local step = s.step
	local now = os.clock()
	if step.seconds and now - s.at >= step.seconds then
		return true
	end
	if step.done == "phone" then
		local open = Phone and Phone.isOpen and Phone.isOpen()
		if open and not s.phoneOpened then
			s.phoneOpened = true
			s.phoneOpenAt = now
			fillCard()
		end
		if s.phoneOpened and (not open or now - (s.phoneOpenAt :: number) >= Config.Tuning.PhoneReadSeconds) then
			return true
		end
	elseif step.done == "task" then
		return tasksDone() > s.tasksAtStart
	elseif step.done == "menu" then
		return Menu ~= nil and Menu.isOpen ~= nil and Menu.isOpen()
	end
	return false
end

---------------------------------------------------------------- main loop

local function blocked(): boolean
	if Cutscene and Cutscene.isPlaying and Cutscene.isPlaying() then
		quietUntil = math.max(quietUntil, os.clock() + Config.Tuning.FirstDelay)
		return true
	end
	-- the HUD's own popups (Store, Emotes) win: never cover them
	local pg = player:FindFirstChild("PlayerGui")
	local panels = pg and pg:FindFirstChild("MTL_HUD") and pg.MTL_HUD:FindFirstChild("Panels")
	if panels then
		for _, p in panels:GetChildren() do
			if p:IsA("GuiObject") and p.Visible then
				quietUntil = math.max(quietUntil, os.clock() + 0.4)
				return true
			end
		end
	end
	local st = UIState.get()
	if st.hideHUD then
		quietUntil = math.max(quietUntil, os.clock() + 0.6)
		return true
	end
	return os.clock() < quietUntil
end

local function tick()
	local data = ClientData.get()
	if not data then
		return
	end
	local stage = data.Story and data.Story.Stage
	local done = savedDone()
	-- cutscenes, fades and HUD popups always win (even over a step's tick)
	if blocked() then
		if gui.Card.Visible then
			hideCard()
		end
		return
	end
	if TutorialRules.finished(Steps, done) then
		if shown and not completing then
			shown = nil
			hideCard()
		end
		return
	end
	-- steps whose moment has passed (e.g. "Walk" once you're in the store) count as done
	local passed = TutorialRules.passed(Steps, done, stage, Story.Stages)
	if passed > done and not completing then
		if shown and shown.index <= passed then
			complete() -- the tick shows for a step the player just finished by moving the story on
			return
		end
		save(passed)
		done = passed
	end
	if completing then
		return
	end
	local index, step = TutorialRules.current(Steps, done, stage, Story.Stages)
	if not index then
		if shown then
			shown = nil
			hideCard()
		end
		return
	end
	if not shown or shown.index ~= index then
		showCard(index :: number, step)
	elseif not gui.Card.Visible then
		gui.Card.Visible = true -- back after a cutscene / menu hid it
		fillCard()
	elseif shown.step.liveTask then
		fillCard()
	end
	if shown and stepDone(shown) then
		complete()
	end
end

function Tutorial.restart()
	localDone = 0
	Net.get("PhoneAction"):FireServer({ type = "setSetting", key = "Tutorial", value = 0 })
	shown = nil
	hideCard()
end

function Tutorial.init()
	local pg = player:WaitForChild("PlayerGui")
	gui = pg:FindFirstChild("MTL_Tutorial")
	if not gui then
		gui = Build.build()
		gui.Parent = pg
	end
	gui.Card.Visible = false
	gui.Ring.Visible = false
	gui.Arrow.Visible = false
	Phone = optional("PhoneController")
	Menu = optional("MenuController")
	HUD = optional("HUDController")
	Cutscene = optional("CutsceneController")
	quietUntil = os.clock() + Config.Tuning.FirstDelay

	gui.Card.Bottom.Ok.Activated:Connect(function()
		if shown and shown.step.ok then
			complete()
		end
	end)
	gui.Card.Bottom.Skip.Activated:Connect(function()
		sound("Tap", 0.4)
		localDone = Config.Skipped
		Net.get("PhoneAction"):FireServer({ type = "setSetting", key = "Tutorial", value = Config.Skipped })
		shown = nil
		hideCard()
		if HUD and HUD.toast then
			pcall(HUD.toast, "Tutorial skipped. Your goal is always at the top.", T.Dim)
		end
	end)
	-- a cutscene hides the card at once (not on the next tick, or it shows through the fade-in)
	if Cutscene and Cutscene.Started then
		Cutscene.Started:Connect(function()
			quietUntil = math.max(quietUntil, os.clock() + Config.Tuning.FirstDelay)
			hideCard()
		end)
	end
	if Phone and Phone.Opened then
		Phone.Opened:Connect(fillCard)
		Phone.Closed:Connect(fillCard)
	end
	UserInputService.LastInputTypeChanged:Connect(function()
		if shown then
			fillCard()
		end
	end)

	local acc = 0
	RunService.RenderStepped:Connect(function(dt)
		placeRing(os.clock())
		acc += dt
		if acc >= 0.2 then
			acc = 0
			local ok, err = pcall(tick)
			if not ok then
				warn("[MTL Tutorial]", err)
			end
		end
	end)
	print("[MTL Tutorial] ready")
end

return Tutorial
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "UIState", "ModuleScript", [======[--!strict
-- Who owns the screen right now. Cutscenes, the open phone, minigames etc. push a state and pop it when done.
-- Flags merge with OR across everything pushed:
--   hideHUD, hidePhone, hideWaypoints, lockControls, lockCamera
--   UIState.push("Cutscene", { hideHUD = true, hidePhone = true, lockControls = true })
--   UIState.pop("Cutscene")
--   UIState.get().hideHUD ; UIState.Changed:Connect(function(state) end)
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Signal = require(ReplicatedStorage.MTL.Signal)

local UIState = {}
UIState.Changed = Signal.new()

local owners: { [string]: { [string]: boolean } } = {}
local merged: { [string]: boolean } = {}
local controls: any = nil

-- Movement lock. Uses the PlayerModule when the place has one; otherwise (newer Roblox builds don't put a
-- PlayerModule in PlayerScripts) sinks every movement input with ContextActionService. Never yields: a push or
-- pop must return at once, or a cutscene waiting on it would hang on a black screen.
local ContextActionService = game:GetService("ContextActionService")
local LOCK_ACTION = "MTL_LockControls"
local SINK_INPUTS = {
	Enum.PlayerActions.CharacterForward,
	Enum.PlayerActions.CharacterBackward,
	Enum.PlayerActions.CharacterLeft,
	Enum.PlayerActions.CharacterRight,
	Enum.PlayerActions.CharacterJump,
	Enum.KeyCode.W, Enum.KeyCode.A, Enum.KeyCode.S, Enum.KeyCode.D,
	Enum.KeyCode.Up, Enum.KeyCode.Down, Enum.KeyCode.Left, Enum.KeyCode.Right,
	Enum.KeyCode.Space, Enum.KeyCode.ButtonA, Enum.KeyCode.Thumbstick1,
}

local function getControls()
	if controls then
		return controls
	end
	local ps = Players.LocalPlayer:FindFirstChild("PlayerScripts")
	local pmScript = ps and ps:FindFirstChild("PlayerModule")
	if pmScript then
		local ok, result = pcall(function()
			return (require(pmScript :: any) :: any):GetControls()
		end)
		if ok then
			controls = result
		end
	end
	return controls
end

local function stopCharacter()
	local char = Players.LocalPlayer.Character
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	if hum then
		hum:Move(Vector3.zero)
	end
end

local function setLocked(locked: boolean)
	local c = getControls()
	if c then
		if locked then
			c:Disable()
		else
			c:Enable()
		end
	end
	if locked then
		ContextActionService:BindActionAtPriority(LOCK_ACTION, function()
			return Enum.ContextActionResult.Sink
		end, false, Enum.ContextActionPriority.High.Value + 100, table.unpack(SINK_INPUTS))
		stopCharacter()
	else
		ContextActionService:UnbindAction(LOCK_ACTION)
	end
end

local function recompute()
	local m: { [string]: boolean } = {}
	for _, flags in owners do
		for k, v in flags do
			if v then
				m[k] = true
			end
		end
	end
	local wasLocked = merged.lockControls == true
	merged = m
	if (m.lockControls == true) ~= wasLocked then
		local ok, err = pcall(setLocked, m.lockControls == true)
		if not ok then
			warn("[MTL UIState] control lock failed:", err)
		end
	end
	UIState.Changed:Fire(merged)
end

function UIState.push(owner: string, flags: { [string]: boolean })
	owners[owner] = flags
	recompute()
end

function UIState.pop(owner: string)
	if owners[owner] then
		owners[owner] = nil
		recompute()
	end
end

function UIState.get(): { [string]: boolean }
	return merged
end

function UIState.has(owner: string): boolean
	return owners[owner] ~= nil
end

function UIState.init()
	-- a respawn never leaves controls locked by a state whose owner died with the character
	Players.LocalPlayer.CharacterAdded:Connect(function()
		task.wait()
		if merged.lockControls then
			pcall(setLocked, true)
		end
	end)
end

return UIState
]======])
put("StarterPlayer/StarterPlayerScripts/MTL/Controllers", "WayfindingController", "ModuleScript", [======[--!strict
-- Waypoints the server sets (Waypoint remote). For each: a floating marker with the name and distance, and an arrow
-- on the screen edge when it's off screen. For the newest waypoint with breadcrumbs: a line of glowing chevrons on
-- the ground along a walkable path (PathfindingService), flowing toward the target. Arrival is decided by the server.
-- Research: "Onboarding Funnels and Wayfinding". Client API (local markers, e.g. job tasks):
--   Wayfinder.set(id, position, { label, radius, breadcrumbs })   Wayfinder.clear(id)
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local PathfindingService = game:GetService("PathfindingService")
local SoundService = game:GetService("SoundService")

local Net = require(ReplicatedStorage.MTL.Net)
local Theme = require(ReplicatedStorage.MTL.UI.Theme)
local Format = require(ReplicatedStorage.MTL.Format)
local Motion = require(ReplicatedStorage.MTL.UI.Motion)
local UIState = require(script.Parent.UIState)

local player = Players.LocalPlayer
local camera = workspace.CurrentCamera
local C = Theme.Colors

local Wayfinder = {}

-- tuning
local CHEVRON_SPACING = 5 -- studs between chevrons
local CHEVRON_COUNT = 18 -- so the trail shows ~90 studs ahead
local FLOW_SPEED = 7 -- studs/s the chevrons drift toward the target
local REPATH_EVERY = 1.5 -- seconds
local STRAY_REPATH = 12 -- studs off the line -> repath now
local SAMPLE_STEP = 2.5 -- studs between ground samples on the path
local MAX_PATH_DIST = 1200 -- beyond this, breadcrumbs point straight for the first stretch

type WP = {
	id: string,
	position: Vector3,
	label: string,
	radius: number,
	breadcrumbs: boolean,
	order: number,
	attachment: Attachment,
	billboard: BillboardGui,
}

local waypoints: { [string]: WP } = {}
local orderCounter = 0
local edgeGui: ScreenGui
local edgeArrow: Frame
local trailFolder: Folder
local chevrons: { Model } = {}
local trail: { Vector3 } = {} -- ground points from the player toward the target
local trailLength = 0
local lastPath = 0
local pathing = false
local hidden = false

local function new(className: string, props: { [string]: any }): any
	local inst = Instance.new(className)
	for k, v in props do
		if k ~= "Parent" then
			(inst :: any)[k] = v
		end
	end
	if props.Parent then
		inst.Parent = props.Parent
	end
	return inst
end

local function root(): BasePart?
	local char = player.Character
	return char and char:FindFirstChild("HumanoidRootPart") :: BasePart?
end

---------------------------------------------------------------- markers

local function makeMarker(wp: WP)
	local att = new("Attachment", { Name = "MTL_WP_" .. wp.id, WorldPosition = wp.position, Parent = workspace.Terrain })
	local bb = new("BillboardGui", {
		Name = "MTL_WP_" .. wp.id,
		Adornee = att,
		AlwaysOnTop = true,
		LightInfluence = 0,
		Size = UDim2.fromOffset(180, 64),
		StudsOffsetWorldSpace = Vector3.new(0, 5, 0),
		MaxDistance = 1e6,
		ResetOnSpawn = false,
		Parent = player:WaitForChild("PlayerGui"),
	})
	local icon = new("Frame", {
		Name = "Icon",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.fromScale(0.5, 0),
		Size = UDim2.fromOffset(18, 18),
		Rotation = 45,
		BackgroundColor3 = C.Gold,
		Parent = bb,
	})
	new("UIStroke", { Color = C.Shadow, Transparency = 0.4, Thickness = 2, Parent = icon })
	new("TextLabel", {
		Name = "Label",
		Position = UDim2.fromOffset(0, 24),
		Size = UDim2.new(1, 0, 0, 20),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Bold,
		Text = wp.label,
		TextColor3 = C.Text,
		TextSize = 15,
		Parent = bb,
	})
	new("TextLabel", {
		Name = "Distance",
		Position = UDim2.fromOffset(0, 43),
		Size = UDim2.new(1, 0, 0, 16),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Body,
		Text = "",
		TextColor3 = C.Gold,
		TextSize = 13,
		Parent = bb,
	})
	for _, l in bb:GetChildren() do
		if l:IsA("TextLabel") then
			new("UIStroke", { Color = C.Shadow, Transparency = 0.45, Thickness = 1.5, Parent = l })
		end
	end
	wp.attachment = att
	wp.billboard = bb
end

local function primary(): WP?
	local best: WP? = nil
	for _, wp in waypoints do
		if wp.breadcrumbs and (not best or wp.order > best.order) then
			best = wp
		end
	end
	return best
end

---------------------------------------------------------------- breadcrumbs

local function makeChevron(): Model
	local m = Instance.new("Model")
	m.Name = "Chevron"
	for i, side in { -1, 1 } do
		local p = new("Part", {
			Name = if i == 1 then "L" else "R",
			Anchored = true,
			CanCollide = false,
			CanQuery = false,
			CanTouch = false,
			CastShadow = false,
			Material = Enum.Material.Neon,
			Color = C.Gold,
			Size = Vector3.new(0.35, 0.08, 1.6),
			Transparency = 1,
			Parent = m,
		})
		p:SetAttribute("Side", side)
	end
	m.Parent = trailFolder
	return m
end

local groundParams = RaycastParams.new()
groundParams.FilterType = Enum.RaycastFilterType.Exclude
groundParams.IgnoreWater = false

local function ground(p: Vector3): Vector3
	groundParams.FilterDescendantsInstances = { player.Character :: any, trailFolder }
	local hit = workspace:Raycast(p + Vector3.new(0, 6, 0), Vector3.new(0, -30, 0), groundParams)
	return if hit then hit.Position + Vector3.new(0, 0.12, 0) else p
end

-- Turns a list of path points into evenly spaced ground samples (first ~110 studs only).
local function resample(points: { Vector3 }): ({ Vector3 }, number)
	local out = { ground(points[1]) }
	local total = 0
	local carry = 0
	for i = 1, #points - 1 do
		local a, b = points[i], points[i + 1]
		local seg = (b - a).Magnitude
		local d = SAMPLE_STEP - carry
		while d <= seg do
			table.insert(out, ground(a:Lerp(b, d / seg)))
			total += SAMPLE_STEP
			if total > CHEVRON_SPACING * CHEVRON_COUNT + 60 then
				return out, total
			end
			d += SAMPLE_STEP
		end
		carry = seg - (d - SAMPLE_STEP)
	end
	table.insert(out, ground(points[#points]))
	return out, total + carry
end

local function straightPoints(from: Vector3, to: Vector3): { Vector3 }
	local dir = (to - from)
	local len = math.min(dir.Magnitude, CHEVRON_SPACING * CHEVRON_COUNT + 60)
	return { from, from + dir.Unit * len }
end

local function repath(target: Vector3)
	if pathing then
		return
	end
	local r = root()
	if not r then
		return
	end
	pathing = true
	lastPath = os.clock()
	local from = r.Position
	task.spawn(function()
		local points: { Vector3 }
		if (target - from).Magnitude > MAX_PATH_DIST then
			points = straightPoints(from, target)
		else
			local path = PathfindingService:CreatePath({ AgentRadius = 2, AgentHeight = 5, AgentCanJump = true, WaypointSpacing = 4 })
			local ok = pcall(function()
				path:ComputeAsync(from, target)
			end)
			if ok and path.Status == Enum.PathStatus.Success then
				points = {}
				for _, w in path:GetWaypoints() do
					table.insert(points, w.Position)
				end
			else
				points = straightPoints(from, target)
			end
		end
		if #points >= 2 then
			trail, trailLength = resample(points)
		end
		pathing = false
	end)
end

-- point at distance d along the trail, and the direction there
local function along(d: number): (Vector3?, Vector3?)
	if #trail < 2 then
		return nil, nil
	end
	local i = math.floor(d / SAMPLE_STEP) + 1
	if i >= #trail then
		return nil, nil
	end
	local a, b = trail[i], trail[i + 1]
	local f = (d - (i - 1) * SAMPLE_STEP) / SAMPLE_STEP
	return a:Lerp(b, f), (b - a)
end

-- nearest trail sample to the player (only the first stretch, the player can't be further along than that)
-- returns its distance along the trail and how far off the trail the player is
local function nearestOnTrail(p: Vector3): (number, number)
	local best, bestI = math.huge, 1
	for i = 1, math.min(#trail, 24) do
		local d = (Vector2.new(trail[i].X, trail[i].Z) - Vector2.new(p.X, p.Z)).Magnitude
		if d < best then
			best, bestI = d, i
		end
	end
	return (bestI - 1) * SAMPLE_STEP, best
end

local function hideTrail()
	for _, m in chevrons do
		for _, p in m:GetChildren() do
			(p :: BasePart).Transparency = 1
		end
	end
end

local function updateTrail(wp: WP?)
	local r = root()
	if not wp or not r or hidden then
		hideTrail()
		return
	end
	local flat = Vector2.new(r.Position.X - wp.position.X, r.Position.Z - wp.position.Z).Magnitude
	if flat <= wp.radius + 6 then
		hideTrail()
		return
	end
	local base, off = 0, 0
	if #trail > 0 then
		base, off = nearestOnTrail(r.Position)
	end
	if os.clock() - lastPath > REPATH_EVERY or off > STRAY_REPATH then
		repath(wp.position)
	end
	local phase = (os.clock() * FLOW_SPEED) % CHEVRON_SPACING
	for i, m in chevrons do
		local rel = (i - 1) * CHEVRON_SPACING + phase + 3 -- distance ahead of the player
		local d = base + rel
		local pos, dir = along(d)
		if pos and dir and dir.Magnitude > 0.01 and d < trailLength then
			-- distance from the player along the trail: fade in near the player, fade out at the far end
			local nearFade = math.clamp((rel - 3) / 6, 0, 1)
			local farFade = math.clamp((CHEVRON_SPACING * CHEVRON_COUNT - rel) / 20, 0, 1)
			local t = 1 - 0.75 * nearFade * farFade
			local look = CFrame.lookAt(pos, pos + Vector3.new(dir.X, 0, dir.Z))
			for _, p in m:GetChildren() do
				local part = p :: BasePart
				local side = part:GetAttribute("Side") :: number
				part.CFrame = look * CFrame.new(side * 0.55, 0, 0.35) * CFrame.Angles(0, -side * math.rad(35), 0)
				part.Transparency = t
			end
		else
			for _, p in m:GetChildren() do
				(p :: BasePart).Transparency = 1
			end
		end
	end
end

---------------------------------------------------------------- edge arrow + distances

local function updateMarkers(top: WP?)
	local r = root()
	for _, wp in waypoints do
		wp.billboard.Enabled = not hidden
		if r then
			wp.billboard.Distance.Text = Format.distance((r.Position - wp.position).Magnitude)
		end
	end
	if hidden or not top or not r then
		edgeArrow.Visible = false
		return
	end
	local screen, onScreen = camera:WorldToViewportPoint(top.position + Vector3.new(0, 5, 0))
	local vp = camera.ViewportSize
	local margin = 48
	if onScreen and screen.X > margin and screen.X < vp.X - margin and screen.Y > margin and screen.Y < vp.Y - margin then
		edgeArrow.Visible = false
		return
	end
	-- direction from screen centre toward the target (flip when behind the camera)
	local center = vp / 2
	local dir = Vector2.new(screen.X, screen.Y) - center
	if screen.Z < 0 then
		dir = -dir
	end
	if dir.Magnitude < 1 then
		dir = Vector2.new(0, -1)
	end
	dir = dir.Unit
	local sx = (vp.X / 2 - margin) / math.max(math.abs(dir.X), 1e-4)
	local sy = (vp.Y / 2 - margin) / math.max(math.abs(dir.Y), 1e-4)
	local p = center + dir * math.min(sx, sy)
	edgeArrow.Position = UDim2.fromOffset(math.floor(p.X), math.floor(p.Y))
	edgeArrow.Arrow.Rotation = math.deg(math.atan2(dir.Y, dir.X)) + 90
	edgeArrow.Distance.Text = Format.distance((r.Position - top.position).Magnitude)
	edgeArrow.Visible = true
end

local function buildEdge()
	edgeGui = new("ScreenGui", {
		Name = "MTL_Waypoints",
		ResetOnSpawn = false,
		IgnoreGuiInset = true,
		DisplayOrder = 4,
		Parent = player:WaitForChild("PlayerGui"),
	})
	edgeArrow = new("Frame", {
		Name = "Edge",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Size = UDim2.fromOffset(60, 60),
		BackgroundTransparency = 1,
		Visible = false,
		Parent = edgeGui,
	})
	local arrow = new("TextLabel", {
		Name = "Arrow",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.4),
		Size = UDim2.fromOffset(30, 30),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Display,
		Text = "▲", -- TODO(Alex art): arrow image
		TextColor3 = C.Gold,
		TextSize = 28,
		Parent = edgeArrow,
	})
	new("UIStroke", { Color = C.Shadow, Transparency = 0.4, Thickness = 2, Parent = arrow })
	local dist = new("TextLabel", {
		Name = "Distance",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.fromScale(0.5, 0.72),
		Size = UDim2.fromOffset(80, 16),
		BackgroundTransparency = 1,
		FontFace = Theme.Fonts.Bold,
		Text = "",
		TextColor3 = C.Text,
		TextSize = 13,
		Parent = edgeArrow,
	})
	new("UIStroke", { Color = C.Shadow, Transparency = 0.45, Thickness = 1.5, Parent = dist })
end

---------------------------------------------------------------- API

function Wayfinder.set(id: string, position: Vector3, opts: { [string]: any }?)
	local o = opts or {}
	Wayfinder.clear(id, true)
	orderCounter += 1
	local wp = {
		id = id,
		position = position,
		label = o.label or "",
		radius = o.radius or 12,
		breadcrumbs = if o.breadcrumbs == nil then true else o.breadcrumbs,
		order = orderCounter,
	} :: any
	makeMarker(wp)
	waypoints[id] = wp
	trail = {}
	lastPath = 0
	-- small pop so the eye catches a new marker
	local icon = wp.billboard.Icon
	icon.Size = UDim2.fromOffset(4, 4)
	Motion.tween(icon, Motion.Spring, { Size = UDim2.fromOffset(18, 18) })
end

function Wayfinder.clear(id: string, silent: boolean?)
	local wp = waypoints[id]
	if not wp then
		return
	end
	waypoints[id] = nil
	wp.attachment:Destroy()
	wp.billboard:Destroy()
	trail = {}
	if not silent then
		hideTrail()
	end
end

function Wayfinder.init()
	trailFolder = new("Folder", { Name = "MTL_Breadcrumbs", Parent = workspace })
	for _ = 1, CHEVRON_COUNT do
		table.insert(chevrons, makeChevron())
	end
	buildEdge()

	UIState.Changed:Connect(function(state)
		hidden = state.hideWaypoints == true or state.hideHUD == true
	end)

	Net.get("Waypoint").OnClientEvent:Connect(function(msg)
		if type(msg) ~= "table" or type(msg.id) ~= "string" then
			return
		end
		if msg.clear then
			Wayfinder.clear(msg.id)
			if msg.arrived and Theme.Sounds.Arrive ~= "" then
				local s = Instance.new("Sound")
				s.SoundId = Theme.Sounds.Arrive
				s.Volume = 0.4
				SoundService:PlayLocalSound(s)
				task.delay(2, function()
					s:Destroy()
				end)
			end
		elseif typeof(msg.position) == "Vector3" then
			Wayfinder.set(msg.id, msg.position, msg)
		end
	end)

	RunService.RenderStepped:Connect(function()
		local top = primary()
		updateTrail(top)
		updateMarkers(top)
	end)
end

return Wayfinder
]======])
-- save every UI/Build/<Name> screen (MTL_HUD, MTL_Phone, ...) into StarterGui as real instances (Alex reskins them)
do
 -- require from a throwaway copy so a re-run never gets an old cached module
 local tmp = game.ReplicatedStorage.MTL:Clone()
 tmp.Name = "MTL_InstallTmp"
 tmp.Parent = game.ServerStorage
 for _, m in tmp.UI.Build:GetChildren() do
  if m:IsA("ModuleScript") then
   local ok, err = pcall(function()
    local build = require(m)
    local gui = build.build()
    local old = game.StarterGui:FindFirstChild(gui.Name)
    if old then old:Destroy() end
    gui.Parent = game.StarterGui
   end)
   print("[MTL Install] " .. m.Name .. " into StarterGui:", ok, err or "")
  end
 end
 tmp:Destroy()
end
print("[MTL Install] wrote 104 scripts")
